  ui_story_1_1_60_dialog_content = "<anim type=Shake><size=50>吼——！！</size></anim>",
  ui_story_1_1_61_dialog_content = "光能……我需要光能……",
  ui_story_1_1_62_dialog_content = "往左邊移動兩步。",
  ui_story_1_1_63_dialog_content = "<size=45>誰？！</size>",
