  ui_story_1_1_66_dialog_content = "啊！真的有人！這個感覺，是某種通訊？不對……",
  ui_story_1_1_67_dialog_content = "這是<color=#FFB400>精神感應</color>。",
  ui_story_1_1_68_dialog_content = "精神……感應？",
  ui_story_1_1_B25_dialog_content = "第一次和真人說話，還真是不太習慣……",
  ui_story_1_1_A26_dialog_content = "加油！你可以的！雖然是第一次，但畢竟練習了這麼多年……",
  ui_story_1_1_A27_dialog_content = "為什麼突然鼓勵起我？！你到底是誰？！",
  ui_story_1_1_A28_dialog_content = "我是在對我自己說！總之——",
  ui_story_1_1_69_option_content = "強制感應！",
  ui_story_1_1_70_dialog_content = "<size=45>咿呀——！！</size>",
  ui_story_1_1_75_dialog_content = "我竟然一個人打敗了這些暗鬼！",
  ui_story_1_1_76_dialog_content = "因為看到光之軌跡，我的力量大幅提升",
  ui_story_1_1_77_dialog_content = "難道我的光感視覺覺醒了嗎？我掌握了所有光靈都不可能學會的能力？",
  ui_story_1_1_78_dialog_content = "……命運……是命運！不，難道我有什麼特殊的血脈？！",
  ui_story_1_1_79_dialog_content = "家族悲劇、宿命中的挑戰接踵而來？！要是因為成為異族而飽受非議該怎麼辦？？",
  ui_story_1_1_80_dialog_content = "嚴格來說……那是我的能力。",
  ui_story_1_1_81_dialog_content = "哇！你怎麼還在？你是這裡的幽靈嗎？！",
  ui_story_1_1_82_dialog_content = "沒有幽靈這種設定。這是我的感應能力，剛剛妳看到的光之軌跡也是。",
  ui_story_1_1_83_dialog_content = "什麼？欸……我沒有覺醒超能力之類的嗎？",
  ui_story_1_1_84_dialog_content = "抱歉，讓妳失望了……",
  ui_story_1_1_B26_dialog_content = "……",
  ui_story_1_1_B27_dialog_content = "啊……我是不是嚇到你了？",
  ui_story_1_1_B28_dialog_content = "不過，剛剛你突然闖進來，也嚇到我了。",
  ui_story_1_1_B29_dialog_content = "我完全沒辦法理解現在發生了什麼事。",
  ui_story_1_1_B30_dialog_content = "我們還是當面說吧，你們光靈也許不習慣這種溝通方式。",
  ui_story_1_1_85_dialog_content = "總之，先沿著通道前進，我在最後一個房間等妳。",
  ui_story_1_1_86_dialog_content = "哇……",
  ui_story_1_1_A34_dialog_content = "咦……",
  ui_story_1_1_87_dialog_content = "怎麼了，我臉上有東西嗎？明明剛才還特地洗了把臉……",
  ui_story_1_1_88_dialog_content = "沒事，只是沒想到真的是個活人，不是幽靈嗎……",
  ui_story_1_1_89_dialog_content = "<size=40>就說了這個世界沒有幽靈！</size>",
  ui_story_1_1_B31_dialog_content = "那你剛才又在「哇」什麼？",
  ui_story_1_1_B32_dialog_content = "……我也沒想到會遇到活人。",
  ui_story_1_1_90_dialog_content = "你不也是嗎……所以你到底是什麼人？這裡……是巨像嗎？",
  ui_story_1_1_91_dialog_content = "這裡是巨像，而我是這裡的主人，也是剛才與妳精神感應的人。",
  ui_story_1_1_92_dialog_content = "那種能力我只在歷史課本上讀過，可是……",
  ui_story_1_1_93_dialog_content = "可是……？",
  ui_story_1_1_94_dialog_content = "等等，難道你是——\n「<color=#FFB400>空裔</color>」？",
  ui_story_1_1_95_dialog_content = "為什麼那麼驚訝？沒錯，我是「空裔」。",
  ui_story_1_1_96_dialog_content = "……這裡只有你一個人嗎？",
  ui_story_1_1_97_dialog_content = "對，我一直在這裡獨自生活。當年，我的家鄉被暗鬼突襲……",
  ui_story_1_1_A29_dialog_content = "嗯，那件事我有所耳聞……",
  ui_story_1_1_B33_dialog_content = "那、我可以問妳一個問題嗎？",
  ui_story_1_1_B34_dialog_content = "太、太近了，這位空裔……",
  ui_story_1_1_B35_dialog_content = "啊，抱歉。我只是想問——",
  ui_story_1_1_B36_option_content = "妳見過其他空裔嗎？",
  ui_story_1_1_B37_option_content = "十七年前到底發生了什麼事？",
  ui_story_1_1_B38_option_content = "光靈和暗鬼是什麼？",
  ui_story_1_1_B39_dialog_content = "我從有記憶起就一直在這，通訊系統也損壞了，我無法——",
  ui_story_1_1_B40_dialog_content = "別激動，我確實沒見過其他空裔。但也許他們只是在我沒去過的地方呢？",
  ui_story_1_1_B41_dialog_content = "……那他們為什麼不來找我？",
  ui_story_1_1_B42_dialog_content = "……",
  ui_story_1_1_B43_dialog_content = "當年……空之山谷發生的事，我只在檔案上讀過，偶爾也會做奇怪的<color=#FFB400>夢</color>……",
  ui_story_1_1_B44_dialog_content = "夢？",
  ui_story_1_1_B45_dialog_content = "關於那場災難……你能告訴我更多細節嗎？",
  ui_story_1_1_B46_dialog_content = "那場災難發生的時候，我才剛出生，不太清楚什麼細節。",
  ui_story_1_1_B47_dialog_content = "但似乎是「暗鬼們突然發動<color=#FFB400>有組織的襲擊</color>」，在一夜之間掃蕩空裔居住的空之山谷。",
  ui_story_1_1_B48_dialog_content = "……嗯，這些我知道。",
  ui_story_1_1_B49_dialog_content = "那看來我知道得沒比你多。抱歉……",
  ui_story_1_1_B50_dialog_content = "所以，妳是「<color=#FFB400>光靈</color>」？",
  ui_story_1_1_B51_dialog_content = "對，聽說我們還曾經和空裔一起對抗過暗鬼呢。",
  ui_story_1_1_B52_dialog_content = "剛才那些怪物，就是暗鬼吧？",
  ui_story_1_1_B53_dialog_content = "沒錯。這些「生物」肆虐整個大陸，沒人知道牠們是從哪裡冒出來的。",
  ui_story_1_1_B54_dialog_content = "有人說牠們來自大陸的另一側，也有人說牠們的出現是神罰……",
  ui_story_1_1_B55_dialog_content = "總之，從有歷史記載開始，這些怪物就是我們共同的敵人了。",
  ui_story_1_1_B56_dialog_content = "嗯……這些我也都在資料裡讀過了。",
  ui_story_1_1_B57_dialog_content = "那你還問什麼……",
  ui_story_1_1_B58_option_content = "我還有個問題",
  ui_story_1_1_B59_option_content = "（沉默）",
  ui_story_1_1_B60_dialog_content = "我還有個問題——",
  ui_story_1_1_98_dialog_content = "對了，你一直都在這裡，沒想過要離開嗎？",
  ui_story_1_1_99_dialog_content = "這個嘛……我們是沒有戰鬥技能的，不像你們可以用<color=#FFB400>光能術</color>作戰。",
  ui_story_1_1_100_dialog_content = "可以看到光的軌跡，卻無法使用它來戰鬥。是不是很諷刺？",
  ui_story_1_1_101_dialog_content = "不……光靈們可以使用光來戰鬥，卻看不到光，這才諷刺……",
  ui_story_1_1_103_dialog_content = "總之，這些年來我從來沒有離開過地下，是依靠臨空者號的維生系統才活到今天。",
  ui_story_1_1_104_dialog_content = "「<color=#FFB400>臨空者號</color>」？這座巨像嗎？真了不起啊！原來他是有名字的……",
  ui_story_1_1_105_dialog_content = "當然。作為魔法、科技和生命的結合體，巨像也有自己的思想。",
  ui_story_1_1_106_dialog_content = "所以你可以和他溝通，對吧？畢竟是擁有感應能力的空裔。",
  ui_story_1_1_107_dialog_content = "當然，這可是我們空裔的天賦。",
  ui_story_1_1_109_dialog_content = "你怎麼了？剛才受傷了嗎？",
  ui_story_1_1_110_dialog_content = "……",
  ui_story_1_1_111_dialog_content = "啊，沒有，只是想起一些原來的事情。",
  ui_story_1_1_112_dialog_content = "對了！這麼說的話，他現在還能啟動嗎？我們搞不好可以——",
  ui_story_1_1_113_dialog_content = "抱歉。雖然他曾是屈指可數的天空級巨像，但現在的我……無法啟動他。",
  ui_story_1_1_114_dialog_content = "不過薇絲，妳對巨像好像很瞭解嘛？",
  ui_story_1_1_115_dialog_content = "略懂而已啦！我看過有關巨像的書籍，這次的任務也是為尋找可能還存在的巨……",
  ui_story_1_1_A31_dialog_content = "欸，你剛才叫我什麼？我好像沒告訴過你我的名字……",
  ui_story_1_1_A32_dialog_content = "感應能力，薇絲。我剛才有聽到妳和隊友在外面的對話。",
  ui_story_1_1_A33_dialog_content = "啊——哈哈，抱歉，真不愧是空裔呢。",
  ui_story_1_1_116_dialog_content = "雖然不能啟動臨空者號很可惜，但看來我找到更加珍貴的寶貝呢！",
  ui_story_1_1_117_dialog_content = "……妳該不會是在說我吧？",
  ui_story_1_1_118_dialog_content = "還需要請你幫一個忙……對了，還沒有問你的名字呢，你是？",
  ui_story_1_1_119_dialog_content = "PlayerName。",
  ui_story_1_1_120_dialog_content = "PlayerName？果然有一種奇特的異域色彩呢！",
  ui_story_1_1_121_dialog_content = "是這樣的，我從上面掉下來時和隊友們失散了。你可以幫我找到她們嗎？",
  ui_story_1_1_122_dialog_content = "我暫時沒有感應到。臨空者，你有辦法嗎？",
  ui_story_1_1_123_dialog_content = "訊號發射台那邊有兩個光靈，而且還有不少暗鬼正在朝那裡前進。",
  ui_story_1_1_124_dialog_content = "換句話說，我們這個地方恐怕也不安全了。",
  ui_story_1_1_125_dialog_content = "她們在訊號發射台附近，似乎遇到麻煩了。",
  ui_story_1_1_126_dialog_content = "那我必須去支援她們！",
  ui_story_1_1_127_dialog_content = "我需要你的幫助！你可以看到光的分布，可以指揮我們作戰！",
  ui_story_1_1_128_dialog_content = "就像剛才那樣，我的戰鬥力一下提高了好幾倍！",
  ui_story_1_1_129_option_content = "可是我不擅長戰鬥……",
  ui_story_1_1_130_option_content = "那就一起行動吧！",
  ui_story_1_1_131_dialog_content = "放心啦，我會保護你的！",
  ui_story_1_1_132_dialog_content = "她說得對。暗鬼已經侵入，和她一起行動反而更安全。",
  ui_story_1_1_133_dialog_content = "好。我可以答應妳，薇絲，但我也想請妳幫個忙。",
  ui_story_1_1_134_dialog_content = "好！不用擔心，我會保護你的！",
  ui_story_1_1_135_dialog_content = "不錯，很有氣魄的光靈，妳叫薇絲吧？",
  ui_story_1_1_X6_dialog_content = "PlayerName，你也做出很了不起的決定呢！",
  ui_story_1_1_136_dialog_content = "但我有一個要求，希望妳也能幫幫我。",
  ui_story_1_1_B61_dialog_content = "沒問題！不論是什麼忙，只要是我能做到的，妳儘管說！",
  ui_story_1_1_137_dialog_content = "我想請妳帶我離開這裡。",
  ui_story_1_1_138_dialog_content = "離開……當然。你真的準備好了嗎？",
  ui_story_1_1_139_dialog_content = "我……也不知道。",
  ui_story_1_1_140_dialog_content = "但我必須離開！",
  ui_story_1_2_1_dialog_content = "安潔兒，我不行了……",
  ui_story_1_2_2_dialog_content = "這些暗鬼怎麼都殺不完？我已經沒剩多少力量了……",
  ui_story_1_2_3_dialog_content = "這地方不見天日，光能少得可憐。暗鬼沒了光的壓制，比在地表時更猖狂！",
  ui_story_1_2_4_dialog_content = "怎麼才能回到上面……薇絲到底在哪裡……",
  ui_story_1_2_6_dialog_content = "咕——！我不想死在這裡啊……",
  ui_story_1_2_7_dialog_content = "多孚！是我！",
  ui_story_1_2_8_dialog_content = "好險，還好這傢伙沒多少光能了，要不然傷到薇絲怎麼辦。",
  ui_story_1_2_9_dialog_content = "薇、薇絲？妳沒事吧……",
  ui_story_1_2_10_dialog_content = "我很好！多虧PlayerName的幫助，我才能順利找到妳們！",
  ui_story_1_2_11_dialog_content = "PlayerName？誰？我沒看到別人啊？",
  ui_story_1_2_12_dialog_content = "他不在這裡，但會告訴我們怎麼做！你們只要配合就行了！",
  ui_story_1_2_13_dialog_content = "配合？要怎麼配合，我們……",
  ui_story_1_2_14_option_content = "強制感應！",
  ui_story_1_2_15_dialog_content = "我剛剛是不是​​做了個夢……夢到自己在光裡穿梭……",
  ui_story_1_2_16_dialog_content = "這是怎麼回事，薇絲……還有那個傢伙，怎麼一直躲在門後？",
  ui_story_1_2_17_dialog_content = "抱歉……因為我不能戰鬥。",
  ui_story_1_2_18_dialog_content = "光感視覺和感應能力，所以你是……",
  ui_story_1_2_19_dialog_content = "薇絲，我從沒聽說妳有這樣的朋友。",
  ui_story_1_2_20_option_content = "其實我們剛認識……",
  ui_story_1_2_21_option_content = "「朋友」……？",
  ui_story_1_2_22_dialog_content = "嗯，我們掉下來之後，是PlayerName救了我。",
  ui_story_1_2_23_dialog_content = "而他是這座巨像的主人，是位空裔喔。",
  ui_story_1_2_24_dialog_content = "我的……「朋友」？",
  ui_story_1_2_25_dialog_content = "PlayerName……你怎麼了？",
  ui_story_1_2_26_dialog_content = "啊，沒事……",
  ui_story_1_2_28_dialog_content = "我掉下來後也遇到暗鬼，是PlayerName救了我。",
  ui_story_1_2_29_dialog_content = "這位是安潔兒，這傢伙是多孚。她們都是我的小隊隊員。",
  ui_story_1_2_30_dialog_content = "我是PlayerName，這座巨像的主人，我是一名空裔。",
  ui_story_1_2_31_dialog_content = "感謝你出手相救，PlayerName。恐怕我還有很多問題要問你……",
  ui_story_1_2_32_dialog_content = "什麼空什麼裔？完全聽不懂你們在說什麼……",
  ui_story_1_2_33_dialog_content = "總之，謝謝你，PlayerName。以後我們就是朋友了！",
  ui_story_1_2_34_dialog_content = "沒想到，有一天我也會交到「朋友」……",
  ui_story_1_3_1_dialog_content = "薇絲，接下來怎麼辦，暗鬼的數量太多了——我們需要支援。",
  ui_story_1_3_2_dialog_content = "帶來的通訊器在戰鬥時已經毀掉了。<color=#FFB400>導航員</color>，臨空者號有聯絡方法嗎？",
  ui_story_1_3_3_dialog_content = "被毀了。",
  ui_story_1_3_X1_dialog_content = "那你應該有武器吧……",
  ui_story_1_3_X2_dialog_content = "什麼武器都沒有……",
  ui_story_1_3_4_dialog_content = "這裡是巨像吧，那我們為什麼不啟動他？",
  ui_story_1_3_X3_dialog_content = "<color=#e8d9bb>啟動失敗。累積失敗次數：3921次。</color>",
  ui_story_1_3_X4_dialog_content = "啟動不了……",
  ui_story_1_3_X5_dialog_content = "怎麼會……？",
  ui_story_1_3_X6_dialog_content = "不行。這麼多年來，我試過無數次……但不知道為什麼總是啟動失敗。",
  ui_story_1_3_X7_dialog_content = "真是抱歉，但巨像狀況真的很差……",
  ui_story_1_3_X8_dialog_content = "勉強維持我的生存就已竭盡全力了，他也很辛苦的。",
  ui_story_1_3_X9_dialog_content = "謝謝你的誇獎，PlayerName。",
  ui_story_1_3_X10_dialog_content = "……",
  ui_story_1_3_6_dialog_content = "等一下，導航員。",
  ui_story_1_3_X11_dialog_content = "就算無法啟動，也沒有武器，但你之前提到……",
  ui_story_1_3_7_dialog_content = "訊號發射台，對吧？",
  ui_story_1_3_8_dialog_content = "我記得每座巨像都有訊號發射台，可以用它發射求救訊號。",
  ui_story_1_3_A1_dialog_content = "如果有人看到求救訊號，一定會過來援救我們！",
  ui_story_1_3_9_dialog_content = "應該就在這附近吧？剛才你說過，多孚與安潔兒在訊號發射台那邊！",
  ui_story_1_3_10_dialog_content = "……妳對巨像這麼瞭解嗎？",
  ui_story_1_3_X12_dialog_content = "哈哈，略懂而已啦。平時大家總說這些知識百無一用……",
  ui_story_1_3_X13_dialog_content = "發射臺確實就在這附近，而且完好無損。",
  ui_story_1_3_X14_dialog_content = "但是，妳們也許猜到我要說什麼了……",
  ui_story_1_3_11_dialog_content = "我沒有發射標記物的原材料——",
  ui_story_1_3_12_dialog_content = "<color=#FFB400>光珀</color>。",
  ui_story_1_3_13_dialog_content = "妳怎麼知道……啊，「略懂」，對吧。",
  ui_story_1_3_14_dialog_content = "如果是光珀的話，我們剛好有帶哦。",
  ui_story_1_3_15_dialog_content = "咳咳，薇絲，那個……",
  ui_story_1_3_16_dialog_content = "怎麼了？我看到妳有帶啊，就在妳的包包裡面吧？",
  ui_story_1_3_18_dialog_content = "那個可貴了……",
  ui_story_1_3_19_dialog_content = "生死攸關的時候說什麼呢！現在是吝嗇的時候嗎，多孚！",
  ui_story_1_3_B1_dialog_content = "可以報帳嗎？",
  ui_story_1_3_B2_dialog_content = "當然啦！回去我再准妳10天假，好嗎？",
  ui_story_1_3_B3_dialog_content = "咕咕咕！一言為定。",
  ui_story_1_3_B4_dialog_content = "那就讓我們趕快去訊號發射台吧！",
  ui_story_1_3_A2_dialog_content = "路上說不定會遇到暗鬼，大家務必小心！",
  ui_story_1_3_24_dialog_content = "到了！這地方還蠻難找的。真不愧是導航員！",
  ui_story_1_3_25_dialog_content = "畢竟已經在這裡繭居十七年了……",
  ui_story_1_3_26_dialog_content = "還好我們來得及時，剛剛暗鬼差點攻進來了……",
  ui_story_1_3_27_dialog_content = "還好設備沒有被破壞。",
  ui_story_1_3_28_dialog_content = "所以，那個就是控制台嗎？",
  ui_story_1_3_29_dialog_content = "啊啊，第一次看到實物呢。要實際操作的話……",
  ui_story_1_3_30_dialog_content = "把光珀放進發射器，再<color=#FFB400>拉動拉桿</color>就行了。",
  ui_story_1_3_31_dialog_content = "可惜我沒有材料，一直沒辦法使用……",
  ui_story_1_3_33_dialog_content = "但你今天有值得信賴的夥伴了！多孚～",
  ui_story_1_3_34_dialog_content = "薇絲，妳會善待這些材料的吧？",
  ui_story_1_3_35_dialog_content = "當然。",
  ui_story_1_3_36_dialog_content = "……",
  ui_story_1_3_B5_dialog_content = "……多孚，妳……可以放手了……",
  ui_story_1_3_B6_dialog_content = "咕咕……我可以反悔嗎……",
  ui_story_1_3_B7_dialog_content = "食言的人要吞一千根暗鬼手指哦。",
  ui_story_1_3_B8_dialog_content = "咕——！",
  ui_story_1_4_1_dialog_content = "喔喔喔！發射成功啦！好耀眼～",
  ui_story_1_4_2_dialog_content = "成功了……薇絲，謝謝妳！",
  ui_story_1_4_3_dialog_content = "欸？我什麼都沒做啊！只不過是拍拍腦袋想出一些歪點子而已。",
  ui_story_1_4_4_dialog_content = "如果真要謝我，等先逃出去再說吧！",
  ui_story_1_4_5_dialog_content = "這位光靈果然不同凡響。你們配合得很有默契！",
  ui_story_1_4_6_dialog_content = "這麼多年的沉寂……今天一口氣打破了呢。",
  ui_story_1_4_X1_dialog_content = "但是，怎麼感覺你不太開心呢，PlayerName？是哪裡不舒服嗎？",
  ui_story_1_4_X2_dialog_content = "沒有，只是覺得……眼皮有點重吧……",
  ui_story_1_4_B29_dialog_content = "難道是想睡了？啊！我有這個——|\n《機械製圖學》！",
  ui_story_1_4_B30_dialog_content = "每次我想睡的時候都會翻一翻，看著這些圖表，精神一下就來了呢！",
  ui_story_1_4_B31_dialog_content = "我不認為大家都跟妳一樣，薇絲……",
  ui_story_1_4_X3_dialog_content = "欸？可是……啊！",
  ui_story_1_4_X4_dialog_content = "怎麼了？我臉上又有什麼東西嗎？",
  ui_story_1_4_X5_dialog_content = "鼻血！你在流鼻血！",
  ui_story_1_4_X6_dialog_content = "糟、糟了，感應……超載了……",
  ui_story_1_4_X7_dialog_content = "發射訊號的操作，讓腦袋超過極限了……",
  ui_story_1_4_A1_dialog_content = "欸？！明明剛才指揮我們所有人都遊刃有餘，怎麼會……？",
  ui_story_1_4_A2_dialog_content = "操作巨像設備……需要……更多精力……沒事，以前，也有過……馬上就……",
  ui_story_1_4_7_option_content = "不、不行了……",
  ui_story_1_4_8_option_content = "薇……絲……",
  ui_story_1_4_9_dialog_content = "你怎麼了……啊！快來人！PlayerName沿著通道滾下去了！！",
  ui_story_1_4_10_dialog_content = "等等，我扶不住你啦！妳們兩個快過來幫忙……PlayerName太重了！！",
  ui_story_1_4_12_dialog_content = "訊號吸引了很多暗鬼過來，我們必須盡快轉移！",
  ui_story_1_4_13_dialog_content = "薇絲中尉，他現在處於昏迷狀態，帶上他恐怕會拖累大家。",
  ui_story_1_4_A6_dialog_content = "而且我的任務是護送這位女士前往<color=#FFB400>28號地下城</color>，我們沒有多餘的……",
  ui_story_1_4_A3_dialog_content = "感謝你來支援我們，士兵。\n但是PlayerName剛才救了我們，我們不能拋棄他。",
  ui_story_1_4_14_dialog_content = "以怨報德可不是我們<color=#FFB400>啟光聯邦</color>的作風！",
  ui_story_1_4_A4_dialog_content = "況且，PlayerName……是一名空裔。",
  ui_story_1_4_15_dialog_content = "這……是真的嗎？",
  ui_story_1_4_16_dialog_content = "可是我們的戰鬥力不足，帶著一個昏迷的人難以保障所有人的安全！",
  ui_story_1_4_17_dialog_content = "你說得有道理，士兵。\n那就請你帶大家離開，留下補給，我在這裡保護他。",
  ui_story_1_4_18_dialog_content = "您的魄力真是令人敬佩！薇絲中尉。",
  ui_story_1_4_19_dialog_content = "我還沒介紹自己，我是白蘭，請多指教。",
  ui_story_1_4_20_dialog_content = "抱歉女士，因為我們耽誤了您的行程……",
  ui_story_1_4_21_dialog_content = "別放在心上，看到求救訊號沒有不回應的道理。",
  ui_story_1_4_22_dialog_content = "能夠參觀到一座巨像，也算是不虛此行呢。",
  ui_story_1_4_23_dialog_content = "既然隊長決定留下，身為聯合探索小隊的一員，我也不能臨陣脫逃。",
  ui_story_1_4_24_dialog_content = "咕？那……那我也留下來吧。畢竟PlayerName可是救過我們的命……",
  ui_story_1_4_25_dialog_content = "大家……",
  ui_story_1_4_A5_dialog_content = "啊！太好了，你醒了！\n我們的支援已經到了。現在感覺如何？可以行動嗎？",
  ui_story_1_4_26_dialog_content = "嗯……",
  ui_story_1_4_28_dialog_content = "薇絲中尉，剛收到訊息，在這附近發現卡拉肯的行蹤。",
  ui_story_1_4_29_dialog_content = "<color=#FFB400>高級暗鬼卡拉肯</color>？牠確實很活躍沒錯，但為什麼會接近這邊……",
  ui_story_1_4_30_dialog_content = "總之，那不是我們現在可以對抗的！必須轉移！",
  ui_story_1_4_31_dialog_content = "PlayerName，你可以跟我們走嗎？",
  ui_story_1_4_32_dialog_content = "我很想跟你們走，薇絲。但臨空者號……",
  ui_story_1_4_33_dialog_content = "原來這座巨像叫臨空者號嗎？他的回收工作可以等到之後再從長計議。",
  ui_story_1_4_X8_dialog_content = "我的職責是保證大家的安全，再無其他。",
  ui_story_1_4_X9_dialog_content = "無礙，PlayerName。只要你能脫離險境，我的安危並不重要。",
  ui_story_1_4_X10_dialog_content = "先和大家一起突破重圍，逃離此地吧！",
  ui_story_1_4_B1_option_content = "對不起，我會盡快回來接你！",
  ui_story_1_4_B2_option_content = "……沒有辦法一起離開嗎？",
  ui_story_1_4_B3_option_content = "我得收拾一下行李……",
  ui_story_1_4_B4_dialog_content = "我想好了，我跟你們走！",
  ui_story_1_4_B5_dialog_content = "今天這一刻，我等太久太久了……無論外面是什麼模樣，我都必須親眼看看。",
  ui_story_1_4_B6_dialog_content = "我還有好多好多問題，要問我的同胞……",
  ui_story_1_4_B7_dialog_content = "好！那就準備戰鬥吧，如果已經有大量暗鬼圍過來，恐怕會有更多戰鬥等著我們！",
  ui_story_1_4_B9_dialog_content = "留戀、恐懼和不安……這些情緒是成為強者的絆腳石。",
  ui_story_1_4_B10_dialog_content = "我希望你能學會克服這些情緒，從告別我開始。",
  ui_story_1_4_B11_dialog_content = "臨空者……",
  ui_story_1_4_B12_dialog_content = "唯有離開這裡，你才能成為完整的空裔。走吧，你不是還有這麼多夥伴嗎？",
  ui_story_1_4_B13_dialog_content = "而我哪裡都不會去的，不要擔心。",
  ui_story_1_4_B14_dialog_content = "PlayerName，我們必須行動了。趁更多暗鬼來之前！",
  ui_story_1_4_B15_dialog_content = "我知道了……",
  ui_story_1_4_B16_dialog_content = "好！大家，集中注意力！隨時做好戰鬥準備，一起離開這裡吧！",
  ui_story_1_4_B17_dialog_content = "欸？行李？",
  ui_story_1_4_B18_dialog_content = "用廢零件做的萬花筒、電線纏成的小球，還有用光能塗料畫的小塗鴉。",
  ui_story_1_4_B19_dialog_content = "……",
  ui_story_1_4_B20_dialog_content = "請不要取笑我……雖然是沒什麼意義的小東西，但它們陪伴我很久……",
  ui_story_1_4_B21_dialog_content = "我甚至幫他們取了名字……",
  ui_story_1_4_B22_dialog_content = "……我瞭解你的心情，但現在真的不是糾結那些東西的時候。",
  ui_story_1_4_B23_dialog_content = "相信我，PlayerName，離開這裡以後，你會有更加值得珍藏的東西。",
  ui_story_1_4_B24_dialog_content = "而且我和它們哪裡都不會去，等一切結束後再回來找我們吧。",
  ui_story_1_4_B25_dialog_content = "似乎也只能這樣了……",
  ui_story_1_4_B26_dialog_content = "抱歉說奇怪的話……我們還是先離開吧。",
  ui_story_1_4_B32_dialog_content = "哈哈，沒關係！我也有很多奇奇怪怪的小癖好啦！",
  ui_story_1_4_B27_dialog_content = "走吧！打起精神來，趁暗鬼聚集之前快點找到出口！",
  ui_story_1_4_B28_dialog_content = "導航員，也請你隨時做好指揮戰鬥的準備吧！",
  ui_story_1_8_1_dialog_content = "突圍的路上暗鬼還真不少……這個地方真的待不下去了呢。",
  ui_story_1_8_B37_dialog_content = "到處都是被破壞的痕跡……明明這些年來每天都打掃得一塵不染……",
  ui_story_1_8_2_dialog_content = "抱歉，PlayerName，要不是我們不請自來……",
  ui_story_1_8_3_dialog_content = "那我也沒機會離開這裡。別自責，妳們沒有錯，錯的是那些從暗影裡爬出來的東西。",
  ui_story_1_8_B29_dialog_content = "你放心，等我們回收了臨空者號，我一定會向啟光申請好好維修他的！",
  ui_story_1_8_B30_dialog_content = "我還可以親自幫你設計改造方案哦！",
  ui_story_1_8_B31_dialog_content = "你有想要的設計嗎？開放式廚房怎麼樣？平常可以弄點牛奶、煮章魚之類的。",
  ui_story_1_8_B32_dialog_content = "我不會下廚，平常都是臨空者負責……",
  ui_story_1_8_B33_dialog_content = "啊，也是。超大號浴缸呢？結束一天的工作後可以泡個熱水澡，再看本書……",
  ui_story_1_8_B34_dialog_content = "不不不，暫時也不需要那個……",
  ui_story_1_8_B35_dialog_content = "果然還是實用的機械製圖室比較重要嗎？",
  ui_story_1_8_B36_dialog_content = "薇絲，謝謝妳。如果妳是想讓我振作起來，我現在真的很有精神，沒問題的。",
  ui_story_1_8_4_dialog_content = "欸？啊……抱歉……",
  ui_story_1_8_B38_dialog_content = "只是發現你似乎有些低落，想用我覺得有趣的東西稍微岔開一下話題而已……",
  ui_story_1_8_5_dialog_content = "而且一想到你指揮的人數又變多了，就擔心你會不會又鼻血流滿地……",
  ui_story_1_8_6_dialog_content = "同時輔助所有人戰鬥問題並不大。比起和巨像的感應，這點程度就像是——",
  ui_story_1_8_7_dialog_content = "<size=45>前方異常！後退！快點後退！</size>",
  ui_story_1_8_8_dialog_content = "這是？！",
  ui_story_1_8_9_dialog_content = "這股力量，只有一種可能……可惡，還是碰到了！",
  ui_story_1_8_10_dialog_content = "<color=#FFB400>卡拉肯</color>！！",
  ui_story_1_8_11_dialog_content = "<anim type=Shake><size=50>吼！！</size></anim>",
  ui_story_1_8_12_dialog_content = "世界上還有這種體型的暗鬼嗎？！空之山谷難道也是面對這樣的……",
  ui_story_1_8_13_dialog_content = "小心，PlayerName！快移動到安全的地方！",
  ui_story_1_8_14_dialog_content = "哪裡還有安全的地方？！如果要突圍，就必須正面擊破卡拉肯！",
  ui_story_1_8_15_option_content = "那我們就正面擊破這傢伙！",
  ui_story_1_8_16_option_content = "那我在後方支援！",
  ui_story_1_8_17_dialog_content = "好！就是這種氣勢！我們上！",
  ui_story_1_8_A2_dialog_content = "指揮一樣交給你，導航員！",
  ui_story_1_8_18_dialog_content = "馬上和大家精神感應，請做好準備！",
  ui_story_1_8_19_dialog_content = "拜託你了！我們上！",
  ui_story_1_8_20_dialog_content = "<anim type=Shake><size=50>吼——！！！</size></anim>",
  ui_story_1_8_21_dialog_content = "別叫了！乖乖滾回地底去吧！！",
  ui_story_1_8_B1_dialog_content = "嘎嘎嘎……",
  ui_story_1_8_B2_dialog_content = "牠好像……在說些什麼？",
  ui_story_1_8_B3_option_content = "給牠最後一擊吧，薇絲",
  ui_story_1_8_B4_option_content = "強制感應！",
  ui_story_1_8_B6_dialog_content = "速射感知——",
  ui_story_1_8_B7_dialog_content = "無論這傢伙在說什麼，我都不想去瞭解了……",
  ui_story_1_8_B8_dialog_content = "牠實在太臭了……！！",
  ui_story_1_8_B9_dialog_content = "這是<color=#FFB400>暗影術</color>的氣味。所有暗鬼都靠這種能量活動。",
  ui_story_1_8_B10_dialog_content = "無論是誰聞到都會有點反胃的……",
  ui_story_1_8_B11_dialog_content = "嘎……嘎……",
  ui_story_1_8_B12_dialog_content = "果然……暗鬼們的語言完全無法理解……",
  ui_story_1_8_B13_dialog_content = "之前從來沒試著感應過其他生物，也許是我的能力還不熟練？",
  ui_story_1_8_B14_dialog_content = "……<color=#FFB400>空</color>……<color=#FFB400>裔</color>？",
  ui_story_1_8_B15_dialog_content = "……？",
  ui_story_1_8_B16_dialog_content = "唔嘎……",
  ui_story_1_8_B17_dialog_content = "死了……？可惜沒讀出更多情報，不過這傢伙的情緒倒是很激烈。",
  ui_story_1_8_B18_dialog_content = "與其說是臨死的恐懼，比較像是……訝異？為什麼？",
  ui_story_1_8_22_dialog_content = "我們……竟然戰勝了高級暗鬼……",
  ui_story_1_8_23_dialog_content = "難道是我在不知不覺間又變強了？",
  ui_story_1_8_24_dialog_content = "清醒點，這都是PlayerName的功勞。不然妳連該往哪邊走都不知道。",
  ui_story_1_8_25_dialog_content = "PlayerName的光感能力實在是太神奇了。",
  ui_story_1_8_A3_dialog_content = "說起來，我只在一些老兵口中聽過呢。",
  ui_story_1_8_26_dialog_content = "據說當年只要有空裔出戰，勝利就絕對屬於我們，看來並不是誇大其詞。",
  ui_story_1_8_27_dialog_content = "出口就在前面，讓我們一鼓作氣離開這裡吧！",
  ui_story_1_8_28_dialog_content = "PlayerName，體力沒問題嗎？",
  ui_story_1_8_B19_dialog_content = "還好。比起體力，我……我有什麼需要注意的事情嗎？",
  ui_story_1_8_B20_dialog_content = "你是指？",
  ui_story_1_8_B21_dialog_content = "我一直生活在巨像裡面，外面的世界究竟怎麼樣……",
  ui_story_1_8_B22_dialog_content = "我需要屏住呼吸嗎？",
  ui_story_1_8_B23_dialog_content = "也許空氣中會有未知的細菌？",
  ui_story_1_8_B24_dialog_content = "我需要閉上眼睛習慣陽光的感覺嗎？",
  ui_story_1_8_B25_dialog_content = "啊啊果然還是捂著臉比較好……",
  ui_story_1_8_B26_dialog_content = "……我能想像這傢伙十七年來都在想些什麼。",
  ui_story_1_8_B27_dialog_content = "哈哈，不用那麼誇張啦。跟我來就行了，外面的世界沒有你想的那麼奇怪。",
  ui_story_1_8_B28_dialog_content = "來，把手給我。",
  ui_story_1_8_29_dialog_content = "<color=#FFB400>新世界</color>……",
  ui_story_1_8_30_dialog_content = "——？！",
  ui_story_1_8_31_dialog_content = "薇絲……看來我們有麻煩了……",
  ui_story_1_8_32_dialog_content = "怎麼會，這是<color=#FFB400>暗鬼大軍</color>？！在這種地方？！",
  ui_story_1_8_33_dialog_content = "大家快退回去，把入口封起來！",
  ui_story_1_8_34_dialog_content = "剛才我們過來的時候明明還沒有……我來加強脆弱的牆面！",
  ui_story_1_8_A4_dialog_content = "但這樣做就很難再出去了，薇絲中尉！",
  ui_story_1_8_36_dialog_content = "怎麼會有這麼多暗鬼？！這裡又不是前線，怎麼會有這種規模！",
  ui_story_1_8_37_dialog_content = "冷靜，薇絲中尉。看來現在有大量暗鬼越過了前線來到這裡。",
  ui_story_1_8_38_dialog_content = "問題是，牠們是怎麼透過啟光封鎖線的？",
  ui_story_1_8_39_dialog_content = "也許是某種載具，可以越過地面……",
  ui_story_1_8_40_dialog_content = "什麼樣的載具能裝那麼多暗鬼？難道是另一座巨像嗎？沒有這麼巧合的事吧？",
  ui_story_1_8_41_dialog_content = "那也許只是我想太多了。不過……現在要離開就只有一個辦法了。",
  ui_story_1_8_42_dialog_content = "那就是<color=#FFB400>啟動這座巨像</color>。",
  ui_story_1_8_44_dialog_content = "可是，你從來沒有成功過……",
  ui_story_1_8_45_dialog_content = "還有其它選擇嗎？只能再去試一次了。",
  ui_story_1_8_46_dialog_content = "身為空裔，如果連巨像都啟動不了……",
  ui_story_1_8_47_dialog_content = "可是你之前暈倒過……撐得住嗎？",
  ui_story_1_8_48_dialog_content = "強行啟動的話，你的腦袋……不會爆炸之類的吧？",
  ui_story_1_8_49_dialog_content = "謝謝妳的擔心，但我還是要試試！",
  ui_story_1_8_50_dialog_content = "……",
  ui_story_1_8_51_dialog_content = "薇絲……妳那個表情，難道是想……",
  ui_story_1_8_52_dialog_content = "嗯。理論上，我是能幫上忙的。只是理論上的話。",
  ui_story_1_8_53_dialog_content = "妳們在說什麼？",
  ui_story_1_8_54_dialog_content = "好！我準備好了！有任何問題，我們就見招拆招！我相信沒有解決不了的難關！",
  ui_story_1_8_55_dialog_content = "之前都是你一人在面對，這次有了我們，說不定問題就迎刃而解了呢？",
  ui_story_1_8_56_dialog_content = "妳怎麼比我還有信心？",
  ui_story_1_8_57_dialog_content = "當然。我可是個樂天派哦，PlayerName。",
  ui_story_1_8_59_dialog_content = "在我眼裡，這點困難不過是啟程的試煉而已！而你現在已經不是孤身一人了！",
  ui_story_1_8_60_dialog_content = "好！那就一起前往艦橋吧！",
  ui_story_1_8_61_dialog_content = "PlayerName……",
  ui_story_1_8_62_dialog_content = "這次我一定會啟動你的，臨空者！",
  ui_story_1_9_1_dialog_content = "<color=#e8d9bb>主控系統自動檢查……無異常。正在啟動……</color>",
  ui_story_1_9_2_dialog_content = "<color=#e8d9bb>生物模組自動檢查……發現異常，處於瀕死狀態。</color>",
  ui_story_1_9_3_dialog_content = "<color=#e8d9bb>維生系統自動檢查……關閉狀態。</color>",
  ui_story_1_9_4_dialog_content = "<color=#e8d9bb>引擎自動檢查……無異常。正在啟動……</color>",
  ui_story_1_9_5_dialog_content = "<color=#e8d9bb>10％……23％……</color>",
  ui_story_1_9_6_dialog_content = "<color=#e8d9bb>76%……85%……</color>",
  ui_story_1_9_7_dialog_content = "<color=#e8d9bb>啟動失敗。累積失敗次數：3922次。</color>",
  ui_story_1_9_8_dialog_content = "果然……還是不行。",
  ui_story_1_9_10_dialog_content = "為什麼，到底為什麼無法啟動？！問題到底出在哪裡……？",
  ui_story_1_9_11_dialog_content = "唔！又要、到極限了嗎……",
  ui_story_1_9_12_dialog_content = "咕咕……PlayerName怎麼了……",
  ui_story_1_9_13_dialog_content = "薇絲，如果妳確定的話，現在就是時候了。",
  ui_story_1_9_14_dialog_content = "嗯！這個與「鋼琴」一模一樣的東西，就是巨像的控制台吧？",
  ui_story_1_9_15_dialog_content = "讓我和你一起啟動巨像吧，導航員。",
  ui_story_1_9_16_dialog_content = "一起……？薇絲，妳是光靈，沒有感應能力……",
  ui_story_1_9_17_dialog_content = "但我可以成為你的力量。我……可以幫上忙。",
  ui_story_1_9_18_dialog_content = "……？",
  ui_story_1_9_19_dialog_content = "相信我吧，PlayerName。我和你其實……是有些相似之處的。",
  ui_story_1_9_21_dialog_content = "不過那就說來話長了。等以後有機會，我再好好跟你講吧！",
  ui_story_1_9_22_dialog_content = "……但妳真的知道怎麼用這座控制台嗎？",
  ui_story_1_9_23_dialog_content = "當然！別忘了我可是對巨像有些研究的！",
  ui_story_1_9_24_dialog_content = "而且，啟光一直在實施「重建巨像與培養導航員」的計劃，可惜……",
  ui_story_1_9_25_dialog_content = "總之，如果我們兩人合作的話，說不定能啟動引擎！",
  ui_story_1_9_26_dialog_content = "但如果出了問題，也意味著我們兩個都會……\n照妳的說法，「腦袋爆炸」喔。",
  ui_story_1_9_27_dialog_content = "目前只剩這一個辦法，即使有風險也要嘗試。",
  ui_story_1_9_28_dialog_content = "明白了。都已經來到這裡，也沒有退路了。過來，一起坐下。",
  ui_story_1_9_29_dialog_content = "我教妳如何「彈奏」它。",
  ui_story_1_9_30_dialog_content = "<color=#e8d9bb>引擎自動檢查……無異常。正在啟動……</color>",
  ui_story_1_9_B1_dialog_content = "導航員，請告訴我該怎麼做。",
  ui_story_1_9_B2_dialog_content = "很簡單，就像演奏一首鋼琴曲。",
  ui_story_1_9_B3_dialog_content = "我看不見曲譜。可以指出我該按下的琴鍵嗎？",
  ui_story_1_9_31_dialog_content = "<color=#e8d9bb>16%……33%……</color>",
  ui_story_1_9_B4_dialog_content = "我感受到……能量在流動。",
  ui_story_1_9_B5_dialog_content = "妳在為他注入光能嗎？",
  ui_story_1_9_B6_dialog_content = "嗯。就像對話一般——雖然我無法理解巨像的語言。",
  ui_story_1_9_B7_dialog_content = "他的語言就是琴鍵的語言，薇絲。",
  ui_story_1_9_32_dialog_content = "<color=#e8d9bb>89%……97%……</color>",
  ui_story_1_9_B8_dialog_content = "快成功了……這簡直，難以置信……",
  ui_story_1_9_B9_dialog_content = "導航員，曲譜快到尾聲了吧？",
  ui_story_1_9_B10_dialog_content = "是的。讓我們完成啟動他的指令吧，薇絲！",
  ui_story_1_9_B11_dialog_content = "最後的音符——",
  ui_story_1_9_33_dialog_content = "<color=#e8d9bb>100%，啟動成功。</color>",
  ui_story_1_9_34_dialog_content = "怎麼回事！周圍亮起來了！",
  ui_story_1_9_35_dialog_content = "<size=45>PlayerName！！</size>",
  ui_story_1_9_36_dialog_content = "艦橋是在發光嗎……？",
  ui_story_1_9_37_dialog_content = "<size=45>啟、啟、啟動了！！</size>",
  ui_story_1_9_38_dialog_content = "……！",
  ui_story_1_9_40_dialog_content = "PlayerName！真的成功了！！沒想到竟然能做到這步！",
  ui_story_1_9_41_dialog_content = "這——就是艦橋的樣子！都亮起來了！",
  ui_story_1_9_42_dialog_content = "好漂亮，這是光能的顏色嗎？",
  ui_story_1_9_A1_dialog_content = "還是說……那就是極光？！",
  ui_story_1_9_43_dialog_content = "太令人震撼了！我從未見過這種景色……",
  ui_story_1_9_44_dialog_content = "這就是真正的……天空？很刺眼，但太美了……",
  ui_story_1_9_45_dialog_content = "不敢相信我們真的做到了！這股迸發的力量我從未感受過！",
  ui_story_1_9_46_dialog_content = "你真的「活起來」了，臨空者！！",
  ui_story_1_9_47_dialog_content = "沒錯！能源開始流入身體的各個部位了——但我還需要時間才能起飛！",
  ui_story_1_9_48_dialog_content = "周圍可能會有敵人，請隨時保持警惕！",
  ui_story_1_9_49_dialog_content = "太久沒動彈了，需要先熱熱身嗎？",
  ui_story_1_9_50_dialog_content = "哈哈，可以這麼說！看你的樣子，似乎還很遊刃有餘呢？",
  ui_story_1_9_51_dialog_content = "PlayerName！注意自己的狀態！",
  ui_story_1_9_52_dialog_content = "我現在感覺很好，薇絲！沒有任何不適！",
  ui_story_1_9_A2_dialog_content = "我一直都在幻想，到底會以什麼樣的契機離開這裡、重回這個世界；",
  ui_story_1_9_A3_dialog_content = "但從沒想過是像今天這樣，沒想到是和光靈們一起！",
  ui_story_1_9_53_dialog_content = "我們一起做到了我從來不敢想像的事！",
  ui_story_1_9_54_dialog_content = "我也很難想像這一切呢……",
  ui_story_1_9_A4_dialog_content = "完好的巨像、近在咫尺的「極光」……",
  ui_story_1_9_55_dialog_content = "你要知道，哪怕就在昨天，我還只是個無法單獨與暗鬼作戰的啟光士兵呢～",
  ui_story_1_9_56_dialog_content = "暈……那個夢……又來了嗎…",
  ui_story_1_9_58_dialog_content = "<color=#FFB400>舒默</color>，為什麼！！",
  ui_story_1_9_59_dialog_content = "舒默，妳這個叛徒！為了力量，妳竟然背叛自己的族人？！",
  ui_story_1_9_60_dialog_content = "背叛……投敵……這些不過是偽善者和懦夫的墓誌銘罷了。",
  ui_story_1_9_61_dialog_content = "空之山谷已經腐爛了，各位「同胞」，我將用自己的方式，實踐你們口中的價值觀。",
  ui_story_1_9_62_dialog_content = "不要掙扎，這只是簡單的適者生存而已。",
  ui_story_1_9_63_dialog_content = "不——！",
  ui_story_1_9_64_dialog_content = "……又是那個夢？",
  ui_story_1_9_65_dialog_content = "不……更多。臨空者，這到底是什麼意思？為什麼會有這些畫面？！",
  ui_story_1_9_A5_dialog_content = "……",
  ui_story_1_9_66_option_content = "先不管這些了",
  ui_story_1_9_A6_option_content = "這些根本不是幻象！",
  ui_story_1_9_67_option_content = "你有什麼事情瞞著我？",
  ui_story_1_9_B12_dialog_content = "我……不能被這些沒頭沒尾的畫面干擾。",
  ui_story_1_9_B13_dialog_content = "現在剛完成啟動，我必須維持巨像穩定，集中精神，快……",
  ui_story_1_9_B14_dialog_content = "辛苦你了，PlayerName。你看到的這些畫面……會得到解釋的。",
  ui_story_1_9_B15_dialog_content = "即便是我，也還在尋求答案，而現在我們已經做好了準備。",
  ui_story_1_9_B16_dialog_content = "你又開始說這些晦澀難懂的話了，臨空者。但無論如何……今天，我做到了。",
  ui_story_1_9_B17_dialog_content = "是的。繼續前進吧，以空裔的身分——藍天就在眼前了。",
  ui_story_1_9_B18_dialog_content = "太真實了……這些畫面是真的，不是幻象！是真實發生過的事情，對吧？！",
  ui_story_1_9_B19_dialog_content = "既然它們在你的意識裡，必然會在現實中留下痕跡。我無法否認這一點。",
  ui_story_1_9_B20_dialog_content = "不要用拐彎抹角的方式糊弄我，臨空者……我需要一個答案！",
  ui_story_1_9_B21_dialog_content = "很遺憾，我也想告訴你，但我做不到。",
  ui_story_1_9_B22_dialog_content = "我不記得了，一切都遺失在那個夜晚，我唯一記住的只有讓你活下去的命令。",
  ui_story_1_9_B23_dialog_content = "……",
  ui_story_1_9_B24_dialog_content = "真實也好，幻象也罷，我們現在已經啟程了。",
  ui_story_1_9_B25_dialog_content = "而你也做好了親自尋找答案的準備，不是嗎？",
  ui_story_1_9_B26_dialog_content = "回答我，臨空者。你到底在隱瞞些什麼……這些畫面，到底是真的假的？！",
  ui_story_1_9_B27_dialog_content = "我不知道，PlayerName。",
  ui_story_1_9_B28_dialog_content = "開什麼玩笑……",
  ui_story_1_9_B29_dialog_content = "我從未欺騙過你。但事實就是，關於當年的一切我都「遺失」了，丟在記憶的深海裡。",
  ui_story_1_9_B30_dialog_content = "我也一直希望能給你一個答案，而不是縹緲的希望。但看來命運仍有轉機。",
  ui_story_1_9_B31_dialog_content = "有了新夥伴的幫助，你已經做好親自尋找答案的準備了，不是嗎？",
  ui_story_1_9_B32_dialog_content = "但那個答案，到底是什麼呢……",
  ui_story_1_9_B33_dialog_content = "我的族人，我的空谷，如果答案的最後一頁寫著我最害怕的內容——",
  ui_story_1_9_B34_dialog_content = "這一切，又有什麼意義呢？",
  ui_story_1_10_1_dialog_content = "<color=#e8d9bb>某處</color>",
  ui_story_1_10_2_dialog_content = "（日蝕語）回報……有光靈闖入巨像臨空者號內部，而裡面有空裔存在……",
  ui_story_1_10_3_dialog_content = "（日蝕語）光靈小隊戰鬥力很強，卡拉肯未能完成真理之命……",
  ui_story_1_10_A1_dialog_content = "（日蝕語）卡拉肯將懷著罪人的覺悟，回到母親所在的彼岸請罪……",
  ui_story_1_10_4_dialog_content = "（日蝕語）<color=#FFB400>日蝕</color>，永存……",
  ui_story_1_10_5_dialog_content = "以上就是卡拉肯那傢伙的「遺言」嗎？ 「被光靈和空裔給打敗了」？",
  ui_story_1_10_6_dialog_content = "哼，沒想到<color=#FFB400>當年</color>還有漏網之魚，我以為他們一個都不剩了呢。",
  ui_story_1_10_A2_dialog_content = "我親自去解決那個空裔吧？",
  ui_story_1_10_7_dialog_content = "怎麼，對自己<color=#FFB400>族人</color>趕盡殺絕讓妳這麼高興嗎？",
  ui_story_1_10_8_dialog_content = "……族人？已經很多年都沒聽到這個詞了。",
  ui_story_1_10_9_dialog_content = "妳有更重要的事情得做，別老是分心在這種無關緊要的事情上。",
  ui_story_1_10_10_dialog_content = "我們想要的東西不在那座巨像裡，別浪費妳我的時間。妳還等得不夠久嗎？",
  ui_story_1_10_11_dialog_content = "至於那個空裔，就交給<color=#FFB400>麥格芬</color>吧，他剛好在附近不是嗎？",
  ui_story_1_10_12_dialog_content = "你要讓那傢伙來接卡拉肯的爛攤子嗎？",
  ui_story_1_10_13_dialog_content = "光憑麥格芬就夠對付那群光靈了，而且最好是帶活的回來……",
  ui_story_1_10_14_dialog_content = "我會叫他完事後立刻與我們會合，正事要緊。",
  ui_story_1_10_A3_dialog_content = "他很聽話，哪像妳。有空多學學他吧。",
  ui_story_1_10_15_dialog_content = "……哼，和那件事比起來，一個毫無頭緒的空裔確實不值得一提。",
  ui_story_1_10_16_dialog_content = "但你要是再瞧不起我，我可是會找機會扭斷你的脖子哦。",
  ui_story_1_10_17_dialog_content = "哈、哈、哈……妳很幽默嘛，<color=#FFB400>舒默</color>。",
  ui_story_1_10_18_dialog_content = "麥格芬，就送你到這裡了。要是敢搞砸，你知道後果！",
  ui_story_1_10_19_dialog_content = "當然。麥格芬，無所畏懼……",
  ui_story_1_10_21_dialog_content = "目標就在眼前。腐臭的枯骨、漏網的巨像……貿然在我們的領地露出真面目。",
  ui_story_1_10_22_dialog_content = "趁他還沒起飛，給我把他釘死在地面上！",
  ui_story_1_10_23_dialog_content = "然後找遍豬圈的每一個角落，找出那個空裔，獻給大人！",
  ui_story_1_10_24_dialog_content = "<size=45>以母親之名——進攻！</size>",
  ui_story_1_10_25_dialog_content = "那個規模……是認真的嗎。",
  ui_story_1_10_26_dialog_content = "巨像啟動後，我們等於暴露在敵人的視野中，周圍的所有暗鬼都在聚集。",
  ui_story_1_10_27_dialog_content = "這是難以避免的。所以臨空者號還需要時間預熱對嗎？",
  ui_story_1_10_B1_dialog_content = "……",
  ui_story_1_10_B2_dialog_content = "PlayerName？",
  ui_story_1_10_B3_dialog_content = "嗯？抱歉，我……剛才在想其他事。",
  ui_story_1_10_B4_dialog_content = "……我想確認一下，臨空者號是不是還需要時間才能預熱完成。",
  ui_story_1_10_28_dialog_content = "嗯，恐怕沒錯。臨空者號還需要一些時間才能動起來。但等他飛上天空，我們就安全了。",
  ui_story_1_10_30_dialog_content = "幫我拖延時間，PlayerName。",
  ui_story_1_10_31_dialog_content = "很快我就能帶大家一起離開。新世界的天空，我已經迫不及待了！",
  ui_story_1_10_32_dialog_content = "我們得死守臨空者號！只要等到他飛起來就行了！",
  ui_story_1_10_33_dialog_content = "好！那我們分頭行動，守住這裡的每一個入口！",
  ui_story_1_10_34_dialog_content = "PlayerName，請你留在艦橋！",
  ui_story_1_10_35_dialog_content = "看來，接下來就是「巷戰」了！我的人，都過來！",
  ui_story_1_10_A4_dialog_content = "把武器填裝好，為臨空者號爭取預熱完成的時間！",
  ui_story_1_10_36_dialog_content = "為了啟明之光！",
  ui_story_1_10_37_dialog_content = "為了啟明之光！",
  ui_story_1_10_38_dialog_content = "為了什麼光？？",
  ui_story_1_14_1_dialog_content = "（日蝕語）巨像馬上就要預熱完成了！立刻毀掉他！讓他變成光靈們的棺材！",
  ui_story_1_14_2_dialog_content = "（日蝕語）我們已經攻入巨像各個區域，但在艦橋等地遇到強烈抵抗，損失慘重……",
  ui_story_1_14_3_dialog_content = "（日蝕語）所以呢？我們是貪生怕死的生物嗎？",
  ui_story_1_14_4_dialog_content = "（日蝕語）絕不是！",
  ui_story_1_14_5_dialog_content = "（日蝕語）那就把你的利爪磨好，不許再有這種遲疑。",
  ui_story_1_14_A1_dialog_content = "（日蝕語）就算是死，也要在倒下的時候先劃開敵人的肚皮！",
  ui_story_1_14_6_dialog_content = "（日蝕語）帶路吧，讓我親自見見那些負隅頑抗的光靈們……！",
  ui_story_1_14_7_dialog_content = "<color=#e8d9bb>巨像內</color>",
  ui_story_1_14_8_dialog_content = "所有人抓緊時間休息，下一撥暗鬼不久又會攻上來。清點彈藥、統計傷亡！",
  ui_story_1_14_9_dialog_content = "報告！殘彈十一發，參戰六人，輕傷四人，兩人……",
  ui_story_1_14_10_dialog_content = "……嗯，我瞭解了。",
  ui_story_1_14_11_dialog_content = "隊長，我們撤退吧……",
  ui_story_1_14_12_dialog_content = "辦不到！現在薇絲她們正防守最重要的艦橋，我們也必須在外圍牽制其他暗鬼！",
  ui_story_1_14_13_dialog_content = "大家都在為了活下去而拼命，大家都一樣艱難！不准再說出這種話，列兵！！",
  ui_story_1_14_14_dialog_content = "所有人，打起精神！彈藥用光的人，就把你們的刀子給我抽出來吧！！",
  ui_story_1_15_1_dialog_content = "這隻——也別想跑！！",
  ui_story_1_15_2_dialog_content = "太好了！這樣一來，艦橋處的暗鬼就被清乾淨了！！",
  ui_story_1_15_3_dialog_content = "PlayerName，你的指揮也越來越熟練了呢！",
  ui_story_1_15_4_dialog_content = "今天無論是技巧還是大腦「轉速」，都以肉眼可見的速度成長不少……",
  ui_story_1_15_5_dialog_content = "不知道巨像其他地方的戰況如何……",
  ui_story_1_15_6_dialog_content = "臨空者，你還需要多久？",
  ui_story_1_15_7_dialog_content = "引擎已經發動，麻煩各位站穩了。\n<size=45>巨像，升空！</size>",
  ui_story_1_15_8_dialog_content = "飛起來了？！",
  ui_story_1_15_9_dialog_content = "哇——差點從控制台上被甩下去……外面好高！！我們在飛行嗎？！",
  ui_story_1_15_10_dialog_content = "大家快抓住些什麼！",
  ui_story_1_15_11_dialog_content = "薇絲妳抓到我頭髮了！！",
  ui_story_1_15_A1_dialog_content = "天空！真是久違了……上一次翱翔，還是瀰漫著血腥味的那個夜晚呢……",
  ui_story_1_15_A2_dialog_content = "PlayerName，我想要繼續加速！",
  ui_story_1_15_A3_dialog_content = "當然，臨空者，請繼續攀升！",
  ui_story_1_15_12_dialog_content = "讓我們用最大功率飛起來！！那些暗鬼好像也都被甩下去了！",
  ui_story_1_15_13_dialog_content = "好！就讓我們一起飛回最高的天空吧！",
  ui_story_1_15_14_dialog_content = "薇絲中尉，這股震動是？！",
  ui_story_1_15_15_dialog_content = "我正想聯絡你！我們成功起飛了！",
  ui_story_1_15_16_dialog_content = "是嗎……太好了……我還以為、來不及了……",
  ui_story_1_15_17_dialog_content = "來不及？發生什麼事了？你們還好嗎！",
  ui_story_1_15_18_dialog_content = "有個大傢伙已經進來了！我們……攔不住，好多人都……",
  ui_story_1_15_19_dialog_content = "牠直接往艦橋那邊去了！是高級暗鬼沒錯……抱歉……",
  ui_story_1_15_20_dialog_content = "難道有強敵？！還沒結束，大家保持警惕！！",
  ui_story_1_15_21_dialog_content = "怎、怎麼溫度突然降了下來？好冷……",
  ui_story_1_15_22_dialog_content = "不是溫度，多孚。那是暗能的觸感……各位，敵人已經出現了。",
  ui_story_1_15_23_dialog_content = "<color=#e8d9bb>突然，一陣惡寒襲來——</color>",
  ui_story_1_15_25_dialog_content = "沒用的東西。竟然讓這座棺柩成功起飛。不過你們也到此為止了。",
  ui_story_1_15_26_dialog_content = "另一隻高級暗鬼？！",
  ui_story_1_15_27_dialog_content = "我有名字，光靈。你可以叫我<color=#FFB400>麥格芬</color>，這是母親大人賜予的名字……",
  ui_story_1_15_28_dialog_content = "記住這個字眼吧，就當做你們到達真理的彼岸後，用來引路的明燈！",
  ui_story_1_15_29_dialog_content = "為什麼這隻暗鬼會說話？「母親」？「真理」？這些是什麼意思？",
  ui_story_1_15_30_dialog_content = "不要跟牠多費唇舌，PlayerName！會通用語的暗鬼很少，這傢伙不對勁！",
  ui_story_1_15_31_dialog_content = "我們掌握通用語，用來讓光靈獲得頓悟。然而看來有些螻蟻注定冥頑不化……",
  ui_story_1_15_32_dialog_content = "出於對將死之人的尊重，我說得夠多了。接下來——",
  ui_story_1_15_33_dialog_content = "該赴死了。",
  ui_story_1_15_34_option_content = "你說的是你自己吧！",
  ui_story_1_15_35_option_content = "各位，準備戰鬥！",
  ui_story_1_15_36_dialog_content = "你們……竟敢傷害我！！夠了！",
  ui_story_1_15_37_dialog_content = "本想留你們小命，但要想踩過螞蟻而不傷到牠，力道實在難以掌握！！",
  ui_story_1_15_38_dialog_content = "<color=#FFB400>舒默大人</color>……您可真是交給了麥格芬一項艱難的任務呢。",
  ui_story_1_15_39_dialog_content = "<color=#FFB400>舒默</color>？！那是之前夢境裡的名字！你從哪裡聽到的！她是誰？！",
  ui_story_1_15_40_dialog_content = "看來空裔對當年的事並非一無所知……但那又如何？",
  ui_story_1_15_B1_dialog_content = "你的族人已經全都死在我們手下，苟活下去會讓你覺得滿足嗎？",
  ui_story_1_15_B2_dialog_content = "你說……什麼？",
  ui_story_1_15_B3_dialog_content = "奇怪的問題，我相信你已聽清楚我的話了。",
  ui_story_1_15_B4_dialog_content = "你的族人，<color=#FFB400>全都死了</color>。",
  ui_story_1_15_B5_dialog_content = "空之山谷，已經不復存在了。",
  ui_story_1_15_B6_dialog_content = "火海、哀嚎，一個一個被踩爛揉碎……\n然後丟掉了。",
  ui_story_1_15_B7_dialog_content = "……不……不、不會的。",
  ui_story_1_15_B8_dialog_content = "不可能……",
  ui_story_1_15_B9_dialog_content = "閉嘴吧，暗鬼！你懂什麼？！",
  ui_story_1_15_B10_dialog_content = "因為我在現場。<color=#FFB400>我們</color>都在……如此盛大的活動，誰會缺席呢？",
  ui_story_1_15_B11_dialog_content = "總有一天，我們也會突破光靈的防線，為你們獻上同樣的「滅族盛典」。",
  ui_story_1_15_41_dialog_content = "PlayerName，別相信暗鬼的話！",
  ui_story_1_15_42_dialog_content = "我並不在乎你是否相信。反正你們都要死了。",
  ui_story_1_15_44_dialog_content = "怎麼可能讓你得逞？！",
  ui_story_1_15_46_dialog_content = "愚蠢！明明可以苟活，卻要趕來赴死！",
  ui_story_1_15_47_dialog_content = "嗚啊……！！",
  ui_story_1_15_48_dialog_content = "無謂的衝動，被我踩在腳下就是你的計劃嗎？！",
  ui_story_1_15_49_dialog_content = "是……是<color=#FFB400>炸彈</color>哦，愚蠢的怪物……",
  ui_story_1_15_50_dialog_content = "你……",
  ui_story_1_15_53_dialog_content = "<size=45>和我一起墜入地獄吧，白癡。</size>",
  ui_story_1_15_54_dialog_content = "PlayerName！你們在的位置被轟出一個缺口，請注意安全！",
  ui_story_1_15_55_dialog_content = "風壓！！要被拖出去了——！",
  ui_story_1_15_56_dialog_content = "等等——！！",
  ui_story_1_15_B13_dialog_content = "隊長！！",
  ui_story_1_15_B14_dialog_content = "別過去！！先抓住我的手，別被吸出去了！",
  ui_story_1_15_B15_dialog_content = "可惡，為什麼會變成這樣……明明都已經到了最後關頭……！",
  ui_story_1_15_57_dialog_content = "爆……爆炸了？那位光靈，為什麼……",
  ui_story_1_15_A4_dialog_content = "剛才變成碎片的，是他的身體……？",
  ui_story_1_15_58_dialog_content = "PlayerName！冷靜！你的精神狀態在波動……",
  ui_story_1_15_A5_dialog_content = "和記憶裡……同胞們的軀體……",
  ui_story_1_15_A6_dialog_content = "都死了，<color=#FFB400>所有人都死了</color>？空谷外面呢，大陸外面呢？我是<color=#FFB400>最後一名空裔</color>？",
  ui_story_1_15_A7_dialog_content = "你的心率在飆升！當心又像之前那樣超載！",
  ui_story_1_15_B12_dialog_content = "不可能的……不應該是這樣的，我好不容易才……",
  ui_story_1_15_A8_dialog_content = "<size=45>別開玩笑了！！！</size>",
  ui_story_1_15_59_dialog_content = "巨、巨像突然加速了？！快要站不穩了……",
  ui_story_1_15_60_dialog_content = "空裔！！你做了什麼？！不行，爪子抓不住了……",
  ui_story_1_15_61_dialog_content = "<size=45>不可能的、不可能的……</size>",
  ui_story_1_15_62_dialog_content = "<size=45>導航員，低頭！！</size>",
  ui_story_1_15_63_dialog_content = "嘎啊……！！！",
  ui_story_2_1_A1_dialog_content = "「巨像終於啟航了。」",
  ui_story_2_1_A2_dialog_content = "「就在不久前，我還以為自己會永遠困在地底。」",
  ui_story_2_1_A3_dialog_content = "「但就在我完成這一切的瞬間……」",
  ui_story_2_1_A4_dialog_content = "「我的生命又失去了意義。」",
  ui_story_2_1_A5_dialog_content = "「因為空裔們……都已經不復存在了。」",
  ui_story_2_1_1_dialog_content = "咦？你在寫日記嗎？",
  ui_story_2_1_3_dialog_content = "嗯，以前養成的習慣，一個人也沒其他事情可做。",
  ui_story_2_1_4_dialog_content = "寫日誌可以讓我保持對時間的概念，雖然也沒什麼用……",
  ui_story_2_1_5_dialog_content = "這個習慣很好呢，看來PlayerName是個對自己非常嚴苛的人……",
  ui_story_2_1_6_dialog_content = "現在情況怎麼樣了？",
  ui_story_2_1_B26_dialog_content = "我們已經暫時脫離險境，也大致安置好傷患了。",
  ui_story_2_1_B27_dialog_content = "那位……犧牲了自己的士兵……",
  ui_story_2_1_B28_dialog_content = "……",
  ui_story_2_1_B29_dialog_content = "遺體已經沒辦法回收，但我會為他立一塊墓碑。",
  ui_story_2_1_B30_dialog_content = "……",
  ui_story_2_1_B31_dialog_content = "……這是你第一次目睹死亡嗎？",
  ui_story_2_1_B32_dialog_content = "不是。",
  ui_story_2_1_B33_dialog_content = "但這種事情，無論經歷多少次我都沒辦法習慣……",
  ui_story_2_1_B34_dialog_content = "他的……家人，該怎麼辦？",
  ui_story_2_1_B35_dialog_content = "放心，啟光聯邦會妥善安置他的家人。",
  ui_story_2_1_B37_dialog_content = "我們會記住所有為啟明之光犧牲的英雄。",
  ui_story_2_1_B38_dialog_content = "抱歉，PlayerName。",
  ui_story_2_1_B39_dialog_content = "為什麼道歉？",
  ui_story_2_1_B40_dialog_content = "我只是打從心底感到十分抱歉，因為今天發生的所有事情……",
  ui_story_2_1_B41_dialog_content = "作為生者，我們現在唯一能做的，就是繼續前進，不讓死者白白犧牲。",
  ui_story_2_1_F1_dialog_content = "……",
  ui_story_2_1_7_dialog_content = "你有什麼打算嗎？",
  ui_story_2_1_8_dialog_content = "……我不知道。",
  ui_story_2_1_9_dialog_content = "不如……和我一起回啟光吧？",
  ui_story_2_1_10_dialog_content = "妳……聽到之前麥格芬說的話了嗎？",
  ui_story_2_1_A8_dialog_content = "我聽到了，但那只是他的一面之詞。",
  ui_story_2_1_11_dialog_content = "我的族人全都死了，空之山谷不復存在了。",
  ui_story_2_1_13_dialog_content = "……",
  ui_story_2_1_A9_dialog_content = "你還有故鄉可以回去，還有許多族人，可是我……",
  ui_story_2_1_14_dialog_content = "……PlayerName，別這樣想。",
  ui_story_2_1_15_dialog_content = "一定還有其他空裔像你一樣活著！",
  ui_story_2_1_B1_dialog_content = "……",
  ui_story_2_1_B2_dialog_content = "我可以幫你一起找！",
  ui_story_2_1_B3_dialog_content = "抱歉，薇絲。我只是……",
  ui_story_2_1_B4_dialog_content = "沒關係的，我明白。",
  ui_story_2_1_B5_dialog_content = "我在地底待了十七年，對空谷念想了十七年。",
  ui_story_2_1_B6_dialog_content = "忽然被告知這一切……早就消失了？我無法接受，我不能接受！",
  ui_story_2_1_B7_dialog_content = "那就不要接受，PlayerName。",
  ui_story_2_1_B8_dialog_content = "我……我想知道十七年前到底發生什麼事！",
  ui_story_2_1_B9_dialog_content = "好！我們可以探索整個大陸，找尋當年的真相！",
  ui_story_2_1_B10_dialog_content = "但在那之前，你必須好好休息。跟我回啟光吧。",
  ui_story_2_1_A10_option_content = "好，我先跟妳走",
  ui_story_2_1_A11_option_content = "不，我有自己的路",
  ui_story_2_1_A12_dialog_content = "妳說得對，薇絲。",
  ui_story_2_1_A13_dialog_content = "而且，我現在確實無處可去……",
  ui_story_2_1_A14_dialog_content = "放心吧，你一定不會討厭啟光的～",
  ui_story_2_1_B11_dialog_content = "妳說的是「<color=#FFB400>舒默</color>」吧……這個名字，對我來說既遙遠又陌生。",
  ui_story_2_1_B12_dialog_content = "除了反復回憶起那副臉孔之外，我現在什麼也做不了。",
  ui_story_2_1_B13_dialog_content = "所以你更要答應我，先保護好自己和這座巨像。",
  ui_story_2_1_B14_dialog_content = "等你把思緒梳理清楚，也調整好臨空者的狀態後，我再陪你繼續冒險。",
  ui_story_2_1_A15_dialog_content = "為什麼？",
  ui_story_2_1_A16_dialog_content = "嗯？因為啟光聯邦……",
  ui_story_2_1_A17_dialog_content = "我是說，為什麼妳願意做我的朋友？還願意幫我？",
  ui_story_2_1_A18_dialog_content = "那還用說，你可是我的救命恩人！",
  ui_story_2_1_A19_dialog_content = "況且，你的能力對光靈來說意義非凡……",
  ui_story_2_1_A20_dialog_content = "是那個什麼「巨像導航員」計劃嗎？",
  ui_story_2_1_A21_dialog_content = "是「重建巨像與培養導航員」計劃啦。",
  ui_story_2_1_A22_dialog_content = "其實，我自己也……啊，不重要不重要！",
  ui_story_2_1_A23_dialog_content = "雖然聽不懂妳在說什麼……",
  ui_story_2_1_F2_dialog_content = "但我願意相信妳，薇絲。",
  ui_story_2_1_A24_dialog_content = "PlayerName……謝謝。",
  ui_story_2_1_A25_dialog_content = "好了，讓我們盡快找到最近的啟光地下城吧。不好好休息整備一下的話……",
  ui_story_2_1_A26_dialog_content = "這些年來，我一直在努力。",
  ui_story_2_1_A28_dialog_content = "我每天都試著啟動巨像，暈倒過不知多少次。",
  ui_story_2_1_B15_dialog_content = "我每天都在學習臨空者傳授的知識，雖然不知道有什麼用。",
  ui_story_2_1_B16_dialog_content = "我每天都想像著能看到外面的世界，能回到空之山谷。",
  ui_story_2_1_B17_dialog_content = "我知道你真的很努力，PlayerName。",
  ui_story_2_1_B19_dialog_content = "我想，我有屬於自己的路。",
  ui_story_2_1_B20_dialog_content = "可是你要去哪裡呢？",
  ui_story_2_1_B21_dialog_content = "……",
  ui_story_2_1_B22_dialog_content = "回家……我要回到空之山谷。",
  ui_story_2_1_B23_dialog_content = "我還要找到<color=#FFB400>舒默</color>。",
  ui_story_2_1_A29_dialog_content = "PlayerName，你一個人太危險了！",
  ui_story_2_1_A30_dialog_content = "我知道會很危險。但是我想知道真相，我想回家。",
  ui_story_2_1_A31_dialog_content = "你和臨空者剛剛衝出地面，又經歷了這麼多……你們現在真的很需要休息。",
  ui_story_2_1_A32_dialog_content = "等你們休息整備好，我、我可以幫你找……",
  ui_story_2_1_A33_dialog_content = "妳為什麼要幫我？",
  ui_story_2_1_A34_dialog_content = "那還用說，你可是我的救命恩人！",
  ui_story_2_1_A35_dialog_content = "而且……你的能力對光靈來說意義非凡。",
  ui_story_2_1_A36_dialog_content = "……",
  ui_story_2_1_A37_dialog_content = "我們可以並肩對抗共同的敵人——就像曾經的光靈和空裔一樣！",
  ui_story_2_1_A38_dialog_content = "但在那之前，我們需要加快腳步，去最近的啟光地下城好好休息整備……",
  ui_story_2_1_19_dialog_content = "啊！怎麼了？",
  ui_story_2_1_20_dialog_content = "臨空者，發生了什麼事！？",
  ui_story_2_1_21_dialog_content = "巡航系統偵測到多處損傷，暫時無法修復。",
  ui_story_2_1_22_dialog_content = "十七年來疏於保養，果然撐不了太久……看來我們又要回到地面了。",
  ui_story_2_1_23_dialog_content = "PlayerName，恐怕我只能帶你到這裡了。",
  ui_story_2_1_24_dialog_content = "……",
  ui_story_2_1_25_dialog_content = "無論發生什麼事，都要保護好自己，保護好你的同伴！",
  ui_story_2_1_26_dialog_content = "我相信你……可以成為獨當一面的……強……者。",
  ui_story_2_1_A43_dialog_content = "臨空者，臨空者——！",
  ui_story_2_1_27_dialog_content = "PlayerName！！！",
  ui_story_2_1_28_dialog_content = "準備接受撞擊！！",
  ui_story_2_1_29_dialog_content = "我剛剛感受到一股強烈的光能波動。",
  ui_story_2_1_30_dialog_content = "舒默大人，一切依然在我的掌握之中。",
  ui_story_2_1_A44_dialog_content = "被人從空中甩下來的喪家犬，最好別許下做不到的承諾哦。",
  ui_story_2_1_A45_dialog_content = "……",
  ui_story_2_1_X1_dialog_content = "我承認你比卡拉肯更頑強。但如果無法完成我們給你的命令……",
  ui_story_2_1_X2_dialog_content = "那你也不過是塊廢料，麥格芬。",
  ui_story_2_1_31_dialog_content = "巨像不會成為永久的庇護所，他們正在做無謂的掙扎！",
  ui_story_2_1_32_dialog_content = "很快我就會奉上您期待的結果。",
  ui_story_2_1_33_dialog_content = "珍惜第二次機會。最好在我耐心消失前把事情辦好。",
  ui_story_2_1_35_dialog_content = "如您所願，大人。",
  ui_story_2_1_36_dialog_content = "（日蝕語）巨像……墜落……西方……荒野……",
  ui_story_2_1_37_dialog_content = "（日蝕語）西方，那是<color=#FFB400>黑蹄</color>的族群……回覆我！",
  ui_story_2_1_38_dialog_content = "（日蝕語）我們在。",
  ui_story_2_1_39_dialog_content = "（日蝕語）追上他們、擊潰他們……我稍後就到！",
  ui_story_2_1_40_dialog_content = "（日蝕語）黑蹄遵命，暗鬼出擊！",
  ui_story_2_2_2_dialog_content = "好痛……咦？",
  ui_story_2_2_3_dialog_content = "薇絲，可以從我身上下來嗎……",
  ui_story_2_2_A1_dialog_content = "欸？抱、抱歉……你沒事吧？",
  ui_story_2_2_A2_dialog_content = "至少還活著……",
  ui_story_2_2_4_dialog_content = "已經有暗鬼圍過來了？！這麼快？",
  ui_story_2_2_5_dialog_content = "PlayerName！！快給我指令吧！",
  ui_story_2_2_6_dialog_content = "<color=#e8d9bb>墜落的巨響引來了數隻暗鬼</color>",
  ui_story_2_3_1_dialog_content = "現在情況如何？",
  ui_story_2_3_2_dialog_content = "薇絲中尉，我們監測到大批暗鬼正在逼近，但是我們已經耗盡戰鬥資源。",
  ui_story_2_3_3_dialog_content = "這裡距離哪座地下城比較近？",
  ui_story_2_3_A1_dialog_content = "28號地下城就在不遠處，可以直接前往避難。",
  ui_story_2_3_A2_dialog_content = "薇絲中尉，請下達命令！",
  ui_story_2_3_4_dialog_content = "全體人員，目標28號地下城，全速行進！",
  ui_story_2_3_6_dialog_content = "PlayerName，我們走！",
  ui_story_2_3_7_dialog_content = "別管我了，你們走吧。",
  ui_story_2_3_8_dialog_content = "PlayerName？！",
  ui_story_2_3_A3_dialog_content = "你們趕快撤退吧，再晚就走不了了。",
  ui_story_2_3_A4_dialog_content = "你不和我們一起走嗎？",
  ui_story_2_3_9_dialog_content = "臨空者現在傷痕累累，我不能離開……",
  ui_story_2_3_10_dialog_content = "這十七年來，我能活下來都是因為他，他是我現在唯一的「親人」。",
  ui_story_2_3_A5_dialog_content = "……",
  ui_story_2_3_11_dialog_content = "如果麥格芬說的都是真的……",
  ui_story_2_3_12_dialog_content = "無論如何，我都不會再離開臨空者半步。",
  ui_story_2_3_13_dialog_content = "你一個人在這裡要怎麼對付那些暗鬼？！",
  ui_story_2_3_A6_dialog_content = "那些暗鬼的目標就是我吧？我留下來對大家都好。",
  ui_story_2_3_14_dialog_content = "你……！！",
  ui_story_2_3_15_dialog_content = "我明白了。士兵，你帶著大家前往地下城！",
  ui_story_2_3_A7_dialog_content = "薇絲中尉，那妳怎麼辦……",
  ui_story_2_3_A8_dialog_content = "不要浪費時間，現在立刻出發！",
  ui_story_2_3_A9_dialog_content = "是！",
  ui_story_2_3_A10_dialog_content = "薇絲，妳已經幫我很多了，快和妳的夥伴一起走吧。",
  ui_story_2_3_16_dialog_content = "你也是我的夥伴，我不能讓你一個人送死！",
  ui_story_2_3_17_dialog_content = "妳再不走，就是兩個人一起送死了。",
  ui_story_2_3_18_dialog_content = "PlayerName——！！",
  ui_story_2_3_19_dialog_content = "<anim type=Shake><size=45>吼！！！</size></anim>",
  ui_story_2_3_B3_dialog_content = "薇絲！！",
  ui_story_2_3_B4_dialog_content = "退、退後！先到安全的地方躲起來！",
  ui_story_2_3_B5_dialog_content = "這群傢伙，來得這麼快嗎……",
  ui_story_2_3_B6_option_content = "建立感應",
  ui_story_2_3_B7_dialog_content = "嘎——！！",
  ui_story_2_3_B8_dialog_content = "夥伴就是夥伴！",
  ui_story_2_3_B9_dialog_content = "薇絲……",
  ui_story_2_3_B10_dialog_content = "嘎啊！！",
  ui_story_2_3_22_dialog_content = "唔啊——！",
  ui_story_2_3_A11_dialog_content = "好痛！集中不了注意力……",
  ui_story_2_3_F1_dialog_content = "PlayerName！堅持下去，我馬上過來！",
  ui_story_2_3_B11_dialog_content = "<anim type=Shake><size=45>吼！！！</size></anim>",
  ui_story_2_3_B12_dialog_content = "<color=#e8d9bb>來不及反應，數頭暗鬼再次同時撲向薇絲——</color>",
  ui_story_2_3_B13_dialog_content = "咳啊——",
  ui_story_2_3_B14_dialog_content = "跑，跑……躲起……來……",
  ui_story_2_3_B15_dialog_content = "薇絲？！",
  ui_story_2_3_24_option_content = "建立感應",
  ui_story_2_3_25_dialog_content = "不行，她已經失去意識了……",
  ui_story_2_3_26_dialog_content = "戰鬥……我要想辦法戰鬥，不能就這麼坐著……",
  ui_story_2_3_27_dialog_content = "<color=#e8d9bb>暗鬼們越過失去意識的薇絲，包圍了過來……</color>",
  ui_story_2_3_28_dialog_content = "喂喂喂，拼命可解決不了問題，殺暗鬼可是很看技術的。",
  ui_story_2_3_29_dialog_content = "小的們，開殺啦！",
  ui_story_2_3_30_dialog_content = "<size=45>動起來！！動起來！！</size>",
  ui_story_2_3_31_dialog_content = "遵命老大！",
  ui_story_2_3_32_dialog_content = "小心爆炸！",
  ui_story_2_3_33_dialog_content = "大家嗨起來～",
  ui_story_2_3_34_dialog_content = "大叔讓開，你在這太擋路了！",
  ui_story_2_3_36_dialog_content = "你們是誰！想要幹什麼？",
  ui_story_2_3_37_dialog_content = "呵，看不出來嗎？我們是搶劫的。",
  ui_story_2_3_38_dialog_content = "你的小命可是我們救的，還不快把值錢的東西交出來！",
  ui_story_2_3_F2_dialog_content = "哈哈哈哈哈！",
  ui_story_2_3_39_dialog_content = "自我介紹一下，我叫<color=#FFB400>醒山</color>，是<color=#FFB400>紅油扳手</color>的老大。",
  ui_story_2_3_40_dialog_content = "這位喜歡凹造型的是<color=#FFB400>蕾吉娜</color>。",
  ui_story_2_3_41_dialog_content = "正在玩炸彈的是<color=#FFB400>比比比約恩</color>。",
  ui_story_2_3_42_dialog_content = "她們可是我的左右手。",
  ui_story_2_3_43_dialog_content = "紅油……扳手？搶劫……？你們要幹什麼？不准你們打巨像的主意！",
  ui_story_2_3_44_dialog_content = "你說的是這大傢伙吧？怎麼進不去？那……就直接炸開囉～！",
  ui_story_2_3_45_dialog_content = "小的們！搬東西啦！",
  ui_story_2_3_46_dialog_content = "哦！！！砰砰大姐頭萬歲！！！",
  ui_story_2_3_47_dialog_content = "哈哈哈哈！沒想到居然是座巨像，今天真是出運了哈哈哈！",
  ui_story_2_3_A12_dialog_content = "大家快點拆，拆好了直接運回去！",
  ui_story_2_3_48_dialog_content = "可不能讓煮熟的鴨子飛了！",
  ui_story_2_3_49_dialog_content = "你們不能破壞臨空……巨像！他，還有維生裝置……",
  ui_story_2_3_50_dialog_content = "我的夥伴薇絲，她受傷了，必須使用那些裝置才行……！",
  ui_story_2_3_51_dialog_content = "這個小女生的傷勢看起來可不怎麼樂觀啊。",
  ui_story_2_3_52_dialog_content = "這個制服？啟光的？",
  ui_story_2_3_53_dialog_content = "我們和這些軍爺的關係，可沒你想像的那麼融洽啊……",
  ui_story_2_3_54_dialog_content = "而且巨像現在已經是我們的財產了，想救那個女孩，你得用其他東西來換。",
  ui_story_2_3_55_dialog_content = "不過看你這樣子應該不是有錢人！你那身破爛衣服都多久沒洗了？",
  ui_story_2_3_56_option_content = "我當然有錢，很多錢！",
  ui_story_2_3_57_option_content = "不要招惹我，光靈們！",
  ui_story_2_3_58_dialog_content = "老實跟你們說，最值錢的就是這座巨像！怎麼樣，你們沒見過吧？！",
  ui_story_2_3_59_dialog_content = "哼，誰沒見過巨像啊？不過……跟我們營地裡的比起來，這傢伙確實很完整……",
  ui_story_2_3_60_dialog_content = "沒錯！如果你們再這樣拆下去，巨像就不值錢了！",
  ui_story_2_3_61_dialog_content = "嘖……真難辦！還以為終於可以火力全開了呢！老大，怎麼搞！",
  ui_story_2_3_62_dialog_content = "……",
  ui_story_2_3_63_dialog_content = "這傢伙說的有道理，先停手吧。",
  ui_story_2_3_64_dialog_content = "對對對，快停手！",
  ui_story_2_3_65_dialog_content = "喂，你。過來。",
  ui_story_2_3_66_dialog_content = "說吧，你是什麼人？",
  ui_story_2_3_67_dialog_content = "……",
  ui_story_2_3_68_dialog_content = "不說話我也能猜個八九不離十。你那身衣服只有十七年前的那群人會穿吧。",
  ui_story_2_3_69_dialog_content = "帶著這麼大的傢伙閒逛，虧你能活到今天！",
  ui_story_2_3_70_dialog_content = "你能猜出我的身分……？",
  ui_story_2_3_71_dialog_content = "那件事沒過很久，<color=#FFB400>空裔</color>，我可不健忘。",
  ui_story_2_3_72_dialog_content = "你們不知道我是誰，也不知道亂來會有什麼後果！我可不、不怕你們！",
  ui_story_2_3_73_dialog_content = "……",
  ui_story_2_3_74_dialog_content = "……這傢伙，摔傷腦袋了嗎？",
  ui_story_2_3_75_dialog_content = "真有意思，仗著自己<color=#FFB400>特殊的身分</color>來威脅我們嗎？",
  ui_story_2_3_76_dialog_content = "別搞錯了，我們可是窮凶極惡的強盜哦。",
  ui_story_2_3_77_dialog_content = "……你知道我的身分？",
  ui_story_2_3_78_dialog_content = "拜託，那身衣服，這座巨像，和那副無所適從的表情，猜也能猜個八九不離十。",
  ui_story_2_3_79_dialog_content = "估計能賣個好價錢吧……",
  ui_story_2_3_80_dialog_content = "賣、賣掉？！都是光靈為什麼對待我的方式差那麼多？！",
  ui_story_2_3_81_dialog_content = "別誤會，<color=#FFB400>空裔</color>。你對我們這些流賊來說什麼都不是。",
  ui_story_2_3_82_dialog_content = "空裔？被暗鬼殺光的那個種族嗎？",
  ui_story_2_3_B1_dialog_content = "殺光……",
  ui_story_2_3_B2_dialog_content = "所以，十七年前那場對空谷發動的襲擊，真的沒有其他倖存者了嗎？",
  ui_story_2_3_83_dialog_content = "你們還知不知道什麼細節……",
  ui_story_2_3_84_dialog_content = "抱歉，一夜之間發生的事情，開始和結束的都很快。",
  ui_story_2_3_85_dialog_content = "當年的我也還是個毛頭小子呢，怎麼會知道得那麼清楚？",
  ui_story_2_3_89_dialog_content = "好了，廢話說夠了！空裔也好、巨像也好，現在都是我們的了！",
  ui_story_2_3_90_dialog_content = "那個，薇絲她……",
  ui_story_2_3_91_dialog_content = "早就送到<color=#FFB400>維生裝置</color>裡治療了！我們是強盜，不是殺人犯！",
  ui_story_2_3_92_dialog_content = "為什麼你們會對巨像這麼瞭解……",
  ui_story_2_3_93_dialog_content = "别以為擁有巨像的只有你们空裔。我们紅油扳手也有自己的「<color=#FFB400>野路子</color>」。",
  ui_story_2_3_94_dialog_content = "讓我們看看，到底會不會有人拿錢來贖你們吧——空裔！",
  ui_story_2_4_1_dialog_content = "老大，有一撥暗鬼向我們這邊衝過來了。",
  ui_story_2_4_2_dialog_content = "啊啊，沒完沒了地來呢，這樣下去要怎麼把巨像給拖回去啊？",
  ui_story_2_4_3_dialog_content = "話說回來，PlayerName，你們剛才也是在被暗鬼追殺吧。",
  ui_story_2_4_4_dialog_content = "是……",
  ui_story_2_4_5_dialog_content = "切，還真是招惹了個麻煩",
  ui_story_2_4_6_dialog_content = "小的們，打起精神——有蟲子靠近了！",
  ui_story_2_4_7_dialog_content = "讓我們也感受一下傳聞中空裔的「感應之力」吧？",
  ui_story_2_4_8_dialog_content = "你還需要我指揮嗎……",
  ui_story_2_4_9_dialog_content = "這可是難得的機會！讓我們也開開眼界，看看光之軌跡吧！",
  ui_story_2_4_10_dialog_content = "敵人來了！抄傢伙，可別死了！",
  ui_story_2_8_1_dialog_content = "這種迂迴戰術，似乎不像是巧合啊。",
  ui_story_2_8_2_dialog_content = "暗鬼的腦袋什麼時候開竅了？",
  ui_story_2_8_3_dialog_content = "砰砰，妳覺得呢？",
  ui_story_2_8_4_dialog_content = "不會有高級暗鬼在指揮吧？",
  ui_story_2_8_5_dialog_content = "閉上妳的烏鴉嘴！",
  ui_story_2_8_7_dialog_content = "高級暗鬼……",
  ui_story_2_8_B1_dialog_content = "吼，已經這麼晚了嗎？",
  ui_story_2_8_B2_dialog_content = "老大你終於想起來了！",
  ui_story_2_8_B3_dialog_content = "抱歉抱歉，帶著空裔戰鬥實在太爽了，一時忘了……",
  ui_story_2_8_B4_dialog_content = "大家放下手上的事吧！<color=#FFB400>開飯時間到了</color>！！",
  ui_story_2_8_B5_dialog_content = "<anim type=Shake><size=45>噢噢噢噢噢噢！！放飯啦！</size></anim>",
  ui_story_2_8_SS_dialog_content = "紅油野炊CG",
  ui_story_2_8_B6_dialog_content = "喂！不要擠啦！！要讓老大先盛不知道嗎？！",
  ui_story_2_8_B7_dialog_content = "哈哈哈，你們先吃！留兩桶給我就好了！",
  ui_story_2_8_B8_dialog_content = "這……到底是在幹什麼……",
  ui_story_2_8_B9_dialog_content = "吃飯啊。很奇怪嗎？你長這麼大沒吃過飯？",
  ui_story_2_8_B10_dialog_content = "我的意思是，這也太狂野了……",
  ui_story_2_8_B11_dialog_content = "求生本能啊，PlayerName。可別小看了我們的生命力喔。",
  ui_story_2_8_B12_dialog_content = "能吃、能喝，我們才算活著；活著，也是為了吃得更痛快！",
  ui_story_2_8_B13_dialog_content = "老大，你再和那個空裔扯那些有的沒的，肉就沒了！",
  ui_story_2_8_B14_dialog_content = "我搶了兩根<color=#FFB400>烤蜥蜴串</color>給你！！",
  ui_story_2_8_B15_dialog_content = "這個給空裔吧，我還不餓。",
  ui_story_2_8_B16_dialog_content = "來吧！",
  ui_story_2_8_B17_dialog_content = "……我……我也不餓……",
  ui_story_2_8_B18_dialog_content = "你這小子怎麼總是這副半死不活的樣子？",
  ui_story_2_8_B19_dialog_content = "你不是說你是第一次到外面來嗎。",
  ui_story_2_8_B20_dialog_content = "就不想打滾撒野？",
  ui_story_2_8_B21_dialog_content = "在這裡裝什麼深沉啊！",
  ui_story_2_8_B22_dialog_content = "怎樣，外面的世界沒有地底下好啊？",
  ui_story_2_8_B23_dialog_content = "欸？",
  ui_story_2_8_B24_dialog_content = "老子不在乎你經歷過什麼。但是現在，你、巨像、還有那個小姑娘，不都好好的嗎？",
  ui_story_2_8_B25_dialog_content = "要不是看你這個空裔還有點用，哪有你的飯吃？",
  ui_story_2_8_B26_dialog_content = "在這世界上，沒人活著是輕鬆的。但你要是想不開，就是蠢貨一個。",
  ui_story_2_8_B27_dialog_content = "要蠢貨有什麼用，不如殺了吧？帶著只是麻煩。",
  ui_story_2_8_B28_dialog_content = "你殺了我只會更麻煩。啟……啟光不會放過你的！",
  ui_story_2_8_B29_dialog_content = "哈哈哈哈哈哈哈！",
  ui_story_2_8_B30_dialog_content = "有什麼好笑的？",
  ui_story_2_8_B33_dialog_content = "看來還不是個蠢貨，那就行！",
  ui_story_2_8_8_dialog_content = "找到了！空裔！",
  ui_story_2_8_9_dialog_content = "是<color=#FFB400>黑蹄</color>？！",
  ui_story_2_8_B34_dialog_content = "暗鬼！真的是衝著我來的？！",
  ui_story_2_8_B35_dialog_content = "放下碗筷，給老子把陣型擺開，準備戰鬥！",
  ui_story_2_8_10_dialog_content = "怎麼能在別人吃飯的時候打過來呢？哼，不像話。",
  ui_story_2_8_B36_dialog_content = "看來，我得好好教教你，什麼是基本的禮貌了！",
  ui_story_2_8_11_dialog_content = "比想像的還要艱難呢……",
  ui_story_2_8_12_dialog_content = "這輛<color=#FFB400>火車</color>……",
  ui_story_2_8_13_dialog_content = "該不會是<color=#FFB400>那個傢伙</color>吧……",
  ui_story_2_8_14_dialog_content = "真狼狽啊，醒山。",
  ui_story_2_8_15_dialog_content = "你在跟暗鬼扮家家酒嗎？",
  ui_story_2_8_16_dialog_content = "我就知道是你，這位軍爺，我最近可沒搶你的軍糧。",
  ui_story_2_8_17_dialog_content = "在下來接啟光的同伴回去，軍糧的事情下次再找你算帳。",
  ui_story_2_8_18_dialog_content = "哦？那個小女生？",
  ui_story_2_8_19_dialog_content = "真巧，我不久前還在考慮把她送回去呢。",
  ui_story_2_8_20_dialog_content = "不只是她，這座巨像也是<color=#FFB400>啟光聯邦</color>的財產。",
  ui_story_2_8_21_dialog_content = "別得寸進尺啊，白毛的傢伙！",
  ui_story_2_8_22_dialog_content = "小心我炸了你的車廂。",
  ui_story_2_8_23_dialog_content = "別衝動，砰砰！",
  ui_story_2_8_24_dialog_content = "這個傢伙可是比剛才那個黑蹄還難纏的對手。",
  ui_story_2_8_25_dialog_content = "巨像而已，又不能拆又不能賣，對我們沒那麼重要。",
  ui_story_2_8_26_dialog_content = "哼！便宜你了！",
  ui_story_2_8_B37_dialog_content = "卡戎，你可得好好珍惜那個大傢伙和這個小傢伙。",
  ui_story_2_8_B38_dialog_content = "PlayerName比我想的還要有趣呢。",
  ui_story_2_8_B39_dialog_content = "欸？",
  ui_story_2_8_B40_dialog_content = "唉，可惜！好不容易遇到一個稀罕的寶貝。",
  ui_story_2_8_B41_dialog_content = "PlayerName，雖然你一點都不陽光……",
  ui_story_2_8_B42_dialog_content = "但還是充滿光的氣息呢。",
  ui_story_2_8_B43_dialog_content = "光的氣息？可是我並不會使用光之力……",
  ui_story_2_8_B44_dialog_content = "嘖，那是個比喻！",
  ui_story_2_8_B48_dialog_content = "感覺上了年紀的人，說話都一樣晦澀難懂。",
  ui_story_2_8_B49_dialog_content = "哈哈哈，開始損我了。看來你狀態稍微好一點了嘛。",
  ui_story_2_8_B50_dialog_content = "記住，空裔，死很容易，但是你既然活著，就給我好好活著！",
  ui_story_2_8_B51_dialog_content = "「<color=#FFB400>希望</color>」這東西，要找總是能找到的。",
  ui_story_2_8_B52_dialog_content = "不管是在白晝，還是在黑夜……",
  ui_story_2_8_B53_dialog_content = "從哪裡抄來的話術？",
  ui_story_2_8_B54_dialog_content = "嗯……忘記從哪看來的了。",
  ui_story_2_8_B55_dialog_content = "幾天不見，開始讀書了嘛。",
  ui_story_2_8_B56_dialog_content = "哈哈哈哈，軍爺可別小看我們這些頑強生活的遊民啊！再會了，各位！",
  ui_story_2_8_28_dialog_content = "我有種直覺，以後我們還會再見的……",
  ui_story_2_8_29_dialog_content = "紅油扳手，回家囉！今晚搞點沙蟲來犒賞犒賞大家吧！",
  ui_story_2_8_31_dialog_content = "……你就不能帶點好消息回來嗎，麥格芬？",
  ui_story_2_8_32_dialog_content = "啟光的增援抵達了，是位名叫<color=#FFB400>卡戎</color>的光靈……",
  ui_story_2_8_33_dialog_content = "卡戎？真是個讓人懷念的名字。",
  ui_story_2_8_34_dialog_content = "這麼說來，空裔也被帶走了？",
  ui_story_2_8_35_dialog_content = "他們已前往<color=#FFB400>28號地下城</color>。",
  ui_story_2_8_36_dialog_content = "至少黑蹄已探明目標位置，你知道接下來該怎麼做。",
  ui_story_2_8_37_dialog_content = "遵命！",
  ui_story_2_8_38_dialog_content = "光靈的地下城……",
  ui_story_2_8_39_dialog_content = "這群鼠輩，竟以為躲進洞穴裡就能高枕無憂了？",
  ui_story_2_8_40_dialog_content = "儘管後悔吧，懦夫……既然躲進那種地方——",
  ui_story_2_8_41_dialog_content = "那就準備讓所有人跟你一起陪葬吧！",
  ui_story_2_9_1_dialog_content = "你是誰？",
  ui_story_2_9_2_dialog_content = "在下是<color=#FFB400>28號後勤地下城</color>的主管。",
  ui_story_2_9_3_dialog_content = "你可以稱呼在下為卡戎。",
  ui_story_2_9_4_dialog_content = "薇絲在哪裡？",
  ui_story_2_9_5_dialog_content = "在巨像的維生裝置裡。她受傷了，我……我沒有保護好她。",
  ui_story_2_9_6_dialog_content = "你是薇絲的……？",
  ui_story_2_9_7_dialog_content = "薇絲曾向在下報備過她這次的探索行動。",
  ui_story_2_9_8_dialog_content = "後來在下看到巨像的求救訊號，一路上跟著暗鬼就找到你們了。",
  ui_story_2_9_9_dialog_content = "薇絲情況怎麼樣？",
  ui_story_2_9_10_dialog_content = "傷勢已經用巨像的維生裝置穩定住了。",
  ui_story_2_9_11_dialog_content = "接下來要怎麼辦？",
  ui_story_2_9_12_dialog_content = "你的問題真的很多。先跟在下回28號地下城吧。",
  ui_story_2_9_13_dialog_content = "卡戎長官回來了！",
  ui_story_2_9_14_dialog_content = "哇！好大，帶回來什麼了？",
  ui_story_2_9_15_dialog_content = "快通知交通班開放卡戎長官的專用鐵路。",
  ui_story_2_9_17_dialog_content = "卡戎長官，歡迎回來。",
  ui_story_2_9_18_dialog_content = "這是……巨像？！",
  ui_story_2_9_19_dialog_content = "嗯，巨像裡有傷患，通知治療班。",
  ui_story_2_9_20_dialog_content = "另外，還有一支啟光小隊……犧牲了。",
  ui_story_2_9_21_dialog_content = "是！我立刻安排善後工作，並調配候補隊員。",
  ui_story_2_9_22_dialog_content = "嗯，辛苦了。",
  ui_story_2_9_23_dialog_content = "前線情況如何？",
  ui_story_2_9_24_dialog_content = "沒有異常！",
  ui_story_2_9_25_dialog_content = "奇怪了，規模這麼大的暗鬼是怎麼越過前線的？",
  ui_story_2_9_26_dialog_content = "通知通訊班，轉接<color=#FFB400>迦南總部</color>，在下稍後要和總部通話。",
  ui_story_2_9_B1_dialog_content = "……",
  ui_story_2_9_B2_dialog_content = "怎麼？沒有見過如此龐大的地下空間和社會組織嗎？",
  ui_story_2_9_B3_dialog_content = "這裡……就是啟光嗎。",
  ui_story_2_9_B4_dialog_content = "這裡只是啟光聯邦的其中一座地下城而已，編號二十八。",
  ui_story_2_9_B5_dialog_content = "28號地下城雖然不是對抗暗鬼的最前線，但也是非常重要的後勤基地。",
  ui_story_2_9_F1_dialog_content = "如果這裡失守，暗鬼就能突破我們的防線，直接撲向……",
  ui_story_2_9_B6_dialog_content = "對了，空裔，你學過地理嗎？",
  ui_story_2_9_F2_dialog_content = "我……我還是學過一點的。如果暗鬼突破防線，就會直接突破整個大陸的腹地，對嗎？",
  ui_story_2_9_B7_dialog_content = "不錯！一面永晝，一面永夜，大陸是我們唯一的生存地區，我們沒有任何撤退的餘地。",
  ui_story_2_9_B8_dialog_content = "我們啟光人生來就要和暗鬼戰鬥，這既是我們的宿命，也是我們的使命。",
  ui_story_2_9_B9_dialog_content = "我們要保護我們珍貴的家園。",
  ui_story_2_9_B10_dialog_content = "家園……你是指光靈的土地嗎？",
  ui_story_2_9_B11_dialog_content = "準確來說，是所有<color=#FFB400>心愛之物</color>所在的地方。",
  ui_story_2_9_B13_dialog_content = "也許是光靈，也許是遺跡，也許是「無足輕重」的一段回憶。",
  ui_story_2_9_B14_dialog_content = "意外的……很浪漫呢。",
  ui_story_2_9_B15_dialog_content = "浪漫嗎？在下卻認為這是讓我們活下去最現實的動力。",
  ui_story_2_9_B16_dialog_content = "換句話說，就是「<color=#FFB400>希望</color>」！",
  ui_story_2_9_B17_dialog_content = "如果絕望無法改變，那就用希望去填滿永恆的黑夜。",
  ui_story_2_9_B18_dialog_content = "嗯，意外地作出一首好詩。",
  ui_story_2_9_B19_dialog_content = "……和醒山說過的，好像。",
  ui_story_2_9_B20_dialog_content = "看你不太有精神的樣子？你接下來打算做什麼？休息？",
  ui_story_2_9_B21_dialog_content = "還是去找你其他的夥伴？",
  ui_story_2_9_B22_dialog_content = "夥伴……？我不知道我的同胞……",
  ui_story_2_9_B23_dialog_content = "在下說的是那些光靈。她們不是你的同伴嗎？",
  ui_story_2_9_B24_dialog_content = "啊……是、是的。她們的確幫了我很多……",
  ui_story_2_9_B25_dialog_content = "我可能需要整理一下思緒。今天對我來說，有點過於刺激了……",
  ui_story_2_9_B26_dialog_content = "嗯。那你自己待著吧。在下還得處理日常匯報，就不奉陪了。",
  ui_story_2_9_B27_dialog_content = "態度突然變得好冷……？",
  ui_story_2_9_B28_dialog_content = "再浪漫的詩人，也是要背負工作責任的。",
  ui_story_2_9_B30_dialog_content = "另外，請不要過分自責。",
  ui_story_2_9_B31_dialog_content = "那些啟光士兵們的死，是源於使命，並不光是為了你。",
  ui_story_2_9_27_dialog_content = "希望這能讓你好受點。",
  ui_story_2_9_28_dialog_content = "……",
  ui_story_2_9_29_dialog_content = "空……空裔？我可以直接這樣叫你嗎？休息室在這邊。",
  ui_story_2_9_30_dialog_content = "跟我來吧，雖然是第一次見面，但卡戎長官帶回來的人應該沒問題。",
  ui_story_2_9_32_dialog_content = "歡迎來到28號地下城。",
  ui_story_2_9_33_dialog_content = "28號地下城呼叫迦南，這裡是卡戎，有重要情況需要回報。",
  ui_story_2_9_34_dialog_content = "迦南收到，我是<color=#FFB400>緋</color>。",
  ui_story_2_9_35_dialog_content = "口令。",
  ui_story_2_9_36_dialog_content = "<color=#FFB400>「火車俠超帥」</color>。",
  ui_story_2_9_37_dialog_content = "緋，今天是妳值班啊。",
  ui_story_2_9_38_dialog_content = "回令。",
  ui_story_2_9_39_dialog_content = "<color=#FFB400>「櫻花綻放」</color>……",
  ui_story_2_9_41_dialog_content = "薇絲的任務進度如何？",
  ui_story_2_9_42_dialog_content = "在下正要說這件事。",
  ui_story_2_9_43_dialog_content = "巨像找到了，已經帶回28號地下城。",
  ui_story_2_9_44_dialog_content = "薇絲受了傷，正在接受治療。",
  ui_story_2_9_45_dialog_content = "受傷？她的傷勢嚴重嗎？",
  ui_story_2_9_46_dialog_content = "別著急，薇絲並無大礙。",
  ui_story_2_9_47_dialog_content = "卡戎，作為她的臨時長官，你應該為此負責。",
  ui_story_2_9_48_dialog_content = "告訴我發生了什麼事。",
  ui_story_2_9_49_dialog_content = "薇絲的猜測是對的。",
  ui_story_2_9_50_dialog_content = "十七年前從空谷離開的巨像中，確實有一座墜落在28號地下城附近。",
  ui_story_2_9_51_dialog_content = "薇絲她們遇到不少暗鬼，那些暗鬼似乎在追蹤這座巨像。",
  ui_story_2_9_52_dialog_content = "薇絲發現巨像後沒向你們請求支援嗎？",
  ui_story_2_9_F3_dialog_content = "在下看到求救訊號，但可能去的……",
  ui_story_2_9_53_dialog_content = "你去晚了？",
  ui_story_2_9_54_dialog_content = "緋，請聽在下把話說完，這次的情況很複雜。",
  ui_story_2_9_55_dialog_content = "那座巨像被埋在地下。但你一定想不到，巨像裡還有一個活著的空裔。",
  ui_story_2_9_57_dialog_content = "空裔？",
  ui_story_2_9_58_dialog_content = "你的意思是，這個空裔在地下生活了十七年……",
  ui_story_2_9_60_dialog_content = "然後呢？",
  ui_story_2_9_61_dialog_content = "當時薇絲透過巨像發射求救訊號。",
  ui_story_2_9_62_dialog_content = "在下立即出發，趕到時在那看到大量暗鬼的痕跡。",
  ui_story_2_9_63_dialog_content = "後來從空裔那邊得知，與他們交戰的有卡拉肯、麥格芬和黑蹄。",
  ui_story_2_9_64_dialog_content = "三隻高級暗鬼？",
  ui_story_2_9_65_dialog_content = "他們越過啟光的防線，甚至潛到28號地下城附近？",
  ui_story_2_9_66_dialog_content = "只有卡拉肯有能力穿行在防線下方，其他的暗鬼做不到。",
  ui_story_2_9_67_dialog_content = "而且還有數量龐大的普通暗鬼緊隨在後。",
  ui_story_2_9_68_dialog_content = "他們就像從天而降一樣，找不到來時的痕跡。彷彿十七年前的空谷重演。",
  ui_story_2_9_69_dialog_content = "也就是說暗鬼已經掌握越過防線的手段？",
  ui_story_2_9_70_dialog_content = "恐怕是這樣沒錯……",
  ui_story_2_9_71_dialog_content = "另外，麥格芬也許還活著，這是個隱患。",
  ui_story_2_9_72_dialog_content = "好，我馬上通知大元帥。",
  ui_story_2_9_73_dialog_content = "你們做好防備。",
  ui_story_2_9_74_dialog_content = "28號地下城是前線的重要補給站，那裡的物資……",
  ui_story_2_9_75_dialog_content = "緋，在下知道該怎麼做。",
  ui_story_2_9_76_dialog_content = "<color=#e8d9bb>數日後·巨像維修場</color>",
  ui_story_2_9_77_dialog_content = "你果然在這裡。",
  ui_story_2_9_78_dialog_content = "薇絲？！妳的傷，已經可以活動了​​嗎？！",
  ui_story_2_9_79_dialog_content = "別小看啟光的醫療水準啊。",
  ui_story_2_9_80_dialog_content = "臨空者號怎麼樣了？",
  ui_story_2_9_81_dialog_content = "已經沒問題了，啟光的科技太令人驚訝了，短短幾天就把損壞的部件都修好了。",
  ui_story_2_9_82_dialog_content = "現在工人們正在處理最後的鍍層作業，我倒覺得有點過分追求完美了。",
  ui_story_2_9_83_dialog_content = "如果能把那個顯眼的啟光標誌擦掉就更好了……",
  ui_story_2_9_84_dialog_content = "沒想到啟光的科技人員還有這種實力……替我向薇絲道謝。",
  ui_story_2_9_87_dialog_content = "這是當然的啦，啟光的科學班一向是精益求精的。",
  ui_story_2_9_88_dialog_content = "你看我的制服跟武器，都是科學班的傑作，這些可是我們作戰的基礎。",
  ui_story_2_9_89_dialog_content = "這就是「工程化」的光能力配置，能調節和激發光靈自身的力量。",
  ui_story_2_9_90_dialog_content = "這種方式的運用效率和術式發動速度，是「儀式化」所沒有的優勢。",
  ui_story_2_9_91_dialog_content = "但與儀式化比起來威力小很多，不過比較適合我們群體作戰的風格。",
  ui_story_2_9_A1_dialog_content = "……",
  ui_story_2_9_A2_dialog_content = "……",
  ui_story_2_9_A3_dialog_content = "啊，是有哪裡沒聽懂嗎？",
  ui_story_2_9_A4_dialog_content = "……嗯，差不多全都沒聽懂。",
  ui_story_2_9_A5_dialog_content = "欸？全部嗎？啊抱歉，我忘了你對這些還不太瞭解……",
  ui_story_2_9_A6_dialog_content = "嗯……比起聊這些……",
  ui_story_2_9_A7_dialog_content = "薇絲，我們墜落以後……那個時候……",
  ui_story_2_9_98_dialog_content = "我好像說了一些……唔……",
  ui_story_2_9_99_dialog_content = "總之——對不起！",
  ui_story_2_9_100_dialog_content = "欸？為什麼突然道歉？",
  ui_story_2_9_101_dialog_content = "之前我自顧自地說了很多話，又害妳受傷。這幾天總做噩夢……",
  ui_story_2_9_102_dialog_content = "哦，你說這個啊，完全不用道歉啦！",
  ui_story_2_9_103_dialog_content = "那個時候，我沒有體會到你和臨空者的羈絆……貿然提議是我不對。",
  ui_story_2_9_104_dialog_content = "一想到你要留在那裡，還要一個人面對暗鬼，我就很著急。",
  ui_story_2_9_105_dialog_content = "總之，現在沒事就好！",
  ui_story_2_9_107_dialog_content = "以後也請多關照啦，PlayerName。",
  ui_story_2_9_108_dialog_content = "嗯！",
  ui_story_2_9_109_dialog_content = "<color=#e8d9bb>轟隆隆——</color>",
  ui_story_2_9_110_dialog_content = "<color=#e8d9bb>震動更加強烈了，似乎是從腳底傳來。</color>",
  ui_story_2_9X_1_dialog_content = "<color=#e8d9bb>一陣微妙的震動傳來。</color>",
  ui_story_2_9X_2_dialog_content = "<color=#e8d9bb>震動更加強烈了，似乎是從腳底傳來。</color>",
  ui_story_2_9X_3_dialog_content = "有點不對勁……",
  ui_story_2_9X_4_dialog_content = "……什麼東西在震？是臨空者號嗎？",
  ui_story_2_9X_5_dialog_content = "絕對不是，讓我感應一下看看。",
  ui_story_2_9X_6_dialog_content = "<color=#e8d9bb>匡——匡——轟！</color>",
  ui_story_2_9X_7_dialog_content = "這個警報……防禦網出現漏洞？！怎麼可能！明明餘量都是百分之百，到底是從哪裡來的……？",
  ui_story_2_9X_8_dialog_content = "薇絲！防禦……漏洞……遭受攻擊！！你們……",
  ui_story_2_9X_9_dialog_content = "什麼意思？卡戎長官，我聽不清楚！",
  ui_story_2_9X_19_dialog_content = "薇絲！我感應到暗鬼了！",
  ui_story_2_9X_20_dialog_content = "暗鬼？在地下城？！怎麼可能！",
  ui_story_2_9X_21_dialog_content = "三隻……十隻……還在增加，薇絲，暗鬼正在不斷增加！！",
  ui_story_2_9X_22_dialog_content = "剛才的震動絕不簡單！說不定這座地下城已經……",
  ui_story_2_9X_23_dialog_content = "那就往源頭走！如果真的是暗鬼入侵，必須及時把牠們攔在居民區之外！！",
  ui_story_2_9X_24_dialog_content = "準備作戰，PlayerName！",
  ui_story_2_9X_25_dialog_content = "交給我吧！",
  ui_story_2_9X_26_dialog_content = "去吧……殺吧……將一切所見撕成碎片……",
  ui_story_2_9X_27_dialog_content = "不能再次失敗……必須用光靈的血肉洗刷失敗的屈辱！",
  ui_story_2_9X_28_dialog_content = "<size=45>給我屠光這座地下城！！</size>",
  ui_story_2_10_19_dialog_content = "薇絲、PlayerName！",
  ui_story_2_10_20_dialog_content = "卡戎長官，你沒事吧？",
  ui_story_2_10_21_dialog_content = "薇絲？ ？",
  ui_story_2_10_22_dialog_content = "<color=#FFB400>地下城的防禦網被突破了</color>……直接攻破壁壘，簡直前所未聞！",
  ui_story_2_10_23_dialog_content = "而且為什麼會發動襲擊？還這麼有組織地襲擊地下城的弱點？",
  ui_story_2_10_24_dialog_content = "不可能，絕對事有蹊蹺！這麼多年來，地下城從未出現過這種情況！",
  ui_story_2_10_25_dialog_content = "所以現在怎麼應對？！我們還有多少人能戰鬥，先集結到豁口處！",
  ui_story_2_10_26_dialog_content = "啟動撤離備案吧。已經有大量暗鬼趁虛而入了，按照啟光規章，這已經是S級威脅，\n必須棄城。",
  ui_story_2_10_27_dialog_content = "……對不起，沒能料到……",
  ui_story_2_10_28_dialog_content = "打起精神，薇絲。一起疏散傷患和民眾！",
  ui_story_2_10_29_option_content = "情況已經這麼危急了嗎？！",
  ui_story_2_10_30_option_content = "沒有反擊的可能嗎……",
  ui_story_2_10_31_dialog_content = "你看看四周！ 28號地下城不是戰鬥前線，這裡都是傷患和負責後勤的士兵！",
  ui_story_2_10_32_dialog_content = "節省力氣，先前往其它地下城避難才是上策！",
  ui_story_2_10_33_dialog_content = "現在情況怎麼樣了？",
  ui_story_2_10_34_dialog_content = "全都是暗鬼，而且似乎有高級暗鬼……無論如何，我們不能待在這裡！",
  ui_story_2_10_A1_dialog_content = "是麥格芬……",
  ui_story_2_10_35_dialog_content = "再過不久，這座地下城就會變成充滿暗鬼的巢穴……",
  ui_story_2_10_36_dialog_content = "瞭解！PlayerName，我們需要你的指引，一起疏散大家吧！",
  ui_story_2_10_40_dialog_content = "好的，絕不會拋棄任何一個人！",
  ui_story_2_10_41_dialog_content = "是的，在下也不會拋棄任何一個同胞！一定要完成華麗的撤離！！",
  ui_story_2_10_42_dialog_content = "走吧，事不宜遲！",
  ui_story_2_10_43_dialog_content = "就是這樣！！不要讓光靈有喘息的機會！！如果發現了巨像和空裔的位置——",
  ui_story_2_10_44_dialog_content = "<size=45>馬上告訴我！</size>",
  ui_story_2_12_3_dialog_content = "骯髒、噁心的生物、就應該、在陰影裡、好好待著！！",
  ui_story_2_12_4_dialog_content = "為什麼要弄壞這華麗的地下城啊？！！太反常了！！",
  ui_story_2_12_5_dialog_content = "唔嘎——！",
  ui_story_2_12_6_dialog_content = "在下聽不懂！！",
  ui_story_2_12_7_dialog_content = "這樣下去，暗鬼會比我們先抵達居民區！",
  ui_story_2_12_8_dialog_content = "卡戎長官，你的火車呢？我們不能用那個前進嗎？",
  ui_story_2_12_9_dialog_content = "這裡可沒有能讓彼岸號行駛的鐵路。",
  ui_story_2_12_10_dialog_content = "如果把那東西召喚出來的話，別說救人，大家能留全屍就不錯了。",
  ui_story_2_12_11_dialog_content = "不到最後關頭……",
  ui_story_2_12_12_dialog_content = "這些真的是我見過的那種暗鬼嗎？為什麼這麼……有組織、有目的？",
  ui_story_2_12_13_dialog_content = "<color=#FFB400>就好像是在衝著什麼……</color>",
  ui_story_2_12_14_dialog_content = "……",
  ui_story_2_12_15_dialog_content = "啊，原來目標就是空裔嗎？我還真是接了個燙手山芋……",
  ui_story_2_12_16_dialog_content = "<color=#e8d9bb>地下城再次瘋狂震動起來。</color>",
  ui_story_2_12_17_dialog_content = "雖然不想承認，但我們似乎被逼入絕境了？",
  ui_story_2_12_18_dialog_content = "還有一線希望，我們的王牌還沒打出來！",
  ui_story_2_12_19_dialog_content = "PlayerName，你指的是……",
  ui_story_2_12_20_dialog_content = "<color=#FFB400>臨空者號</color>！",
  ui_story_2_12_24_dialog_content = "就像我和PlayerName之前做的那樣！",
  ui_story_2_12_25_dialog_content = "那傢伙還在充能，而且很可能還沒充好。",
  ui_story_2_12_26_dialog_content = "那也必須試試看，不是嗎？剛好他也可以載著所有人逃離這裡……",
  ui_story_2_12_X26_dialog_content = "走吧，現在只能把我們的命運交給臨空者號了。",
  ui_story_2_12_27_dialog_content = "我早已習慣這樣的「臨危受命」，但最好加快速度。",
  ui_story_2_12_X27_dialog_content = "因為已經有暗鬼的氣息，逼近這裡了……",
  ui_story_2_12_28_dialog_content = "現在也沒其他辦法了，在下去安排群眾登上巨像。",
  ui_story_2_12_29_dialog_content = "那我們先走一步！去啟動巨像！",
  ui_story_2_13_1_dialog_content = "<color=#e8d9bb>地下停泊港·巨像臨空者號處</color>",
  ui_story_2_13_2_dialog_content = "愈來愈多了……",
  ui_story_2_13_3_dialog_content = "呼……唔咕…………",
  ui_story_2_13_4_dialog_content = "果然！巨像這裡也開始有暗鬼聚集了！",
  ui_story_2_13_5_dialog_content = "唔……",
  ui_story_2_13_6_dialog_content = "牠在……發出訊號？難道是在和遠處的同類溝通……？",
  ui_story_2_13_7_dialog_content = "不管了！大家先都進到巨像裡，讓傷者跟小孩先走！我們這邊會掩護你們！",
  ui_story_2_13_8_dialog_content = "看來用不著火車了呢……在下本來以為今天會有一場華麗的謝幕。",
  ui_story_2_13_9_dialog_content = "就勉強拿這個東西來過過癮吧。",
  ui_story_2_13_10_dialog_content = "你為什麼拿出一個……遙控器？",
  ui_story_2_13_11_dialog_content = "……<color=#FFB400>紅鍵</color>？你什麼時候……",
  ui_story_2_13_12_dialog_content = "S級撤離的標準流程吧，銷毀所有痕跡。到時候的煙火會十分華麗哦。",
  ui_story_2_13_13_dialog_content = "不過還真有點捨不得這座地下城……說起來，已經住了好多年了呢。",
  ui_story_2_13_14_dialog_content = "「28號地下城主管」……哈，最後卻沒守住這座城，算是晚節不保嗎？",
  ui_story_2_13_15_dialog_content = "對不起……",
  ui_story_2_13_16_dialog_content = "為什麼要道歉？難道是你們故意把暗鬼放進來的？",
  ui_story_2_13_17_dialog_content = "不是的！",
  ui_story_2_13_18_dialog_content = "冷靜，中尉……在下只是開玩笑而已。",
  ui_story_2_13_19_dialog_content = "只能說，28號地下城的命數已盡，怪不了任何人。",
  ui_story_2_13_20_dialog_content = "也許……萬事萬物，都會有終結吧……",
  ui_story_2_13_21_dialog_content = "就像永晝與永夜，也必有終結的那天呢……嗯，無意間作出一首好詩！",
  ui_story_2_13_22_dialog_content = "還不趕快上去，愣著幹嘛？到時候按下紅鍵炸死誰，在下可不管的喔～",
  ui_story_2_13_23_dialog_content = "中尉！暗鬼、暗鬼群又來了！後面還有傷員……",
  ui_story_2_13_24_dialog_content = "瞭解！我們會拖住的，剩下的人加快腳步啊！！",
  ui_story_2_13_25_dialog_content = "看來謝幕時刻還沒到呢，先把紅鍵收起來吧……",
  ui_story_2_14_1_dialog_content = "終於——進來了！各位，有受傷嗎？",
  ui_story_2_14_2_dialog_content = "我們在清點人數！應該齊了，卡戎長官呢？",
  ui_story_2_14_3_dialog_content = "卡戎長官？他在另一個位置掩護巨像登入口……",
  ui_story_2_14_4_dialog_content = "抱歉久等了，中尉！沒有剩下的人了吧？！暗鬼已經多到沒地方容身了！！",
  ui_story_2_14_5_dialog_content = "多謝你們！帶來這樣的麻煩真是非常——",
  ui_story_2_14_6_dialog_content = "中尉，請不要說這種話！先帶大家離開吧，我們走！",
  ui_story_2_14_7_dialog_content = "等等，人還沒齊！卡戎長官在哪？",
  ui_story_2_14_8_dialog_content = "卡戎長官？我剛看到他在掩護幾個落後的傷員，好像是……",
  ui_story_2_14_9_dialog_content = "看到了！在那邊！",
  ui_story_2_14_10_dialog_content = "該死，這些傢伙弄髒我的衣服……",
  ui_story_2_14_11_dialog_content = "那傢伙還在孤軍奮戰呢，整個地下城的暗鬼都圍過來了！",
  ui_story_2_14_12_dialog_content = "這個進攻路線已經很明顯了，那些東西的目標是我！",
  ui_story_2_14_13_dialog_content = "快上來！",
  ui_story_2_14_14_dialog_content = "在下、也想啊——！但這群、王八蛋、讓人太、火、大、了！！",
  ui_story_2_14_15_dialog_content = "至少、絕不能讓牠們接近你們！！",
  ui_story_2_14_16_dialog_content = "不行，我得去支援他……PlayerName，跟我來！其他人待在原地！！",
  ui_story_2_14_17_dialog_content = "嘎——？！",
  ui_story_2_14_18_dialog_content = "太多了！連前進都……做不到！",
  ui_story_2_14_19_dialog_content = "再不啟動，我們也得一起陪葬！現在不是猶豫不決的時候了！",
  ui_story_2_14_20_option_content = "薇絲，我們必須走了",
  ui_story_2_14_21_dialog_content = "不行！我們說好不拋下任何一個人的！",
  ui_story_2_14_22_dialog_content = "薇絲！PlayerName說得對，我們必須盡快離開了！",
  ui_story_2_14_23_dialog_content = "卡戎他救過你！不，他對我們所有人都有恩……這不是啟光的報答方式！",
  ui_story_2_14_24_dialog_content = "但我們也絕對不能拿這裡所有居民的生命冒險！",
  ui_story_2_14_25_dialog_content = "我知道……我當然知道這些道理……可惡，為什麼會變成這樣？！",
  ui_story_2_14_26_option_content = "不行，必須拯救卡戎",
  ui_story_2_14_27_dialog_content = "你想清楚了嗎，PlayerName？",
  ui_story_2_14_28_dialog_content = "這座地下城的所有居民都在這裡！你想清楚失敗的代價了嗎？",
  ui_story_2_14_29_dialog_content = "我相信我們可以做到！",
  ui_story_2_14_31_dialog_content = "你這份勇往直前的自信，或許能創造奇蹟吧。",
  ui_story_2_14_32_dialog_content = "這也是你與別人最不同的地方，PlayerName……",
  ui_story_2_15_1_dialog_content = "卡戎長官！",
  ui_story_2_15_X1_dialog_content = "嘎啊——！",
  ui_story_2_15_F1_dialog_content = "可惡，完全無法靠近……",
  ui_story_2_15_X2_dialog_content = "薇絲！別做蠢事！",
  ui_story_2_15_X3_dialog_content = "你們這群髒東西，不可饒恕！讓在下給你們一點顏色瞧瞧吧！",
  ui_story_2_15_X4_dialog_content = "<color=#e8d9bb>咻——！</color>",
  ui_story_2_15_A1_dialog_content = "卡戎長官，你在做什麼？！訊號彈只會吸引更多暗鬼！",
  ui_story_2_15_X6_dialog_content = "中尉，你們還在等什麼？！真是幼稚！不要自作主張地給在下添麻煩！",
  ui_story_2_15_2_dialog_content = "在下、冥河列車·卡戎，榮譽與相貌兼具，光榮使命不容妨礙！",
  ui_story_2_15_3_dialog_content = "難道，你是……故意的？！",
  ui_story_2_15_4_dialog_content = "PlayerName，快出發吧，不要如此留戀在下華麗的身姿！！",
  ui_story_2_15_5_dialog_content = "卡戎長官，這個時候請別說場面話了！！你不登船，我們是絕不會……",
  ui_story_2_15_A2_dialog_content = "放心！這種程度的敵人絕對奈何不了在下，妳是知道的，薇絲！",
  ui_story_2_15_A3_dialog_content = "你們在這裡反而礙手礙腳！！甚至會害死我冥河列車·暗鬼屠殺者·卡戎！！",
  ui_story_2_15_A4_dialog_content = "卡戎……",
  ui_story_2_15_A5_dialog_content = "中尉，快登船帶大家離開！這是命令！稍後我自有辦法追上你們。",
  ui_story_2_15_A6_dialog_content = "……遵命。PlayerName，準備啟動……",
  ui_story_2_15_A7_dialog_content = "啟動成功……",
  ui_story_2_15_A8_dialog_content = "臨空者，不要鎖死登入口，卡戎可能會隨時趕來！",
  ui_story_2_15_A9_dialog_content = "PlayerName，你真的確定嗎？",
  ui_story_2_15_A10_dialog_content = "……什麼意思？",
  ui_story_2_15_A11_dialog_content = "卡戎他……一點都不像是要「趕來」的樣子。",
  ui_story_2_15_A12_dialog_content = "相反，他正往暗鬼群的深處走去……",
  ui_story_2_15_A13_dialog_content = "什麼？！卡戎他……",
  ui_story_2_15_6_dialog_content = "這、這個警報聲是？！",
  ui_story_2_15_7_dialog_content = "中尉！那是自毀程式，長官按下紅鍵了！！",
  ui_story_2_15_8_dialog_content = "那種事情我當然知道！",
  ui_story_2_15_A14_dialog_content = "卡戎……從一開始你就是這麼打算的嗎……！",
  ui_story_2_15_9_dialog_content = "已清空引擎噴口，我會記住那位光靈的！坐穩了！",
  ui_story_2_15_10_option_content = "出發！",
  ui_story_2_15_13_dialog_content = "艙體破裂！白色巨翼<color=#FFB400>掛到什麼東西？這個重量不太對……</color>",
  ui_story_2_15_14_dialog_content = "……",
  ui_story_2_15_15_option_content = "妳還好嗎？",
  ui_story_2_15_17_dialog_content = "……你最好抓穩點，PlayerName，我們還沒脫離危險。",
  ui_story_2_15_18_dialog_content = "卡戎已經按下紅鍵了。在地下城……爆炸之前，我們必須提升到安全高度才行。",
  ui_story_2_15_19_option_content = "對不起……",
  ui_story_2_15_20_option_content = "卡戎他……",
  ui_story_2_15_21_dialog_content = "我承諾過……不會拋​​棄任何一個人……明明承諾過……",
  ui_story_2_15_F2_dialog_content = "這不是你的錯，PlayerName。是我……",
  ui_story_2_15_22_dialog_content = "如果我當時再努力一點，哪怕只是換一個接應路線，也許就不會被暗鬼隔開了。",
  ui_story_2_15_23_dialog_content = "不，也許從一開始就不應該和他分頭掩護大家……",
  ui_story_2_15_24_dialog_content = "真是令人感動的戲碼。差點擦肩而過。",
  ui_story_2_15_25_dialog_content = "真頑固啊……比我預想的還要堅強呢。",
  ui_story_2_15_26_dialog_content = "你竟然……？！",
  ui_story_2_15_27_dialog_content = "放棄吧，抵抗沒有意義！我不會再中你們的計，不會的……",
  ui_story_2_15_28_option_content = "你為什麼要追殺我？！",
  ui_story_2_15_29_dialog_content = "我要完成自己的使命。",
  ui_story_2_15_30_dialog_content = "使命到底是什麼？比如毀滅一切沒有信仰的生命。",
  ui_story_2_15_31_option_content = "你的目的到底是什麼？！",
  ui_story_2_15_32_dialog_content = "一切都是為了完成我們的使命。",
  ui_story_2_15_33_dialog_content = "我們的力量，來自我們的信仰。",
  ui_story_2_15_34_dialog_content = "我們的信仰，來自我們的母親。",
  ui_story_2_15_35_dialog_content = "空裔，還有光靈，你們這些苟活於大陸的低等生物，能被我們毀滅就是最大的幸福。",
  ui_story_2_15_36_dialog_content = "你最好也放棄無謂的掙扎，那只會徒增痛苦，就像之前那個愚蠢的士兵一樣。",
  ui_story_2_15_37_dialog_content = "停止升空，回到地面，然後光靈們可以有個痛快的結局。",
  ui_story_2_15_38_dialog_content = "我不會投降的。也絕不會再讓你……傷害我的夥伴了！",
  ui_story_2_15_39_dialog_content = "尋求光榮戰死？好。",
  ui_story_2_15_40_dialog_content = "那我就給予你們，能配得上這份執拗的死亡。",
  ui_story_2_15_41_dialog_content = "是你們，將會被我用最殘忍的方式蹂躪至死。",
  ui_story_2_15_89_dialog_content = "主人……我……失敗了……",
  ui_story_2_15_91_dialog_content = "可是，這並不是……結束……",
  ui_story_2_15_X92_dialog_content = "想聽到我的懺悔嗎？哈哈……哈哈哈哈……",
  ui_story_2_15_X93_dialog_content = "你們就短暫沉溺在所謂的「勝利」之中吧！",
  ui_story_2_15_X94_dialog_content = "主人終將給予你們裁決，當她親自面對你們，無論是光靈還是懦弱的空裔——",
  ui_story_2_15_X95_dialog_content = "你們卑賤的喉嚨將連最輕微的呻吟都無法發出……",
  ui_story_2_15_92_dialog_content = "「舒默」，儘管讓這個名字在你們腦中迴盪吧。",
  ui_story_2_15_93_dialog_content = "你們永遠無法想像她洶湧的力量。",
  ui_story_2_15_42_dialog_content = "……這次，它再也回不來了。",
  ui_story_2_15_43_dialog_content = "<color=#e8d9bb>轟——！！！</color>",
  ui_story_2_15_44_dialog_content = "28號地下城……爆炸了……",
  ui_story_2_15_45_dialog_content = "<color=#e8d9bb>火光與黎明一同到來，宛如對新生的致意，以及對逝者的哀悼……</color>",
  ui_story_2_15_46_dialog_content = "別了……地下城28號、卡戎……",
  ui_story_2_15_47_dialog_content = "我很抱歉。",
  ui_story_2_15_48_dialog_content = "那是他的選擇，和你沒有關係，PlayerName。",
  ui_story_2_15_49_dialog_content = "為什麼……為了掩護我們，連自己的安危都不顧嗎，到最後關頭還要逞強……",
  ui_story_2_15_51_option_content = "他會成為其他人的榜樣吧",
  ui_story_2_15_52_dialog_content = "沒有了生命，成為榜樣有什麼意義？",
  ui_story_2_15_B1_dialog_content = "所謂的「榜樣」，又到底是什麼意思……",
  ui_story_2_15_B2_dialog_content = "如果我理解得沒錯，卡戎是在保護他的「心愛之物」。",
  ui_story_2_15_B3_dialog_content = "……",
  ui_story_2_15_B4_dialog_content = "士兵、同事、夥伴……以及這座地下城",
  ui_story_2_15_53_option_content = "他會活在我們所有人心中",
  ui_story_2_15_54_dialog_content = "活在心裡？也許我說的話聽來很自私，但那不是生命的延續，PlayerName。",
  ui_story_2_15_55_dialog_content = "那是另一種痛苦……給他人的痛苦。",
  ui_story_2_15_B5_dialog_content = "就像你經歷的那些痛苦一樣。難道你願意接受這種結局嗎……",
  ui_story_2_15_B6_dialog_content = "但我也只能接受……",
  ui_story_2_15_B7_dialog_content = "至少他是為了保護「心愛之物」而犧牲的，為了士兵、夥伴……",
  ui_story_2_15_B8_dialog_content = "我們不能辜負這份心意，薇絲。",
  ui_story_2_15_B9_dialog_content = "我懂你說的道理，PlayerName，但我心裡很亂……",
  ui_story_2_15_B10_dialog_content = "保護、奉獻，身為啟光人，我當然知道這些品德。",
  ui_story_2_15_B11_dialog_content = "但看到身邊的人一個個離開……我還是無法坦然面對。",
  ui_story_2_15_57_dialog_content = "我們每天都說「為了啟明之光」，但我們真的能與天空的極光身心合一，惠及後人嗎……",
  ui_story_2_15_58_dialog_content = "我在想，如果有一天……",
  ui_story_2_15_59_dialog_content = "如果有一天，我們又不得不做出這樣的抉擇……",
  ui_story_2_15_60_dialog_content = "我不敢去想像……",
  ui_story_2_15_61_dialog_content = "「希望」。",
  ui_story_2_15_62_dialog_content = "……？",
  ui_story_2_15_63_dialog_content = "卡戎說過，「如果無法改變絕望，那就以希望填滿永恆的黑夜」。",
  ui_story_2_15_66_option_content = "……還真像他的風格。",
  ui_story_2_15_F3_dialog_content = "我會永遠記住這個名字——「冥河列車·卡戎」！",
  ui_story_2_15_F4_dialog_content = "「冥河列車」……？",
  ui_story_2_15_F5_dialog_content = "怎麼了？",
  ui_story_2_15_70_dialog_content = "為什麼卡戎會被稱作「冥河列車」？",
  ui_story_2_15_71_dialog_content = "那是因為他那輛……浮誇的火車，你見過的。",
  ui_story_2_15_72_dialog_content = "身為前任地下鐵調度員，他可以隨時召喚那輛名為「彼岸號」的……火車……",
  ui_story_2_15_73_dialog_content = "啊！",
  ui_story_2_15_74_dialog_content = "火車？等等……那發訊號彈……",
  ui_story_2_15_79_dialog_content = "那傢伙，該不會——",
  ui_story_2_15_80_dialog_content = "薇絲中尉、PlayerName！快看天空！",
  ui_story_2_15_81_dialog_content = "……<color=#FFB400>還真是浮誇</color>。",
  ui_story_2_15_82_dialog_content = "<size=45>華——————麗的謝幕！！</size>",
  ui_story_2_15_A15_dialog_content = "煙火、掌聲、以及各位感動的淚水，在下都不客氣地收下了！！",
  ui_story_2_15_83_dialog_content = "<size=45>冥河列車·卡戎，到此一遊～！！！</size>",
  ui_story_2_15_84_dialog_content = "各位觀眾～是否有為在下，流下激動的淚水呢～！",
  ui_story_2_15_F6_dialog_content = "讓我們隨機抽取一位幸運觀眾——PlayerName，請問有什麼感想嗎？",
  ui_story_2_15_X85_dialog_content = "呃……真、真是場目眩神迷的精彩演出……",
  ui_story_2_15_85_dialog_content = "不愧是……卡戎長官……",
  ui_story_2_15_86_dialog_content = "真是……讓人哭笑不得呢……",
  ui_story_2_15_87_option_content = "太好了……唔？",
  ui_story_2_15_88_dialog_content = "PlayerName？",
  ui_story_2_15_X88_dialog_content = "好暈……那個……又來了……",
  ui_story_2_15_95_dialog_content = "這似曾相識的場景……",
  ui_story_2_15_96_dialog_content = "薇絲……",
  ui_story_2_15_100_dialog_content = "PlayerName！我在這裡！請保持清醒！",
  ui_story_2_15_101_dialog_content = "<color=#e8d9bb>另一處<color=#FFB400>巨像遺跡</color>外</color>",
  ui_story_2_15_102_dialog_content = "……",
  ui_story_2_15_103_dialog_content = "您還好嗎，大人？",
  ui_story_2_15_104_dialog_content = "為什麼這麼說？",
  ui_story_2_15_105_dialog_content = "您剛才分心了。明明是苦等了許久的機會，您應該不會如此心不在焉……",
  ui_story_2_15_106_dialog_content = "……不要去探究不該問的事情，暗鬼。我只是……也許只是錯覺吧。",
  ui_story_2_15_107_dialog_content = "那就祝您狩獵順利。希望您可以找到一直想找的東西。",
  ui_story_2_15_108_dialog_content = "狩獵嗎……哼，我倒是喜歡這個說法。",
  ui_story_2_15_109_dialog_content = "可以聽到我的聲音嗎……我能夠感覺到你的存在……",
  ui_story_2_15_110_dialog_content = "你應該也能感應到身為<color=#FFB400>同類</color>的我……我已經沒有時間了。",
  ui_story_2_15_111_dialog_content = "吞噬者號，<color=#FFB400>那個女人</color>……不祥的黑色……同類相殘的罪人……",
  ui_story_2_15_112_dialog_content = "她現在找到我了……",
  ui_story_2_15_113_dialog_content = "我和我的巨像……已經沒有時間了……",
  ui_story_3_1_1_dialog_content = "聽得見嗎？雖然不認識你，但我知道你是我的「同胞」……",
  ui_story_3_1_2_dialog_content = "你……一定能聽到，我的聲音……",
  ui_story_3_1_3_dialog_content = "訊號彈已經發出，所有人在原地待命，不准亂跑。",
  ui_story_3_1_4_dialog_content = "嗯？薇絲，這個叫PlayerName的傢伙醒過來了！！",
  ui_story_3_1_5_dialog_content = "不過他好像還對在下華麗的表演意猶未盡呢。",
  ui_story_3_1_6_dialog_content = "非常感謝，卡戎長官，但請你先去接受緊急治療！",
  ui_story_3_1_7_dialog_content = "小事。在下好得很。可惜我剛才的英姿沒有留下珍貴的影像資料……",
  ui_story_3_1_8_dialog_content = "重點是這個嗎……？",
  ui_story_3_1_9_dialog_content = "話說回來，紅鍵的威力真是不得了呢。其實我很久以前就想按按看了……",
  ui_story_3_1_10_dialog_content = "卡戎長官，28號地下城就這樣化為廢墟，你……會遺憾嗎？",
  ui_story_3_1_11_dialog_content = "遺憾，但也不至於痛哭流涕。因為<color=#FFB400>家園</color>還在。",
  ui_story_3_1_12_dialog_content = "家園？",
  ui_story_3_1_13_dialog_content = "當然，你看看周圍。",
  ui_story_3_1_14_dialog_content = "居民、士兵，這些啟光聯邦最重要的「資產」都完好無損。",
  ui_story_3_1_15_dialog_content = "「心愛之物」在的地方就是家園。",
  ui_story_3_1_F1_dialog_content = "嗯……",
  ui_story_3_1_16_dialog_content = "妳和那位空裔沒有受傷吧？說起來，在下已經救你們兩次了。",
  ui_story_3_1_F2_dialog_content = "謝謝長官……",
  ui_story_3_1_17_dialog_content = "在下必須去那邊查看受災情況了。你們不要亂跑，在這裡待命！",
  ui_story_3_1_18_dialog_content = "是、是……",
  ui_story_3_1_19_dialog_content = "卡戎長官……意外地有些溫柔呢。",
  ui_story_3_1_20_dialog_content = "PlayerName，還好嗎？你剛才……",
  ui_story_3_1_B1_dialog_content = "嗯，不要緊。",
  ui_story_3_1_B2_dialog_content = "你的臉色很糟，不要勉強自己。",
  ui_story_3_1_B3_dialog_content = "薇絲，謝謝妳……一直陪在我身邊。",
  ui_story_3_1_B4_dialog_content = "欸，不用這麼見外啦。我們可是有默契的夥伴喔！",
  ui_story_3_1_B5_dialog_content = "多虧有你，我們才能打敗那些高級暗鬼嘛～",
  ui_story_3_1_B6_dialog_content = "這只是<color=#FFB400>開始</color>而已，薇絲。",
  ui_story_3_1_B7_dialog_content = "欸？開始？",
  ui_story_3_1_B8_dialog_content = "麥格芬死前，又提到那個名字——<color=#FFB400>舒默</color>。",
  ui_story_3_1_B9_dialog_content = "「舒默」……這到底是什麼人？",
  ui_story_3_1_B10_dialog_content = "我還不能確定，但我想這個人一定知道所有真相。",
  ui_story_3_1_B11_dialog_content = "薇絲，對不起，我必須找到「舒默」，我必須要找到真相。",
  ui_story_3_1_B12_dialog_content = "PlayerName……怎麼突然這麼有幹勁？",
  ui_story_3_1_B13_dialog_content = "我……重新找到自己的「<color=#FFB400>家園</color>」了。",
  ui_story_3_1_B14_dialog_content = "我養傷的時候，你和卡戎是不是產生了什麼奇怪的默契……",
  ui_story_3_1_B15_dialog_content = "可惜，我們沒有從麥格芬那裡得到更多關於「舒默」的資訊……",
  ui_story_3_1_B17_dialog_content = "沒關係。等我們回到啟光聯邦總部，也許可以找到一些資料。",
  ui_story_3_1_B18_dialog_content = "PlayerName，你怎麼了……？",
  ui_story_3_1_B21_dialog_content = "……救……",
  ui_story_3_1_B22_dialog_content = "……快……聽得到嗎！",
  ui_story_3_1_B23_dialog_content = "PlayerName，你感受到了嗎？從剛才起似乎就……",
  ui_story_3_1_B24_dialog_content = "沒錯。<color=#FFB400>似乎是誰在向我們求救</color>？",
  ui_story_3_1_21_dialog_content = "吞噬……者……正在……我已經沒有時間了……",
  ui_story_3_1_22_dialog_content = "你聽到了什麼聲音，是嗎？",
  ui_story_3_1_23_option_content = "只有空裔能這樣進行感應！",
  ui_story_3_1_24_dialog_content = "是<color=#FFB400>和我一樣</color>的倖存者？是我的同族？！",
  ui_story_3_1_25_dialog_content = "沒錯，而且從傳遞的內容來看，對方的處境很危險。",
  ui_story_3_1_26_dialog_content = "難道他也像我們一樣……",
  ui_story_3_1_27_option_content = "是個男孩的聲音",
  ui_story_3_1_28_dialog_content = "沒錯，他的意識充滿恐懼，恐怕凶多吉少。",
  ui_story_3_1_F3_dialog_content = "能進行這樣的感應……他是我的同族？！",
  ui_story_3_1_29_dialog_content = "沒錯。但是對方巨像的訊號很微弱，不論怎麼嘗試都無法連接到訊號。",
  ui_story_3_1_30_dialog_content = "他在求救，有什麼可怕的事情正在發生。發生在他，還有他的巨像身上……",
  ui_story_3_1_31_dialog_content = "<color=#FFB400>又一名空裔</color>？",
  ui_story_3_1_32_dialog_content = "等一下，你是說，你還能透過他找到其他巨像？",
  ui_story_3_1_33_dialog_content = "薇絲，可以請妳幫幫我嗎？",
  ui_story_3_1_34_dialog_content = "……",
  ui_story_3_1_35_dialog_content = "中尉，有什麼需要告訴我的事情嗎？",
  ui_story_3_1_36_dialog_content = "呃，我們……",
  ui_story_3_1_37_dialog_content = "我們收到其他空裔的求救訊號！",
  ui_story_3_1_38_dialog_content = "……？！",
  ui_story_3_1_39_dialog_content = "一下出現兩名空裔？最近是怎麼了？",
  ui_story_3_1_40_dialog_content = "我可以肯定，那種感應方式和我的一模一樣！",
  ui_story_3_1_41_dialog_content = "在哪？就在附近嗎？",
  ui_story_3_1_42_dialog_content = "不清楚……但我知道大概的方位，我們最好現在就出發！",
  ui_story_3_1_43_dialog_content = "……",
  ui_story_3_1_44_dialog_content = "不行。",
  ui_story_3_1_45_dialog_content = "長官！",
  ui_story_3_1_46_dialog_content = "毫無組織、藐視紀律！你們才剛造成了多大的麻煩，自己不知道嗎！",
  ui_story_3_1_47_dialog_content = "可是……",
  ui_story_3_1_48_dialog_content = "大家都在看呢，這種時候就不要再製造慌亂了。",
  ui_story_3_1_49_dialog_content = "而且妳的直系長官——第三軍團長緋就快到了。",
  ui_story_3_1_50_dialog_content = "不準備向她匯報一下現在的狀況嗎？",
  ui_story_3_1_51_dialog_content = "……",
  ui_story_3_1_52_dialog_content = "可是，我們不能在這裡浪費時間……",
  ui_story_3_1_53_dialog_content = "誰知道下次再出現這樣的線索是什麼時候呢？",
  ui_story_3_1_54_dialog_content = "那個人聽起來真的很需要幫助！我很確定他正處於危險中！",
  ui_story_3_1_55_dialog_content = "那是我的同胞，卡戎。我真正的、活生生的同胞！",
  ui_story_3_1_56_dialog_content = "…………",
  ui_story_3_1_57_dialog_content = "長官……",
  ui_story_3_1_58_dialog_content = "在下明白這件事對你的重要性，PlayerName。",
  ui_story_3_1_59_dialog_content = "但啟光聯邦也有自己的紀律，特別是我這個長官還在場的情況下。",
  ui_story_3_1_60_dialog_content = "除非……",
  ui_story_3_1_61_dialog_content = "……！",
  ui_story_3_1_62_dialog_content = "除非，在下並不知道你們的行動。",
  ui_story_3_1_63_dialog_content = "欸？",
  ui_story_3_1_64_dialog_content = "妳好歹也是個中尉，薇絲，而且妳的直系長官並非在下。",
  ui_story_3_1_A1_dialog_content = "所以妳也有一定程度的自行決斷權，只要別把啟光聯邦置於險境即可。",
  ui_story_3_1_A2_dialog_content = "咳，在下再強調一次，啟光聯邦的同僚都在看呢。",
  ui_story_3_1_A3_dialog_content = "我知道該怎麼辦了，薇絲。",
  ui_story_3_1_65_dialog_content = "你想到什麼主意了嗎？",
  ui_story_3_1_B25_option_content = "我們悄悄溜走就好",
  ui_story_3_1_B26_option_content = "表演一齣戲就行了",
  ui_story_3_1_66_dialog_content = "PlayerName，不要當著長官的面說這種話……",
  ui_story_3_1_67_dialog_content = "嗯？什麼話？剛才風聲太大，在下沒聽清楚。",
  ui_story_3_1_68_dialog_content = "……",
  ui_story_3_1_B26_dialog_content = "長官，你難道是在暗示我們……",
  ui_story_3_1_B27_dialog_content = "暗示？在下什麼都沒暗示！妳在說什麼呢？",
  ui_story_3_1_B28_dialog_content = "剛才只是提醒了妳，身為中尉有哪些選擇而已，薇絲。",
  ui_story_3_1_B29_dialog_content = "到底何去何從，那是你們自己的事。",
  ui_story_3_1_B30_dialog_content = "瞭解，長官。謝謝你。",
  ui_story_3_1_B31_dialog_content = "緋馬上就到了，如果要做什麼「在下不知道」的事，就趁現在吧。",
  ui_story_3_1_B32_dialog_content = "等她來，妳就真的要留下來匯報了唷。",
  ui_story_3_1_B33_dialog_content = "卡戎長官這個人……真是有趣呢。",
  ui_story_3_1_B34_dialog_content = "呼……緊張、好緊張……不知道緋長官會有什麼反應……",
  ui_story_3_1_B35_dialog_content = "一齣戲……？",
  ui_story_3_1_B36_dialog_content = "咳、咳！",
  ui_story_3_1_B37_dialog_content = "哦！卡戎，有件事我不知道該不該講！",
  ui_story_3_1_B38_dialog_content = "咳，請暢所欲言，空裔！",
  ui_story_3_1_B39_dialog_content = "臨空者號剛才告訴我，有大批暗鬼正隨著巨像的蹤跡向我們追來！",
  ui_story_3_1_B40_dialog_content = "欸？啊？",
  ui_story_3_1_B41_dialog_content = "什麼？！巨像的氣息會吸引更多暗鬼嗎？！",
  ui_story_3_1_B42_dialog_content = "這種事情為什麼不早說！那可真是危險至極！",
  ui_story_3_1_B43_dialog_content = "？ ？ ？ ？",
  ui_story_3_1_B44_dialog_content = "（配合！薇絲，配合「演出」！）",
  ui_story_3_1_B45_dialog_content = "啊、啊！抱歉，我……也是剛知道……？",
  ui_story_3_1_B46_dialog_content = "哼！簡直不可理喻！讓剛從地獄火海脫身的民眾再次陷入可怕威脅……",
  ui_story_3_1_B47_dialog_content = "在下無法容忍這種危害百姓的行為！",
  ui_story_3_1_B48_dialog_content = "哦，那、那該怎麼辦！",
  ui_story_3_1_B49_dialog_content = "快把這座巨像開走！！離可憐的受災民眾遠一點！",
  ui_story_3_1_B50_dialog_content = "是！",
  ui_story_3_1_B51_dialog_content = "（快走快走！）",
  ui_story_3_1_B52_dialog_content = "謝、謝謝你，卡戎長官。",
  ui_story_3_1_B53_dialog_content = "……哼。",
  ui_story_3_1_B55_dialog_content = "剛才那段莫名其妙的表演，真的有必要嗎……",
  ui_story_3_1_B56_dialog_content = "不知道，但卡戎看起來樂在其中？",
  ui_story_3_1_B57_dialog_content = "而且我們也需要一個離開的理由——趁妳的直屬長官過來之前。",
  ui_story_3_1_B58_dialog_content = "對，緋……",
  ui_story_3_1_B59_dialog_content = "唉，緋長官知道我們擅自離開會有什麼反應呢……",
  ui_story_3_1_69_option_content = "後悔了嗎？",
  ui_story_3_1_70_dialog_content = "沒有！",
  ui_story_3_1_71_dialog_content = "希望妳那個叫「緋」的上司是個善解人意的長官。",
  ui_story_3_1_72_dialog_content = "……你這麼一說，我現在有點後悔了。",
  ui_story_3_1_73_option_content = "希望這個選擇是正確的",
  ui_story_3_1_74_dialog_content = "是不是正確，都不是我們能決定的吧？……",
  ui_story_3_1_76_dialog_content = "啊啊啊啊，緋長官絕對不會放過我的！！！",
  ui_story_3_1_77_dialog_content = "目標：未知空裔生命訊號發射地。加速倒數計時！",
  ui_story_3_1_78_dialog_content = "五……四……三……二……",
  ui_story_3_1_79_dialog_content = "一！起飛！",
  ui_story_3_1_80_dialog_content = "長官！關於這次事件的書面總結，您看這樣處理可以嗎……",
  ui_story_3_1_81_dialog_content = "我看看，嗯……嗯……這裡不夠好。",
  ui_story_3_1_82_dialog_content = "關於薇絲和空裔的部分要更詳細一些，讓他們的行為和這裡發生的事情連結起來。",
  ui_story_3_1_83_dialog_content = "啊、是，長官！",
  ui_story_3_1_84_dialog_content = "相信我，你不會想讓那個女人質問你細節的。",
  ui_story_3_1_85_dialog_content = "這可和我預想的不一樣，卡戎。",
  ui_story_3_1_86_dialog_content = "……",
  ui_story_3_1_87_dialog_content = "要問28號地下城那片廢墟就是了，軍團長大人。",
  ui_story_3_1_88_dialog_content = "不要重複我已經知道的事情，卡戎。你在簡報裡提到的巨像呢？",
  ui_story_3_1_89_dialog_content = "鳥兒已經華麗地離開了。",
  ui_story_3_1_90_dialog_content = "我的部下現在在哪裡？",
  ui_story_3_1_91_dialog_content = "走了，她在巨像上。",
  ui_story_3_1_92_dialog_content = "地下城28號主管卡戎，你是在說我的人違抗命令嗎？",
  ui_story_3_1_93_dialog_content = "我只是告訴您，她和那名空裔在一起。",
  ui_story_3_1_94_dialog_content = "空裔……",
  ui_story_3_1_95_dialog_content = "長官！這邊已經……啊，軍團長大人，很抱歉打擾你們談話！！",
  ui_story_3_1_96_dialog_content = "說吧。",
  ui_story_3_1_97_dialog_content = "是！已將受難規模和民眾的健康狀態統計完畢。請求下一步指示！",
  ui_story_3_1_98_dialog_content = "照原計劃把他們安排到最近的地下城，我會讓一營和三營留下來，在路上保護他們。",
  ui_story_3_1_99_dialog_content = "保護民眾這種事情，我們自己來就可以了，不必勞煩妳的……",
  ui_story_3_1_100_dialog_content = "其餘的人，跟我來。",
  ui_story_3_1_101_dialog_content = "……",
  ui_story_3_1_102_dialog_content = "還是那副不近人情的老樣子啊，緋。",
  ui_story_3_1_103_dialog_content = "你在做什麼？",
  ui_story_3_1_104_dialog_content = "我？",
  ui_story_3_1_A4_dialog_content = "這是什麼，烹飪工具？",
  ui_story_3_1_A5_dialog_content = "……這是小型遠程通訊器。",
  ui_story_3_1_105_dialog_content = "這是啟光的東西嗎？妳之前怎麼沒拿出來？",
  ui_story_3_1_106_dialog_content = "這是剛才卡戎長官偷偷塞給我的。",
  ui_story_3_1_107_dialog_content = "卡戎……",
  ui_story_3_1_108_dialog_content = "這個要怎麼……啊這個真的好難用……",
  ui_story_3_1_109_dialog_content = "我記得是……在這裡交叉，把線繞進去，然後調一下頻率……",
  ui_story_3_1_111_dialog_content = "啊，接通了！",
  ui_story_3_1_112_dialog_content = "報告妳現在的位置。",
  ui_story_3_1_113_dialog_content = "是，緋長官？",
  ui_story_3_1_114_dialog_content = "看來妳還認得自己的上司，中尉。為什麼擅自離開？",
  ui_story_3_1_115_dialog_content = "對不起，28號地下城遭到暗鬼入侵，已經啟動自毀程序爆炸了。",
  ui_story_3_1_116_dialog_content = "不要重複我已經知道的事情。我問你為什麼擅自帶走巨像？",
  ui_story_3_1_117_dialog_content = "巨像……我……",
  ui_story_3_1_118_dialog_content = "這位……女士，巨像並不屬於你們，請先認清事實。",
  ui_story_3_1_119_dialog_content = "原來就是你……",
  ui_story_3_1_120_dialog_content = "對，我才是這座巨像的主人。",
  ui_story_3_1_122_dialog_content = "現在因為你和你的寶貝巨像，28號地下城已經從地圖上消失了。",
  ui_story_3_1_A6_dialog_content = "你不覺得你需要給啟光聯邦一個解釋嗎？",
  ui_story_3_1_123_dialog_content = "真的很抱歉……但我一定會想辦法，給啟光一個交代！",
  ui_story_3_1_124_dialog_content = "麥格芬提過，有個叫「<color=#FFB400>舒默</color>」的傢伙……",
  ui_story_3_1_125_dialog_content = "麥格芬、舒默，我對這些奇怪的名字沒興趣。",
  ui_story_3_1_126_dialog_content = "但是所有的事情……28號地下城的事，可能都跟「舒默」有關！",
  ui_story_3_1_127_dialog_content = "哦？",
  ui_story_3_1_128_dialog_content = "長官，我們有其他空裔的線索，可能會指向其他的巨像！！！",
  ui_story_3_1_129_dialog_content = "你說什麼？！",
  ui_story_3_1_130_dialog_content = "但是那名空裔和他的巨像現在遇到了危險！",
  ui_story_3_1_131_dialog_content = "PlayerName想做點什麼，我想……",
  ui_story_3_1_132_dialog_content = "我想我應該幫助他！這對啟光也非常重要！",
  ui_story_3_1_133_dialog_content = "中尉，我必須提醒妳——",
  ui_story_3_1_A7_dialog_content = "你現在是一名啟光聯邦的士兵！請你想清楚！",
  ui_story_3_1_134_dialog_content = "長官，對不起，我之前阻止過他，但我想這次他是對的！",
  ui_story_3_1_135_dialog_content = "薇絲……？",
  ui_story_3_1_136_dialog_content = "這一次，他是對的……",
  ui_story_3_1_137_dialog_content = "我會拯救我的族人，弄清這一切的真相。",
  ui_story_3_1_A8_dialog_content = "……",
  ui_story_3_1_A9_dialog_content = "…………",
  ui_story_3_1_138_dialog_content = "唉……你們有多大把握？",
  ui_story_3_1_139_dialog_content = "我不會再讓暗鬼得逞的！",
  ui_story_3_1_140_dialog_content = "……馬上把目的地座標傳來。",
  ui_story_3_1_141_dialog_content = "你的通訊訊號很不穩定，我們無法追蹤你們的位置。",
  ui_story_3_1_142_dialog_content = "還有薇絲，不要忘記妳的立場！別做蠢事……",
  ui_story_3_1_144_dialog_content = "啊，訊號怎麼忽然斷了？！",
  ui_story_3_1_145_dialog_content = "是一股強大的壓迫感……和我們之前遇到的都不一樣。",
  ui_story_3_1_146_dialog_content = "我的同族，在呼救時提過「<color=#FFB400>吞噬者號</color>」。",
  ui_story_3_1_A10_dialog_content = "是這傢伙嗎？",
  ui_story_3_1_147_dialog_content = "我不知道，PlayerName，但這股力量非常強大，就在……",
  ui_story_3_1_148_dialog_content = "嗯，就在這裡！",
  ui_story_3_1_A11_dialog_content = "薇絲，臨空者找到目的地了，裡面可能有一個叫做「吞噬者號」的傢伙。",
  ui_story_3_1_A12_dialog_content = "現在情報太少，我們得加倍小心。",
  ui_story_3_1_149_dialog_content = "「吞噬者號」？難道是巨像？！",
  ui_story_3_1_150_dialog_content = "現在還不能確定……",
  ui_story_3_1_151_dialog_content = "欸……",
  ui_story_3_1_152_dialog_content = "PlayerName，如果我現在阻止你，你會聽我的嗎？",
  ui_story_3_1_153_dialog_content = "臨空者……對不起。",
  ui_story_3_1_154_dialog_content = "我想也是……",
  ui_story_3_1_155_dialog_content = "馬上降落，讓大家做好戰鬥的準備。",
  ui_story_3_1_A13_dialog_content = "下方已有不少暗鬼盤踞！",
  ui_story_3_3_1_dialog_content = "嗯？有人來了。",
  ui_story_3_3_2_dialog_content = "不自量力的傢伙……竟敢來打擾我？",
  ui_story_3_3_3_dialog_content = "需要屬下去處理掉嗎？",
  ui_story_3_3_4_dialog_content = "暫時沒有這個必要。接下來要做的事才是最重要的。",
  ui_story_3_3_5_dialog_content = "舒默……妳來做什麼？",
  ui_story_3_3_6_dialog_content = "喔？我可愛的兄弟出現了，還以為你會和那個時候一樣逃走呢。",
  ui_story_3_3_7_dialog_content = "<color=#FFB400>守祕者號</color>巨像的主人。",
  ui_story_3_3_8_dialog_content = "哎呀不對，我應該叫你迷人的綽號，「膽小鬼<color=#FFB400>孟德爾頌</color>」。",
  ui_story_3_3_9_dialog_content = "……咳咳、我被喚醒的第一時間，聞到的就是妳令人作嘔的氣味……舒默。",
  ui_story_3_3_10_dialog_content = "或者我應該稱呼妳為「<color=#FFB400>吞噬者號的主人</color>」。",
  ui_story_3_3_11_dialog_content = "看在你是我兄弟的份上，我就把事情變得簡單些吧。",
  ui_story_3_3_12_dialog_content = "帶我去尋找<color=#FFB400>那個東西</color>。",
  ui_story_3_3_A1_dialog_content = "我不知道妳在說什麼。我這裡什麼也沒有，舒默，只有無聊的歷史……",
  ui_story_3_3_A2_dialog_content = "還有骯髒的祕密，別以為我不知道。",
  ui_story_3_3_A3_dialog_content = "把「<color=#FFB400>智庫組件</color>」給我！我知道你有一個。",
  ui_story_3_3_A4_dialog_content = "……妳要它做什麼？",
  ui_story_3_3_A5_dialog_content = "獲取一些……想知道的情報而已。",
  ui_story_3_3_A6_dialog_content = "如果妳是想做那件事，我是絕不會答應的。",
  ui_story_3_3_A7_dialog_content = "那是明令禁止的，是違背巨像使命的「邪道」！",
  ui_story_3_3_13_dialog_content = "想讓我為妳敞開大門？",
  ui_story_3_3_14_dialog_content = "恐怕妳對「守祕者」這個字眼有什麼誤解吧，舒默。",
  ui_story_3_3_15_dialog_content = "不要那麼小氣嘛，孟德爾頌。",
  ui_story_3_3_16_dialog_content = "我們都投靠相同的力量，不是嗎？不然你也活不到今天。",
  ui_story_3_3_17_dialog_content = "那是空裔永遠無法擁有的力量。你和我，是一樣的。",
  ui_story_3_3_18_dialog_content = "所以我沒有一天不後悔，舒默……咳咳，早知如此……",
  ui_story_3_3_19_dialog_content = "嗯……？你的身體，好像在崩潰呢……",
  ui_story_3_3_A8_dialog_content = "看來你沒有完全接受那種恩賜呢，孟德爾頌。可憐的牆頭草……",
  ui_story_3_3_20_dialog_content = "看你這副德行，連說話都費力成這樣……真是令人心疼呢！！！",
  ui_story_3_3_22_dialog_content = "落錘處乃爾等死線——以此為誡，寸步休進。",
  ui_story_3_3_23_dialog_content = "聽懂了嗎？跨過這條線，就​​是地獄了。",
  ui_story_3_3_24_dialog_content = "我雖然沒有戰鬥能力，但是守祕者號也不是能任人宰割的，咳咳……",
  ui_story_3_3_25_dialog_content = "人形防火牆……膽小鬼所特有的保護機制嗎？",
  ui_story_3_3_26_dialog_content = "別把我看扁了，舒默！",
  ui_story_3_3_27_dialog_content = "大人，需要屬下出手嗎？",
  ui_story_3_3_A9_dialog_content = "就說不用了！這是我們自己的事！",
  ui_story_3_3_28_dialog_content = "哼，家貓，還有忠犬……很適合孟德爾頌呢。",
  ui_story_3_3_29_dialog_content = "正因如此，你才一直是個沒出息的膽小鬼。",
  ui_story_3_3_30_dialog_content = "無禮！",
  ui_story_3_3_31_dialog_content = "好了，跪下！",
  ui_story_3_3_32_dialog_content = "無法活動！無法活動！接收到優先級為最高的指令，強制執行！",
  ui_story_3_3_33_dialog_content = "菲萊克斯！主人您快看他……",
  ui_story_3_3_34_dialog_content = "啊啊啊啊……",
  ui_story_3_3_35_dialog_content = "樊尼，菲萊克斯……這是什麼……舒默！你對他們做了什麼？！",
  ui_story_3_3_36_dialog_content = "這兩個「玩具」實在太有趣了，孟德爾頌。",
  ui_story_3_3_37_dialog_content = "所以我臨時決定要把他們變成屬於我的東西。",
  ui_story_3_3_38_dialog_content = "看來妳墮落的不僅是靈魂和身軀……妳已經完全變成另外一種東西了，舒默！",
  ui_story_3_3_39_dialog_content = "謝謝誇獎，不過這不會改變我要做的任何事哦。",
  ui_story_3_3_40_dialog_content = "把他們還給我！！！妳這個怪物！",
  ui_story_3_3_41_dialog_content = "哎呀，這個要求倒是可以滿足你！！菲萊克斯、樊尼……是叫這個名字對嗎？ ？",
  ui_story_3_3_42_dialog_content = "我在！",
  ui_story_3_3_43_dialog_content = "給我抓住孟德爾頌！",
  ui_story_3_3_44_dialog_content = "什……什麼！",
  ui_story_3_3_45_dialog_content = "呿，竟然又逃走了。",
  ui_story_3_3_46_dialog_content = "說什麼「別瞧不起我」，結果還是一點都沒變嘛，一樣是當年那個膽小鬼。",
  ui_story_3_3_47_dialog_content = "接下來該怎麼做，我的主人？",
  ui_story_3_3_48_dialog_content = "追擊，直到抓住他為止，然後把他帶回來，讓我再看看他那張臉……",
  ui_story_3_3_49_dialog_content = "到時候，會是什麼樣子呢？",
  ui_story_3_3_50_dialog_content = "是！！",
  ui_story_3_3_51_dialog_content = "是！！",
  ui_story_3_3_52_dialog_content = "我、我不能被他們捉住……你……能聽見吧……救救……",
  ui_story_3_3_53_dialog_content = "我能聽見！你在哪？你也是空裔吧？！",
  ui_story_3_3_54_dialog_content = "吞噬者號的……力量，變得更強了……",
  ui_story_3_3_55_dialog_content = "不，不能讓她奪走「智庫組件」，不能讓她掌握……那個「方法」……",
  ui_story_3_3_56_dialog_content = "你離不開我的。瞧你連說話都費力的孱弱模樣……真是令人心疼。",
  ui_story_3_3_57_dialog_content = "舒默……這次妳不會得逞的，絕不……",
  ui_story_3_3_58_dialog_content = "你離不開我的。",
  ui_story_3_3_59_dialog_content = "但……妳已經贏了，不是嗎？打從一開始就贏了。",
  ui_story_3_3_60_dialog_content = "妳用那種邪惡的力量侵蝕我，讓我無法阻止妳——",
  ui_story_3_3_61_dialog_content = "不，必須阻止……這是我的使命，是守祕者號的使命……",
  ui_story_3_3_62_dialog_content = "……你一直是個沒出息的膽小鬼。",
  ui_story_3_3_63_dialog_content = "我到底該生存，還是毀滅……",
  ui_story_3_3_64_dialog_content = "（日蝕語）有人！抓住他！",
  ui_story_3_3_65_dialog_content = "你在嗎？同族，我要繼續逃跑了！",
  ui_story_3_3_66_dialog_content = "求求你快一點……為了我，也為了你自己！",
  ui_story_3_3_A10_dialog_content = "……那個人，正在被暗鬼追擊。我無法掌握確切位置……",
  ui_story_3_3_A11_dialog_content = "瞭解，那就加快腳步！",
  ui_story_3_3_A12_dialog_content = "PlayerName，前方暗鬼會越來越多，請繼續保持警惕！",
  ui_story_3_7_1_dialog_content = "這裡也到處都是暗鬼……PlayerName，你沒事吧？",
  ui_story_3_7_2_dialog_content = "我沒事。",
  ui_story_3_7_3_dialog_content = "不知道你說的那個空裔……",
  ui_story_3_7_4_dialog_content = "等一下！",
  ui_story_3_7_5_dialog_content = "……不能被抓到……不能……",
  ui_story_3_7_6_dialog_content = "我們已經進來了！你在哪？！聽得見嗎？",
  ui_story_3_7_7_dialog_content = "快來我這裡！我可以保護你！！",
  ui_story_3_7_8_dialog_content = "是你……同族，你來了！",
  ui_story_3_7_9_dialog_content = "抱歉，我來晚了！！你聽得到我說話嗎？！",
  ui_story_3_7_10_dialog_content = "當然，同族，當然……我甚至能看到你，那是你嗎？",
  ui_story_3_7_16_dialog_content = "誰！",
  ui_story_3_7_17_dialog_content = "咳、敵人，在後面……",
  ui_story_3_7_18_dialog_content = "你沒事吧？！趕上了，太好了，我們趕上了！",
  ui_story_3_7_A5_dialog_content = "啊，這難道就是……？",
  ui_story_3_7_A6_dialog_content = "沒錯，薇絲，這就是一直向我們求救的那位空裔！",
  ui_story_3_7_19_dialog_content = "看起來……狀態很不妙呢。PlayerName，他身上的傷口不是暗鬼造成的……",
  ui_story_3_7_20_dialog_content = "這些事情，是誰對你做的……",
  ui_story_3_7_22_dialog_content = "找到目標孟德爾頌！",
  ui_story_3_7_23_dialog_content = "準備執行緝捕指令！",
  ui_story_3_7_24_dialog_content = "菲萊克斯、樊尼……",
  ui_story_3_7_25_dialog_content = "我的族人！退後！！",
  ui_story_3_7_26_dialog_content = "他就交給你了，PlayerName！戰鬥就讓我們來！",
  ui_story_3_7_27_dialog_content = "菲萊克斯、樊尼……",
  ui_story_3_7_28_dialog_content = "對不起……到頭來，我還是無能為力……",
  ui_story_3_7_29_dialog_content = "他們似乎不是暗鬼，這到底是怎麼回事？",
  ui_story_3_7_30_dialog_content = "他們本來是我的護衛，是這座巨像的防禦機制。",
  ui_story_3_7_31_dialog_content = "可是他們為什麼會攻擊你？",
  ui_story_3_7_32_dialog_content = "是她……她的強大力量，直接覆蓋了我的權限……",
  ui_story_3_7_33_dialog_content = "竟然有這種事情……",
  ui_story_3_7_34_dialog_content = "我真的替你感到抱歉……",
  ui_story_3_7_35_dialog_content = "沒想到……一切都和當年一樣……",
  ui_story_3_7_36_dialog_content = "同族，請問你叫什麼名字？",
  ui_story_3_7_37_dialog_content = "我是守祕者號的主人，孟德爾頌。",
  ui_story_3_7_38_dialog_content = "守祕者號……熟悉的名字。可惜很多事情，我也已經忘記了……",
  ui_story_3_7_40_dialog_content = "那一天，倖存下來的巨像們為了保護火種，切斷了彼此之間的聯繫。",
  ui_story_3_7_41_dialog_content = "看來，這麼多年來是臨空者號保護了你，太好了、太好了……",
  ui_story_3_7_42_dialog_content = "你一直待在這裡嗎？還有其他空裔嗎？",
  ui_story_3_7_43_dialog_content = "你為什麼會變成這樣？吞噬者號是什麼？……",
  ui_story_3_7_44_dialog_content = "咳、我，咳咳……",
  ui_story_3_7_45_dialog_content = "他的傷勢……PlayerName，先讓他喘口氣……",
  ui_story_3_7_46_dialog_content = "請原諒，我不像你們……PlayerName，臨空者號……",
  ui_story_3_7_47_dialog_content = "你還健在，表示臨空者號成功履行保護空裔的職責。",
  ui_story_3_7_48_dialog_content = "而我卻沒能完成自己唯一的使命……",
  ui_story_3_7_49_dialog_content = "對不起，我不懂。",
  ui_story_3_7_50_dialog_content = "PlayerName，臨空者號沒告訴你？",
  ui_story_3_7_51_dialog_content = "……很遺憾，我的記憶在墜落時損壞了。",
  ui_story_3_7_52_dialog_content = "除了服從保護PlayerName的命令外，其他的事情我也……",
  ui_story_3_7_53_dialog_content = "臨空者號在那天受到了損傷。",
  ui_story_3_7_54_dialog_content = "是這樣嗎……咳咳……我感應到了，你們的對話……",
  ui_story_3_7_55_dialog_content = "該說幸還是不幸呢……",
  ui_story_3_7_56_dialog_content = "那麼，這裡到底發生了什麼事？",
  ui_story_3_7_57_dialog_content = "在守祕者這座巨像內部，有一件名為「<color=#FFB400>智庫組件</color>」的重要物品……",
  ui_story_3_7_A1_dialog_content = "那裡面存放著許多訊息，從空裔們的史料到光靈世界的典籍……",
  ui_story_3_7_58_dialog_content = "有無上光明的頌歌，也有至暗深淵的低語……",
  ui_story_3_7_60_dialog_content = "但對於吞噬者號——舒默來說，她想要的卻是最不起眼的內容……",
  ui_story_3_7_61_dialog_content = "舒默她果然在這裡？！",
  ui_story_3_7_62_dialog_content = "是的，此時此刻，她正趕往我的核心區域，試圖強佔「智庫組件」。",
  ui_story_3_7_A2_dialog_content = "並利用它來……不，我不能告訴你們，那是絕不能透露的……！",
  ui_story_3_7_63_dialog_content = "那就讓我們去阻止她！薇絲，請幫幫我！",
  ui_story_3_7_64_dialog_content = "請讓你的同胞帶路吧。我也想親自討伐摧毀28號地下城的幕後黑手！",
  ui_story_3_7_65_dialog_content = "你也在等這一天吧，PlayerName。",
  ui_story_3_7_A3_dialog_content = "沒錯。我已經等不及將所有事問個清楚了……",
  ui_story_3_7_A4_dialog_content = "小心，PlayerName……她，她……",
  ui_story_3_7_66_dialog_content = "咳咳、咳……",
  ui_story_3_7_67_dialog_content = "你的身體狀況在惡化，同胞。我該怎麼辦……",
  ui_story_3_7_68_dialog_content = "不能把他留在這裡，PlayerName。但我們又必須前進……",
  ui_story_3_7_69_dialog_content = "……",
  ui_story_3_7_70_dialog_content = "不要擔心，我的同胞。",
  ui_story_3_7_71_dialog_content = "我沒事的，有我引領，你們會事半功倍……",
  ui_story_3_7_72_dialog_content = "而且作為守祕者號的主人，阻止她奪走「智庫組件」也是我的……職責……",
  ui_story_3_7_73_dialog_content = "謝謝你，孟德爾頌。等這一切結束，你一定要告訴我關於空裔的所有事情！",
  ui_story_3_7_74_dialog_content = "當然，PlayerName。我答應你……我會好好向你細說空谷的歲月……",
  ui_story_3_7_75_dialog_content = "那就出發吧。請帶路，孟德爾頌！",
  ui_story_3_7_76_dialog_content = "讓我們去阻止舒默！",
  ui_story_3_9_A1_dialog_content = "（我在做什麼……明明有逃走的機會，卻又回頭……）",
  ui_story_3_9_A2_dialog_content = "（那是不可能戰勝的力量，不是嗎……為什麼要堅持……）",
  ui_story_3_9_A3_dialog_content = "（逃吧，孟德爾頌，放棄那些無謂的「職責」，為了你自己的性命……）",
  ui_story_3_9_2_dialog_content = "為了我……自己的性命……嗎？",
  ui_story_3_9_3_dialog_content = "怎麼停下了？我們到了嗎？",
  ui_story_3_9_4_dialog_content = "你們……真的想清楚了嗎？現在想逃的話，還來得及……",
  ui_story_3_9_5_dialog_content = "舒默可不是普通的敵人，看看她對菲萊克斯和樊尼做的事情……",
  ui_story_3_9_6_dialog_content = "他們曾義無反顧地守在我身旁，而現在卻對我刀刃相向……",
  ui_story_3_9_7_dialog_content = "舒默的能力也許真的超出我們的認知。",
  ui_story_3_9_8_dialog_content = "PlayerName，身為沒有戰鬥能力的空裔，你為何想要與她正面對抗？",
  ui_story_3_9_10_dialog_content = "我一直在找她，我有很多問題想問她。關於28號地下城，關於十七年前……",
  ui_story_3_9_A4_dialog_content = "而現在，她又肆無忌憚地傷害我的同胞……",
  ui_story_3_9_13_dialog_content = "我不能就這樣離開！我必須阻止她！",
  ui_story_3_9_14_dialog_content = "逃跑也許很容易，但是我們又能跑去哪裡呢？",
  ui_story_3_9_15_dialog_content = "有些地方我們注定回不去了，孟德爾頌。如果前方是面鐵牆……",
  ui_story_3_9_A5_dialog_content = "那就和夥伴一起，撞個頭破血流吧。",
  ui_story_3_9_16_dialog_content = "我懂你的意思了。也對，我在想什麼呢……",
  ui_story_3_9_18_dialog_content = "空谷已經覆滅，所有的親人、朋友都被暗鬼殘殺。",
  ui_story_3_9_19_dialog_content = "只有我，弱小又怯懦的我，為了苟且偷生，帶著守祕者號……逃走了……",
  ui_story_3_9_20_dialog_content = "而現在，我竟然還想再次逃避。",
  ui_story_3_9_21_dialog_content = "孟德爾頌……",
  ui_story_3_9_22_dialog_content = "如果我不繼續前進，那和之前又有什麼差別呢……我們……",
  ui_story_3_9_23_dialog_content = "孟德爾頌！",
  ui_story_3_9_24_dialog_content = "啊……我的……",
  ui_story_3_9_25_dialog_content = "你……怎麼會突然這麼痛苦！",
  ui_story_3_9_26_dialog_content = "已經開始了嗎……舒默？我知道，<color=#FFB400>妳已經拿到它了</color>……！",
  ui_story_3_9_27_dialog_content = "我能感覺到你那強大的黑暗力量，那股能夠將守祕者號完全淹沒的黑暗力量！",
  ui_story_3_9_28_dialog_content = "連最後一點光芒都能淹沒的……",
  ui_story_3_9_29_dialog_content = "我能為你做什麼嗎，孟德爾頌？！",
  ui_story_3_9_30_dialog_content = "……不要……擔心！如此一來，反而打消我最後的顧慮……",
  ui_story_3_9_A8_dialog_content = "走吧，PlayerName，還有你的夥伴們，跟緊我！",
  ui_story_3_9_A9_dialog_content = "讓我們掃光前面的暗鬼，直到黑暗的最深處吧……",
  ui_story_3_9_A10_dialog_content = "還有，小心後面！敵人來襲！",
  ui_story_3_9_31_dialog_content = "孟德爾頌，我摯愛的兄弟，不用再做無謂的掙扎了。",
  ui_story_3_9_32_dialog_content = "藏得這麼隱密不也被我找到了嗎，這個「<color=#FFB400>智庫組件</color>」！",
  ui_story_3_9_33_dialog_content = "不費吹呼之力呢，甚至有點無聊。",
  ui_story_3_9_34_dialog_content = "來吧，向我展示你存有的祕密吧……",
  ui_story_3_9_A11_dialog_content = "哼，果然設了加密手段。看來要花點時間了……",
  ui_story_3_9_35_dialog_content = "大人，我的主人在等您……",
  ui_story_3_9_36_dialog_content = "妳要慢條斯理弄到什麼時候？",
  ui_story_3_9_37_dialog_content = "只不過是些小花招，再一下就好……",
  ui_story_3_9_38_dialog_content = "不久後，我就能完全讀取資料，包括「那個方法」……",
  ui_story_3_9_39_dialog_content = "那些祕密將透過我，與我的<color=#FFB400>黑色巨像</color>融為一體，成為進化之船上的一根鉚釘！",
  ui_story_3_9_41_dialog_content = "……最後給妳半刻，舒默。",
  ui_story_3_9_42_dialog_content = "（日蝕語）去吧，同胞們。",
  ui_story_3_9_43_dialog_content = "陣仗這麼大嗎？",
  ui_story_3_9_44_dialog_content = "還遠遠不夠呢。暗鬼傳來消息，妳向孟德爾頌奪來的「玩具」被擊倒了哦……",
  ui_story_3_9_45_dialog_content = "被那個臨空者號的主人——你的同族。",
  ui_story_3_9_47_dialog_content = "這樣不是更好嗎？破解我要的資訊後，我會連他們一起收拾掉。",
  ui_story_3_9_48_dialog_content = "舊帳隨時都能算，但計劃就是計劃，舒默。小心節外生枝。",
  ui_story_3_9_50_dialog_content = "你覺得我能忍耐嗎？……當年的漏網之魚如今近在咫尺，你叫我忍耐？",
  ui_story_3_9_51_dialog_content = "我討厭混亂、無序、臨時起意。",
  ui_story_3_9_52_dialog_content = "而且我不喜歡鬥爭，對那種低級嗜好沒有興趣。",
  ui_story_3_9_53_dialog_content = "……",
  ui_story_3_9_54_dialog_content = "好了，討論到此為止。",
  ui_story_3_9_56_dialog_content = "塔巴德！",
  ui_story_3_9_57_dialog_content = "我已在黑暗中靜候多時了……需要我出手嗎，主人？",
  ui_story_3_9_58_dialog_content = "你自己看著辦吧。",
  ui_story_3_9_59_dialog_content = "是……主人。",
  ui_story_3_9_61_dialog_content = "我會親手將他們撕成碎片，他們微弱的光亮終會滅於無盡黑暗……",
  ui_story_3_9_A12_dialog_content = "PlayerName，你感覺到了嗎？暗鬼們似乎都在往我們這裡……",
  ui_story_3_9_A13_dialog_content = "嗯，正不斷湧過來呢。但這種程度的敵人是絕對無法阻止我們的，不是嗎？",
  ui_story_3_9_A14_dialog_content = "當然。繼續前進吧，把沿途的暗鬼都清理乾淨！！",
  ui_story_3_12_2_dialog_content = "我們到了。",
  ui_story_3_12_3_dialog_content = "就是這裡嗎？存放「智庫組件」的地方……",
  ui_story_3_12_4_dialog_content = "前面就是了……小心舒默……",
  ui_story_3_12_5_dialog_content = "孟德爾頌，讓我們一起結束這一切吧！",
  ui_story_3_12_6_dialog_content = "謝謝你，PlayerName！我們一起阻止……",
  ui_story_3_12_7_dialog_content = "你的呼吸……孟德爾頌，你冷靜一下，你的身體……",
  ui_story_3_12_9_dialog_content = "……別在意。是<color=#FFB400>黑暗的力量</color>……我無法控制，它已經擴散到全身了。",
  ui_story_3_12_10_dialog_content = "這、這是怎麼回事？",
  ui_story_3_12_12_dialog_content = "為了生存……十七年前的那天，我為了活下去，接受<color=#FFB400>暗鬼的力量</color>……",
  ui_story_3_12_A1_dialog_content = "<color=#FFB400>就像舒默一樣</color>。只不過，我的軀體卻漸漸在崩潰……",
  ui_story_3_12_A2_dialog_content = "是因為「信仰」不夠堅定嗎？還是我本來就排斥著如此的「苟活」……",
  ui_story_3_12_15_dialog_content = "孩子，這明明只是剎那的痛苦……不要做會令你後悔的決定。",
  ui_story_3_12_16_dialog_content = "老師……對不起，已經晚了。我，我要活下去……",
  ui_story_3_12_17_dialog_content = "為了活下去，而接受暗鬼的力量？為什麼……",
  ui_story_3_12_18_dialog_content = "諷刺嗎？就算變成了這種怪物，我仍然恪守著「守祕者」的職責……",
  ui_story_3_12_A3_dialog_content = "我到底應該算什麼……我到底，是誰……",
  ui_story_3_12_A4_dialog_content = "還有機會。只要擊敗舒默，我一定會為你找到復原的方法！",
  ui_story_3_12_A5_dialog_content = "沒用了，已經太晚了……命運果真神祕莫測。",
  ui_story_3_12_19_dialog_content = "此前我靠著黑暗的力量，藏身在這暗無天日的地底沉睡多年……",
  ui_story_3_12_20_dialog_content = "而這一次，我本以為自己會像從前一樣，再次懦弱地逃離。",
  ui_story_3_12_21_dialog_content = "躲在某個陰暗的角落裡，繼續任由這無趣的生命延續下去……",
  ui_story_3_12_22_dialog_content = "然而我遇見了你們！或許我也應該勇敢一次……",
  ui_story_3_12_23_dialog_content = "這次我不會再逃避了！讓我們一起在支離破碎的命運中，拯救未來！",
  ui_story_3_13_1_dialog_content = "<color=#e8d9bb>守祕者號遺跡外</color>",
  ui_story_3_13_2_dialog_content = "塔巴德，他們到了嗎？",
  ui_story_3_13_3_dialog_content = "三個不安的靈魂。其中一個如風中殘燭，奄奄一息。",
  ui_story_3_13_4_dialog_content = "好。你隨意處理吧。",
  ui_story_3_13_5_dialog_content = "遵命。願母親見證，我將毫無保留。極光之下，唯有「日蝕」永存。",
  ui_story_3_13_6_dialog_content = "就是這傢伙嗎？",
  ui_story_3_13_8_dialog_content = "來得太晚了……你們錯過很多精彩的演出。",
  ui_story_3_13_9_dialog_content = "竟然，只有這一隻？！！",
  ui_story_3_13_10_dialog_content = "塔巴德一人足矣。",
  ui_story_3_13_11_dialog_content = "足矣？",
  ui_story_3_13_12_dialog_content = "PlayerName……空裔餘孽，你和這個光靈不一樣，明明有更適合你的道路。",
  ui_story_3_13_13_dialog_content = "你怎麼會知道PlayerName的名字？",
  ui_story_3_13_14_dialog_content = "因為我們擁有所有的知識、視界和未來。\nPlayerName，這不是你一直以來嚮往的嗎？",
  ui_story_3_13_15_dialog_content = "不必掩飾，PlayerName。我很清楚你們空裔心中的渴求，你渴望這些……",
  ui_story_3_13_16_dialog_content = "PlayerName？",
  ui_story_3_13_17_dialog_content = "你渴望擁有強大的力量，而不是只站在這些羸弱光靈的身後……",
  ui_story_3_13_18_dialog_content = "我……",
  ui_story_3_13_19_dialog_content = "靠近一些，對，再近一點。你也來，像我的主人一樣，<color=#FFB400>擁抱日蝕吧</color>！",
  ui_story_3_13_20_dialog_content = "日蝕？ ？",
  ui_story_3_13_21_dialog_content = "休想！！！",
  ui_story_3_13_22_dialog_content = "……失勢的喪家犬，又夾著尾巴回來了。",
  ui_story_3_13_23_dialog_content = "是看到了最不想見的亡魂嗎？你的主人呢？那個人呢！",
  ui_story_3_13_A1_dialog_content = "（「智庫組件」和舒默都不在！）",
  ui_story_3_13_24_dialog_content = "這倒是出乎我意料，孟德爾頌。",
  ui_story_3_13_25_dialog_content = "像骯髒的小狗一樣躲藏在巨像裡，眼睜睜看著族人被殺而不敢站出來的你……",
  ui_story_3_13_26_dialog_content = "封閉了意識，不願面對現實的你，竟然也有主動想面對那位大人的一天。",
  ui_story_3_13_27_dialog_content = "可惜，瞧你顫抖的樣子，就連指尖都透露出脆弱和無助，真是惹人發笑。",
  ui_story_3_13_28_dialog_content = "閉上你的臭嘴，離孟德爾頌遠一點！",
  ui_story_3_13_29_dialog_content = "你沒事吧！",
  ui_story_3_13_30_dialog_content = "抱歉，看、看來，真正的罪魁禍首已經逃走了……",
  ui_story_3_13_31_dialog_content = "就連「智庫組件」也被拿走——唔！我快要，到極限了……",
  ui_story_3_13_32_dialog_content = "不行……還有一件事，我必須完成……",
  ui_story_3_13_33_dialog_content = "請先休息一下，接下來的事情交給我們就好！",
  ui_story_3_13_34_dialog_content = "有趣，將死之人同情將死之人。",
  ui_story_3_13_35_dialog_content = "PlayerName！不要多想！",
  ui_story_3_13_36_dialog_content = "戰鬥的指揮——就交給你了！",
  ui_story_3_13_37_dialog_content = "結束了嗎……",
  ui_story_3_13_38_dialog_content = "<color=#e8d9bb>此刻，周圍只有一片異樣的沉默。</color>",
  ui_story_3_13_39_dialog_content = "不，不對，黑暗的力量在凝聚！小心他的攻擊！",
  ui_story_3_13_40_dialog_content = "塔巴德不會在此終結！為了偉大的使命，看看塔巴德的覺悟吧！！",
  ui_story_3_13_41_dialog_content = "黑暗，吞噬那個空裔——！！！",
  ui_story_3_13_42_dialog_content = "糟糕，衝著我來了……！",
  ui_story_3_13_43_dialog_content = "啟光拼命保護的人，絕不會讓你輕易傷害！！",
  ui_story_3_13_44_dialog_content = "說得好，中尉！！",
  ui_story_3_13_45_dialog_content = "<color=#e8d9bb>嘖——！</color>",
  ui_story_3_13_F1_dialog_content = "嘎啊！！！",
  ui_story_3_13_46_dialog_content = "長、長官！",
  ui_story_3_13_47_dialog_content = "看來，我來的正是時候。",
  ui_story_3_13_48_dialog_content = "（日蝕語）……低……低賤、污穢、無知……弱……者……垃……",
  ui_story_3_13_49_dialog_content = "暗鬼……消散成櫻花？",
  ui_story_3_13_50_dialog_content = "感謝您的馳援！",
  ui_story_3_13_51_dialog_content = "薇絲中尉，妳的行動嚴重破壞了啟光的紀律，妳知道這是很危險的行為嗎？",
  ui_story_3_13_52_dialog_content = "……",
  ui_story_3_13_53_dialog_content = "薇絲中尉！",
  ui_story_3_13_54_dialog_content = "在！",
  ui_story_3_13_55_dialog_content = "回去撰寫一篇至少五千字的報告，關於這座巨像，還有這位無法戰鬥的空裔。",
  ui_story_3_13_56_dialog_content = "是能操縱巨像、擅長指揮作戰的空裔！",
  ui_story_3_13_57_dialog_content = "不要重複我已經知道的事情。",
  ui_story_3_13_58_dialog_content = "<color=#e8d9bb>匡——！</color>",
  ui_story_3_13_59_dialog_content = "孟德爾頌，你的身體！",
  ui_story_3_13_60_dialog_content = "糟了！難道說他……",
  ui_story_3_13_61_dialog_content = "看來……我的結局已經註定……我要為自己當年的選擇負責。",
  ui_story_3_13_62_dialog_content = "不……我們能救你！薇絲，對吧？！",
  ui_story_3_13_63_dialog_content = "PlayerName，我……",
  ui_story_3_13_64_dialog_content = "沒關係。這是我的選擇，我……將走向早該面對的死亡……",
  ui_story_3_13_A2_dialog_content = "現在有比我的存亡更重要的事，PlayerName。",
  ui_story_3_13_A3_dialog_content = "事情已經走到這步，我也沒必要再守護這個祕密了……",
  ui_story_3_13_65_dialog_content = "還記得之前我提到的「智庫組件」嗎？<color=#FFB400>接下來的話你一定要記住</color>……",
  ui_story_3_13_A4_dialog_content = "本來，所有巨像各有所長，但皆沒有直接參與戰鬥的能力。",
  ui_story_3_13_A5_dialog_content = "除了吞噬者號……他是唯一一座理論上具有攻擊能力的巨像！",
  ui_story_3_13_66_dialog_content = "萬幸的是，現在的他並不是完整的。",
  ui_story_3_13_67_dialog_content = "而他的主人——舒默，正在尋求補全巨像的辦法。她需要：",
  ui_story_3_13_X67_dialog_content = "「<color=#FFB400>智庫組件</color>」",
  ui_story_3_13_X68_dialog_content = "「<color=#FFB400>自長單元</color>」",
  ui_story_3_13_X69_dialog_content = "「<color=#FFB400>火控模組</color>」",
  ui_story_3_13_X70_dialog_content = "……這三個組件。",
  ui_story_3_13_A6_dialog_content = "而她之所以先尋找「智庫組件」，就是因為它能揭示接下來兩個組件的位置！",
  ui_story_3_13_68_dialog_content = "為了獲得凌駕一切的力量，舒默一定會不惜一切代價奪到它們……",
  ui_story_3_13_69_dialog_content = "可是她已經拿走你的「智庫組件」！",
  ui_story_3_13_70_dialog_content = "不，她不會得逞的。那個組件有一道防護程序，只要我一死，程序就會被觸發。\n算是我給她最後的「驚喜」……",
  ui_story_3_13_71_dialog_content = "孟德爾頌，一定還有別的辦法……你先休息一下！等你恢復健康，我們還會有很多時間！",
  ui_story_3_13_72_dialog_content = "我們可以一起阻止舒默！還可以一起回家鄉！",
  ui_story_3_13_73_dialog_content = "我還沒去過那裡，你可以跟我描述空谷的故事……",
  ui_story_3_13_74_dialog_content = "可惜、不行了，就讓臨空者號告訴你吧……或者，你可以找到其他的同胞……",
  ui_story_3_13_75_dialog_content = "不！孟德爾頌！",
  ui_story_3_13_A7_dialog_content = "安靜，聽我說，時間不多了……",
  ui_story_3_13_76_dialog_content = "我走後，舒默應該會去<color=#FFB400>白夜城</color>，光靈的「最後之都」……",
  ui_story_3_13_A8_dialog_content = "因為那裡還有一個「智庫組件」！是的，唯獨這個組件，不止一個……",
  ui_story_3_13_A9_dialog_content = "一定要讓白夜城的人知道這個威脅，PlayerName……",
  ui_story_3_13_A10_dialog_content = "那裡的光靈，一定不知道「智庫組件」的，重要性……",
  ui_story_3_13_77_dialog_content = "孟德爾頌！求求你！別留下我一個人啊！",
  ui_story_3_13_78_dialog_content = "PlayerName，我也很想和你，還有新朋友們一起……",
  ui_story_3_13_79_dialog_content = "不過這一次我不想再逃避了。舒默，她不會得逞的……",
  ui_story_3_13_80_dialog_content = "起碼我的「智庫組件」，她休想拿到手……她將會收到「膽小鬼」的……反抗！",
  ui_story_3_13_81_dialog_content = "孟德爾頌……",
  ui_story_3_13_82_dialog_content = "好美啊……",
  ui_story_3_13_83_dialog_content = "……",
  ui_story_3_13_84_dialog_content = "那隻龍……好特別。",
  ui_story_3_13_F2_dialog_content = "那是緋長官的<color=#FFB400>櫻龍</color>。",
  ui_story_3_13_F3_dialog_content = "原來世界上還有這種……顏色，好想看到更多……",
  ui_story_3_13_85_dialog_content = "這些年……我一直躲在黑暗中，都快要忘記天空的顏色了……",
  ui_story_3_13_86_dialog_content = "PlayerName！緋長官！難道沒有辦法了嗎！難道真的要眼睜睜地看著他……",
  ui_story_3_13_F4_dialog_content = "……",
  ui_story_3_13_F5_dialog_content = "……",
  ui_story_3_13_87_dialog_content = "PlayerName，好想再和你多說說話……臨空者號，好想像從前一樣，和大家一起……",
  ui_story_3_13_88_dialog_content = "好想再看一眼……天空……",
  ui_story_3_13_89_dialog_content = "臨空者！",
  ui_story_3_13_90_dialog_content = "在，PlayerName。",
  ui_story_3_13_91_dialog_content = "感應！讓孟德爾頌與你建立感應！把天空……展示給他看……",
  ui_story_3_13_92_dialog_content = "……是。",
  ui_story_3_13_93_dialog_content = "啊，久違的……藍天……",
  ui_story_3_13_94_dialog_content = "孟德爾頌！讓我與你分享我的臨空者號！",
  ui_story_3_13_95_dialog_content = "現在以及未來，他會永遠做你在世間的雙耳與眼眸，盡收雲端之上的光景……",
  ui_story_3_13_96_dialog_content = "這就是……死亡嗎……和想像中，稍微有些……不一樣呢……好孤獨……",
  ui_story_3_13_97_dialog_content = "我在，主人。",
  ui_story_3_13_98_dialog_content = "這個聲音是？！",
  ui_story_3_13_99_dialog_content = "我們都在。",
  ui_story_3_13_100_dialog_content = "主人，吾等將陪您走到最後。",
  ui_story_3_13_101_dialog_content = "樊尼……菲……萊……克……",
  ui_story_3_13_103_dialog_content = "孟德爾頌！",
  ui_story_3_13_104_dialog_content = "……",
  ui_story_3_13_105_dialog_content = "……",
  ui_story_3_13_106_dialog_content = "<size=45>舒默……妳收到這份「驚喜」了嗎？</size>",
  ui_story_3_13_107_dialog_content = "嗯？",
  ui_story_3_13_108_dialog_content = "「智庫組件」……<color=#FFB400>在衰變</color>？！糟了！！",
  ui_story_3_13_110_dialog_content = "<anim type=Shake>孟、德、爾、頌——</anim>",
  ui_story_3_13_111_dialog_content = "真是難看啊，舒默。看來事情的變化超出了預期呢。",
  ui_story_3_13_112_dialog_content = "沒想到孟德爾頌竟敢來這一招……這東西已經沒用了。",
  ui_story_3_13_113_dialog_content = "那個膽小鬼、那個雜魚，竟敢……",
  ui_story_3_13_114_dialog_content = "哈哈，哈哈哈哈，不愧是我的兄弟！",
  ui_story_3_13_115_dialog_content = "虧我這麼多年來一直把他當作懦弱的傢伙，沒想到他竟然有勇氣在死前暗算我。",
  ui_story_3_13_116_dialog_content = "不要告訴我，你什麼資訊都沒有得到。",
  ui_story_3_13_118_dialog_content = "雖然只有隻字片語，但我的確發現新的情報……",
  ui_story_3_13_120_dialog_content = "<color=#FFB400>白夜城</color>還有同樣的「智庫組件」。",
  ui_story_3_13_121_dialog_content = "而且那些愚蠢的光靈，似乎並不知道它的重要性……",
  ui_story_3_13_122_dialog_content = "白夜城可不能隨便進去。讓我想想，要怎麼幫你收拾這爛攤子……",
  ui_story_3_13_123_dialog_content = "看著吧，孟德爾頌，用你無法瞑目的雙眼好好看著，沒人能阻止我的補完……",
  ui_story_3_13_124_dialog_content = "我會讓你明白，你做的這些沒有任何意義。",
  ui_story_3_14_A2_dialog_content = "<color=#e8d9bb>白夜城·資料館</color>",
  ui_story_3_14_1_dialog_content = "哎唷……今天又有這麼多的東西。",
  ui_story_3_14_2_dialog_content = "真是的，亂七八糟什麼都有……啊？這是……",
  ui_story_3_14_3_dialog_content = "<color=#e8d9bb>匡啷！</color>",
  ui_story_3_14_4_dialog_content = "唉唷！",
  ui_story_3_14_5_dialog_content = "你沒事吧？砸到哪裡了？",
  ui_story_3_14_6_dialog_content = "我沒事。你在幹嘛阿，這些東西都搬不好！",
  ui_story_3_14_7_dialog_content = "對、對不起，我今天第一次……",
  ui_story_3_14_8_dialog_content = "哎呀！這！這！你怎麼？！",
  ui_story_3_14_9_dialog_content = "對不起，真的對不起，我不是故意的……",
  ui_story_3_14_10_dialog_content = "你！怎麼偏偏把<color=#FFB400>它</color>摔了！這東西很貴重！",
  ui_story_3_14_11_dialog_content = "這……我這就去撿。",
  ui_story_3_14_12_dialog_content = "還是我來吧，雖然不知道它究竟是什麼，但一看就是值錢的東西。",
  ui_story_3_14_13_dialog_content = "一陣腳步聲。",
  ui_story_3_14_14_dialog_content = "你們！不要在執勤時交頭接耳！專心做自己的工作！",
  ui_story_3_14_15_dialog_content = "中隊長！我、我們正在整理資料館的物品，工作剛剛進行到一半……",
  ui_story_3_14_16_dialog_content = "這裡不用你們了，離開吧。",
  ui_story_3_14_17_dialog_content = "是！中隊長！",
  ui_story_3_14_18_dialog_content = "是！中隊長！",
  ui_story_3_14_A1_dialog_content = "……沒有錯，這個東西和<color=#FFB400>那位大人</color>描述的一樣。",
  ui_story_3_14_19_dialog_content = "你很貴重，但是白夜城的大人們只把你當古董……",
  ui_story_3_14_20_dialog_content = "而你的<color=#FFB400>真正價值</color>，會有人知曉的……",
  ui_story_3_14_B1_dialog_content = "中隊長！長官叫我們去報到了！",
  ui_story_3_14_B2_dialog_content = "……",
  ui_story_3_14_B3_dialog_content = "知道了，走吧。",
  ui_story_4_1_1_dialog_content = "「<color=#FFB400>智庫組件</color>」，「<color=#FFB400>自長單元</color>」，「<color=#FFB400>火控模組</color>」……可是它們都長什麼樣子呢？",
  ui_story_4_1_2_dialog_content = "孟德爾頌提供的資訊太少了，就算知道另一個「智庫組件」在白夜城……",
  ui_story_4_1_3_dialog_content = "會不會是另一座巨像？",
  ui_story_4_1_4_dialog_content = "無論對方的計劃是什麼，我們都一定要趕在她之前！",
  ui_story_4_1_5_dialog_content = "我們直奔白夜城嗎？然後呢？",
  ui_story_4_1_6_option_content = "見招拆招！",
  ui_story_4_1_7_option_content = "說實話，我還沒想好",
  ui_story_4_1_8_dialog_content = "這聽起來一點也不可靠，PlayerName……",
  ui_story_4_1_9_dialog_content = "我們完全不瞭解目前的對手。對方的實力、目的，甚至是樣貌我們都不知道。",
  ui_story_4_1_10_dialog_content = "竟然這麼誠實……",
  ui_story_4_1_11_dialog_content = "不過，在完全不瞭解對手的情況下，我們也無法制定任何戰略。",
  ui_story_4_1_12_dialog_content = "對方的實力、目的，甚至連樣貌我們都不知道。",
  ui_story_4_1_13_dialog_content = "況且白夜城跟我們啟光不一樣，是……是很麻煩的地方……",
  ui_story_4_1_14_dialog_content = "<color=#e8d9bb>薇絲的臉上露出了為難的表情，彷彿想到了什麼讓人頭痛的情景。</color>",
  ui_story_4_1_15_dialog_content = "但是，PlayerName，既然你是導航員，還是你來決定吧。",
  ui_story_4_1_16_dialog_content = "我還是想去白夜城一探究竟。",
  ui_story_4_1_17_dialog_content = "薇絲，我知道這個決定或許過於冒險，但是…",
  ui_story_4_1_18_dialog_content = "這是關於十七年前真相的唯一一條線索……",
  ui_story_4_1_19_dialog_content = "好吧……但是！我要先向緋長官報告。這件事可比你想的要困難許多……",
  ui_story_4_1_20_dialog_content = "看來，妳還沒有忘記自己的長官。",
  ui_story_4_1_21_dialog_content = "咿呀！長官還在嗎！",
  ui_story_4_1_22_dialog_content = "我一直在，薇絲中尉。\nPlayerName，你同族的事情我深感遺憾，但攸關白夜城的情報還需謹慎對待。",
  ui_story_4_1_23_dialog_content = "慎重對待……的意思是？",
  ui_story_4_1_24_dialog_content = "未經調查，孟德爾頌的話不能成為證據。\n何況高級暗鬼已經出現多次，我建議你們最好不要貿然行動。",
  ui_story_4_1_25_dialog_content = "可是我們沒有時間了。如果真的發生什麼……臨空者號！他可以保護我們！",
  ui_story_4_1_26_dialog_content = "……恕我直言，PlayerName。",
  ui_story_4_1_27_dialog_content = "我早就注意到你的巨像，也從卡戎那裡得到了基本資料。",
  ui_story_4_1_A1_dialog_content = "按照以前的巨像評級標準……",
  ui_story_4_1_28_dialog_content = "你的臨空者號，是<color=#FFB400>第六級</color>。",
  ui_story_4_1_29_dialog_content = "……",
  ui_story_4_1_30_dialog_content = "哦？這麼高嗎。不愧是臨空者號。",
  ui_story_4_1_31_dialog_content = "最高是一級。數字越大性能越差。",
  ui_story_4_1_32_dialog_content = "……？",
  ui_story_4_1_33_dialog_content = "那最低是幾級？",
  ui_story_4_1_34_dialog_content = "<color=#FFB400>六級</color>。",
  ui_story_4_1_35_dialog_content = "……？！",
  ui_story_4_1_36_dialog_content = "臨空者！！你不是說你是「天空級」巨像嗎？！",
  ui_story_4_1_37_dialog_content = "那是為了給你活下去的信心，這只不過是一個必要的謊言罷了。",
  ui_story_4_1_A2_dialog_content = "而且從來就沒有「天空級」這種設定。",
  ui_story_4_1_38_dialog_content = "你竟然如此輕率地欺騙我！",
  ui_story_4_1_39_dialog_content = "六級巨像只有維生、裝載和運輸的功能……",
  ui_story_4_1_40_dialog_content = "擅長完成「逃跑」任務。",
  ui_story_4_1_41_dialog_content = "不用再說了……",
  ui_story_4_1_42_dialog_content = "PlayerName看起來相當失落呢……",
  ui_story_4_1_43_dialog_content = "看樣子是我多言了……你也無需灰心，PlayerName。",
  ui_story_4_1_44_dialog_content = "作為空裔，你擁有獨一無二的天賦和出色的指揮才能。我並未懷疑這一點。",
  ui_story_4_1_45_dialog_content = "而且薇絲中尉這麼看好你，想必你確實值得信賴。",
  ui_story_4_1_46_dialog_content = "欸？",
  ui_story_4_1_47_dialog_content = "謝謝長官，我……會努力的。",
  ui_story_4_1_48_dialog_content = "那我們出發吧！舒默肯定已經開始行動，我們也必須加快腳步！",
  ui_story_4_1_49_dialog_content = "好！長官，請問可以提供前往白夜城的通關文件給我們嗎？",
  ui_story_4_1_50_dialog_content = "不行，這個你得自己想辦法。",
  ui_story_4_1_51_dialog_content = "欸？？",
  ui_story_4_1_52_dialog_content = "很遺憾。只根據目前這些尚未驗證的情報，啟光聯邦難以採取任何官方行動——\n更何況這還涉及白夜城。",
  ui_story_4_1_54_dialog_content = "……",
  ui_story_4_1_55_dialog_content = "我記得你的履歷裡有一條「曾在白夜城留學」。也許是時候開個同學會了。",
  ui_story_4_1_56_dialog_content = "沒記錯的話，妳和白夜城那位叫「<color=#FFB400>卡蓮</color>」的衛隊隊長，似乎就是同學？",
  ui_story_4_1_57_dialog_content = "正因為這樣，才更讓人頭痛啊……唉……",
  ui_story_4_1_58_dialog_content = "<color=#e8d9bb>白夜城上空</color>",
  ui_story_4_1_59_dialog_content = "那座<color=#FFB400>漂浮在空中的城市</color>，就是目的地吧。",
  ui_story_4_1_60_dialog_content = "看來我們已經到了，乘坐巨像速度真快呢……",
  ui_story_4_1_X1_dialog_content = "薇絲，妳那身裝扮是……",
  ui_story_4_1_X2_dialog_content = "適度喬裝而已！雖然已經寄信向卡蓮說明過了，但還是得避免引人注目……",
  ui_story_4_1_X3_dialog_content = "……這樣反而會更引人注目吧。",
  ui_story_4_1_61_dialog_content = "PlayerName，你看！",
  ui_story_4_1_62_dialog_content = "那就是白夜城。",
  ui_story_4_1_64_option_content = "這就是「最後之都」嗎……",
  ui_story_4_1_65_option_content = "這座城市怎麼浮起來的……",
  ui_story_4_1_66_dialog_content = "嗯？你在自言自語什麼呢？快過來這邊，在任務開始之前我要重申一下！",
  ui_story_4_1_67_dialog_content = "從現在開始，不管發生什麼事，由我負責答話，明白嗎？",
  ui_story_4_1_68_dialog_content = "千萬不要衝動，別忘了我們必須比舒默更快找到目標！",
  ui_story_4_1_69_dialog_content = "是，薇絲中尉。妳真可靠！",
  ui_story_4_1_70_dialog_content = "嗯，讓我再檢查一下證件……真是不想面對「那個傢伙」啊……",
  ui_story_4_1_71_dialog_content = "PlayerName，我有些不安。我獨自留在這裡真的好嗎？",
  ui_story_4_1_72_dialog_content = "沒有辦法，臨空者，你也知道你有多麼顯眼。",
  ui_story_4_1_73_dialog_content = "帶著你的話，別說進入白夜城了，我們估計連城郊都別想靠近。",
  ui_story_4_1_74_dialog_content = "而且你不是六級巨像嗎？沒有辦法為我們提供任何戰鬥支持。",
  ui_story_4_1_75_dialog_content = "……還在耿耿於懷嗎。",
  ui_story_4_1_76_dialog_content = "是的，你說得沒錯，戰鬥都交給你們了。",
  ui_story_4_1_A3_dialog_content = "我會在隱蔽的空域等待你們。請一路小心。",
  ui_story_4_1_77_dialog_content = "好了，出發吧！我看入城的隊伍已經排到～～那麼長。",
  ui_story_4_1_A4_dialog_content = "唉……我真的一點都不喜歡排隊啊……",
  ui_story_4_1_78_dialog_content = "也一點都不想見到「那傢伙」啊……白夜城的衛隊長，<color=#FFB400>卡蓮·德·舒瓦茲</color>。",
  ui_story_4_1_79_dialog_content = "這位衛隊長怎麼了嗎？",
  ui_story_4_1_80_dialog_content = "哈啊……等一下你就知道了，她現在應該在城門口等著我們呢！",
  ui_story_4_1_81_dialog_content = "薇絲，妳說的衛隊長在哪裡啊？",
  ui_story_4_1_82_dialog_content = "噓——！",
  ui_story_4_1_83_dialog_content = "請各位遵守秩序，配合檢查！",
  ui_story_4_1_84_dialog_content = "持有臨時通行證的外來人員不得滯留超過二十四小時，否則白夜城將依法行使驅逐權！",
  ui_story_4_1_85_dialog_content = "若發現可疑人士，請立即向白夜城衛兵報告！",
  ui_story_4_1_86_dialog_content = "PlayerName，再重複一次，無論發生什麼事，都不要……",
  ui_story_4_1_87_dialog_content = "請不要交頭接耳！把你們的通行證拿出來！",
  ui_story_4_1_88_dialog_content = "啊、是……",
  ui_story_4_1_89_dialog_content = "又一個啟光的……前線那麼閒嗎？妳這身打扮很可疑啊，小妹妹。",
  ui_story_4_1_90_dialog_content = "……呃，這次來是辦私事。",
  ui_story_4_1_91_dialog_content = "眼神為什麼到處亂飄？第一次來白夜城？",
  ui_story_4_1_92_dialog_content = "不，我曾經是這裡的留學生。這次是以甲類通行證辦理延期……",
  ui_story_4_1_93_dialog_content = "旁邊那個傢伙呢？幾乎就要把「我是可疑分子」寫在臉上了呢。",
  ui_story_4_1_94_option_content = "我？我不久前才剛出土",
  ui_story_4_1_95_option_content = "（薇絲叫我不要說話……）",
  ui_story_4_1_96_dialog_content = "……你以為我在跟你開玩笑嗎？你的證件！一人一證，寫得清清楚楚！",
  ui_story_4_1_97_dialog_content = "我問你話呢。耳朵不好嗎？！",
  ui_story_4_1_98_dialog_content = "抱歉，這位和我是一起的。我的申請是經特殊管道核發的，請再仔細確認一下！",
  ui_story_4_1_99_dialog_content = "是你們的衛隊長卡蓮……",
  ui_story_4_1_100_dialog_content = "「衛隊長」？……啊，原來就是妳啊！",
  ui_story_4_1_101_dialog_content = "也不早說。明白了，請在這邊稍微等待一會。",
  ui_story_4_1_102_dialog_content = "呼……",
  ui_story_4_1_103_dialog_content = "還真是悠閒啊，啟光的工作這麼輕鬆嗎？",
  ui_story_4_1_104_dialog_content = "哈，<color=#FFB400>卡蓮</color>……好久不見，妳還是那麼……威風凜凜呢。",
  ui_story_4_1_105_dialog_content = "直呼衛隊長本名……這膽量倒是值得尊敬……",
  ui_story_4_1_106_dialog_content = "這位穿著奇怪的大姐姐好眼熟呀……",
  ui_story_4_1_107_dialog_content = "啊！你是卡蓮姐姐的同學吧？",
  ui_story_4_1_108_dialog_content = "拉斐爾，小聲點喔……讓衛隊長去交涉喔～",
  ui_story_4_1_109_dialog_content = "看看我們的米迦勒，一言不發非常穩重呢～",
  ui_story_4_1_110_dialog_content = "……",
  ui_story_4_1_111_dialog_content = "全都安靜。",
  ui_story_4_1_112_dialog_content = "這裡不需要這麼多人，衛隊去例行巡邏吧。",
  ui_story_4_1_113_dialog_content = "至於這兩位訪客，交給我就行了。",
  ui_story_4_1_114_dialog_content = "相信已經不必自我介紹了。",
  ui_story_4_1_115_dialog_content = "卡蓮，那我就開門見山了。我們此行是……",
  ui_story_4_1_116_dialog_content = "信件裡寫得夠詳細了。妳的文法還是和之前一樣，敬語用得一塌糊塗。",
  ui_story_4_1_117_dialog_content = "讓我再確認一次，妳的意思是，「<color=#FFB400>有暗鬼盯上了白夜城</color>」，是嗎？",
  ui_story_4_1_118_dialog_content = "這種時候竟然還要批評我的文法……",
  ui_story_4_1_A5_dialog_content = "沒錯，我們得到消息，一個名為「舒默」的傢伙正窺伺著白夜城。",
  ui_story_4_1_119_dialog_content = "我們相信她正企圖從白夜城盜走一件叫作「<color=#FFB400>智庫組件</color>」的東西。",
  ui_story_4_1_120_dialog_content = "「智庫組件」？抱歉，從未聽過。而且無論那是什麼，都休想從白夜城……",
  ui_story_4_1_122_dialog_content = "嗯？你是什​​麼人？",
  ui_story_4_1_123_dialog_content = "……我可以回答嗎？",
  ui_story_4_1_124_dialog_content = "你以為這種音量她就聽不到了嗎？",
  ui_story_4_1_125_dialog_content = "……",
  ui_story_4_1_126_dialog_content = "PlayerName是……卡蓮，我只能告訴妳一個人，請、請靠近一點……",
  ui_story_4_1_127_dialog_content = "你是說……那些偏安一隅的「自私之人」嗎？那所謂的巨像呢？",
  ui_story_4_1_128_dialog_content = "他叫臨空者號……正懸停在白夜城的上方空域，你們偵測不到。",
  ui_story_4_1_129_dialog_content = "……！",
  ui_story_4_1_130_dialog_content = "放心，是個六級巨像……「只能用來逃跑」，「毫無戰鬥能力」。",
  ui_story_4_1_131_dialog_content = "哼。",
  ui_story_4_1_132_dialog_content = "這些都不重要。卡蓮，我已經告訴妳PlayerName的身分了，請相信我們吧！",
  ui_story_4_1_133_dialog_content = "妳的證據實在太單薄……還有什麼更具說服力的嗎？",
  ui_story_4_1_134_dialog_content = "沒有了……暗鬼一定正在嘗試進入白夜城，或許就混在排隊的人群裡！",
  ui_story_4_1_137_dialog_content = "衛隊長！有緊急情況！",
  ui_story_4_1_139_dialog_content = "？！真的？",
  ui_story_4_1_140_dialog_content = "他們在說什麼？",
  ui_story_4_1_141_dialog_content = "不知道，但是我猜，應該不是什麼好消息……",
  ui_story_4_1_142_dialog_content = "薇絲，念妳是我的同學……我就姑且相信妳一次，准許你們進城。",
  ui_story_4_1_143_dialog_content = "不過我要全程跟隨你們。如果事後證明這是謊言，請接受相應的責罰！",
  ui_story_4_1_144_dialog_content = "好，我答應妳！那就快走吧！我們就先從……",
  ui_story_4_1_145_dialog_content = "從<color=#FFB400>下城區</color>開始。",
  ui_story_4_1_146_dialog_content = "下城區？",
  ui_story_4_1_147_dialog_content = "沒錯……就在剛才，下城區發生了<color=#FFB400>襲擊事件</color>。",
  ui_story_4_1_148_dialog_content = "？！",
  ui_story_4_2_1_dialog_content = "<color=#e8d9bb>下城區</color>",
  ui_story_4_2_2_dialog_content = "玩到忘記時間了，抄近路回去吧……",
  ui_story_4_2_3_dialog_content = "嗯？什麼人在那……嗚啊啊啊啊啊啊啊啊！！",
  ui_story_4_2_4_dialog_content = "吵死了。",
  ui_story_4_2_5_dialog_content = "抱歉抱歉，是我的失誤。",
  ui_story_4_2_6_dialog_content = "死沒？",
  ui_story_4_2_A1_dialog_content = "放心，已經解決掉了。",
  ui_story_4_2_7_dialog_content = "不要怨恨我，可憐的傢伙，誰叫你在這個時間跑到這裡亂晃。",
  ui_story_4_2_8_dialog_content = "運氣也是重要的生存技能啊。",
  ui_story_4_2_9_dialog_content = "你還真喜歡和這些傢伙說廢話，格茲德。",
  ui_story_4_2_A2_dialog_content = "我們這麼久沒見面，你對這傢伙說的話竟然比對我還要多！",
  ui_story_4_2_10_dialog_content = "嘶魘兒，妳永遠在我心上，我時時刻刻都在思念妳。",
  ui_story_4_2_11_dialog_content = "油嘴滑舌……先講正事，那位大人傳來消息，我們要啟用了。",
  ui_story_4_2_12_dialog_content = "現在？",
  ui_story_4_2_13_dialog_content = "沒錯，詳細計劃我會慢慢告訴你。",
  ui_story_4_2_14_dialog_content = "我已經派出小朋友們去當誘餌了，守衛很快就會被吸引到附近來，然後你趁機……",
  ui_story_4_2_15_dialog_content = "等等，所以妳真的決定了嗎？嘶魘兒，妳不必冒這麼大的風險，妳可以等我……",
  ui_story_4_2_16_dialog_content = "別說了，格茲德，別說了，就照我說的去辦。",
  ui_story_4_2_17_dialog_content = "我會在這裡纏住衛隊，然後再由你……去<color=#FFB400>盜取那個東西</color>。",
  ui_story_4_2_18_dialog_content = "……東西的位置我倒是確認好了。但就這麼簡單？",
  ui_story_4_2_19_dialog_content = "是的，就這麼簡單。這個計劃成功了，我們才能獲得想要的自由，不是嗎？",
  ui_story_4_2_20_dialog_content = "……好吧，妳永遠能輕易說服我。",
  ui_story_4_2_21_dialog_content = "報告！有居民通報遭到暗鬼襲擊！",
  ui_story_4_2_22_dialog_content = "不是同一個地點嗎？難道是團隊犯案？",
  ui_story_4_2_23_dialog_content = "卡蓮姐姐！我們來了哦！",
  ui_story_4_2_24_dialog_content = "……",
  ui_story_4_2_25_dialog_content = "請你們去東區巡邏！敵人不止一個。",
  ui_story_4_2_26_dialog_content = "收到！其他衛隊成員呢？",
  ui_story_4_2_27_dialog_content = "留在上城區了，大部分成員必須鎮守貴族們的住所……畢竟這是那個男人的命令。",
  ui_story_4_2_28_dialog_content = "<color=#FFB400>城主殿下</color>嗎……",
  ui_story_4_2_29_dialog_content = "目前報告的襲擊地點都在東區，下城區的管理者也都過去了。",
  ui_story_4_2_30_dialog_content = "而我……會去西區。我有種奇怪的直覺……",
  ui_story_4_2_31_dialog_content = "又是這個眼神，「想到什麼不得了的事然後立刻就要去做」的樣子。",
  ui_story_4_2_32_dialog_content = "妳們還是學生的時候，她也有過這種眼神嗎？",
  ui_story_4_2_33_dialog_content = "嗯。例如格鬥課她準備把我擊倒的時候。",
  ui_story_4_2_34_dialog_content = "……看來卡蓮是個非常厲害的人物呢。",
  ui_story_4_2_35_dialog_content = "恭維我沒有任何意義。走吧，去西區——你能戰鬥嗎，PlayerName？",
  ui_story_4_2_36_dialog_content = "我不能戰鬥，但我可以指揮與引導。",
  ui_story_4_2_37_dialog_content = "這話從你嘴裡說出來，多少欠缺一點可信度。",
  ui_story_4_2_38_dialog_content = "不過，我願意給你證明自己的機會。",
  ui_story_4_2_39_dialog_content = "壓力好大……",
  ui_story_4_3_1_dialog_content = "意料之外，你擁有不俗的指揮天賦。",
  ui_story_4_3_2_dialog_content = "而且……這就是光之軌跡嗎？擁有如此天賦的一族，竟在我出生前就滅絕了。",
  ui_story_4_3_3_dialog_content = "妳暴露年齡了，卡蓮小姐。",
  ui_story_4_3_4_dialog_content = "別得意忘形。現在西區也出現暗鬼了，必須保持警惕。",
  ui_story_4_3_5_dialog_content = "暗鬼的數量，比想像中還多啊……",
  ui_story_4_3_6_option_content = "白夜城不是「永不淪陷」嗎？",
  ui_story_4_3_7_option_content = "城門的衛兵沒辦法抵禦暗鬼嗎？",
  ui_story_4_3_8_dialog_content = "「永不淪陷」指的是上城區，而不是下城區……",
  ui_story_4_3_9_dialog_content = "衛兵當然有作用，只不過保衛的大部分都是上城區，而不是下城區。",
  ui_story_4_3_10_dialog_content = "我們目前所在的下城區，一切只能靠自己。對吧，卡蓮大人？",
  ui_story_4_3_F1_dialog_content = "……",
  ui_story_4_3_11_dialog_content = "下城區和上城區的待遇，差別竟然這麼大？",
  ui_story_4_3_12_dialog_content = "沒辦法，這就是「白夜城」啊……",
  ui_story_4_3_13_dialog_content = "抱歉來遲了……中隊長格茲德向您報到。",
  ui_story_4_3_14_dialog_content = "有異常情況嗎？",
  ui_story_4_3_15_dialog_content = "一切正常，衛隊長。",
  ui_story_4_3_16_dialog_content = "召集人手，先引導城內居民避難！同時封鎖下城區出入口！",
  ui_story_4_3_17_dialog_content = "已經都完成了，衛隊長。",
  ui_story_4_3_18_dialog_content = "動作很快！那接下來，請你跟我們一起——",
  ui_story_4_3_19_dialog_content = "恕屬下無禮，但還有很多民眾被封鎖在城外，必須接引入城。",
  ui_story_4_3_20_dialog_content = "否則那些人會暴露在暗鬼的威脅下。",
  ui_story_4_3_21_dialog_content = "……好。那你去吧，留一些人手給我！",
  ui_story_4_3_22_dialog_content = "那屬下先告退了。白夜至上。",
  ui_story_4_3_23_dialog_content = "卡蓮，剛才那位是……？",
  ui_story_4_3_24_dialog_content = "下城區的中隊長之一，許多防務都是由他負責，辦事效率一直都很高。",
  ui_story_4_3_25_dialog_content = "畢竟……曾經也算是位<color=#FFB400>有名的騎士</color>呢。",
  ui_story_4_3_26_dialog_content = "果然人不可貌相……",
  ui_story_4_3_27_dialog_content = "好了，我們也繼續吧。似乎還有不少漏網的暗鬼在下城區到處滋事。",
  ui_story_4_3_28_dialog_content = "而且我也很想見見，你們提到的那個「<color=#FFB400>舒默</color>」。",
  ui_story_4_6_1_dialog_content = "報告！東區已全部清理完畢！",
  ui_story_4_6_2_dialog_content = "衛隊長，西區有新的目擊報告！似乎是高級暗鬼！！",
  ui_story_4_6_3_dialog_content = "果然！在哪裡，報告位置！！",
  ui_story_4_6_4_dialog_content = "剛才那些都是障眼法嗎？「智庫組件」一定就在高級暗鬼附近！",
  ui_story_4_6_5_dialog_content = "看來沒落後太多！",
  ui_story_4_6_6_dialog_content = "因為我們這邊可是有直覺敏銳的卡蓮呢！",
  ui_story_4_6_7_dialog_content = "……",
  ui_story_4_6_8_dialog_content = "嗚啊，又是那種眼神……怎麼了，有什麼不對勁嗎？",
  ui_story_4_6_9_dialog_content = "……不知道，但我不喜歡這種感覺……無論如何，先前進吧！",
  ui_story_4_6_10_dialog_content = "嘶魘兒！我們必須中止計劃！",
  ui_story_4_6_11_dialog_content = "你在說什麼？那個小公主——卡蓮·德·舒瓦茲，已經被我引到這邊來了！",
  ui_story_4_6_12_dialog_content = "都已經這種時候了，你說要中止？格茲德，我不想為了這個跟你吵架。",
  ui_story_4_6_13_dialog_content = "除了卡蓮，還有啟光的小鬼！他們好像也是來尋找「智庫組件」的！",
  ui_story_4_6_14_dialog_content = "再說，資料館的大門很難解鎖，我不知道還來不來得及……",
  ui_story_4_6_15_dialog_content = "不、不行，我們不能因為這些小鬼就停手！",
  ui_story_4_6_16_dialog_content = "我絕對……絕對不允許……",
  ui_story_4_6_17_dialog_content = "那我們要怎麼做？",
  ui_story_4_6_18_dialog_content = "我會幫你拖延更多的時間！",
  ui_story_4_6_19_dialog_content = "<color=#FFB400>夏爾</color>……對了，我可以把夏爾喚醒，讓她和我一起……",
  ui_story_4_6_20_dialog_content = "不可以！嘶魘兒，不管妳在想什麼，我都不允許！",
  ui_story_4_6_21_dialog_content = "夏爾——妳的妹妹，已經是個無法控制的瘋子了！",
  ui_story_4_6_22_dialog_content = "瘋子？呵……我又何嘗不是呢？",
  ui_story_4_6_23_dialog_content = "格茲德，離開這裡吧。去你該去的地方，別讓我失望。",
  ui_story_4_6_24_dialog_content = "……我在約定的地方等妳，嘶魘兒。",
  ui_story_4_6_25_dialog_content = "妳對一名騎士許下了諾言，妳會遵守的，對吧？",
  ui_story_4_6_26_dialog_content = "當然，格茲德。無論發生什麼事，我一定會遵守我們的約定……",
  ui_story_4_6_27_dialog_content = "夏爾，妳睡飽了嗎？醒醒，姐姐帶妳……出去玩。",
  ui_story_4_6_28_dialog_content = "玩、玩——",
  ui_story_4_7_1_dialog_content = "<color=#e8d9bb>下城區·街巷內</color>",
  ui_story_4_7_2_dialog_content = "衛隊長，前面剛發現一具屍體。經確認，是負責守衛下城區的衛兵。",
  ui_story_4_7_3_dialog_content = "傷口只有一處……被人一擊刺穿了心臟……",
  ui_story_4_7_4_dialog_content = "全體衛兵！原地搜查，我絕對不會讓任何東西傷害我的城民！",
  ui_story_4_7_5_dialog_content = "「<color=#FFB400>我的城民</color>」？",
  ui_story_4_7_6_dialog_content = "唔，說起來，卡蓮確實很關愛城民……",
  ui_story_4_7_7_dialog_content = "不，我的疑問點是，「<color=#FFB400>我的</color>」？",
  ui_story_4_7_8_dialog_content = "啊……我沒提過嗎？卡蓮她啊……可是<color=#FFB400>白夜城城主的女兒</color>哦。",
  ui_story_4_7_9_dialog_content = "？？？",
  ui_story_4_7_10_dialog_content = "抱歉抱歉，事情太多，一時忘了告訴你……",
  ui_story_4_7_11_dialog_content = "但至少現在的她，是「白夜城衛隊長」。",
  ui_story_4_7_13_dialog_content = "唔啊！什麼聲音！ ？",
  ui_story_4_7_14_dialog_content = "衛兵！全速前往聲音來源偵查！！",
  ui_story_4_7_16_dialog_content = "第一次……以這模樣示人呢。",
  ui_story_4_7_17_dialog_content = "那是……一座民宅被炸毀了？",
  ui_story_4_7_18_dialog_content = "這個人不對勁！卡蓮、PlayerName，小心！",
  ui_story_4_7_19_dialog_content = "……妳是……嘶魘兒？",
  ui_story_4_7_20_dialog_content = "沒想到啊，小公主，我這輩子還有和妳平等對視的一天……",
  ui_story_4_7_21_dialog_content = "怎麼樣？這幅皮囊和原本相比，哪個更好看？",
  ui_story_4_7_22_dialog_content = "卡蓮，妳們認識？",
  ui_story_4_7_23_dialog_content = "嗯，很久以前。只不過是一個背棄了自己信仰的可憐蟲罷了。",
  ui_story_4_7_24_dialog_content = "「可憐蟲」嗎……沒錯，我的確是。",
  ui_story_4_7_25_dialog_content = "在大人們的眼裡，我連上城區的蟲子都比不上啊。的確可憐……",
  ui_story_4_7_26_dialog_content = "妳會淪落至此是因為自甘墮落！",
  ui_story_4_7_27_dialog_content = "看看現在的妳……我簡直找不到可以用來形容那副模樣的話語。",
  ui_story_4_7_28_dialog_content = "是我自己的墮落嗎？小公主，如果妳沒有誕生在那高貴的產床上，妳又是什麼呢？",
  ui_story_4_7_29_dialog_content = "如果妳也生在發霉的稻草上，妳……又是什麼呢？",
  ui_story_4_7_30_dialog_content = "……",
  ui_story_4_7_31_dialog_content = "回答不出來吧。如此輕易地用「自甘墮落」來解釋一切，不愧是傲慢的公主。",
  ui_story_4_7_32_dialog_content = "嘶魘兒，還記得上次我跟妳說的話嗎？",
  ui_story_4_7_33_dialog_content = "以白夜之名起誓，倘若妳膽敢再踏入這裡半步，我將以此槍執行正義！",
  ui_story_4_7_34_dialog_content = "今天我就要兌現誓言了。",
  ui_story_4_7_35_dialog_content = "其實我從未離開過呀。我一直在妳的眼皮底下，在聖光無法照耀的角落裡……",
  ui_story_4_7_36_dialog_content = "很驚訝吧？不僅如此，我還擁有了許多的「朋友」。",
  ui_story_4_7_37_dialog_content = "什麼……？！",
  ui_story_4_7_38_dialog_content = "我的「妹妹」啊，我可愛的夏爾，來到我的身邊吧！",
  ui_story_4_7_39_dialog_content = "姐、姐姐……夏爾想、想……",
  ui_story_4_7_40_dialog_content = "想要「玩」是嗎？真拿妳沒辦法啊～",
  ui_story_4_7_41_dialog_content = "來吧，我們一起和對面那位可愛的小公主，好好地「玩玩」吧～",
  ui_story_4_7_42_dialog_content = "……玩——！",
  ui_story_4_7_43_dialog_content = "小心——！",
  ui_story_4_7_44_dialog_content = "可惡啊啊啊！為什麼！為什麼！你——！！",
  ui_story_4_7_45_dialog_content = "你是誰？！為什麼你可以引導、可以指揮她們？！",
  ui_story_4_7_46_dialog_content = "你是……空裔？！",
  ui_story_4_7_47_dialog_content = "……",
  ui_story_4_7_48_dialog_content = "不好玩……不好玩！！姐姐，離開這裡……",
  ui_story_4_7_49_dialog_content = "不，他還需要時間，我們不能……也不可能就此作罷！",
  ui_story_4_7_50_dialog_content = "你，還有白夜城的走狗們，有膽就追上來試試看！！",
  ui_story_4_7_51_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_4_7_53_dialog_content = "咳咳咳……糟糕！<color=#FFB400>她們逃走了</color>！",
  ui_story_4_7_54_dialog_content = "上城區！她們逃竄的方向是上城區！！",
  ui_story_4_7_55_dialog_content = "拉響警報！通知全體衛隊成員！迅速回防上城區！",
  ui_story_4_7_56_dialog_content = "PlayerName！快！我們也跟上！",
  ui_story_4_8_1_dialog_content = "<color=#e8d9bb>遠離上城區的白夜城資料館中</color>",
  ui_story_4_8_2_dialog_content = "左旋……三度……右旋……十四度……再……",
  ui_story_4_8_3_dialog_content = "又卡住了……這到底是什麼加密法？！上次沒留下後門真是失算……",
  ui_story_4_8_4_dialog_content = "乾脆直接用炸彈……不、不行，萬一傷到組件……",
  ui_story_4_8_5_dialog_content = "資料館這種地方，有必要用這樣的鎖嗎……？",
  ui_story_4_8_6_dialog_content = "格茲德。",
  ui_story_4_8_7_dialog_content = "嘶魘兒！抱歉，我還需要點時間，資料館的大門……",
  ui_story_4_8_8_dialog_content = "等等，妳在戰鬥嗎？",
  ui_story_4_8_9_dialog_content = "不……抱歉，我……在逃跑。",
  ui_story_4_8_10_dialog_content = "有空裔！格茲德……她們那邊，有一個空裔！",
  ui_story_4_8_11_dialog_content = "妳與卡蓮交手了嗎？有受傷嗎？",
  ui_story_4_8_12_dialog_content = "聽我說，我會把人都引到上城區南邊，那是離你最遠的地方……",
  ui_story_4_8_A1_dialog_content = "這樣你就有充足的時間……",
  ui_story_4_8_13_dialog_content = "不！你往上城區跑，等同於放棄了生路！！",
  ui_story_4_8_14_dialog_content = "嘶魘兒，別忘了我們的目標是……",
  ui_story_4_8_15_dialog_content = "<color=#FFB400>那位大人</color>會幫助我們的，我相信。她承諾過……",
  ui_story_4_8_16_dialog_content = "信念就是力量，格茲德，既然我們已經做了選擇，就要實踐到底！",
  ui_story_4_8_17_dialog_content = "白夜城外見，親愛的。",
  ui_story_4_8_18_dialog_content = "嘶魘兒——！！",
  ui_story_4_8_19_dialog_content = "等、等等我，妳們速度太快了……",
  ui_story_4_8_20_dialog_content = "卡蓮，那個叫夏爾的孩子是誰？她們原來都是光靈嗎？",
  ui_story_4_8_21_dialog_content = "雖然不想承認，但的確沒錯，她們是兩個曾經與白夜城有糾葛的……叛徒而已。",
  ui_story_4_8_22_dialog_content = "PlayerName，剛才的指揮非常漂亮。我本來以為面對高級暗鬼你會退縮。",
  ui_story_4_8_23_dialog_content = "你和我想像中的空裔，似乎完全不一樣。",
  ui_story_4_8_24_option_content = "這只不過是職責所在",
  ui_story_4_8_25_option_content = "不，我跟所有空裔都一樣",
  ui_story_4_8_26_dialog_content = "卡蓮小姐，妳作為衛隊長不也在奮戰著嗎？",
  ui_story_4_8_A2_dialog_content = "我們並不喜歡戰鬥，也沒有直接戰鬥的能力。",
  ui_story_4_8_27_dialog_content = "我們只是不想讓暗鬼獲得勝利而已。",
  ui_story_4_8_28_dialog_content = "我相信，我的族人也曾抱持這種心態參與戰鬥。",
  ui_story_4_8_29_dialog_content = "沒有戰鬥能力也要戰鬥，你不會害怕嗎？",
  ui_story_4_8_31_dialog_content = "我知道，我的族人也曾拼命和暗鬼戰鬥過，而且發揮重要的作用。",
  ui_story_4_8_32_dialog_content = "我和我的同胞們沒有任何不同。",
  ui_story_4_8_33_dialog_content = "你的能力確實令人印象深刻。",
  ui_story_4_8_34_dialog_content = "我的能力……可能，這也是我們遭遇血腥襲擊的原因吧。",
  ui_story_4_8_35_dialog_content = "你不會覺得很無力嗎？",
  ui_story_4_8_36_dialog_content = "不會。因為……我有屬於自己的使命。",
  ui_story_4_8_37_dialog_content = "為了這所謂的使命，你甘願將自己置身險境嗎？",
  ui_story_4_8_F1_dialog_content = "對。因為這不是我一個人的戰鬥。",
  ui_story_4_8_38_dialog_content = "有趣。薇絲，妳的這位搭檔非常有意思。",
  ui_story_4_8_39_dialog_content = "將自己置身險境，為<color=#FFB400>他人而戰鬥</color>嗎……",
  ui_story_4_8_40_dialog_content = "……",
  ui_story_4_8_41_dialog_content = "……！！",
  ui_story_4_8_46_dialog_content = "拉斐爾，妳在嗎？",
  ui_story_4_8_47_dialog_content = "在！",
  ui_story_4_8_48_dialog_content = "妳不必跟我們一起往上城區追擊。請妳……往反方向走。",
  ui_story_4_8_49_dialog_content = "欸？！為什麼？",
  ui_story_4_8_50_dialog_content = "妳不認為，向「上城區」逃跑是自尋死路嗎？",
  ui_story_4_8_51_dialog_content = "也許她們根本就不是想逃跑……而是……",
  ui_story_4_8_52_dialog_content = "繼續吸引注意力？",
  ui_story_4_8_53_dialog_content = "沒錯。但當下我們卻沒有選擇，不得不追。",
  ui_story_4_8_54_dialog_content = "所以我希望拉斐爾去反方向調查，直覺告訴我在某個地方，有什麼人……",
  ui_story_4_8_55_dialog_content = "哦哦哦！拉斐爾聽懂了！總之就是尋找可疑人士對吧！拉斐爾這就出發！",
  ui_story_4_8_56_dialog_content = "卡蓮真的很敏銳呢。好像沒有任何事能瞞過妳的眼睛。",
  ui_story_4_8_57_dialog_content = "正好相反，很多事情我都還沒辦法看清楚。所謂的「立場」，太複雜了……",
  ui_story_4_8_58_dialog_content = "罷了，集中注意力。路上湧出新的蟲子，趕快清掉吧。",
  ui_story_4_12_1_dialog_content = "……",
  ui_story_4_12_2_dialog_content = "……",
  ui_story_4_12_3_dialog_content = "欸……所以說，中隊長先生在這裡是……",
  ui_story_4_12_4_dialog_content = "唉，我說過兩次了，我來這裡是為了護送資料館的員工。不信你可以去問他們。",
  ui_story_4_12_5_dialog_content = "可之前您跟衛隊長匯報的是去城外接應城民……",
  ui_story_4_12_6_dialog_content = "我接應的城民，就是資料館的人。現在送回來了。",
  ui_story_4_12_7_dialog_content = "欸……那你手上拿的那個盒子是……？為什麼要用布蓋住？",
  ui_story_4_12_8_dialog_content = "啊，這個嗎。上週放在這裡的一些文件，打包了。",
  ui_story_4_12_9_dialog_content = "內容嘛……主要是近半年以來，被暗鬼殘害的城民的……驗屍報告。",
  ui_story_4_12_10_dialog_content = "呃……",
  ui_story_4_12_11_dialog_content = "我們的治安工作需要這些作為參考。裡面有一些現場照片和遺體解剖圖之類的。",
  ui_story_4_12_12_dialog_content = "……妳要看看嗎？",
  ui_story_4_12_13_dialog_content = "……",
  ui_story_4_12_14_dialog_content = "……",
  ui_story_4_12_15_dialog_content = "啊哈哈，不用了、不用了。",
  ui_story_4_12_16_dialog_content = "沒事，畢竟現在事態非比尋常，如果您要奉命檢查的話……",
  ui_story_4_12_17_dialog_content = "唔啊啊啊不用！我、我先去那邊巡查了！",
  ui_story_4_12_18_dialog_content = "……",
  ui_story_4_13_1_dialog_content = "報告！血跡延伸到這邊！！似乎往這扇門裡去了！",
  ui_story_4_13_2_dialog_content = "血滴的間隔越來越短……她們的速度慢下來了，我們正在縮短距離！",
  ui_story_4_13_3_dialog_content = "加快速度，也許就在前面！",
  ui_story_4_13_4_dialog_content = "哇，不知不覺已經跑了好遠，幾乎快要到上城區了……",
  ui_story_4_13_5_dialog_content = "看來她們也知道無法突破上城區，所以要在這裡決一死戰了嗎。",
  ui_story_4_13_6_dialog_content = "那就來吧，來多少次結果都是一樣——背叛者的結局永遠不會改變！",
  ui_story_4_13_7_dialog_content = "姐姐……想睡……",
  ui_story_4_13_8_dialog_content = "別睡，夏爾……抱歉，我知道妳很累了……",
  ui_story_4_13_9_dialog_content = "已經到了嗎……真快呢，不愧是……卡蓮……",
  ui_story_4_13_10_dialog_content = "是時候，來驗證那位大人的承諾了……",
  ui_story_4_13_11_dialog_content = "妳好，嘶魘兒。",
  ui_story_4_13_12_dialog_content = "大人……！我……我們，面臨了絕境……敵人，有一名空裔！",
  ui_story_4_13_13_dialog_content = "……真是冤家路窄。",
  ui_story_4_13_14_dialog_content = "我們需要幫助……！格茲德那邊，還沒完成……還需要時間！",
  ui_story_4_13_15_dialog_content = "請賜予我們擊敗敵人的力量……賜予我們，活下去的希望……！",
  ui_story_4_13_16_dialog_content = "這是兩個要求，嘶魘兒。",
  ui_story_4_13_17_dialog_content = "……！",
  ui_story_4_13_18_dialog_content = "到底是想擊敗敵人，還是想活下去呢？",
  ui_story_4_14_1_dialog_content = "嘶魘兒、夏爾。",
  ui_story_4_14_3_dialog_content = "妳們……來了……",
  ui_story_4_14_4_dialog_content = "姐姐……",
  ui_story_4_14_5_dialog_content = "嘶魘兒，告訴我，<color=#FFB400>妳們是在為什麼人爭取時間</color>？",
  ui_story_4_14_6_dialog_content = "……",
  ui_story_4_14_7_dialog_content = "看來妳們不會回答我，那就別怪我不客氣了！",
  ui_story_4_14_8_dialog_content = "卡蓮……妳以為現在的我們，只是甕中之鱉嗎？",
  ui_story_4_14_9_dialog_content = "那位大人……已經賜予了我們新的……力量……",
  ui_story_4_14_10_dialog_content = "「那位大人」？難道是舒默？",
  ui_story_4_14_11_dialog_content = "我們……我們會活下去的……然後驕傲地離開，這腐朽的白夜城！",
  ui_story_4_14_13_dialog_content = "小公主，妳不會永遠都贏的！",
  ui_story_4_14_14_dialog_content = "姐……姐？身體，正在……",
  ui_story_4_14_15_dialog_content = "<anim type=Shake>啊啊啊啊啊啊啊啊！！！</anim>",
  ui_story_4_14_17_dialog_content = "這是……？！她們、<color=#FFB400>融為一體</color>了？！",
  ui_story_4_14_18_dialog_content = "剛才賜予她們的，恐怕不是什麼普通的力量吧。",
  ui_story_4_14_19_dialog_content = "啊啊，但的確是她們想要的、擊敗敵人的力量哦。",
  ui_story_4_14_21_dialog_content = "幫那造物取個名字吧？妳想叫她們什麼？",
  ui_story_4_14_22_dialog_content = "……無聊。",
  ui_story_4_14_23_dialog_content = "<anim type=Shake>唔啊啊啊啊——！！痛、痛！！為什麼、這不對！！我們——</anim>",
  ui_story_4_14_24_dialog_content = "<anim type=Shake>姐姐、力量、在湧現——但、好痛……！</anim>",
  ui_story_4_14_25_dialog_content = "<anim type=Shake>大人，大人！！這到底是、什麼？！！</anim>",
  ui_story_4_14_26_dialog_content = "PlayerName，請退後……那個東西，已經不能用怪物來形容……",
  ui_story_4_14_27_option_content = "不要害怕，我在",
  ui_story_4_14_28_option_content = "集中精神，會贏的",
  ui_story_4_14_29_dialog_content = "憤怒令我顫抖……",
  ui_story_4_14_30_dialog_content = "到底是什麼樣的傢伙，會賜予人「這樣」的力量？！",
  ui_story_4_14_31_dialog_content = "好！那就一如往常地拜託你了，PlayerName！",
  ui_story_4_14_32_dialog_content = "<anim type=Shake>痛……痛！姐姐，我……好痛……</anim>",
  ui_story_4_14_33_dialog_content = "<anim type=Shake>妹妹……殺、殺了我們……</anim>",
  ui_story_4_14_35_dialog_content = "……",
  ui_story_4_14_36_dialog_content = "這是怎麼回事……所謂的「賜予力量」，到底是什麼意思？",
  ui_story_4_14_A1_dialog_content = "雖然不知道怎麼辦到的，但既然選擇投靠黑暗，就只有這個下場。",
  ui_story_4_14_37_dialog_content = "以白夜之名，我賜予妳們……",
  ui_story_4_14_38_dialog_content = "<anim type=Shake>蒲公英……</anim>",
  ui_story_4_14_39_dialog_content = "？",
  ui_story_4_14_40_dialog_content = "<anim type=Shake>蒲公英……我會化作蒲公英，飛……飛走……</anim>",
  ui_story_4_14_41_dialog_content = "妳已經語無倫次了。不，我現在甚至都不知道該用妳、還是妳們……",
  ui_story_4_14_42_dialog_content = "<anim type=Shake>我、我明明已經完成了……那位大人的計劃……</anim>",
  ui_story_4_14_43_dialog_content = "<anim type=Shake>為什麼……承諾的不是這樣，我的——格茲德還在等我——</anim>",
  ui_story_4_14_44_dialog_content = "<anim type=Shake>大人、那位大人……</anim>",
  ui_story_4_14_45_dialog_content = "<color=#e8d9bb>轟隆——！！！</color>",
  ui_story_4_14_46_dialog_content = "又、又有爆炸？！",
  ui_story_4_14_47_dialog_content = "報告……是<color=#FFB400>資料館</color>！資料館爆炸了！對、對不起——！",
  ui_story_4_14_48_dialog_content = "知道了！不過拉斐爾，妳為什麼要道歉？",
  ui_story_4_14_49_dialog_content = "<anim type=Shake>嘻嘻……嘻、嘻嘻……妳終於，輸了，小公主……</anim>",
  ui_story_4_14_50_dialog_content = "<anim type=Shake>格茲德、格……我的……格茲德……你要活下去啊……</anim>",
  ui_story_4_14_53_dialog_content = "雖然是敵人，我也不忍心看到這種慘況。",
  ui_story_4_14_54_dialog_content = "<color=#e8d9bb>資料館外</color>",
  ui_story_4_14_55_dialog_content = "所以，你和那個叛徒擦肩而過，是嗎？",
  ui_story_4_14_56_dialog_content = "……對不起，卡蓮姐姐……要是我當時……",
  ui_story_4_14_57_dialog_content = "<color=#FFB400>全城搜捕格茲德</color>。即刻動員。",
  ui_story_4_14_58_dialog_content = "是、是！",
  ui_story_4_14_59_dialog_content = "危害治安，大肆破壞……這樣的惡劣行徑簡直無法容忍……",
  ui_story_4_14_60_dialog_content = "這個人是不是從資料館偷走了……",
  ui_story_4_14_61_dialog_content = "「智庫組件」……",
  ui_story_4_14_62_dialog_content = "直到被偷走，也沒能看到長什麼樣子……真是太失敗了……",
  ui_story_4_14_63_dialog_content = "我也有責任。不，我應該負主要責任。",
  ui_story_4_14_64_dialog_content = "卡蓮，我很抱歉……",
  ui_story_4_14_65_dialog_content = "暗鬼總會反撲，薇絲。",
  ui_story_4_14_66_dialog_content = "我反而慶幸，這次危機的「信使」是你和PlayerName。",
  ui_story_4_14_67_dialog_content = "如果是其他人，造成的損失可能更慘不忍睹。",
  ui_story_4_14_68_dialog_content = "這算是誇獎還是責怪……？",
  ui_story_4_14_69_dialog_content = "誇獎吧……？",
  ui_story_4_14_70_dialog_content = "身為衛隊長，我相當失職。我必須……向城主殿下索求懲罰。",
  ui_story_4_14_71_dialog_content = "那是妳父親，他應該會原諒妳吧。",
  ui_story_4_14_72_dialog_content = "……看來你完全不瞭解白夜城，和那個男人呢。",
  ui_story_4_14_73_dialog_content = "那我們也應該回啟光商量後續的計劃了。",
  ui_story_4_14_74_dialog_content = "老話說得好，「若你因錯過週一而煩惱，那你也會錯過週二了」。",
  ui_story_4_14_75_dialog_content = "還有這種老話嗎……？",
  ui_story_4_14_76_dialog_content = "……妳還真是樂觀啊，薇絲。",
  ui_story_4_14_77_dialog_content = "畢竟情況已經變成這樣了，一味失落也沒有任何意義！",
  ui_story_4_14_78_dialog_content = "那我也必須回上城區向城主殿下報告了。你們一路保重。",
  ui_story_4_14_79_dialog_content = "以及你，PlayerName……也許我們還會再見的。",
  ui_story_4_14_80_dialog_content = "<color=#e8d9bb>與此同時·某處</color>",
  ui_story_4_14_81_dialog_content = "死掉了呢，那對姐妹。",
  ui_story_4_14_82_dialog_content = "……意料之內不是嗎。",
  ui_story_4_14_83_dialog_content = "有兩個消息。「智庫組件」確認到手，以及……",
  ui_story_4_14_84_dialog_content = "上次那個空裔，又出現了。",
  ui_story_4_14_85_dialog_content = "我記得是叫PlayerName？",
  ui_story_4_14_86_dialog_content = "對妳的同胞念念不忘嘛。",
  ui_story_4_14_90_dialog_content = "……我再說一次，我已經不是那種低等生物了！！",
  ui_story_4_14_91_dialog_content = "倒是你的部下們，愚蠢又拖泥帶水，差點就讓整個計劃泡湯了！",
  ui_story_4_14_92_dialog_content = "下一個組件我會親自出手！任何膽敢阻撓我的人……任何人，都會被我撕爛。",
  ui_story_4_14_93_dialog_content = "組件呢？先給我！格茲德！",
  ui_story_4_14_95_dialog_content = "嘶魘兒……嘶魘兒……不、不可能！",
  ui_story_4_14_96_dialog_content = "她答應我的……她答應了要和我一起離開……一起獲得自由……",
  ui_story_4_14_97_dialog_content = "到底發生了什麼事……？！",
  ui_story_4_14_98_dialog_content = "別在那邊自言自語了！一副沒出息的樣子！",
  ui_story_4_14_99_dialog_content = "她們已經被白夜城衛隊幹掉了，你該慶幸自己還有時間完成我們的命令！",
  ui_story_4_14_100_dialog_content = "……卡蓮……！",
  ui_story_4_14_101_dialog_content = "表情不錯，格茲德，和通緝令上可謂判若兩人呢。",
  ui_story_4_14_102_dialog_content = "我要她們……血債血償！",
  ui_story_5_1_1_dialog_content = "卡蓮衛隊長，這是妳自己的決定嗎？",
  ui_story_5_1_2_dialog_content = "是的，殿下。我認為必須觀察那個空裔，他……十分特殊。",
  ui_story_5_1_3_dialog_content = "我不會干預妳的行動，但希望妳能牢記自己的立場，衛隊長。",
  ui_story_5_1_4_dialog_content = "是，殿下。白夜至上。",
  ui_story_5_1_5_dialog_content = "情況我瞭解了。半小時後是軍團長的例行會議，你們可以在會議上報告詳細內容。",
  ui_story_5_1_6_dialog_content = "但實際要怎麼解決，還得看商議的結果。",
  ui_story_5_1_7_dialog_content = "……那麼，第一項議題結束。",
  ui_story_5_1_A1_dialog_content = "關於上述座標附近的暗鬼活動巡邏工作，就交給三位軍團長了。",
  ui_story_5_1_8_dialog_content = "<size=30>咳，PlayerName，剛剛這位長官是第一軍團的<color=#FFB400>希羅娜</color>軍團長。</size>",
  ui_story_5_1_A2_dialog_content = "<size=30>這一位是第二軍團的<color=#FFB400>巴頓</color>軍團長，都算是軍方代表人物。</size>",
  ui_story_5_1_9_dialog_content = "好的。最近迦南附近也出現了可疑的高級暗鬼，恐怕不是什麼好兆頭。",
  ui_story_5_1_10_dialog_content = "所以才集結三位軍團長。請各位居安思危，不要放過任何眼皮下的威脅。",
  ui_story_5_1_11_dialog_content = "這兩個小鬼頭來幹嘛的？",
  ui_story_5_1_12_dialog_content = "他們是今天的第二項議題。緋，請說明一下情況。",
  ui_story_5_1_13_dialog_content = "能夠操縱巨像的殘存空裔嗎……",
  ui_story_5_1_14_dialog_content = "……",
  ui_story_5_1_15_option_content = "為、為什麼大家都看著我？",
  ui_story_5_1_16_dialog_content = "你是不是臉紅了？",
  ui_story_5_1_X16_dialog_content = "果然還是個小鬼頭。",
  ui_story_5_1_17_option_content = "需要我現在就表演一下嗎？",
  ui_story_5_1_18_dialog_content = "在這裡啟動巨像會把屋頂掀翻。",
  ui_story_5_1_19_dialog_content = "果然是高度危險人物。小鬼，你和舒默是什麼關係？",
  ui_story_5_1_20_dialog_content = "長官！PlayerName和舒默是不一樣的。",
  ui_story_5_1_21_dialog_content = "不必緊張，未被污染又缺乏戰鬥能力的空裔，當然和那些暗鬼同謀截然不同。",
  ui_story_5_1_22_dialog_content = "我只是沒想到空裔現在還有倖存者，以為他們都已經在那場浩劫中死去了。",
  ui_story_5_1_23_dialog_content = "回到正題，你們所說的舒默，那傢伙對這三樣組件的情報，掌握到什麼程度？",
  ui_story_5_1_24_dialog_content = "我們也沒有頭緒，畢竟尋找剩下兩個組件的方法在「智庫組件」裡……",
  ui_story_5_1_25_dialog_content = "而且我們認為舒默已經獲得「智庫組件」，所以現在情況並不樂觀。",
  ui_story_5_1_26_dialog_content = "當務之急是想辦法在她之前找到另外兩個組件！",
  ui_story_5_1_27_dialog_content = "希望長官能給予我們協助，或者……由長官接手這件事情。",
  ui_story_5_1_28_dialog_content = "啟光軍團的第一要務是保衛前線以及總部迦南城。",
  ui_story_5_1_29_dialog_content = "最近暗鬼襲擊事件轉趨頻繁，日常的防衛事務已經飽和，恐怕很難抽調人手。",
  ui_story_5_1_30_dialog_content = "我還是那句話，沒有大元帥的命令，沒有人能夠指揮我和我的軍團。",
  ui_story_5_1_31_dialog_content = "緋呢？身為薇絲的長官，妳怎麼想？",
  ui_story_5_1_32_dialog_content = "啟光軍人的天職為服從命令。",
  ui_story_5_1_33_dialog_content = "明白。",
  ui_story_5_1_34_dialog_content = "很抱歉PlayerName，在得到明確命令之前，我們無法為你們提供幫助。",
  ui_story_5_1_35_dialog_content = "PlayerName，能感應到什麼嗎？",
  ui_story_5_1_36_dialog_content = "一片虛無，沒有任何特殊訊號。",
  ui_story_5_1_37_dialog_content = "現在連最後能依靠的方法也沒用了嗎？",
  ui_story_5_1_38_dialog_content = "孟德爾頌死前曾說過，舒默一定會接著尋找下一樣組件。",
  ui_story_5_1_39_dialog_content = "如果我們找得到舒默的蹤跡，或許就能順著線索發現一些蛛絲馬跡。",
  ui_story_5_1_40_dialog_content = "但她就像是從這個世界上蒸發了一樣。難道我們只能被動等待嗎？",
  ui_story_5_1_41_dialog_content = "哈——欠。欸～你們怎麼灰頭土臉的喵，開會不順利嗎？",
  ui_story_5_1_42_dialog_content = "<color=#FFB400>菲莉詩</color>前輩！",
  ui_story_5_1_43_dialog_content = "哎呀，不用這麼激動，菲莉詩只是來送一點東西給你們喵。這個。",
  ui_story_5_1_44_dialog_content = "<color=#FFB400>《無名者十三號巨像遺跡研究報告》</color>？",
  ui_story_5_1_45_dialog_content = "菲莉詩花了好多時間呢！！",
  ui_story_5_1_46_dialog_content = "薇薇安給菲莉詩超困難的任務，好睏……這工作安排強度實在太高了喵。",
  ui_story_5_1_47_dialog_content = "「無名巨像隕落之處，曾發現可自主生長的部件，或許是生長型巨像特有……」",
  ui_story_5_1_48_dialog_content = "「關鍵部分沉睡於遺跡深處，解封方式未知，正在持續探索……」",
  ui_story_5_1_49_dialog_content = "這個描述，難道就是「<color=#FFB400>自長單元</color>」？！",
  ui_story_5_1_50_dialog_content = "會這麼巧嗎～不過你們也只能根據這條線索試試了喵。",
  ui_story_5_1_51_dialog_content = "對了對了，薇薇安還讓菲莉詩跟你們說喵……",
  ui_story_5_1_52_dialog_content = "雖然軍團長們暫時無法提供協助，不過遺跡那裡也有啟光的人喵！",
  ui_story_5_1_53_dialog_content = "哈——欠，菲莉詩真的要撐不住了，先去睡了喵，讓我在夢裡為你們加油吧！",
  ui_story_5_1_54_dialog_content = "菲莉詩前輩還是老樣子啊。",
  ui_story_5_1_55_option_content = "巨像上如果有這樣的夥伴",
  ui_story_5_1_56_dialog_content = "她可是啟光的情報長，能像這樣提供幫助已經很不錯了。",
  ui_story_5_1_57_dialog_content = "如果菲莉詩前輩能直接加入我們的行動，至少蒐集情報時就不會這麼被動了。",
  ui_story_5_1_58_dialog_content = "可是她看起來快要當場睡死了。",
  ui_story_5_1_59_dialog_content = "是因為工作壓力太大吧……",
  ui_story_5_1_60_option_content = "其實我也好睏……不如我們……",
  ui_story_5_1_61_dialog_content = "現在去休息一下吧。",
  ui_story_5_1_A4_dialog_content = "不行！打起精神來啊！PlayerName！如果能順利解決這些問題……",
  ui_story_5_1_62_dialog_content = "我就帶你去迦南最大的圖書館，好好休息一下！",
  ui_story_5_1_63_dialog_content = "不是應該去遊樂園或者咖啡廳嗎？工作結束後還要繼續學習也太殘酷了。",
  ui_story_5_1_64_dialog_content = "總之，我們時間所剩不多了！一定要趕在舒默之前找到下一個組件！",
  ui_story_5_1_65_dialog_content = "我們去啟動巨像吧！",
  ui_story_5_1_66_dialog_content = "看你們這副胸有成竹的樣子，看來已經匯報完畢並得到處理方案了。",
  ui_story_5_1_67_dialog_content = "卡蓮？！",
  ui_story_5_1_68_dialog_content = "不必驚訝。我向城主申請了特派令，將全權負責調查舒默一事。",
  ui_story_5_1_69_dialog_content = "任何膽敢侵犯白夜城的行為都將受到嚴懲，勾結暗鬼更是罪無可赦。",
  ui_story_5_1_70_dialog_content = "<size=30>卡蓮……好像很不近人情的樣子，要小心點了。</size>",
  ui_story_5_1_71_dialog_content = "你說什麼？",
  ui_story_5_1_72_dialog_content = "欸？我說出來了嗎？！",
  ui_story_5_1_73_dialog_content = "若是問心無愧，自然不必有懼於我。",
  ui_story_5_1_A5_dialog_content = "該懼怕我的是嘶魘兒和格茲德之流，還有他們背後的人。",
  ui_story_5_1_74_dialog_content = "格茲德……是之前幫嘶魘兒她們製造混亂、試圖逃跑的傢伙嗎？",
  ui_story_5_1_75_dialog_content = "沒錯，那個投靠日蝕的叛徒，以為自己能夠隱蔽於陰影之中，尋求庇護。",
  ui_story_5_1_76_dialog_content = "但無論天涯海角，舒瓦茲家族的利劍必會刺穿背叛者的胸膛。",
  ui_story_5_1_77_dialog_content = "閒話說夠了，接下來去哪？",
  ui_story_5_1_78_dialog_content = "無名者十三號巨像遺跡。衛隊長之前去過巨像遺跡嗎？",
  ui_story_5_1_79_dialog_content = "有沒有去過並不重要……我從不沉溺於過去的事物，眼下有更需要我守護的東西。",
  ui_story_5_1_80_dialog_content = "不過，不管怎樣，PlayerName閣下，感謝你們及時提供情報。",
  ui_story_5_1_81_dialog_content = "這次行動，我將與你們同行，以我手中之槍起誓，絕不會讓背叛者得償所願！",
  ui_story_5_2_1_dialog_content = "（好像有什麼聲音，令人心酸的、令人懷念的聲音……）",
  ui_story_5_2_2_dialog_content = "為已經逝去的故土獻上花束，那裡曾有樹木迎風生長……",
  ui_story_5_2_3_dialog_content = "為已經逝去的同胞祈禱極光，光芒照耀寬恕所有生靈……",
  ui_story_5_2_4_dialog_content = "我們的痛苦會隨時間逝去，直到記憶風化成灰，最終化為虛無……",
  ui_story_5_2_5_dialog_content = "太陽會照常升起，但我們卻將在沉睡中迎來永遠的安息。",
  ui_story_5_2_6_dialog_content = "老師……這樣就可以了嗎？但我還是害怕……",
  ui_story_5_2_7_dialog_content = "我種下的小花還沒有發芽，好想看到它開花的那一天啊。",
  ui_story_5_2_8_dialog_content = "別害怕，孩子，閉上眼睛。死亡只是剎那的痛苦，老師會一直陪在你的身邊。",
  ui_story_5_2_9_dialog_content = "（我的……<color=#FFB400>同胞</color>？這些片段到底是現實，還是幻象……）",
  ui_story_5_2_10_dialog_content = "無聊的死前禱告。來吧，別說我沒給你們選擇——",
  ui_story_5_2_11_dialog_content = "我們已經在目的地上方了。PlayerName，你還好嗎？",
  ui_story_5_2_12_option_content = "薇絲……",
  ui_story_5_2_13_dialog_content = "別怕，有我在。你是感應到什麼了嗎？",
  ui_story_5_2_14_dialog_content = "一些幻象……他們究竟是？",
  ui_story_5_2_15_dialog_content = "也許是一些死去的空裔在這片遺跡裡留下強烈的執念。",
  ui_story_5_2_16_dialog_content = "……死去的，是嗎。所以他們並不像孟德爾頌那樣能夠與我對話。",
  ui_story_5_2_17_dialog_content = "是的，他們不能。他們的遺體應該早已被風蝕為塵埃了。",
  ui_story_5_2_18_option_content = "我，我好像看到了很多的幻象。",
  ui_story_5_2_19_dialog_content = "PlayerName，你感應到誰的意識嗎？難道說這片遺跡還有倖存者？",
  ui_story_5_2_A1_dialog_content = "這裡沒有生還者的氣息。你看到的畫面，恐怕是某種幻象……",
  ui_story_5_2_20_dialog_content = "悲傷而絕望的幻象……或許這些是死去的空裔殘留的意識？",
  ui_story_5_2_21_dialog_content = "我相信是的。是同胞們的執念。",
  ui_story_5_2_A2_dialog_content = "我們降落吧，臨空者。",
  ui_story_5_2_24_dialog_content = "我們到了，<color=#FFB400>無名者十三號遺跡</color>。",
  ui_story_5_2_25_dialog_content = "資料上說，「最初發現這裡的人，被眼前無名巨像沉眠的姿態所震撼……」",
  ui_story_5_2_26_dialog_content = "「認為它就像是隕落的星星，在地面上陷入沉睡。」",
  ui_story_5_2_27_dialog_content = "「巨像上已經沒有任何生命跡象。只剩下時光流逝後的虛無」",
  ui_story_5_2_28_dialog_content = "這肅殺的氣氛……我還是第一次見到這種地方。",
  ui_story_5_2_29_dialog_content = "關於空之山谷的浩劫，我曾在資料館的書上看過——",
  ui_story_5_2_30_dialog_content = "「暗鬼如潮水般襲擊了空谷之裔的部族，除了暗鬼的追隨者，無人倖存。」",
  ui_story_5_2_31_dialog_content = "然而真正靠近這裡時，見到的景象卻比想像中還要……令人心酸。",
  ui_story_5_2_A3_dialog_content = "……",
  ui_story_5_2_A4_dialog_content = "薇絲，妳應該也有很多感觸吧？",
  ui_story_5_2_A5_dialog_content = "嗯，我能感受到的東西雖然不如PlayerName那樣強烈，但也……十分悲傷。",
  ui_story_5_2_34_dialog_content = "PlayerName，你是怎麼活下來的？",
  ui_story_5_2_35_dialog_content = "我只知道劫難發生時，臨空者號遵循命令，將還是嬰兒的我帶走了。",
  ui_story_5_2_A6_dialog_content = "那之後便是長達十七年的地底生活，直到不久之前。",
  ui_story_5_2_36_dialog_content = "是薇絲帶我來到外面的世界……可惜外面的世界也沒有比地下好多少。",
  ui_story_5_2_37_dialog_content = "我好想……再和我的族人們，再和孟德爾頌說說話啊。",
  ui_story_5_2_38_dialog_content = "PlayerName……",
  ui_story_5_2_39_dialog_content = "不能讓空裔的悲劇重演……",
  ui_story_5_2_40_dialog_content = "當然。任何族群都不應承受此般悲劇，不是嗎？",
  ui_story_5_2_41_dialog_content = "你們看——中間這艘最大的巨像，就是資料上提到的目標吧？",
  ui_story_5_2_A7_dialog_content = "根據資料顯示，他是「<color=#FFB400>教化者</color>」，他也是唯一一艘能夠自主成長的巨像。",
  ui_story_5_2_42_dialog_content = "「<color=#FFB400>自長單元</color>」恐怕就在他身上。",
  ui_story_5_2_43_dialog_content = "巨像損毀成這個樣子，那東西還會完好無缺嗎？",
  ui_story_5_2_44_dialog_content = "資料的內容就到此為止了。",
  ui_story_5_2_45_dialog_content = "進去看看吧，裡面肯定有線索。",
  ui_story_5_2_46_dialog_content = "PlayerName，你一定知道，這很危險，就像孟德爾頌那時一樣……",
  ui_story_5_2_F1_dialog_content = "我知道，進去以後，我可能會像他一樣遭遇危險，像他一樣消失。",
  ui_story_5_2_47_dialog_content = "直到現在，我仍無法忘懷孟德爾頌消失的情景，以及無法挽救他的無力感。",
  ui_story_5_2_48_dialog_content = "我們現在放棄還來得及。",
  ui_story_5_2_F2_dialog_content = "薇絲，我也害怕，但是我沒有選擇。",
  ui_story_5_2_F3_dialog_content = "我已經想清楚了……不管有什麼危險，會發生什麼，我都會面對。",
  ui_story_5_2_49_dialog_content = "我知道了……我不會讓你獨自面對這一切的。無論如何，我都會站在你身邊。",
  ui_story_5_2_A8_dialog_content = "<color=#e8d9bb>遺跡內部</color>",
  ui_story_5_2_50_dialog_content = "基本模塊已損毀得殘破不堪了，傷腦筋。",
  ui_story_5_2_51_dialog_content = "或許需要重新啟動巨像才能將核心元件剝離出來。",
  ui_story_5_2_52_dialog_content = "這個聲音……",
  ui_story_5_2_53_option_content = "難道是……舒默！ ？",
  ui_story_5_2_54_dialog_content = "不，不是，是<color=#FFB400>貢露</color>前輩！",
  ui_story_5_2_55_option_content = "是啟光的同伴嗎？",
  ui_story_5_2_56_dialog_content = "是的！是<color=#FFB400>貢露</color>前輩。",
  ui_story_5_2_57_dialog_content = "貢露前輩是啟光科研部的科研長，對於巨像、光能力量都深入研究過。",
  ui_story_5_2_58_dialog_content = "前輩！！",
  ui_story_5_2_59_dialog_content = "薇絲？！沒想到能援助我的同伴在這個時候出現了！",
  ui_story_5_2_60_dialog_content = "原來菲莉詩交代要我留意的人是妳啊～",
  ui_story_5_2_61_dialog_content = "妳能想像嗎！菲莉詩像是中了沉睡效果一樣，話才說一半就睡死了。",
  ui_story_5_2_62_dialog_content = "留我一個人在原地手足無措！好、生、氣！不過幸好命運之神還是眷顧我的～",
  ui_story_5_2_63_dialog_content = "聽說你還帶著一座「活的」巨像？！不可思議，這表示他完好無缺！",
  ui_story_5_2_64_dialog_content = "<size=45>可以讓我玩一下嗎！！</size>",
  ui_story_5_2_65_dialog_content = "欸？",
  ui_story_5_2_66_dialog_content = "咳咳，我好像有點太激動了。還是先回到主線任務吧！！",
  ui_story_5_2_67_dialog_content = "貢露前輩什麼都好，就是說話方式有點奇怪，讓人聽不懂。",
  ui_story_5_2_68_dialog_content = "或許是過於沉迷某些東西的後遺症吧。",
  ui_story_5_2_69_dialog_content = "貢露前輩，只有妳一個人在這裡嗎？",
  ui_story_5_2_70_dialog_content = "是呀！這座巨像損毀得太嚴重，調查進展極其緩速，所以只能算支線任務。",
  ui_story_5_2_71_dialog_content = "但我總覺得，裡面還有我們沒調查清楚的事情。",
  ui_story_5_2_72_dialog_content = "而且支線全清也是職業素養，所以我就跟薇薇安申請了幾天過來再重新調查一下。",
  ui_story_5_2_73_dialog_content = "對了，你們是來這裡尋找……「<color=#FFB400>自長單元</color>」的？",
  ui_story_5_2_74_dialog_content = "是的，您的調查中有涉及這些嗎？",
  ui_story_5_2_75_dialog_content = "這座巨像確實有這種成長型組件，但不能用蠻力硬是將它剝離。",
  ui_story_5_2_77_dialog_content = "巨像畢竟是舊時代的尖端造物，以啟光現在的科技水準沒辦法完全解析他。",
  ui_story_5_2_78_dialog_content = "沒有別的辦法了嗎？",
  ui_story_5_2_79_dialog_content = "辦法嗎？倒不是沒有。",
  ui_story_5_2_80_dialog_content = "你就是菲莉詩提到的<color=#FFB400>「殘存的空裔」</color>吧？自帶頭銜，像個主角。",
  ui_story_5_2_81_dialog_content = "既然有現成的空裔，就可以試試重新啟動這座龐然大物啦。",
  ui_story_5_2_82_dialog_content = "事不宜遲，我們趕快……",
  ui_story_5_2_83_dialog_content = "<anim type=Shake>唔嘎！！</anim>",
  ui_story_5_2_84_dialog_content = "有礙事者，看來我們必須先將前路清一清，才能繼續前進。",
  ui_story_5_2_A9_dialog_content = "那就讓我們快速解決牠們！",
  ui_story_5_2_85_dialog_content = "第二樣組件「自長單元」的所在位置，妳一定會喜歡的……",
  ui_story_5_2_86_dialog_content = "我還以為是什麼了不起的地方呢，原來只是埋葬臭蟲的垃圾場。",
  ui_story_5_2_87_dialog_content = "這些死去的「弱者」身上會有我需要的組件？該不會，已經被我弄壞了吧？",
  ui_story_5_2_88_dialog_content = "啊——煩躁，<color=#FFB400>那個女人</color>是在嘲笑我嗎？！早就說了我和這些混蛋弱者不一樣！",
  ui_story_5_2_89_dialog_content = "弱者就該被撕碎、踩爛，粉身碎骨！！",
  ui_story_5_2_90_dialog_content = "可惡，即便知道她在幫我，但這種令人難以忍受的感覺還是揮之不去。",
  ui_story_5_2_91_dialog_content = "那些不中用的暗鬼，要不是因為上次差點出了差錯，我也不必什麼事都親自出馬。",
  ui_story_5_2_92_dialog_content = "還有那個空裔……哼，甚至還有點期待那傢伙出現呢。",
  ui_story_5_3_1_dialog_content = "巨像內部也損壞得如此嚴重……看不清路線，方向沒問題嗎？",
  ui_story_5_3_2_dialog_content = "放心，我可是專業的。我已經確實定位艦橋方位，就在前方兩百公尺處！",
  ui_story_5_3_3_dialog_content = "對於我這種內建方向感的人，ˊ這小菜一碟啦。",
  ui_story_5_3_4_dialog_content = "有聲音？",
  ui_story_5_3_5_dialog_content = "似乎並不在這附近。",
  ui_story_5_3_6_dialog_content = "好像有種陰冷的感覺……",
  ui_story_5_3_8_dialog_content = "PlayerName怎麼了？你還好嗎？",
  ui_story_5_3_9_dialog_content = "有一股比高級暗鬼更強烈的氣息！很可能……是舒默！",
  ui_story_5_3_10_dialog_content = "保持鎮定，我們繼續按照計劃行動。",
  ui_story_5_3_11_dialog_content = "如果她來了，就在這裡解決她。",
  ui_story_5_3_12_dialog_content = "可是……",
  ui_story_5_3_13_dialog_content = "沒有可是。她的手伸得太長了，我會讓她知道這麼做的下場。",
  ui_story_5_3_A1_dialog_content = "繼續前進吧，前面還有更多暗鬼等著我們。",
  ui_story_5_3_14_dialog_content = "熟悉的氣息……哼，難道那傢伙真的來了？",
  ui_story_5_3_16_dialog_content = "弱者實力不值一提，偏偏特別執著。",
  ui_story_5_3_17_dialog_content = "死了一個孟德爾頌，又來一個PlayerName想保護組件了嗎？呵呵。",
  ui_story_5_3_18_dialog_content = "我早就說過了，只有我選擇的道路才是正確的……",
  ui_story_5_3_A2_dialog_content = "唯有拿起武器才能掌握自己的命運，否則……永遠都是可憐的獵物。",
  ui_story_5_3_A3_dialog_content = "雜碎們！循著光能的氣息，去迎接一下我們的客人吧！讓他們先熱熱身！",
  ui_story_5_3_A4_dialog_content = "突然有一點點期待這次戰鬥呢。",
  ui_story_5_3_A5_dialog_content = "（日蝕語）遵命……進攻……！！",
  ui_story_5_7_A14_dialog_content = "目的地……到達！這裡就是這座巨像的艦橋了！",
  ui_story_5_7_A15_dialog_content = "這一路上的暗鬼可真難纏……我們必須提高警惕才行！",
  ui_story_5_7_A16_dialog_content = "之前我研究了好——久，都沒辦法將「自長單元」從艦橋取出，直接卡關了呢。",
  ui_story_5_7_A17_dialog_content = "這次就拜託你啦！如果是空裔的話，應該能成功啟動巨像吧！",
  ui_story_5_7_A18_dialog_content = "嗯，我盡力試試。",
  ui_story_5_7_1_dialog_content = "啟動巨像的第一步是確定能量儲存情況。",
  ui_story_5_7_2_dialog_content = "這座巨像雖然損毀嚴重，但意外地保留些許能量，足以重啟。",
  ui_story_5_7_3_dialog_content = "第二步是與巨像建立感應，只有這樣才能啟動控制台，而這只有空裔能做到。",
  ui_story_5_7_4_dialog_content = "第三步是操縱控制臺……",
  ui_story_5_7_5_dialog_content = "對，就是這樣。你做得很好。",
  ui_story_5_7_6_dialog_content = "聲音？是誰？ ？",
  ui_story_5_7_7_dialog_content = "我真的很開心……已經好久、好久，沒有見到我們的同胞、我們的後裔了。",
  ui_story_5_7_8_dialog_content = "一個人長大，無法與人交流和接觸，你一定吃了很多苦吧。",
  ui_story_5_7_9_dialog_content = "怎麼會知道……",
  ui_story_5_7_11_dialog_content = "我和你一樣，來自美麗的空之山谷。",
  ui_story_5_7_14_dialog_content = "從小，我就和族人一起讀書、生活，聆聽歌聲，與巨像對話。",
  ui_story_5_7_A1_dialog_content = "那是溫暖而穩固的大家庭，PlayerName。屬於空裔的家。",
  ui_story_5_7_15_option_content = "可是你的身體……是透明的？",
  ui_story_5_7_16_dialog_content = "為什麼我看不清楚你的面貌？",
  ui_story_5_7_17_dialog_content = "因為我只是你心中的……一縷思念啊，你想要看到我們的時候，我們才能夠出現。",
  ui_story_5_7_18_dialog_content = "我們試圖逃跑，卻依然逝去，身軀化為腐朽的枯骨，而靈魂飄散到無垠的天空。",
  ui_story_5_7_19_dialog_content = "她帶領暗鬼，殘忍殺害一個個同胞……那時的黑暗濃稠的連極光都無法穿破。",
  ui_story_5_7_20_dialog_content = "時至今日，她都沒有放棄自己的執念。",
  ui_story_5_7_21_dialog_content = "可憐的孩子，獨自生活的日子讓你很孤獨、很痛苦吧。",
  ui_story_5_7_22_dialog_content = "雖然我沒辦法擁抱你，但我至少可以與你一同奏響這首……回憶之歌。",
  ui_story_5_7_23_dialog_content = "感應吧，就像操縱臨空者號一樣……去感受巨像。",
  ui_story_5_7_24_dialog_content = "未曾謀面的最後之子，收下這份禮物吧。",
  ui_story_5_7_A2_dialog_content = "（我明白他只是幻象，但為什麼？我卻能感受到他的手觸碰我的皮膚。）",
  ui_story_5_7_25_dialog_content = "（我知道他早已死去，但為什麼？他的意識卻跨越了生死，指引我……）",
  ui_story_5_7_26_dialog_content = "（點亮這座巨像，見到你們。）",
  ui_story_5_7_27_dialog_content = "（你們在唱什麼？這合聲如此虔誠悠揚。你們在奠祭誰？我知道你們已被埋葬。）",
  ui_story_5_7_28_dialog_content = "（我從未聽過這樣的旋律，但我卻能和你們一起哼唱。）",
  ui_story_5_7_29_dialog_content = "（謝謝​​你們為我演奏……這穿過歲月的交響詩篇，我會永遠記得。）",
  ui_story_5_7_30_dialog_content = "我的……同胞們……我多希望你們是真實的。",
  ui_story_5_7_31_dialog_content = "巨像正在啟動！",
  ui_story_5_7_32_dialog_content = "這座巨像好像發出某種難以形容的低鳴？像是悲傷嗚咽，卻又不是……",
  ui_story_5_7_33_dialog_content = "我彷佛能感受到有什麼人充滿感情地和PlayerName一起哼唱。",
  ui_story_5_7_34_dialog_content = "PlayerName，我陪著你。",
  ui_story_5_7_35_dialog_content = "還差最後一點……五……四……啟動成功！",
  ui_story_5_7_36_dialog_content = "你們看！那就是他的核心組件「<color=#FFB400>自長單元</color>」！",
  ui_story_5_7_37_dialog_content = "快拿下來……",
  ui_story_5_7_38_dialog_content = "怎麼回事！ ？",
  ui_story_5_7_39_dialog_content = "<anim type=Shake>吼！</anim>",
  ui_story_5_7_40_dialog_content = "看來我來得正好啊。",
  ui_story_5_7_41_dialog_content = "妳是……舒默？！",
  ui_story_5_7_A3_dialog_content = "那麼，你就是PlayerName？",
  ui_story_5_7_A4_dialog_content = "比我想像的更年輕呢。這副透著無能和恐懼的面孔……呵。",
  ui_story_5_7_42_dialog_content = "自我陶醉的清唱劇就到此為止吧。多虧你們，才把「自長單元」剝離出來。",
  ui_story_5_7_A5_dialog_content = "舒默……真的是妳……就站在我面前……",
  ui_story_5_7_45_dialog_content = "痛……好痛苦……",
  ui_story_5_7_46_dialog_content = "誰來……救救我們吧……",
  ui_story_5_7_47_dialog_content = "你讓我想起了那群空裔，PlayerName。碾死他們就像碾死一窩螞蟻。",
  ui_story_5_7_48_dialog_content = "一想到我曾經也和你們這些無法戰鬥的渣滓一樣孱弱，我就覺得……噁心。",
  ui_story_5_7_49_dialog_content = "話多。",
  ui_story_5_7_50_dialog_content = "如此微弱的反抗，真令人失望。",
  ui_story_5_7_51_dialog_content = "之前讓那些骯髒的暗鬼襲擊白夜城的，就是妳嗎？",
  ui_story_5_7_52_dialog_content = "那些傢伙沒一個中用的。",
  ui_story_5_7_53_dialog_content = "不可饒恕！用那雙髒手觸碰我們的最後之都，妳會付出代價的！",
  ui_story_5_7_54_dialog_content = "你們又能怎麼樣呢？",
  ui_story_5_7_55_dialog_content = "PlayerName！你還好嗎？！",
  ui_story_5_7_A6_dialog_content = "（冷靜，我要冷靜……無視那股威壓，我可以的……）",
  ui_story_5_7_A7_dialog_content = "（只要一如既往地戰鬥就行，就能把那個人、那個禍亂的源頭，舒默……）",
  ui_story_5_7_A8_dialog_content = "PlayerName！你的眼神——",
  ui_story_5_7_A9_dialog_content = "呼……",
  ui_story_5_7_A10_dialog_content = "薇絲，我沒事。拜託妳和卡蓮就位吧，就像以前那樣，我會全力引導妳們。",
  ui_story_5_7_A11_dialog_content = "……好。我準備好了！",
  ui_story_5_7_56_dialog_content = "那就拜託你來指揮了，PlayerName。我的槍必會穿透，一切邪惡！",
  ui_story_5_7_57_dialog_content = "各位，準備戰鬥！敵人是——舒默！",
  ui_story_5_7_A12_dialog_content = "弱者就該乖乖被碾碎。",
  ui_story_5_7_58_dialog_content = "都說了，弱者就該有弱者的樣子！乖乖躺平不好嗎？掙扎什麼！",
  ui_story_5_7_59_dialog_content = "嘖，真是難纏。指揮、引導，說到底不就是個躲在背後的膽小鬼？",
  ui_story_5_7_60_dialog_content = "不過我承認，你和其他的空裔好像是不太一樣……",
  ui_story_5_7_61_option_content = "不，我跟所有空裔都一樣",
  ui_story_5_7_62_option_content = "對付妳綽綽有餘",
  ui_story_5_7_63_dialog_content = "說什麼蠢話呢，我可不是在誇你，只是在宣判你的死刑。",
  ui_story_5_7_64_dialog_content = "畢竟這種力量在我眼裡不過如此。你們，實在是太弱小了。",
  ui_story_5_7_65_dialog_content = "好強……",
  ui_story_5_7_66_dialog_content = "說吧，被捏碎或是踩爛，選哪一個？",
  ui_story_5_7_67_dialog_content = "就是現在！！",
  ui_story_5_7_68_dialog_content = "嗯？這震動……",
  ui_story_5_7_69_dialog_content = "延長戰！幸好我們拖延時間的戰略還不錯！",
  ui_story_5_7_70_dialog_content = "組件已經順利拿到了！卡蓮、PlayerName！",
  ui_story_5_7_71_dialog_content = "我來拖住她，你們快帶著組件撤退。",
  ui_story_5_7_72_option_content = "可是貢露妳？！",
  ui_story_5_7_73_dialog_content = "我能有什麼問題？正好露一手我的必殺技！",
  ui_story_5_7_74_option_content = "遵命！長官！",
  ui_story_5_7_75_dialog_content = "善於運用遊戲規則是非常強大的能力，妳很不錯！一定要把組件帶回啟光！",
  ui_story_5_7_76_dialog_content = "舒默的攻擊非比尋常，妳一個人……",
  ui_story_5_7_77_dialog_content = "我可不是普通的科研人員！最瞭解力量的也是我！我很強！！",
  ui_story_5_7_78_dialog_content = "我明白了。薇絲，PlayerName，我們走，不能浪費貢露閣下創造的機會。",
  ui_story_5_7_79_dialog_content = "閒聊夠久了吧，快把組件交出來。",
  ui_story_5_7_80_dialog_content = "怎麼辦呢？可是我真的很想和妳打一架呀！",
  ui_story_5_7_A13_dialog_content = "掌握了暗鬼能力的空裔，地獄難度的絕命單挑，聽起來就超熱血刺激的啦！",
  ui_story_5_7_81_dialog_content = "來和我一起玩個遊戲吧！",
  ui_story_5_7_82_dialog_content = "……無聊透頂！",
  ui_story_5_7_83_dialog_content = "薇絲，已經過很久了……貢露那邊還沒捎來消息。",
  ui_story_5_7_84_dialog_content = "貢露前輩……應該不會有問題吧。",
  ui_story_5_7_85_dialog_content = "時間不允許我們繼續拖延，恐怕必須起飛了。",
  ui_story_5_7_86_dialog_content = "我知道……",
  ui_story_5_7_87_dialog_content = "你們有沒有聽到什麼聲音？通訊器好像響了！",
  ui_story_5_7_88_dialog_content = "是……",
  ui_story_5_7_89_dialog_content = "<color=#FFB400>貢露前輩</color>？！",
  ui_story_5_8_1_dialog_content = "薇絲，快帶著組件坐臨空者號回啟光，回……",
  ui_story_5_8_2_dialog_content = "貢露前輩！",
  ui_story_5_8_3_dialog_content = "閉嘴！我是叫你說這個嗎？！",
  ui_story_5_8_4_dialog_content = "聽好雜魚們，我不會再說第二遍。",
  ui_story_5_8_5_dialog_content = "三十分鐘內立即返回這裡並把「自長單元」交給我，不然這傢伙必死無疑。",
  ui_story_5_8_6_dialog_content = "別理她！快回去！這是命令！",
  ui_story_5_8_7_dialog_content = "給我安靜！！",
  ui_story_5_8_8_dialog_content = "三十分鐘太短了，就算馬上請求啟光後援，也不可能趕得上……",
  ui_story_5_8_9_dialog_content = "現在將「自長單元」帶回去能夠保全更多人的生命。",
  ui_story_5_8_10_dialog_content = "我知道這個時候應該聽從長官的指令，這一直是做啟光人的第一要務……",
  ui_story_5_8_11_dialog_content = "但我實在沒法眼睜睜看著貢露前輩死在這裡。",
  ui_story_5_8_12_dialog_content = "妳還是像從前一樣，說好聽點是善良，其實根本就是優柔寡斷。",
  ui_story_5_8_13_dialog_content = "一個人的生命還是一群人的生命，真的很難做出選擇嗎？",
  ui_story_5_8_14_dialog_content = "……我想要保護每一個人。",
  ui_story_5_8_15_dialog_content = "吼——！",
  ui_story_5_8_16_dialog_content = "先解決這些登上巨像的不速之客，之後的事我們再從長計議吧。",
  ui_story_5_10_1_dialog_content = "讓我猜猜，你們這些喜歡躲躲藏藏的雜魚還沒有動作，是不是在拖延時間呢？",
  ui_story_5_10_2_dialog_content = "可惜我的耐心有限，還有二十分鐘——不，十九分鐘。",
  ui_story_5_10_3_dialog_content = "十九分鐘後我會一點點撕碎這個黃毛丫頭的身體。",
  ui_story_5_10_4_dialog_content = "她的慘叫，想想都覺得熱血刺激呢。",
  ui_story_5_10_5_dialog_content = "除了交出組件，沒有其它辦法能救貢露前輩了嗎？",
  ui_story_5_10_6_dialog_content = "這瘋子。",
  ui_story_5_10_7_option_content = "未必只有一種解決辦法",
  ui_story_5_10_8_dialog_content = "欸？",
  ui_story_5_10_9_dialog_content = "我有個想法，也許能逆轉局勢……十五分鐘應該夠了。",
  ui_story_5_10_10_dialog_content = "你的意思是？",
  ui_story_5_10_11_dialog_content = "或許我們可以用迂迴戰術……",
  ui_story_5_10_12_option_content = "我想要保護大家",
  ui_story_5_10_13_dialog_content = "PlayerName……你認同我的想法嗎？",
  ui_story_5_10_14_dialog_content = "無論是貢露的生命，還是大家的生命，都要保護。",
  ui_story_5_10_15_dialog_content = "薇絲是這樣，你也是這樣，真是敗給你們了。",
  ui_story_5_10_16_dialog_content = "不過你既然這麼說，想必心裡已經有辦法了吧。",
  ui_story_5_10_17_dialog_content = "是的！這會很冒險，但……我需要妳們的協助。",
  ui_story_5_10_A1_dialog_content = "接下來我們要主動出擊，而且動作要快！",
  ui_story_5_10_A2_dialog_content = "請聽我說，方法是這樣的……",
  ui_story_5_10_18_dialog_content = "只剩下幾分鐘了，沒有離開也沒有降落。還在糾結嗎？",
  ui_story_5_10_19_dialog_content = "王座啟——動！",
  ui_story_5_10_20_dialog_content = "不安分的傢伙。",
  ui_story_5_10_21_dialog_content = "還是沒有效果……？！",
  ui_story_5_10_22_dialog_content = "三次自殺式襲擊，還真是不要命。妳最好乖一點，現在還不到妳死的時候。",
  ui_story_5_10_23_dialog_content = "震撼——連——",
  ui_story_5_10_24_dialog_content = "好暈！遊戲已經結束了嗎……",
  ui_story_5_10_25_dialog_content = "睡吧，睡吧，再睡上幾分鐘我就會讓你永遠深眠。",
  ui_story_5_10_A3_dialog_content = "這邊還有一隻！",
  ui_story_5_10_A4_dialog_content = "非常迅速！應該沒有被舒默發現吧？",
  ui_story_5_10_A5_dialog_content = "我真的不擅長這種躲躲藏藏的作戰，PlayerName。",
  ui_story_5_10_A6_dialog_content = "已經做得很好了。繼續前進吧，我們也只剩這一個選擇了。",
  ui_story_5_13_1_dialog_content = "還有五分鐘，喂，起來。",
  ui_story_5_13_2_dialog_content = "呼、呼嚕……眼前都是星星，吃了星星能升級嗎……",
  ui_story_5_13_3_dialog_content = "妳給我起來。",
  ui_story_5_13_4_dialog_content = "哎哎哎！剛才嫌我吵把我打暈，現在又要把我弄醒，不愧是大反派。",
  ui_story_5_13_5_dialog_content = "只剩五分鐘了，他們還沒有動靜，該不會已經放棄妳了吧？",
  ui_story_5_13_6_dialog_content = "這才對嘛。他們要是敢回來，妳就算不動手我也會出手揍他們一頓。",
  ui_story_5_13_7_dialog_content = "算了，正好我也等得煩了。",
  ui_story_5_13_A1_dialog_content = "雖然麻煩一些，但是現在解決妳，再去處理掉他們也是個不錯的選擇。",
  ui_story_5_13_8_dialog_content = "喂喂喂，妳真的要提前撕票嗎？這不符合遊戲規則啊！",
  ui_story_5_13_9_dialog_content = "遊戲規則？強者就是規則！",
  ui_story_5_13_A2_dialog_content = "永遠閉上妳那張囉嗦的嘴吧——",
  ui_story_5_13_10_dialog_content = "什麼！！",
  ui_story_5_13_11_dialog_content = "冰花綻放！！",
  ui_story_5_13_12_dialog_content = "竟然是偷襲……",
  ui_story_5_13_13_dialog_content = "她的情緒和狀態很不穩定，我覺得她很有可能不會遵守約定。",
  ui_story_5_13_14_dialog_content = "貢露長官的處境非常危險，我們必須盡快行動。",
  ui_story_5_13_A3_dialog_content = "我準備好了，PlayerName。就按照你的計劃進行吧！",
  ui_story_5_13_A13_dialog_content = "將臨空者號停靠在原來的位置，干擾舒默的判斷，然後……",
  ui_story_5_13_17_dialog_content = "突襲她！她肯定想不到我們敢主動出擊的！",
  ui_story_5_13_18_dialog_content = "佯裝猶豫不決，然後偷襲？",
  ui_story_5_13_19_dialog_content = "看來這個簡單的招數確實奏效了！放棄吧舒默！周圍的暗鬼也被我們收拾乾淨了！",
  ui_story_5_13_20_dialog_content = "哼，你們要是以為這就算「成功」……",
  ui_story_5_13_21_dialog_content = "可別忘了我啊！！看招！！",
  ui_story_5_13_22_dialog_content = "攻擊奏效了！大反派受傷，我們也重新湊齊四人隊伍！情勢大逆轉！",
  ui_story_5_13_A4_dialog_content = "你們已經把最關鍵的組件藏在安全的地方了吧！那我們現在可以光明正大的圍毆她了！",
  ui_story_5_13_24_dialog_content = "卡蓮，我們一起上！！",
  ui_story_5_13_26_dialog_content = "好！不要給她反應的時間！",
  ui_story_5_13_27_dialog_content = "看來妳也就只有這種程度了。",
  ui_story_5_13_28_dialog_content = "……我竟然，會被你們這些廢物小看。",
  ui_story_5_13_29_dialog_content = "周圍的氣氛好像變了？！",
  ui_story_5_13_30_dialog_content = "她的力量，和之前的感覺完全不一樣！",
  ui_story_5_13_31_dialog_content = "無法忍受！既然你們趕著來送死，那我也不必手下留情了！",
  ui_story_5_13_A14_dialog_content = "不錯！比剛才更能打了！幾乎快要可以取悅我了。",
  ui_story_5_13_A15_dialog_content = "但你剛才那副「能贏」的表情，實在太令人作噁！！跪下！！",
  ui_story_5_13_A16_dialog_content = "這、為什麼妳的力量又提升了？！",
  ui_story_5_13_A17_dialog_content = "難道妳一直在……保留實力嗎，就是為了……玩弄我們？",
  ui_story_5_13_32_dialog_content = "（會被殺掉！這樣下去，說不定真的會死——）",
  ui_story_5_13_A5_dialog_content = "（當年的同胞們面臨的是這種絕望嗎？這充滿壓迫感的力量……）",
  ui_story_5_13_33_dialog_content = "（接受暗鬼力量的空裔，竟然會……強大到這個地步？）",
  ui_story_5_13_34_dialog_content = "震撼嗎？弱小的空裔也可以變得這樣強大，這便是日蝕賜予的力量！",
  ui_story_5_13_35_dialog_content = "<size=45>比光靈還要強大！</size>",
  ui_story_5_13_36_dialog_content = "好、好痛……無法……呼吸。",
  ui_story_5_13_37_dialog_content = "現在你們該做出選擇了，要她的性命還是「自長單元」？",
  ui_story_5_13_38_dialog_content = "咳……不、不能給她……",
  ui_story_5_13_39_dialog_content = "貢露！薇絲，還有卡蓮……",
  ui_story_5_13_40_dialog_content = "可惡，我還能戰鬥…還能戰……鬥……",
  ui_story_5_13_41_dialog_content = "我……",
  ui_story_5_13_42_dialog_content = "嗯，你好像有什麼想法？你難道是……想和我戰鬥？毫無戰鬥能力的你？",
  ui_story_5_13_43_dialog_content = "哈哈……哈哈哈哈，這也太可笑了。",
  ui_story_5_13_44_dialog_content = "我……雖然沒有戰鬥能力，但我還有拳頭……",
  ui_story_5_13_45_dialog_content = "舒默！！！",
  ui_story_5_13_46_dialog_content = "PlayerName，別去！",
  ui_story_5_13_47_dialog_content = "儘管我是沒有光能的空裔……但我並不害怕戰鬥。",
  ui_story_5_13_48_dialog_content = "我必須保護我的同伴、我的同胞，我的家人！！！",
  ui_story_5_13_A6_dialog_content = "拳頭打爛了就用咬的，牙齒被拔光了，那就用頭撞！",
  ui_story_5_13_A7_dialog_content = "妳休想讓我屈服，妳休想讓空裔屈服！舒默……這次，我要……",
  ui_story_5_13_49_dialog_content = "<size=45>擋在她們的前面！</size>",
  ui_story_5_13_A8_dialog_content = "……",
  ui_story_5_13_A9_dialog_content = "哼……無聊。",
  ui_story_5_13_50_dialog_content = "我早就聽夠這種老套的「豪言壯語」了，有必要喊成這樣？",
  ui_story_5_13_51_dialog_content = "呃啊……",
  ui_story_5_13_52_dialog_content = "PlayerName，為什麼要這麼做……",
  ui_story_5_13_53_dialog_content = "垃圾，快做出選擇，是要組件，還是她們的生命？我要倒數了，十、九……",
  ui_story_5_13_54_option_content = "我有個條件……",
  ui_story_5_13_55_option_content = "好，組件給妳",
  ui_story_5_13_56_dialog_content = "哼，你居然想跟我講條件嗎？哈哈哈……",
  ui_story_5_13_57_dialog_content = "組件可以給妳，但是妳要先放她們走！",
  ui_story_5_13_58_dialog_content = "笑死我了，你怎麼還真的講起條件了？跪下求饒吧。",
  ui_story_5_13_59_dialog_content = "你先放她們走，我的命和組件都是妳的。否則，我會毀了它。",
  ui_story_5_13_60_dialog_content = "毀了它？你現在這副「英勇赴死」的表情是跟孟德爾頌學的嗎？真讓人噁心。",
  ui_story_5_13_F1_dialog_content = "好吧，她們可以走了。",
  ui_story_5_13_F2_dialog_content = "組件給妳。",
  ui_story_5_13_F3_dialog_content = "空裔總是這麼可憐，沒有力量就只能任人宰割，連苟活的機會都是強者施捨的。",
  ui_story_5_13_F4_dialog_content = "哈哈哈，這種任人宰割的感覺是不是讓你很不爽？",
  ui_story_5_13_F5_dialog_content = "是不是又讓你想到往事？",
  ui_story_5_13_F6_dialog_content = "記住這種感覺，身為<size=45>弱者</size>，就要熟悉這種屈辱，不然你連苟活的機會都沒有。",
  ui_story_5_13_61_dialog_content = "空裔總是這麼可憐，沒有力量就只能任人宰割，連苟活的機會都是強者施捨的。",
  ui_story_5_13_F7_dialog_content = "要不是因為組件，我連看都懶得看你們一眼。",
  ui_story_5_13_68_dialog_content = "恭喜你們保住小命，這是強者的施捨，感恩戴德地接受吧，哈哈哈……",
  ui_story_5_13_69_dialog_content = "貢露前輩妳還好嗎？妳已經昏迷兩小時了……",
  ui_story_5_13_70_dialog_content = "只剩下一絲血……但幸好還是撐過來了……",
  ui_story_5_13_F8_dialog_content = "很抱歉，為了救我，組件還是被拿走了。",
  ui_story_5_13_71_dialog_content = "不，貢露前輩，是我們不夠強大……",
  ui_story_5_13_72_dialog_content = "不過至少，大家都還活著，一切還不算太糟。",
  ui_story_5_13_73_dialog_content = "你們已經很厲害了！",
  ui_story_5_13_74_dialog_content = "之前菲莉詩跟我說這件事的時候我還不以為然，但親眼看見後……",
  ui_story_5_13_A10_dialog_content = "舒默實在太強大，遠超乎我之前的想像！",
  ui_story_5_13_75_dialog_content = "我會將這裡發生的事情全部上報，告知高層這件事的嚴重性。",
  ui_story_5_13_76_dialog_content = "接下來還有第三個組件是嗎？",
  ui_story_5_13_77_dialog_content = "<color=#FFB400>「火控模組」……</color>",
  ui_story_5_13_78_dialog_content = "用於改裝巨像，使巨像具備攻擊能力的超級武器組件嗎……但我們並不知道它在哪。",
  ui_story_5_13_79_option_content = "我知道該怎麼做",
  ui_story_5_13_F9_dialog_content = "我已經跟她接觸夠多次了，死都不會忘記她的氣息。",
  ui_story_5_13_F10_dialog_content = "她現在離我們還不遠，我只需要閉上眼睛……",
  ui_story_5_13_F11_dialog_content = "只要我像「弱者」一樣無聲無息地潛入，絕不會引起她的注意。",
  ui_story_5_13_80_dialog_content = "（這是……一座充斥著無數陷阱、錯綜複雜的迷宮？）",
  ui_story_5_13_81_dialog_content = "（看起來神祕、陰暗，有著各式各樣惡趣味的收藏品。）",
  ui_story_5_13_82_dialog_content = "舒默一定知道該前往哪個地方……",
  ui_story_5_13_83_dialog_content = "……<color=#FFB400>低語迴廊</color>……",
  ui_story_5_13_85_option_content = "低語迴廊！",
  ui_story_6_1_1_dialog_content = "舒默實在是個可怕的對手……",
  ui_story_6_1_2_dialog_content = "等她集齊想要的組件後只會更難對付……",
  ui_story_6_1_3_dialog_content = "（卡蓮和薇絲都很消沉，我得說點什麼轉換一下氣氛。）",
  ui_story_6_1_F1_dialog_content = "如果直接去追擊舒默，我們或許能夠阻止她拿到下一個組件。",
  ui_story_6_1_F2_dialog_content = "當然，我知道這很危險……",
  ui_story_6_1_4_option_content = "卡蓮，妳的看法是？",
  ui_story_6_1_5_dialog_content = "不能拖延，現在要趕快去追擊舒默。",
  ui_story_6_1_6_option_content = "薇絲，妳怎麼認為呢？",
  ui_story_6_1_7_dialog_content = "我已經向總部發送消息，報告我們將前往<color=#FFB400>低語迴廊</color>。",
  ui_story_6_1_8_dialog_content = "這低語迴廊……有人瞭解嗎？",
  ui_story_6_1_9_dialog_content = "卡蓮，那裡應該是屬於<color=#FFB400>影鎮</color>的地盤。我在白夜城留學時聽說過。",
  ui_story_6_1_10_dialog_content = "不愧是從不曠課的好學生，妳還知道更詳細的資訊吧。",
  ui_story_6_1_11_dialog_content = "啊，咳咳。低語迴廊原本是一座影鎮外的地下遺跡。",
  ui_story_6_1_12_dialog_content = "白夜城的人發現它後，從中挖出很多值錢的東西。",
  ui_story_6_1_13_dialog_content = "但那裡沒有挖掘價值後，便成了無人看管的廢墟。",
  ui_story_6_1_14_dialog_content = "後來成為流浪者和罪犯的聚集地，變得混亂不堪。",
  ui_story_6_1_A1_dialog_content = "十幾年前，名為<color=#FFB400>伊斯塔萬幫</color>的團體出現在影鎮。",
  ui_story_6_1_A2_dialog_content = "這個團體的首領名為伊斯塔萬，他因受大家愛戴而被尊稱為「影主」。",
  ui_story_6_1_A3_dialog_content = "他們接管低語迴廊後，就沒人敢隨意進入了。",
  ui_story_6_1_A4_dialog_content = "聽說現在已經變成存放各類珍奇古玩的「藏館」。",
  ui_story_6_1_A5_dialog_content = "身邊有妳這樣一本「活字典」可真方便呢……",
  ui_story_6_1_F3_dialog_content = "嘿嘿，謝謝。",
  ui_story_6_1_A6_dialog_content = "我還試著寄一封說明信給「影主」，希望得到他們支持。",
  ui_story_6_1_A7_dialog_content = "說不定到了低語迴廊，就會有影主的人來接應我們。",
  ui_story_6_1_A8_dialog_content = "如果妳的文法還是像之前那樣，我想影主是不會理妳的。",
  ui_story_6_1_F4_dialog_content = "哎呀，就算寫得不好還是要硬著頭皮寄出去嘛！",
  ui_story_6_1_15_dialog_content = "對了！剛收到一條消息，啟光軍部又召開了一次會議……",
  ui_story_6_1_16_dialog_content = "請各位軍團長想清楚。低語迴廊雖是影主的財產，但考慮到敵人的身分……",
  ui_story_6_1_17_dialog_content = "再加上對貢露科研長出手的行為，這是公然挑釁。",
  ui_story_6_1_F5_dialog_content = "如果不是PlayerName等人捎來消息，我們可能對舒默的行動一無所知。",
  ui_story_6_1_18_dialog_content = "如果不是有那幾個小鬼在，說不定根本不會有這件事？",
  ui_story_6_1_19_dialog_content = "不，PlayerName是否存在和舒默有沒有要蒐集武器組件沒有直接關係。",
  ui_story_6_1_20_dialog_content = "責任的事先放一邊，緋！要不要和我一起出兵一句話！",
  ui_story_6_1_21_dialog_content = "啊……那個……",
  ui_story_6_1_22_dialog_content = "不是我不想，對冒犯啟光的傢伙我和你有一樣的心情……",
  ui_story_6_1_23_dialog_content = "但大元帥的命令是「靜候時機」。",
  ui_story_6_1_X23_dialog_content = "為什麼大元帥會下達這種命令？",
  ui_story_6_1_X24_dialog_content = "請大家先稍安勿躁！各位的心情我可以理解。",
  ui_story_6_1_X25_dialog_content = "但沒有大元帥的命令，我們也只能繼續觀察情況了！",
  ui_story_6_1_X26_dialog_content = "也許她有更深遠的考慮呢？相信啟明之光吧！",
  ui_story_6_1_X27_dialog_content = "……",
  ui_story_6_1_X28_dialog_content = "巴頓他們呢？為什麼沒出現？",
  ui_story_6_1_X29_dialog_content = "如果他和那個筋肉女也同意出兵的話，多少能向大元帥再爭取一下。",
  ui_story_6_1_X30_dialog_content = "其他軍團長也接到臨時任務了呢～",
  ui_story_6_1_X31_dialog_content = "小希妳要和我一起去白夜城近郊布防喔！",
  ui_story_6_1_25_dialog_content = "畢竟還是要有檯面上的動作嘛。",
  ui_story_6_1_27_dialog_content = "情況就是這樣……所以，無論舒默有什麼目的，只能靠我們自己去探明了。",
  ui_story_6_1_28_dialog_content = "上次我們幸運地得到菲莉詩前輩和貢露長官的幫助，但這次……",
  ui_story_6_1_F6_dialog_content = "我們要去的地方在影鎮管轄範圍內，而影鎮上方就是白夜城……",
  ui_story_6_1_F7_dialog_content = "嗯，我明白。啟光和白夜城雖是合作關係，但還是有所顧忌。",
  ui_story_6_1_29_dialog_content = "但這樣下去對兩方都沒有好處，尤其考慮到現在的處境。",
  ui_story_6_1_30_dialog_content = "我會去爭取一下白夜城的援助，至少……",
  ui_story_6_1_31_dialog_content = "卡蓮衛隊長，情況如何？",
  ui_story_6_1_32_dialog_content = "很抱歉，我們失敗了。<color=#FFB400>「自長單元」</color>已被搶走。",
  ui_story_6_1_33_dialog_content = "是否有人員傷亡？",
  ui_story_6_1_34_dialog_content = "沒有人員傷亡。",
  ui_story_6_1_35_dialog_content = "但那傢伙已經早我們一步前往低語迴廊。",
  ui_story_6_1_36_dialog_content = "舒瓦茲殿下，我請求派出守衛隊，最好是四天使前來支援。",
  ui_story_6_1_37_dialog_content = "不行。",
  ui_story_6_1_38_dialog_content = "父……殿下，如果再讓那傢伙搶走<color=#FFB400>「火控模組」</color>，後果不堪設想！",
  ui_story_6_1_39_dialog_content = "那傢伙甚至有可能在改裝巨像後做出威脅白夜城的舉動！",
  ui_story_6_1_40_dialog_content = "是的，卡蓮衛隊長，我正是考量到這點才決定不派出衛隊。",
  ui_story_6_1_41_dialog_content = "舒瓦茲殿下，身為衛隊長，我擁有衛隊的管轄權，請允許我調遣她們。",
  ui_story_6_1_42_dialog_content = "我可以解除妳的這項權利，衛隊長。",
  ui_story_6_1_43_dialog_content = "那麼我作為衛隊長，將代表白夜城支援他們——即使只有我一個人。",
  ui_story_6_1_45_dialog_content = "卡蓮，我欣賞妳的勇敢。",
  ui_story_6_1_46_dialog_content = "PlayerName！作為白夜之下的子民，我希望你們能保證卡蓮衛隊長的安全。",
  ui_story_6_1_47_dialog_content = "欸？是、是。",
  ui_story_6_1_48_dialog_content = "<size=30>我和PlayerName又不是白夜城的人……</size>",
  ui_story_6_1_49_dialog_content = "即使卡蓮不是衛隊長，我們也會互相保護對方，畢竟我們是夥伴啊！",
  ui_story_6_1_50_dialog_content = "……閒話就先免了。我們應該快到了吧！",
  ui_story_6_1_51_dialog_content = "這附近好荒涼，應該已經很久沒人來過了。",
  ui_story_6_1_52_dialog_content = "多虧了臨空者號！否則肯定追不上舒默！",
  ui_story_6_1_F8_dialog_content = "臨空者號，薇絲在誇你喔。",
  ui_story_6_1_53_dialog_content = "我本來就是為了你存在，能幫到你們是我的榮幸。",
  ui_story_6_1_54_dialog_content = "這裡的氣氛也和之前的空谷一樣令人不安，請務必小心。",
  ui_story_6_1_55_dialog_content = "PlayerName，此地各處都可能出現暗鬼。臨空者號現在的位置是否安全？",
  ui_story_6_1_56_dialog_content = "停在那片山丘外側，正好有一片樹林可以掩藏巨像。",
  ui_story_6_1_57_dialog_content = "放心，他已經掌握「隱匿」的技巧。我們可以安心戰鬥，他會在那裡等我們回去。",
  ui_story_6_1_58_dialog_content = "突然有種「有人在等著我回家」的溫馨感呢……要是再有個浴缸什麼的就更好了。",
  ui_story_6_1_59_dialog_content = "你的想法未免也太幼稚了。",
  ui_story_6_1_A9_dialog_content = "另外，這種地方會有你說的「藏館」？怎麼看都是荒郊野外。",
  ui_story_6_1_A10_dialog_content = "低語迴廊的入口隱蔽，如果不好好調查可是找不到的喔。",
  ui_story_6_1_A11_dialog_content = "難道說，薇絲妳已經……",
  ui_story_6_1_A12_dialog_content = "沒錯！入口處就在我們腳下！",
  ui_story_6_1_A13_dialog_content = "腳下……？低語迴廊，在地底嗎？",
  ui_story_6_1_A14_dialog_content = "注意地面！我要啟動開關了～",
  ui_story_6_1_A15_dialog_content = "地面……在裂開？！",
  ui_story_6_1_A16_dialog_content = "哇——這可真是……",
  ui_story_6_1_A17_dialog_content = "大費周章呢。完全不懂幹嘛做這種設計。",
  ui_story_6_1_A18_dialog_content = "只有不法分子和見不得光的贓物，才需要藏匿得如此隱蔽。",
  ui_story_6_1_A19_dialog_content = "這下面就是低語迴廊了。PlayerName，你能感應到什麼？",
  ui_story_6_1_60_dialog_content = "舒默……就在這下面，我能感覺到從地底傳來的寒意。",
  ui_story_6_1_A20_dialog_content = "果然，這裡面好冷！",
  ui_story_6_1_A21_dialog_content = "現在不是抱怨的時候，我們必須加快腳步。",
  ui_story_6_1_61_dialog_content = "有辦法直接感應到她的實際方位嗎？",
  ui_story_6_1_62_dialog_content = "抱歉，就算用感應也只能確定她在低語迴廊裡面，我看不出她的具體位置。",
  ui_story_6_1_63_dialog_content = "這就棘手了……",
  ui_story_6_1_64_dialog_content = "據說低語迴廊裡面地形複雜，到處都是暗門暗道，只有影主對它瞭若指掌。",
  ui_story_6_1_65_dialog_content = "就是因為如此，這裡才會成為「藏館」。",
  ui_story_6_1_F9_dialog_content = "畢竟把東西放在這裡，可比放在影鎮安全多了。",
  ui_story_6_1_66_dialog_content = "等等，有人來了！",
  ui_story_6_1_67_dialog_content = "小心！對方很可能是暗鬼……",
  ui_story_6_1_68_dialog_content = "PlayerName一點都不慌張，我猜對方是光靈。",
  ui_story_6_1_70_dialog_content = "這裡很熱鬧嘛！隔著六堵牆和七道門都能聽到你們熱情的討論。",
  ui_story_6_1_71_dialog_content = "喔呵呵，真有意思，白夜城的貴族小姐、啟光的隨軍小妹，還有空裔……",
  ui_story_6_1_72_dialog_content = "你們應該就是那些大人物口中的巨像小分隊了。",
  ui_story_6_1_73_dialog_content = "雖然白夜城和啟光都持觀望態度，但影主特地讓我來接應你們～",
  ui_story_6_1_X73_dialog_content = "真是難處理呢～",
  ui_story_6_1_74_dialog_content = "果然……關鍵時刻出現了貴人！",
  ui_story_6_1_F10_dialog_content = "叫我「涉」就可以了。你們需要什麼幫助嗎？",
  ui_story_6_1_75_option_content = "請問之前有其他人進入這裡嗎？",
  ui_story_6_1_76_dialog_content = "這裡平常很少有人來，不過，最近似乎有暗鬼來過，但是沒損失什麼東西。",
  ui_story_6_1_77_dialog_content = "舒默……",
  ui_story_6_1_78_dialog_content = "我比較關心的是，你們要面對的敵人現在在裡面嗎？",
  ui_story_6_1_79_dialog_content = "我更關心的是，妳剛才在一旁偷聽？",
  ui_story_6_1_80_dialog_content = "嗯～PlayerName，你的女伴倒是十分敏銳嘛～",
  ui_story_6_1_81_dialog_content = "嗯，咳、涉女士，如果妳不想回答這個問題也沒關係，能請妳介紹一下這裡嗎？",
  ui_story_6_1_82_dialog_content = "大家都知道這裡原本是一片廢墟。",
  ui_story_6_1_83_dialog_content = "因此價格低廉。後來影主買下這裡，只有他最瞭解這個地方。",
  ui_story_6_1_84_dialog_content = "雖然這裡沒有守衛，但擅自闖入的人通常只有「踩中陷阱」和「迷路」兩個下場。",
  ui_story_6_1_85_dialog_content = "因此你們如果想找到存放東西的房間，肯定需要嚮導。",
  ui_story_6_1_86_dialog_content = "所以我們的嚮導是……",
  ui_story_6_1_87_dialog_content = "這裡還有別人嗎？",
  ui_story_6_1_88_dialog_content = "啊！原來是妳……那就有勞了。",
  ui_story_6_1_89_dialog_content = "嗯？我什麼時候說過要當嚮導了呀？",
  ui_story_6_1_90_dialog_content = "這女孩真可愛呢～PlayerName，你還真是幸運……",
  ui_story_6_1_91_dialog_content = "……涉女士恐怕是有什麼誤解。",
  ui_story_6_1_92_dialog_content = "那妳知道我們在找什麼嗎？有聽過「火控模組」嗎？",
  ui_story_6_1_93_dialog_content = "嗯……不知道呢……",
  ui_story_6_1_94_option_content = "能請妳介紹一下這裡嗎？",
  ui_story_6_1_95_dialog_content = "大家都知道這裡原本是一片廢墟。",
  ui_story_6_1_96_dialog_content = "因此價格低廉。後來影主買下這裡，只有他最瞭解這個地方。",
