  ui_story_6_1_98_dialog_content = "因此你們如果想找到存放東西的房間，肯定需要嚮導。",
  ui_story_6_1_99_dialog_content = "所以我們的嚮導是……",
  ui_story_6_1_100_dialog_content = "這裡還有別人嗎？",
  ui_story_6_1_101_dialog_content = "啊！原來是妳……那就有勞了。",
  ui_story_6_1_102_dialog_content = "你真可愛～我什麼時候說過要當嚮導了呀～",
  ui_story_6_1_103_dialog_content = "PlayerName，你的女伴們真是可愛又有禮貌呢～",
  ui_story_6_1_104_dialog_content = "咳、嗯，涉女士，請妳不要轉移話題，我們在趕時間……",
  ui_story_6_1_105_dialog_content = "喔？也是，畢竟敵人說不定已經在裡面了。",
  ui_story_6_1_106_dialog_content = "這附近到處都是暗鬼活躍的痕跡呢，而且全都延伸到低語迴廊裡面……",
  ui_story_6_1_107_dialog_content = "現在的情況很不妙～你們要找的東西說不定已經被拿走了呢！",
  ui_story_6_1_108_dialog_content = "……那麼，可以有勞您帶我們前往火控模組的收藏處嗎？",
  ui_story_6_1_109_dialog_content = "欸？什麼東西，沒聽過哦。",
  ui_story_6_1_110_option_content = "其實，我們在找一樣東西",
  ui_story_6_1_111_dialog_content = "明白～到這裡來的人，都是來找東西的呢～只不過暗鬼似乎已經先到了。",
  ui_story_6_1_112_dialog_content = "我知道暗鬼已經進去了……我們必須盡快！",
  ui_story_6_1_113_dialog_content = "稍安勿躁，親愛的。",
  ui_story_6_1_114_dialog_content = "大家都知道這裡原本是一片廢墟。",
  ui_story_6_1_115_dialog_content = "因此價格低廉。後來影主買下這裡，只有他最瞭解這個地方。",
  ui_story_6_1_116_dialog_content = "雖然這裡沒有守衛，但擅自闖入的人通常只有「踩中陷阱」和「迷路」兩個下場。",
  ui_story_6_1_117_dialog_content = "因此你們如果想找到存放東西的房間，肯定需要嚮導。",
  ui_story_6_1_118_dialog_content = "所以我們的嚮導是……",
  ui_story_6_1_119_dialog_content = "這裡還有別人嗎？",
  ui_story_6_1_120_dialog_content = "啊！原來是妳……那就有勞了。",
  ui_story_6_1_121_dialog_content = "嗯？我什麼時候說過要當嚮導了呀～",
  ui_story_6_1_122_dialog_content = "這位姑娘很可愛呢～PlayerName，你的福氣真是不錯。",
  ui_story_6_1_123_dialog_content = "涉女士，請說正事……",
  ui_story_6_1_124_dialog_content = "涉閣下，妳知道我們在找什麼嗎？聽過「火控模組」嗎？",
  ui_story_6_1_125_dialog_content = "嗯……不知道呢……",
  ui_story_6_1_126_dialog_content = "<size=30>她在撒謊。</size>",
  ui_story_6_1_127_dialog_content = "<size=30>我知道。</size>",
  ui_story_6_1_128_dialog_content = "涉女士，我們並不打算擅自闖入這裡，那封說明信就是最好的證明。",
  ui_story_6_1_129_dialog_content = "我知道呢，你們想阻止那個「舒默」吧？",
  ui_story_6_1_130_dialog_content = "對。我想妳已經聽說白夜城發生的事情了。",
  ui_story_6_1_131_dialog_content = "舒默為了拿到<color=#FFB400>「火控模組」</color>一定會不擇手段。",
  ui_story_6_1_132_dialog_content = "當我們得知她會來這時就立刻通知影主。我們擔心，如果有大批暗鬼入侵……",
  ui_story_6_1_F11_dialog_content = "影鎮可能會陷入危險……嗯，話說得很誠懇呢～很難不相信你呢。",
  ui_story_6_1_F12_dialog_content = "不過，你們又是怎麼知道她會來這的？",
  ui_story_6_1_F13_dialog_content = "我可以老實回答妳這點……我憑藉空裔的能力，想辦法感應到她的行蹤。",
  ui_story_6_1_134_dialog_content = "喔？空裔還真是名不虛傳。不錯，為了獎勵你的坦誠，那我就姑且當一回響導吧～",
  ui_story_6_1_135_dialog_content = "謝謝，那就拜託妳了。",
  ui_story_6_1_136_dialog_content = "可愛～～",
  ui_story_6_1_137_dialog_content = "……還有幾層啊？我們快到了嗎？",
  ui_story_6_1_138_dialog_content = "還早～剛剛才到外圍呢！後面的路途還有好幾倍長。",
  ui_story_6_1_139_dialog_content = "天啊，這裡簡直比迦南城還復雜。",
  ui_story_6_1_140_dialog_content = "「火控模組」為什麼會藏在這裡？",
  ui_story_6_1_141_dialog_content = "據說是影主在十幾年前那場對抗暗鬼的戰爭中，在一處廢棄戰場上找到它。",
  ui_story_6_1_142_dialog_content = "我也只見過它一次，看起來就是個布滿灰塵的老古董。",
  ui_story_6_1_143_dialog_content = "如果不是你們要找，或許它會永遠被藏在這。",
  ui_story_6_1_144_dialog_content = "停。這裡……好像不太對勁。",
  ui_story_6_1_145_dialog_content = "感覺這道門被什麼人破壞過？",
  ui_story_6_1_146_dialog_content = "這種破壞痕跡一定不是光靈留下的。",
  ui_story_6_1_147_dialog_content = "哎～我可一點也不想戰鬥啊～",
  ui_story_6_1_148_dialog_content = "PlayerName，你能感覺到什麼？",
  ui_story_6_1_149_dialog_content = "舒默的氣息一直在。",
  ui_story_6_1_150_dialog_content = "果然被她搶了先機。我們距離她有多遠？",
  ui_story_6_1_151_dialog_content = "不近，但也不遠……暗鬼就在附近，大家務必小心。",
  ui_story_6_1_152_dialog_content = "……",
  ui_story_6_1_153_dialog_content = "那還趕得上！她沒有嚮導可能迷路。但我們有……",
  ui_story_6_1_154_dialog_content = "喂！嚮導！妳要去哪裡？往反方向前進嗎？",
  ui_story_6_1_155_dialog_content = "涉女士，妳……反悔了嗎？",
  ui_story_6_1_156_dialog_content = "畢竟這件事很危險，涉女士，我們不會勉強妳……",
  ui_story_6_1_157_dialog_content = "的確很危險，但臨陣退縮的人只會害了與其並肩戰鬥的同伴。",
  ui_story_6_1_158_dialog_content = "各位～我什麼時候說要「臨陣退縮」了？我依舊是你們的嚮導喔～",
  ui_story_6_1_159_dialog_content = "不過我確實不擅長戰鬥呢～所以我就不和你們待在一起啦～",
  ui_story_6_1_160_dialog_content = "可是不待在一起，你要怎麼當嚮導呢。難道遠距指點嗎……",
  ui_story_6_1_161_dialog_content = "正如可愛的薇絲所說，我就在此地和你們保持通訊～",
  ui_story_6_1_162_dialog_content = "只要你們能說出周圍大概樣子，我就能知道具體位置喔～",
  ui_story_6_1_163_dialog_content = "我就知道……這是他們影鎮的處世哲學，薇絲。",
  ui_story_6_1_164_dialog_content = "可是我剛才的意思並不是想讓她遠程指點……涉女士，我覺得，我們還是一起走比較好。",
  ui_story_6_1_165_dialog_content = "喔？說得有道理呢～那我就去外面等你們了喔～我會遠程指點各位，我們隨時保持聯繫～",
  ui_story_6_1_168_dialog_content = "另外，如果你們能活著出來，親愛的PlayerName……",
  ui_story_6_1_169_dialog_content = "記得來我店裡光顧喔。我們現在也算是朋友了，會給你們友情價的～",
  ui_story_6_1_170_dialog_content = "祝你們好運～",
  ui_story_6_1_171_dialog_content = "這位涉女士一定是個很會做生意的商人……",
  ui_story_6_1_172_dialog_content = "那個，難道是因為我說錯話了嗎，那句「遠程指點」？",
  ui_story_6_1_173_dialog_content = "薇絲，別想了，她這個時候離開總比關鍵時刻退縮好。",
  ui_story_6_1_174_dialog_content = "卡蓮，我真羨慕妳能一如既往地冷靜……",
  ui_story_6_1_175_dialog_content = "無需緊張。無論前面有什麼，我都會讓牠明白自己來錯地方。",
  ui_story_6_2_X29_dialog_content = "啊……？欸……嗯……",
  ui_story_6_2_X30_dialog_content = "卡戎長官？你怎麼一直在這發出奇怪的聲音喵？",
  ui_story_6_2_X31_dialog_content = "菲莉詩小姐，妳的氣色看起來依舊那麼……",
  ui_story_6_2_X32_dialog_content = "缺乏睡眠呢。",
  ui_story_6_2_X33_dialog_content = "其實，在下正在等長官們的會議結束，有些關於28號地下城的報銷款項……",
  ui_story_6_2_X34_dialog_content = "長官們都離開了喵，下次吧。",
  ui_story_6_2_X35_dialog_content = "怎麼走得這麼快！還有好多補貼款項沒有發放呢！",
  ui_story_6_2_X36_dialog_content = "沒辦法喵，大家都接到緊急命令去周圍的區域布防了喵。",
  ui_story_6_2_X37_dialog_content = "唉，明明薇絲已經報告威脅在<color=#FFB400>低語迴廊</color>那邊……",
  ui_story_6_2_X38_dialog_content = "大元帥卻做出這樣的決策，菲莉詩也不明白為什麼喵……",
  ui_story_6_2_X39_dialog_content = "嗯？等等等等，一時資訊量太大了。",
  ui_story_6_2_X40_dialog_content = "你能仔細說說嗎？薇絲和PlayerName他們，是不是又遇到麻煩？",
  ui_story_6_2_X41_dialog_content = "麻煩？唉，怎麼說喵，也許是「<color=#FFB400>史上最大的劫難</color>」喵……",
  ui_story_6_2_X42_dialog_content = "劫難？！",
  ui_story_6_2_1_dialog_content = "……我們似乎已經走很久了。",
  ui_story_6_2_2_dialog_content = "就連我也能感受到濃烈的暗鬼氣息了。",
  ui_story_6_2_3_dialog_content = "涉女士……",
  ui_story_6_2_4_dialog_content = "嗯？我在哦。",
  ui_story_6_2_6_dialog_content = "親愛的～你們迷路了嗎？",
  ui_story_6_2_7_dialog_content = "倒不至於迷路。但這地方確實像迷宮一樣，而且很陰暗，讓人感覺很壓抑。",
  ui_story_6_2_9_dialog_content = "你們快看，這裡的痕跡很奇怪。除了暗鬼的腳印，還有……",
  ui_story_6_2_10_dialog_content = "這是「軍靴」的痕跡吧？",
  ui_story_6_2_11_dialog_content = "軍靴？這是……",
  ui_story_6_2_12_dialog_content = "我感知到了光靈的氣息。是援軍嗎？！",
  ui_story_6_2_13_dialog_content = "白夜城制式，不會有錯，而且是衛隊的。",
  ui_story_6_2_14_dialog_content = "鞋印清晰，沒有戰鬥痕跡，甚至……感覺不出任何恐慌。",
  ui_story_6_2_15_dialog_content = "單憑鞋印就可以解讀這麼多資訊嗎？",
  ui_story_6_2_16_dialog_content = "<color=#FFB400>格茲德</color>。",
  ui_story_6_2_X16_dialog_content = "格茲德？如果我沒記錯的話……",
  ui_story_6_2_17_option_content = "之前追擊嘶魘兒時聽過這個名字",
  ui_story_6_2_18_option_content = "是那時偷走「智庫組件」的傢伙？",
  ui_story_6_2_19_dialog_content = "沒錯。但格茲德不是失踪了嗎？",
  ui_story_6_2_20_dialog_content = "是叛逃。他投靠了日蝕，證據確鑿……",
  ui_story_6_2_21_dialog_content = "他和他的情人很久之前就在為暗鬼賣命了，簡直是白夜城的恥辱。",
  ui_story_6_2_22_dialog_content = "在這個時間、這個地點，會與暗鬼同行又穿著衛隊軍靴的……",
  ui_story_6_2_23_dialog_content = "只能是格茲德！",
  ui_story_6_2_24_dialog_content = "他到底為什麼要這麼做？",
  ui_story_6_2_25_dialog_content = "沒人知道。",
  ui_story_6_2_26_dialog_content = "據說格茲德工作認真，還是個戰爭英雄，所以從沒人懷疑過他。",
  ui_story_6_2_27_dialog_content = "難道說，格茲德因為嘶魘兒的事懷恨在心，來這裡就是為了……",
  ui_story_6_2_28_dialog_content = "一條跟著主子到處流浪的敗犬，來得正好。",
  ui_story_6_2_29_dialog_content = "如果遇到，我會將他和舒默一起埋葬在這兒！",
  ui_story_6_2_30_dialog_content = "嘖。煩死了，這路是腸子嗎也太迂迴曲折了！還有一種被人盯著的感覺……",
  ui_story_6_2_31_dialog_content = "煩死了！格茲德，給我唱首歌吧。",
  ui_story_6_2_32_dialog_content = "……",
  ui_story_6_2_33_dialog_content = "格茲德，你那是什麼眼神？",
  ui_story_6_2_34_dialog_content = "殺死嘶魘兒的人來了，難道不應該高興地唱首戰歌嗎？",
  ui_story_6_2_35_dialog_content = "他們追來了，正如妳說的那樣……",
  ui_story_6_2_36_dialog_content = "那些……殺害嘶魘兒的傢伙正在靠近，對吧？",
  ui_story_6_2_37_dialog_content = "對。我知道那些低等的雜魚沒辦法拖住他們……還真是頑強。",
  ui_story_6_2_39_dialog_content = "嘶魘兒，她……",
  ui_story_6_2_40_dialog_content = "很慘。格茲德，就連我都覺得她死得很慘。",
  ui_story_6_2_41_dialog_content = "為什麼！她們……",
  ui_story_6_2_42_dialog_content = "嘶魘兒告訴過我，這是一件光榮的任務！她為什麼不向你和那位大人求助呢？",
  ui_story_6_2_A1_dialog_content = "不，以她的性格，她一定會求助的……難道說……",
  ui_story_6_2_43_dialog_content = "你聲音那麼大幹什麼？",
  ui_story_6_2_44_dialog_content = "……抱歉。",
  ui_story_6_2_45_dialog_content = "聽說，是PlayerName逼死可憐的嘶魘兒。",
  ui_story_6_2_46_dialog_content = "你放走嘶魘兒後，下城區就一片混亂了，上城區的那些傢伙沒心思管她們。",
  ui_story_6_2_47_dialog_content = "但是PlayerName和那兩條「惡犬」還是追個不停喔。",
  ui_story_6_2_48_dialog_content = "……他們！欺人太甚！",
  ui_story_6_2_49_dialog_content = "對啊，沒偷到東西的小偷也要被打死，哪有這種規定？",
  ui_story_6_2_50_dialog_content = "後逼得嘶魘兒和她妹妹不得不……唉，變成醜惡的怪物",
  ui_story_6_2_51_dialog_content = "……嘶魘兒……嘶魘兒……",
  ui_story_6_2_52_dialog_content = "如果有什麼想做的，你現在就可以去哦。",
  ui_story_6_2_53_dialog_content = "我要找的「火控模組」就在前面了，你打算怎麼辦？",
  ui_story_6_2_54_dialog_content = "PlayerName——！！！",
  ui_story_6_2_55_dialog_content = "喔？看來你已經準備好復仇了呢。",
  ui_story_6_2_56_dialog_content = "——哈啾！",
  ui_story_6_2_57_dialog_content = "怎麼了，PlayerName？是不是這裡太冷了？",
  ui_story_6_2_58_dialog_content = "不……只是莫名其妙地起了一身雞皮疙瘩。",
  ui_story_6_2_59_dialog_content = "PlayerName，你畢竟是空裔，也許這裡的暗能對你來說太濃厚了。",
  ui_story_6_2_60_dialog_content = "但請堅持住，我們還有很多敵人要解決。",
  ui_story_6_2_61_dialog_content = "瞭解……那就繼續趕路吧……",
  ui_story_6_6_1_dialog_content = "我們似乎來到了奇怪的地方。涉女士！",
  ui_story_6_6_2_dialog_content = "吧嘰吧嘰……嗯？",
  ui_story_6_6_3_dialog_content = "涉女士……妳是在吃東西嗎？",
  ui_story_6_6_4_dialog_content = "唔……嗯，喝了點茶順便吃了個甜點……怎麼啦？",
  ui_story_6_6_5_dialog_content = "我們想知道，這條路是通往「<color=#FFB400>火控模組</color>」的方向沒錯吧？",
  ui_story_6_6_6_dialog_content = "嗯啊——當然！我可是好不容易才想起來那個「火控模組」可能在哪裡的。",
  ui_story_6_6_7_dialog_content = "要相信別人的話啊，親愛的。喔，對了，你們要小心前面的陷阱喔～",
  ui_story_6_6_8_dialog_content = "等等。我感應到……",
  ui_story_6_6_9_dialog_content = "是暗鬼嗎？",
  ui_story_6_6_10_dialog_content = "不，好像是……光靈。",
  ui_story_6_6_11_dialog_content = "光靈！涉閣下，沒人進來吧？",
  ui_story_6_6_12_dialog_content = "連一隻蒼蠅都沒飛進來。",
  ui_story_6_6_13_dialog_content = "那就是格茲德……前面恐怕會有埋伏。",
  ui_story_6_6_14_dialog_content = "埋伏？",
  ui_story_6_6_15_dialog_content = "前面是個十字路口，而且還有陷阱。",
  ui_story_6_6_16_dialog_content = "再加上年久失修，可能會有屋頂坍塌或者地面下陷的情況，是個天然的伏擊場！",
  ui_story_6_6_17_dialog_content = "他雖然曾是名騎士，但現在投靠了日蝕，天知道他會做出什麼事。",
  ui_story_6_6_18_dialog_content = "讓我走在最前面。格茲德……我會給他公正的結局。",
  ui_story_6_7_1_dialog_content = "呼……好險，幸虧卡蓮提醒，要不然我們剛才就掉到陷阱坑洞了。",
  ui_story_6_7_2_dialog_content = "我也提醒了你們好多次，對吧。",
  ui_story_6_7_3_dialog_content = "例如剛才那個火油陷阱，差點砸死可愛的PlayerName呢。",
  ui_story_6_7_4_dialog_content = "我快嚇死了……",
  ui_story_6_7_5_dialog_content = "這是格茲德的策略。他已經變得和暗鬼一樣，無恥、卑劣……",
  ui_story_6_7_6_dialog_content = "才說著，就出現了呢。",
  ui_story_6_7_7_dialog_content = "……你們殺死了嘶魘兒。",
  ui_story_6_7_8_dialog_content = "你們，殺死了……嘶魘兒……！",
  ui_story_6_7_9_dialog_content = "果然……你是來復仇的。",
  ui_story_6_7_10_dialog_content = "復仇？是的。很可惜剛才的陷阱沒有困住你們，因為……",
  ui_story_6_7_11_dialog_content = "光是殺死你們已經無法消除我的仇恨了。",
  ui_story_6_7_F1_dialog_content = "你還想殺死我們？！",
  ui_story_6_7_12_dialog_content = "格茲德！你作為白夜城的騎士卻拋棄榮譽投靠暗鬼……我絕不會饒恕你！",
  ui_story_6_7_13_dialog_content = "饒恕我？我需要妳的饒恕嗎？我以前是白夜城的騎士，現在是暗鬼的菁英……",
  ui_story_6_7_14_dialog_content = "但這一切都是為了她！可她卻、可她卻被你們……",
  ui_story_6_7_15_dialog_content = "你們比暗鬼還殘忍……是你們折磨死嘶魘兒的！",
  ui_story_6_7_16_dialog_content = "格茲德！嘶魘兒她們是自己選擇死亡的！",
  ui_story_6_7_17_dialog_content = "格茲德，是她們自己尋求死亡，想要解脫的……",
  ui_story_6_7_18_dialog_content = "不可能！",
  ui_story_6_7_19_dialog_content = "嘶魘兒她……那麼嚮往自由，若不是被你們逼到絕路，怎麼會自己尋死？",
  ui_story_6_7_20_dialog_content = "是不是舒默要你來阻擋我們的？",
  ui_story_6_7_21_dialog_content = "不，我是來復仇的，向你們、向白夜城復仇！",
  ui_story_6_7_22_dialog_content = "至於舒默……她要什麼，與我無關。",
  ui_story_6_7_23_dialog_content = "一個叛徒為一個內奸復仇？",
  ui_story_6_7_27_dialog_content = "……",
  ui_story_6_7_28_dialog_content = "卡蓮，他身上的恨意好像越來越濃了，小心一些……",
  ui_story_6_7_29_dialog_content = "恨意？那是叛徒天生就有的東西！",
  ui_story_6_7_30_dialog_content = "因為他們走投無路，因此才有滿腔的恨意……",
  ui_story_6_7_31_dialog_content = "他們恨那些審判者、恨自己難以回首的過去，也恨自己不會有的未來。",
  ui_story_6_7_32_dialog_content = "和這種傢伙沒有什麼好談的。",
  ui_story_6_7_33_dialog_content = "妳一個白夜城衛隊長、城主的女兒，妳怎麼可能會懂？",
  ui_story_6_7_34_dialog_content = "即使我不是叛徒，妳也不會知道我在恨什麼！",
  ui_story_6_7_35_dialog_content = "我只恨你們逼死嘶魘兒！",
  ui_story_6_7_36_dialog_content = "對，她變成了暗鬼，而你們是光靈，作為敵人，死在戰場上是嘶魘兒的命運。",
  ui_story_6_7_37_dialog_content = "但你們將嘶魘兒逼成那個樣子！那！個！樣！子！",
  ui_story_6_7_38_dialog_content = "他！他的模樣！",
  ui_story_6_7_39_dialog_content = "復仇……我的復仇……就像你一樣，PlayerName。",
  ui_story_6_7_40_dialog_content = "我們，一模一樣，都走在復仇的路上無法回頭……",
  ui_story_6_7_41_dialog_content = "和我一樣？你什麼意思……",
  ui_story_6_7_42_dialog_content = "你居然能變得像暗鬼一樣……你向你的主人，索取力量？！",
  ui_story_6_7_43_dialog_content = "……復仇！讓我們死在彼此的劍下，PlayerName！！",
  ui_story_6_7_44_dialog_content = "讓我們一起去死後的世界，向嘶魘兒尋求原諒吧！！！",
  ui_story_6_7_45_dialog_content = "後退，PlayerName！支援我們戰鬥！",
  ui_story_6_7_X45_dialog_content = "嘶魘兒……我輸了……",
  ui_story_6_7_48_dialog_content = "準備好接受審判了嗎，叛徒？",
  ui_story_6_7_49_dialog_content = "……",
  ui_story_6_7_50_dialog_content = "為何不說話？死到臨頭，終於後悔了嗎？",
  ui_story_6_7_51_dialog_content = "不。我不後悔，我知道自己的結局。",
  ui_story_6_7_52_dialog_content = "我現在只想知道，嘶魘兒最後的時刻。",
  ui_story_6_7_53_dialog_content = "你沒有必要知道！",
  ui_story_6_7_F2_dialog_content = "等一下！我們可以解釋這件事……",
  ui_story_6_7_54_dialog_content = "我們的確追上嘶魘兒她們，但我們當時更想問出她們的目的。",
  ui_story_6_7_55_dialog_content = "是的，我們根本沒有想要殺掉她們。",
  ui_story_6_7_56_dialog_content = "但她們為了逃走開始向一個暗鬼首領求助。",
  ui_story_6_7_57_dialog_content = "……舒默？",
  ui_story_6_7_58_dialog_content = "不……那股氣息不是舒默，是另一個傢伙，比舒默更強大。",
  ui_story_6_7_59_dialog_content = "隨後，她們的身軀就發生可怕的變異，她們好像蠟燭一樣……融合了。",
  ui_story_6_7_60_dialog_content = "而且那不像是她們主動選擇融合，更像是……",
  ui_story_6_7_61_dialog_content = "更像是被某種無法抵抗的力量給硬生生地……",
  ui_story_6_7_62_dialog_content = "那後來……！",
  ui_story_6_7_63_dialog_content = "我們不得不殺了嘶魘兒。",
  ui_story_6_7_64_dialog_content = "……她走得痛苦嗎。",
  ui_story_6_7_65_dialog_content = "這……",
  ui_story_6_7_66_option_content = "她走得十分痛苦",
  ui_story_6_7_67_dialog_content = "<anim type=Shake><size=45>痛……好痛苦……</size></anim>",
  ui_story_6_7_69_dialog_content = "在我們決定與她戰鬥之前，某個人已強行將力量施加在她們身上……",
  ui_story_6_7_70_dialog_content = "強行讓她們融合，把她們兩人變成一隻暗鬼，這才是她們痛苦的原因。",
  ui_story_6_7_71_option_content = "我們動作很俐落",
  ui_story_6_7_72_dialog_content = "是你們……讓她解脫嗎？",
  ui_story_6_7_73_dialog_content = "是的，因為我們也不忍看她承受那樣的痛苦。",
  ui_story_6_7_74_dialog_content = "在我們決定與她戰鬥之前，某個人已強行將力量施加在她們身上……",
  ui_story_6_7_75_dialog_content = "強行讓她們融合，把她們兩人變成一隻暗鬼，這才是她們痛苦的原因。",
  ui_story_6_7_76_dialog_content = "或許她們的痛苦也源於自身的悔恨。",
  ui_story_6_7_78_dialog_content = "尤其是嘶魘兒，我能感受到她當時……並不想與我們戰鬥。",
  ui_story_6_7_79_dialog_content = "她只是想直接逃走，只是想逃離白夜城，逃到很遠的地方去……",
  ui_story_6_7_80_dialog_content = "她……在最後好像提到了一種花。",
  ui_story_6_7_81_dialog_content = "花……？",
  ui_story_6_7_82_option_content = "「蒲公英」",
  ui_story_6_7_83_dialog_content = "<size=45>……！！</size>",
  ui_story_6_7_84_dialog_content = "我們不懂其中的含義，但你……應該瞭解吧。",
  ui_story_6_7_85_dialog_content = "對不起……對不起，嘶魘兒……",
  ui_story_6_7_86_dialog_content = "妳明明已經跟我說過，我明明應該發現，那個時候我們都還有機會……",
  ui_story_6_7_87_dialog_content = "格茲德、格茲德，附近有沒有什麼好玩的地方？",
  ui_story_6_7_88_dialog_content = "你要出去玩嗎？",
  ui_story_6_7_89_dialog_content = "不是出去玩。你知道低語迴廊嗎？",
  ui_story_6_7_90_dialog_content = "那裡似乎是個很隱蔽的地方，誰也找不到我們！可以住一輩子！",
  ui_story_6_7_91_dialog_content = "或者，紅油沙漠也不錯，就是熱了些。",
  ui_story_6_7_92_dialog_content = "妳打算離開白夜城？是因為惹到什麼貴族了嗎？",
  ui_story_6_7_93_dialog_content = "不，是……日蝕。",
  ui_story_6_7_94_dialog_content = "想變成蒲公英。",
  ui_story_6_7_95_dialog_content = "嗯？為什麼突然這麼說？",
  ui_story_6_7_96_dialog_content = "因為你永遠抓不住一朵蒲公英，它會化為千千萬萬個小小的蒲公英，然後乘著風離開。",
  ui_story_6_7_97_dialog_content = "它們會飛啊……飛啊……去到世界上任何地方。",
  ui_story_6_7_98_dialog_content = "其實那個「小小的它們」是蒲公英的種子……而且掉進水裡怎麼辦？",
  ui_story_6_7_99_dialog_content = "嘖，你——哎！算了！不講了！",
  ui_story_6_7_100_dialog_content = "自由……是的，嘶魘兒經常說因為日蝕而想離開白夜城。",
  ui_story_6_7_101_dialog_content = "她說要和我……像蒲公英一樣……遠走高飛。",
  ui_story_6_7_102_dialog_content = "你真無知，格茲德。日蝕才是萬事萬物的終點，不，那是真理……",
  ui_story_6_7_103_dialog_content = "……真的是PlayerName殺死了嘶魘兒嗎？",
  ui_story_6_7_104_dialog_content = "我已經告訴過你發生了什麼事，竟然還有這麼多疑問……是我對你的期待太高了嗎？",
  ui_story_6_7_105_dialog_content = "收起你的軟弱，放下對我們的猜忌，格茲德。",
  ui_story_6_7_106_dialog_content = "你要記住：她們本可以活下去，但PlayerName改寫了她們的命運。",
  ui_story_6_7_107_dialog_content = "也改寫了，你的命運……",
  ui_story_6_7_108_dialog_content = "不！不！假的！假的！",
  ui_story_6_7_109_dialog_content = "格茲德！",
  ui_story_6_7_110_dialog_content = "我、我、嘶魘兒……嘶魘兒、嘶魘兒要離開，怎麼會融合，怎麼會？！",
  ui_story_6_7_111_dialog_content = "我們不會使用暗能，只有暗能才有可能讓嘶魘兒姐妹變成融合的暗鬼。",
  ui_story_6_7_112_dialog_content = "為她們注入暗能的即便不是舒默，也是跟舒默有關的暗鬼。",
  ui_story_6_7_113_dialog_content = "那傢伙，是那傢伙，是那傢伙，是那傢伙……！！",
  ui_story_6_7_114_dialog_content = "格茲德……你知道什麼嗎？",
  ui_story_6_7_116_dialog_content = "……",
  ui_story_6_7_119_dialog_content = "<color=#FFB400>舒默</color>……我知道她在哪兒。",
  ui_story_6_8_1_dialog_content = "卡蓮……他真的會帶我們去見舒默嗎？",
  ui_story_6_8_2_dialog_content = "這一路上都沒什麼暗鬼，有點奇怪。會不會是另一個陷阱？",
  ui_story_6_8_F1_dialog_content = "就算是陷阱又如何？",
  ui_story_6_8_3_dialog_content = "如果他再次背叛，那我會再打敗他一次，但這次……我絕不會手下留情。",
  ui_story_6_8_F2_dialog_content = "……",
  ui_story_6_8_4_dialog_content = "抱歉，格茲德……我們依舊會懷疑你，但如果你想反駁，可以直接說。",
  ui_story_6_8_5_dialog_content = "一個叛徒能反駁什麼？",
  ui_story_6_8_6_dialog_content = "啊……叛徒。我之前也是白夜城的英雄呢。",
  ui_story_6_8_7_dialog_content = "我十八歲就成為正式騎士，而且是城主親手冊封的。",
  ui_story_6_8_8_dialog_content = "<color=#FFB400>「暗潮危機」</color>知道吧。",
  ui_story_6_8_9_dialog_content = "是從十七年前開始，持續很久的那場戰爭……",
  ui_story_6_8_10_dialog_content = "在十七年前……暗鬼突襲空裔的山谷。這場襲擊毫無徵兆，連白夜城都為之震驚。",
  ui_story_6_8_11_dialog_content = "很快地，我們就接到密集訓練的命令……這是為了應對可能到來的大規模暗鬼襲擊。",
  ui_story_6_8_12_dialog_content = "我接到命令時，年紀比現在的你們還小，我那時剛成為騎士侍從。",
  ui_story_6_8_13_dialog_content = "我刻苦訓練，並在白夜城守衛隊中當了四年的後備軍。",
  ui_story_6_8_14_dialog_content = "隨後，你的機會就來了。",
  ui_story_6_8_15_dialog_content = "對，那是個晴朗的上午，白夜城出兵對抗襲擊影鎮的暗鬼，因此城內守備不足。",
  ui_story_6_8_16_dialog_content = "當時有暗鬼跑進白夜城的下城區……我挺身而出，救了一名落難的貴族女孩。",
  ui_story_6_8_19_dialog_content = "後來我跟隨衛隊出戰，因為我的英勇表現……",
  ui_story_6_8_20_dialog_content = "回來後不久就被城主親手封為騎士。",
  ui_story_6_8_22_dialog_content = "聽起來是個很好的開始。",
  ui_story_6_8_23_dialog_content = "是啊，就像童話一般，我得到「騎士迎娶公主」的結局。",
  ui_story_6_8_27_dialog_content = "一個月後，我和那位貴族女孩……舉行了婚禮。",
  ui_story_6_8_28_dialog_content = "她就是嘶魘兒吧。",
  ui_story_6_8_29_dialog_content = "不是。",
  ui_story_6_8_30_dialog_content = "你……？！",
  ui_story_6_8_31_dialog_content = "她是大貴族家的小姐，雖然是二女兒。",
  ui_story_6_8_32_dialog_content = "但我們的地位差距依舊是無法靠個人努力彌補的……",
  ui_story_6_8_33_dialog_content = "妻子的家族造成她的強勢，也造成她的失落……",
  ui_story_6_8_34_dialog_content = "甜蜜、平淡、比較、不滿、抱怨、爭吵、麻木。",
  ui_story_6_8_35_dialog_content = "幾年後，我在她眼中，就和路邊的石頭一樣，根本不存在。",
  ui_story_6_8_36_dialog_content = "是她想讓我消失的……然後我遇到了嘶魘兒。",
  ui_story_6_8_45_dialog_content = "她讓我如死水的生活泛起少年時代才有過的漣漪。",
  ui_story_6_8_46_dialog_content = "看到她，我似乎又回到了年輕的時候。",
  ui_story_6_8_47_dialog_content = "什麼家族、什麼地位，我只需要在戰場上立下功勳，贏得美人芳心……",
  ui_story_6_8_49_dialog_content = "夠了！格茲德，沒有人會同情你。",
  ui_story_6_8_50_dialog_content = "看看你實際上做了什麼？",
  ui_story_6_8_51_dialog_content = "背叛妻子、勾結暗鬼、襲擊衛兵、搶奪「智庫組件」！",
  ui_story_6_8_53_dialog_content = "你或許曾經是白夜城的英雄，但你現在就是一個背信棄義的罪人！",
  ui_story_6_8_54_dialog_content = "呵呵……哈哈哈哈！我確實背叛了白夜城，我罪無可赦。",
  ui_story_6_8_F3_dialog_content = "但我並不認為我做錯什麼，我只是在追求自己的真愛……",
  ui_story_6_8_55_dialog_content = "我不能理解，這簡直……太荒謬了。",
  ui_story_6_8_63_dialog_content = "所以故事結束了嗎？",
  ui_story_6_8_64_dialog_content = "抱歉涉女士……我剛才完全忘記妳的存在！",
  ui_story_6_8_65_dialog_content = "我只是來提醒你們，格茲德沒有帶錯路……",
  ui_story_6_8_66_dialog_content = "他指出的方向和我記得的線路是一致的，而且特意繞過了疑似陷阱的地方哦。",
  ui_story_6_8_67_dialog_content = "……",
  ui_story_6_8_68_dialog_content = "我不需要你們理解我，我說過。我會帶你們去見舒默，然後……我有我要做的事情。",
  ui_story_6_9_1_dialog_content = "果然，牆頭草就是牆頭草。",
  ui_story_6_9_2_dialog_content = "格茲德嗎？",
  ui_story_6_9_3_dialog_content = "看來你的說服力不如PlayerName。",
  ui_story_6_9_4_dialog_content = "那又如何？我知道格茲德會背叛我們，只不過跟我預期的有點不一樣……",
  ui_story_6_9_5_dialog_content = "因為PlayerName嗎？",
  ui_story_6_9_6_dialog_content = "對，我沒想到他們會放過格茲德。哼，肯定是那個PlayerName搞的鬼，虛偽。",
  ui_story_6_9_7_dialog_content = "是聰明。你還是別做任何「預期」了，舒默，你不適合動腦。",
  ui_story_6_9_8_dialog_content = "我總有一天會扯斷你的脖子……",
  ui_story_6_9_9_dialog_content = "哼，反正我比他們快。我都能聞到「<color=#FFB400>火控模組</color>」的香味了。",
  ui_story_6_9_10_dialog_content = "等我拿到它，就在那邊特別等PlayerName來，到時候……",
  ui_story_6_9_11_dialog_content = "一網打盡。",
  ui_story_6_9_12_dialog_content = "哈，對，一網打盡，我喜歡這個詞。",
  ui_story_6_9_13_dialog_content = "你應該多學一點詞彙。還是小心為妙，那群人背後有白夜城和啟光的支持。",
  ui_story_6_9_14_dialog_content = "他們的軍隊不會來，這些光靈之間充滿可笑的猜忌與隔閡。",
  ui_story_6_9_15_dialog_content = "要不要過來觀賞看看，他們的表情，會很有意思哦。",
  ui_story_6_9_16_dialog_content = "免了，你知道的，我不喜歡爭鬥。",
  ui_story_6_9_17_dialog_content = "不過我倒是為你準備了幫手，啊不，是一個<color=#FFB400>禮物</color>，給他們的禮物。",
  ui_story_6_9_18_dialog_content = "禮物？幫手？哦！是不是那個傢伙？",
  ui_story_6_9_19_dialog_content = "是它，是他們的<color=#FFB400>老朋友</color>。我把它「變強」了。",
  ui_story_6_9_20_dialog_content = "我看你也挺愛玩的，天天搞這些「創作」。",
  ui_story_6_9_21_dialog_content = "這是在我計劃內的適度發揮，但你的那些行為叫「添麻煩」。",
  ui_story_6_9_22_dialog_content = "彼此彼此。",
  ui_story_6_9_23_dialog_content = "閒話到此為止，來看看這禮物吧……",
  ui_story_6_9_24_dialog_content = "哎呀呀，它可真漂亮。PlayerName見到這位老朋友會是什麼表情呢？",
  ui_story_6_9_25_dialog_content = "迫不及待、迫不及待地想看到呢……",
  ui_story_6_9_A1_dialog_content = "格茲德，還有多遠？",
  ui_story_6_9_A2_dialog_content = "不遠了。相信我，我比你們更想見到那張虛偽的臉……",
  ui_story_6_9_A3_dialog_content = "……",
  ui_story_6_9_A4_dialog_content = "前面有伏擊，是舒默留下的暗鬼們。你們不是擅長戰鬥嗎？快上吧。",
  ui_story_6_13_1_dialog_content = "這前面是不是低語迴廊的盡頭？",
  ui_story_6_13_2_dialog_content = "對。舒默一定就在附近……",
  ui_story_6_13_3_dialog_content = "我能感受到她的氣息就在前方。",
  ui_story_6_13_5_dialog_content = "你們在附近找找，在一個巨大的玻璃瓶下寫著一串編號。",
  ui_story_6_13_6_dialog_content = "唔，具體是什麼我有點忘記了，好像是……",
  ui_story_6_13_7_dialog_content = "<color=#FFB400>「RX6007」</color>。",
  ui_story_6_13_8_dialog_content = "啊對！就是那個！那是物品存放進來的編號！為什麼你會知道？",
  ui_story_6_13_10_dialog_content = "舒默無意間提到過。我不會忘記聽到的任何東西。",
  ui_story_6_13_11_dialog_content = "無論是情報，還是往事……呵，這樣的記憶力簡直像詛咒一樣。",
  ui_story_6_13_12_dialog_content = "抵達這個編號物品的位置，那麼你們要找的東西就在前方不遠處了。",
  ui_story_6_13_14_dialog_content = "小心。如果舒默已經知道這串數字了，那證明……",
  ui_story_6_13_16_dialog_content = "她早就知道那個東西放在哪，而且很可能正等著我們上鉤。",
  ui_story_6_14_1_dialog_content = "啊，我們又見面啦。",
  ui_story_6_14_2_dialog_content = "舒……",
  ui_story_6_14_3_dialog_content = "舒默！",
  ui_story_6_14_4_dialog_content = "啊，你很生氣嗎？是因為輸給PlayerName？",
  ui_story_6_14_5_dialog_content = "看樣子你被俘虜啦？要不要我救你出來，你們再打一次呀。",
  ui_story_6_14_6_dialog_content = "你，還有她，都騙了我……嘶魘兒的死，妳根本沒告訴我真相！",
  ui_story_6_14_7_dialog_content = "我們欺騙你？不，格茲德，是你更願意相信「嘶魘兒被白夜城殺害」。",
  ui_story_6_14_8_dialog_content = "所以你要向白夜城復仇，不是嗎？",
  ui_story_6_14_9_dialog_content = "我們都被你們騙了……是你們欺騙嘶魘兒，利用她，然後丟棄她！",
  ui_story_6_14_10_dialog_content = "你擦完手，不會將紙巾丟掉嗎？",
  ui_story_6_14_11_dialog_content = "紙巾……嘶魘兒……",
  ui_story_6_14_12_dialog_content = "你似乎流了很多汗，巡邏很辛苦吧，這張紙巾給你。",
  ui_story_6_14_13_dialog_content = "謝……謝。",
  ui_story_6_14_14_dialog_content = "你怎麼開始發呆了？啊，你臉上的不是汗水而是淚水喔？",
  ui_story_6_14_15_dialog_content = "我的格茲德，你為何哭泣？你不是個叛徒嗎？叛徒有什麼可哭的？",
  ui_story_6_14_16_dialog_content = "舒默……妳……嘶魘兒是不是被……",
  ui_story_6_14_17_dialog_content = "被什麼？格茲德，你失去我們給你的力量，你還能做什麼？",
  ui_story_6_14_20_dialog_content = "舒默，是你將嘶魘兒她們融合到一起的嗎？！",
  ui_story_6_14_22_dialog_content = "不是。啊——應該也可以說，是的。",
  ui_story_6_14_23_dialog_content = "你……！",
  ui_story_6_14_24_dialog_content = "我知道你想說什麼，「為什麼這麼做」什麼的。",
  ui_story_6_14_25_dialog_content = "我告訴你，只是因為我們可以這樣做。",
  ui_story_6_14_26_dialog_content = "用過的東西該整理就整理，該丟就丟，這有什麼奇怪的？你在生氣什麼？",
  ui_story_6_14_27_dialog_content = "問來問去，煩死了。",
  ui_story_6_14_28_dialog_content = "PlayerName，還有這兩個女人……都是他們這群垃圾害你這麼痛苦。",
  ui_story_6_14_29_dialog_content = "舒默，妳……",
  ui_story_6_14_30_dialog_content = "我可以幫你除掉她們……",
  ui_story_6_14_31_dialog_content = "小心——！！",
  ui_story_6_14_32_dialog_content = "卡蓮？！",
  ui_story_6_14_33_dialog_content = "……！",
  ui_story_6_14_34_dialog_content = "啊！格……茲德？！",
  ui_story_6_14_35_dialog_content = "妳！",
  ui_story_6_14_36_dialog_content = "我……我……",
  ui_story_6_14_37_dialog_content = "嘖！你瘋了嗎，格茲德！！狗奴才，誰都做你的主子嗎？！",
  ui_story_6_14_38_dialog_content = "為什麼……",
  ui_story_6_14_39_dialog_content = "不是……為了你們，是為了……嘶魘兒……",
  ui_story_6_14_40_dialog_content = "……",
  ui_story_6_14_A1_dialog_content = "殺了……舒默……",
  ui_story_6_14_A2_dialog_content = "我做不到，但你們……你們，可以……",
  ui_story_6_14_A3_dialog_content = "讓她……死在你們的劍下……！",
  ui_story_6_14_A5_dialog_content = "舒默……",
  ui_story_6_14_A7_dialog_content = "……我和嘶魘兒……<anim type=Shake><size=50>在地獄等你！</size></anim>",
  ui_story_6_14_44_dialog_content = "格茲德……你……",
  ui_story_6_14_45_dialog_content = "卡蓮，他已經……那是他最後的遺願。",
  ui_story_6_14_46_dialog_content = "……無聊。無聊、無聊、無聊死了！格茲德也好，你們也好！你們……",
  ui_story_6_14_47_dialog_content = "舒默！<color=#FFB400>他們來了</color>。撤。",
  ui_story_6_14_48_dialog_content = "吵死了！你要幹什麼？別妨礙我！！",
  ui_story_6_14_49_dialog_content = "讓你現在離開那兒，立刻",
  ui_story_6_14_50_dialog_content = "為什麼？！",
  ui_story_6_14_51_dialog_content = "……發生什麼事了？",
  ui_story_6_14_52_dialog_content = "PlayerName！好像有打著啟光名號的「<color=#FFB400>軍隊</color>」過來了哦！聲勢非常浩大呢！",
  ui_story_6_14_53_dialog_content = "你們堅持住，等軍團大部隊抵達，就將這裡圍的滴水不漏！",
  ui_story_6_14_54_dialog_content = "有大量敵人來了，拿著組件立馬出來。",
  ui_story_6_14_56_dialog_content = "我能馬上殺掉這些傢伙！然後把那個PlayerName抓過來，慢慢地……",
  ui_story_6_14_57_dialog_content = "你做不到。",
  ui_story_6_14_58_dialog_content = "我可以！三分鐘，不，一……",
  ui_story_6_14_59_dialog_content = "我說妳做不到！啟光的軍隊來了……我不想冒這個險。",
  ui_story_6_14_60_dialog_content = "哦哦哦哦！！再多弄點煙塵出來！",
  ui_story_6_14_61_dialog_content = "作為啟光三大集團聯軍的先鋒隊，我……",
  ui_story_6_14_62_dialog_content = "暗鬼獵手、長夜終結者、地下城爆破家、冥河列車·卡戎！",
  ui_story_6_14_63_dialog_content = "正帶領著數以萬計的士兵包圍低語迴廊呢！！前面的暗鬼們，可都別跑啊！！",
  ui_story_6_14_X64_dialog_content = "別讓我使出強制手段，舒默。",
  ui_story_6_14_65_dialog_content = "知道了知道了！哼，反正組件已經到手……",
  ui_story_6_14_66_dialog_content = "站住！舒默！",
  ui_story_6_14_67_dialog_content = "「<color=#FFB400>火控模組</color>」！它現在在哪裡？",
  ui_story_6_14_68_dialog_content = "<color=#FFB400>在這裡呢</color>。",
  ui_story_6_14_69_dialog_content = "你逃不了的，如果大部隊已經到達，我們不會放過你的！",
  ui_story_6_14_70_dialog_content = "有這個功夫，還是先擔心一下白夜城吧。",
  ui_story_6_14_71_dialog_content = "白夜城？",
  ui_story_6_14_72_dialog_content = "永不淪陷之都，可笑而荒謬的稱號……",
  ui_story_6_14_A8_dialog_content = "補完黑色巨像之後，我會證明什麼才是至高無上的力量！！",
  ui_story_6_14_73_dialog_content = "地面！大家小心！",
  ui_story_6_14_74_dialog_content = "哈哈，驚喜吧！！",
  ui_story_6_14_75_dialog_content = "這是！麥格芬！它不是死了嗎？",
  ui_story_6_14_76_dialog_content = "<anim type=Shake><size=45>嗚啊啊啊……啊啊啊啊！！</size></anim>",
  ui_story_6_14_77_dialog_content = "節儉是美德，物要盡其用嘛。",
  ui_story_6_14_78_dialog_content = "不要耽誤時間了。黑色巨像正在降落……",
  ui_story_6_14_79_dialog_content = "唉，真可惜沒辦法看完這場好戲了。",
  ui_story_6_14_80_dialog_content = "……算了，接下來會更好玩。那就，拜拜啦～",
  ui_story_6_14_81_dialog_content = "這隻暗鬼是……麥格芬？我感覺的到牠擁有強烈的恨意！",
  ui_story_6_14_83_dialog_content = "牠跟上次遇到的麥格芬不一樣！大家一定要小心！",
  ui_story_6_14_84_dialog_content = "麥格芬上次應該已經死了，但這次比之前的更加難纏……",
  ui_story_6_14_85_dialog_content = "你們在前往白夜城之前，有遇到過這種暗鬼嗎？",
  ui_story_6_14_86_dialog_content = "遇過，但是……牠確實已經死了。",
  ui_story_6_14_87_dialog_content = "也就是說，日蝕將牠的屍體復活，變成新的作戰工具。真變態……",
  ui_story_6_14_90_dialog_content = "其它暗鬼對她們而言根本不是同伴。就像之前的嘶魘兒和夏爾，她們只是工具。",
  ui_story_6_14_92_dialog_content = "「<color=#FFB400>火控模組</color>」已經被拿走了，我們接下來該怎麼辦。",
  ui_story_6_14_93_dialog_content = "還有格茲德的事要處理……",
  ui_story_6_14_94_dialog_content = "卡蓮？",
  ui_story_6_14_97_dialog_content = "我要燒了格茲德。",
  ui_story_6_14_98_dialog_content = "不將他安葬嗎？火葬並不是白夜城的習俗……",
  ui_story_6_14_99_dialog_content = "首先，他是叛徒，原本該受拋屍之刑。其次，日蝕可能會復活他的屍體。",
  ui_story_6_14_100_dialog_content = "確實，就連屍體都要變成作戰工具，這太過分了……",
  ui_story_6_14_102_dialog_content = "薇絲，PlayerName，找一些易燃物來吧。",
  ui_story_6_14_103_dialog_content = "卡蓮·德·舒瓦茲，白夜城衛隊長，在此代表白夜城給予格茲德最後判決：",
  ui_story_6_14_104_dialog_content = "他本為白夜城的騎士，在戰亂中立下戰功；",
  ui_story_6_14_105_dialog_content = "但他苦於平凡、困於心魔、遭暗鬼籠絡，還做出背叛白夜城的逆舉。",
  ui_story_6_14_106_dialog_content = "後又被惡徒煽動、縱鬼作亂且危及白夜城的城民，罪無可赦。",
  ui_story_6_14_107_dialog_content = "但最終迷途知返，用其性命償還。他所犯下的罪行無法被抵消，但可免去拋屍之刑。",
  ui_story_6_14_108_dialog_content = "我們將焚燒他的軀體，保障他的名節……白夜至上。",
  ui_story_6_14_109_dialog_content = "格茲德，白夜城的英雄、背叛的騎士、日蝕的走狗，請在此安息。",
  ui_story_6_14_111_dialog_content = "這樣他應該就能安息了吧……PlayerName，你能感應到舒默去哪了嗎？",
  ui_story_6_14_112_dialog_content = "她已經離開低語迴廊了。",
  ui_story_6_14_114_dialog_content = "至於方向，我有點不確定，非說不可的話，好像升高了……",
  ui_story_6_14_115_dialog_content = "升高……難道說，她之前提到白夜城是指……",
  ui_story_6_14_116_dialog_content = "抱歉打擾！還活著嗎？！",
  ui_story_6_14_117_dialog_content = "當然！！",
  ui_story_6_14_118_dialog_content = "剛看到不得了的傢伙突然出現，還以為……",
  ui_story_6_14_119_dialog_content = "除了沒能奪得「火控模組」，我們都沒事！",
  ui_story_6_14_120_dialog_content = "那就好~",
  ui_story_6_14_121_dialog_content = "啟光的軍隊呢？剛才不是說援軍到了？",
  ui_story_6_14_122_dialog_content = "唔，等會你們自己看吧……",
  ui_story_6_14_123_dialog_content = "……唷，薇絲，PlayerName。",
  ui_story_6_14_124_dialog_content = "卡戎長官……？",
  ui_story_6_14_125_dialog_content = "可以讓在下先喝口水嗎？一路狂奔……真的很累……",
  ui_story_6_14_126_dialog_content = "這到底是什麼情況？聯軍呢？",
  ui_story_6_14_127_dialog_content = "幾個小時前，菲莉詩那傢伙告訴在下，你們好像有麻煩……",
  ui_story_6_14_128_dialog_content = "但是迦南那邊又不放兵，所以在下就自作主張地過來了……",
  ui_story_6_14_129_dialog_content = "難道剛才涉女士說的「軍隊」，其實是你……",
  ui_story_6_14_130_dialog_content = "正如你猜測的那樣，薇絲。",
  ui_story_6_14_131_dialog_content = "在下到這附近後發現古怪的黑色巨像，然後又遇到涉女士。",
  ui_story_6_14_132_dialog_content = "涉女士擔心你們打不過舒默，於是在下便心生一計。",
  ui_story_6_14_133_dialog_content = "於是……咳咳，靠一輛火車弄出幾千人的陣仗實在不容易啊……",
  ui_story_6_14_134_dialog_content = "原來是虛張聲勢……萬一舒默沒被騙怎麼辦？",
  ui_story_6_14_135_dialog_content = "那也值得一試……而且，有誰又知道啟光的列車會裝多少士兵呢？",
  ui_story_6_14_136_dialog_content = "話說，舒默那傢伙逃到哪裡去了？",
  ui_story_6_14_137_dialog_content = "剛才我整個人都被捲進自己弄出來的沙塵完全沒看到……",
  ui_story_6_14_138_dialog_content = "現在我基本上可以確定氣息的走向了。上空……往白夜城的方向。",
  ui_story_6_14_139_dialog_content = "白夜城！",
  ui_story_6_14_140_dialog_content = "？！白夜城？",
  ui_story_6_14_141_dialog_content = "她集齊組件後直奔白夜城……難道說她想對白夜城出手？！",
  ui_story_6_14_142_dialog_content = "不……白夜城外有強大的防護罩，她不可能得手的！",
  ui_story_6_14_A9_dialog_content = "可是她那樣做一定有原因……",
  ui_story_6_14_143_dialog_content = "所以她認為，光靠補完後的巨像已經足以正面對抗白夜城了嗎？！",
  ui_story_6_14_144_dialog_content = "PlayerName，立即啟程前往白夜城！",
  ui_story_6_14_145_dialog_content = "好……我們快走！",
  ui_story_7_1_1_dialog_content = "白夜之主，是我的鎧甲、血肉和骨骼，萬般邪祟傷不了我……",
  ui_story_7_1_A1_dialog_content = "白夜之主，是我的鎧甲、血肉和骨骼，萬般邪——冷靜！都別慌亂！！",
  ui_story_7_1_2_dialog_content = "快看！撞上了！撞上了！",
  ui_story_7_1_3_dialog_content = "那是……黑……<color=#FFB400>黑龍</color>？？？",
  ui_story_7_1_4_dialog_content = "應、應該沒關係吧？我們的護盾牢不可破，不可能被輕易破壞！",
  ui_story_7_1_5_dialog_content = "要相信白夜之主，相信極光的庇護。",
  ui_story_7_1_6_dialog_content = "只要護盾還在，任何邪祟都無法進入神聖的上城區！不要恐慌！",
  ui_story_7_1_7_dialog_content = "快到了！前面就是白夜城！",
  ui_story_7_1_8_dialog_content = "為什麼天空的顏色發生了變化？！",
  ui_story_7_1_9_dialog_content = "是城主啟動<color=#FFB400>護盾</color>。",
  ui_story_7_1_X1_dialog_content = "可能有很多人面臨危險，我們要趕緊入城！",
  ui_story_7_1_X2_dialog_content = "那舒默？",
  ui_story_7_1_10_dialog_content = "還是先救人吧。我們馬上進城！",
  ui_story_7_1_11_option_content = "好，那就停到城裡",
  ui_story_7_1_12_option_content = "不，最好停在外面",
  ui_story_7_1_13_dialog_content = "做不到……我的體型，和白夜城現在的狀態都不允許這樣做。",
  ui_story_7_1_14_dialog_content = "不行，白夜城的<color=#FFB400>護盾已經展開</color>。",
  ui_story_7_1_A2_dialog_content = "護盾不但能阻隔暗鬼，也會把臨空者號阻擋在外。",
  ui_story_7_1_16_dialog_content = "白夜城的護盾這麼厲害……為何我們還要趕緊入城？",
  ui_story_7_1_17_dialog_content = "護盾只會保護上城區。剩下的地方……就完全暴露在護盾之外了！",
  ui_story_7_1_F1_dialog_content = "暗鬼肯定會從下城區進入，進攻護盾盲區！",
  ui_story_7_1_F2_dialog_content = "我們不能把臨空者號停在满是暗鬼的下城區。",
  ui_story_7_1_18_dialog_content = "PlayerName，我可以懸停在白夜城的上空，隨時接應你們。",
  ui_story_7_1_19_dialog_content = "這樣你會不會有危險？",
  ui_story_7_1_F3_dialog_content = "我會盡量提防舒默，與你保持聯繫！",
  ui_story_7_1_F4_dialog_content = "那就委屈你了，臨空者。",
  ui_story_7_1_20_dialog_content = "卡蓮，白夜城會被擊破嗎？",
  ui_story_7_1_21_dialog_content = "不可能的，只要有<color=#FFB400>那個男人</color>在，白夜城的根基永遠不會被撼動。",
  ui_story_7_1_22_dialog_content = "的確。我的體型和白夜城目前的狀態都不允許我們進入。",
  ui_story_7_1_23_dialog_content = "PlayerName，你認為臨空者號停在外面更好嗎？",
  ui_story_7_1_24_dialog_content = "嗯，如果舒默是以白夜城為目標，臨空者號反而應該盡量遠離……",
  ui_story_7_1_25_dialog_content = "贊成。而且就算我們想把臨空者號開進城內也是不可能的。",
  ui_story_7_1_26_dialog_content = "上城區的<color=#FFB400>護盾已經打開了</color>，任何東西都進不去。",
  ui_story_7_1_F5_dialog_content = "但暗鬼肯定會從下城區進入，進攻護盾盲區！",
  ui_story_7_1_27_dialog_content = "PlayerName，我可以懸停在白夜城的上空，隨時接應你們。",
  ui_story_7_1_28_dialog_content = "這樣你會不會有危險？",
  ui_story_7_1_F6_dialog_content = "我會盡量提防舒默，與你保持聯繫！",
  ui_story_7_1_F7_dialog_content = "那就委屈你了，臨空者。",
  ui_story_7_1_29_dialog_content = "我們全速前進吧，如果舒默真的有自信擊垮白夜城……",
  ui_story_7_1_30_dialog_content = "不可能的，只要有<color=#FFB400>那個男人</color>在，白夜城的根基永遠不會被撼動。",
  ui_story_7_1_31_dialog_content = "城主大人，威脅已確認。是一座巨像正在衝擊白夜城！",
  ui_story_7_1_32_dialog_content = "我們的護盾已經啟動，目前上城區依然安全。",
  ui_story_7_1_33_dialog_content = "不可大意，目前還無法判斷敵方的力量和意圖，保持警戒。",
  ui_story_7_1_34_dialog_content = "讓衛隊繼續盯好對方的動向，情報部門也隨時追蹤最新動態。",
  ui_story_7_1_35_dialog_content = "現在下城區的情況如何？",
  ui_story_7_1_36_dialog_content = "城主，下城區已經有暗鬼侵入。需要調派人手前去支援嗎？",
  ui_story_7_1_37_dialog_content = "不。依然集中保護上城區，不要讓貴族們陷入恐慌，做出愚蠢的事來。",
  ui_story_7_1_38_dialog_content = "至於下城區，他們有自己的生存法則。",
  ui_story_7_1_39_dialog_content = "啟光的軍團呢？",
  ui_story_7_1_40_dialog_content = "大部分軍團都在遠離此地的區域布防，暫時無法回援。",
  ui_story_7_1_41_dialog_content = "白夜城附近只有兩隻小隊抵達，由薇薇安參謀長和希羅娜軍團長帶領。",
  ui_story_7_1_42_dialog_content = "她們兩位嗎……嗯，我知道了。最後，<color=#FFB400>卡蓮</color>呢？有消息了嗎？",
  ui_story_7_1_43_dialog_content = "剛收到消息，衛隊長一行正徒步進入下城區。",
  ui_story_7_1_44_dialog_content = "要她馬上回上城區。現在不是兒戲的時候，我不想讓別人再搬弄是非。",
  ui_story_7_1_45_dialog_content = "<color=#e8d9bb>白夜城·下城區內</color>",
  ui_story_7_1_46_dialog_content = "衛隊的人，一個也沒見到。",
  ui_story_7_1_47_dialog_content = "已經有暗鬼的氣息了。",
  ui_story_7_1_48_dialog_content = "這混亂的樣子，真的是之前見過的白夜城嗎……",
  ui_story_7_1_49_dialog_content = "……停好了，在你們上方大概……的位置。",
  ui_story_7_1_A3_dialog_content = "白夜城的護盾……造成干擾，希望……聽到……",
  ui_story_7_1_50_dialog_content = "放心，我聽到了！我們都很安全。你保護好自己！",
  ui_story_7_1_51_dialog_content = "這句話……我說才對，PlayerName",
  ui_story_7_1_52_dialog_content = "我……等待你們！請……保護好自……",
  ui_story_7_1_53_dialog_content = "真希望現在有人告訴我情況如何……",
  ui_story_7_1_54_dialog_content = "狀況沒有看起來那麼糟哦，小薇絲、PlayerName。",
  ui_story_7_1_55_dialog_content = "<color=#FFB400>不，是薇薇安</color>長官的。",
  ui_story_7_1_56_dialog_content = "大部分軍團都在防守周邊其他區域，所以暫時只有我們能來幫忙了。",
  ui_story_7_1_57_dialog_content = "這些民眾喊得太誇張了吧，什麼「白夜城陷落」之類的。",
  ui_story_7_1_A4_dialog_content = "空裔！我們又見面了。你一直被捲進麻煩的事情呢，每次都有你。",
  ui_story_7_1_58_dialog_content = "其實我也不願意被捲進這些麻煩裡，請不要責怪我……",
  ui_story_7_1_59_dialog_content = "怎麼會~你很努力地在阻止舒默了不是嗎？只是我們都沒有料到這一步罷了！",
  ui_story_7_1_60_dialog_content = "長官，妳知道白夜城的狀況如何嗎？",
  ui_story_7_1_61_dialog_content = "上城區部分當然是高枕無憂啦，你看到那個護盾了嗎？",
  ui_story_7_1_62_dialog_content = "已經啟動了，沒有任何攻擊可以穿透喔。這也是「永不淪陷」的資本呢……",
  ui_story_7_1_63_dialog_content = "但是下城區就沒這麼好過了。",
  ui_story_7_1_64_dialog_content = "<color=#FFB400>希羅娜</color>長官？不、軍團長……",
  ui_story_7_1_65_dialog_content = "啊，我忘了說這次緊急回援大部分的兵力都是從第一軍團調的呢。",
  ui_story_7_1_66_dialog_content = "那護盾並未覆蓋下城區。別說暗鬼了，就連三歲小孩都能來去自如。",
  ui_story_7_1_68_dialog_content = "能應對嗎？現在的確切情況是？",
  ui_story_7_1_70_dialog_content = "正在快速清理中。雖然很棘手，但這個數量我的人勉強可以應對。",
  ui_story_7_1_71_dialog_content = "衛隊呢？我接到的通知是要我立即返回上城區。其他衛隊在哪裡？",
  ui_story_7_1_72_dialog_content = "卡蓮·德·舒瓦茲小姐，恐怕你還沒理解我的意思。",
  ui_story_7_1_A5_dialog_content = "妳的父親已經下令，所有衛隊，包括妳，都要全力保護上城區。",
  ui_story_7_1_73_dialog_content = "毫不意外，不是嗎？你不可能想不到。",
  ui_story_7_1_74_dialog_content = "你沒必要用這種態度跟我說話，希羅娜！我認為我過去的行動已經足夠表態了！",
  ui_story_7_1_75_dialog_content = "你的行動改變了什麼嗎？白夜城依舊沒變，仍是那個白夜城。",
  ui_story_7_1_76_option_content = "都少說兩句吧，二位女士",
  ui_story_7_1_77_option_content = "都給我住口！現在大局為重！",
  ui_story_7_1_78_dialog_content = "我對吵架不感興趣。",
  ui_story_7_1_79_dialog_content = "PlayerName，輪不到你來當和事佬。",
  ui_story_7_1_80_dialog_content = "這是我們啟光人和白夜人之間的事情。",
  ui_story_7_1_81_dialog_content = "問題不在這裡吧……而且你們不都是光靈嗎……",
  ui_story_7_1_82_dialog_content = "長官，PlayerName只是擔心現在的情況吧。大家都很著急……",
  ui_story_7_1_83_dialog_content = "小薇絲的 EQ 很高呢。PlayerName說得沒錯，大家不都是一家人嗎？",
  ui_story_7_1_84_dialog_content = "首先以光靈的身分一起戰鬥才是要緊的事～對吧對吧？",
  ui_story_7_1_85_dialog_content = "……我贊成。立場現在不重要。",
  ui_story_7_1_86_dialog_content = "說起立場，卡蓮妳要不要先回上城區復命？城主殿下好像在找妳。",
  ui_story_7_1_F8_dialog_content = "難道只有我看得見那些暗鬼嗎？",
  ui_story_7_1_87_dialog_content = "注意你說話的語氣，PlayerName！",
  ui_story_7_1_88_dialog_content = "PlayerName，那可是啟光第一軍團的軍團長……以及卡蓮。",
  ui_story_7_1_89_dialog_content = "我知道！但我也相信無論是軍團長還是衛隊長，都不想為了口舌之爭耽誤救援吧？",
  ui_story_7_1_90_dialog_content = "好，現在最重要的是誅殺暗鬼。不要把無聊的勢力鬥爭掛在嘴邊。",
  ui_story_7_1_91_dialog_content = "很遺憾，我暫時還不需要一個小姑娘來教我怎麼為人處世。",
  ui_story_7_1_92_dialog_content = "至於誅殺暗鬼，這是我每天在戰場前線做的事。",
  ui_story_7_1_93_dialog_content = "聽說你最近經歷不少戰鬥，現在應該能理解了吧？",
  ui_story_7_1_94_dialog_content = "……",
  ui_story_7_1_95_dialog_content = "好了、好了，都是一家人～有這個精力，不如先用來對付暗鬼吧？",
  ui_story_7_1_96_dialog_content = "卡蓮呢，妳要不要先遵循命令返回……",
  ui_story_7_1_97_dialog_content = "我不回去。將在外，君令有所不受。",
  ui_story_7_1_98_dialog_content = "這……也沒有「在外」吧，實際上已經被打到家裡了……",
  ui_story_7_1_F9_dialog_content = "薇絲，妳少說兩句……",
  ui_story_7_1_99_dialog_content = "軍團長！下城區出現的暗鬼比預估要多，出現一個防守缺口！",
  ui_story_7_1_A6_dialog_content = "那裡的民眾還沒來得及避難，請指示！！",
  ui_story_7_1_100_dialog_content = "我親自過去！至於你們，自便。",
  ui_story_7_1_101_dialog_content = "請讓我們也一起！多少能幫上忙！",
  ui_story_7_1_102_dialog_content = "很有幹勁呢，小薇絲！<color=#FFB400>那大家一起吧</color>！",
  ui_story_7_1_103_dialog_content = "我來帶路吧。下城區是我巡邏過無數次的地方，沒人比我更熟悉了。",
  ui_story_7_1_104_dialog_content = "卡蓮……妳不回去覆命真的可以嗎？",
  ui_story_7_1_105_dialog_content = "不用再多說。我心意已決，這一切……必須有個了結。",
  ui_story_7_1_106_dialog_content = "白夜城的龜殼，真硬呢。",
  ui_story_7_1_107_dialog_content = "可惡，為什麼你不告訴我？！竟然還有這種防禦手段……懦夫的伎倆！",
  ui_story_7_1_108_dialog_content = "我說過等補完後再發動進攻。可顯然你的自負超越了理智不是嗎？",
  ui_story_7_1_109_dialog_content = "……有空說教，不如趕快多派你的走狗去白夜城製造混亂！！",
  ui_story_7_1_110_dialog_content = "噓……安靜。我不喜歡喧鬧。",
  ui_story_7_1_111_dialog_content = "白夜城的護盾很快就要耗盡能量了。",
  ui_story_7_1_A7_dialog_content = "到時候……你隨便進去。",
  ui_story_7_1_112_dialog_content = "那我現在要做什麼？要等嗎？還是繼續進攻？",
  ui_story_7_1_113_dialog_content = "坐著看你那群沒用的廢物行動嗎？",
  ui_story_7_1_114_dialog_content = "別急躁，舒默。妳的老對手也來了，而且就在附近。",
  ui_story_7_1_116_dialog_content = "你是說臨空者號？還有PlayerName？",
  ui_story_7_1_117_dialog_content = "對。你那副表情是什麼意思？你又想去玩了？給我適可而止。",
  ui_story_7_1_X3_dialog_content = "……我想做什麼，就做什麼。別忘了，我不聽命於任何人，包括妳，也包括日蝕。",
  ui_story_7_1_X4_dialog_content = "唉，無可救藥。",
  ui_story_7_2_1_dialog_content = "卡蓮，離需要支援的地方還有多遠？",
  ui_story_7_2_2_dialog_content = "到了！就是這邊，剛剛那個士兵說的地方……",
  ui_story_7_2_3_dialog_content = "暗鬼的氣息已經很濃郁了。如果要論<color=#FFB400>最優先行動</color>的話……",
  ui_story_7_2_4_option_content = "先引導民眾避難",
  ui_story_7_2_5_option_content = "先清理遊蕩暗鬼",
  ui_story_7_2_6_dialog_content = "PlayerName會做以人為本的決策呢！說不定以後可以成為了不起的人～",
  ui_story_7_2_7_dialog_content = "鼓勵過頭了，長官……",
  ui_story_7_2_8_dialog_content = "好。我去找落難的民眾，我的速度比你們都快。",
  ui_story_7_2_A1_dialog_content = "你們只管殺死眼前的暗鬼就好了，這點小事可以做到吧？",
  ui_story_7_2_9_dialog_content = "明白！只有解決危險的源頭才能保證救援順利。",
  ui_story_7_2_10_dialog_content = "我們分工合作，救援和戰鬥也許可以同步進行。",
  ui_story_7_2_11_dialog_content = "我去找落難的民眾，我的速度比你們都快。",
  ui_story_7_2_A2_dialog_content = "你們只管殺死眼前的暗鬼就好了，這點小事可以做到吧？",
  ui_story_7_2_12_dialog_content = "小看人也要有個限度，希羅娜。",
  ui_story_7_2_13_dialog_content = "哈、哈哈，都很有幹勁呢！那真是太好了，開始吧！",
  ui_story_7_2_14_dialog_content = "我走這邊，小薇絲，那邊就交給你們了！",
  ui_story_7_2_15_dialog_content = "另外，你們的巨像呢？現在局面還不明朗，小心別被敵人抄了後路！",
  ui_story_7_2_16_dialog_content = "停在城外了，現在非常安全……應該吧。",
  ui_story_7_2_17_dialog_content = "我們人力不足，大家都要打起精神來。",
  ui_story_7_2_F1_dialog_content = "哎，如果有衛隊支援的話……",
  ui_story_7_2_18_dialog_content = "我不就是衛隊的人嗎？",
  ui_story_7_2_19_dialog_content = "啊、啊！沒有責怪誰的意思～",
  ui_story_7_2_21_dialog_content = "我們趕緊行動！今天也要以擊殺三位數的暗鬼為小目標呢！",
  ui_story_7_2_22_dialog_content = "小、小目標？！",
  ui_story_7_2_23_dialog_content = "啟光的長官們可沒有等閒之輩呢……我們也開始肅清周圍的敵人吧！",
  ui_story_7_6_1_dialog_content = "呼——我這邊，清理完畢！",
  ui_story_7_6_2_dialog_content = "這邊也是！長官，請問下城區還有需要支援的地方嗎！",
  ui_story_7_6_3_dialog_content = "有新的蟲子爬出來了，但數量已經在可控範圍內。辛苦了。",
  ui_story_7_6_4_dialog_content = "呼……有驚無險呢。還好我們動作夠快……",
  ui_story_7_6_6_dialog_content = "好了呢小薇絲～下城區暫時不需要太多支援了，我們可以看看其他地方",
  ui_story_7_6_7_dialog_content = "也許狡猾的敵人正在偷襲防守薄弱之處哦！",
  ui_story_7_6_8_dialog_content = "長官您知道您有一項叫做「一語成讖」的特技嗎……",
  ui_story_7_6_9_dialog_content = "為了保險起見，再確認一下臨空者號的狀態吧，PlayerName？",
  ui_story_7_6_10_dialog_content = "說起來，臨空者號很久沒聯絡我了。我試試……",
  ui_story_7_6_12_dialog_content = "……正常。沒有暗鬼……但氣溫似乎突然下降很多，我……",
  ui_story_7_6_13_dialog_content = "<size=45>這……？！</size>",
  ui_story_7_6_14_dialog_content = "怎麼了，卡蓮？你受傷了？",
  ui_story_7_6_15_dialog_content = "不……剛收到的消息，<color=#FFB400>上城受到攻擊</color>！",
  ui_story_7_6_16_dialog_content = "上城區？難道有暗鬼突破下城區的防線攻入上城區？",
  ui_story_7_6_17_dialog_content = "不，下城區的防線並沒有被攻破。應該是有預謀的潛伏作戰！",
  ui_story_7_6_18_dialog_content = "直接進攻白夜城的核心區域？上城區不是防守得相當嚴密嗎？",
  ui_story_7_6_19_dialog_content = "是的，非常嚴密。但是剛才那些暗鬼的行動詭異……",
  ui_story_7_6_20_dialog_content = "舒默敢進攻白夜城，那些暗鬼很可能有備而來。",
  ui_story_7_6_21_dialog_content = "對，我突然有不好的預感，我必須馬上回去。",
  ui_story_7_6_22_dialog_content = "我們也一起去，PlayerName，快！",
  ui_story_7_6_23_dialog_content = "能潛入上城的敵人必定有恐怖的實力……謝謝你們願意同行。",
  ui_story_7_6_24_dialog_content = "好！長官，我們剛收到消息，上城區受到特殊暗鬼的攻擊，現在立刻前往協防！",
  ui_story_7_6_25_dialog_content = "正在路上啦～",
  ui_story_7_6_26_dialog_content = "我都已經快到了。",
  ui_story_7_6_27_dialog_content = "軍團長果然不一樣？！",
  ui_story_7_7_1_dialog_content = "抱歉，來晚了！",
  ui_story_7_7_2_dialog_content = "衛隊長大人！您終於回來了！暗鬼正在……",
  ui_story_7_7_3_dialog_content = "不用廢話！敵人呢？！",
  ui_story_7_7_4_dialog_content = "在這邊！請跟我來！",
  ui_story_7_7_5_dialog_content = "<size=45>……唔嘎嘎嘎嘎……！！</size>",
  ui_story_7_7_6_dialog_content = "繼續！不要讓它再前進了！前面可就是上城區！！",
  ui_story_7_7_7_dialog_content = "嘎——！！",
  ui_story_7_7_8_dialog_content = "糟、糟了！防線被打亂了，重新組織起來！！不能讓牠再靠近城區！",
  ui_story_7_7_9_dialog_content = "嗚啊！卡蓮姐姐！",
  ui_story_7_7_10_dialog_content = "你們在幹什麼？！就這樣看著那傢伙到處破壞嗎！這可是白夜城的核心要地啊！",
  ui_story_7_7_11_dialog_content = "城主殿下有令，<color=#FFB400>我們只負責守住上城區</color>……",
  ui_story_7_7_12_dialog_content = "嚴格來說，那大蟲子還沒突破到這裡面來，所以我們也不能出去……",
  ui_story_7_7_13_dialog_content = "這是哪門子的原則？！！",
  ui_story_7_7_15_dialog_content = "卡蓮，如果衛隊無法出擊，我們還有啟光的支援！兩位長官應該可以對付它！",
  ui_story_7_7_16_dialog_content = "又要幫衛隊的傢伙們擦屁股了嗎？",
  ui_story_7_7_17_dialog_content = "長官！衛隊只是聽令……無法離開上城區迎擊敵人，請讓我們來吧！",
  ui_story_7_7_18_dialog_content = "每次和白夜城的傢伙們合作，都會更新我對「迂腐」二字的理解。",
  ui_story_7_7_19_dialog_content = "好啦小希，現在不是吐槽的時候啦～那個傢伙，那些士兵已經快撐不住了……",
  ui_story_7_7_21_dialog_content = "把絞索和牽引車拉過來！那種東西，直接肢解就好了！",
  ui_story_7_7_22_dialog_content = "肢、肢解？！",
  ui_story_7_7_23_dialog_content = "……？",
  ui_story_7_7_24_dialog_content = "方便處理屍體！這都是經驗之談，毛頭小鬼只需要戰鬥就好了！",
  ui_story_7_7_25_dialog_content = "是、是！需要我們怎麼做請長官……",
  ui_story_7_7_26_dialog_content = "先一起把這傢伙打趴下！薇薇安，記住看準時機「剪掉」它，就像以前那樣！",
  ui_story_7_7_27_dialog_content = "明白，就像以前那樣！",
  ui_story_7_7_28_dialog_content = "我來開路！其他無關人員都讓開，別去送死了！至於<color=#FFB400>指揮</color>……",
  ui_story_7_7_29_dialog_content = "交給我吧！我可以勝任！",
  ui_story_7_7_30_dialog_content = "<color=#FFB400>讓它倒在上城區之外吧</color>！",
  ui_story_7_7_31_dialog_content = "<anim type=Shake><size=45>吼——！！！</size></anim>",
  ui_story_7_7_32_dialog_content = "薇薇安、現在！",
  ui_story_7_7_33_dialog_content = "來了！「鐳擊」！",
  ui_story_7_7_34_dialog_content = "「血債血償」！",
  ui_story_7_7_36_dialog_content = "倒、倒下了！終於！",
  ui_story_7_7_37_dialog_content = "壓制很成功！你們這幾個小鬼，也有能派上用場的時候嘛！",
  ui_story_7_7_38_dialog_content = "……",
  ui_story_7_7_39_dialog_content = "長官過獎了。",
  ui_story_7_7_40_dialog_content = "報告！黑色巨像對我們的攻擊依然在繼續，沒有減弱的跡象！",
  ui_story_7_7_41_dialog_content = "舒默……",
  ui_story_7_7_42_dialog_content = "仍然執迷不悟嗎……這樣耗下去對她有什麼好處？",
  ui_story_7_7_43_dialog_content = "不自量力。這點暗鬼哪怕再來十次也無法觸及上城區一根汗毛。",
  ui_story_7_7_44_dialog_content = "也許只是愚蠢而已。",
  ui_story_7_7_45_dialog_content = "確定上城區的威脅都清除了吧？如果沒有別的事情，我先走了。",
  ui_story_7_7_46_dialog_content = "第一軍團還有東邊的防務要完成，「托衛隊的福」呢。",
  ui_story_7_7_47_dialog_content = "……無論如何，感謝你們的協助，啟光。",
  ui_story_7_7_48_dialog_content = "不用感謝我，感謝PlayerName和薇絲吧。",
  ui_story_7_7_A2_dialog_content = "不是所有人都有耐心和白夜城的傢伙合作的，更別提把背後交給你們了。",
  ui_story_7_7_49_dialog_content = "……",
  ui_story_7_7_50_dialog_content = "撂下莫名其妙的話就走了呢。小希有時候的確是這樣，不要太在意，小卡蓮。",
  ui_story_7_7_51_dialog_content = "危機告一段落，這就是最好的結果啦。",
  ui_story_7_7_52_dialog_content = "舒默想正面進攻白夜城，卻沒想到這裡有近乎無解的防禦手段……",
  ui_story_7_7_53_dialog_content = "下一步她會做什麼？剛才的黑色巨像，是已經補完過後的嗎？",
  ui_story_7_7_X1_dialog_content = "她已經搶了三個組件，還好……那座黑色巨像的威力看起來並不強。",
  ui_story_7_7_54_dialog_content = "我猜舒默還沒有完成自己的補完？這是一次過於輕敵的進攻吧。",
  ui_story_7_7_55_dialog_content = "以你們對她的判斷，她會惱羞成怒地做出其他意料之外的舉動嗎？",
  ui_story_7_7_56_dialog_content = "啊，不會有什麼不得了的事情發生吧？",
  ui_story_7_7_57_dialog_content = "長官請不要再說了，您真的每次都會說中……",
  ui_story_7_7_58_option_content = "現在應該主動出擊",
  ui_story_7_7_59_option_content = "目前最好靜觀其變",
  ui_story_7_7_60_dialog_content = "同意，這時候我們最好趁此情勢主動出擊！",
  ui_story_7_7_61_dialog_content = "對，之前搶奪組件一直處於被動狀態，現在要轉守為攻呀！",
  ui_story_7_7_62_dialog_content = "PlayerName說得有道理～在掌握更多情報之前，最好按兵不動。",
  ui_story_7_7_63_dialog_content = "現在更急躁的應該是舒默才對——",
  ui_story_7_7_A3_dialog_content = "明明掌握了三個組件，卻碰了一鼻子灰——我們等著她犯錯就好了！",
  ui_story_7_7_64_dialog_content = "唔……！",
  ui_story_7_7_65_dialog_content = "PlayerName？你怎麼了……",
  ui_story_7_7_66_dialog_content = "（頭腦中……這股刺痛是？！）",
  ui_story_7_7_67_dialog_content = "……",
  ui_story_7_7_68_dialog_content = "臨空者號！",
  ui_story_7_7_69_dialog_content = "敵襲！有敵……她已侵入我的……敵人不止……還有一個……",
  ui_story_7_7_X2_dialog_content = "我聽不清楚！臨空者號，你還在之前的座標嗎？！我們馬上回援！",
  ui_story_7_7_X3_dialog_content = "……附近！請……敵人已經侵入到……而且不只她一個！",
  ui_story_7_7_A4_dialog_content = "……<color=#FFB400>回援</color>……<color=#FFB400>回援</color>！",
  ui_story_7_7_X4_dialog_content = "臨空者號被入侵了！舒默，她轉移了攻擊目標！！",
  ui_story_7_7_X5_dialog_content = "？！",
  ui_story_7_7_X6_dialog_content = "攻不進白夜城，就轉頭攻擊我們嗎？！",
  ui_story_7_7_70_dialog_content = "緊急回援吧。這次我沒有帶空艇……可以調用白夜城的嗎，卡蓮？",
  ui_story_7_7_71_dialog_content = "我……",
  ui_story_7_7_72_dialog_content = "衛隊長，城主又發來了命令。您……必須回上城區復命了。",
  ui_story_7_7_73_dialog_content = "再一下就行。情況緊急，我先幫他們……",
  ui_story_7_7_74_dialog_content = "這不是請求，而是……抱歉，如果您再不回去，恐怕要動用四天使了。",
  ui_story_7_7_75_dialog_content = "……欸？！我只是在旁聽，為什麼突然提到我啊？",
  ui_story_7_7_76_dialog_content = "……",
  ui_story_7_7_77_dialog_content = "卡蓮，看來妳父親有自己的考量，妳回去吧。",
  ui_story_7_7_78_dialog_content = "不用擔心，現在臨空者號是我們啟光的事情，我們啟光人自己解決。",
  ui_story_7_7_79_dialog_content = "等等，我什麼時候變成啟光的人了……",
  ui_story_7_7_80_dialog_content = "……",
  ui_story_7_7_81_dialog_content = "……",
  ui_story_7_7_82_dialog_content = "有一種退而求其次的感覺呢……我的巨像還要多久補完？",
  ui_story_7_7_83_dialog_content = "很快，別操心了。要做什麼快抓緊時間吧，我的忍耐也是有限度的，舒默。",
  ui_story_7_7_85_dialog_content = "當然。我只是想完成之前在低語迴廊沒能完成的事而已……",
  ui_story_7_7_86_dialog_content = "PlayerName……那傢伙太特殊了，我第一次有想要留空裔一命的念頭。",
  ui_story_7_7_87_dialog_content = "會來的，我有種預感，「羈絆」也好，「道義」也好……",
  ui_story_7_7_A5_dialog_content = "PlayerName會被這些腐朽的觀念引回這裡的。",
  ui_story_7_7_89_dialog_content = "那就別等了，我就不重申有多少傢伙死於太多廢話了。",
  ui_story_7_7_90_dialog_content = "<color=#FFB400>直接殺死它吧</color>，舒默。",
  ui_story_7_7_91_dialog_content = "臨空者號，我的老朋友……",
  ui_story_7_7_92_dialog_content = "<size=45>這可能會有點痛！！</size>",
  ui_story_7_8_1_dialog_content = "臨空者……你聽到了嗎？",
  ui_story_7_8_2_option_content = "試著感應",
  ui_story_7_8_3_dialog_content = "臨空者……臨空者……",
  ui_story_7_8_4_option_content = "試著感應",
  ui_story_7_8_5_dialog_content = "不行，還是感應不到！護盾的干擾加上……",
  ui_story_7_8_6_dialog_content = "我們必須盡快趕回巨像上去！",
  ui_story_7_8_7_dialog_content = "好像我也無權調用白夜城的空艇呢。果然需要衛隊的許可才行嗎？",
  ui_story_7_8_8_dialog_content = "如果從最近的啟光據點徵調，恐怕需要不少時間……",
  ui_story_7_8_9_dialog_content = "可是卡蓮也沒有辦法……",
  ui_story_7_8_11_dialog_content = "卡蓮作為城主的女兒和白夜城衛隊長，已經為我們做太多了。",
  ui_story_7_8_12_dialog_content = "對～如果此時她真的再次抗命，帶著一架空艇出現，我們會內疚一年吧？",
  ui_story_7_8_13_dialog_content = "……糟了，長官使用「一語成讖」的技能了……",
  ui_story_7_8_14_dialog_content = "——你們看！",
  ui_story_7_8_15_dialog_content = "抱歉打斷一下。那邊有一艘突然起飛的空艇？",
  ui_story_7_8_16_dialog_content = "飛得歪歪扭扭的，是不是正在向我們這邊衝過來……？",
  ui_story_7_8_17_dialog_content = "……？",
  ui_story_7_8_18_dialog_content = "欸？",
  ui_story_7_8_19_dialog_content = "不是吧？！卡蓮，妳……",
  ui_story_7_8_20_dialog_content = "快！先上來！我這是<color=#FFB400>搶</color>來的！",
  ui_story_7_8_21_dialog_content = "搶、搶來的？！你不是衛隊長嗎？！",
  ui_story_7_8_22_dialog_content = "待會兒再解釋！你們不是還要回臨空者號嗎？到底走不走！",
  ui_story_7_8_23_dialog_content = "這樣一來，趕得上！",
  ui_story_7_8_24_dialog_content = "對不起，PlayerName……我來遲了……",
  ui_story_7_8_25_option_content = "不，妳已經為我們做了很多",
  ui_story_7_8_26_option_content = "沒關係，沒想到妳還會駕駛空艇",
  ui_story_7_8_27_dialog_content = "好吧。本來我只是為了守護白夜城……",
  ui_story_7_8_28_dialog_content = "但現在看來，還有其它我想要守護的東西。",
  ui_story_7_8_29_dialog_content = "還能耍嘴皮子，看來你心態還不錯。",
  ui_story_7_8_30_dialog_content = "快回到臨空者號上吧！他……一定在等著我們呢。",
  ui_story_7_8_31_dialog_content = "我從不懼怕死亡，正如<color=#FFB400>那一年</color>，我沒在你面前退縮。",
  ui_story_7_8_32_dialog_content = "你可以背棄光的信條，也可以投靠黑色的彼岸……",
  ui_story_7_8_A1_dialog_content = "但只有極光才是所有生靈最終的歸宿。",
  ui_story_7_8_33_dialog_content = "舒默，妳可以毀掉我的意識，但妳絕對……無法擊垮PlayerName！",
  ui_story_7_9_1_dialog_content = "果然，舒默終於對臨空者號出手了！",
  ui_story_7_9_2_dialog_content = "已經有很多暗鬼侵入進來了呢，空氣中一股暗能的惡臭。",
  ui_story_7_9_3_dialog_content = "這群傢伙竟然把我的臨空者號弄成這副模樣！",
  ui_story_7_9_4_dialog_content = "在左邊，來了。這些骯髒的東西發現我們了……",
  ui_story_7_9_5_dialog_content = "先迎戰吧！",
  ui_story_7_9_6_dialog_content = "還好，好像沒有引起太多騷動，不會打草驚蛇。",
  ui_story_7_9_7_dialog_content = "我們可以直接用最快的速度殺進去，在舒默反應過來之前……",
  ui_story_7_9_8_dialog_content = "做、做不到的吧……",
  ui_story_7_9_9_dialog_content = "卡蓮，現在這種情況……妳沒有必要和我們一起冒險。",
  ui_story_7_9_10_dialog_content = "我們是夥伴，你們是這麼說的，對吧。",
  ui_story_7_9_11_dialog_content = "而且強敵出現在眼前，不用手中的槍將它撕成兩半，晚上豈能安眠？",
  ui_story_7_9_12_option_content = "……不愧是卡蓮",
  ui_story_7_9_13_option_content = "嗯，我們是夥伴",
  ui_story_7_9_14_dialog_content = "嗯？這是想表達什麼意思呢？",
  ui_story_7_9_15_dialog_content = "PlayerName應該是想說，卡蓮不愧是白夜城的衛隊長吧？",
  ui_story_7_9_A1_dialog_content = "既有責任心又有魄力。",
  ui_story_7_9_16_dialog_content = "是嗎。但恭維我，似乎並不能為現狀帶來改變。",
  ui_story_7_9_17_dialog_content = "而且就算你不這樣說，我也……會跟你一起戰鬥的。嗯，因為我們是<color=#FFB400>夥伴</color>。",
  ui_story_7_9_18_dialog_content = "雖然大家都說白夜城的人不近人情，但我覺得妳不一樣。",
  ui_story_7_9_19_dialog_content = "……這也是我覺得矛盾的地方。我應該代表白夜城，還是代表我自己呢？",
  ui_story_7_9_20_dialog_content = "現在你已經用行動得出結論了吧。",
  ui_story_7_9_21_dialog_content = "也許吧。",
  ui_story_7_9_22_dialog_content = "我知道我們是夥伴，你為何又要重複一遍？",
  ui_story_7_9_23_dialog_content = "妳剛才不是問了「對吧」嗎……算了，這種時候還是不要閒聊了。",
  ui_story_7_9_24_dialog_content = "卡蓮，妳明白我們接下來要面對什麼吧？雖然前幾次都有驚無險，但……",
  ui_story_7_9_25_dialog_content = "啊，有種不祥的預感？",
  ui_story_7_9_26_dialog_content = "長官你快別說了……",
  ui_story_7_9_27_dialog_content = "不管舒默多麼強大，我們都有必須要戰勝她的理由不是嗎？",
  ui_story_7_9_28_dialog_content = "雖然「<color=#FFB400>有要守護的東西</color>」這種說法很老套……",
  ui_story_7_9_A2_dialog_content = "但說到底，浴血奮戰的意義不就是保護在意的人和物嗎？",
  ui_story_7_9_29_dialog_content = "嗯，比如臨空者號。",
  ui_story_7_9_30_dialog_content = "對，臨空者號……",
  ui_story_7_9_31_dialog_content = "PlayerName，你可以感應到臨空者號嗎？我們最好先確認他是否還……",
  ui_story_7_9_32_dialog_content = "我感應不到。但我相信他還活著。",
  ui_story_7_9_33_dialog_content = "我從未有和任何巨像交談的機會呢，有點好奇。",
  ui_story_7_9_A3_dialog_content = "啊，抱歉，妄加評論了。",
  ui_story_7_9_34_dialog_content = "倒是長官您，為什麼也跟著上來了……",
  ui_story_7_9_35_dialog_content = "和卡蓮的理由一樣吧？被那傢伙耍得團團轉，這口惡氣我也想好好出一出呀～",
  ui_story_7_9_36_dialog_content = "好，那我們快前進吧。PlayerName，舒默在哪？",
  ui_story_7_9_37_dialog_content = "我能感覺到，那股寒氣的源頭……在<color=#FFB400>艦橋</color>！",
  ui_story_7_9_A4_dialog_content = "路上恐怕有許多暗鬼，大家準備好了嗎？",
  ui_story_7_9_A5_dialog_content = "當然，我手中的槍一刻也沒有放下過！",
  ui_story_7_12_1_dialog_content = "PlayerName……無論你是否可以收到這條留言……",
  ui_story_7_12_2_dialog_content = "與你同行是我莫大的榮幸。我很慶幸在十七年前保護了你，為世界留下希望。",
  ui_story_7_12_3_dialog_content = "如果可以，希望你<color=#FFB400>不要回援</color>，重複一遍，<color=#FFB400>不要回援</color>——",
  ui_story_7_12_A1_dialog_content = "因為敵人的強大遠遠超乎我們的想像。",
  ui_story_7_12_4_dialog_content = "累積你的力量，PlayerName，無需為我的離去感到悲傷……",
  ui_story_7_12_5_dialog_content = "巨像，<color=#FFB400>本就是為你們而生</color>！",
  ui_story_7_13_1_dialog_content = "<size=45>唔——！</size>",
  ui_story_7_13_2_dialog_content = "（心跳……開始<color=#FFB400>紊亂</color>了……？）",
  ui_story_7_13_3_dialog_content = "艦橋就在前方！注意敵情！",
  ui_story_7_13_4_dialog_content = "還是聯繫不上臨空者號嗎？",
  ui_story_7_13_5_dialog_content = "我在嘗試。隱約能聽到……好像在不斷重複一句話。",
  ui_story_7_13_6_dialog_content = "但從剛剛連那句也聽不到了，也許是……",
  ui_story_7_13_7_dialog_content = "（這——心跳又紊亂了？！）",
  ui_story_7_13_8_dialog_content = "你怎麼了，PlayerName？",
  ui_story_7_13_9_dialog_content = "是不是這裡暗能太濃郁了？PlayerName的身體適應不了吧。",
  ui_story_7_13_10_dialog_content = "或者是感應到什麼了？",
  ui_story_7_13_11_dialog_content = "喔？真的嗎？是臨空者號嗎？",
  ui_story_7_13_12_dialog_content = "不，不是。我也感受到了……你沒發現<color=#FFB400>空氣突然變冷了</color>嗎？",
  ui_story_7_13_13_dialog_content = "這種熟悉又陌生的感覺，那個狂傲得讓人反胃的傢伙……",
  ui_story_7_13_14_dialog_content = "……？！",
  ui_story_7_13_15_dialog_content = "呵——欠。",
  ui_story_7_13_16_dialog_content = "<size=45><color=#FFB400>舒默</color>——！</size>",
  ui_story_7_13_17_dialog_content = "PlayerName！你感應到舒默了嗎？！她在哪！",
  ui_story_7_13_18_dialog_content = "妳……舒默……妳對臨空者號做了……唔……！",
  ui_story_7_13_19_dialog_content = "果然陰魂不散……而且絲毫沒有學聰明，PlayerName。",
  ui_story_7_13_20_dialog_content = "我還能對臨空者號做什麼？不過是捏碎他的意識模組而已。",
  ui_story_7_13_21_dialog_content = "意識模組？妳破壞臨空者號的「自我意識」？！",
  ui_story_7_13_22_dialog_content = "對啊，你沒有感覺到那種「心臟被生生拽下、連靈魂都為之刺痛」的感覺嗎？",
  ui_story_7_13_23_dialog_content = "舒默……！",
  ui_story_7_13_24_dialog_content = "你要是聽不懂，我換句話說……你的臨空者號，<color=#FFB400>已經死了</color>。",
  ui_story_7_14_1_dialog_content = "……跟丟了？",
  ui_story_7_14_2_dialog_content = "嗚啊啊！！抱歉！卡蓮姐姐實在跑得太快，一溜煙就跑掉了……",
  ui_story_7_14_3_dialog_content = "拉斐爾在空中轉了一圈，只看到那艘可怕的黑色巨像，還有小小的白色巨像！",
  ui_story_7_14_4_dialog_content = "白色巨像……PlayerName。呵，一群小孩子湊到一塊兒了。",
  ui_story_7_14_5_dialog_content = "黑色巨像的行動有變化嗎？",
  ui_story_7_14_6_dialog_content = "沒有。她仍然在持續攻擊護盾。暗鬼的攻勢也沒有減弱。",
  ui_story_7_14_7_dialog_content = "維持護盾的能量佔用狀態，用儲備光能優先恢復貴族區和基建的供給。",
  ui_story_7_14_A1_dialog_content = "然後讓兵力迅速支援下城區。",
  ui_story_7_14_9_dialog_content = "那那那，卡蓮姐姐呢……？",
  ui_story_7_14_10_dialog_content = "卡蓮做出了她自己的選擇，想必也做好了相應的覺悟。",
  ui_story_7_14_11_dialog_content = "以我的立場，現在沒有任何理由出動衛隊跟隨她進行這種無謂的「追擊」。",
  ui_story_7_14_12_dialog_content = "是……",
  ui_story_7_14_13_dialog_content = "不過，她是怎麼搶到那艘空艇的……這樣會有不好的影響。",
  ui_story_7_14_14_dialog_content = "如果其他衛隊成員也私自飛出白夜城<color=#FFB400>去支援她</color>……",
  ui_story_7_14_15_dialog_content = "嗯？您為何看著拉斐爾……？",
  ui_story_7_14_16_dialog_content = "嗯。還有什麼問題嗎？",
  ui_story_7_14_17_dialog_content = "啊！啊……喔……拉斐爾明白了！好的！",
  ui_story_7_14_18_dialog_content = "拉斐爾這就去……啊，不是！是這就告退……",
  ui_story_7_14_19_dialog_content = "慢死了，老鼠們。你們是在自己家裡迷路了嗎？",
  ui_story_7_14_20_dialog_content = "閉上你的嘴，暗鬼。有心思說廢話，不如把自己的遺願交代一下！",
  ui_story_7_14_21_dialog_content = "你是不是誤會了什麼，大小姐？現在的我，可是擁有<color=#FFB400>所有組件</color>的力量哦。",
  ui_story_7_14_X1_dialog_content = "有空跟著PlayerName來送死，不如回白夜城龜縮起來！",
  ui_story_7_14_22_dialog_content = "但妳突破不了白夜城的護盾，對吧？看來所謂的「補完」不過如此？",
  ui_story_7_14_23_dialog_content = "閉嘴，空裔。現在的黑色巨像還不完整……",
  ui_story_7_14_A2_dialog_content = "到時候我會給你們預留「頭等席位」的。",
  ui_story_7_14_X2_dialog_content = "（果然，她還沒有補完巨像……！）",
  ui_story_7_14_X3_dialog_content = "別用那種眼神看我，PlayerName。",
  ui_story_7_14_24_dialog_content = "在進攻白夜城的同時，我還親自過來處理你們，這已經是我耐心的極限了。",
  ui_story_7_14_25_dialog_content = "話說，小薇絲，PlayerName，這位暗鬼的實力這麼強大嗎？",
  ui_story_7_14_26_dialog_content = "雖說確實看上去很不好對付啦，但如果我們聯手的話也不一定吧？",
  ui_story_7_14_27_dialog_content = "如果能把希羅娜長官也叫回來，那是最好……",
  ui_story_7_14_28_dialog_content = "異想天開。現在就算把你們的聯軍都叫來，也不是「他」的對手……",
  ui_story_7_14_A3_dialog_content = "我的黑色巨像，現在正茁壯成長著呢……",
  ui_story_7_14_29_dialog_content = "不得不說，你們這副樂觀的樣子真讓人佩服。啟光的人都有這樣的盲目自信？",
  ui_story_7_14_30_dialog_content = "長話短說，舒默，不要徒增變數。",
  ui_story_7_14_31_dialog_content = "我知道，囉嗦死了。",
  ui_story_7_14_32_dialog_content = "……",
  ui_story_7_14_33_dialog_content = "怎麼了，長官？",
  ui_story_7_14_34_dialog_content = "舒默背後那個人……總覺得<color=#FFB400>很眼熟</color>。",
  ui_story_7_14_38_dialog_content = "喂，說什麼悄悄話呢，死前的遺言不大喊出來可是沒人聽得見的。",
  ui_story_7_14_39_dialog_content = "不過PlayerName，你是特別的……",
  ui_story_7_14_A4_dialog_content = "我知道你不會甘心做一個永遠匍匐在地上的弱者……你跟我一樣。",
  ui_story_7_14_40_dialog_content = "來吧，加入我們，走來正確的一方。",
  ui_story_7_14_41_dialog_content = "唯有如此你才能獲得改變命運的力量。",
  ui_story_7_14_42_dialog_content = "改變命運的力量？比如？",
  ui_story_7_14_43_dialog_content = "視野、壽命、資訊、強大的暗能和世界的真相。",
  ui_story_7_14_44_dialog_content = "最重要的是，你不必再擔心會被誰消滅了……只有你，消滅他們，你會成為凌駕一切的強者。",
  ui_story_7_14_46_dialog_content = "可以說快點嗎，我趕時間。",
  ui_story_7_14_47_dialog_content = "你……？",
  ui_story_7_14_48_dialog_content = "抱歉，我對妳說的話一點興趣都沒有。",
  ui_story_7_14_49_dialog_content = "妳就這麼喜歡把不明所以的話掛在嘴邊？妳知道自己在說什麼嗎？",
  ui_story_7_14_50_dialog_content = "「我最清醒」、「改變命運」、「我要成為強者是因為有人要消滅我」……",
  ui_story_7_14_51_dialog_content = "因為這種理由而去危害他人性命的傢伙就應該告別這個世界。",
  ui_story_7_14_52_dialog_content = "按照妳的說法，遇到弱者就消滅，遇到強者就跪下求饒，加入對方祈求力量？",
  ui_story_7_14_A5_dialog_content = "我無法理解，妳是怎麼堅信自己是對的？妳居然以為我想變得跟妳一樣？",
  ui_story_7_14_53_dialog_content = "總而言之，妳這種認為「天地之間我最正確」的傢伙……",
  ui_story_7_14_54_dialog_content = "應該去啟光或白夜城的診所看看大腦是不是進了澱粉與水的混合物吧。",
  ui_story_7_14_55_dialog_content = "…………",
  ui_story_7_14_56_dialog_content = "PlayerName……竟然一口氣說出了這麼多……",
  ui_story_7_14_57_dialog_content = "酣暢淋漓的話……？",
  ui_story_7_14_F1_dialog_content = "喔，對了。我還想問妳一句……妳是跪拜多久才得到力量的？",
  ui_story_7_14_58_dialog_content = "哈哈。",
  ui_story_7_14_59_dialog_content = "<size=50>哈哈哈，哈哈哈哈哈哈！！！</size>",
  ui_story_7_14_60_dialog_content = "你這臭魚爛蝦一樣的東西……愚蠢！不知好歹！",
  ui_story_7_14_61_dialog_content = "激怒我是想尋死嗎？想證明自己不怕死亡？我不會讓你如願的……",
  ui_story_7_14_63_dialog_content = "喔，終於打算動真格了。",
  ui_story_7_14_A6_dialog_content = "「力量」的成長果然需要憤怒催化。",
  ui_story_7_14_64_dialog_content = "我要將你留下，慢慢地折磨你，讓你體會沒有力量的屈辱！",
  ui_story_7_14_F2_dialog_content = "讓你知道我才是正確的！！",
  ui_story_7_14_65_dialog_content = "這句話應該我來說，<color=#FFB400>「空裔的叛徒」——舒默</color>！！",
  ui_story_7_14_66_dialog_content = "來啊！繼續啊！你們還在等什麼？！",
  ui_story_7_14_67_dialog_content = "太、太強了……這種力量……",
  ui_story_7_14_68_dialog_content = "……我還能動。準備再次發動攻擊！不能讓她活著離開……",
  ui_story_7_14_69_dialog_content = "理智一點！我們……需要另想辦法。",
  ui_story_7_14_70_dialog_content = "啊啊，雖然很不想承認，但PlayerName是對的……",
  ui_story_7_14_A7_dialog_content = "還好沒有帶其他人上來，否則也會一起被困在這裡吧？",
  ui_story_7_14_71_dialog_content = "現在啊，似乎連跑也跑不掉呢……",
  ui_story_7_14_72_dialog_content = "跑？！想離開嗎？可以啊，被我撕成碎片、再像紙屑一樣落下去怎麼樣？！",
  ui_story_7_14_73_dialog_content = "白夜城的天空會下起你們的血雨！",
  ui_story_7_14_74_dialog_content = "補完了，舒默。黑色巨像，現在已經「<color=#FFB400>完整</color>」了。",
  ui_story_7_14_75_dialog_content = "剛剛好，不是嗎？眼前這些牲畜，不就剛好可以拿來當新生的祭禮？！",
  ui_story_7_14_76_dialog_content = "那個……抱歉插嘴一下。但從剛才起我就一直在意……你到底是誰？",
  ui_story_7_14_77_dialog_content = "哈？！現在還不知道嗎？",
  ui_story_7_14_78_dialog_content = "你讓一下。我說的是背後，那隻……高級暗鬼。",
  ui_story_7_14_79_dialog_content = "……",
  ui_story_7_14_80_dialog_content = "不，與其說是暗鬼，你倒更像一個<color=#FFB400>光靈</color>。",
  ui_story_7_14_81_dialog_content = "？！光靈？",
  ui_story_7_14_82_dialog_content = "體型、氣息，和說話方式……直覺告訴我，你不是天生的暗鬼。",
  ui_story_7_14_83_dialog_content = "……直覺……無聊的根據。",
  ui_story_7_14_84_dialog_content = "<color=#FFB400>你是誰</color>，告訴我。我必須要知道。",
  ui_story_7_14_85_dialog_content = "我拒絕。",
  ui_story_7_14_86_dialog_content = "<size=45>告訴我！馬上！</size>",
  ui_story_7_14_87_dialog_content = "長官怎麼突然激動了起來……",
  ui_story_7_14_88_dialog_content = "我再次拒絕。因為……",
  ui_story_7_14_89_dialog_content = "我的名字，早就被「<color=#FFB400>剝奪</color>」了呀。",
  ui_story_7_14_90_dialog_content = "……",
  ui_story_7_14_91_dialog_content = "在這美好的世界，在「<color=#FFB400>啟明之光</color>」裡，一個沒有姓名的人要如何生活下去呢？",
  ui_story_7_14_92_dialog_content = "……你曾是啟光的一員。",
  ui_story_7_14_94_dialog_content = "我確實是。",
  ui_story_7_14_95_dialog_content = "看著我的臉，這些疤痕……這是被火燒過的痕跡，看見了嗎？",
  ui_story_7_14_97_dialog_content = "……",
  ui_story_7_14_F3_dialog_content = "怎麼樣……",
  ui_story_7_14_98_dialog_content = "想起什麼來了嗎？",
  ui_story_7_14_99_dialog_content = "……與其說是想起來，不如說是得到了證實。",
  ui_story_7_14_100_dialog_content = "嗅覺靈敏。這麼多年過去了，你的洞察力依然絲毫不減……",
  ui_story_7_14_101_dialog_content = "長官？你們……認識？",
  ui_story_7_14_102_dialog_content = "何止是認識，PlayerName……",
  ui_story_7_14_103_dialog_content = "你面前這個助紂為虐的高級暗鬼，曾經……是<color=#FFB400>啟光裡的同伴</color>！",
  ui_story_7_14_104_dialog_content = "有什麼好意外的？",
  ui_story_7_14_A8_dialog_content = "倒是你，<color=#FFB400>吞羅</color>，平時一直說我囉嗦，現在又和這群蟑螂聊天是什麼意思？",
  ui_story_7_14_105_dialog_content = "<color=#FFB400>吞羅</color>……？",
  ui_story_7_14_109_dialog_content = "簡單閒話家常。好了，我的部分結束了，你隨意發揮吧。",
  ui_story_7_14_110_dialog_content = "順帶一提……黑色巨像補完後，可是有大量能量發洩不出去呢。",
  ui_story_7_14_A9_dialog_content = "找個配得上自己的對手吧。",
  ui_story_7_14_111_dialog_content = "面前這座城市，不就很合適嗎？",
  ui_story_7_14_112_dialog_content = "傲慢，腐朽，以為護盾牢不可破——我今天就要讓光靈的信仰崩塌！",
  ui_story_7_14_113_dialog_content = "不會讓你得逞！白夜城永不淪陷，區區暗鬼怎麼可能……",
  ui_story_7_14_114_dialog_content = "<size=45>閉上你的嘴，光靈！！</size>",
  ui_story_7_14_115_dialog_content = "來吧……我親愛的巨像！",
  ui_story_7_14_116_dialog_content = "你巨大的身軀和血紅的眼睛會讓他們瑟瑟發抖！",
  ui_story_7_14_117_dialog_content = "看見了嗎？！黑色巨像？黑龍？不，這都不是他的名字。",
  ui_story_7_14_118_dialog_content = "對！就是這樣！跪伏、膜拜！這就是我的——<size=45><color=#FFB400>「吞噬者號」</color></size>！！",
  ui_story_7_14_119_dialog_content = "那是什麼？巨像嗎？！……她，做了什麼？！PlayerName、解釋一下！",
  ui_story_7_14_120_dialog_content = "就算你問我我也不知道！",
  ui_story_7_14_121_dialog_content = "光能……在流逝？不行，我們不能坐以待斃！",
  ui_story_7_14_122_dialog_content = "動不了……大家，有辦法移動嗎？",
  ui_story_7_14_123_dialog_content = "……各位注意，我會為你們爭取時間。",
  ui_story_7_14_128_dialog_content = "南方是薄弱處，往那邊逃。直接跳下去還有一線生機。",
  ui_story_7_14_129_dialog_content = "再會了，小薇絲，PlayerName，還有卡蓮妹妹～",
  ui_story_7_14_130_dialog_content = "長官？！妳……",
  ui_story_7_14_131_dialog_content = "<size=50>休想——！！</size>",
  ui_story_7_14_133_dialog_content = "（到底……）",
  ui_story_7_14_134_dialog_content = "（發生了什麼……）",
  ui_story_8_1_1_1_dialog_content = "PlayerName？你在看哪裡呢？",
  ui_story_8_1_1_2_dialog_content = "不跟上我可是會走丟的哦。",
  ui_story_8_1_1_3_dialog_content = "快來，牽著我的手。",
  ui_story_8_1_1_4_dialog_content = "幹嘛一臉疑惑啊？我們不是說好一起來參加白夜城的盛會嗎？",
  ui_story_8_1_1_5_dialog_content = "那邊有小吃攤！去看看吧？",
  ui_story_8_1_1_6_option_content = "這……是哪？",
  ui_story_8_1_1_7_dialog_content = "你真的忘啦，這裡是白夜城啊。",
  ui_story_8_1_1_8_option_content = "發生了什麼事？",
  ui_story_8_1_1_9_dialog_content = "還能發生什麼？這可是一年一度的節日，大家當然要慶祝啦！",
  ui_story_8_1_1_10_dialog_content = "你到底怎麼啦～該不會在戲弄我吧？",
  ui_story_8_1_1_11_dialog_content = "那樣我可是會生氣的喔！像這樣，唔——超、生、氣！",
  ui_story_8_1_1_12_option_content = "薇絲你怪怪的",
  ui_story_8_1_1_13_dialog_content = "有嗎？我哪裡怪怪的啦～我還是你的小薇絲呀！",
  ui_story_8_1_1_14_dialog_content = "別想那麼多，快過來。你再這樣我真的要生氣了！",
  ui_story_8_1_1_15_option_content = "……你是誰？",
  ui_story_8_1_1_16_dialog_content = "……啊？我是薇絲啊，還會是誰？",
  ui_story_8_1_1_17_dialog_content = "幹嘛問這麼奇怪的問題！快過來，你再這樣我真的要生氣了！",
  ui_story_8_1_1_18_dialog_content = "……",
  ui_story_8_1_1_19_dialog_content = "什麼聲音……？",
  ui_story_8_1_1_20_dialog_content = "嗯？你聽到什麼了？",
  ui_story_8_1_1_21_dialog_content = "這裡不太對，薇絲。我感覺很不舒服，就好像……",
  ui_story_8_1_1_22_dialog_content = "是錯覺，PlayerName。和我在一起還不放心嗎？你要相信我。",
  ui_story_8_1_1_23_dialog_content = "就算……你的問題再多，我也會全部回答的。但請先握住我的手，好嗎？",
  ui_story_8_1_1_24_dialog_content = "我會告訴你的，我會全部告訴你的……",
  ui_story_8_1_1_25_dialog_content = "……PlayerName。",
  ui_story_8_1_1_26_dialog_content = "過去、未來，你想知道的一切……",
  ui_story_8_1_1_27_dialog_content = "讓我們一起，迎接「明天」！",
  ui_story_8_1_1_28_dialog_content = "別丟下我一個人……我們說好了，不是嗎？",
  ui_story_8_1_1_29_dialog_content = "……這都聽不到？您睡得也太死了，PlayerName！",
  ui_story_8_1_1_30_option_content = "好，我絕不會離開你",
  ui_story_8_1_1_31_dialog_content = "太好了！你終於瞭解了，接納了……那就說好，永遠不要離開……",
  ui_story_8_1_1_32_dialog_content = "放下空裔的軀殼，去擁抱真正的力量！",
  ui_story_8_1_1_33_option_content = "我要走了，妳不是薇絲。",
  ui_story_8_1_1_34_dialog_content = "回來！回來、回來、回來！愚蠢的空裔！！",
  ui_story_8_1_1_35_dialog_content = "這是多少人夢寐以求的機會，你知道嗎？！愚蠢、蠢到可憐、可悲！",
  ui_story_8_1_1_36_dialog_content = "跟著我的聲音，從這危險又香甜的幻境走出來吧……",
  ui_story_8_1_1_37_dialog_content = "來，跟隨「舊夢」的指引，它會告訴你何為真實……",
  ui_story_8_1_1_38_dialog_content = "居——！！",
  ui_story_8_1_1_39_dialog_content = "（唔——！好痛，那是什麼東西？！）",
  ui_story_8_1_1_42_dialog_content = "（什麼東西從我的身體裡飛出去了？！）",
  ui_story_8_1_1_43_dialog_content = "（那是什麼？為什麼會……）",
  ui_story_8_1_1_44_dialog_content = "吼——！",
  ui_story_8_1_1_45_dialog_content = "居——！！",
  ui_story_8_1_1_47_dialog_content = "啊、你是——「居里」！薇薇安身邊的！",
  ui_story_8_1_1_48_dialog_content = "居！！！",
  ui_story_8_1_1_49_dialog_content = "你的主人呢？……還有薇絲呢？",
  ui_story_8_1_1_50_dialog_content = "剛才那個，難不成是從我身體裡……那到底是什麼……",
  ui_story_8_1_1_51_dialog_content = "唔，頭有點痛……嘶、這也太痛了，難道之前撞到腦袋了嗎？",
  ui_story_8_1_1_52_dialog_content = "居！",
  ui_story_8_1_1_53_dialog_content = "可憐的小傢伙，你怎麼全身都是傷……你也跟大家走散了吧？",
  ui_story_8_1_1_54_dialog_content = "也不知道大家怎麼樣了……",
  ui_story_8_1_1_55_dialog_content = "休想——！！",
  ui_story_8_1_1_58_dialog_content = "疼疼疼……那之後的事情完全想不起來了。",
  ui_story_8_1_1_59_dialog_content = "不知道薇絲她們的情況怎麼樣了……",
  ui_story_8_1_1_60_dialog_content = "PlayerName！",
  ui_story_8_1_1_61_dialog_content = "薇絲？！",
  ui_story_8_1_1_62_dialog_content = "噓！是我，你先小點聲……",
  ui_story_8_1_1_63_dialog_content = "你還好嗎？這裡到處都是暗能的氣息！我剛才……",
  ui_story_8_1_1_64_dialog_content = "我知道，我很好，你放心吧！你呢？你怎麼樣，讓我看看有沒有受傷！",
  ui_story_8_1_1_65_option_content = "我感覺不太好",
  ui_story_8_1_1_66_dialog_content = "我感覺……不太好。應該沒受傷，但總覺得整個身體非常……沉重。",
  ui_story_8_1_1_67_dialog_content = "好像連腦子都有點不清楚……這到底是什麼鬼地方？",
  ui_story_8_1_1_68_dialog_content = "……你不知道嗎？這裡是「吞噬者號」的內部，PlayerName。",
  ui_story_8_1_1_69_option_content = "我不知道",
  ui_story_8_1_1_70_dialog_content = "……我不知道，我剛醒來……對，我做了個夢，噩夢！夢裡面……",
  ui_story_8_1_1_71_dialog_content = "嗯，有妳，可妳又不太像妳……不不不那肯定不是妳。",
  ui_story_8_1_1_F1_dialog_content = "對了，好像還有另一個傢伙……",
  ui_story_8_1_1_72_dialog_content = "一個夢？你夢到我了？又不太像我？另一個傢伙是誰？",
  ui_story_8_1_1_F2_dialog_content = "我也不太清楚是怎麼回事……抱歉。",
  ui_story_8_1_1_73_dialog_content = "那……然後呢？你醒過來就在這裡了嗎？",
  ui_story_8_1_1_F3_dialog_content = "我……對，醒過來就在這。",
  ui_story_8_1_1_74_dialog_content = "好吧，也許是暗能干擾你的腦袋。畢竟這裡是「吞噬者號」內部……",
  ui_story_8_1_1_75_option_content = "這到底是哪裡？",
  ui_story_8_1_1_76_dialog_content = "這裡是「吞噬者號」內部。",
  ui_story_8_1_1_77_dialog_content = "我也是第一次看到這種型態的巨像。不，這已經不能稱作巨像了……",
  ui_story_8_1_1_78_dialog_content = "看，到處都是暗能侵蝕的痕跡。這裡簡直是暗鬼的樂土。",
  ui_story_8_1_1_79_dialog_content = "我來的路上也遇到很多暗鬼，希望沒有用出太大的動靜……",
  ui_story_8_1_1_80_dialog_content = "等等等等……你剛才說……",
  ui_story_8_1_1_81_dialog_content = "這裡是吞噬者號內部？？",
  ui_story_8_1_1_82_dialog_content = "對。我打探到你被舒默抓來這兒了，然後……",
  ui_story_8_1_1_83_dialog_content = "然後我就跟著進來了。",
  ui_story_8_1_1_84_dialog_content = "啊？！你為什麼要跟進來？太危險了！",
  ui_story_8_1_1_88_dialog_content = "為了救你呀！你推了我們一把，自己卻留在臨空者號上，我怎麼能……",
  ui_story_8_1_1_89_dialog_content = "等一下等一下……到底發生了什麼事？",
  ui_story_8_1_1_90_dialog_content = "不，應該說不管發生什麼你都不該一個人來這裡！太危險了！！",
  ui_story_8_1_1_91_dialog_content = "我知道！但總不能什麼都不做吧？！",
  ui_story_8_1_1_92_dialog_content = "一想到你可能還活著，一想到……我還能做點什麼……",
  ui_story_8_1_1_93_dialog_content = "我明白你的意思，薇絲。可是……",
  ui_story_8_1_1_94_dialog_content = "現在說這些都沒有用了，PlayerName，我已經來了！",
  ui_story_8_1_1_95_dialog_content = "接下來就是一起想辦法釐清狀況！打起精神！",
  ui_story_8_1_1_96_dialog_content = "居！",
  ui_story_8_1_1_97_dialog_content = "居里你倒是說說薇絲呀……唉。",
  ui_story_8_1_1_98_dialog_content = "所以到底發生了什麼事？我已經不記得了，一思考腦子就嗡嗡地痛起來……",
  ui_story_8_1_1_99_dialog_content = "先動起來！別停在這裡發呆，我們邊走邊說。",
  ui_story_8_1_1_100_dialog_content = "當時薇薇安長官讓我們趁機離開，然後舒默……",
  ui_story_8_1_1_101_dialog_content = "……各位注意，我會為你們爭取時間。",
  ui_story_8_1_1_103_dialog_content = "六點鐘方向是薄弱處，往那邊逃。直接跳下去還有一線生機。",
  ui_story_8_1_1_104_dialog_content = "再會了，小薇絲，PlayerName，還有卡蓮妹妹～",
  ui_story_8_1_1_105_dialog_content = "長官？！妳……",
  ui_story_8_1_1_106_dialog_content = "休想——！！",
  ui_story_8_1_1_107_dialog_content = "你的對手是我！！",
  ui_story_8_1_1_108_dialog_content = "出乎我意料之外……很能打呢，你這混蛋！",
  ui_story_8_1_1_109_dialog_content = "……",
  ui_story_8_1_1_110_dialog_content = "那就姑且稍微再認真一點吧……真讓人不爽……",
  ui_story_8_1_1_111_dialog_content = "還有那邊！偷偷摸摸，想跑哪裡去？！",
  ui_story_8_1_1_112_dialog_content = "快！往、往下跳！",
  ui_story_8_1_1_113_dialog_content = "這高度……但也沒得選了！走吧！",
  ui_story_8_1_1_114_dialog_content = "拉住我的手，我們一起……",
  ui_story_8_1_1_115_dialog_content = "吼——！",
  ui_story_8_1_1_116_dialog_content = "放開我！",
  ui_story_8_1_1_117_dialog_content = "PlayerName！！",
  ui_story_8_1_1_118_dialog_content = "（要被拉回去了！！）",
  ui_story_8_1_1_119_dialog_content = "使不出力……怎麼辦，必須一起走……",
  ui_story_8_1_1_120_dialog_content = "……",
  ui_story_8_1_1_121_option_content = "你們快走！",
  ui_story_8_1_1_122_dialog_content = "？！",
  ui_story_8_1_1_123_dialog_content = "PlayerName！",
  ui_story_8_1_1_124_dialog_content = "這、太高了！！會摔死的！",
  ui_story_8_1_1_125_dialog_content = "穩住身體，薇絲！至少在落地的時候……",
  ui_story_8_1_1_126_dialog_content = "卡——蓮——姐——姐——！！",
  ui_story_8_1_1_127_dialog_content = "接住了！！",
  ui_story_8_1_1_128_dialog_content = "拉斐爾……？妳為什麼……唔，好痛！",
  ui_story_8_1_1_129_dialog_content = "這艘空艇……卡蓮，你叫了救兵？",
  ui_story_8_1_1_130_dialog_content = "嘿嘿……怎麼說呢，算是救兵吧！拉斐爾確實是來接應你們的！",
  ui_story_8_1_1_131_dialog_content = "還好及時趕到呢……要是再晚兩秒鐘……",
  ui_story_8_1_1_132_dialog_content = "咿——",
  ui_story_8_1_1_133_dialog_content = "什麼聲音？",
  ui_story_8_1_1_134_dialog_content = "欸？好像是從我屁股下面……",
  ui_story_8_1_1_135_dialog_content = "居——！！",
  ui_story_8_1_1_136_dialog_content = "居里？！",
  ui_story_8_1_1_137_dialog_content = "抱歉抱歉！剛才壓到你了吧！",
  ui_story_8_1_1_138_dialog_content = "居！",
  ui_story_8_1_1_139_dialog_content = "這是小薇絲的寵物嗎？",
  ui_story_8_1_1_140_dialog_content = "不，是薇薇安長官的。",
  ui_story_8_1_1_141_dialog_content = "喔？那位長官呢？好像還有一個空裔吧？",
  ui_story_8_1_1_142_dialog_content = "他們……",
  ui_story_8_1_1_143_dialog_content = "……",
  ui_story_8_1_1_144_dialog_content = "拉斐爾，現在不是討論這些的時候。事態有變，我們盡快回去向城主報告。",
  ui_story_8_1_1_145_dialog_content = "PlayerName好不容易為我們爭取脫身的機會，我們不能浪費……",
  ui_story_8_1_1_146_dialog_content = "必須想辦法反擊。",
  ui_story_8_1_1_147_dialog_content = "卡蓮，你有什麼打算？",
  ui_story_8_1_1_148_dialog_content = "回去說服那個男人，使用「達摩克利斯」。",
  ui_story_8_1_1_149_dialog_content = "？！",
  ui_story_8_1_1_150_dialog_content = "只有那個可以對付舒默了。這是唯一的辦法。",
  ui_story_8_1_1_151_dialog_content = "可是已經十年沒啟動過「達摩克利斯」了？殿下會同意嗎？",
  ui_story_8_1_1_152_dialog_content = "我會讓他同意的。能阻止吞噬者號的，只有它了。",
  ui_story_8_1_1_153_dialog_content = "可是PlayerName……",
  ui_story_8_1_1_154_dialog_content = "這關乎整個白夜城的存亡。我別無選擇……我們都別無選擇，薇絲。",
  ui_story_8_1_1_155_dialog_content = "……",
  ui_story_8_1_1_156_dialog_content = "怎麼了？你要做什麼？",
  ui_story_8_1_1_157_dialog_content = "你……難道想回到臨空者號上去嗎？",
  ui_story_8_1_1_158_dialog_content = "對……",
  ui_story_8_1_1_159_dialog_content = "對不起，卡蓮。我沒辦法拋下PlayerName，還有薇薇安長官。",
  ui_story_8_1_1_160_dialog_content = "薇絲，妳……",
  ui_story_8_1_1_161_dialog_content = "我明白你的想法，卡蓮！但拋下夥伴，我做不到，我真的做不到……",
  ui_story_8_1_1_162_dialog_content = "冷靜一點，薇絲。現在回去很危險！",
  ui_story_8_1_1_164_dialog_content = "難道你要浪費掉PlayerName拼命換來的契機嗎？",
  ui_story_8_1_1_165_dialog_content = "我明白這有多危險，卡蓮！我……我自己會想辦法。",
  ui_story_8_1_1_166_dialog_content = "什麼辦法？空艇只有一艘！",
  ui_story_8_1_1_167_dialog_content = "對、對啊……",
  ui_story_8_1_1_168_dialog_content = "小薇絲也不會飛吧……要不然還是先……",
  ui_story_8_1_1_169_dialog_content = "……",
  ui_story_8_1_1_170_dialog_content = "居里……拜託你了。",
  ui_story_8_1_1_171_dialog_content = "居？",
  ui_story_8_1_1_172_dialog_content = "……居？！",
  ui_story_8_1_1_173_dialog_content = "我可以和居里一起回去。",
  ui_story_8_1_1_174_dialog_content = "你確定那傢伙載得動你嗎？",
  ui_story_8_1_1_175_dialog_content = "卡蓮，雖然我的體重有點……但是居里很強！",
  ui_story_8_1_1_176_dialog_content = "居！",
  ui_story_8_1_1_177_dialog_content = "我明白的，居里。你也很想回去救自己的主人吧？",
  ui_story_8_1_1_180_dialog_content = "你們要出發的話，就是現在。從這裡回去距離還不算太遠。",
  ui_story_8_1_1_181_dialog_content = "卡蓮……",
  ui_story_8_1_1_182_dialog_content = "我知道勸不動你，就像你也勸不動我一樣。我們都會遵從自己的理念行動。",
  ui_story_8_1_1_183_dialog_content = "但你要明白一點……到目前為止，你的「運氣」都還不錯。",
  ui_story_8_1_1_184_dialog_content = "無論是啟動臨空者逃生，還是以身犯險救出貢露。",
  ui_story_8_1_1_185_dialog_content = "但萬一……你這次的天真行為不再受到「運氣」眷顧呢？",
  ui_story_8_1_1_186_dialog_content = "……我相信PlayerName。我相信我們能再次一起脫困。",
  ui_story_8_1_1_187_dialog_content = "我相信只要努力，就一定會出現奇蹟。",
  ui_story_8_1_1_188_dialog_content = "有時候我真的很佩服你的樂觀，薇絲。",
  ui_story_8_1_1_189_dialog_content = "你走吧。我還得說服一個老頑固，就不與你同行了。",
  ui_story_8_1_1_190_dialog_content = "照顧好那個空裔，薇絲！",
  ui_story_8_1_1_191_dialog_content = "妳也要小心，卡蓮！如果真能啟動那個，一定能讓舒默吃點苦頭！",
  ui_story_8_1_1_192_dialog_content = "何止是吃點苦頭。我只希望到時候你們來得及脫身。",
  ui_story_8_1_1_193_dialog_content = "那就待會兒見了，卡蓮。",
  ui_story_8_1_1_194_dialog_content = "待會兒見，薇絲。",
  ui_story_8_1_1_195_dialog_content = "（日蝕語）那邊的，也拆下來。動作快。",
  ui_story_8_1_1_196_dialog_content = "（日蝕語）只要是有用處的統統拆掉！主人補完後的巨像需要大量建材！",
  ui_story_8_1_1_197_dialog_content = "（日蝕語）喂！有沒有聽到？！",
  ui_story_8_1_1_198_dialog_content = "……嘎？！",
  ui_story_8_1_1_200_dialog_content = "別叫了。這個房間就剩你一個了。其他暗鬼呢？都離開臨空者號了嗎？",
  ui_story_8_1_1_201_dialog_content = "把PlayerName心愛的家拆成這樣，我絕對不會原諒你們的！",
  ui_story_8_1_1_202_dialog_content = "（日蝕語）光……光靈……雜碎，必須通知大人…",
  ui_story_8_1_1_203_dialog_content = "抱歉，我本應該給你個痛快，但我有必須要問的事。",
  ui_story_8_1_1_204_dialog_content = "唔嘎——？！",
  ui_story_8_1_1_205_dialog_content = "我知道你可能聽不懂我的話，但是……",
  ui_story_8_1_1_206_dialog_content = "有兩個很重要的人，PlayerName和薇薇安長官，我需要知道他們的下落。",
  ui_story_8_1_1_207_dialog_content = "（日蝕語）你是那個空裔的同伴嗎？他不是逃掉了嗎？愚蠢的女人……",
  ui_story_8_1_1_208_dialog_content = "聽不懂。唉，簡直是浪費時間……",
  ui_story_8_1_1_209_dialog_content = "如果你不會通用語……對了，紙和筆！",
  ui_story_8_1_1_210_dialog_content = "？",
  ui_story_8_1_1_211_dialog_content = "只要畫出來……",
  ui_story_8_1_1_212_dialog_content = "這個人……在哪",
  ui_story_8_1_1_213_dialog_content = "（日蝕語）……果然是為了那個空裔而來的！",
  ui_story_8_1_1_214_dialog_content = "（日蝕語）我記得那個空裔在……不對。",
  ui_story_8_1_1_215_dialog_content = "喂，你在看哪個地方？",
  ui_story_8_1_1_216_dialog_content = "（日蝕語）怎麼可能告訴妳！垃圾、螻蟻，還想繼續阻礙大人的計……",
  ui_story_8_1_1_217_dialog_content = "嗚啊……！",
  ui_story_8_1_1_218_dialog_content = "吞噬者號……的方向嗎",
  ui_story_8_1_1_219_dialog_content = "居、居……",
  ui_story_8_1_1_220_dialog_content = "你還好嗎？還有體力嗎？之前抓著我飛這麼遠，很辛苦吧。",
  ui_story_8_1_1_221_dialog_content = "居……！",
  ui_story_8_1_1_222_dialog_content = "還有體力就好……很抱歉，但可能要再拜託你一次了。",
  ui_story_8_1_1_223_dialog_content = "我們得飛到吞噬者號上去！PlayerName和薇薇安長官恐怕都在那！",
  ui_story_8_1_1_224_dialog_content = "居？！",
  ui_story_8_1_1_225_dialog_content = "所以……你們就潛了進來？居然能用這種方法？",
  ui_story_8_1_1_226_dialog_content = "這過程聽起來可能有點難以置信，但真的是全靠著居里我才能過來的。",
  ui_story_8_1_1_227_dialog_content = "居……",
  ui_story_8_1_1_228_dialog_content = "這傢伙已經一副快累死的樣子了。",
  ui_story_8_1_1_229_dialog_content = "真的是辛苦居里了，回去我一定好好慰勞他！",
  ui_story_8_1_1_230_option_content = "那就趕快離開這裡吧",
  ui_story_8_1_1_231_dialog_content = "居！",
  ui_story_8_1_1_232_dialog_content = "我們還沒找到薇薇安長官，PlayerName。",
  ui_story_8_1_1_233_dialog_content = "如果你還有體力，我希望你能和我一起繼續深入……",
  ui_story_8_1_1_234_dialog_content = "把長官也救出來！",
  ui_story_8_1_1_235_option_content = "可是我沒看到薇薇安長官",
  ui_story_8_1_1_236_dialog_content = "居……",
  ui_story_8_1_1_237_dialog_content = "我認為長官也被抓到這裡來了，所以我們接下來要去找薇薇安長官。",
  ui_story_8_1_1_238_dialog_content = "無論舒默她們有什麼打算，我們都絕對不能拋下長官！",
  ui_story_8_1_1_239_dialog_content = "很有可能，我現在狀態還不錯，我們一起行動吧。",
  ui_story_8_1_1_240_dialog_content = "好，我們繼續深入！",
  ui_story_8_1_1_241_dialog_content = "居！",
  ui_story_8_2_1_1_dialog_content = "老師，對不起……可以再表演一遍嗎？",
  ui_story_8_2_1_2_dialog_content = "我又感應失敗了，果然還是不太會……",
  ui_story_8_2_1_3_dialog_content = "老師？老師？",
  ui_story_8_2_1_4_dialog_content = "喂？",
  ui_story_8_2_1_5_dialog_content = "你又神遊到哪裡去了？",
  ui_story_8_2_1_6_dialog_content = "……",
  ui_story_8_2_1_7_dialog_content = "集中精神。馬上就能證明給他看了呢，對吧？",
  ui_story_8_2_1_8_dialog_content = "你廢話太多了。",
  ui_story_8_2_1_9_dialog_content = "我做事情不需要你嘰嘰喳喳地講解。",
  ui_story_8_2_1_10_dialog_content = "哦。",
  ui_story_8_2_1_11_dialog_content = "……",
  ui_story_8_2_1_12_dialog_content = "我留PlayerName一命，不是為了什麼無聊的「證明」，吞羅。",
  ui_story_8_2_1_13_dialog_content = "我……",
  ui_story_8_2_1_14_dialog_content = "……我覺得解釋了你也不懂。",
  ui_story_8_2_1_15_dialog_content = "其實跟你留著那個啟光的傢伙道理是一樣的。",
  ui_story_8_2_1_16_dialog_content = "不一樣。我跟你太不一樣了。",
  ui_story_8_2_1_17_dialog_content = "畢竟我早跟啟光無關了，但你還是個空裔，哈。",
  ui_story_8_2_1_18_dialog_content = "你想死嗎？！說誰是空裔？！",
  ui_story_8_2_1_19_dialog_content = "別激動，我沒打算繼續這場對話。無趣。",
  ui_story_8_2_1_20_dialog_content = "神經病！",
  ui_story_8_2_1_21_dialog_content = "走了。",
  ui_story_8_2_1_22_dialog_content = "你要去哪裡？",
  ui_story_8_2_1_23_dialog_content = "我已經幫你賜予那傢伙「同樣的力量」，相信你們很快就能再次變成「同胞」。",
  ui_story_8_2_1_24_dialog_content = "什麼意思？我沒要你那麼做吧？",
  ui_story_8_2_1_25_dialog_content = "嘖，莫名其妙！",
  ui_story_8_2_1_26_dialog_content = "這傢伙到底來幹嘛的？從見面第一天就是這副鬼樣子！",
  ui_story_8_2_1_27_dialog_content = "不幫忙就算了，還在我集中精力對付白夜城的時候找麻煩……",
  ui_story_8_2_1_28_dialog_content = "舒默，我奉吞羅大人之命留下協助你……",
  ui_story_8_2_1_29_dialog_content = "但也希望你注意對大人的言辭。",
  ui_story_8_2_1_30_dialog_content = "……呵。看來也不是完全撒手不管嘛。",
  ui_story_8_2_1_31_dialog_content = "這個地方的狀況……簡直一片混沌……",
  ui_story_8_2_1_32_dialog_content = "PlayerName？怎麼樣，成功了嗎？",
  ui_story_8_2_1_33_dialog_content = "已經成功了。我感應到這座巨像，但……無法理解他。",
  ui_story_8_2_1_F1_dialog_content = "不，不是我無法理解他……",
  ui_story_8_2_1_34_dialog_content = "而是這座巨像根本沒有屬於自己的意識模組。一片空白。",
  ui_story_8_2_1_35_dialog_content = "小心點，或許會觸發警報……",
  ui_story_8_2_1_36_dialog_content = "沒關係，薇絲，我很小心。",
  ui_story_8_2_1_37_dialog_content = "而且我只是透過感應他來阻止可能觸發的警報，可以隱藏我們的行蹤。",
  ui_story_8_2_1_F2_dialog_content = "感應能力還可以做到這種事嗎？",
  ui_story_8_2_1_F3_dialog_content = "嗯，自從學會用感應「潛入」之後……總之就是能透過小幅度的感應做些事。",
  ui_story_8_2_1_38_dialog_content = "能感應到薇薇安長官的位置嗎？",
  ui_story_8_2_1_F4_dialog_content = "抱歉，我不敢貿然加強感應。",
  ui_story_8_2_1_F5_dialog_content = "這裡是吞噬者號的內部，所以能夠直接透過接觸來感應……",
  ui_story_8_2_1_39_dialog_content = "但如果直接以感應能力大範圍搜尋，恐怕會被舒默發現。",
  ui_story_8_2_1_40_dialog_content = "瞭解。果然還是要靠我們自己找嗎……",
  ui_story_8_2_1_41_dialog_content = "你的狀態怎麼樣？能適應這裡的暗能量嗎？",
  ui_story_8_2_1_42_dialog_content = "嗯，完全沒問題。頭已經不痛了。",
  ui_story_8_2_1_43_dialog_content = "甚至可說更有精神了……好像睡了很長的一覺……",
  ui_story_8_2_1_44_dialog_content = "是嗎？奇怪……之前在低語迴廊的時候，你明明無法適應暗能……",
  ui_story_8_2_1_45_dialog_content = "居！",
  ui_story_8_2_1_46_dialog_content = "居里！你嗅到什麼了？",
  ui_story_8_2_1_47_dialog_content = "哈啾！",
  ui_story_8_2_1_48_dialog_content = "居……",
  ui_story_8_2_1_49_dialog_content = "暗能太濃郁，連居里都有點受不了了……",
  ui_story_8_2_1_50_dialog_content = "您的動作也太慢了。",
  ui_story_8_2_1_51_dialog_content = "你是……？！",
  ui_story_8_2_1_52_dialog_content = "您用的時間比預期更長，不過這並不妨礙命運之輪轉動如常。",
  ui_story_8_2_1_53_dialog_content = "空裔，這邊走，您想要的就在這條走廊的盡頭……",
  ui_story_8_2_1_54_dialog_content = "你到底是誰？光靈還是暗鬼？",
  ui_story_8_2_1_55_dialog_content = "噓……那不重要。重要的是將會發生的事，和我們都在苦苦搜尋的……",
  ui_story_8_2_1_56_dialog_content = "真理。",
  ui_story_8_2_1_57_dialog_content = "PlayerName，你怎麼了？臉色突然變得好差？",
  ui_story_8_2_1_58_dialog_content = "我、我看到了奇怪的東西……",
  ui_story_8_2_1_59_dialog_content = "有個身穿白衣、提著箱子的男人，告訴我……往那邊走。",
  ui_story_8_2_1_60_dialog_content = "欸？哪有男人？",
  ui_story_8_2_1_F6_dialog_content = "這……或許是我感應到的……他說往那邊走，好像可以信任。",
  ui_story_8_2_1_F7_dialog_content = "那邊的話……光是這樣說也不太清楚該走哪邊吧？",
  ui_story_8_2_1_61_dialog_content = "唔，雖然我不太熟悉吞噬者號的內部結構，但結合目前為止走過的路徑……",
  ui_story_8_2_1_62_dialog_content = "嗯，我簡單畫個地圖吧！",
  ui_story_8_2_1_63_dialog_content = "剛好那張紙還可以用……",
  ui_story_8_2_1_64_dialog_content = "薇絲，妳這紙上畫簡筆畫的是？",
  ui_story_8_2_1_65_dialog_content = "沒什麼！這、什麼也不是！",
  ui_story_8_2_1_66_dialog_content = "這紙上畫的小人……",
  ui_story_8_2_1_68_dialog_content = "我、我是為了向那些傢伙打聽你在哪裡！",
  ui_story_8_2_1_F8_dialog_content = "畫的原來是我？",
  ui_story_8_2_1_69_dialog_content = "我承認，難看是難看了點……但是，這圖還是有用的！",
  ui_story_8_2_1_70_dialog_content = "言歸正傳！趁還記得住，我得把現在探明的路線畫下來……",
  ui_story_8_2_1_72_dialog_content = "（暗鬼竟然能看懂這種圖……）",
  ui_story_8_2_1_73_dialog_content = "在這裡……再畫上比例尺，然後……",
  ui_story_8_2_1_74_dialog_content = "好了！",
  ui_story_8_2_1_75_dialog_content = "（就算她畫出了很抽象的地圖也不能笑，畢竟是她辛辛苦苦畫的……）",
  ui_story_8_2_1_76_dialog_content = "畫得超好！！這是工程結構圖了吧？！",
  ui_story_8_2_1_77_dialog_content = "還行吧，因為時間緊湊，只能簡單畫畫。",
  ui_story_8_2_1_78_dialog_content = "簡單畫畫？！明明畫人像畫成那樣，畫地圖卻已經達到這種境界？！",
  ui_story_8_2_1_79_dialog_content = "我跟你說過吧，我在啟光學的就是這些東西哦。",
  ui_story_8_2_1_80_dialog_content = "而且臨空者的維護與檢修也需要這些知識。",
  ui_story_8_2_1_81_dialog_content = "居！",
  ui_story_8_2_1_82_dialog_content = "居里，你怎麼了！",
  ui_story_8_2_1_83_dialog_content = "居！居！",
  ui_story_8_2_1_84_dialog_content = "這邊嗎？這個方向……",
  ui_story_8_2_1_85_dialog_content = "不就是那個男人指出的方向嗎……？",
  ui_story_8_2_1_86_dialog_content = "它應該嗅到長官的氣息了！走吧，PlayerName！",
  ui_story_8_2_1_87_dialog_content = "（看來那個男人，不是敵人……？）",
  ui_story_8_2_1_88_dialog_content = "前面一定有更多暗鬼，讓我們快速解決掉它們吧！",
  ui_story_8_2_1_89_dialog_content = "準備戰鬥——！",
  ui_story_8_2_2_1_dialog_content = "<color=#e8d9bb>白夜城上城區·高庭</color>",
  ui_story_8_2_2_2_dialog_content = "你要啟用……",
  ui_story_8_2_2_3_dialog_content = "……達摩克利斯？",
  ui_story_8_2_2_5_dialog_content = "沒錯。根據目前的情況，這是唯一的解決方案！",
  ui_story_8_2_2_6_dialog_content = "卡蓮，你知道自己在說什麼嗎？",
  ui_story_8_2_2_7_dialog_content = "啟動那東西必須透過三方決議！且不論需要的流程……",
  ui_story_8_2_2_F1_dialog_content = "你知道那東西會吃掉多少能源嗎？！",
  ui_story_8_2_2_8_dialog_content = "它會吸光維持護盾所需的全部能量！甚至連白夜城都會停擺！",
  ui_story_8_2_2_9_dialog_content = "……我知道。",
  ui_story_8_2_2_10_dialog_content = "我看你是腦袋摔壞了吧！",
  ui_story_8_2_2_11_dialog_content = "奧托。",
  ui_story_8_2_2_12_dialog_content = "……哼。",
  ui_story_8_2_2_13_dialog_content = "城主殿下，您沒有親眼目睹舒默和黑色巨像的威力，但我是從上面……逃下來的！",
  ui_story_8_2_2_14_dialog_content = "沒人能阻擋補完後的黑色巨像，再加上她現在還有同夥！",
  ui_story_8_2_2_15_dialog_content = "我們必須背水一戰！護盾無法永遠庇護我們，它遲早會被沖破……",
  ui_story_8_2_2_16_dialog_content = "你受傷了嗎？",
  ui_story_8_2_2_17_dialog_content = "欸？",
  ui_story_8_2_2_18_dialog_content = "你受傷了嗎，卡蓮？",
  ui_story_8_2_2_19_dialog_content = "拉斐爾說接到妳時，妳整個人狀態都很差。她說從未見過妳如此挫敗的樣子。",
  ui_story_8_2_2_20_dialog_content = "……",
  ui_story_8_2_2_21_dialog_content = "我很好，城主殿下。不用擔心。",
  ui_story_8_2_2_22_dialog_content = "好。",
  ui_story_8_2_2_23_dialog_content = "你們怎麼看？",
  ui_story_8_2_2_24_dialog_content = "我表達過我的意見了。要以白夜城停擺為代價，簡直是瘋了。",
  ui_story_8_2_2_25_dialog_content = "審判庭那邊呢？",
  ui_story_8_2_2_26_dialog_content = "我只遵循流程。任何提案只要通過三方決議，就可以施行。",
  ui_story_8_2_2_27_dialog_content = "反之，審判庭會堅決制止，無論對像是誰。",
  ui_story_8_2_2_28_dialog_content = "那就開始簡單決議吧。",
  ui_story_8_2_2_29_dialog_content = "奧托，元老院代表，我相信你會否決這項提案。",
  ui_story_8_2_2_30_dialog_content = "當然。",
  ui_story_8_2_2_31_dialog_content = "伊倫汀，審判庭大審判長，你的決定是？",
  ui_story_8_2_2_32_dialog_content = "棄權。",
  ui_story_8_2_2_33_dialog_content = "好。",
  ui_story_8_2_2_34_dialog_content = "最後，我，舒瓦茲，白夜城城主與大貴族們的代表……",
  ui_story_8_2_2_35_dialog_content = "我否決這項提案。",
  ui_story_8_2_2_36_dialog_content = "——！！",
  ui_story_8_2_2_37_dialog_content = "兩票否決，一票棄權，審判庭視為不予施行。",
  ui_story_8_2_2_38_dialog_content = "你父親顯然比你更懂得維護白夜城的根基，卡蓮。",
  ui_story_8_2_2_39_dialog_content = "簡直是兒戲！所謂的三方決議，就這樣口頭完成了嗎？！",
  ui_story_8_2_2_40_dialog_content = "緊急情況下，決議不必走固定流程，只要審判庭在場並認可，決議便有效。",
  ui_story_8_2_2_41_dialog_content = "請你尊重秩序，卡蓮。",
  ui_story_8_2_2_42_dialog_content = "我……",
  ui_story_8_2_2_43_dialog_content = "聽見了嗎？要用那個，就得集中能源，甚至關閉護盾……",
  ui_story_8_2_2_44_dialog_content = "那樣做與自殺有何區別？至少我們現在還有護盾的保護……",
  ui_story_8_2_2_45_dialog_content = "真是的，明明是城主之女，卻搞不清楚自己在幹嘛……",
  ui_story_8_2_2_46_dialog_content = "……",
  ui_story_8_2_2_47_dialog_content = "卡蓮。",
  ui_story_8_2_2_48_dialog_content = "……",
  ui_story_8_2_2_49_dialog_content = "抬起妳的頭，卡蓮·德·舒瓦茲！",
  ui_story_8_2_2_50_dialog_content = "這裡可是白夜城！不是什麼過扮家家酒似的巨像冒險團！",
  ui_story_8_2_2_51_dialog_content = "別把那些作風搬到我的城邦裡來，聽懂了嗎？",
  ui_story_8_2_2_52_dialog_content = "……",
  ui_story_8_2_2_53_dialog_content = "我問你聽懂了嗎？！",
  ui_story_8_2_2_54_dialog_content = "是，城主殿下。",
  ui_story_8_2_2_55_dialog_content = "在事態明朗之前，繼續維持護盾才是明策。至於啟動達摩克利斯……",
  ui_story_8_2_2_56_dialog_content = "簡直是不可理喻。",
  ui_story_8_2_2_57_dialog_content = "遇事則亂，毫無章法！卡蓮，妳現在跟小時候一樣，從不吸取教訓！",
  ui_story_8_2_2_58_dialog_content = "……？",
  ui_story_8_2_2_59_dialog_content = "我以為妳那年為了拯救一隻貓而從樹屋上掉下來，已經是愚蠢的極限了。",
  ui_story_8_2_2_60_dialog_content = "但顯然，你還是毫無長進！",
  ui_story_8_2_2_61_dialog_content = "（樹屋……？）",
  ui_story_8_2_2_62_dialog_content = "雖然妳最後的確救下那隻貓，妳的決斷也算正確，但那又如何？",
  ui_story_8_2_2_63_dialog_content = "不顧他人阻攔，為了一隻貓的命而摔斷腿，這值得嗎？",
  ui_story_8_2_2_64_dialog_content = "（……？！）",
  ui_story_8_2_2_65_dialog_content = "我問你，值得嗎？！",
  ui_story_8_2_2_66_dialog_content = "舒瓦茲，這是什麼意思？為什麼聊起了家常？",
  ui_story_8_2_2_67_dialog_content = "我是在問你嗎，奧托·特洛伊？",
  ui_story_8_2_2_68_dialog_content = "……",
  ui_story_8_2_2_69_dialog_content = "值得。",
  ui_story_8_2_2_70_dialog_content = "我認為值得，父親。",
  ui_story_8_2_2_71_dialog_content = "好。那你果然無藥可救了。",
  ui_story_8_2_2_72_dialog_content = "你就和那隻貓咪一樣，困死在自己的象牙塔裡好了。",
  ui_story_8_2_2_73_dialog_content = "……",
  ui_story_8_2_2_74_dialog_content = "嗚啊……城主殿下剛才好凶……",
  ui_story_8_2_2_75_dialog_content = "而且為什麼突然扯起以前的事啊？感覺好奇怪，甚至有點毛骨悚然……",
  ui_story_8_2_2_77_dialog_content = "咿——？！卡蓮姐姐為什麼在笑？這更毛骨悚然了！！",
  ui_story_8_2_2_78_dialog_content = "因為我好像聽懂……那個男人想說什麼了。",
  ui_story_8_2_2_79_dialog_content = "欸？",
  ui_story_8_2_2_80_dialog_content = "樹屋，還有貓咪……呵，小時候的確發生過這麼一件事。",
  ui_story_8_2_2_81_dialog_content = "只不過……",
  ui_story_8_2_2_82_dialog_content = "……我當時根本就沒救下那隻貓。",
  ui_story_8_2_2_83_dialog_content = "所以是城主記錯了嗎？唔……還是說……",
  ui_story_8_2_2_84_dialog_content = "啊，難道……",
  ui_story_8_2_2_85_dialog_content = "殿下得老年癡呆了？",
  ui_story_8_2_2_86_dialog_content = "妳不懂，沒關係。跟我來就行了……我們要去個地方。",
  ui_story_8_2_2_87_dialog_content = "哦哦！好！哪裡？",
  ui_story_8_2_2_88_dialog_content = "……",
  ui_story_8_2_2_89_dialog_content = "達摩克利斯的控制室。",
  ui_story_8_3_1_1_dialog_content = "<color=#e8d9bb>吞噬者號內</color>",
  ui_story_8_3_1_2_dialog_content = "哼哼哼～哼哼♪",
  ui_story_8_3_1_3_dialog_content = "啊，抱歉，我有些得意忘形了。",
  ui_story_8_3_1_4_dialog_content = "來，繼續往這邊走吧……我也是第一次來這裡「觀光」呢……",
  ui_story_8_3_1_5_dialog_content = "居！",
  ui_story_8_3_1_6_dialog_content = "（居里能追蹤薇薇安的氣味，如果他也認為該往這個方向走……）",
  ui_story_8_3_1_7_dialog_content = "繼續前進吧，這邊應該是對的。",
  ui_story_8_3_1_8_dialog_content = "……",
  ui_story_8_3_1_9_dialog_content = "怎麼了，為什麼這樣看著我……",
  ui_story_8_3_1_10_dialog_content = "你真的沒事嗎？連我都受不了這裡的暗能了，你卻一點事都沒有？",
  ui_story_8_3_1_11_dialog_content = "唔，真的沒事。",
  ui_story_8_3_1_12_dialog_content = "說來奇怪，我完全不牴觸這裡的暗能。恰恰相反，甚至覺得……",
  ui_story_8_3_1_13_dialog_content = "味道還挺好聞的？",
  ui_story_8_3_1_14_dialog_content = "欸……",
  ui_story_8_3_1_15_dialog_content = "只是身上真的有點癢。該不會是過敏了吧？",
  ui_story_8_3_1_16_dialog_content = "癢？哪裡，要我幫你看看嗎？",
  ui_story_8_3_1_17_dialog_content = "不用，是背上。隔著衣服搔一搔就好了……",
  ui_story_8_3_1_18_dialog_content = "比起這個……",
  ui_story_8_3_1_19_option_content = "薇絲妳剛才說有點受不了？",
  ui_story_8_3_1_20_dialog_content = "果然，比起自己總是在擔心別人……",
  ui_story_8_3_1_21_dialog_content = "我沒事。雖說很難受，但比之前被舒默壓制的時候好得多。",
  ui_story_8_3_1_22_dialog_content = "而且這一路走來，我也成長了不少呢，PlayerName。",
  ui_story_8_3_1_23_dialog_content = "希望每個難關我們都能順利渡過！",
  ui_story_8_3_1_24_dialog_content = "一定可以的。在打倒舒默之前，可決不能認輸。",
  ui_story_8_3_1_25_dialog_content = "這個精神就對了，PlayerName。",
  ui_story_8_3_1_26_option_content = "不知道卡蓮現在怎麼樣",
  ui_story_8_3_1_27_dialog_content = "她應該已經回到白夜城了吧。",
  ui_story_8_3_1_28_dialog_content = "現在的她，也一定在用不同的方式為打倒舒默奮戰著……",
  ui_story_8_3_1_29_dialog_content = "所以「達摩克利斯」到底是什麼？是很厲害的武器嗎？",
  ui_story_8_3_1_30_dialog_content = "我沒有親眼見過，但留學時聽聞過她的「實力」……",
  ui_story_8_3_1_31_dialog_content = "總的來說就是不到關鍵時刻絕不能使用的殺手鐧吧。",
  ui_story_8_3_1_32_dialog_content = "所以你也完全不知道嘛……",
  ui_story_8_3_1_33_option_content = "薇薇安長官到底在哪裡",
  ui_story_8_3_1_34_dialog_content = "不清楚。但看居里的反應，一定是在前面沒錯！",
  ui_story_8_3_1_35_dialog_content = "它一定能帶著我們找到長官的。",
  ui_story_8_3_1_36_dialog_content = "如果不是長官，我們可能連逃脫的機會都沒有。",
  ui_story_8_3_1_37_dialog_content = "你也做了很多，PlayerName。最後你做出那種決定……",
  ui_story_8_3_1_38_dialog_content = "你是說推你們的那一下嗎？",
  ui_story_8_3_1_39_dialog_content = "也許只是某種本能的、下意識的反應。我甚至都差點忘了有這麼一回事……",
  ui_story_8_3_1_40_dialog_content = "我希望你以後不要再做出這種……「犧牲自我」的行為。",
  ui_story_8_3_1_41_dialog_content = "上次和貢露長官在一起的時候也是，你自己一個人衝上去……",
  ui_story_8_3_1_42_dialog_content = "居！！",
  ui_story_8_3_1_43_dialog_content = "抱歉，居里有些著急了呢，我們加快腳步吧。",
  ui_story_8_3_1_44_dialog_content = "PlayerName，總之你還是多注意一下自己的身體狀況。",
  ui_story_8_3_1_46_dialog_content = "好，別擔心我……",
  ui_story_8_6_1_1_dialog_content = "好、好亮……",
  ui_story_8_6_1_3_option_content = "不行！我得躲起來！",
  ui_story_8_6_1_4_dialog_content = "PlayerName？你跑到角落裡做什麼？",
  ui_story_8_6_1_5_dialog_content = "你在做什麼？快過來！",
  ui_story_8_6_1_6_dialog_content = "居！",
  ui_story_8_6_1_7_dialog_content = "抱、抱歉，這裡太亮了，讓我慢慢……",
  ui_story_8_6_1_8_dialog_content = "亮嗎？不過是普通的房間……",
  ui_story_8_6_1_9_dialog_content = "連這種亮度都……你不會是有點畏光吧？",
  ui_story_8_6_1_10_dialog_content = "不知道。唔……眼睛稍微有點適應了。",
  ui_story_8_6_1_11_option_content = "嘶……好癢……",
  ui_story_8_6_1_12_dialog_content = "眼睛好了，背又癢起來了嗎？",
  ui_story_8_6_1_13_dialog_content = "嗯。我是不是生病了……？",
  ui_story_8_6_1_14_dialog_content = "休息一下吧。這裡似乎沒有敵人，我們可以稍作整頓……",
  ui_story_8_6_1_15_dialog_content = "居！",
  ui_story_8_6_1_16_dialog_content = "居里？你要去哪？！",
  ui_story_8_6_1_17_dialog_content = "居！居！",
  ui_story_8_6_1_18_dialog_content = "薇薇安？！就在這個房間後面嗎？",
  ui_story_8_6_1_19_dialog_content = "居——！！居！居！",
  ui_story_8_6_1_20_dialog_content = "居里！我們會想辦法開門的，不要撞，被發現就……",
  ui_story_8_6_1_21_dialog_content = "嗯？這個味道……這個味道是？！",
  ui_story_8_6_1_22_dialog_content = "薇絲小心！",
  ui_story_8_6_1_23_dialog_content = "嘎嘎……！",
  ui_story_8_6_1_24_dialog_content = "牠們……牠們衝著你過去了！",
  ui_story_8_6_1_25_dialog_content = "擊中了！還有幾隻，不能讓它們去通報其他暗鬼！！",
  ui_story_8_6_1_26_dialog_content = "把剩下的解決掉！",
  ui_story_8_6_1_27_dialog_content = "好！都交給我，速戰速決吧！",
  ui_story_8_6_2_1_dialog_content = "很好！沒有製造太大的騷動……",
  ui_story_8_6_2_2_dialog_content = "不知道還有沒有漏網之……",
  ui_story_8_6_2_3_dialog_content = "？！小心後面……",
  ui_story_8_6_2_4_dialog_content = "唔嘎！！",
  ui_story_8_6_2_5_dialog_content = "（直接越過了我？！）",
  ui_story_8_6_2_6_dialog_content = "呼……果然，這裡的暗能開始影響我的判斷了，竟然漏掉一隻。",
  ui_story_8_6_2_7_dialog_content = "薇絲，剛才……",
  ui_story_8_6_2_8_dialog_content = "這隻暗鬼直接越過了我。不，好像根本就沒看到我！",
  ui_story_8_6_2_9_dialog_content = "對，我注意到了。不止剛才，這一路上都是，牠們似乎對你愈來愈沒興趣了。",
  ui_story_8_6_2_10_dialog_content = "就好像……",
  ui_story_8_6_2_11_dialog_content = "……沒有把你當作敵人。",
  ui_story_8_6_2_12_dialog_content = "……",
  ui_story_8_6_2_13_dialog_content = "可是……為什麼呢？",
  ui_story_8_6_2_14_dialog_content = "不清楚。PlayerName，你還好嗎？還有沒有不舒服的地方？",
  ui_story_8_6_2_15_dialog_content = "我不知道，薇絲……",
  ui_story_8_6_2_16_dialog_content = "居！",
  ui_story_8_6_2_17_dialog_content = "我瞭解，居里。可是PlayerName的身體……",
  ui_story_8_6_2_18_dialog_content = "沒事，如果薇薇安長官就在這裡面，還是先救出她再說！",
  ui_story_8_7_1_A1_dialog_content = "唔……爸爸……媽媽……？",
  ui_story_8_7_1_A2_dialog_content = "鎮子不是已經……淪陷了嗎？你們沒事就太好了……",
  ui_story_8_7_1_1_dialog_content = "是的，沉醉吧……它給你最甜蜜的夢，最真實的夢……",
  ui_story_8_7_1_2_dialog_content = "潔白、純粹，來自本源的印記……（日蝕語）母親的賜福。",
  ui_story_8_7_1_3_dialog_content = "它會發掘軀殼的潛力，匯聚獨一無二的力量。",
  ui_story_8_7_1_4_dialog_content = "更重要的是，它會使你變成我們的一員……",
  ui_story_8_7_1_5_dialog_content = "快點，再快點……到本源的殿堂裡來吧。",
  ui_story_8_7_1_6_dialog_content = "不管你拿著什麼，給我離她遠一點，暗鬼！",
  ui_story_8_7_1_7_dialog_content = "光靈？你什麼時候進來的？",
  ui_story_8_7_1_8_dialog_content = "長官！能聽到我說話嗎！",
  ui_story_8_7_1_9_dialog_content = "唔……",
  ui_story_8_7_1_10_dialog_content = "太好了，還活著！",
  ui_story_8_7_1_11_dialog_content = "為了救你的同伴，不自量力地現身……",
  ui_story_8_7_1_12_dialog_content = "還是說，特地來回應日蝕的感召？",
  ui_story_8_7_1_A3_dialog_content = "我名「落卞」，很樂意擔任你們的引路人。",
  ui_story_8_7_1_13_dialog_content = "「感召」指的是變成和你一樣的醜陋暗鬼嗎？謝謝，不必了。",
  ui_story_8_7_1_14_dialog_content = "（日蝕語）空裔！你現在應該已經轉變了才對！",
  ui_story_8_7_1_15_dialog_content = "我聽不懂你在說什麼。你還是說通用語吧。",
  ui_story_8_7_1_16_dialog_content = "為什麼大人沒有提醒我們？甚至連警報都不曾發出，你們用了什麼手段……",
  ui_story_8_7_1_17_dialog_content = "技巧，暗鬼。從某種程度上說，吞噬者號也是可以被我感應的，瞭解嗎？",
  ui_story_8_7_1_18_dialog_content = "只要不鬧出太大的動靜，截斷警報和隱藏行蹤還是綽綽有餘。",
  ui_story_8_7_1_19_dialog_content = "意料之外的變化呢……不過沒關係，如果我的嗅覺沒錯……",
  ui_story_8_7_1_20_dialog_content = "你已經快要加入我們了，空裔。",
  ui_story_8_7_1_21_dialog_content = "……什麼意思？",
  ui_story_8_7_1_F1_dialog_content = "PlayerName，別受它的蠱惑。",
  ui_story_8_7_1_22_dialog_content = "你剛才要對長官做什麼？那個發光的東西又是什麼？",
  ui_story_8_7_1_23_dialog_content = "（日蝕語）無聊的問題。",
  ui_story_8_7_1_24_dialog_content = "不要浪費我的耐心，暗鬼。我現在可沒時間跟你玩猜謎遊戲。",
  ui_story_8_7_1_25_dialog_content = "那是恩賜！母親給予的恩賜！",
  ui_story_8_7_1_26_dialog_content = "你們明白主人的苦心嗎？明明可以瞬間讓你們化為齏粉，卻特地放過你們。",
  ui_story_8_7_1_27_dialog_content = "還邀請你們來這片樂土，無償地、溫柔地賜予你們力量……",
  ui_story_8_7_1_28_dialog_content = "榮幸！這是榮幸！！",
  ui_story_8_7_1_29_dialog_content = "賜予力量？說清楚一點！",
  ui_story_8_7_1_30_dialog_content = "你馬上就知道了，不要問無謂的問題。",
  ui_story_8_7_1_31_dialog_content = "難道說……",
  ui_story_8_7_1_32_dialog_content = "別聽它囉嗦。趕快解決掉，現在還來得及！",
  ui_story_8_7_1_33_dialog_content = "又是你！你在哪裡？",
  ui_story_8_7_1_34_dialog_content = "旁觀席，頭等座。這重要嗎？",
  ui_story_8_7_1_35_dialog_content = "您若還想作為空裔活下去，就聽我的……速戰速決！",
  ui_story_8_7_1_36_dialog_content = "（日蝕語）在更廣闊的視野中發抖吧，為過往的無知而羞愧、震顫！",
  ui_story_8_7_1_37_dialog_content = "唔——！",
  ui_story_8_7_1_38_dialog_content = "薇絲、我……身體裡、有東西在動！不，是能量……",
  ui_story_8_7_1_39_dialog_content = "有……某種能量……",
  ui_story_8_7_1_40_dialog_content = "PlayerName！！冷靜！保持冷靜！",
  ui_story_8_7_1_41_dialog_content = "呃啊——頭，頭快要裂開了——",
  ui_story_8_7_1_43_dialog_content = "好、好強！PlayerName，快回過神來！！",
  ui_story_8_7_1_44_option_content = "我知道……要穩定……意識……",
  ui_story_8_7_1_45_dialog_content = "太晚了，一切都定型了。",
  ui_story_8_7_1_46_dialog_content = "「種子」已經生根發芽，我聽到它的尖嘯……",
  ui_story_8_7_1_47_dialog_content = "母親身邊，又多ㄧ個寶貴的靈魂！",
  ui_story_8_7_1_48_option_content = "穩定……意識……",
  ui_story_8_7_1_49_dialog_content = "居！！",
  ui_story_8_7_1_51_dialog_content = "居里，我們一起上……",
  ui_story_8_7_1_52_dialog_content = "真是悲哀。沒有空裔扶持，你們根本就是扶不起的阿斗。",
  ui_story_8_7_1_53_dialog_content = "唔！",
  ui_story_8_7_1_54_dialog_content = "PlayerName……",
  ui_story_8_7_1_55_dialog_content = "您這在幹什麼？",
  ui_story_8_7_1_56_dialog_content = "您不應該就此被打敗！",
  ui_story_8_7_1_57_dialog_content = "您是空裔……沒人能掌控您的意識！",
  ui_story_8_7_1_58_option_content = "（讓意識穩定下來！！！）",
  ui_story_8_7_1_59_dialog_content = "……？",
  ui_story_8_7_1_60_dialog_content = "差點……就失控了……",
  ui_story_8_7_1_61_dialog_content = "你！強行停止轉化？！",
  ui_story_8_7_1_62_dialog_content = "噓，吵死了……",
  ui_story_8_7_1_63_dialog_content = "從剛剛就一直吵，搞得我頭好痛……",
  ui_story_8_7_1_64_dialog_content = "不對！不可能！你是怎麼擺脫「種子」的控制的？！",
  ui_story_8_7_1_65_dialog_content = "嘰嘰喳喳……嘰嘰喳喳……",
  ui_story_8_7_1_66_dialog_content = "你的聲音快要大到連舒默都能聽見了。",
  ui_story_8_7_1_67_dialog_content = "不過現在嘛，你可以隨便叫了……我重新與吞噬者號建立感應了。",
  ui_story_8_7_1_F2_dialog_content = "我控制了這座巨像，這個房間將完全隔音……",
  ui_story_8_7_1_68_dialog_content = "你最後發出的噪音也傳不到那個什麼「母親」的耳朵裡了。",
  ui_story_8_7_1_69_dialog_content = "PlayerName……太好了，你似乎恢復正常了？",
  ui_story_8_7_1_70_dialog_content = "嗯，我沒事了。抱歉，讓妳一個人面對那種傢伙。",
  ui_story_8_7_1_71_dialog_content = "雖然腦袋又開始痛起來了……但好歹能忍一下。",
  ui_story_8_7_1_73_dialog_content = "無知愚蠢的東西、不知好歹、褻瀆者！你會被帶向「那裡」的！",
  ui_story_8_7_1_74_dialog_content = "不論是現在或以後，你遲早都會成為我們的一份子！！",
  ui_story_8_7_1_75_dialog_content = "薇絲，讓它閉嘴吧。",
  ui_story_8_7_1_76_dialog_content = "薇薇安長官還在等著我們呢……",
  ui_story_8_7_1_77_dialog_content = "好！",
  ui_story_8_7_2_1_dialog_content = "長官！",
  ui_story_8_7_2_2_dialog_content = "居！居！",
  ui_story_8_7_2_4_dialog_content = "唔……",
  ui_story_8_7_2_5_dialog_content = "長官，您怎麼會……虛弱成這樣……對不起，這麼晚才趕來。",
  ui_story_8_7_2_6_dialog_content = "與其擔心別人，先看看您自己的身體吧……",
  ui_story_8_7_2_7_dialog_content = "誰？！",
  ui_story_8_7_2_8_dialog_content = "是妳？薇絲，我見過他……他就是剛才給我指路的人。",
  ui_story_8_7_2_9_dialog_content = "啊，他就是你所說的那個「手持白箱」的人！",
  ui_story_8_7_2_10_dialog_content = "我不是你們的敵人。如你所見，我也是光靈。",
  ui_story_8_7_2_11_dialog_content = "你們可以稱呼我為「浮士德」，我侍奉真理……",
  ui_story_8_7_2_12_dialog_content = "「真理」？聽上去有點可疑……",
  ui_story_8_7_2_13_dialog_content = "真理是永恆不變的正確道理，是萬物的規律。無需擔心，我是來幫助您的。",
  ui_story_8_7_2_14_dialog_content = "你的自我介紹完全沒辦法讓人知道你是誰。",
  ui_story_8_7_2_15_dialog_content = "您也不需要明白。請將精力放在自己身上……",
  ui_story_8_7_2_16_dialog_content = "您體內的「種子」就快要發芽了。",
  ui_story_8_7_2_17_dialog_content = "……所以「種子」到底是什麼？",
  ui_story_8_7_2_18_dialog_content = "先處理吧，等等再解釋。",
  ui_story_8_7_2_19_dialog_content = "請脫下衣服，PlayerName。",
  ui_story_8_7_2_20_dialog_content = "欸？",
  ui_story_8_7_2_21_dialog_content = "抱歉，現在不是您害羞的時候。請按照我說的做。",
  ui_story_8_7_2_22_dialog_content = "您身上有感覺到古怪的地方吧？",
  ui_story_8_7_2_23_dialog_content = "嗯，你一說，我又覺得背上開始癢了……",
  ui_story_8_7_2_24_dialog_content = "所以是在背上。",
  ui_story_8_7_2_25_dialog_content = "請相信我。我能幫助您。",
  ui_story_8_7_2_26_option_content = "好吧，我脫……",
  ui_story_8_7_2_27_dialog_content = "……",
  ui_story_8_7_2_28_dialog_content = "裡面這件也請脫掉。",
  ui_story_8_7_2_29_dialog_content = "PlayerName，需要我轉過去嗎？",
  ui_story_8_7_2_30_dialog_content = "並不是什麼奇怪的地方，只是後背而已，請不要再拖延了……",
  ui_story_8_7_2_31_option_content = "行行行……我脫……",
  ui_story_8_7_2_32_dialog_content = "這……",
  ui_story_8_7_2_33_dialog_content = "果然……",
  ui_story_8_7_2_34_dialog_content = "怎麼了？我背上有什麼？",
  ui_story_8_7_2_35_dialog_content = "在這種情況下還能保持清醒……該說您不簡單，還是遲鈍呢。",
  ui_story_8_7_2_36_dialog_content = "到底是什麼情況！",
  ui_story_8_7_2_37_dialog_content = "薇絲小姐，您能把「它」挖出來嗎？",
  ui_story_8_7_2_38_dialog_content = "已經快要進入皮膚下面了，趁還能看到位置，簡單粗暴一點吧。",
  ui_story_8_7_2_39_dialog_content = "……我沒有告訴過你我的名字。",
  ui_story_8_7_2_40_dialog_content = "是的，但這並不重要，現在有更重要的事。",
  ui_story_8_7_2_41_dialog_content = "您從我身上感受到任何敵意了嗎？",
  ui_story_8_7_2_42_dialog_content = "……",
  ui_story_8_7_2_43_dialog_content = "好吧。強行取出這個應該沒問題。",
  ui_story_8_7_2_44_dialog_content = "喂！我身上到底……",
  ui_story_8_7_2_45_dialog_content = "不要亂動！",
  ui_story_8_7_2_46_dialog_content = "薇絲，拜託了。",
  ui_story_8_7_2_47_dialog_content = "……可能會有點痛，PlayerName。",
  ui_story_8_7_2_48_dialog_content = "嗚啊——？！",
  ui_story_8_7_2_50_dialog_content = "（痛、痛到說不出話？！這是「有點痛」嗎？！）",
  ui_story_8_7_2_51_dialog_content = "請後退，薇絲小姐！不要太靠近……",
  ui_story_8_7_2_52_dialog_content = "這東西，真是危險……又迷人呢……",
  ui_story_8_7_2_53_option_content = "這到底是什麼東西？",
  ui_story_8_7_2_54_dialog_content = "「種子」，至少那些暗鬼是這麼稱呼它的。",
  ui_story_8_7_2_55_dialog_content = "而在其他資料裡，還有「力量之源」、「母親之吻」、「飛升印記」等外號。",
  ui_story_8_7_2_56_dialog_content = "不過說的意思都一樣。暗鬼透過它能獲得強大而獨特的力量。",
  ui_story_8_7_2_57_dialog_content = "更重要的是，「種子」是將其他生物轉為暗鬼的唯一途徑……",
  ui_story_8_7_2_58_dialog_content = "轉化……難道說和格茲德那個時候一樣？",
  ui_story_8_7_2_59_dialog_content = "甚至是……舒默。",
  ui_story_8_7_2_60_dialog_content = "我不清楚你們說的是誰，但如果是身為光的子民卻使用暗影之力的人……",
  ui_story_8_7_2_61_dialog_content = "那「種子」一定已經在那個人身上生根發芽。",
  ui_story_8_7_2_62_option_content = "所以我被「治好」了？",
  ui_story_8_7_2_63_dialog_content = "算是，但更多取決於您自己的意志。否則在我現身之前，您就已經淪陷了。",
  ui_story_8_7_2_64_dialog_content = "而且「種子」並不是疾病，它更像……一種意識。",
  ui_story_8_7_2_65_dialog_content = "您現在感覺如何？",
  ui_story_8_7_2_66_dialog_content = "應該會很輕鬆吧，畢竟……",
  ui_story_8_7_2_67_dialog_content = "不，很……難受。",
  ui_story_8_7_2_68_dialog_content = "欸？",
  ui_story_8_7_2_69_dialog_content = "感覺一下子洩了氣一樣，呼吸不順，而且……胸悶、眼前發黑，而且嗓子也……",
  ui_story_8_7_2_70_dialog_content = "這才是正常的。",
  ui_story_8_7_2_71_dialog_content = "這裡暗能非常濃厚，您這樣的空裔本該有這些反應。",
  ui_story_8_7_2_72_dialog_content = "之前毫無異樣是因為「種子」在將您轉化為暗鬼。明白了嗎？",
  ui_story_8_7_2_73_dialog_content = "原來如此……咳咳……",
  ui_story_8_7_2_74_dialog_content = "這東西真是太危險了。摧毀它吧！",
  ui_story_8_7_2_75_dialog_content = "且慢，薇絲小姐。",
  ui_story_8_7_2_76_dialog_content = "它對一些人是穿腸毒藥，對另一些人，卻是求之不得的寶物……比如我。",
  ui_story_8_7_2_77_dialog_content = "……？！",
  ui_story_8_7_2_78_dialog_content = "請放心，我不會拿去迫害另一個可憐蟲的。我只是好奇。",
  ui_story_8_7_2_79_dialog_content = "身為真理的領命人，我們有我們的追求。僅此而已。",
  ui_story_8_7_2_80_dialog_content = "而且只要將它裝進我的箱子裡，就不會有危險。",
  ui_story_8_7_2_81_dialog_content = "那個箱子……好像在動？",
  ui_story_8_7_2_82_dialog_content = "請勿擔心，這箱子是特殊的。相信我，光靈與暗鬼的祕密，終有揭開的一天。",
  ui_story_8_7_2_83_dialog_content = "而在漫長的索求之路上，我們還要繼續互相扶持。",
  ui_story_8_7_2_84_dialog_content = "說中文好嗎……你到底要它幹嘛？",
  ui_story_8_7_2_85_dialog_content = "我相信您很快會知道的。後會有期，PlayerName，薇絲。",
  ui_story_8_7_2_86_dialog_content = "希望你們順利渡過難關。啊，不，應該說……",
  ui_story_8_7_2_87_dialog_content = "在不遠的未來，我已經看到你們脫身後的英姿了。",
  ui_story_8_7_2_88_dialog_content = "願真理祝福你們。",
  ui_story_8_7_2_89_dialog_content = "薇……絲？",
  ui_story_8_7_2_90_dialog_content = "居！居！",
  ui_story_8_7_2_91_dialog_content = "啊，長官！抱歉，剛才在緊急處理PlayerName的傷……",
  ui_story_8_7_2_92_dialog_content = "嗯，我好像聽到你們的對話……PlayerName沒事吧？",
  ui_story_8_7_2_F1_dialog_content = "他已經沒事了。長官您還好嗎？",
  ui_story_8_7_2_F2_dialog_content = "我也沒事。剛才恐怕中了敵人的「幻象」，現在已經緩過神來了。",
  ui_story_8_7_2_93_dialog_content = "居！",
  ui_story_8_7_2_94_dialog_content = "讓你擔心了，居里。",
  ui_story_8_7_2_95_dialog_content = "抱歉，也給大家添麻煩了……",
  ui_story_8_7_2_96_option_content = "請不要說這種話",
  ui_story_8_7_2_97_dialog_content = "長官，如果不是您，我們大家連逃脫的機會都沒有……",
  ui_story_8_7_2_98_dialog_content = "所以你們為了救我，又折回來？",
  ui_story_8_7_2_99_dialog_content = "……發生了很多事。等我們先逃出這裡，再慢慢說給您聽吧！",
  ui_story_8_7_2_100_dialog_content = "吞羅……呢？還有那個神經質的女孩……",
  ui_story_8_7_2_101_dialog_content = "舒默吧。她們不在這附近，但遲早會發現我們的。",
  ui_story_8_7_2_102_dialog_content = "剛才的騷動可能被舒默感知到了，必須盡快離開！",
  ui_story_8_7_2_103_option_content = "已經沒事了，長官",
  ui_story_8_7_2_104_dialog_content = "已經沒事了，我們沒讓那個暗鬼將「種子」放進你體內。",
  ui_story_8_7_2_105_dialog_content = "「種子」……？就是你們……剛才說的那個……",
  ui_story_8_7_2_106_dialog_content = "先離開這裡吧，細節我們稍後再向您詳細說明。",
  ui_story_8_7_2_107_dialog_content = "好。那就……拜託你們了。",
  ui_story_8_7_2_108_dialog_content = "對了，吞羅呢？還有那個強得誇張的傢伙……",
  ui_story_8_7_2_109_dialog_content = "她們不在這附近，但不能掉以輕心。",
  ui_story_8_7_2_110_dialog_content = "剛才的騷動也許已經被舒默感知到了，必須盡快離開！",
  ui_story_8_7_2_111_dialog_content = "面對敵人，只能偷偷逃走嗎……",
  ui_story_8_7_2_112_dialog_content = "等回到迦南，得主動向大元帥領罪了……",
  ui_story_8_7_2_113_dialog_content = "……",
  ui_story_8_7_2_114_dialog_content = "擊碎、貫穿、碾成粉末。",
  ui_story_8_7_2_115_dialog_content = "那些無聊的價值標準、道德，還有眼前這座噁心的城市……都會被碾成粉末。",
  ui_story_8_7_2_116_dialog_content = "你就睜大眼睛看著吧，PlayerName。",
  ui_story_8_7_2_117_dialog_content = "我要讓這些地獄般的畫面刻進你那雙屬於空裔的、最後的眼睛中。",
  ui_story_8_7_2_118_dialog_content = "刻進你們那弱小的基因中。",
  ui_story_8_8_1_1_dialog_content = "這裡可是白夜城！不是什麼扮家家酒似的巨像冒險團！",
  ui_story_8_8_1_2_dialog_content = "我以為妳那年為了拯救一隻貓而從樹屋上掉下來，已經是愚蠢的極限了。",
  ui_story_8_8_1_3_dialog_content = "雖然妳最後的確救下那隻貓，妳的決斷也算正確，但那又如何？",
  ui_story_8_8_1_4_dialog_content = "我問你，值得嗎？！",
  ui_story_8_8_1_5_dialog_content = "……",
  ui_story_8_8_1_6_dialog_content = "希望我沒有理解錯他的意思。",
  ui_story_8_8_1_7_dialog_content = "真是不可思議……那個男人從來沒說過這種話。",
  ui_story_8_8_1_8_dialog_content = "就算卡蓮姐姐妳會錯意了，現在也晚了不是嗎。",
  ui_story_8_8_1_9_dialog_content = "畢竟我們已經溜進……",
  ui_story_8_8_1_10_dialog_content = "達摩克利斯的控制室。",
  ui_story_8_8_1_11_dialog_content = "嗯。如果被其他人抓住了，你就說是被我逼迫的。",
  ui_story_8_8_1_12_dialog_content = "拉斐爾在意的不是這個啦～",
  ui_story_8_8_1_13_dialog_content = "卡蓮姐姐有時候會露出特別堅定的眼神呢，就像剛剛一樣。",
  ui_story_8_8_1_14_dialog_content = "每次拉斐爾不知道該怎麼辦的時候，看到那樣的眼神就會覺得「那就跟著卡蓮姐姐吧」！",
  ui_story_8_8_1_15_dialog_content = "選擇本身並沒有對錯，勇於選擇才是最重要的不是嗎！",
  ui_story_8_8_1_16_dialog_content = "……",
  ui_story_8_8_1_17_dialog_content = "這話聽起來很有哲理，但轉念一想卻毫無道理。",
  ui_story_8_8_1_18_dialog_content = "……",
  ui_story_8_8_1_19_dialog_content = "唷！小米迦勒！你來得很快欸！",
  ui_story_8_8_1_20_dialog_content = "……",
  ui_story_8_8_1_21_dialog_content = "謝謝你，米迦勒。我沒指望所有衛隊成員都能回應我的請求，有你已經足夠。",
  ui_story_8_8_1_22_dialog_content = "小米迦勒很值得信賴的～！從來不會多嘴問不該問的問題，對吧？",
  ui_story_8_8_1_23_dialog_content = "…………",
  ui_story_8_8_1_24_dialog_content = "外面情況如何？護盾還好嗎？",
  ui_story_8_8_1_25_dialog_content = "……",
  ui_story_8_8_1_26_dialog_content = "剛才拉斐爾有收到最新的報告哦，護盾正在以肉眼可見的速度在減少。",
  ui_story_8_8_1_27_dialog_content = "竟然能破壞那麼牢固的光能屏障，那傢伙很了不起呢！",
  ui_story_8_8_1_28_dialog_content = "因為她已經不是以前的那個舒默了。而我沒能阻止……",
  ui_story_8_8_1_29_dialog_content = "但這次！這次我一定要做到！",
  ui_story_8_8_1_30_dialog_content = "嗯嗯！拉斐爾也充滿幹勁喔！",
  ui_story_8_8_1_31_dialog_content = "小米迦勒也準備好了吧！",
  ui_story_8_8_1_32_dialog_content = "……",
  ui_story_8_8_1_33_dialog_content = "好。我說明一下，你們要做的事情很簡單……",
  ui_story_8_8_1_34_dialog_content = "你們幫我擋住控制室的大門，不能放任何人進去！",
  ui_story_8_8_1_35_dialog_content = "等我啟動達摩克利斯後，它會將整個白夜城的能源都集中到這裡……",
  ui_story_8_8_1_36_dialog_content = "護盾會短暫地消失一段時間，必定會造成極大恐慌。",
  ui_story_8_8_1_37_dialog_content = "拉斐爾，你能再聯絡一下其他衛隊成員嗎？",
  ui_story_8_8_1_38_dialog_content = "讓她們去其他區域防守，撐過達摩克利斯充能的階段！",
  ui_story_8_8_1_39_dialog_content = "好！我再試試看聯絡她們！",
  ui_story_8_8_1_40_dialog_content = "卡蓮姐姐，你放心去做你認為是對的事吧！",
  ui_story_8_8_1_41_dialog_content = "辛苦了。這裡……就交給你們了。",
  ui_story_8_8_1_42_dialog_content = "……",
  ui_story_8_8_1_43_dialog_content = "父親，這或許是我做過最瘋狂的事了吧。",
  ui_story_8_8_1_44_dialog_content = "但我相信……",
  ui_story_8_8_1_45_dialog_content = "「用自己的方式，去保護想要保護的人……」。",
  ui_story_8_8_1_46_dialog_content = "這是對的選擇。",
  ui_story_8_8_1_47_dialog_content = "<color=#e8d9bb>控制室外</color>",
  ui_story_8_8_1_48_dialog_content = "審判長，她果然進去了。",
  ui_story_8_8_1_49_dialog_content = "……",
  ui_story_8_8_1_50_dialog_content = "要出動嗎？趁現在的話……",
  ui_story_8_8_1_51_dialog_content = "如果只是進入達摩克利斯控制室，卡蓮並沒有違反任何條例不是嗎？",
  ui_story_8_8_1_52_dialog_content = "作為衛隊長，她有權力出入任何場所……",
  ui_story_8_8_1_53_dialog_content = "但如果她膽敢啟動達摩克利斯，就另當別論了。",
  ui_story_8_8_1_54_dialog_content = "可是，等到那個時候……也晚了呀。",
  ui_story_8_8_1_55_dialog_content = "什麼意思？",
  ui_story_8_8_1_56_dialog_content = "白夜城的存亡建立在秩序與規則之上，要是打破這裡的鐵律而隨意行動……",
  ui_story_8_8_1_57_dialog_content = "那才是真的為時已晚。",
  ui_story_8_8_1_58_dialog_content = "明白。屬下隨時待命。",
  ui_story_8_8_1_59_dialog_content = "另外，讓一部分人力做好支援其他城區的準備。",
  ui_story_8_8_1_60_dialog_content = "支援？",
  ui_story_8_8_1_61_dialog_content = "如果她真的啟動達摩克利斯，白夜城的城門將會短暫地大開。",
  ui_story_8_8_1_62_dialog_content = "這到底會是絕處逢生的機會，還是墜入深淵的開端呢……",
  ui_story_8_8_1_63_dialog_content = "……卡蓮·德·舒瓦茲。",
  ui_story_8_9_1_1_dialog_content = "這邊！如果我之前記的路線沒錯，我們……",
  ui_story_8_9_1_2_dialog_content = "等一下，薇絲……",
  ui_story_8_9_1_3_dialog_content = "怎麼了？",
  ui_story_8_9_1_4_dialog_content = "我……我們最好先等等。",
  ui_story_8_9_1_5_dialog_content = "長官，我們一刻也不能耽擱……我可以背您！來！",
  ui_story_8_9_1_6_dialog_content = "我的意思不是這個。我們在吞噬者號的哪個位置？",
  ui_story_8_9_1_7_dialog_content = "位置？我們已經靠近來的時候的出口。",
  ui_story_8_9_1_8_dialog_content = "它在……戰鬥嗎？",
  ui_story_8_9_1_9_dialog_content = "雖然在裡面不太清楚情況，但恐怕吞噬者號正在不斷攻擊白夜城的護盾。",
  ui_story_8_9_1_10_dialog_content = "這樣下去，護盾被攻破是遲早的事……",
  ui_story_8_9_1_11_dialog_content = "白夜城……有採取什麼對策嗎？",
  ui_story_8_9_1_12_dialog_content = "卡蓮回去了，正在爭取啟用達摩克利斯。",
  ui_story_8_9_1_13_dialog_content = "竟然被逼到這個地步……",
  ui_story_8_9_1_14_dialog_content = "是的。吞噬者號已經成功補完，現在的力量……",
  ui_story_8_9_1_15_dialog_content = "……",
  ui_story_8_9_1_16_dialog_content = "舒默呢？她還沒發現我們？",
  ui_story_8_9_1_17_dialog_content = "PlayerName一直利用感應能力限制這座巨像。",
  ui_story_8_9_1_18_dialog_content = "是的，我限制它獲取內部情報，現在與之相連的舒默應該還沒意識到我們逃走了。",
  ui_story_8_9_1_19_dialog_content = "但這個尺度很難掌握，不小心用力過猛的話……舒默反而會察覺到不對勁。",
  ui_story_8_9_1_20_dialog_content = "也就是說，現在情勢逆轉了……",
  ui_story_8_9_1_21_dialog_content = "敵明，我暗。",
  ui_story_8_9_1_22_dialog_content = "長官，難道……",
  ui_story_8_9_1_23_dialog_content = "我們不能走，薇絲。",
  ui_story_8_9_1_24_dialog_content = "欸？",
  ui_story_8_9_1_25_dialog_content = "基本的……戰略分析，你忘了嗎？現在的我們，是從內部攻破敵人的……",
  ui_story_8_9_1_26_dialog_content = "唯一希望。",
  ui_story_8_9_1_27_dialog_content = "可是，長官您的狀態……",
  ui_story_8_9_1_28_dialog_content = "這時候不應該在意我。",
  ui_story_8_9_1_29_dialog_content = "我們不能放棄這次絕佳的機會，如果成功，或許可以保護整座城。",
  ui_story_8_9_1_30_dialog_content = "……",
  ui_story_8_9_1_31_dialog_content = "你也知道孰輕孰重，對吧？",
  ui_story_8_9_1_32_dialog_content = "薇絲，你之前是個非常冷靜、果斷的孩子。最近似乎變得有些猶豫不決呢。",
  ui_story_8_9_1_33_dialog_content = "長官，我只是……不想再拋下任何人。更何況是你們……",
  ui_story_8_9_1_34_dialog_content = "那我問你，如果我們角色互換，你會允許我們放棄這樣一個絕佳的機會嗎……？",
  ui_story_8_9_1_35_dialog_content = "我……",
  ui_story_8_9_1_36_dialog_content = "況且，托PlayerName的福，我的傷勢已經控制住了。",
  ui_story_8_9_1_37_dialog_content = "薇絲，敵人就在前方，怎麼能夠轉身逃跑呢？",
  ui_story_8_9_2_1_dialog_content = "<color=#e8d9bb>白夜城內·若干年前</color>",
  ui_story_8_9_2_2_dialog_content = "（「用自己的方式，去保護想要保護的人……」）",
  ui_story_8_9_2_3_dialog_content = "……",
  ui_story_8_9_2_4_dialog_content = "可是……",
  ui_story_8_9_2_5_dialog_content = "它……死掉了。",
  ui_story_8_9_2_6_dialog_content = "任何生物都有逝去的一天，卡蓮。",
  ui_story_8_9_2_7_dialog_content = "我沒救到它……要是再小心一點就好了……",
  ui_story_8_9_2_8_dialog_content = "它是因為害怕，自己從樹屋上掉下來的，並不是你的錯。",
  ui_story_8_9_2_9_dialog_content = "但我明明可以幫到它……明明可以做到的。",
  ui_story_8_9_2_10_dialog_content = "嘖，和小孩子沒辦法講道理啊。",
  ui_story_8_9_2_11_dialog_content = "你該吸取的教訓不是「本來可以幫助別人」，而是「以後必須更注意保護自己」。",
  ui_story_8_9_2_F1_dialog_content = "你知道有多少人會擔心你的安危嗎？",
  ui_story_8_9_2_12_dialog_content = "不過你和貓一起從樹屋摔下來，貓死了，你卻連皮外傷都沒有。",
  ui_story_8_9_2_13_dialog_content = "你們舒瓦茲家都是些什麼怪物……",
  ui_story_8_9_2_14_dialog_content = "總之，乖乖待在這裡吧，我已經通知你父親了。待會還是得讓醫官看看妳……",
  ui_story_8_9_2_15_dialog_content = "奧托先生。",
  ui_story_8_9_2_16_dialog_content = "嗯？",
  ui_story_8_9_2_17_dialog_content = "我可以問您一個問題嗎？",
  ui_story_8_9_2_18_dialog_content = "哎。說吧。",
  ui_story_8_9_2_19_dialog_content = "母親……過世的時候，您在場嗎？",
  ui_story_8_9_2_20_dialog_content = "……",
  ui_story_8_9_2_21_dialog_content = "我不在，卡蓮。除了你父親，沒人知道詳情。",
  ui_story_8_9_2_22_dialog_content = "……",
  ui_story_8_9_2_23_dialog_content = "我不應該去北境的。我應該留在母親身邊，好好保護她……",
  ui_story_8_9_2_24_dialog_content = "如果我好好地保護她……或許她就不會……",
  ui_story_8_9_2_25_dialog_content = "就算你在，也不一定能改變什麼。",
  ui_story_8_9_2_26_dialog_content = "欸？",
  ui_story_8_9_2_27_dialog_content = "這是實話。如果是舒瓦茲都無法改變的事實，就算多你一個又怎麼樣呢？",
  ui_story_8_9_2_28_dialog_content = "……所以，我依然是個沒辦法保護任何人的……小孩子對嗎？",
  ui_story_8_9_2_29_dialog_content = "不然呢？",
  ui_story_8_9_2_30_dialog_content = "……",
  ui_story_8_9_2_31_dialog_content = "不過是隻死貓而已，卡蓮。",
  ui_story_8_9_2_32_dialog_content = "記住，下次不要再一個人到處亂跑了。有點教養吧。",
  ui_story_8_9_2_33_dialog_content = "……",
  ui_story_8_9_2_34_dialog_content = "卡蓮姐姐！！",
  ui_story_8_9_2_35_dialog_content = "說吧。",
  ui_story_8_9_2_36_dialog_content = "審判庭的人已經包圍過來了！",
  ui_story_8_9_2_37_dialog_content = "是嗎。他們沒有出手？",
  ui_story_8_9_2_38_dialog_content = "目前沒有！但全都緊盯著這邊的動向……拉斐爾有種不好的預感……",
  ui_story_8_9_2_39_dialog_content = "伊倫汀審判長似乎也在的樣子……",
  ui_story_8_9_2_40_dialog_content = "……",
  ui_story_8_9_2_41_dialog_content = "拉斐爾，和米迦勒準備好吧。",
  ui_story_8_9_2_42_dialog_content = "是！",
  ui_story_8_9_2_43_dialog_content = "守住那扇門。不能讓任何人走進達摩克利斯的控制室，明白嗎？",
  ui_story_8_9_2_44_dialog_content = "拉斐爾明白！",
  ui_story_8_9_2_45_dialog_content = "達摩克利斯……",
  ui_story_8_9_2_46_dialog_content = "請成為白夜之主的利劍吧，刺穿我們眼前絕望的陰霾……",
  ui_story_8_9_2_47_dialog_content = "達摩克利斯，<color=#FFB400>啟動</color>！",
  ui_story_8_10_1_1_dialog_content = "這、這是怎麼回事？！",
  ui_story_8_10_1_2_dialog_content = "停電了？",
  ui_story_8_10_1_3_dialog_content = "控制室……達摩克利斯的控制室！",
  ui_story_8_10_1_4_dialog_content = "快去看看什麼情況！愣在這幹嘛！",
  ui_story_8_10_1_5_dialog_content = "……",
  ui_story_8_10_1_6_dialog_content = "舒瓦茲，如果這是卡蓮做的，你知道後果嗎？！",
  ui_story_8_10_1_7_dialog_content = "這並非我授意。她是個健全的人，自然擁有選擇的自由。",
  ui_story_8_10_1_8_dialog_content = "但你沒有推卸責任的理由……！",
  ui_story_8_10_1_9_dialog_content = "伊倫汀呢？！讓審判庭的人也……",
  ui_story_8_10_1_10_dialog_content = "審判長已經在控制室門口了！",
  ui_story_8_10_1_11_dialog_content = "高、高庭區域發生騷亂！貴族們突然恐慌起來，大家……",
  ui_story_8_10_1_12_dialog_content = "先維持秩序！別亂，就算啟動達摩克利斯，白夜城的能源也不會馬上就……",
  ui_story_8_10_1_14_dialog_content = "城市……在下降？",
  ui_story_8_10_1_15_dialog_content = "能源都往達摩克利斯匯聚，現在所有基礎設施都在讓路給它。",
  ui_story_8_10_1_16_dialog_content = "還用你說嗎！快做點什麼！",
  ui_story_8_10_1_17_dialog_content = "我早已吩咐衛隊去各個區域做好準備了。你要賦予我調動元老院的權力嗎？",
  ui_story_8_10_1_18_dialog_content = "妳！",
  ui_story_8_10_1_19_dialog_content = "城主、奧托大人！護盾正在……！",
  ui_story_8_10_1_20_dialog_content = "<color=#e8d9bb>與此同時·吞噬者號上</color>",
  ui_story_8_10_1_22_dialog_content = "剛才那個是……？！",
  ui_story_8_10_1_23_dialog_content = "吞噬者號有動作了？外面發生什麼事？",
  ui_story_8_10_1_24_dialog_content = "居——！",
  ui_story_8_10_1_25_dialog_content = "……",
  ui_story_8_10_1_26_dialog_content = "白夜城的護盾……正在消失。",
  ui_story_8_10_1_27_dialog_content = "確定嗎？那可能意味卡蓮成功啟動達摩克利斯了！",
  ui_story_8_10_1_28_dialog_content = "也可能是舒默攻破護盾。我們無法判斷現在的情況。",
  ui_story_8_10_1_29_dialog_content = "……我相信是卡蓮做的。",
  ui_story_8_10_1_30_dialog_content = "等等……為什麼護盾會消失？",
  ui_story_8_10_1_31_dialog_content = "達摩克利斯的充能需要集中白夜城幾乎所有能量，包括維持護盾的能量。",
  ui_story_8_10_1_32_dialog_content = "但這一過程並不會太長，只要能撐過這段時間就……",
  ui_story_8_10_1_34_dialog_content = "糟了，感應出現問題……舒默發現我們了！",
  ui_story_8_10_1_35_dialog_content = "抱歉，因為它突然活躍起來，我沒準備好……",
  ui_story_8_10_1_36_dialog_content = "PlayerName——！！",
  ui_story_8_10_1_37_dialog_content = "舒默……！",
  ui_story_8_10_1_38_dialog_content = "你，為什麼……什麼時候跑掉的？",
  ui_story_8_10_1_39_dialog_content = "先回答我的問題……你到底做了什麼！",
  ui_story_8_10_1_40_dialog_content = "為什麼不接受你的命運？為什麼要做這種沒有意義的反抗？！",
  ui_story_8_10_1_41_dialog_content = "明明你和這座城市一樣，最終都要向我敞開門扉！",
  ui_story_8_10_1_42_dialog_content = "你以為是吞噬者號的攻擊奏效了嗎，你……",
  ui_story_8_10_1_43_dialog_content = "（不，她也許還不知道達摩克利斯的事！）",
  ui_story_8_10_1_F1_dialog_content = "哈哈哈，你是沒見識到吞噬者號的威力吧？",
  ui_story_8_10_1_44_dialog_content = "PlayerName，你不好奇嗎？為什麼我多次擊敗你後，卻沒有對你趕盡殺絕……",
  ui_story_8_10_1_45_dialog_content = "……",
  ui_story_8_10_1_46_dialog_content = "最初是輕視，是憐憫。後來變成了憤怒……對你冥頑不化的憤怒。",
  ui_story_8_10_1_47_dialog_content = "我現在已經受夠了。我終歸只需要向你們這些空裔證明一點就可以了……",
  ui_story_8_10_1_48_dialog_content = "真正的力量，才不是你們口中說的那種東西！！",
  ui_story_8_10_1_49_dialog_content = "我聽不懂你在說什麼！",
  ui_story_8_10_1_50_dialog_content = "你會懂的。",
  ui_story_8_10_1_51_dialog_content = "你會懂的……",
  ui_story_8_10_1_52_dialog_content = "PlayerName，你怎麼了？你還好嗎？快醒醒別發呆了！",
  ui_story_8_10_1_53_dialog_content = "不用擔心，我醒著。我剛才在跟舒默……對話。",
  ui_story_8_10_1_54_dialog_content = "她已經發現我們了！我們必須阻止她！",
  ui_story_8_10_1_55_dialog_content = "同意。走吧，我們必須盡快動作才行！",
  ui_story_8_10_1_56_dialog_content = "居！",
  ui_story_8_10_1_57_dialog_content = "好。只要製造騷亂，盡量干擾舒默就可以了吧？",
  ui_story_8_10_1_58_dialog_content = "希望我們能為卡蓮爭取足夠的時間。",
  ui_story_8_10_2_1_dialog_content = "長官……小心！！",
  ui_story_8_10_2_2_dialog_content = "身體還很僵硬……抱歉，沒派上太大用場……",
  ui_story_8_10_2_3_dialog_content = "長官，要不您在這裡等我們吧！愈靠近它的艦橋，暗鬼就愈多……",
  ui_story_8_10_2_4_dialog_content = "別小看你的長官，薇絲。我怎麼可能讓下屬與後輩孤軍奮戰呢？",
  ui_story_8_10_2_5_dialog_content = "嗚——抓穩了！",
  ui_story_8_10_2_6_dialog_content = "它正在拼命攻擊白夜城……！不知道外面現在……",
  ui_story_8_10_2_7_dialog_content = "……去……三隊！快從……",
  ui_story_8_10_2_8_dialog_content = "……匯合！別自……攻擊它外殼的縫……",
  ui_story_8_10_2_9_dialog_content = "這是！衛隊的通訊？！",
  ui_story_8_10_2_10_dialog_content = "但吞噬者號可以干擾我們的通訊，為什麼……",
  ui_story_8_10_2_11_dialog_content = "也許是近距離接收到的訊號夠強？總之根據通訊內容判斷，他們現在就在外面。",
  ui_story_8_10_2_12_dialog_content = "他們就在外面？衛隊正在攻擊吞噬者號？",
  ui_story_8_10_2_13_dialog_content = "沒錯。一定有大批士兵在附近，而且正在主動出擊……",
  ui_story_8_10_2_14_dialog_content = "……上！別後退，後面可是白夜……",
  ui_story_8_10_2_15_dialog_content = "我……繼續！頂住……不要讓…",
  ui_story_8_10_2_16_dialog_content = "空艇失控！正在墜……不行了！我和這傢伙同歸於盡！",
  ui_story_8_10_2_17_dialog_content = "<color=#e8d9bb>轟——！！</color>",
  ui_story_8_10_2_18_dialog_content = "……",
  ui_story_8_10_2_19_dialog_content = "剛才那是……自殺式攻擊？！",
  ui_story_8_10_2_20_dialog_content = "嗚……",
  ui_story_8_10_2_21_dialog_content = "長官，您的傷勢……",
  ui_story_8_10_2_22_dialog_content = "走吧。沒時間發呆了。",
  ui_story_8_10_2_23_dialog_content = "趁它還沒發展成十七年前那樣……阻止這些暗鬼。",
  ui_story_8_10_2_24_dialog_content = "嗯……",
  ui_story_8_10_2_25_dialog_content = "我們離艦橋已經很近了。確定舒默就在那邊嗎，PlayerName？",
  ui_story_8_10_2_26_dialog_content = "確定。走吧，讓我們結束這一切吧。",
  ui_story_8_10_2_27_dialog_content = "再也沒有任何暗鬼可以阻擋我們前進的道路了。",
  ui_story_8_13_2_1_dialog_content = "老師，我……又失敗了。",
  ui_story_8_13_2_2_dialog_content = "沒關係，再試一次。",
  ui_story_8_13_2_3_dialog_content = "可是我……",
  ui_story_8_13_2_4_dialog_content = "沒有人天生就足夠強大。成長、遭遇困難，不斷失敗再重新站起來……",
  ui_story_8_13_2_5_dialog_content = "你一定可以成為「真正的強者」。",
  ui_story_8_13_2_6_dialog_content = "可是……",
  ui_story_8_13_2_7_dialog_content = "舒默~~",
  ui_story_8_13_2_8_dialog_content = "你們來了。舒默，你的好朋友來了，快去跟她們玩兒吧。今天的訓練結束了。",
  ui_story_8_13_2_9_dialog_content = "對呀！快來，我們可是你的「好朋友」呢！",
  ui_story_8_13_2_10_dialog_content = "哈哈哈哈！",
  ui_story_8_13_2_11_dialog_content = "……",
  ui_story_8_13_2_12_dialog_content = "怎麼了？",
  ui_story_8_13_2_13_dialog_content = "……我……",
  ui_story_8_13_2_14_dialog_content = "……",
  ui_story_8_13_2_15_dialog_content = "我把她們都殺了。",
  ui_story_8_13_2_16_dialog_content = "我親手掐斷她們的脖子，讓骨頭粉碎的聲音連成一首歌。",
  ui_story_8_13_2_17_dialog_content = "一首……歌頌真正力量的歌。",
  ui_story_8_13_2_18_dialog_content = "舒默，狀況如何？",
  ui_story_8_13_2_19_dialog_content = "別打擾我。白夜城已經被攻破了，那群光靈正在做最後的抵抗。",
  ui_story_8_13_2_20_dialog_content = "怎麼樣？我告訴過你，我可以做到！",
  ui_story_8_13_2_22_dialog_content = "我能做到你們沒人做得到的事。哈哈……",
  ui_story_8_13_2_23_dialog_content = "哈哈哈哈……！",
  ui_story_8_13_2_24_dialog_content = "……",
  ui_story_8_13_2_25_dialog_content = "你能別在我面前擋路嗎？",
  ui_story_8_13_2_26_dialog_content = "那名空裔快到了。",
  ui_story_8_13_2_27_dialog_content = "正好，這裡正是屠殺的序幕。讓他進來。",
  ui_story_8_13_2_28_dialog_content = "你不殺他？",
  ui_story_8_13_2_29_dialog_content = "為什麼要？他可是我的「同胞」。",
  ui_story_8_13_2_30_dialog_content = "……可你之前不是……",
  ui_story_8_13_2_31_dialog_content = "煩死了。這個也是，那個也是，為什麼總是要來煩我？",
  ui_story_8_13_2_32_dialog_content = "來吧，PlayerName。最好站到我旁邊。",
  ui_story_8_13_2_33_dialog_content = "看看我變成什麼模樣……睜開你的雙眼，好好看看吧……",
  ui_story_8_14_1_1_dialog_content = "……",
  ui_story_8_14_1_3_dialog_content = "小米迦勒！我來支援你了！",
  ui_story_8_14_1_4_dialog_content = "……？",
  ui_story_8_14_1_5_dialog_content = "卡蓮姐姐嗎？她一切順利！有其他人在幫忙守門了！",
  ui_story_8_14_1_6_dialog_content = "<color=#e8d9bb>達摩克利斯控制室·門外</color>",
  ui_story_8_14_1_7_dialog_content = "讓開！都給老子滾！",
  ui_story_8_14_1_8_dialog_content = "伊倫汀，你在做什麼？！為什麼不攻進去！",
  ui_story_8_14_1_9_dialog_content = "如你所見。",
  ui_story_8_14_1_10_dialog_content = "別那麼急躁嘛，奧托大人……",
  ui_story_8_14_1_11_dialog_content = "退後！我代表元老院，命令你們全都退後！",
  ui_story_8_14_1_F1_dialog_content = "誰叫你們守著控制室的？！給我讓開！",
  ui_story_8_14_1_12_dialog_content = "舒瓦茲呢？！關鍵時刻跑到哪裡去了！不來管管他的女兒嗎？！",
  ui_story_8_14_1_13_dialog_content = "奧托大人，您靜下心來聽我講喔……",
  ui_story_8_14_1_14_dialog_content = "您看看，天上全是暗鬼呢～審判庭和元老院不去幫忙清理好嗎？",
  ui_story_8_14_1_15_dialog_content = "加百列……",
  ui_story_8_14_1_16_dialog_content = "我可以燒光那些暗鬼嗎？",
  ui_story_8_14_1_17_dialog_content = "可以唷～注意別燒到貴族們的房子～",
  ui_story_8_14_1_18_dialog_content = "嗯，可是……應該很難吧……",
  ui_story_8_14_1_19_dialog_content = "……",
  ui_story_8_14_1_20_dialog_content = "加百列，你確定要站在我面前嗎？",
  ui_story_8_14_1_21_dialog_content = "嗯……確定哦。",
  ui_story_8_14_1_22_dialog_content = "啊，不過並不準確，應該是坐在你面前啦～",
  ui_story_8_14_1_23_dialog_content = "審判庭士兵！前進……",
  ui_story_8_14_1_24_dialog_content = "<size=45>你試試？</size>",
  ui_story_8_14_1_25_dialog_content = "樓、樓塌了！背後的樓，快躲開……",
  ui_story_8_14_1_26_dialog_content = "！！",
  ui_story_8_14_1_27_dialog_content = "數量太多了！這樣下去會顧此失彼的！！",
  ui_story_8_14_1_28_dialog_content = "……！！",
  ui_story_8_14_1_29_dialog_content = "明白！撤退回狹窄的地方，我們轉攻為守吧！！",
  ui_story_8_14_1_30_dialog_content = "不能再讓暗鬼越過這片街道了！",
  ui_story_8_14_1_31_dialog_content = "吼——！",
  ui_story_8_14_1_33_dialog_content = "<color=#e8d9bb>達摩克利斯·控制室</color>",
  ui_story_8_14_1_34_dialog_content = "……",
  ui_story_8_14_1_35_dialog_content = "（拉斐爾、米迦勒……還有趕來的加百列她們，都在戰鬥嗎……）",
  ui_story_8_14_1_36_dialog_content = "達摩克利斯……求你了，再快點……",
  ui_story_8_14_1_37_dialog_content = "白夜城的城民，和這座城市……需要你的甦醒……！",
  ui_story_8_14_1_38_dialog_content = "還是太慢了，必須加速充能……哪怕用盡我全部的力量……",
  ui_story_8_14_1_39_dialog_content = "<color=#e8d9bb>吞噬者號·艦橋</color>",
  ui_story_8_14_1_40_dialog_content = "塔樓。",
  ui_story_8_14_1_41_dialog_content = "城牆。",
  ui_story_8_14_1_42_dialog_content = "還有蒼蠅似的空艇……",
  ui_story_8_14_1_43_dialog_content = "戰車已經開始動了，就算你們死一百遍也阻止不了我……",
  ui_story_8_14_1_44_dialog_content = "哈哈哈，已經……沒人可以阻擋我了……！！",
  ui_story_8_14_1_45_dialog_content = "舒默。",
  ui_story_8_14_1_46_dialog_content = "PlayerName。",
  ui_story_8_14_1_47_dialog_content = "氣喘吁吁的，很急嗎？演出才剛開始呢。",
  ui_story_8_14_1_48_dialog_content = "過來，坐吧。",
  ui_story_8_14_1_49_dialog_content = "住手……停下來。不要再繼續了……",
  ui_story_8_14_1_50_dialog_content = "PlayerName！她現在正忙於操控吞噬者號，我們可以趁機……",
  ui_story_8_14_1_51_dialog_content = "薇絲，左邊。",
  ui_story_8_14_1_52_dialog_content = "吼……",
  ui_story_8_14_1_53_dialog_content = "是高級暗鬼！",
  ui_story_8_14_1_54_dialog_content = "氣息很特殊。那傢伙看起來打算繼續攻擊我們……",
  ui_story_8_14_1_55_dialog_content = "讓他們過來，雜種。不要壞了我的興致。",
  ui_story_8_14_1_56_dialog_content = "這場演出好不容易開幕，沒人看就太浪費了。",
  ui_story_8_14_1_57_dialog_content = "……舒默，妳一次次地忤逆吞羅大人的命令，甚至在這種時候都執迷不悟。",
  ui_story_8_14_1_58_dialog_content = "我無權阻止你做這些，但你也沒有立場命令我。",
  ui_story_8_14_1_59_dialog_content = "我們，包括大人們，也都只效忠於母親一人……而不是一己私慾！",
  ui_story_8_14_1_60_dialog_content = "開口閉口都母親、母親、母親……無聊死了。",
  ui_story_8_14_1_61_dialog_content = "PlayerName，如你所見，我現在很忙。",
  ui_story_8_14_1_62_dialog_content = "白夜城的毀滅，無論如何我都要你親眼見證。所以……",
  ui_story_8_14_1_63_dialog_content = "說起來還是第一次拜託你呢……快點殺掉這只暗鬼，到我旁邊來。",
  ui_story_8_14_1_64_dialog_content = "你……？！",
  ui_story_8_14_1_65_dialog_content = "這又是什麼陰謀詭計嗎？PlayerName，請務必小心！",
  ui_story_8_14_1_66_dialog_content = "我知道。但她有一點說對了。無論如何，我們都得先解決這個傢伙！",
  ui_story_8_14_1_67_dialog_content = "久仰「大名」，空裔，還有這位光靈。",
  ui_story_8_14_1_68_dialog_content = "你們製造夠多麻煩了。我必須貫徹日蝕與母親的意志，所以……",
  ui_story_8_14_1_69_dialog_content = "來吧。",
  ui_story_8_14_1_70_dialog_content = "……別讓我失望啊，PlayerName。",
  ui_story_8_14_2_1_dialog_content = "不、不可能……這不可能！",
  ui_story_8_14_2_2_dialog_content = "再給我次機會，吞羅大人，母親大人！賜予我力量，再讓我……",
  ui_story_8_14_2_3_dialog_content = "話太多了……",
  ui_story_8_14_2_4_dialog_content = "嗚啊——！",
  ui_story_8_14_2_5_dialog_content = "舒默……叛徒……！",
  ui_story_8_14_2_6_dialog_content = "叛徒？狗屁。我從來沒說過要效忠任何人。",
  ui_story_8_14_2_7_dialog_content = "舒默……結束了。",
  ui_story_8_14_2_8_dialog_content = "嗯？什麼結束了？這不是才剛開始嗎？",
  ui_story_8_14_2_9_dialog_content = "吞噬者號……建立感應！",
  ui_story_8_14_2_10_dialog_content = "PlayerName！",
  ui_story_8_14_2_11_dialog_content = "你幹什麼！",
  ui_story_8_14_2_12_dialog_content = "我要阻止你……我要阻止你的巨像！",
  ui_story_8_14_2_13_dialog_content = "你操控不了他的。吞噬者號就是我，而我就是他，你不可能操控他！",
  ui_story_8_14_2_14_dialog_content = "我不可能操控他？我只知道我不能讓你繼續靠近白夜城……",
  ui_story_8_14_2_15_dialog_content = "那裡，是光靈們的住所……是大家的家……",
  ui_story_8_14_2_16_dialog_content = "也是我重要的夥伴們……在的地方！！",
  ui_story_8_14_2_18_dialog_content = "所以……哪怕拼上全部……呃啊啊啊……！！",
  ui_story_8_14_2_19_dialog_content = "PlayerName！你的鼻血！！",
  ui_story_8_14_2_20_dialog_content = "別過來！！去攻擊……攻擊舒默！！",
  ui_story_8_14_2_21_dialog_content = "我說了，你不可能操控他……",
  ui_story_8_14_2_22_dialog_content = "薇絲、小心！！",
  ui_story_8_14_2_23_dialog_content = "（再次感應吞噬者號——！）",
  ui_story_8_14_2_24_dialog_content = "沒完沒了嗎，PlayerName？！",
  ui_story_8_14_2_25_dialog_content = "沒錯。除非我死……否則我不會放棄！",
  ui_story_8_14_2_26_dialog_content = "舒默！妳已經沒有勝算了！！",
  ui_story_8_14_2_27_dialog_content = "哈？你知道自己在說什麼嗎？你給我睜大眼睛看著！！",
  ui_story_8_14_2_28_dialog_content = "白夜城已經完了！它的士兵，它的龜殼，一切都完了！！",
  ui_story_8_14_2_29_dialog_content = "我做到了，PlayerName！！我做到沒人做得到的事！",
  ui_story_8_14_2_30_dialog_content = "為什麼不願意承認？！在絕對的力量面前只需要臣服就好了，為什麼要抬起頭？！",
  ui_story_8_14_2_31_dialog_content = "吞噬者號，關閉……引擎……",
  ui_story_8_14_2_32_dialog_content = "他是我的巨像！",
  ui_story_8_14_2_33_dialog_content = "呃啊啊啊啊啊啊啊啊——！！！",
  ui_story_8_14_2_35_dialog_content = "唔……呃，頭，頭暈，我……",
  ui_story_8_14_2_36_dialog_content = "PlayerName……",
  ui_story_8_14_2_37_dialog_content = "抱歉，我和長官……無法突破舒默的防禦。",
  ui_story_8_14_2_38_dialog_content = "看見這個差距了嗎？你，還有這些沒用的人，要怎麼跨越這條鴻溝？",
  ui_story_8_14_2_39_dialog_content = "看著就好了，PlayerName。我不想折磨你，特別是現在這個時候——",
  ui_story_8_14_2_40_dialog_content = "我需要你的見證。作為空裔的，見證……",
  ui_story_8_14_2_41_dialog_content = "……嗯？",
  ui_story_8_14_2_42_dialog_content = "……？",
  ui_story_8_14_2_43_dialog_content = "（為什麼……周圍……好像變安靜了？）",
  ui_story_8_14_2_44_dialog_content = "……",
  ui_story_8_14_2_45_dialog_content = "……你們又在搞什麼小動作？",
  ui_story_8_14_2_46_dialog_content = "（舒默也不知道是怎麼回事？這並不是她做的？）",
  ui_story_8_14_2_47_dialog_content = "嗯？",
  ui_story_8_14_2_48_dialog_content = "為什麼……有一種渾身起雞皮疙瘩的感覺……",
  ui_story_8_14_2_49_dialog_content = "薇絲……空氣的味道，發生了變化。",
  ui_story_8_14_2_50_dialog_content = "不，還有聲音……為什麼聲音都消失了？",
  ui_story_8_14_2_51_dialog_content = "的確，太安靜了。怎麼會一點動靜都沒有……",
  ui_story_8_14_2_52_dialog_content = "薇絲，快看地面！",
  ui_story_8_14_2_53_dialog_content = "地上的塵土，似乎都朝同個方向……移動……",
  ui_story_8_14_2_54_dialog_content = "也許是風。感受到了嗎？空氣也在朝某處匯聚，就好像……",
  ui_story_8_14_2_55_dialog_content = "有什麼在累積……？",
  ui_story_8_14_2_56_dialog_content = "各位……這種感覺，不太妙！",
  ui_story_8_14_2_58_dialog_content = "PlayerName、長官，壓低身體，找個東西抓穩……",
  ui_story_8_14_2_59_dialog_content = "如果我想得沒錯的話……時間到了。",
  ui_story_8_14_2_62_dialog_content = "白夜城的上空……是什麼東西？",
  ui_story_8_14_2_63_dialog_content = "哪來的光點？",
  ui_story_8_14_2_64_dialog_content = "……",
  ui_story_8_14_2_65_dialog_content = "……白夜至上。我的誓詞宣讀完畢。",
  ui_story_8_14_2_66_dialog_content = "舒默……空裔的叛徒，由我卡蓮·德·舒瓦茲，賜予妳最終的……",
  ui_story_8_14_2_67_dialog_content = "裁決！！！",
  ui_story_8_14_2_68_dialog_content = "那是？！",
  ui_story_8_14_2_69_dialog_content = "大家快趴下！！",
  ui_story_8_14_2_70_dialog_content = "<color=#e8d9bb>轟——！！</color>",
  ui_story_8_14_2_73_dialog_content = "（什麼？！光砲……？我的眼睛……！）",
  ui_story_8_14_2_74_dialog_content = "（我……為什麼動不了？為什麼……我為什麼動不了？！）",
  ui_story_8_14_2_75_dialog_content = "（舒默……）",
  ui_story_8_14_2_76_dialog_content = "（你！！！）",
  ui_story_8_14_2_77_dialog_content = "（我說過……除非我、死掉……否則我會一直，阻止你的……）",
  ui_story_8_14_2_78_dialog_content = "（你以為這樣就能阻止我嗎？！）",
  ui_story_8_14_2_82_dialog_content = "舒默！！",
  ui_story_8_14_2_83_dialog_content = "休想做任何垂死掙扎！！",
  ui_story_8_14_2_F1_dialog_content = "達摩克利斯的光束！會擊穿妳和妳的吞噬者號！",
  ui_story_8_14_2_84_dialog_content = "（卡——卡蓮！！）",
  ui_story_8_14_2_87_dialog_content = "吞噬者號，閃避！改道！！",
  ui_story_8_14_2_88_dialog_content = "不會……讓你逃走……唔啊啊啊……！！",
  ui_story_8_14_2_89_dialog_content = "離開砲口上方！給我動起來啊！！",
  ui_story_8_14_2_90_dialog_content = "（一定要……竭盡全力！不能讓這座巨像離開！！）",
  ui_story_8_14_2_91_dialog_content = "放開我的巨像，PlayerName！！斷開你的感應！",
  ui_story_8_14_2_92_dialog_content = "（不行……光束……打不中了？！）",
  ui_story_8_14_2_93_dialog_content = "卡蓮，妳的光能很弱了！妳無法繼續引導光束！靠邊！",
  ui_story_8_14_2_94_dialog_content = "？！",
  ui_story_8_14_2_95_dialog_content = "您、為什麼！",
  ui_story_8_14_2_96_dialog_content = "幫你指引達摩克利斯，僅此而已！",
  ui_story_8_14_2_97_dialog_content = "別回頭，看前方。你的目標在前面不是嗎？",
  ui_story_8_14_2_98_dialog_content = "還記得擊潰敵人的最後一步，最忌諱什麼嗎！",
  ui_story_8_14_2_99_dialog_content = "當然，父親！",
  ui_story_8_14_2_100_dialog_content = "「穿透敵人胸膛之前，決不能減弱手握長槍的力量」！",
  ui_story_8_14_2_101_dialog_content = "（會、會死！這樣下去、我會——）",
  ui_story_8_14_2_102_dialog_content = "（給我滾！滾啊，PlayerName！！！）",
  ui_story_8_14_2_103_dialog_content = "舒默！！",
  ui_story_8_14_2_104_dialog_content = "我要妳在死的時候，直視我的眼睛！！！",
  ui_story_8_14_2_105_dialog_content = "不、不——",
  ui_story_8_14_2_106_dialog_content = "不！！！！！！",
  ui_story_8_14_2_112_dialog_content = "舒默。",
  ui_story_8_14_2_113_dialog_content = "嗯？老師，我在。",
  ui_story_8_14_2_114_dialog_content = "你……為什麼要這麼做？",
  ui_story_8_14_2_115_dialog_content = "……",
  ui_story_8_14_2_116_dialog_content = "你……",
  ui_story_8_14_2_117_dialog_content = "……為什麼要……殺掉我們？",
  ui_story_8_14_2_118_dialog_content = "我將用餘生詛咒你，舒默……叛徒，空裔的敗類，我的失敗之作……",
  ui_story_8_14_2_119_dialog_content = "我詛咒妳在死亡的時候比我們痛苦一百倍，舒默……",
  ui_story_8_14_2_120_dialog_content = "我詛咒你，永生永世……",
  ui_story_8_14_2_121_dialog_content = "……不得……安寧…………",
  ui_story_8_15_1_1_dialog_content = "你來晚了，吞羅。",
  ui_story_8_15_1_2_dialog_content = "這地方也太遠了。有必要藏到這裡嗎？",
  ui_story_8_15_1_3_dialog_content = "東西呢？",
  ui_story_8_15_1_4_dialog_content = "還在舒默身上。已經快了，別催我。",
  ui_story_8_15_1_5_dialog_content = "為什麼要縱容舒默攻擊白夜城？你要做的事很簡單，只要讓她體內的……",
  ui_story_8_15_1_6_dialog_content = "小孩子，不懂事唄。",
  ui_story_8_15_1_7_dialog_content = "很重要嗎？",
  ui_story_8_15_1_8_dialog_content = "……",
  ui_story_8_15_1_9_dialog_content = "別忘了你的身分，光靈。",
  ui_story_8_15_1_10_dialog_content = "呵——欠。",
  ui_story_8_15_1_11_dialog_content = "……以上，就是關於下城區的損失報告。然後是對衛隊長的處罰……",
  ui_story_8_15_1_12_dialog_content = "好了，先這樣吧。",
  ui_story_8_15_1_13_dialog_content = "你先出去，五分鐘後再進來繼續匯報。",
  ui_story_8_15_1_14_dialog_content = "是！",
  ui_story_8_15_1_15_dialog_content = "說吧。",
  ui_story_8_15_1_16_dialog_content = "好久不見，舒瓦茲。",
  ui_story_8_15_1_17_dialog_content = "你來慰問我的？",
  ui_story_8_15_1_18_dialog_content = "哈哈哈，你相信嗎？",
  ui_story_8_15_1_19_dialog_content = "作為一個連底牌都被翻開的人，你心態還算不錯。",
  ui_story_8_15_1_20_dialog_content = "不過是從一副牌打出一張而已，全當消遣。",
  ui_story_8_15_1_21_dialog_content = "而且，現在可不只我一人在守護這座城市了。",
  ui_story_8_15_1_22_dialog_content = "我對子女教育沒什麼興趣，就說到這吧。",
  ui_story_8_15_1_23_dialog_content = "倒是我這段時間沒幫上忙，沒放心上吧？",
  ui_story_8_15_1_24_dialog_content = "別多想，這只是因為我相信白夜城的力量，永不淪陷之都的主人。",
  ui_story_8_15_1_25_dialog_content = "而且我這邊也發生相當有趣的事呢……你很快就知道了。",
  ui_story_8_15_1_26_dialog_content = "好。啟光聯邦能做到什麼地步，就讓我們拭目以待吧。",
  ui_story_8_15_1_27_dialog_content = "搖曳的火苗，終於要把夜幕撕開一道開口了……",
  ui_story_8_15_1_28_dialog_content = "為了啟明之光……！",
  ui_story_9_1_1_1_dialog_content = "兩位可以進去旁聽了。",
  ui_story_9_1_1_2_dialog_content = "謝謝……PlayerName，我們走。",
  ui_story_9_1_1_3_dialog_content = "<color=#e8d9bb>吱——呀——</color>",
  ui_story_9_1_1_4_dialog_content = "薇絲，我還不知道……",
  ui_story_9_1_1_5_option_content = "這是什麼地方。",
  ui_story_9_1_1_6_dialog_content = "這是位於白夜城高庭的審判庭。",
  ui_story_9_1_1_7_dialog_content = "台上那位手持長杖的女士應該就是審判長<color=#FFB400>伊倫汀</color>。",
  ui_story_9_1_1_8_option_content = "那些人都是誰？",
  ui_story_9_1_1_9_dialog_content = "如果我沒有猜錯……",
  ui_story_9_1_1_10_dialog_content = "台上那位手持長杖的女士，應該就是掌管這座審判庭的審判長<color=#FFB400>伊倫汀</color>。",
  ui_story_9_1_1_11_dialog_content = "她旁邊那位不苟言笑的男人……",
  ui_story_9_1_1_12_dialog_content = "……我……記得！那是卡蓮的父親吧？",
  ui_story_9_1_1_13_dialog_content = "對，那就是白夜城城主——<color=#FFB400>狄安理·德·舒瓦茲</color>。",
  ui_story_9_1_1_14_dialog_content = "不知道為什麼有點不寒而慄……",
  ui_story_9_1_1_15_dialog_content = "噓……",
  ui_story_9_1_1_16_dialog_content = "……",
  ui_story_9_1_1_17_dialog_content = "看來你們就是卡蓮衛隊長提到的「夥伴」。",
  ui_story_9_1_1_18_dialog_content = "咳咳……您好，城主大人。",
  ui_story_9_1_1_19_dialog_content = "我是來自啟光聯邦的薇絲。這位是PlayerName。",
  ui_story_9_1_1_20_dialog_content = "……您好，我是PlayerName。",
  ui_story_9_1_1_21_dialog_content = "免禮。",
  ui_story_9_1_1_22_dialog_content = "聽聞你們為了拖延敵方的攻擊，奮勇迎敵，在護城戰中發揮了非常關鍵的作用。",
  ui_story_9_1_1_23_dialog_content = "我在此向你們表達謝意。",
  ui_story_9_1_1_24_dialog_content = "謝謝城主大人，我們也只是做了些力所能及的事情。",
  ui_story_9_1_1_25_dialog_content = "近來傷勢如何，有好點嗎？",
  ui_story_9_1_1_26_dialog_content = "多虧您派人幫我們治療，我們已經好多了。",
  ui_story_9_1_1_27_dialog_content = "甚好。啟光聯邦此前在危急時刻派來援兵相助，這份情誼白夜城不會忘記。",
  ui_story_9_1_1_28_dialog_content = "也請代我向啟光民眾轉達白夜城的感激。",
  ui_story_9_1_1_29_dialog_content = "好的，城主大人。我一定會代為轉達。",
  ui_story_9_1_1_X29_dialog_content = "好。",
  ui_story_9_1_1_X30_dialog_content = "那麼審判長，妳可以宣布開庭了。",
  ui_story_9_1_1_X31_dialog_content = "是，城主殿下。",
  ui_story_9_1_1_30_dialog_content = "現在開庭，請當事人入庭。",
  ui_story_9_1_1_31_dialog_content = "是！",
  ui_story_9_1_1_32_dialog_content = "（卡蓮……）",
  ui_story_9_1_1_33_dialog_content = "白夜至上。",
  ui_story_9_1_1_34_dialog_content = "我謹代表審判庭，在此宣讀對卡蓮·德·舒瓦茲的審判結果。",
  ui_story_9_1_1_35_dialog_content = "卡蓮·德·舒瓦茲，現任白夜城近衛隊長。",
  ui_story_9_1_1_36_dialog_content = "現已查明，其在任職期間——",
  ui_story_9_1_1_37_dialog_content = "越過三方決議，挾持騎士長强闖控制室，擅自啟動達摩克利斯。",
  ui_story_9_1_1_38_dialog_content = "其行為直接導致白夜城護盾失效，間接導致白夜城高庭、中庭遭到襲擊。",
  ui_story_9_1_1_39_dialog_content = "最終造成貴族一百零八人輕重傷，僕役傷亡不計，另導致大量財產受損。",
  ui_story_9_1_1_40_dialog_content = "此人行為違反了白夜城法律，應予重罰。",
  ui_story_9_1_1_41_dialog_content = "然而念其最終擊敗進攻者，守護白夜城有功。依照法理、考慮功過。",
  ui_story_9_1_1_42_dialog_content = "經審判庭決議，判處卡蓮·德·舒瓦茲——停職察看一年……",
  ui_story_9_1_1_43_dialog_content = "荒謬！豈有此理！怎麼會如此判決？！",
  ui_story_9_1_1_44_dialog_content = "……",
  ui_story_9_1_1_45_dialog_content = "她的所作所為，是在拿白夜城所有貴族的性命當賭注！",
  ui_story_9_1_1_46_dialog_content = "這次只不過是僥倖。如果就這樣放過她，誰知道下次她還會幹出什麼勾當？",
  ui_story_9_1_1_47_dialog_content = "舒瓦茲，你這不會是在勾結審判庭，明目張膽地包庇令嬡吧？",
  ui_story_9_1_1_48_dialog_content = "奧托·特洛伊，當庭打斷審判長的宣判，並非貴族應有的禮儀。",
  ui_story_9_1_1_49_dialog_content = "哼。",
  ui_story_9_1_1_50_dialog_content = "審判長，請繼續。",
  ui_story_9_1_1_51_dialog_content = "經審判庭決議，判處卡蓮·德·舒瓦茲——停職察看一年。",
  ui_story_9_1_1_52_dialog_content = "一年之內，卡蓮·德·舒瓦茲必須查清白夜城遇襲的真相。",
  ui_story_9_1_1_53_dialog_content = "給白夜城所有貴族一個交代。",
  ui_story_9_1_1_54_dialog_content = "若無法及時查清，則審判庭將撤銷卡蓮·德·舒瓦茲的職位、貴族身分……",
  ui_story_9_1_1_55_dialog_content = "……以及白夜城居住權。",
  ui_story_9_1_1_56_dialog_content = "白夜至上，願「光之神」保佑白夜子民。",
  ui_story_9_1_1_57_dialog_content = "白夜至上。",
  ui_story_9_1_1_58_dialog_content = "薇絲、PlayerName，走這邊。",
  ui_story_9_1_1_59_dialog_content = "卡蓮，妳……還好嗎？",
  ui_story_9_1_1_60_dialog_content = "我很好，多謝關心。",
  ui_story_9_1_1_61_dialog_content = "倒是你，PlayerName，身體已經痊癒了嗎？",
  ui_story_9_1_1_62_dialog_content = "剛剛的氣氛太嚇人了……",
  ui_story_9_1_1_63_dialog_content = "……讓大家見笑了。",
  ui_story_9_1_1_64_dialog_content = "看來PlayerName的身體已經痊癒了。",
  ui_story_9_1_1_65_dialog_content = "痊癒是痊癒了……哈哈……",
  ui_story_9_1_1_66_dialog_content = "剛剛那個叫奧托的人……",
  ui_story_9_1_1_67_dialog_content = "那位審判長還沒宣讀完，他就開始那麼大聲反對。",
  ui_story_9_1_1_68_dialog_content = "一點都不尊重在場的城主和卡蓮，真是太過分了！",
  ui_story_9_1_1_69_dialog_content = "卡蓮明明是為了保護白夜城，才去啟動達摩克利斯的。",
  ui_story_9_1_1_70_dialog_content = "而且最後都已經擊敗敵人了。",
  ui_story_9_1_1_71_dialog_content = "他怎麼好像還覺得卡蓮是犯了什麼十惡不赦的大罪一樣？",
  ui_story_9_1_1_72_dialog_content = "渾身上下都是白夜城老貴族的迂腐習氣，不可理喻！",
  ui_story_9_1_1_73_dialog_content = "……",
  ui_story_9_1_1_74_dialog_content = "……！",
  ui_story_9_1_1_75_dialog_content = "對不起，我不是想說白夜城的壞話……",
  ui_story_9_1_1_76_dialog_content = "沒關係，我相信妳沒有惡意。同樣地，我也相信白夜城的律法和審判。",
  ui_story_9_1_1_77_dialog_content = "就算審判庭沒有下令，我也會自己去查個清楚。",
  ui_story_9_1_1_78_dialog_content = "我明白妳的心情，我也有……想要查明的真相。",
  ui_story_9_1_1_79_dialog_content = "可是，審判庭既然要卡蓮去執行調查，為什麼不多給一點兵力呢？",
  ui_story_9_1_1_80_dialog_content = "也許……城主殿下從一開始就沒有將舒默當作威脅……",
  ui_story_9_1_1_81_dialog_content = "這……怎麼會？",
  ui_story_9_1_1_82_dialog_content = "審判結束後，我單獨見過城主殿下……",
  ui_story_9_1_1_83_dialog_content = "父親，有關舒默襲擊白夜城一事……我有一些問題想請教。",
  ui_story_9_1_1_84_dialog_content = "說吧。",
  ui_story_9_1_1_85_dialog_content = "面對舒默的襲擊，白夜城當初為何毫無反擊的打算……",
  ui_story_9_1_1_86_dialog_content = "反而放任對方攻擊護盾？",
  ui_story_9_1_1_87_dialog_content = "卡蓮，妳身為高庭衛隊隊長，明白自己的職責嗎？",
  ui_story_9_1_1_88_dialog_content = "這……？",
  ui_story_9_1_1_89_dialog_content = "明白，衛隊的職責便是保護民眾。",
  ui_story_9_1_1_90_dialog_content = "恕請直言，我不明白您為何迴避我的問題，轉而問我與此無關的事情。",
  ui_story_9_1_1_91_dialog_content = "看來妳確實不明白。",
  ui_story_9_1_1_92_dialog_content = "高庭衛隊原本負責守衛高庭，也就是上層貴族所居住的區域。",
  ui_story_9_1_1_93_dialog_content = "近幾年由於人手不足，高庭衛隊的管轄範圍才有所增加。",
  ui_story_9_1_1_94_dialog_content = "承擔了一部分下城區的治安。",
  ui_story_9_1_1_95_dialog_content = "實際上，在眾人看來，妳的職責應該是守護上層貴族的安全。",
  ui_story_9_1_1_96_dialog_content = "……",
  ui_story_9_1_1_97_dialog_content = "我想妳應該意識到自己的錯誤了。",
  ui_story_9_1_1_98_dialog_content = "至於妳剛才的問題……",
  ui_story_9_1_1_99_dialog_content = "妳真的認為那種東西能夠攻破白夜城的護盾嗎？",
  ui_story_9_1_1_100_dialog_content = "父親，您的意思是……？",
  ui_story_9_1_1_101_dialog_content = "自己想想吧，我還有下一場會議要出席。",
  ui_story_9_1_1_102_dialog_content = "……",
  ui_story_9_1_1_103_dialog_content = "城主大人這話是什麼意思……？",
  ui_story_9_1_1_104_dialog_content = "我也猜不透，那個男人到底在想些什麼……",
  ui_story_9_1_1_105_dialog_content = "白夜城也好……啟光也好……也許根本輪不到我去操心……",
  ui_story_9_1_1_106_dialog_content = "我……只想找到過去的真相！",
  ui_story_9_1_1_107_dialog_content = "PlayerName……",
  ui_story_9_1_1_108_dialog_content = "咳咳，不過現在回想起來，還是有些膽戰心驚呢。",
  ui_story_9_1_1_109_dialog_content = "光砲都打到眼前了，PlayerName還是一動不動！",
  ui_story_9_1_1_110_dialog_content = "我和薇薇安長官怎麼拉都拉不走。",
  ui_story_9_1_1_111_dialog_content = "幸好居里也來幫忙，我們才在光砲命中吞噬者號之前順利逃脫。",
  ui_story_9_1_1_112_dialog_content = "當時我只顧著不讓吞噬者號逃跑……",
  ui_story_9_1_1_113_dialog_content = "還是多虧卡蓮，最後指引達摩克利斯命中了吞噬者號。",
  ui_story_9_1_1_114_dialog_content = "……",
  ui_story_9_1_1_115_dialog_content = "您、為什麼！",
  ui_story_9_1_1_116_dialog_content = "幫你指引達摩克利斯，僅此而已！",
  ui_story_9_1_1_117_dialog_content = "……守護白夜城，本就是我的使命。",
  ui_story_9_1_1_118_dialog_content = "話說薇薇安和居里呢，已經回啟光了嗎？",
  ui_story_9_1_1_119_dialog_content = "薇薇安長官和居里還留在白夜城的醫院裡……",
  ui_story_9_1_1_120_dialog_content = "不用擔心，她們雖然傷勢較重，但生命沒有大礙，現在只是需要靜養一陣子。",
  ui_story_9_1_1_X120_dialog_content = "居里主要是傷了翅膀，已經恢復得差不多了，一直守在薇薇安身邊。",
  ui_story_9_1_1_121_dialog_content = "那就好……不過……",
  ui_story_9_1_1_122_dialog_content = "舒默真的死了嗎？",
  ui_story_9_1_1_123_dialog_content = "我們逃出吞噬者號前，舒默一直留在艦橋，好像沒辦法動彈。",
  ui_story_9_1_1_124_dialog_content = "這樣正面吃下達摩克利斯的攻擊，應該沒有生物能活下來吧。",
  ui_story_9_1_1_125_dialog_content = "PlayerName，我想我知道你在擔心什麼。",
  ui_story_9_1_1_126_dialog_content = "不找到舒默的屍體，我也不會罷休。",
  ui_story_9_1_1_X126_dialog_content = "不過在那之前，我還有一個重要任務。",
  ui_story_9_1_1_X127_dialog_content = "嗯？還有什麼任務？",
  ui_story_9_1_1_X128_dialog_content = "帶你們去見臨空者號。",
  ui_story_9_1_1_127_dialog_content = "我們請來了能夠修理臨空者號的人，據說已經修理完畢了。",
  ui_story_9_1_1_128_dialog_content = "<color=#FFB400>臨空者</color>！！！",
  ui_story_9_1_1_129_dialog_content = "沒有回應……",
  ui_story_9_1_1_130_dialog_content = "嘿，來得正好。",
  ui_story_9_1_1_131_dialog_content = "貢露前輩？！妳不是在迦南城休假嗎？",
  ui_story_9_1_1_132_dialog_content = "嘿嘿，好不容易觸發的「支線任務」，我可不會錯過。何況還是巨像！",
  ui_story_9_1_1_133_dialog_content = "是拉斐爾叫來了無敵搭檔小露喔~",
  ui_story_9_1_1_134_dialog_content = "當年拉斐爾剛前往啟光交流的時候，我們就一拍即合、一見如故、一見傾心——",
  ui_story_9_1_1_135_dialog_content = "好啦，不用一一回溯啦。",
  ui_story_9_1_1_136_dialog_content = "總之，我已經找到材料，幫PlayerName把巨像修補好了~",
  ui_story_9_1_1_137_dialog_content = "看在上次PlayerName幫我回復HP的份上，這次我就勉強不收「任務報酬」啦。",
  ui_story_9_1_1_138_dialog_content = "這麼快就修補好了嗎？",
  ui_story_9_1_1_139_dialog_content = "我記得臨空者號當時被暗鬼拆得亂七八糟的……",
  ui_story_9_1_1_140_dialog_content = "現在好像完全看不出被破壞的痕跡了！",
  ui_story_9_1_1_141_dialog_content = "好厲害！真不愧是我們啟光的科研長！",
  ui_story_9_1_1_142_dialog_content = "拉斐爾也有幫忙喔！",
  ui_story_9_1_1_143_dialog_content = "謝謝，謝謝大家……那現在……",
  ui_story_9_1_1_144_dialog_content = "臨空者的所有機能都已經恢復了嗎？",
  ui_story_9_1_1_145_dialog_content = "主控系統、生物模組、維生系統……都沒什麼問題了。",
  ui_story_9_1_1_146_dialog_content = "我還趁機幫你調高了引擎功率喔~",
  ui_story_9_1_1_147_dialog_content = "這些用來修補的材料……",
  ui_story_9_1_1_148_dialog_content = "不愧是空裔，可以感應得到嗎？",
  ui_story_9_1_1_149_dialog_content = "我感應到了……<color=#FFB400>守祕者號</color>的氣息。",
  ui_story_9_1_1_150_dialog_content = "鑑定發現，臨空者號的基本建材，與守祕者號的相似度高達百分之九十九點九。",
  ui_story_9_1_1_151_dialog_content = "守祕者號已經喪失了巨像的功能……",
  ui_story_9_1_1_152_dialog_content = "所以我就回收了可用的材料，安裝在臨空者號上啦。",
  ui_story_9_1_1_153_dialog_content = "<color=#FFB400>孟德爾頌</color>！我與你分享我的臨空者號！",
  ui_story_9_1_1_154_dialog_content = "現在以及未來，他會永遠做你在世間的雙耳與眼眸，盡收雲端之上的光景……",
  ui_story_9_1_1_155_dialog_content = "這就是……死亡嗎……和想像中，稍微有些……不一樣呢……好孤獨……",
  ui_story_9_1_1_156_dialog_content = "（孟德爾頌，最終還是你和守祕者號幫助了我們……）",
  ui_story_9_1_1_157_dialog_content = "只是，為什麼我還是感應不到臨空者的意識……",
  ui_story_9_1_1_158_dialog_content = "那個……我在艦橋找到了一樣長得像組件的東西。",
  ui_story_9_1_1_159_dialog_content = "但它被破壞得太嚴重了，只剩下這一小塊看起來比較完整。",
  ui_story_9_1_1_160_dialog_content = "這是……我記得臨空者以前說過，意識模組裡有一個部分叫作「核心」。",
  ui_story_9_1_1_161_dialog_content = "他的「意識」其實是「裝」在核心裡的。",
  ui_story_9_1_1_162_dialog_content = "如果這東西就是「核心」，那臨空者的意識就有可能恢復了！",
  ui_story_9_1_1_163_dialog_content = "太好了！這就是那個核心吧？",
  ui_story_9_1_1_164_dialog_content = "這……應該是吧？臨空者跟我說過模組的事，但並沒有給我看過……",
  ui_story_9_1_1_165_dialog_content = "唔，這東西也沒辦法拆開給你看吧？",
  ui_story_9_1_1_166_dialog_content = "所以……妳覺得這個是核心嗎？",
  ui_story_9_1_1_167_dialog_content = "應該……沒錯。",
  ui_story_9_1_1_168_dialog_content = "那你知道這個怎麼修嗎？",
  ui_story_9_1_1_169_dialog_content = "……",
  ui_story_9_1_1_170_dialog_content = "我……",
  ui_story_9_1_1_171_dialog_content = "PlayerName跟貢露前輩都不知道怎麼修嗎……？",
  ui_story_9_1_1_172_dialog_content = "很抱歉。",
  ui_story_9_1_1_173_dialog_content = "以我的能力，還沒辦法解讀這種舊時代的技術。",
  ui_story_9_1_1_174_dialog_content = "我……只向臨空者學過一點點的巨像知識。",
  ui_story_9_1_1_175_dialog_content = "但我從來沒想過這有什麼問題，也沒想過有一天……我會失去他。",
  ui_story_9_1_1_X175_dialog_content = "如果我再多關心一下臨空者，或許……",
  ui_story_9_1_1_176_dialog_content = "這是一場考驗，PlayerName。享受孤獨、磨練意志，這樣才能成為強者。",
  ui_story_9_1_1_177_dialog_content = "現實是你還活著，而我要確保你繼續活下去。",
  ui_story_9_1_1_178_dialog_content = "PlayerName，我可以懸停在白夜城的上空，隨時接應你們。",
  ui_story_9_1_1_179_dialog_content = "那就委屈你了，臨空者。",
  ui_story_9_1_1_180_dialog_content = "臨空者，你聽得到的，對嗎？",
  ui_story_9_1_1_181_dialog_content = "對不起……是我……",
  ui_story_9_1_1_182_dialog_content = "是我沒有保護好你。我當時怎麼那麼大意……",
  ui_story_9_1_1_183_dialog_content = "PlayerName……",
  ui_story_9_1_1_184_dialog_content = "咦？拉斐爾不懂，現在的巨像明明比之前更堅固了。",
  ui_story_9_1_1_185_dialog_content = "為什麼PlayerName還這麼傷心？",
  ui_story_9_1_1_186_dialog_content = "拉斐爾，別多話。",
  ui_story_9_1_1_187_dialog_content = "唔，對不起……",
  ui_story_9_1_1_188_dialog_content = "PlayerName，當時你是為了保護白夜城的民眾，才離開臨空者號的。",
  ui_story_9_1_1_189_dialog_content = "這件事我也有責任。",
  ui_story_9_1_1_190_dialog_content = "大家這麼幫我，我已經很感激了。臨空者的事，不能怪大家。",
  ui_story_9_1_1_191_dialog_content = "一切……都是舒默和那些暗鬼造成的！",
  ui_story_9_1_1_192_dialog_content = "舒默……啊！差點就忘記了……",
  ui_story_9_1_1_193_dialog_content = "拉斐爾有個重要的消息要告訴卡蓮姐姐……",
  ui_story_9_1_1_194_dialog_content = "什麼事？",
  ui_story_9_1_1_195_dialog_content = "騎士團調查後發現，吞噬者號墜落到<color=#FFB400>空之山谷</color>的方向了！",
  ui_story_9_1_1_196_dialog_content = "……辛苦了。看來要查明真相，要去一趟PlayerName的家鄉了。",
  ui_story_9_1_1_197_dialog_content = "空之山谷……？",
  ui_story_9_1_1_198_dialog_content = "吞噬者號居然落入了空之山谷……真是諷刺。",
  ui_story_9_1_1_199_dialog_content = "PlayerName，還有一件事情……要告訴你。",
  ui_story_9_1_1_200_dialog_content = "吞噬者號攻擊白夜城的具體方式，以及三個組件的事……",
  ui_story_9_1_1_201_dialog_content = "我已經向白夜城報告了。",
  ui_story_9_1_1_202_dialog_content = "PlayerName，希望你能諒解。",
  ui_story_9_1_1_203_dialog_content = "嗯……沒關係，我懂。",
  ui_story_9_1_1_204_dialog_content = "三個組件……",
  ui_story_9_1_1_205_dialog_content = "PlayerName，你還記得三個組件中的<color=#FFB400>「智庫組件」</color>嗎？",
  ui_story_9_1_1_206_dialog_content = "當然記得，我還記得孟德爾頌曾經說過……",
  ui_story_9_1_1_207_dialog_content = "「智庫組件」裡存放了很多訊息，要什麼有什麼的那種。",
  ui_story_9_1_1_208_dialog_content = "是的！我也想到了！",
  ui_story_9_1_1_209_dialog_content = "……找到「智庫組件」，也許就能找到修好意識模組的方法！！",
  ui_story_9_1_1_210_dialog_content = "對！PlayerName、卡蓮，那我們現在就——",
  ui_story_9_1_1_211_dialog_content = "向空之山谷出發！",
  ui_story_9_1_1_212_dialog_content = "<color=#e8d9bb>空之山谷</color>",
  ui_story_9_1_1_213_dialog_content = "和我想的一樣，妳果然還是個空裔。",
  ui_story_9_1_1_214_dialog_content = "臨死都要跑到這個早就變成墳場的空谷。",
  ui_story_9_1_1_215_dialog_content = "……",
  ui_story_9_1_1_216_dialog_content = "只會給人添麻煩的傢伙。",
  ui_story_9_1_1_217_dialog_content = "在我拿到最後的結果之前。",
  ui_story_9_1_1_218_dialog_content = "妳，還不能死。",
  ui_story_9_1_1_219_dialog_content = "咳……咳咳……",
  ui_story_9_1_1_220_dialog_content = "妳終於醒了。",
  ui_story_9_1_1_221_dialog_content = "咳咳……一睜開眼睛就看見你……真是……火大……",
  ui_story_9_1_1_222_dialog_content = "被打得落花流水的傢伙，好意思對救命恩人發脾氣啊。",
  ui_story_9_1_1_223_dialog_content = "胡……說……咳、咳……",
  ui_story_9_1_1_224_dialog_content = "承認吧，舒默，妳輸了。輸得徹徹底底。",
  ui_story_9_1_1_225_dialog_content = "我……才沒有……輸給那群……螻蟻。",
  ui_story_9_1_1_226_dialog_content = "還嘴硬。妳知道妳為什麼輸嗎？",
  ui_story_9_1_1_227_dialog_content = "別……別說了……咳咳……",
  ui_story_9_1_1_228_dialog_content = "因為妳還不夠強大。",
  ui_story_9_1_1_229_dialog_content = "我不……不想聽……",
  ui_story_9_1_1_230_dialog_content = "不過我可以再給妳一次機會。",
  ui_story_9_1_1_231_dialog_content = "只要妳幫我繼續完成實驗，我保證妳會知道——",
  ui_story_9_1_1_232_dialog_content = "成為真正的強者究竟是什麼滋味。",
  ui_story_9_1_1_233_dialog_content = "……還有機會……強化「種子」？",
  ui_story_9_1_1_234_dialog_content = "看來妳的腦子還算清醒。",
  ui_story_9_1_1_235_dialog_content = "咳咳……我只有……一個問題……",
  ui_story_9_1_1_236_dialog_content = "妳真的很麻煩。",
  ui_story_9_1_1_237_dialog_content = "妳為什麼要幫我？",
  ui_story_9_1_1_238_dialog_content = "別誤會，我只想要完成實驗。",
  ui_story_9_1_1_239_dialog_content = "……",
  ui_story_9_1_1_240_dialog_content = "而妳可是我最寶貝的實驗品。",
  ui_story_9_1_1_241_dialog_content = "……",
  ui_story_9_1_1_242_dialog_content = "妳為什麼要幫我？",
  ui_story_9_1_1_243_dialog_content = "我、我……我知道，錯的是他們……",
  ui_story_9_2_1_1_dialog_content = "……這個座標，就是吞噬者號的墜毁地點——<color=#FFB400>空之山谷</color>。",
  ui_story_9_2_1_2_dialog_content = "這裡就是……",
  ui_story_9_2_1_3_dialog_content = "（在夢裡想了十七年的……故鄉……）",
  ui_story_9_2_1_4_dialog_content = "（馬上就可以到了……我……）",
  ui_story_9_2_1_5_dialog_content = "別擔心，PlayerName。我們都在你身邊。",
  ui_story_9_2_1_6_dialog_content = "PlayerName，不要忘記……你還有我們這些「夥伴」。",
  ui_story_9_2_1_7_dialog_content = "薇絲、卡蓮……謝謝妳們……",
  ui_story_9_2_1_8_dialog_content = "PlayerName，說過好多次啦，不用跟自己的夥伴客氣嘛。",
  ui_story_9_2_1_9_dialog_content = "還是要謝謝妳們。",
  ui_story_9_2_1_10_dialog_content = "因為有妳們在身邊，我才更有勇氣去面對這個世界。",
  ui_story_9_2_1_11_dialog_content = "如此說來，我也要謝謝你們兩位。",
  ui_story_9_2_1_12_dialog_content = "正是因為你們兩位，我才有機會去真正認識這個世界。",
  ui_story_9_2_1_13_dialog_content = "PlayerName、卡蓮……",
  ui_story_9_2_1_14_dialog_content = "我們的旅程才剛剛開始呢！",
  ui_story_9_2_1_15_dialog_content = "話說回來，大家知道空之山谷是什麼樣的地方嗎？",
  ui_story_9_2_1_16_dialog_content = "我雖然翻閱過一些資料，但也許PlayerName比知道的我們多。",
  ui_story_9_2_1_17_dialog_content = "空之山谷，我的故鄉……那是個「四季如春，氣候宜人」的地方……",
  ui_story_9_2_1_18_dialog_content = "臨空者，播放一下空谷的影像資料吧。",
  ui_story_9_2_1_19_dialog_content = "……",
  ui_story_9_2_1_20_dialog_content = "……",
  ui_story_9_2_1_21_dialog_content = "臨空者？臨……",
  ui_story_9_2_1_22_dialog_content = "PlayerName，臨空者的意識模組已經……",
  ui_story_9_2_1_23_dialog_content = "……",
  ui_story_9_2_1_24_dialog_content = "再播一次吧，臨空者。",
  ui_story_9_2_1_25_dialog_content = "準備播放「空之山谷」，累積播放十六次。",
  ui_story_9_2_1_26_dialog_content = "「空之山谷，位於世界之脊的南部……是一座被群山環繞的肥沃山谷。」",
  ui_story_9_2_1_27_dialog_content = "「這裡四季如春，氣候宜人……勤勞善良的空裔，世世代代於此生息。」",
  ui_story_9_2_1_28_dialog_content = "臨空者，這些毛茸茸的是什麼？",
  ui_story_9_2_1_29_dialog_content = "這是蒲公英，黃色的是蒲公英花，白色絨球是蒲公英的種子。",
  ui_story_9_2_1_30_dialog_content = "為什麼我抓不住它們？",
  ui_story_9_2_1_31_dialog_content = "PlayerName，這只是影像。",
  ui_story_9_2_1_32_dialog_content = "如果你喜歡，我可以再播放一遍。",
  ui_story_9_2_1_33_dialog_content = "準備播放「空之山谷」，累積播放十七次。",
  ui_story_9_2_1_34_dialog_content = "……九十次。",
  ui_story_9_2_1_35_dialog_content = "……四百三十七次。",
  ui_story_9_2_1_36_dialog_content = "……兩千六百二十八次。",
  ui_story_9_2_1_37_dialog_content = "臨空者，我一定要把你的意識找回來！",
  ui_story_9_2_1_38_dialog_content = "<color=#e8d9bb>空之山谷</color>",
  ui_story_9_2_1_39_dialog_content = "我們到了。",
  ui_story_9_2_1_40_dialog_content = "這裡就是……空之山谷？",
  ui_story_9_2_1_41_dialog_content = "完全不一樣……",
  ui_story_9_2_1_42_dialog_content = "這裡和我在影像中看到的完全不一樣！",
  ui_story_9_2_1_43_dialog_content = "我們沒有走錯嗎？",
  ui_story_9_2_1_44_dialog_content = "座標所示的位置，確實是這裡沒錯。",
  ui_story_9_2_1_45_dialog_content = "……",
  ui_story_9_2_1_46_dialog_content = "到處都是乾枯的雜草……",
  ui_story_9_2_1_47_dialog_content = "欸，雜草下面藏著一些白色的石頭。",
  ui_story_9_2_1_48_dialog_content = "這些石頭排列得很有規律，應該是房屋的地基。",
  ui_story_9_2_1_49_dialog_content = "這裡也有……那裡也有……",
  ui_story_9_2_1_50_dialog_content = "看來，這裡曾經是一片小有規模的居住區。",
  ui_story_9_2_1_51_option_content = "感應",
  ui_story_9_2_1_52_dialog_content = "（一片空白……）",
  ui_story_9_2_1_53_dialog_content = "為什麼……我什麼都感應不到……",
  ui_story_9_2_1_54_dialog_content = "PlayerName，那件事已經過去太久，就連這些石頭都已經風化變形。",
  ui_story_9_2_1_55_option_content = "感應",
  ui_story_9_2_1_56_dialog_content = "……",
  ui_story_9_2_1_57_dialog_content = "PlayerName，我們再往前看看，也許……",
  ui_story_9_2_1_58_option_content = "感應",
  ui_story_9_2_1_59_dialog_content = "哈啾！",
  ui_story_9_2_1_60_dialog_content = "小心，這種觸感……是<color=#FFB400>暗能</color>！",
  ui_story_9_2_1_61_dialog_content = "難道是因為吞噬者號在附近？",
  ui_story_9_2_1_62_dialog_content = "好像不是……這裡的暗能很濃，還有些別的東西混進來了。",
  ui_story_9_2_1_63_dialog_content = "PlayerName，你還好嗎？",
  ui_story_9_2_1_64_dialog_content = "放心，我比任何時候都要清醒。",
  ui_story_9_2_1_65_dialog_content = "卡蓮，六點鐘方向！",
  ui_story_9_2_1_66_dialog_content = "吼——！",
  ui_story_9_2_1_67_dialog_content = "散開！冰花！",
  ui_story_9_2_1_68_dialog_content = "可惡的暗鬼，竟敢玷污PlayerName的家鄉！",
  ui_story_9_2_1_69_dialog_content = "PlayerName，指揮就拜託你了！",
  ui_story_9_2_2_1_dialog_content = "<color=#e8d9bb>吞噬者號內</color>",
  ui_story_9_2_2_2_dialog_content = "躺好。",
  ui_story_9_2_2_3_dialog_content = "這是……<color=#FFB400>「治療繭」</color>？",
  ui_story_9_2_2_4_dialog_content = "舒服嗎？",
  ui_story_9_2_2_5_dialog_content = "原來妳早就料到會有這一天……咳咳……",
  ui_story_9_2_2_6_dialog_content = "所以當初……妳給我的黑色巨像裝了這麼個破玩意……",
  ui_story_9_2_2_7_dialog_content = "注意妳的用詞。",
  ui_story_9_2_2_8_dialog_content = "這東西……看起來真噁心。",
  ui_story_9_2_2_9_dialog_content = "無可救藥。",
  ui_story_9_2_2_10_dialog_content = "怎麼？不……咳咳……不打算救妳寶貝的實驗品了嗎。",
  ui_story_9_2_2_11_dialog_content = "我說過，只要妳肯放棄空裔的一切，就會獲得無上的力量。",
  ui_story_9_2_2_12_dialog_content = "我也說過不止一次——我早就不是空裔了。",
  ui_story_9_3_2_1_dialog_content = "喂！真的是這條路嗎？",
  ui_story_9_3_2_2_dialog_content = "有我這個紅油扳手最可靠的男人帶路，還能有錯嗎？",
  ui_story_9_3_2_3_dialog_content = "什麼？剛才都是你這傢伙在帶路嗎？！",
  ui_story_9_3_2_4_dialog_content = "居然在這地方找到一顆炸彈，真走運哈哈哈！",
  ui_story_9_3_2_5_dialog_content = "奇怪，這炸彈不是我剛扔掉的啞彈嗎……",
  ui_story_9_3_2_6_dialog_content = "所以……剛才我們是一直在繞圈子嗎？",
  ui_story_9_3_2_7_dialog_content = "瞎說什麼，我可是照著地圖走的！",
  ui_story_9_3_2_8_dialog_content = "黑潮！你這個聒噪的笨蛋！你地圖拿反了！",
  ui_story_9_3_2_9_dialog_content = "……不迷路才怪。",
  ui_story_9_3_2_10_dialog_content = "<size=45>黑！潮！</size>",
  ui_story_9_3_2_11_dialog_content = "我現在就駭進你的腦子！看看到底是哪裡生鏽了！",
  ui_story_9_3_2_12_dialog_content = "♪不用擔心~有芭芭拉為大家應援喔~",
  ui_story_9_3_2_13_dialog_content = "<anim type=Shake>♪只要有愛，就有希望~！</anim>",
  ui_story_9_3_2_14_dialog_content = "呃啊——！老大，我快要爆炸了！我可以揍她嗎？！",
  ui_story_9_3_2_X14_dialog_content = "老大說過，今天要和諧相處唷！完美的芭芭拉才不跟妳計較呢~",
  ui_story_9_3_2_X15_dialog_content = "妳再不閉嘴，就算是老大也別想阻止我揍……",
  ui_story_9_3_2_15_dialog_content = "嗯？老大呢？",
  ui_story_9_3_2_16_dialog_content = "喂！你們有沒有看見老大？",
  ui_story_9_3_2_17_dialog_content = "不會是被我的氣勢嚇跑了吧！我就知道我才是最強的！",
  ui_story_9_3_2_18_dialog_content = "老大？剛剛還在的啊！",
  ui_story_9_3_2_19_dialog_content = "醒山大哥不見了？！",
  ui_story_9_3_2_20_dialog_content = "不對，叭噗也不見了……",
  ui_story_9_3_2_21_dialog_content = "你們聽好了，衝啊！",
  ui_story_9_3_2_22_dialog_content = "黑潮！你給我回來！！",
  ui_story_9_3_2_23_dialog_content = "<size=45><anim type=Shake>&*#%#%……！</anim></size>",
  ui_story_9_3_2_24_dialog_content = "<color=#e8d9bb>匡當——！咚——！</color>",
  ui_story_9_3_2_25_dialog_content = "啊啊啊啊啊，好痛……！",
  ui_story_9_3_2_26_dialog_content = "喂！是哪個不長眼的給老子設了陷阱？！",
  ui_story_9_3_2_27_dialog_content = "暗地裡偷襲，算哪門子好漢？",
  ui_story_9_3_2_28_dialog_content = "有本事快出來！老子一定揍死你們！",
  ui_story_9_3_2_29_dialog_content = "剛剛我們踩空的地方，和周圍的地面明明沒有什麼不同……",
  ui_story_9_3_2_30_dialog_content = "雖然這很像是人工挖掘的陷阱……",
  ui_story_9_3_2_31_dialog_content = "可是從坑道被植被覆蓋的程度來看……",
  ui_story_9_3_2_32_dialog_content = "快出來啊！！",
  ui_story_9_3_2_33_dialog_content = "老大，你有聽到我說話嗎？",
  ui_story_9_3_2_34_dialog_content = "嗯？你說什麼？",
  ui_story_9_3_2_35_dialog_content = "這只是個天然的坑洞，不是陷阱！也沒有人偷襲我們！",
  ui_story_9_3_2_36_dialog_content = "……",
  ui_story_9_3_2_37_dialog_content = "叭噗，記住你剛才什麼都沒聽見……千萬別把我說粗話的事告訴我妹！",
  ui_story_9_3_2_38_dialog_content = "只要老大你不要假裝聽不到我說話……",
  ui_story_9_3_2_39_dialog_content = "<anim type=Shake>你們聽好了，衝啊！</anim>",
  ui_story_9_3_2_40_dialog_content = "<anim type=Shake>黑潮！你給我回來！！</anim>",
  ui_story_9_3_2_41_dialog_content = "行行行。",
  ui_story_9_3_2_42_dialog_content = "既然不是陷阱，那就不用擔心有人埋伏了，我們快出去吧。",
  ui_story_9_3_2_X42_dialog_content = "蕾吉娜！黑潮！！聽得到嗎！！！",
  ui_story_9_3_2_43_dialog_content = "從跌落的時間長度和重力加速度來分析……",
  ui_story_9_3_2_44_dialog_content = "就算我們在這裡喊破喉嚨，他們也聽不見。",
  ui_story_9_3_2_45_dialog_content = "蕾吉娜——！",
  ui_story_9_3_2_46_dialog_content = "老大！我要告訴伊芙你說髒話了！",
  ui_story_9_3_2_47_dialog_content = "別別別，妳剛才說什麼時長、什麼速度來著？",
  ui_story_9_3_2_48_dialog_content = "嗯……簡單來說就是，這個洞太深了，他們聽不見我們的聲音。",
  ui_story_9_3_2_49_dialog_content = "咳，原來如此……",
  ui_story_9_3_2_50_dialog_content = "不愧是我們<color=#FFB400>「陸行者號」</color>的駕駛員，分析能力就是不一般！",
  ui_story_9_3_2_51_dialog_content = "好吧，走！瞧瞧這洞到底通到什麼鬼地方。",
  ui_story_9_3_2_52_dialog_content = "<color=#e8d9bb>叮鈴——匡！</color>",
  ui_story_9_3_2_53_dialog_content = "老大你看，這裡有好多巨像的零件喔！",
  ui_story_9_3_2_54_dialog_content = "哇！這圓潤的小腦袋，這可愛的小翅膀，這細膩的做工……",
  ui_story_9_3_2_55_dialog_content = "第一次見到這麼好看的螢盞……「陸行者」一定會喜歡的！",
  ui_story_9_3_2_56_dialog_content = "這螢盞只剩下一根翅膀，能拿來幹嘛？當球踢嗎？",
  ui_story_9_3_2_57_dialog_content = "那裡還有好多！這個我要帶回去！那個我也要……",
  ui_story_9_3_2_58_dialog_content = "還是留點口袋吧。別忘了我們是來幹嘛的！",
  ui_story_9_3_2_59_dialog_content = "我沒忘。但我答應過要給「陸行者」帶特產……",
  ui_story_9_3_2_60_dialog_content = "等找到那座墜毀的黑色巨像，有的是更值錢的玩意。",
  ui_story_9_3_2_61_dialog_content = "唔……",
  ui_story_9_3_2_62_dialog_content = "不過，這洞裡怎麼也有這麼多巨像的零件……",
  ui_story_9_3_2_63_dialog_content = "難道這裡是……？",
  ui_story_9_3_2_64_dialog_content = "……？",
  ui_story_9_3_2_65_dialog_content = "走！我們得快點找到出口了。",
  ui_story_9_3_2_66_dialog_content = "總覺得這地方除了我們，還有別人。",
  ui_story_9_4_1_1_dialog_content = "小心，有狀況！",
  ui_story_9_4_1_2_dialog_content = "穿透敵人！",
  ui_story_9_4_1_3_dialog_content = "喂，小姑娘，偷襲可不是個好主意！",
  ui_story_9_4_1_4_dialog_content = "你們是……光靈？",
  ui_story_9_4_1_5_dialog_content = "戰鬥是有兩把刷子，判斷能力嘛……還是差了一點啊！",
  ui_story_9_4_1_6_dialog_content = "你……！",
  ui_story_9_4_1_7_dialog_content = "卡蓮，怎麼回事……",
  ui_story_9_4_1_8_dialog_content = "老大，你沒事吧？",
  ui_story_9_4_1_9_dialog_content = "好得很！",
  ui_story_9_4_1_10_dialog_content = "是你？",
  ui_story_9_4_1_11_dialog_content = "PlayerName，你認識這個紅油扳手的人？",
  ui_story_9_4_1_12_option_content = "之前在啟光……",
  ui_story_9_4_1_13_dialog_content = "我和臨空者剛從地下出來的時候，不小心墜落在啟光地下城附近。",
  ui_story_9_4_1_14_dialog_content = "就是他帶著一幫人來趁火打劫。",
  ui_story_9_4_1_15_dialog_content = "喂，你這小子怎麼說話呢？明明是把你們從暗鬼手中救下來好嗎？",
  ui_story_9_4_1_16_dialog_content = "後來在紅油沙漠，臨空者又差點被他大卸八塊。",
  ui_story_9_4_1_17_option_content = "之前在紅油沙漠……",
  ui_story_9_4_1_18_dialog_content = "我們從紅油沙漠離開的時候，就是他帶人把我們攔截下來的。",
  ui_story_9_4_1_19_dialog_content = "他們還差點把臨空者大卸八塊。",
  ui_story_9_4_1_20_dialog_content = "你這麼說我，我沒話說。那次是我草率了。",
  ui_story_9_4_1_21_dialog_content = "後來還是多虧了你，我妹妹才能得救。",
  ui_story_9_4_1_22_dialog_content = "PlayerName，就算我醒山欠你一個人情。",
  ui_story_9_4_1_23_dialog_content = "……你們還去過紅油沙漠？",
  ui_story_9_4_1_24_dialog_content = "是上次從白夜城離開以後的事了……",
  ui_story_9_4_1_25_dialog_content = "這位來自白夜城的「大小姐」，還是一副咄咄逼人的老樣子。",
  ui_story_9_4_1_26_dialog_content = "都不確認清楚情況就直接開始攻擊，萬一傷到了無辜的人怎麼辦？",
  ui_story_9_4_1_27_dialog_content = "醒山，卡蓮她不是故意的……",
  ui_story_9_4_1_28_dialog_content = "剛才的攻擊，的確是我不對。",
  ui_story_9_4_1_29_dialog_content = "本人卡蓮·德·舒瓦茲，為我剛才的攻擊，向你道歉。",
  ui_story_9_4_1_30_dialog_content = "但如果你繼續對白夜城妄加評論……",
  ui_story_9_4_1_31_dialog_content = "我現在就可以跟你算紅油扳手的帳。",
  ui_story_9_4_1_X31_dialog_content = "想打架也得分清楚時間跟場合。",
  ui_story_9_4_1_32_dialog_content = "PlayerName，你認識的這位卡蓮還挺有個性的嘛，你們怎麼會一起行動？",
  ui_story_9_4_1_33_dialog_content = "那個……雖然不知道兩位以前有什麼過節……",
  ui_story_9_4_1_34_dialog_content = "但你們都是跟我和薇絲一起戰鬥過的夥伴，希望不要在這吵起來。",
  ui_story_9_4_1_35_dialog_content = "行，既然PlayerName都這麼說了，沒必要在這裡傷了和氣。",
  ui_story_9_4_1_36_dialog_content = "這句話應該是我來說。",
  ui_story_9_4_1_X36_dialog_content = "請記住，我只是還有別的任務在身，沒時間跟你們胡鬧。",
  ui_story_9_4_1_X37_dialog_content = "哈，妳倒是很敢說嘛……",
  ui_story_9_4_1_37_dialog_content = "咳、那個！我們還是換個話題吧，醒山……",
  ui_story_9_4_1_38_option_content = "後面這個女孩子是……",
  ui_story_9_4_1_39_dialog_content = "哈，這是叭噗。",
  ui_story_9_4_1_40_dialog_content = "大家好，我是叭噗。",
  ui_story_9_4_1_41_dialog_content = "你就是PlayerName嗎？經常聽伊芙提起你呢！",
  ui_story_9_4_1_42_dialog_content = "我們看到一座黑色的巨像墜落在這附近，所以就追過來了。",
  ui_story_9_4_1_43_dialog_content = "沒想到半路上，我倆掉進了洞裡。剛出來就遇見了你們。",
  ui_story_9_4_1_44_option_content = "你為什麼會在這裡……",
  ui_story_9_4_1_45_dialog_content = "當然是來搞點戰利品的，哈哈哈哈！",
  ui_story_9_4_1_46_dialog_content = "戰利品？什麼意思？",
  ui_story_9_4_1_47_dialog_content = "我們看到一座黑色的巨像墜落在這附近，所以就追過來了。",
  ui_story_9_4_1_48_dialog_content = "沒想到半路上，我和叭噗掉進了洞裡。剛出來就遇見了你們。",
  ui_story_9_4_1_49_dialog_content = "我就是叭噗。你是PlayerName吧？經常聽伊芙提起你呢！",
  ui_story_9_4_1_50_dialog_content = "PlayerName，你們也是來「尋寶」的？",
  ui_story_9_4_1_51_dialog_content = "這個……說來話長。",
  ui_story_9_4_1_52_dialog_content = "<color=#e8d9bb>過了一段時間</color>",
  ui_story_9_4_1_53_dialog_content = "<size=45>空之山谷？！</size>",
  ui_story_9_4_1_54_dialog_content = "這裡果然是空之山谷……",
  ui_story_9_4_1_55_dialog_content = "只是PlayerName，沒想到這麼短的時間裡，你已經經歷了這麼多事情。",
  ui_story_9_4_1_56_dialog_content = "可能這就是回到地面之後，必須經歷的磨難吧。",
  ui_story_9_4_1_57_dialog_content = "但我不會忘记……「希望」。",
  ui_story_9_4_1_58_dialog_content = "哈哈哈哈！既然這樣，我醒山就陪你走上一段。",
  ui_story_9_4_1_59_dialog_content = "欸？",
  ui_story_9_4_1_60_dialog_content = "怎麼，有意見嗎？",
  ui_story_9_4_1_61_dialog_content = "沒有意見，非常歡迎！",
  ui_story_9_4_1_62_dialog_content = "前路未卜，多一些戰力也是好的。",
  ui_story_9_4_1_63_dialog_content = "既然兩位小姑娘都不反對，那就這麼決定了！",
  ui_story_9_4_1_64_dialog_content = "老大，蕾吉娜她們怎麼辦？",
  ui_story_9_4_1_65_dialog_content = "喔對了，你們來的路上，有沒有看到紅油扳手的其他人？",
  ui_story_9_4_1_66_dialog_content = "還有其他人也來了嗎？",
  ui_story_9_4_1_X66_dialog_content = "對，我們紅油扳手最愛集體出遊。",
  ui_story_9_4_1_67_dialog_content = "沒看到。我們這一路上，除了暗鬼什麼都沒看見。",
  ui_story_9_4_1_X67_dialog_content = "咕……",
  ui_story_9_4_1_68_dialog_content = "好吧。妳才剛說完，暗鬼就出現了。",
  ui_story_9_4_1_69_dialog_content = "PlayerName，讓我瞧瞧你的指揮技術有沒有進步吧！",
  ui_story_9_4_2_1_dialog_content = "（日蝕語）主人，外面有群光靈接近。",
  ui_story_9_4_2_2_dialog_content = "（日蝕語）其中還有一個空裔。",
  ui_story_9_4_2_3_dialog_content = "（日蝕語）我們人手有限，沒辦法拖延他們的腳步。",
  ui_story_9_4_2_4_dialog_content = "空裔？",
  ui_story_9_4_2_5_dialog_content = "難道是上次那個叫PlayerName的空裔。",
  ui_story_9_4_2_6_dialog_content = "不對。他現在應該已經……",
  ui_story_9_4_2_7_dialog_content = "……",
  ui_story_9_4_2_8_dialog_content = "舒默，妳真是什麼都辦不好。",
  ui_story_9_4_2_9_dialog_content = "（日蝕語）去，幫我把那些從白夜城抓來的雜兵帶來。",
  ui_story_9_4_2_10_dialog_content = "（日蝕語）遵命，主人。",
  ui_story_9_4_2_11_dialog_content = "我討厭節外生枝。",
  ui_story_9_4_2_12_dialog_content = "討厭浪費實驗材料。",
  ui_story_9_4_2_13_dialog_content = "但無論什麼，都不能打斷我的實驗計畫。",
  ui_story_9_5_2_1_dialog_content = "<color=#e8d9bb>真理結社·祕密據點</color>",
  ui_story_9_5_2_2_dialog_content = "我尊貴的維多利亞大人，您還有什麼吩咐嗎？",
  ui_story_9_5_2_3_dialog_content = "浮士德，為了偉大的「真理之主」，去蒐集更多的<color=#FFB400>「種子」</color>吧。",
  ui_story_9_5_2_4_dialog_content = "這是我的容幸，維多利亞大人。",
  ui_story_9_5_2_5_dialog_content = "帶契法和聖釘一起去吧。",
  ui_story_9_5_2_6_dialog_content = "謹遵指令，維多利亞大人。願真理祝福您。",
  ui_story_9_5_2_7_dialog_content = "這就是你提到的那東西嗎？",
  ui_story_9_5_2_8_dialog_content = "讓人恐懼，又讓人渴望的，來自黑暗的力量。",
  ui_story_9_5_2_9_dialog_content = "陽光照耀的土地上，的確會有人違背真理的教誨，主動尋求「種子」的力量。",
  ui_story_9_5_2_10_dialog_content = "那些可悲的人，已經放棄了自己身為光靈的「人性」呢。",
  ui_story_9_5_2_11_dialog_content = "你確定要吃下這東西？",
  ui_story_9_5_2_12_dialog_content = "喔，我忘了。你是一本書，也許不知何為「人性」。",
  ui_story_9_5_2_13_dialog_content = "維多利亞·瓦拉吉。",
  ui_story_9_5_2_X13_dialog_content = "不要多嘴，妳只需要把它放在我身上。",
  ui_story_9_5_2_14_dialog_content = "那就看看你能否消化成功吧。",
  ui_story_9_5_2_15_dialog_content = "<color=#e8d9bb>喀嚓——咕咚——</color>",
  ui_story_9_5_2_16_dialog_content = "味道如何？",
  ui_story_9_5_2_17_dialog_content = "「似乎有一絲血肉的氣息。」",
  ui_story_9_5_2_18_dialog_content = "這「種子」是從一個空裔身上挖下來的。",
  ui_story_9_5_2_19_dialog_content = "「空裔？」",
  ui_story_9_5_2_20_dialog_content = "怎麼了，開始對空裔的肉體感興趣了嗎？",
  ui_story_9_5_2_21_dialog_content = "「維多利亞·瓦拉吉，注意妳的態度！」",
  ui_story_9_5_2_22_dialog_content = "看起來吸收進行得不錯。",
  ui_story_9_5_2_23_dialog_content = "「這只是開始而已。」",
  ui_story_9_5_2_24_dialog_content = "是呢，事情變得愈來愈有意思了。",
  ui_story_9_5_2_25_dialog_content = "「不要忘記我們訂下的契約。」",
  ui_story_9_5_2_26_dialog_content = "怎麼會忘呢。我已經派人去找更多「種子」了。",
  ui_story_9_5_2_27_dialog_content = "「也不要忘記，你需要處理掉的那些傢伙。」",
  ui_story_9_5_2_28_dialog_content = "不要太貪心。",
  ui_story_9_5_2_29_dialog_content = "機會，需要我們慢慢等待。",
  ui_story_9_5_2_30_dialog_content = "<color=#e8d9bb>空谷深處</color>",
  ui_story_9_5_2_31_dialog_content = "好啊，你這小子！",
  ui_story_9_5_2_32_dialog_content = "指揮技術愈來愈好了嘛！",
  ui_story_9_5_2_33_dialog_content = "謝謝……",
  ui_story_9_5_2_X33_dialog_content = "咳、咳咳……",
  ui_story_9_5_2_34_dialog_content = "PlayerName，怎麼了？",
  ui_story_9_5_2_35_option_content = "好冷……",
  ui_story_9_5_2_36_dialog_content = "來，喝點熱水。",
  ui_story_9_5_2_37_dialog_content = "沒想到……醒山居然這麼細心？",
  ui_story_9_5_2_38_dialog_content = "老大之前為了照顧妹妹，總是隨身攜帶熱水瓶。",
  ui_story_9_5_2_39_dialog_content = "這沒什麼，我習慣了。",
  ui_story_9_5_2_40_option_content = "沒什麼……",
  ui_story_9_5_2_41_dialog_content = "PlayerName，伸出手來。",
  ui_story_9_5_2_42_dialog_content = "你的手怎麼這麼冰！",
  ui_story_9_5_2_43_dialog_content = "沒關係的，薇絲。",
  ui_story_9_5_2_44_dialog_content = "奇了怪了，怎麼愈往裡走，溫度愈低？",
  ui_story_9_5_2_45_dialog_content = "傳說中的空之山谷，不是一個很暖和的地方嗎……",
  ui_story_9_5_2_46_dialog_content = "……",
  ui_story_9_5_2_47_dialog_content = "暗能愈來愈濃了，大家保持警惕！",
  ui_story_9_5_2_48_dialog_content = "恐怕空之山谷已經變成了暗鬼的老巢。",
  ui_story_9_5_2_49_dialog_content = "……！",
  ui_story_9_5_2_50_dialog_content = "怪不得這一路上，我們遇到了那麼多暗鬼……",
  ui_story_9_5_2_51_dialog_content = "這麼說來，吞噬者號墜毀在這裡，也許不是意外。",
  ui_story_9_5_2_52_dialog_content = "難道……",
  ui_story_9_7_1_1_dialog_content = "嘎——！",
  ui_story_9_7_1_2_dialog_content = "這些蟲子真是沒完沒了！",
  ui_story_9_7_1_3_dialog_content = "嘿咻~！嘿咻~！嘿咻~！",
  ui_story_9_7_1_4_dialog_content = "叭噗，你這是在做什麼……？",
  ui_story_9_7_1_5_dialog_content = "我在撿寶貝呢。",
  ui_story_9_7_1_6_dialog_content = "你怎麼還在這裡撿破爛？",
  ui_story_9_7_1_7_dialog_content = "老大，這可不是破爛！",
  ui_story_9_7_1_8_dialog_content = "這塊肌材厚度適中、結實耐磨——「陸行者」一定會喜歡！",
  ui_story_9_7_1_9_dialog_content = "這種螺絲，我從來沒見過——要拿回去給小不點看看！",
  ui_story_9_7_1_10_dialog_content = "而且……看！我已經湊齊紅、黃、藍、綠四種顏色的螢盞了！",
  ui_story_9_7_1_11_dialog_content = "叭噗，妳好厲害。",
  ui_story_9_7_1_12_dialog_content = "我都沒發現，原來一路上有這麼多好東西！",
  ui_story_9_7_1_13_dialog_content = "還有還有…………",
  ui_story_9_7_1_14_dialog_content = "PlayerName，這些東西是……",
  ui_story_9_7_1_15_dialog_content = "這些零件確實來自巨像，但不是吞噬者號的……",
  ui_story_9_7_1_16_dialog_content = "所以這是……從其他巨像身上掉下來的？",
  ui_story_9_7_1_17_dialog_content = "是……十七年前的那晚……？",
  ui_story_9_7_1_18_dialog_content = "這些肌材破損得如此厲害，當時的慘況可見一斑。",
  ui_story_9_7_1_19_dialog_content = "……",
  ui_story_9_7_1_20_dialog_content = "對不起……我只是覺得它們丟在這裡很可惜……",
  ui_story_9_7_1_21_dialog_content = "如果惹PlayerName生氣了的話，我就不撿了……",
  ui_story_9_7_1_22_dialog_content = "沒關係，叭噗。",
  ui_story_9_7_1_23_dialog_content = "它們一定也希望，能遇到懂得自己、珍惜自己的夥伴。",
  ui_story_9_7_1_24_dialog_content = "真的嗎？謝謝PlayerName！",
  ui_story_9_7_1_25_dialog_content = "叭噗。",
  ui_story_9_7_1_26_dialog_content = "PlayerName都說沒關係了……",
  ui_story_9_7_1_27_dialog_content = "我們不知道前面還要走多遠，打多少架。",
  ui_story_9_7_1_28_dialog_content = "這種時候，就要學會拿得起、放得下。",
  ui_story_9_7_1_29_dialog_content = "……好吧。",
  ui_story_9_7_1_30_dialog_content = "那我留下這個可以嗎？",
  ui_story_9_7_1_31_dialog_content = "這小玩意倒是不礙事，拿著吧！",
  ui_story_9_7_1_32_dialog_content = "……！",
  ui_story_9_7_1_33_dialog_content = "卡蓮，你認識這東西嗎？",
  ui_story_9_7_1_34_dialog_content = "這是<color=#FFB400>白夜城衛兵</color>的徽章……為何會出現在這裡？",
  ui_story_9_7_1_35_dialog_content = "叭噗，妳是在哪裡撿到這枚徽章的？",
  ui_story_9_7_1_36_dialog_content = "好像是……上一個路口。就是我們遇到暗鬼突襲那裡！",
  ui_story_9_7_1_37_dialog_content = "可以給我看看嗎？",
  ui_story_9_7_1_38_dialog_content = "嗯，給你。",
  ui_story_9_7_1_39_option_content = "感應",
  ui_story_9_7_1_40_dialog_content = "終於！終於戴上了這枚徽章！",
  ui_story_9_7_1_41_dialog_content = "母親，您看到了嗎？",
  ui_story_9_7_1_42_dialog_content = "您的兒子成為了一名威風凜凜的白夜城衛兵！",
  ui_story_9_7_1_43_dialog_content = "再也不用服侍那些上城的老爺太太了！",
  ui_story_9_7_1_44_dialog_content = "可是……可是您卻已經離我而去……",
  ui_story_9_7_1_45_dialog_content = "新來的，還愣著幹什麼？！快去攔住那些暗鬼！",
  ui_story_9_7_1_46_dialog_content = "……是！",
  ui_story_9_7_1_47_dialog_content = "吼——！",
  ui_story_9_7_1_48_dialog_content = "母親，請保佑我吧！",
  ui_story_9_7_1_49_dialog_content = "這……是哪裡……？",
  ui_story_9_7_1_50_dialog_content = "（日蝕語）主人，這些就是從白夜城抓來的雜兵。",
  ui_story_9_7_1_51_dialog_content = "（日蝕語）很好。",
  ui_story_9_7_1_52_dialog_content = "暗鬼？！你們……你們……要對我做什麼？！",
  ui_story_9_7_1_53_dialog_content = "快放我出去！",
  ui_story_9_7_1_54_dialog_content = "別怕，這完全不會痛。",
  ui_story_9_7_1_55_dialog_content = "不……不要過來！！！",
  ui_story_9_7_1_56_dialog_content = "啊——！！！",
  ui_story_9_7_1_57_dialog_content = "……！",
  ui_story_9_7_1_58_dialog_content = "PlayerName，你看到了什麼？",
  ui_story_9_7_1_59_dialog_content = "我看到……",
  ui_story_9_7_1_60_option_content = "衛兵",
  ui_story_9_7_1_61_dialog_content = "這枚徽章屬於一位白夜城衛兵。",
  ui_story_9_7_1_62_dialog_content = "……！",
  ui_story_9_7_1_63_dialog_content = "他剛剛當上衛兵，就參與對抗暗鬼的戰鬥。",
  ui_story_9_7_1_64_dialog_content = "可是……他最後變成了一隻暗鬼。",
  ui_story_9_7_1_65_option_content = "暗鬼",
  ui_story_9_7_1_66_dialog_content = "這枚徽章屬於一隻暗鬼。",
  ui_story_9_7_1_67_dialog_content = "這不可能！",
  ui_story_9_7_1_68_dialog_content = "但這隻暗鬼，曾經是一位白夜城衛兵。",
  ui_story_9_7_1_69_dialog_content = "到底是暗鬼還是衛兵啊？都要被你搞昏頭了。",
  ui_story_9_7_1_70_dialog_content = "這名衛兵是被某人強行變成暗鬼的……",
  ui_story_9_7_1_71_dialog_content = "那個人，毫無疑問就是<color=#FFB400>吞羅</color>！",
  ui_story_9_7_1_72_dialog_content = "你是說，舒默身邊的那個神祕人？",
  ui_story_9_7_1_73_dialog_content = "對！薇絲，還記得妳從我身上挖出的「種子」嗎？",
  ui_story_9_7_1_74_dialog_content = "記得。你差點因為那東西而變成暗鬼！",
  ui_story_9_7_1_75_dialog_content = "嗄？！居然還有這種事？！",
  ui_story_9_7_1_76_dialog_content = "我看見吞羅……強行把「種子」塞進衛兵的身體裡！",
  ui_story_9_7_1_77_dialog_content = "……！",
  ui_story_9_7_1_78_dialog_content = "當時，有個提著白箱的男人說過……",
  ui_story_9_7_1_79_dialog_content = "「種子」是將其他生物轉化為暗鬼的唯一途徑。",
  ui_story_9_7_1_80_dialog_content = "你的意思是……這個吞羅，把一名白夜城衛兵變成了暗鬼？！",
  ui_story_9_7_1_81_dialog_content = "嗯……",
  ui_story_9_7_1_82_dialog_content = "剛才我們打死的暗鬼……其實是白夜城的衛兵嗎……",
  ui_story_9_7_1_83_dialog_content = "嗯……",
  ui_story_9_7_1_84_dialog_content = "……",
  ui_story_9_7_1_85_dialog_content = "你們這群小屁孩，少在那發牢騷了！",
  ui_story_9_7_1_86_dialog_content = "殺死衛兵的不是我們，是那個什麼吞羅！",
  ui_story_9_7_1_87_dialog_content = "也許醒山說得沒錯。",
  ui_story_9_7_1_88_dialog_content = "雖然的確是我們……親手殺死了這名……衛兵。",
  ui_story_9_7_1_89_dialog_content = "但如果不是吞羅，這名衛兵也不會變成暗鬼……",
  ui_story_9_7_1_90_dialog_content = "……",
  ui_story_9_7_1_91_dialog_content = "卡蓮小姐，這枚徽章……",
  ui_story_9_7_1_92_dialog_content = "也許應該交給妳保管。",
  ui_story_9_7_1_93_dialog_content = "……好。",
  ui_story_9_7_1_94_dialog_content = "卡蓮·德·舒瓦茲，在此為死者哀悼。",
  ui_story_9_7_1_95_dialog_content = "這枚徽章的所有者，白夜城的衛兵。",
  ui_story_9_7_1_96_dialog_content = "他身為白夜城衛兵，堅守崗位，奮勇迎敵。",
  ui_story_9_7_1_97_dialog_content = "雖落入敵手而淪為暗鬼，喪失了心智，因而攻擊光靈，但這並非出自他的本意。",
  ui_story_9_7_1_98_dialog_content = "請原諒，我們最後親手結束了他痛苦的生命。",
  ui_story_9_7_1_99_dialog_content = "願他於此地安息。白夜至上。",
  ui_story_9_7_1_100_dialog_content = "願你安息……",
  ui_story_9_7_1_101_dialog_content = "……",
  ui_story_9_7_1_102_dialog_content = "吞噬者號、空谷、吞羅……這一切都太古怪了。",
  ui_story_9_7_1_103_dialog_content = "……我有種不祥的預感。",
  ui_story_9_7_1_104_dialog_content = "舒默……",
  ui_story_9_7_1_105_dialog_content = "舒默也許還活著？！",
  ui_story_9_7_1_106_dialog_content = "……！",
  ui_story_9_7_1_107_dialog_content = "無論如何，我們都要加快腳步了！",
  ui_story_9_7_1_108_dialog_content = "吼——！",
  ui_story_9_7_1_109_dialog_content = "小心！前面又來了個不要命的！",
  ui_story_9_7_1_110_dialog_content = "是高級暗鬼嗎？",
  ui_story_9_7_1_111_dialog_content = "我還從來沒有見過……軀體這麼破碎的暗鬼。",
  ui_story_9_7_1_112_dialog_content = "<anim type=Shake>要……我……家……</anim>",
  ui_story_9_7_1_113_dialog_content = "<anim type=Shake>回……要……家……</anim>",
  ui_story_9_7_1_114_dialog_content = "牠是在說通用語嗎？",
  ui_story_9_7_1_115_dialog_content = "我怎麼完全聽不懂……",
  ui_story_9_7_1_116_dialog_content = "牠身上……有光靈的氣息……",
  ui_story_9_7_1_117_dialog_content = "這傢伙也是光靈變的？",
  ui_story_9_7_1_118_dialog_content = "……！",
  ui_story_9_7_1_119_dialog_content = "不會錯的。我能感應到，牠散發出的……強烈的情緒。",
  ui_story_9_7_1_120_dialog_content = "痛苦、絕望、無助、憤怒……就像找不到出口的洪流……",
  ui_story_9_7_1_121_dialog_content = "這個可憐的「光靈」……牠只是想回家……",
  ui_story_9_7_1_122_dialog_content = "……",
  ui_story_9_7_1_123_dialog_content = "<anim type=Shake>吼啊——！</anim>",
  ui_story_9_7_1_124_dialog_content = "看樣子，這傢伙還不知道自己已經變成暗鬼，再也沒辦法回家了……",
  ui_story_9_7_1_125_dialog_content = "還是在牠受到更大的痛苦之前，給牠個痛快吧！",
  ui_story_9_7_2_1_dialog_content = "<anim type=Shake>……家……回……家……</anim>",
  ui_story_9_7_2_2_dialog_content = "白夜至上，願你在此地安息。",
  ui_story_9_7_2_3_dialog_content = "但願……你已經擺脫了肉體的折磨……",
  ui_story_9_7_2_4_dialog_content = "對不起，我們沒能解救你……對不起……",
  ui_story_9_7_2_5_dialog_content = "剛才的戰鬥中，為了不讓牠感受到多餘的痛苦，我們已經盡力了……",
  ui_story_9_7_2_6_dialog_content = "PlayerName，不要過於自責了。",
  ui_story_9_7_2_X6_dialog_content = "現在我們唯一能為這些光靈做的事，就是找到吞羅，然後阻止她。",
  ui_story_9_7_2_7_dialog_content = "……嗯！",
  ui_story_9_7_2_8_dialog_content = "大家說得對……我們要快點找到吞羅，阻止她繼續製造暗鬼！",
  ui_story_9_7_2_9_dialog_content = "這個吞羅，到底是個什麼人物？聽這名字，難道是個光靈？",
  ui_story_9_7_2_10_option_content = "是的",
  ui_story_9_7_2_11_dialog_content = "無論是體型、氣息還是說話方式，吞羅確實都比較像是個光靈。",
  ui_story_9_7_2_12_dialog_content = "可是，她卻與暗鬼為伍。",
  ui_story_9_7_2_13_dialog_content = "而且……聽薇薇安說，吞羅曾經是啟光的一員……",
  ui_story_9_7_2_14_option_content = "並不是。",
  ui_story_9_7_2_15_dialog_content = "也許吞羅曾經是個光靈，但她現在已經是個助紂為虐的暗鬼了。",
  ui_story_9_7_2_16_dialog_content = "不過……聽薇薇安說，吞羅曾經是啟光的一員……",
  ui_story_9_7_2_17_dialog_content = "薇薇安？",
  ui_story_9_7_2_18_dialog_content = "是啟光的參謀長，我的長官。",
  ui_story_9_7_2_19_dialog_content = "我們出發前，薇薇安長官還特地叮嚀我們要小心吞羅……",
  ui_story_9_7_2_20_dialog_content = "沒想到竟然一語成讖……",
  ui_story_9_7_2_21_dialog_content = "我不明白……吞羅真的曾經是啟光的夥伴嗎……？",
  ui_story_9_7_2_22_dialog_content = "為什麼她可以這麼殘忍？",
  ui_story_9_7_2_23_dialog_content = "就好像是沉迷於將光靈變成暗鬼的實驗一樣。",
  ui_story_9_7_2_24_dialog_content = "我在啟光的時候，從來沒聽說過啟光有這樣的……",
  ui_story_9_7_2_25_dialog_content = "這種見不得人的事，啟光高層恐怕不會讓你們底下的人知道吧。",
  ui_story_9_7_2_26_dialog_content = "醒山，我知道你因為伊芙的事不信任啟光。",
  ui_story_9_7_2_27_dialog_content = "但其實啟光的長官們都是身先士卒、以身作則的……",
  ui_story_9_7_2_X27_dialog_content = "或許他們也一直在調查……",
  ui_story_9_7_2_28_dialog_content = "哈哈哈哈哈。妳們太天真了吧，居然會相信這些鬼話。",
  ui_story_9_7_2_29_dialog_content = "當初……我的妹妹伊芙因為被暗鬼襲擊，留下了嚴重的後遺症。",
  ui_story_9_7_2_30_dialog_content = "我就是輕信了啟光那些冠冕堂皇的說辭，才把伊芙送過去治療。",
  ui_story_9_7_2_31_dialog_content = "……",
  ui_story_9_7_2_32_dialog_content = "結果呢？！伊芙的病情不但沒有得到控制，她還差點死在啟光的一場大火裡！",
  ui_story_9_7_2_33_dialog_content = "那場大火……",
  ui_story_9_7_2_34_dialog_content = "……！",
  ui_story_9_7_2_35_dialog_content = "我早該聯想到了……吞羅的臉上……就有被大火燒過的傷疤……",
  ui_story_9_7_2_36_dialog_content = "你說什麼？！",
  ui_story_9_7_2_37_dialog_content = "啟光的大火……",
  ui_story_9_7_2_38_dialog_content = "啊啊啊啊！！！",
  ui_story_9_7_2_39_dialog_content = "吞羅的傷疤……",
  ui_story_9_7_2_40_dialog_content = "看著我的臉，這些疤痕……這是被火燒過的痕跡，看見了嗎？",
  ui_story_9_7_2_41_dialog_content = "難道……",
  ui_story_9_7_2_42_dialog_content = "醒山，我再確認一次，當時負責治療伊芙的實驗員後來去哪了？",
  ui_story_9_7_2_43_dialog_content = "當時我找到啟光，他們派人告訴我……",
  ui_story_9_7_2_44_dialog_content = "負責那座地下城實驗的人，已經死在大火當中。",
  ui_story_9_7_2_45_dialog_content = "這是真的嗎？",
  ui_story_9_7_2_46_dialog_content = "我當然不相信啟光這些推卸責任的說法。",
  ui_story_9_7_2_47_dialog_content = "而且奇怪的是，他們始終不再提起那個研究員的名字。",
  ui_story_9_7_2_48_dialog_content = "所以我又自己派人去暗中調查。",
  ui_story_9_7_2_49_dialog_content = "但是調查結果……並沒有什麼不同。",
  ui_story_9_7_2_50_dialog_content = "不過，我這輩子都不會忘記那個名字——<color=#FFB400>「德尼耶爾」</color>。",
  ui_story_9_7_2_X50_dialog_content = "我們都被之前得知的消息誤導了，都以為那個實驗員死在大火之中。",
  ui_story_9_7_2_51_dialog_content = "所以見到吞羅後，才沒能第一時間認出她來！",
  ui_story_9_7_2_52_dialog_content = "是的。但現在仔細一想，吞羅恐怕就是德尼耶爾。",
  ui_story_9_7_2_53_dialog_content = "……！",
  ui_story_9_7_2_54_dialog_content = "啊……！！！",
  ui_story_9_7_2_55_dialog_content = "伊芙……",
  ui_story_9_7_2_56_dialog_content = "可惡！我要當面好好問問這個吞羅！",
  ui_story_9_7_2_57_dialog_content = "如果她真的對伊芙做過什麼，我醒山一定不會放過她！",
  ui_story_9_8_1_1_dialog_content = "<color=#e8d9bb>吞噬者號·治療繭內</color>",
  ui_story_9_8_1_2_dialog_content = "老師……",
  ui_story_9_8_1_3_dialog_content = "對不起……老師……再……",
  ui_story_9_8_1_4_dialog_content = "為什麼……",
  ui_story_9_8_1_5_dialog_content = "<color=#e8d9bb>空之山谷·教學巨像停泊處</color>",
  ui_story_9_8_1_6_dialog_content = "漢德羅老師，對不起！可以再給我一次機會嗎？",
  ui_story_9_8_1_7_dialog_content = "舒默，妳的三次機會已經全都用完了。",
  ui_story_9_8_1_8_dialog_content = "很遺憾，妳沒能通過這次「巨像駕駛實務」的測驗。",
  ui_story_9_8_1_9_dialog_content = "可……可是如果沒有通過，我就不能參加「吞噬者號」的導航員選拔了……",
  ui_story_9_8_1_10_dialog_content = "我必須通過這次考核！",
  ui_story_9_8_1_11_dialog_content = "舒默，我理解妳的心情。",
  ui_story_9_8_1_12_dialog_content = "妳是最令我自豪的學生之一，我當然希望妳能去參加選拔。",
  ui_story_9_8_1_13_dialog_content = "但無論是考核還是選拔，都必須做到公平和公正。",
  ui_story_9_8_1_14_dialog_content = "漢德羅老師，我準備好了！什麼時候開始考核？",
  ui_story_9_8_1_15_dialog_content = "好，我馬上過去。",
  ui_story_9_8_1_16_dialog_content = "舒默，看到妳這麼努力，老師真的非常欣慰。",
  ui_story_9_8_1_17_dialog_content = "老師相信，只要妳繼續鍛鍊自己，妳的感應能力就一定會得到強化！",
  ui_story_9_8_1_18_dialog_content = "等到下次的選拔，妳一定可以當上「吞噬者號」的導航員，好嗎？",
  ui_story_9_8_1_19_dialog_content = "可是，下次不知道還要等到什麼時候……",
  ui_story_9_8_1_20_dialog_content = "……",
  ui_story_9_8_1_21_dialog_content = "我看呀，妳是等不到那天囉！畢竟上次選拔已經是幾十年前的事了！",
  ui_story_9_8_1_X1_dialog_content = "（吵死了，平常當我不存在，一聽到我要參加選拔就跑出來擺母親架子。）",
  ui_story_9_8_1_X2_dialog_content = "舒默，雖然妳在之前的測驗中拿到了第一名。",
  ui_story_9_8_1_X3_dialog_content = "但妳不能驕傲，感應巨像和平時測驗不一樣，妳要更努力啊。",
  ui_story_9_8_1_X4_dialog_content = "（我知道，不需要妳來提醒。）",
  ui_story_9_8_1_22_dialog_content = "舒默，妳不是每次考核都拿第一的好學生嗎？",
  ui_story_9_8_1_23_dialog_content = "怎麼操作巨像這麼簡單的事，妳反而做不到呢？",
  ui_story_9_8_1_X5_dialog_content = "（我會做到的，等著瞧吧。）",
  ui_story_9_8_1_X6_dialog_content = "重點是，居然有人感應不到巨像？！舒默，妳還是不是個空裔啊？",
  ui_story_9_8_1_X7_dialog_content = "（閉嘴，只是稍微感應到一點的傢伙，有什麼好得意的？）",
  ui_story_9_8_1_24_dialog_content = "舒默沒有通過駕駛考核嗎？不會吧……",
  ui_story_9_8_1_X8_dialog_content = "（不過是一次考核而已，只要下一次……）",
  ui_story_9_8_1_X9_dialog_content = "漢德羅說妳很適合擔任吞噬者號的導航員？",
  ui_story_9_8_1_X10_dialog_content = "唉……妳還是早點放棄吧，這也是為妳好。",
  ui_story_9_8_1_X11_dialog_content = "妳沒有天分，也沒有這個資格……",
  ui_story_9_8_1_X12_dialog_content = "（閉嘴！你們都是白痴，什麼都不懂！）",
  ui_story_9_8_1_X13_dialog_content = "（總有一天……我會證明一切！）",
  ui_story_9_8_1_X14_dialog_content = "……",
  ui_story_9_8_1_25_dialog_content = "重點是，居然有人感應不到巨像？！舒默，妳還算不算是個空裔啊？",
  ui_story_9_8_1_26_dialog_content = "你……你們……",
  ui_story_9_8_1_27_dialog_content = "呿，還以為是誰呢，原來是膽小鬼孟德爾頌。",
  ui_story_9_8_1_28_dialog_content = "你想說什麼，倒是說說看啊！",
  ui_story_9_8_1_29_dialog_content = "你們……不要說了……",
  ui_story_9_8_1_30_dialog_content = "憑什麼？你叫我們不說，我們就不說嗎？",
  ui_story_9_8_1_31_dialog_content = "漢、漢德羅老師……",
  ui_story_9_8_1_32_dialog_content = "喔，老師怎麼了？",
  ui_story_9_8_1_33_dialog_content = "我……要告訴……",
  ui_story_9_8_1_34_dialog_content = "你要告訴漢德羅老師？哼，光靠老師有什麼用？",
  ui_story_9_8_1_35_dialog_content = "好了好了。都少說兩句吧……",
  ui_story_9_8_1_36_dialog_content = "哼，我們走！",
  ui_story_9_8_1_X15_dialog_content = "你、你們再欺負她……我、我就告訴漢德羅老師。",
  ui_story_9_8_1_37_dialog_content = "妳……妳沒事吧？",
  ui_story_9_8_1_38_dialog_content = "你誰啊？我看起來像需要幫忙嗎？不用你多管閒事。",
  ui_story_9_8_1_39_dialog_content = "我、我叫孟德爾頌……我看到他們好像、也、也在欺負妳……",
  ui_story_9_8_1_X16_dialog_content = "就……有點擔心……",
  ui_story_9_8_1_X17_dialog_content = "看到我被人欺負了，就趁機過來關心兩句？",
  ui_story_9_8_1_40_dialog_content = "你這只是在自作多情罷了。這麼做會讓你覺得自己很偉大嗎？",
  ui_story_9_8_1_X18_dialog_content = "你是不是跟他們一樣？",
  ui_story_9_8_1_X19_dialog_content = "心情好了就過來關心兩句，心情不好就過來嘲笑兩句？",
  ui_story_9_8_1_41_dialog_content = "不、不是的……",
  ui_story_9_8_1_X20_dialog_content = "不是？那是怎樣？",
  ui_story_9_8_1_42_dialog_content = "妳為什麼要幫我？",
  ui_story_9_8_1_43_dialog_content = "我、我……我知道，錯的是他們……",
  ui_story_9_8_1_44_dialog_content = "（錯的當然是他們……）",
  ui_story_9_8_1_45_dialog_content = "（自以為了不起……）",
  ui_story_9_8_1_46_dialog_content = "舒默，妳怎麼一個人在這裡？",
  ui_story_9_8_1_47_dialog_content = "……！",
  ui_story_9_8_1_48_dialog_content = "哈，原來是不會駕駛巨像的舒默啊！",
  ui_story_9_8_1_49_dialog_content = "妳是來學習怎麼和巨像建立感應的嗎？真是辛苦呢。",
  ui_story_9_8_1_50_dialog_content = "我們不要打擾舒默了，還是快走吧……",
  ui_story_9_8_1_51_dialog_content = "等會，我想到一個好主意。",
  ui_story_9_8_1_52_dialog_content = "我們來打個賭怎麼樣？",
  ui_story_9_8_1_53_dialog_content = "賭什麼？",
  ui_story_9_8_1_54_dialog_content = "舒默，妳敢跟我們去空谷外面晃一晃嗎？",
  ui_story_9_8_1_X21_dialog_content = "咦？這不就是我們上次計劃的事嗎……",
  ui_story_9_8_1_X22_dialog_content = "哈哈，你快看舒默，連頭都不敢抬一下，她一定是被你嚇壞了。",
  ui_story_9_8_1_55_dialog_content = "你們先說，敢不敢賭？",
  ui_story_9_8_1_56_dialog_content = "賭就賭！",
  ui_story_9_8_1_57_dialog_content = "你們幾個，虽然可以感應到巨像……但你們……敢開著巨像去空谷外面嗎？",
  ui_story_9_8_1_58_dialog_content = "可是，我上次也說了……漢德羅老師說外面很危險，可能會有暗鬼。",
  ui_story_9_8_1_59_dialog_content = "怎麼了？怕了嗎？",
  ui_story_9_8_1_60_dialog_content = "怕什麼？我們開巨像出去就行了。",
  ui_story_9_8_1_61_dialog_content = "你們要是能開著巨像去外面兜一圈回來，就算你們贏。",
  ui_story_9_8_1_62_dialog_content = "等我們贏了，就要妳好看！",
  ui_story_9_8_1_63_dialog_content = "巨像……就用「學徒一號」吧！",
  ui_story_9_8_1_64_dialog_content = "這樣真的不會被發現嗎？",
  ui_story_9_8_1_65_dialog_content = "放心吧，妳可是「吞噬者號」的下一任導航員，漢德羅老師欽定的勝利者！",
  ui_story_9_8_1_66_dialog_content = "……！",
  ui_story_9_8_1_67_dialog_content = "對，我們相信妳的技術！",
  ui_story_9_8_1_68_dialog_content = "就算被發現……誰敢對妳說什麼？",
  ui_story_9_8_1_69_dialog_content = "好吧……說好了，只有這一次！",
  ui_story_9_8_1_70_dialog_content = "喔！起飛囉——！",
  ui_story_9_8_1_X23_dialog_content = "舒默，妳敢不敢跟過來？",
  ui_story_9_8_1_X24_dialog_content = "我賭她不敢！賭三本書！",
  ui_story_9_8_1_71_dialog_content = "（吞噬者號……是我的……）",
  ui_story_9_8_1_72_dialog_content = "（你們什麼都不懂……所以……）",
  ui_story_9_8_1_73_dialog_content = "<color=#e8d9bb>空之山谷外</color>",
  ui_story_9_8_1_74_dialog_content = "巨像……無法啟動！",
  ui_story_9_8_1_75_dialog_content = "……",
  ui_story_9_8_1_76_dialog_content = "暗鬼！暗鬼在砸門了……！",
  ui_story_9_8_1_77_dialog_content = "怎……怎麼辦？",
  ui_story_9_8_1_78_dialog_content = "桀桀桀桀桀桀桀！",
  ui_story_9_8_1_79_dialog_content = "沒想到，竟然有獵物自己送上門來！",
  ui_story_9_8_1_X25_dialog_content = "（你們都死了。）",
  ui_story_9_8_1_80_dialog_content = "拼……拼了！",
  ui_story_9_8_1_81_dialog_content = "啊——！",
  ui_story_9_8_1_82_dialog_content = "不知天高地厚的小畜生，本來還可以多留你們一刻。",
  ui_story_9_8_1_83_dialog_content = "呃啊……",
  ui_story_9_8_1_84_dialog_content = "唔……",
  ui_story_9_8_1_85_dialog_content = "就這麼不耐打嗎？",
  ui_story_9_8_1_86_dialog_content = "只不過是稍微挑選一下而已，居然就擅自死掉了，真傷腦筋啊。",
  ui_story_9_8_1_87_dialog_content = "……",
  ui_story_9_8_1_88_dialog_content = "就這麼不經打嗎？輕輕一捏，骨頭就碎了。",
  ui_story_9_8_1_89_dialog_content = "我還想把你們的骨頭磨成項鍊，天天掛在身上欣賞呢。",
  ui_story_9_8_1_90_dialog_content = "……",
  ui_story_9_8_1_91_dialog_content = "（逃……從哪……可以逃走……）",
  ui_story_9_8_1_X91_dialog_content = "咕……",
  ui_story_9_8_1_92_dialog_content = "嗯？你說廢墟裡還躲了一隻小畜生？",
  ui_story_9_8_1_X92_dialog_content = "桀桀桀，有點意思。",
  ui_story_9_8_1_X26_dialog_content = "（……！）",
  ui_story_9_8_1_S1_dialog_content = "不要過來！！！",
  ui_story_9_8_1_X27_dialog_content = "安靜點……我這裡有個好消息。",
  ui_story_9_8_1_X28_dialog_content = "妳想聽嗎？",
  ui_story_9_8_1_X29_dialog_content = "……你、你會說通用語？！",
  ui_story_9_8_1_S2_dialog_content = "桀桀桀，在這種情況下還能想這些，妳不怕我殺了妳嗎？",
  ui_story_9_8_1_S3_dialog_content = "……怕。",
  ui_story_9_8_1_X30_dialog_content = "桀桀桀桀桀！那就豎起妳的耳朵，不要錯過任何一個字。",
  ui_story_9_8_1_93_dialog_content = "「偉大的母親降下旨意，空裔將在末日永遠消失。」",
  ui_story_9_8_1_94_dialog_content = "這是對空裔的最後審判，也是母親賜予空裔的幸福結局！",
  ui_story_9_8_1_95_dialog_content = "所以，慶幸吧！你們將看到這歷史性的一刻！",
  ui_story_9_8_1_96_dialog_content = "……什、什麼？",
  ui_story_9_8_1_97_dialog_content = "妳沒有資格提問！",
  ui_story_9_8_1_98_dialog_content = "因為弱者只配立刻去死！",
  ui_story_9_8_1_99_dialog_content = "就像妳那幾個朋友一樣，痛苦扭動，悽慘地死去。",
  ui_story_9_8_1_100_dialog_content = "……！",
  ui_story_9_8_1_101_dialog_content = "桀桀，不過沒關係。我決定選擇妳，我決定給妳機會。",
  ui_story_9_8_1_102_dialog_content = "我可以賜予妳超越空裔的力量！讓妳擺脫弱者的身分！",
  ui_story_9_8_1_103_dialog_content = "擺脫……",
  ui_story_9_8_1_104_dialog_content = "舒默，妳不是每次考核都拿第一的好學生嗎？",
  ui_story_9_8_1_105_dialog_content = "怎麼操作巨像這麼簡單的事，妳反而做不到呢？",
  ui_story_9_8_1_106_dialog_content = "舒默沒有通過駕駛考核嗎？不會吧……",
  ui_story_9_8_1_107_dialog_content = "重點是，居然有人感應不到巨像？！舒默，妳還算不算是個空裔啊？",
  ui_story_9_8_1_108_dialog_content = "這樣真的不會被發現嗎？",
  ui_story_9_8_1_109_dialog_content = "放心吧，妳可是「吞噬者號」的下一任導航員，漢德羅老師欽定的勝利者！",
  ui_story_9_8_1_110_dialog_content = "看到這顆種子了嗎？這就是妳的希望。",
  ui_story_9_8_1_111_dialog_content = "……我的……希望。",
  ui_story_9_8_1_112_dialog_content = "很好，我瞭解妳對力量的渴望了。",
  ui_story_9_8_1_113_dialog_content = "力……量……",
  ui_story_9_8_1_114_dialog_content = "舒……舒默，妳……？",
  ui_story_9_8_1_115_dialog_content = "對，只有選擇成為母親的子民，才能活下去！",
  ui_story_9_8_1_116_dialog_content = "活……下去……",
  ui_story_9_8_1_117_dialog_content = "妳將不再弱小，不再恐懼！",
  ui_story_9_8_1_118_dialog_content = "接受恩賜，獲得力量，加入我們！",
  ui_story_9_8_1_119_dialog_content = "你就可以主宰世界，主宰一切！",
  ui_story_9_8_1_120_dialog_content = "主宰……一切……",
  ui_story_9_8_1_121_dialog_content = "舒默……不……不要過去……",
  ui_story_9_8_1_122_dialog_content = "對，就是這樣，過來吧。",
  ui_story_9_8_1_123_dialog_content = "不……不要……求求妳……",
  ui_story_9_8_1_124_dialog_content = "……",
  ui_story_9_8_1_125_dialog_content = "怎麼了？",
  ui_story_9_8_1_126_dialog_content = "我……",
  ui_story_9_8_1_127_dialog_content = "撿起這把刀！",
  ui_story_9_8_1_128_dialog_content = "我……",
  ui_story_9_8_1_129_dialog_content = "別拖拖拉拉的，我的耐心有限！妳到底在猶豫什麼？！",
  ui_story_9_8_1_130_dialog_content = "我、我會變成暗鬼……對嗎？",
  ui_story_9_8_1_131_dialog_content = "哼，也罷。",
  ui_story_9_8_1_132_dialog_content = "啊——！",
  ui_story_9_8_1_133_dialog_content = "你……！",
  ui_story_9_8_1_134_dialog_content = "你討厭這個女孩，對吧？",
  ui_story_9_8_1_135_dialog_content = "……",
  ui_story_9_8_1_136_dialog_content = "我幫妳殺掉她，你不應該感謝我嗎？",
  ui_story_9_8_1_137_dialog_content = "妳也要……殺掉我嗎？",
  ui_story_9_8_1_138_dialog_content = "怎麼會呢？",
  ui_story_9_8_1_139_dialog_content = "我能看出來，妳和他們不同，是個能成為強者的可造之材。",
  ui_story_9_8_1_140_dialog_content = "當然，成為暗鬼，妳就能獲得超越空裔、甚至超越光靈的力量！",
  ui_story_9_8_1_141_dialog_content = "那……那是一種什麼樣的力量？",
  ui_story_9_8_1_142_dialog_content = "那是母親滋潤大地的甘泉，是母親賜予眾生的無上恩典。",
  ui_story_9_8_1_143_dialog_content = "可以讓妳活下去，讓妳不再懼怕任何事物。",
  ui_story_9_8_1_144_dialog_content = "也就是說，只有接受它……我才能……活下去？",
  ui_story_9_8_1_145_dialog_content = "當然，妳甚至可以比這座山谷更長壽。",
  ui_story_9_8_1_146_dialog_content = "接受它……我就可以……不再弱小？",
  ui_story_9_8_1_147_dialog_content = "當然，從今以後，只有強大可以用來形容妳的力量。",
  ui_story_9_8_1_S147_dialog_content = "接受的話……我就有資格擁有吞噬者號了？",
  ui_story_9_8_1_S148_dialog_content = "吞噬者號？是巨像嗎？",
  ui_story_9_8_1_S149_dialog_content = "桀桀桀，告訴我，妳想要的這座的巨像是怎麼樣的？",
  ui_story_9_8_1_S150_dialog_content = "吞噬者號……是最強大的巨像，只有最強的空裔……才有資格擁有。",
  ui_story_9_8_1_S151_dialog_content = "桀！桀！桀！那妳將比任何空裔都有資格擁有！因為妳將超越所有空裔啊！",
  ui_story_9_8_1_148_dialog_content = "……",
  ui_story_9_8_1_149_dialog_content = "我……",
  ui_story_9_8_1_150_dialog_content = "……我接受。",
  ui_story_9_8_1_151_dialog_content = "桀桀桀桀桀桀桀！",
  ui_story_9_8_1_152_dialog_content = "唔……！",
  ui_story_9_8_1_153_dialog_content = "偉大的母親啊，世上又多了一個您的僕人！",
  ui_story_9_8_1_154_dialog_content = "你真的把力量給我了嗎？",
  ui_story_9_8_1_155_dialog_content = "為什麼我現在一點感覺都沒有……",
  ui_story_9_8_1_156_dialog_content = "妳的名字叫舒默對吧？",
  ui_story_9_8_1_157_dialog_content = "記住，舒默，沒有人可以質疑母親的力量。妳要學會等待。",
  ui_story_9_8_1_158_dialog_content = "……",
  ui_story_9_8_1_159_dialog_content = "接下來，你要帶我去哪裡？",
  ui_story_9_8_1_160_dialog_content = "舒默，我們哪都不去。我只要妳回到空谷，當然，要帶我一起回去。",
  ui_story_9_8_1_161_dialog_content = "回空谷？！",
  ui_story_9_8_1_162_dialog_content = "妳忘了？妳的「吞噬者號」還在空谷等妳。",
  ui_story_9_8_1_163_dialog_content = "有了「吞噬者號」，妳的力量才是完整的、無可匹敵的！",
  ui_story_9_8_1_164_dialog_content = "我沒有忘。只是，我和別人不一樣。",
  ui_story_9_8_1_165_dialog_content = "我……沒辦法感應到巨像，我還以為，可以等一切結束以後……",
  ui_story_9_8_1_166_dialog_content = "喔？無法感應的空裔？",
  ui_story_9_8_1_167_dialog_content = "不許你這麼說！！！",
  ui_story_9_8_1_168_dialog_content = "罷了，「種子」已經開始在妳的體內咆哮。",
  ui_story_9_8_1_169_dialog_content = "從今天起，妳，已經不再只是個空裔。",
  ui_story_9_8_1_170_dialog_content = "現在，妳可以去試試啟動這架巨像了。",
  ui_story_9_8_1_171_dialog_content = "……好。",
  ui_story_9_8_1_172_dialog_content = "不是……不是。真的……！",
  ui_story_9_8_1_173_dialog_content = "沒有輸……我沒有輸……！",
  ui_story_9_8_1_174_dialog_content = "舒默！！",
  ui_story_9_8_1_175_dialog_content = "我要妳在死的時候，直視我的眼睛！！！",
  ui_story_9_8_1_176_dialog_content = "不、不——",
  ui_story_9_8_1_177_dialog_content = "不！！！！！！",
  ui_story_9_9_1_1_dialog_content = "大家小心腳下！",
  ui_story_9_9_1_2_dialog_content = "怎麼回事？！",
  ui_story_9_9_1_3_dialog_content = "<color=#e8d9bb>嗚——嗚——嗚——</color>",
  ui_story_9_9_1_4_dialog_content = "聲音……我聽到很多聲音……",
  ui_story_9_9_1_5_dialog_content = "欸？是地面晃動的聲音嗎？",
  ui_story_9_9_1_6_dialog_content = "不、不是……這是……吞噬者號的嗚咽與悲鳴……",
  ui_story_9_9_1_7_dialog_content = "<color=#e8d9bb>嗚——嗚——嗚——</color>",
  ui_story_9_9_1_8_dialog_content = "（全都是……巨像的哀鳴聲……好像連曾經埋在這裡的巨像都在哀鳴……）",
  ui_story_9_9_1_9_dialog_content = "<color=#e8d9bb><anim type=Shake>嗚——嗚——嗚——</anim></color>",
  ui_story_9_9_1_10_dialog_content = "（心臟好像被劃開了一道傷口……）",
  ui_story_9_9_1_11_dialog_content = "（有什麼熱熱的液體正在流淌……）",
  ui_story_9_9_1_12_dialog_content = "是……眼淚嗎？",
  ui_story_9_9_1_13_dialog_content = "PlayerName……",
  ui_story_9_9_1_14_dialog_content = "PlayerName……你在流眼淚？",
  ui_story_9_9_1_15_dialog_content = "PlayerName……",
  ui_story_9_9_1_16_dialog_content = "沒事……我只是……只是又想到了臨空者。",
  ui_story_9_9_1_X16_dialog_content = "PlayerName……",
  ui_story_9_9_1_17_dialog_content = "……薇絲。",
  ui_story_9_9_1_18_dialog_content = "又感應到什麼了嗎？別擔心，我們都在！",
  ui_story_9_9_1_19_dialog_content = "那個……如果不介意的話……給你這個。",
  ui_story_9_9_1_20_dialog_content = "這是……？",
  ui_story_9_9_1_21_dialog_content = "是手帕……PlayerName可以用這個擦下眼淚。",
  ui_story_9_9_1_22_dialog_content = "對不起，不知道為什麼，我……",
  ui_story_9_9_1_23_dialog_content = "PlayerName，你不用向我們道歉。",
  ui_story_9_9_1_24_dialog_content = "眼淚不是弱者的專利，任何人都有需要發洩情緒的時候。",
  ui_story_9_9_1_25_dialog_content = "嗯。",
  ui_story_9_9_1_26_dialog_content = "小子，你感應到什麼了？",
  ui_story_9_9_1_27_dialog_content = "我聽到許多巨像的哀鳴，好多聲音，一波接著一波。",
  ui_story_9_9_1_28_dialog_content = "那些聲音，好像是在感嘆命運……又好像是在祭奠親人的離去……",
  ui_story_9_9_1_29_dialog_content = "我的心整個揪了起來，覺得……很難過。",
  ui_story_9_9_1_30_dialog_content = "……這裡還有其他巨像嗎？",
  ui_story_9_9_1_31_dialog_content = "我想……我聽到的那些，並不是真實的……",
  ui_story_9_9_1_32_dialog_content = "那些聲音，只是巨像殘存在空谷的……留戀。",
  ui_story_9_9_1_33_dialog_content = "為什麼偏偏在這個時候……？",
  ui_story_9_9_1_34_dialog_content = "……",
  ui_story_9_9_1_35_dialog_content = "PlayerName，你還能感應到吞噬者號嗎？",
  ui_story_9_9_1_36_dialog_content = "空谷裡的暗能愈來愈濃。",
  ui_story_9_9_1_37_dialog_content = "我只能斷斷續續地感應到吞噬者號微弱的氣息。",
  ui_story_9_9_1_38_dialog_content = "只是現在……我又什麼都捕捉不到了。",
  ui_story_9_9_1_39_dialog_content = "PlayerName可以感應到巨像的意識，好羨慕……",
  ui_story_9_9_1_40_dialog_content = "感應能力是空裔的本能和天賦，就像妳可以使用光能戰鬥一樣。",
  ui_story_9_9_1_41_dialog_content = "其實我一直很好奇……",
  ui_story_9_9_1_42_dialog_content = "對巨像的感應，是什麼樣感覺呀？",
  ui_story_9_9_1_43_dialog_content = "什麼感覺嗎……？",
  ui_story_9_9_1_44_dialog_content = "妳這麼一問，我還真不知道該怎麼回答了。",
  ui_story_9_9_1_45_dialog_content = "（十七年來，我早就習慣臨空者陪在自己身邊的日子……）",
  ui_story_9_9_1_46_dialog_content = "（如果……如果我以後再也感應不到臨空者……）",
  ui_story_9_9_1_47_dialog_content = "PlayerName，如果你不想回答的話……也不用勉強啦。",
  ui_story_9_9_1_48_dialog_content = "沒關係，我沒有覺得勉強。",
  ui_story_9_9_1_49_dialog_content = "只是忽然意識到，自己居然從來沒有仔細想過這個問題。",
  ui_story_9_9_1_50_dialog_content = "能感應到巨像的時候……會感覺到安心和溫暖……",
  ui_story_9_9_1_51_dialog_content = "他就像一個知心的朋友，永遠知道你在想什麼。",
  ui_story_9_9_1_52_dialog_content = "而妳也是唯一一個知道他在說什麼的人。",
  ui_story_9_9_1_53_dialog_content = "雖然有的時候，會覺得他很嘮叨。",
  ui_story_9_9_1_54_dialog_content = "但如果他不嘮叨了，又會覺得少了點什麼……",
  ui_story_9_9_1_55_dialog_content = "可以感應到巨像，也許是一種……幸福的感覺。",
  ui_story_9_9_1_56_dialog_content = "幸福的感覺……",
  ui_story_9_9_1_57_dialog_content = "我也好想知道「陸行者」在想什麼……",
  ui_story_9_9_1_58_dialog_content = "欸，難道妳提到的這個「陸行者」也是巨像？",
  ui_story_9_9_1_59_dialog_content = "哈哈哈，「陸行者號」可是我們紅油扳手引以為傲的一員！",
  ui_story_9_9_1_60_dialog_content = "當年我們在紅油沙漠，發現了半截埋在沙子裡的肌材。",
  ui_story_9_9_1_61_dialog_content = "沒想到挖了半天，竟然挖出來一座破破爛爛的巨像。",
  ui_story_9_9_1_62_dialog_content = "我們科學班的伙計們可是折騰了一番，才把它給修好。",
  ui_story_9_9_1_63_dialog_content = "不過，「陸行者號」只讓叭噗駕駛。",
  ui_story_9_9_1_64_dialog_content = "要是換成其他人開，它連尾巴都不抬一下。",
  ui_story_9_9_1_65_dialog_content = "我也是摸索了好久，才學會駕駛「陸行者」的。",
  ui_story_9_9_1_66_dialog_content = "無法感應巨像，卻能駕駛巨像嗎？",
  ui_story_9_9_1_67_dialog_content = "嗯，我也說不清楚……",
  ui_story_9_9_1_68_dialog_content = "但有時候，我覺得我好像能體會到「陸行者」的情緒。",
  ui_story_9_9_1_69_dialog_content = "剛發現「陸行者」的時候，它大概特別孤單，特別迷茫吧……",
  ui_story_9_9_1_70_dialog_content = "雖然不知道它在想什麼，但我還是天天和它聊天。",
  ui_story_9_9_1_71_dialog_content = "現在，它已經喜歡上在紅油扳手的生活啦。",
  ui_story_9_9_1_72_dialog_content = "哈哈哈哈，感應不感應的，對於叭噗來說都不是問題。",
  ui_story_9_9_1_73_dialog_content = "有她現在的駕駛技術，就已經夠了！",
  ui_story_9_9_1_74_dialog_content = "沒想到，遊蕩在沙漠裡的劫匪也有自己的巨像。",
  ui_story_9_9_1_75_dialog_content = "卡蓮小姐，外面的世界還有很多妳意想不到的事情。",
  ui_story_9_9_1_76_dialog_content = "總是待在城堡裡，可不是件好事！",
  ui_story_9_9_1_77_dialog_content = "……",
  ui_story_9_9_1_78_dialog_content = "當心後面！",
  ui_story_9_9_1_79_dialog_content = "難道……又是光靈變成的暗鬼？",
  ui_story_9_9_1_80_dialog_content = "可是這數量……也太多了……",
  ui_story_9_9_1_81_dialog_content = "很明顯，之前有白夜城的衛兵來偵查過這裡，恐怕都被抓去當實驗品了。",
  ui_story_9_9_1_82_dialog_content = "……！",
  ui_story_9_9_1_83_dialog_content = "PlayerName，給我指示！在他們感受到痛苦前，盡快了結他們吧。",
  ui_story_9_13_1_1_dialog_content = "白夜至上，願你們在此地安息。",
  ui_story_9_13_1_2_dialog_content = "願你們安息……",
  ui_story_9_13_1_3_dialog_content = "PlayerName，我們還要多久能走到？",
  ui_story_9_13_1_4_dialog_content = "雖然氣息微弱，但吞噬者號應該就在這附近！",
  ui_story_9_13_1_X4_dialog_content = "「附近」是哪個方向？左邊？右邊？還是前面？",
  ui_story_9_13_1_5_dialog_content = "吼——！",
  ui_story_9_13_1_6_dialog_content = "前方有大批暗鬼，衝著我們來了！",
  ui_story_9_13_1_7_dialog_content = "PlayerName，告訴我該往哪個方向走！直接打出一條路來！",
  ui_story_9_13_2_1_dialog_content = "這裡好像有一個！就在那隻暗鬼屍體的脖子裡。",
  ui_story_9_13_2_2_dialog_content = "呃……難以置信，這暗鬼怎麼這麼髒？我根本沒辦法下手。",
  ui_story_9_13_2_3_dialog_content = "聖釘，麻煩去幫一下契法，好嗎？",
  ui_story_9_13_2_4_dialog_content = "……",
  ui_story_9_13_2_5_dialog_content = "偉大的真理之主，請寬恕我吧……",
  ui_story_9_13_2_6_dialog_content = "教義說道「不可沾染不潔之物」。",
  ui_story_9_13_2_7_dialog_content = "但是為了追尋您的足跡，我即將要見聞我不該見聞的，觸碰我不該觸碰的……",
  ui_story_9_13_2_8_dialog_content = "回去之後，我會沐浴三天以祈求您的寬恕……",
  ui_story_9_13_2_9_dialog_content = "……",
  ui_story_9_13_2_10_dialog_content = "請把它餵給白箱吧。",
  ui_story_9_13_2_11_dialog_content = "<color=#e8d9bb>咻——</color>",
  ui_story_9_13_2_12_dialog_content = "為什麼一定得把種子餵給白箱？",
  ui_story_9_13_2_X12_dialog_content = "白箱似乎滿愛吃這東西的，它萬一吐出來了怎麼辦？",
  ui_story_9_13_2_X13_dialog_content = "既然聖釘敢拿，就讓他拿著吧。",
  ui_story_9_13_2_X14_dialog_content = "……",
  ui_story_9_13_2_13_dialog_content = "請寬恕我，維多利亞大人，我不應產生怒火……",
  ui_story_9_13_2_14_dialog_content = "契法，請不要小看這顆「種子」。",
  ui_story_9_13_2_X15_dialog_content = "它體積雖小，但裡頭蘊含的暗能，能對普通光靈造成嚴重的精神影響。",
  ui_story_9_13_2_X16_dialog_content = "我們身體裡確實含有強大的光能，但也只能暫時抵抗這種影響。",
  ui_story_9_13_2_X17_dialog_content = "無法長期接觸它。",
  ui_story_9_13_2_15_dialog_content = "好吧，看來這也是一種「條律」，我確實不該小看它。",
  ui_story_9_14_1_1_dialog_content = "就是前面了。",
  ui_story_9_14_1_2_dialog_content = "大家保持警戒！",
  ui_story_9_14_1_3_dialog_content = "這就是……吞噬者號嗎？",
  ui_story_9_14_1_4_dialog_content = "好可怕，還是「陸行者」比較可愛……",
  ui_story_9_14_1_5_dialog_content = "光砲的攻擊加上墜落的衝擊……",
  ui_story_9_14_1_6_dialog_content = "吞噬者號現在的樣子……真是慘不忍睹。",
  ui_story_9_14_1_7_dialog_content = "嗯，而且剛才……吞噬者號發出哀鳴聲時，就好像在步入死亡一樣。",
  ui_story_9_14_1_8_dialog_content = "我們還是快點進去找舒默的屍體吧。",
  ui_story_9_14_1_9_dialog_content = "等等，有人出來了！",
  ui_story_9_14_1_10_dialog_content = "是舒默嗎？",
  ui_story_9_14_1_11_dialog_content = "不對，一定不是舒默。",
  ui_story_9_14_1_12_dialog_content = "是<color=#FFB400>吞羅</color>！！",
  ui_story_9_14_1_13_dialog_content = "！！！",
  ui_story_9_14_1_14_dialog_content = "……！",
  ui_story_9_14_1_15_dialog_content = "剛剛還在想，是誰會在這個時候來打擾我的計畫？",
  ui_story_9_14_1_16_dialog_content = "原來是你們。",
  ui_story_9_14_1_17_dialog_content = "沒人教過你們，作客的時候要首先打招呼嗎？",
  ui_story_9_14_1_18_dialog_content = "這句話應該換我們來問妳吧？",
  ui_story_9_14_1_19_dialog_content = "這裡是空之山谷，不是妳該出現的地方！",
  ui_story_9_14_1_20_dialog_content = "既然我在這裡，就輪不到你們定規則。",
  ui_story_9_14_1_21_dialog_content = "是妳……",
  ui_story_9_14_1_22_dialog_content = "我還以為妳早就死在那場大火裡了！",
  ui_story_9_14_1_23_dialog_content = "不過就算妳化成灰，我都記得妳的樣子！別以為妳換個名字就沒事了！",
  ui_story_9_14_1_24_dialog_content = "……",
  ui_story_9_14_1_25_dialog_content = "喂！<color=#FFB400>「德尼耶爾」</color>！妳當年到底對我妹妹做了什麼？！",
  ui_story_9_14_1_26_dialog_content = "……",
  ui_story_9_14_1_27_dialog_content = "喂！聾了嗎？！！",
  ui_story_9_14_1_28_dialog_content = "PlayerName，你身上沒有暗能的氣息了……",
  ui_story_9_14_1_29_option_content = "妳到底是誰？",
  ui_story_9_14_1_30_dialog_content = "難道妳以前真的是啟光的研究員？",
  ui_story_9_14_1_31_dialog_content = "是又怎樣，不是又怎樣？",
  ui_story_9_14_1_32_dialog_content = "這很重要嗎？",
  ui_story_9_14_1_33_dialog_content = "跟我一點關係也沒有。",
  ui_story_9_14_1_34_dialog_content = "倒是你，PlayerName。回答我，你身上的「種子」呢？",
  ui_story_9_14_1_35_dialog_content = "在我背上埋「種子」的人，原來就是妳！",
  ui_story_9_14_1_36_dialog_content = "害我癢了好久。",
  ui_story_9_14_1_37_dialog_content = "癢？",
  ui_story_9_14_1_38_dialog_content = "然後呢，癢的症狀持續了多久？",
  ui_story_9_14_1_39_dialog_content = "大概有……我為什麼要告訴妳？！",
  ui_story_9_14_1_40_dialog_content = "PlayerName，小心！別被她牽著鼻子走。",
  ui_story_9_14_1_41_dialog_content = "你是怎麼取出背上的「種子」的？",
  ui_story_9_14_1_42_dialog_content = "想知道？那你得先告訴我——",
  ui_story_9_14_1_43_option_content = "妳為什麼會在空谷？",
  ui_story_9_14_1_44_dialog_content = "為什麼要把光靈變成暗鬼？！為什麼做這些殘酷的實驗？",
  ui_story_9_14_1_45_option_content = "妳為什麼要給我「種子」？",
  ui_story_9_14_1_46_dialog_content = "如果我不把「種子」取出來，是不是會變成暗鬼？！",
  ui_story_9_14_1_47_dialog_content = "你的問題太多了。",
  ui_story_9_14_1_48_dialog_content = "PlayerName，我只能告訴你，我非常失望。",
  ui_story_9_14_1_49_dialog_content = "我給過你機會，好心邀請你走近力量，走近這個世界的真相。",
  ui_story_9_14_1_50_dialog_content = "可惜的是你自己不知道珍惜，親手葬送了一切。",
  ui_story_9_14_1_51_dialog_content = "真是浪費。",
  ui_story_9_14_1_52_dialog_content = "PlayerName，現在，你已經沒有機會知道了。",
  ui_story_9_14_1_53_dialog_content = "別聽她在那故弄玄虛！",
  ui_story_9_14_1_54_dialog_content = "我敢肯定，面前的這個人，就是前啟光研究員——「德尼耶爾」！",
  ui_story_9_14_1_55_dialog_content = "「德尼耶爾」？我好像不認識這個人。",
  ui_story_9_14_1_56_dialog_content = "別裝了！",
  ui_story_9_14_1_57_dialog_content = "伊芙這些年受了那麼多苦，就是因為被妳這個混蛋利用！",
  ui_story_9_14_1_58_dialog_content = "伊芙？",
  ui_story_9_14_1_59_dialog_content = "怎麼，終於想起來了？",
  ui_story_9_14_1_60_dialog_content = "有印象，但是想不起來。",
  ui_story_9_14_1_61_dialog_content = "畢竟我經手的實驗品實在太多了。",
  ui_story_9_14_1_62_dialog_content = "你……！",
  ui_story_9_14_1_63_dialog_content = "醒山，冷靜。很明顯，吞羅這是在故意激怒你。",
  ui_story_9_14_1_64_dialog_content = "老子現在冷靜得很！",
  ui_story_9_14_1_65_dialog_content = "冷靜到已經想好了一百種把她大卸八塊的方法！",
  ui_story_9_14_1_66_dialog_content = "依我看，你是想到了一百種自討苦吃的方法。",
  ui_story_9_14_1_67_dialog_content = "看來不讓妳吃點苦頭，妳是不會好好說話了！",
  ui_story_9_14_1_68_dialog_content = "……",
  ui_story_9_14_1_69_dialog_content = "只有這點本事，也敢口出狂言。",
  ui_story_9_14_1_70_dialog_content = "老大！你……還好嗎？",
  ui_story_9_14_1_71_dialog_content = "咳，不礙事！",
  ui_story_9_14_1_72_dialog_content = "剛剛發生了什麼事……？",
  ui_story_9_14_1_73_dialog_content = "她剛才一揮手……就把醒山擊飛了？！",
  ui_story_9_14_1_74_dialog_content = "這是暗影術的一種。",
  ui_story_9_14_1_75_dialog_content = "看來我們面前的這個吞羅，已經放棄了光靈的身分，變成了某種怪物！",
  ui_story_9_14_1_76_dialog_content = "妳這個混蛋，老子要讓妳不得好死！",
  ui_story_9_14_1_77_dialog_content = "安靜點，不要不知好歹。",
  ui_story_9_14_1_78_dialog_content = "我不喜歡爭鬥。",
  ui_story_9_14_1_79_dialog_content = "你們要是想玩玩，我倒是可以給你們找個相稱的對手。",
  ui_story_9_14_1_80_dialog_content = "瘋角，來會會你朋友吧。",
  ui_story_9_14_1_81_dialog_content = "<anim type=Shake>塔巴……不會……終結！</anim>",
  ui_story_9_14_1_82_dialog_content = "什麼瘋角？這明明就是之前那個塔巴德！",
  ui_story_9_14_1_X82_dialog_content = "名字不過是方便記錄的代號……",
  ui_story_9_14_1_83_dialog_content = "你們見過這隻暗鬼？",
  ui_story_9_14_1_84_dialog_content = "在守祕者號上，緋長官已經給了它致命一擊……",
  ui_story_9_14_1_85_dialog_content = "又是復活屍體的伎倆。",
  ui_story_9_14_1_86_dialog_content = "原來一直在復活屍體的人，就是吞羅！",
  ui_story_9_14_1_87_dialog_content = "只是一些重複利用的瑕疵品罷了。",
  ui_story_9_14_1_88_dialog_content = "不過陪你們玩，還算綽綽有餘。",
  ui_story_9_14_1_89_dialog_content = "<anim type=Shake>吼——！！！</anim>",
  ui_story_9_14_1_90_dialog_content = "<anim type=Shake>塔巴……不會……終結！</anim>",
  ui_story_9_14_2_1_dialog_content = "<anim type=Shake>嘎——</anim>",
  ui_story_9_14_2_2_dialog_content = "注意！吞羅有所行動！",
  ui_story_9_14_2_3_dialog_content = "PlayerName，小心！",
  ui_story_9_14_2_4_dialog_content = "……！",
  ui_story_9_14_2_5_dialog_content = "休想動他——！",
  ui_story_9_14_2_6_dialog_content = "……",
  ui_story_9_14_2_7_dialog_content = "老大……！",
  ui_story_9_14_2_8_dialog_content = "醒山，你沒事吧……？",
  ui_story_9_14_2_9_dialog_content = "我好得很！咳……",
  ui_story_9_14_2_10_dialog_content = "墮落的光靈，倘若妳再上前一步，我將以此槍執行正義！",
  ui_story_9_14_2_11_dialog_content = "你們不用這麼激動。",
  ui_story_9_14_2_12_dialog_content = "我只不過是想仔細看看PlayerName罷了。",
  ui_story_9_14_2_13_dialog_content = "吞羅！妳到底想對PlayerName做什麼？！",
  ui_story_9_14_2_14_dialog_content = "你們不肯回答我的問題，我只好親自研究。",
  ui_story_9_14_2_15_dialog_content = "PlayerName，你身上果然已經沒有「種子」的痕跡。",
  ui_story_9_14_2_16_dialog_content = "最後一次問你，你是怎麼把「種子」拿出來的？",
  ui_story_9_14_2_17_dialog_content = "先回答我，妳為什麼要做這些「種子」的實驗？",
  ui_story_9_14_2_18_dialog_content = "PlayerName，你還沒有搞清狀況。",
  ui_story_9_14_2_19_dialog_content = "你沒有資格，也沒有實力跟我談條件。",
  ui_story_9_14_2_20_dialog_content = "PlayerName，別跟她廢話了。",
  ui_story_9_14_2_21_dialog_content = "嗯？",
  ui_story_9_14_2_22_dialog_content = "是我幫PlayerName挖出來的，有什麼問題嗎？",
  ui_story_9_14_2_23_dialog_content = "啟光怎麼會有妳這樣子的叛徒？！",
  ui_story_9_14_2_24_dialog_content = "薇絲，不要亂來！",
  ui_story_9_14_2_25_dialog_content = "你們最好給我說實話。",
  ui_story_9_14_2_26_dialog_content = "啊——！唔……",
  ui_story_9_14_2_27_dialog_content = "薇絲！！！",
  ui_story_9_14_2_28_dialog_content = "吞羅！放開薇絲！！！",
  ui_story_9_14_2_29_dialog_content = "我可以不動手，但你要拿出誠意。",
  ui_story_9_14_2_30_dialog_content = "說，「種子」去哪了？",
  ui_story_9_14_2_31_dialog_content = "……",
  ui_story_9_14_2_32_dialog_content = "（不能把薇絲置於危險之中……）",
  ui_story_9_14_2_33_dialog_content = "（只能這麼說了……）",
  ui_story_9_14_2_34_dialog_content = "妳想知道什麼我都告訴妳，妳先放開她！我保證告訴妳！",
  ui_story_9_14_2_X34_dialog_content = "好。",
  ui_story_9_14_2_X35_dialog_content = "咳、咳……",
  ui_story_9_14_2_X36_dialog_content = "薇絲！快過來！",
  ui_story_9_14_2_X37_dialog_content = "好了，說吧。",
  ui_story_9_14_2_35_dialog_content = "我身上的「種子」，被一個手提白箱的男人帶走了。",
  ui_story_9_14_2_36_dialog_content = "白箱，男人……",
  ui_story_9_14_2_37_dialog_content = "誰？",
  ui_story_9_14_2_38_dialog_content = "我不認識他，也不知道為什麼他要帶走「種子」。",
  ui_story_9_14_2_39_dialog_content = "但是他告訴我，「種子」可以把光靈轉化成暗鬼！",
  ui_story_9_14_2_40_dialog_content = "妳不僅想用「種子」把我變成暗鬼，還把白夜城的衛兵變成了暗鬼！",
  ui_story_9_14_2_41_dialog_content = "妳口中的實驗品，其實都是妳測試「種子」的受害者！",
  ui_story_9_14_2_42_dialog_content = "對不對？！",
  ui_story_9_14_2_43_dialog_content = "既然你這麼相信自己的判斷，就不要再問我了。",
  ui_story_9_14_2_44_dialog_content = "不，我要知道，妳為什麼要做這種慘無人道的實驗？",
  ui_story_9_14_2_45_dialog_content = "為什麼身為光靈，卻站在黑暗的那一邊？",
  ui_story_9_14_2_46_dialog_content = "我應該說過，PlayerName，你已經沒有機會知道這一切了。",
  ui_story_9_14_2_47_dialog_content = "<color=#e8d9bb>轟——啪！</color>",
  ui_story_9_14_2_48_dialog_content = "喔？時間到了。",
  ui_story_9_14_2_49_dialog_content = "什麼聲音？",
  ui_story_9_14_2_50_dialog_content = "是……從吞噬者號裡面傳來的……",
  ui_story_9_14_2_51_dialog_content = "這聽起來像是……巨像停止運作的聲音。",
  ui_story_9_14_2_52_dialog_content = "（剛才還能感應到吞噬者號微弱的氣息，忽然一點都感應不到了。）",
  ui_story_9_14_2_53_dialog_content = "（難道……吞噬者號……已經死了？）",
  ui_story_9_14_2_54_dialog_content = "吞羅！妳連吞噬者號都不放過嗎？",
  ui_story_9_14_2_55_dialog_content = "妳對它做了什麼？",
  ui_story_9_14_2_56_dialog_content = "PlayerName，你的問題真的很多。",
  ui_story_9_14_2_57_dialog_content = "要是想知道發生了什麼，不如來巨像裡，直接問問你的<color=#FFB400>「老朋友」</color>吧。",
  ui_story_9_14_2_58_dialog_content = "吞羅！她往吞噬者號裡面走了！",
  ui_story_9_14_2_59_dialog_content = "喂！！妳給老子回來！！！",
  ui_story_9_14_2_60_dialog_content = "<color=#FFB400>「老朋友」</color>……？",
  ui_story_9_14_2_61_dialog_content = "……",
  ui_story_9_14_2_62_dialog_content = "舒默……",
  ui_story_9_14_2_63_dialog_content = "<size=45>舒默還活著！！！</size>",
  ui_story_10_1_1_1_dialog_content = "<color=#e8d9bb>白夜城內，醫療所前</color>",
  ui_story_10_1_1_2_dialog_content = "原來白夜城的中庭區長這樣喵。",
  ui_story_10_1_1_S1_dialog_content = "這些建築……真是一棟比一棟豪華呢。",
  ui_story_10_1_1_3_dialog_content = "真希望薇薇安長官能在這裡多休息一陣子，這樣菲莉詩也能多休息……",
  ui_story_10_1_1_4_dialog_content = "喵？",
  ui_story_10_1_1_5_dialog_content = "新的患者在哪裡？我馬上過去！",
  ui_story_10_1_1_6_dialog_content = "拉斐爾騎士長，請您不要在這裡飛行！",
  ui_story_10_1_1_7_dialog_content = "……走了喵？",
  ui_story_10_1_1_8_dialog_content = "看來菲莉詩行動的機會出現了。",
  ui_story_10_1_1_9_dialog_content = "<color=#e8d9bb>颯——</color>",
  ui_story_10_1_1_10_dialog_content = "唉，這傷到底什麼時候才能好，一直在這待著什麼都不能做。",
  ui_story_10_1_1_11_dialog_content = "居！",
  ui_story_10_1_1_12_dialog_content = "謝謝你的安慰，居里。我沒事，只是有點焦慮而已……",
  ui_story_10_1_1_13_dialog_content = "你幫忙出去守著吧。",
  ui_story_10_1_1_14_dialog_content = "居！",
  ui_story_10_1_1_15_dialog_content = "另外……",
  ui_story_10_1_1_16_dialog_content = "<color=#e8d9bb>窸窸窣窣。</color>",
  ui_story_10_1_1_17_dialog_content = "那邊的「貓」，妳的耳朵已經把地板都擦乾淨了喔。",
  ui_story_10_1_1_18_dialog_content = "欸？菲莉詩才不是在擦地板。",
  ui_story_10_1_1_19_dialog_content = "菲莉詩只是想試試透過地面確認周圍其他人的活動情況~",
  ui_story_10_1_1_20_dialog_content = "我知道你在擔心什麼啦。",
  ui_story_10_1_1_21_dialog_content = "雖然這個房間是他們特地安排給我的，但我已經仔細確認過了……",
  ui_story_10_1_1_22_dialog_content = "沒有監視。",
  ui_story_10_1_1_S2_dialog_content = "他們頂多是希望我留在白夜城久一點而已。",
  ui_story_10_1_1_23_dialog_content = "妳帶了什麼情報來，說吧。",
  ui_story_10_1_1_24_dialog_content = "不愧是長官，一眼就看穿了菲莉詩。",
  ui_story_10_1_1_25_dialog_content = "菲莉詩得到<color=#FFB400>「吞羅」</color>的消息後，第一時間就趕過來了。",
  ui_story_10_1_1_26_dialog_content = "有查到關於她的情報嗎？",
  ui_story_10_1_1_27_dialog_content = "很難喵。",
  ui_story_10_1_1_28_dialog_content = "畢竟……就算在內部報告裡，她也是一個已經<color=#FFB400>「死了」</color>九年的人。",
  ui_story_10_1_1_29_dialog_content = "九年前，大火幾乎燒光了整座地下城……",
  ui_story_10_1_1_30_dialog_content = "所有人都認為她已經死在大火中了。",
  ui_story_10_1_1_31_dialog_content = "但是後來，調查隊在廢墟中發現了暗鬼和光靈的屍體。",
  ui_story_10_1_1_32_dialog_content = "菲莉詩聽到吞羅往PlayerName的身體裡塞了<color=#FFB400>「種子」</color>的時候……",
  ui_story_10_1_1_33_dialog_content = "瞬間就把這些事聯想到一起了喵。",
  ui_story_10_1_1_34_dialog_content = "吞羅當時在研究的東西會不會就跟這個東西有關？",
  ui_story_10_1_1_35_dialog_content = "很有可能，畢竟她現在……<color=#FFB400>已經變成暗鬼了</color>。",
  ui_story_10_1_1_36_dialog_content = "大元帥知道吞羅還活著的時候有什麼反應？",
  ui_story_10_1_1_37_dialog_content = "喵……關於這件事……",
  ui_story_10_1_1_38_dialog_content = "怎麼了？為什麼吞吞吐吐的？",
  ui_story_10_1_1_39_dialog_content = "長官妳應該知道大元帥和吞羅的關係，所以……",
  ui_story_10_1_1_40_dialog_content = "我知道妳在顧慮什麼，因為<color=#FFB400>吞羅是大元帥的妹妹</color>。",
  ui_story_10_1_1_41_dialog_content = "不愧是我的長官喵，僅憑一點點訊息就能察覺到菲莉詩的擔憂。",
  ui_story_10_1_1_42_dialog_content = "發生了什麼事，說吧。",
  ui_story_10_1_1_43_dialog_content = "大元帥帶著軍團長們出去了喵，雖然名義上是軍團長會議……",
  ui_story_10_1_1_44_dialog_content = "但菲莉詩認為這次不太一樣。",
  ui_story_10_1_1_45_dialog_content = "四位軍團長是大元帥最信賴的人，也是啟光最精銳的戰士。",
  ui_story_10_1_1_46_dialog_content = "長官你認為大元帥有可能是帶人去找吞羅了嗎？",
  ui_story_10_1_1_47_dialog_content = "菲莉詩，妳對暗鬼的情報非常敏感。",
  ui_story_10_1_1_48_dialog_content = "但還不太瞭解如何分析對於同伴的情報。",
  ui_story_10_1_1_49_dialog_content = "喵……",
  ui_story_10_1_1_50_dialog_content = "還是請長官直說吧，菲莉詩思考不動了喵……",
  ui_story_10_1_1_51_dialog_content = "妳認為我們的大元帥，是會因為私人情感而隨意行動的人嗎？",
  ui_story_10_1_1_52_dialog_content = "欸——？菲莉詩沒有懷疑大元帥！真的！",
  ui_story_10_1_1_53_dialog_content = "我知道啦……妳不要著急，先聽我說。",
  ui_story_10_1_1_54_dialog_content = "吞羅的出現對於我們來說是一個訊號。",
  ui_story_10_1_1_55_dialog_content = "掠食者瞄準獵物準備出擊時，也是最疏於防禦的時刻。",
  ui_story_10_1_1_56_dialog_content = "瞭解喵！長官妳的意思就是讓菲莉詩不要去探究大元帥的計畫。",
  ui_story_10_1_1_57_dialog_content = "大元帥肯定自有打算喵。",
  ui_story_10_1_1_58_dialog_content = "唉，希望妳是真的瞭解了。總之大元帥那邊的事，妳別瞎猜喔。",
  ui_story_10_1_1_59_dialog_content = "好的喵。",
  ui_story_10_1_1_60_dialog_content = "那菲莉詩還要不要繼續調查「種子」呢？",
  ui_story_10_1_1_61_dialog_content = "當然要調查啦。",
  ui_story_10_1_1_62_dialog_content = "那菲莉詩是不是就可以去找薇絲他們了喵？",
  ui_story_10_1_1_63_dialog_content = "嗯？妳怎麼得出這個結論的？",
  ui_story_10_1_1_64_dialog_content = "很簡單喵，「種子」的情報是薇絲和PlayerName提供的！",
  ui_story_10_1_1_65_dialog_content = "我在來的路上聽說前段時間吞噬者號被擊落了喵！",
  ui_story_10_1_1_66_dialog_content = "然後前幾天有一座巨像離開了白夜城！",
  ui_story_10_1_1_67_dialog_content = "薇絲他們一定是<color=#FFB400>去追吞噬者號</color>了喵！",
  ui_story_10_1_1_68_dialog_content = "既然「種子」跟吞噬者號有關，那菲莉詩直接去調查吞噬者號不就好了？",
  ui_story_10_1_1_69_dialog_content = "妳呀，倒是真的聰明……",
  ui_story_10_1_1_70_dialog_content = "妳猜得沒錯喔，PlayerName和薇絲已經前往吞噬者號的所在地了。",
  ui_story_10_1_1_71_dialog_content = "那菲莉詩是不是也可以去？",
  ui_story_10_1_1_72_dialog_content = "我先確認一下，妳不是打算去玩吧？",
  ui_story_10_1_1_73_dialog_content = "不是的，菲莉詩總有種不好的預感喵……",
  ui_story_10_1_1_74_dialog_content = "畢竟舒默跟吞羅有關，不管是出於調查考慮，還是安全考慮。",
  ui_story_10_1_1_75_dialog_content = "菲莉詩跟過去都有好處。",
  ui_story_10_1_1_76_dialog_content = "而且光是想想那些有關吞羅的情報，菲莉詩就忍不住炸毛了喵！",
  ui_story_10_1_1_77_dialog_content = "要是吞羅趁機抓了PlayerName和薇絲，拿他們去做實驗可怎麼辦？",
  ui_story_10_1_1_78_dialog_content = "原來是這樣，我明白妳的想法了。",
  ui_story_10_1_1_79_dialog_content = "但妳不用這麼擔心薇絲她們喔。",
  ui_story_10_1_1_80_dialog_content = "其實在他們出發之前，我已經與他們討論過遇到吞羅的可能性了。",
  ui_story_10_1_1_81_dialog_content = "最重要的是與他們同路的，還有白夜城的衛隊長卡蓮。",
  ui_story_10_1_1_82_dialog_content = "實際上就等於是……有關舒默的事情，白夜城已經接手了喔。",
  ui_story_10_1_1_83_dialog_content = "欸？原來是這樣……",
  ui_story_10_1_1_84_dialog_content = "那菲莉詩就不方便跟著去了……",
  ui_story_10_1_1_85_dialog_content = "嗯，在情況明朗之前，我們先等待薇絲的消息吧。",
  ui_story_10_2_1_1_dialog_content = "那個……",
  ui_story_10_2_1_2_dialog_content = "接下來我們該怎麼辦？",
  ui_story_10_2_1_3_dialog_content = "還能怎麼辦？當然是殺進去啊！難道要看著她跑掉嗎？",
  ui_story_10_2_1_4_dialog_content = "冷靜一點。",
  ui_story_10_2_1_5_dialog_content = "不管怎麼看，那都是在故意引誘我們進去。",
  ui_story_10_2_1_6_dialog_content = "我當然知道！",
  ui_story_10_2_1_7_dialog_content = "追，可能會掉進吞羅佈下的陷阱。",
  ui_story_10_2_1_8_dialog_content = "但不追，就等於是放過吞羅！",
  ui_story_10_2_1_9_dialog_content = "以及你們在追的那個<color=#FFB400>舒默</color>。",
  ui_story_10_2_1_10_dialog_content = "我只知道如果舒默還活著，一定就在吞噬者號裡！",
  ui_story_10_2_1_11_dialog_content = "她的氣息很微弱，恐怕是重傷。",
  ui_story_10_2_1_12_dialog_content = "你先不要激動，或許我們可以據守此處……",
  ui_story_10_2_1_13_dialog_content = "妳不會是想說，要請求白夜城或啟光的支援吧？",
  ui_story_10_2_1_14_dialog_content = "別想了！等他們派兵出來支援，那得等到天塌下來。",
  ui_story_10_2_1_15_dialog_content = "不要用你的臆想來判斷情況。",
  ui_story_10_2_1_16_dialog_content = "哈！派妳單獨出來，這態度還不夠明顯嗎？",
  ui_story_10_2_1_17_dialog_content = "這裡死了這麼多白夜城士兵，他們早就知道這裡什麼情況了。",
  ui_story_10_2_1_18_dialog_content = "如果有意支援，根本不用等妳去求。",
  ui_story_10_2_1_19_dialog_content = "那個，吵架也不是辦法……",
  ui_story_10_2_1_20_dialog_content = "要不吼兩聲，我們的人聽到了說不定就會過來……",
  ui_story_10_2_1_21_dialog_content = "我倆可是意外掉下來的，等我們的人來？那得等到所有人都掉進坑裡！",
  ui_story_10_2_1_22_dialog_content = "也是……而且大家都找不到路……",
  ui_story_10_2_1_23_dialog_content = "吞羅打算佈下陷阱引誘我們進入，然後一舉剿滅我們嗎？",
  ui_story_10_2_1_24_dialog_content = "我總覺得不是這樣……",
  ui_story_10_2_1_25_dialog_content = "剛才戰鬥的時候，我們連摸都摸不到她。",
  ui_story_10_2_1_26_dialog_content = "明明她有那樣的強的戰鬥力，卻好像……",
  ui_story_10_2_1_27_dialog_content = "<color=#FFB400>沒有攻擊我們的打算？</color>",
  ui_story_10_2_1_28_dialog_content = "難道她是真的希望我們去見見舒默？",
  ui_story_10_2_1_29_dialog_content = "要是能有更多情報就好了……",
  ui_story_10_2_1_30_dialog_content = "PlayerName，你有辦法透過感應瞭解吞羅的想法嗎？",
  ui_story_10_2_1_31_dialog_content = "這個……我其實有試過……",
  ui_story_10_2_1_32_dialog_content = "但是抱歉，我<color=#FFB400>無法直接感應吞羅</color>。",
  ui_story_10_2_1_33_dialog_content = "為什麼？",
  ui_story_10_2_1_34_dialog_content = "我也不知道該怎麼說明，總之……",
  ui_story_10_2_1_35_dialog_content = "感應對方的想法這件事本身並不容易。",
  ui_story_10_2_1_36_dialog_content = "距離、感應能力的強度，以及對象是否抗拒等因素，都會影響感應效果。",
  ui_story_10_2_1_37_dialog_content = "實際上，我現在只有感應舒默的時候特別順利……",
  ui_story_10_2_1_38_dialog_content = "而且好像……愈來愈順利了。",
  ui_story_10_2_1_39_dialog_content = "我現在唯一能確認到的是舒默現在處於重傷虛弱的狀態。",
  ui_story_10_2_1_40_dialog_content = "薇絲、卡蓮，我……",
  ui_story_10_2_1_41_dialog_content = "走吧！以前那麼多危險的狀況我們都敢闖進去，今天也一樣。",
  ui_story_10_2_1_42_dialog_content = "走吧，進去一探究竟，我來開路。",
  ui_story_10_2_1_43_dialog_content = "同意進去了？走得比我還快？",
  ui_story_10_2_1_44_dialog_content = "你這幾句分析聽起來好像有點道理，實際上啥都沒分析出來。",
  ui_story_10_2_1_45_dialog_content = "我知道薇絲跟你特別好，怎麼連那個卡蓮也聽你的？",
  ui_story_10_2_1_46_dialog_content = "妳們並不是「聽我的」……我很感謝薇絲和卡蓮，一路上她們一直在幫助我。",
  ui_story_10_2_1_47_dialog_content = "希望等這件事結束以後，有機會報答她們。",
  ui_story_10_2_1_48_dialog_content = "走吧……",
  ui_story_10_2_1_49_dialog_content = "這就是吞噬者號？",
  ui_story_10_2_1_50_dialog_content = "哈，這吞噬者號內部看起來也不怎麼嚇人嘛，破破爛爛的，一點氣勢都沒有。",
  ui_story_10_2_1_51_dialog_content = "因為白夜城擊落了它。",
  ui_story_10_2_1_52_dialog_content = "我知道，妳沒必要特地再向我強調。",
  ui_story_10_2_1_53_dialog_content = "我只是在回答你的疑問而已。你不是嫌它破爛嗎？",
  ui_story_10_2_1_54_dialog_content = "咳、咳……那個……吞噬者號能量耗盡可能也是原因之一。",
  ui_story_10_2_1_55_dialog_content = "咳咳咳……",
  ui_story_10_2_1_56_dialog_content = "你是怕我們吵起來嗎？有必要咳得這麼凶嗎？",
  ui_story_10_2_1_57_dialog_content = "不……我是因為暗能……",
  ui_story_10_2_1_58_dialog_content = "明明已經是殘骸了，這裡面居然還殘留著這麼濃厚的暗能……",
  ui_story_10_2_1_59_dialog_content = "咕……",
  ui_story_10_2_1_60_dialog_content = "是暗鬼的聲音？大家小心！",
  ui_story_10_2_1_61_dialog_content = "吼——！",
  ui_story_10_2_2_1_dialog_content = "嘎——！",
  ui_story_10_2_2_2_dialog_content = "糟糕！PlayerName小心！",
  ui_story_10_2_2_3_dialog_content = "給我倒下！",
  ui_story_10_2_2_4_dialog_content = "你沒事吧？",
  ui_story_10_2_2_5_dialog_content = "欸、欸、啊……謝謝……",
  ui_story_10_2_2_6_dialog_content = "沒事，就是差點被燒到褲子……",
  ui_story_10_2_2_7_dialog_content = "抱歉，不小心漏了一隻……",
  ui_story_10_2_2_8_dialog_content = "還有一隻！",
  ui_story_10_2_2_9_dialog_content = "吼——！",
  ui_story_10_2_2_10_dialog_content = "欸？怎麼跑了？別跑呀……",
  ui_story_10_2_2_11_dialog_content = "我看你往哪跑！",
  ui_story_10_2_2_12_dialog_content = "咕……",
  ui_story_10_2_2_13_dialog_content = "奇怪了，這些暗鬼就跟瞎了似的，看不見我們？",
  ui_story_10_2_2_14_dialog_content = "確實有點奇怪。照理說，暗鬼一見到我們就會立即撲上來才對。",
  ui_story_10_2_2_15_dialog_content = "但這些暗鬼，好像比起襲擊我們……",
  ui_story_10_2_2_16_dialog_content = "更想要逃跑。",
  ui_story_10_2_2_17_dialog_content = "那正好，別管這些雜魚了，直接去找吞羅算帳吧。",
  ui_story_10_2_2_18_dialog_content = "這種異常或許跟吞羅有關，總之要小心提防。",
  ui_story_10_2_2_19_dialog_content = "嗯，有可能。",
  ui_story_10_2_2_20_dialog_content = "我們還是需要一邊清理暗鬼一邊前進。放著不管的話……",
  ui_story_10_2_2_21_dialog_content = "我擔心會陷入被暗鬼前後夾擊的狀態。",
  ui_story_10_2_2_22_dialog_content = "PlayerName，我知道這裡的暗能會讓你不太舒服。",
  ui_story_10_2_2_23_dialog_content = "但希望你能用感應能力探查一下情況。",
  ui_story_10_2_2_24_dialog_content = "我試試看。",
  ui_story_10_2_2_25_dialog_content = "……",
  ui_story_10_2_2_26_dialog_content = "<color=#e8d9bb>嗚——嗚——</color>",
  ui_story_10_2_2_27_dialog_content = "嘶，哪裡吹來的陰風……",
  ui_story_10_2_2_28_dialog_content = "噓！小聲點，沒看到PlayerName在集中精神嗎？",
  ui_story_10_2_2_29_dialog_content = "可是老大……你聲音比我大欸……",
  ui_story_10_2_2_30_dialog_content = "……噓。",
  ui_story_10_2_2_31_dialog_content = "（暗能……）",
  ui_story_10_2_2_32_dialog_content = "（暗能……全部都在向一個方向匯集。）",
  ui_story_10_2_2_33_dialog_content = "（好噁心……還時淡時濃的……簡直受不了。）",
  ui_story_10_2_2_34_dialog_content = "（暗鬼……暗鬼……）",
  ui_story_10_2_2_35_dialog_content = "（全部都是暗鬼。）",
  ui_story_10_2_2_36_dialog_content = "（好噁心……有一股腥氣……）",
  ui_story_10_2_2_37_dialog_content = "（還有……）",
  ui_story_10_2_2_38_dialog_content = "<color=#e8d9bb>嘎吱……</color>",
  ui_story_10_2_2_39_dialog_content = "（有什麼聲音？）",
  ui_story_10_2_2_40_dialog_content = "<color=#e8d9bb>嘎吱</color>",
  ui_story_10_2_2_41_dialog_content = "（是在磨牙嗎？）",
  ui_story_10_2_2_42_dialog_content = "<color=#e8d9bb>嘎吱</color>",
  ui_story_10_2_2_43_dialog_content = "（不是，是在嚼著什麼……）",
  ui_story_10_2_2_44_dialog_content = "<color=#e8d9bb>嘎吱</color>",
  ui_story_10_2_2_45_dialog_content = "（是什麼東西……黏糊糊的……很臭……）",
  ui_story_10_2_2_46_dialog_content = "（好腥……好噁心……）",
  ui_story_10_2_2_47_dialog_content = "（還伴隨著渾身疼痛……）",
  ui_story_10_2_2_48_dialog_content = "（是什麼……在牙齒間，還有舌頭底下……）",
  ui_story_10_2_2_49_dialog_content = "（還塞在喉嚨裡……是種爛泥一樣的東西？！）",
  ui_story_10_2_2_50_dialog_content = "嘖……",
  ui_story_10_2_2_51_dialog_content = "暗鬼這玩意，真難吃。",
  ui_story_10_3_1_1_dialog_content = "嘔——！",
  ui_story_10_3_1_2_dialog_content = "PlayerName！快、快停止感應！",
  ui_story_10_3_1_3_dialog_content = "嘔……咳、咳……",
  ui_story_10_3_1_4_dialog_content = "已……已經停了……嘔！",
  ui_story_10_3_1_5_dialog_content = "你怎麼回事？怎麼……用個感應能力用成這個鬼樣子？",
  ui_story_10_3_1_6_dialog_content = "咳、咳，抱歉……因為有種腥臭的……嘔！",
  ui_story_10_3_1_7_dialog_content = "行了，省省吧。",
  ui_story_10_3_1_8_dialog_content = "唔……你還是先吐完了再說話吧，不然等會要嗆到了。",
  ui_story_10_3_1_9_dialog_content = "薇絲，空裔在使用感應能力的時候，反應會這麼大嗎？",
  ui_story_10_3_1_10_dialog_content = "不，以前並不會這樣，除非他現在可以感受到……",
  ui_story_10_3_1_11_dialog_content = "什麼特別不妙的東西。",
  ui_story_10_3_1_12_dialog_content = "咕……",
  ui_story_10_3_1_13_dialog_content = "我命令你，過來。",
  ui_story_10_3_1_14_dialog_content = "咕……",
  ui_story_10_3_1_15_dialog_content = "我命令你進去。自己爬進去。",
  ui_story_10_3_1_16_dialog_content = "咕……",
  ui_story_10_3_1_17_dialog_content = "很好。",
  ui_story_10_3_1_18_dialog_content = "嘎！",
  ui_story_10_3_1_19_dialog_content = "閉嘴……你壓到我了……",
  ui_story_10_3_1_20_dialog_content = "咕……嘎！",
  ui_story_10_3_1_21_dialog_content = "……",
  ui_story_10_3_1_22_dialog_content = "總算聽話了。",
  ui_story_10_3_1_23_dialog_content = "吞羅……你能不能讓它們進來的時候小心點？",
  ui_story_10_3_1_24_dialog_content = "我渾身疼得要死……還要被這堆臭得跟爛泥一樣的東西砸？",
  ui_story_10_3_1_25_dialog_content = "妳說……什麼？我聽不清楚。",
  ui_story_10_3_1_26_dialog_content = "少裝了。",
  ui_story_10_3_1_27_dialog_content = "你說話我都聽得見……我那麼大聲妳怎麼可能聽不見？",
  ui_story_10_3_1_28_dialog_content = "你聲音大不大和我聽不聽得見有關係嗎？",
  ui_story_10_3_1_29_dialog_content = "如果閒聊可以讓妳多吃一點，我不介意陪妳聊兩句。",
  ui_story_10_3_1_30_dialog_content = "這麼噁心的東西誰吃得下去……",
  ui_story_10_3_1_31_dialog_content = "憤怒可以激化妳的成長，妳要學會利用它。",
  ui_story_10_3_1_32_dialog_content = "別真把暗鬼當成食物，咬兩口吸收暗能就行。",
  ui_story_10_3_1_33_dialog_content = "這已經是最簡單的方法了，妳可別到現在才說沒學會該怎麼吃。",
  ui_story_10_3_1_34_dialog_content = "不要小看我……",
  ui_story_10_3_1_35_dialog_content = "它們背上的「種子」太硬了……咬不動。",
  ui_story_10_3_1_36_dialog_content = "只是外殼堅硬而已，嚼碎它。妳嘴裡那口暗鬼牙比妳想像得要銳利。",
  ui_story_10_3_1_37_dialog_content = "我知道……但我就是想抱怨兩句。",
  ui_story_10_3_1_38_dialog_content = "……",
  ui_story_10_3_1_39_dialog_content = "看來妳在傷勢恢復以後，心情也變好了許多。",
  ui_story_10_3_1_40_dialog_content = "我想我得「誇獎」妳兩句了。",
  ui_story_10_3_1_41_dialog_content = "突然說什麼鬼話？",
  ui_story_10_3_1_42_dialog_content = "妳的眼光不錯，那個PlayerName有點用處。",
  ui_story_10_3_1_43_dialog_content = "雖然邀請失敗了，但留著他能激化妳不斷成長。",
  ui_story_10_3_1_44_dialog_content = "能被他和白夜城搞成重傷，妳一定很高興吧。",
  ui_story_10_3_1_45_dialog_content = "妳再敢諷刺我，我就出來拔了妳的牙……",
  ui_story_10_3_1_46_dialog_content = "不要聽到一點小小的諷刺就受不了。提升一下精神耐力好嗎。",
  ui_story_10_3_1_47_dialog_content = "妳到底想說什麼？",
  ui_story_10_3_1_48_dialog_content = "我是想說……妳的老朋友PlayerName已經進入吞噬者號了。",
  ui_story_10_3_1_49_dialog_content = "那個空裔，一定很想殺了妳完成復仇吧。",
  ui_story_10_3_1_50_dialog_content = "……",
  ui_story_10_3_1_51_dialog_content = "我只是想告訴妳，我會為妳爭取時間。",
  ui_story_10_3_1_52_dialog_content = "在妳吸收完能量，完成蛻變之前，我會想辦法拖住他們。",
  ui_story_10_3_1_53_dialog_content = "但我們時間有限。",
  ui_story_10_3_1_54_dialog_content = "<color=#e8d9bb>嘎吱</color>",
  ui_story_10_3_1_55_dialog_content = "希望妳能成功<color=#FFB400>「補完」</color>妳自己。",
  ui_story_10_3_1_56_dialog_content = "然後請不要像妳的吞噬者號一樣……",
  ui_story_10_3_1_57_dialog_content = "好不容易抵達白夜城，結果剛過去就被打了一個大窟窿。",
  ui_story_10_3_1_58_dialog_content = "閉嘴……",
  ui_story_10_3_1_59_dialog_content = "不用妳來強調。",
  ui_story_10_3_1_60_dialog_content = "大意輕敵是妳的毛病……",
  ui_story_10_3_1_61_dialog_content = "……",
  ui_story_10_3_1_62_dialog_content = "我唯一疏忽的地方……是高估了PlayerName的腦子。",
  ui_story_10_3_1_63_dialog_content = "把握機會，獲得力量，成為強者……",
  ui_story_10_3_1_64_dialog_content = "這些事情在他的腦子裡，居然都不如叫罵發洩重要?",
  ui_story_10_3_1_65_dialog_content = "真可笑……認識幾個光靈罷了，就以為自己有實力……",
  ui_story_10_3_1_66_dialog_content = "仗著我的寬宏大量，一次次辜負我……",
  ui_story_10_3_1_67_dialog_content = "跟那幾個臭空裔一樣不識好歹。",
  ui_story_10_3_1_68_dialog_content = "都是蠢貨。",
  ui_story_10_3_1_69_dialog_content = "既然如此，那就給我去死……",
  ui_story_10_3_1_70_dialog_content = "我要讓他付出代價，讓他在後悔與恐懼中死去。",
  ui_story_10_3_1_71_dialog_content = "你好點沒？說說你感應到了什麼吧。",
  ui_story_10_3_1_72_dialog_content = "舒默在吃暗鬼……",
  ui_story_10_3_1_73_dialog_content = "嗄？我還以為你感應到什麼不得了的東西了，結果就是吃暗鬼啊。",
  ui_story_10_3_1_74_dialog_content = "不用擔心，她這一定是傷重剛醒，幾天沒吃飯，餓著了吧。",
  ui_story_10_3_1_75_dialog_content = "暗鬼能吃？不是死了就碎掉了嗎？",
  ui_story_10_3_1_76_dialog_content = "能趁著新鮮咬上兩口，不過我聽說那玩意比吃野獸的嘔吐物還糟糕。",
  ui_story_10_3_1_77_dialog_content = "會吃暗鬼的傢伙，肯定是味覺和腦袋一起壞掉了。",
  ui_story_10_3_1_78_dialog_content = "可是根據以往的情報來看，暗鬼既不需要進食，也沒有同類相食的習性。",
  ui_story_10_3_1_79_dialog_content = "我覺得她在……吸收能量……有很濃的暗能。",
  ui_story_10_3_1_80_dialog_content = "她在想辦法治療自己……我們快走吧……嘔……",
  ui_story_10_3_1_81_dialog_content = "嗚……我光聽你們說就已經很想吐了。",
  ui_story_10_3_1_82_dialog_content = "我……沒事……已經沒東西可以吐了……嘔……",
  ui_story_10_3_1_83_dialog_content = "唉，這光是乾嘔也挺恐怖的，你看你整個人都抽搐起來了。",
  ui_story_10_3_1_84_dialog_content = "……走吧。",
  ui_story_10_3_1_85_dialog_content = "等一下，你連站都站不穩了！先坐下來休息五分鐘！",
  ui_story_10_3_1_86_dialog_content = "就五分鐘！",
  ui_story_10_3_1_87_dialog_content = "我沒關係……我還是能支援大家……",
  ui_story_10_3_1_88_dialog_content = "好了，叫你休息你就休息吧。",
  ui_story_10_3_1_89_dialog_content = "既然你們追的那個舒默選擇在這種時候治療自己，那一定是跑不了。",
  ui_story_10_3_1_90_dialog_content = "來，喝點熱水。",
  ui_story_10_3_1_91_dialog_content = "要不要再吃點東西補充一下能量？我們這有紅油特產！",
  ui_story_10_3_1_92_dialog_content = "叭噗，過來把妳身上的蜥蜴乾發給大家！",
  ui_story_10_3_1_93_dialog_content = "對對對！既然那個舒默都在補充能量，那我們也得做好準備，吃點吧。",
  ui_story_10_3_1_94_dialog_content = "不要放鬆過頭了。",
  ui_story_10_3_1_95_dialog_content = "給我一包就行了，我去探查前面。",
  ui_story_10_3_1_96_dialog_content = "啊，好。這個很方便，打開就能吃，是辛口的甜味，好吃又能補充體力。",
  ui_story_10_3_1_97_dialog_content = "PlayerName你看，卡蓮都願意吃了，你也吃一點吧。",
  ui_story_10_3_1_98_dialog_content = "剛吐過，肚子裡肯定空空的，餓著可沒辦法戰鬥呀。",
  ui_story_10_3_1_99_dialog_content = "抱歉……剛吐過最好不要吃東西……不然可能會再吐。",
  ui_story_10_3_1_100_dialog_content = "欸？原來是這樣……那，至少喝點水吧？",
  ui_story_10_3_1_101_dialog_content = "還有一瓶，在這裡。",
  ui_story_10_3_1_102_dialog_content = "前方疑似有一群暗鬼活動，恐怕很快就會到我們這來。",
  ui_story_10_3_1_103_dialog_content = "PlayerName，你不用勉強指揮。",
  ui_story_10_3_1_104_dialog_content = "趁我們戰鬥期間，喘口氣吧。",
  ui_story_10_3_1_105_dialog_content = "對，不會讓一隻暗鬼靠近你的，放心在這坐著！",
  ui_story_10_3_1_106_dialog_content = "暗鬼出現，準備迎擊！",
  ui_story_10_3_2_1_dialog_content = "PlayerName！剛才你又幫忙指揮了！",
  ui_story_10_3_2_2_dialog_content = "不是要你趁機休息一下嗎？",
  ui_story_10_3_2_3_dialog_content = "我沒事……我已經好多了。",
  ui_story_10_3_2_4_dialog_content = "況且與妳們建立感應，可比感應暗鬼好多了。",
  ui_story_10_3_2_5_dialog_content = "這裡的暗鬼……好像又恢復戰意了？",
  ui_story_10_3_2_6_dialog_content = "嗯，看來一邊清理一邊前進是最好的選擇。",
  ui_story_10_3_2_7_dialog_content = "走吧……我已經好多了。",
  ui_story_10_3_2_8_dialog_content = "抱歉，都是我要你使用感應能力去探查，才害你……",
  ui_story_10_3_2_9_dialog_content = "不，這不是妳的錯。",
  ui_story_10_3_2_10_dialog_content = "我剛才是因為突然感應到敵方有吃暗鬼的癖好，才覺得不適而已。",
  ui_story_10_3_2_11_dialog_content = "下一次感應，就不會被影響了。",
  ui_story_10_3_2_12_dialog_content = "好小子，你這話說得還算有點氣勢。",
  ui_story_10_3_2_13_dialog_content = "剛才你有感應到吞羅嗎？",
  ui_story_10_3_2_14_dialog_content = "我剛才感應的時候，有模糊的印象……",
  ui_story_10_3_2_15_dialog_content = "吞羅和舒默好像確實身在同一個地方。",
  ui_story_10_3_2_16_dialog_content = "那就走吧。我們的目的地一致。",
  ui_story_10_3_2_17_dialog_content = "<color=#e8d9bb>嗚——嗚——</color>",
  ui_story_10_3_2_18_dialog_content = "這巨像，好像愈往裡面走愈破爛了……",
  ui_story_10_3_2_19_dialog_content = "簡直有種隨時都要坍塌的感覺，巨像不應該是這樣的啊。",
  ui_story_10_3_2_20_dialog_content = "它被達摩克里斯命中。",
  ui_story_10_3_2_21_dialog_content = "再加上被舒默榨乾能量。",
  ui_story_10_3_2_22_dialog_content = "這座巨像，已經<color=#FFB400>「死了」</color>……",
  ui_story_10_3_2_23_dialog_content = "也就是說，舒默身為這座巨像的導航員……",
  ui_story_10_3_2_24_dialog_content = "親手「弄死」了自己的巨像？",
  ui_story_10_3_2_25_dialog_content = "暗鬼都不會同類相食，就她會。這麼噁心的事她都幹得出來。",
  ui_story_10_3_2_26_dialog_content = "妳說她會炸了巨像我都信，吸收點能量算什麼？",
  ui_story_10_3_2_27_dialog_content = "她有多可惡，PlayerName肯定比我們清楚。",
  ui_story_10_3_2_28_dialog_content = "走吧，決不能讓她完成治療……",
  ui_story_10_7_1_1_dialog_content = "想要進一步提升暗能，吸收是一個不錯的手段。",
  ui_story_10_7_1_2_dialog_content = "但並不是所有暗鬼都能掌握吸收暗能的技巧……",
  ui_story_10_7_1_3_dialog_content = "……",
  ui_story_10_7_1_4_dialog_content = "喔，這麼快就睡著了，看來這次實驗有望成功。",
  ui_story_10_7_1_5_dialog_content = "上一個想跟我討論力量的傢伙是誰呢……喔，想起來了。",
  ui_story_10_7_1_6_dialog_content = "是來自白夜城的人，那兩個長著蟲尾巴的……叫……",
  ui_story_10_7_1_7_dialog_content = "<color=#FFB400>「無聊」</color>？",
  ui_story_10_7_1_8_dialog_content = "<color=#e8d9bb>嗚——嗚——</color>",
  ui_story_10_7_1_9_dialog_content = "這……又是陰風？",
  ui_story_10_7_1_10_dialog_content = "不是……這是……",
  ui_story_10_7_1_11_dialog_content = "嗚……嗚……",
  ui_story_10_7_1_12_dialog_content = "是哭聲？",
  ui_story_10_7_1_13_dialog_content = "暗鬼也會哭嗎？",
  ui_story_10_7_1_14_dialog_content = "後退一點，她們過來了。",
  ui_story_10_7_1_15_dialog_content = "這、這暗鬼……看起來好恐怖。",
  ui_story_10_7_1_16_dialog_content = "等一下……我總覺得好像在哪裡見過這隻暗鬼。",
  ui_story_10_7_1_17_dialog_content = "不會……不會。又是光靈變成的暗鬼吧？",
  ui_story_10_7_1_18_dialog_content = "這個外形，這些像樹根一樣的肢體……這個聲音……我現在唯一能聯想到的是……",
  ui_story_10_7_1_19_dialog_content = "那對姐妹，<color=#FFB400>嘶魘兒</color>和<color=#FFB400>夏爾</color>，她們最終變成的那個怪物。",
  ui_story_10_7_1_20_dialog_content = "姐妹？兩個人……可是這是一隻暗鬼啊？",
  ui_story_10_7_1_21_dialog_content = "我們親眼看到她們被迫融合在一起。",
  ui_story_10_7_1_22_dialog_content = "是的，她們曾念著「那位大人賜予了我們力量」，結果……就是變成這樣。",
  ui_story_10_7_1_23_dialog_content = "嗚……嗚……",
  ui_story_10_7_1_24_dialog_content = "那個，她們雖然走得很慢，但好像是衝著我們來的……要主動迎擊嗎？",
  ui_story_10_7_1_25_dialog_content = "嗚……嗚……殺……",
  ui_story_10_7_1_26_dialog_content = "「殺」？她們在說「殺」嗎？這是想殺我們嗎？",
  ui_story_10_7_1_27_dialog_content = "不是……這是她們在渴望解脫。",
  ui_story_10_7_1_28_dialog_content = "她們曾經這樣說過……<color=#FFB400>「殺了我們」</color>。",
  ui_story_10_7_1_29_dialog_content = "現在卻依舊受困於痛苦中……",
  ui_story_10_7_1_30_dialog_content = "把死者的屍體拖到此處，復活起來再次利用。",
  ui_story_10_7_1_31_dialog_content = "三番兩次使用這種下三濫的手段，簡直喪心病狂！",
  ui_story_10_7_1_32_dialog_content = "嗚——！",
  ui_story_10_7_1_33_dialog_content = "變成這種狀態，已經沒辦法保留意識和人性了。",
  ui_story_10_7_1_34_dialog_content = "打倒她們吧！",
  ui_story_10_7_1_35_dialog_content = "然後去將製造這一切悲劇的元凶，送入墓地！",
  ui_story_10_7_2_1_dialog_content = "……安靜下來了嗎？",
  ui_story_10_7_2_2_dialog_content = "是的，她們死了……她們再次死亡了。",
  ui_story_10_7_2_3_dialog_content = "薇絲，PlayerName，找一些易燃物來吧。",
  ui_story_10_7_2_4_dialog_content = "為她們舉行火葬。",
  ui_story_10_7_2_5_dialog_content = "希望她們能和<color=#FFB400>格茲德</color>一樣獲得安息……",
  ui_story_10_7_2_6_dialog_content = "嗯，我去周圍找找看。",
  ui_story_10_7_2_7_dialog_content = "格茲德又是誰？",
  ui_story_10_7_2_8_dialog_content = "一位來自白夜城的騎士，嘶魘兒的戀人。",
  ui_story_10_7_2_9_dialog_content = "他原本跟嘶魘兒一樣加入了暗鬼一方，但最後……",
  ui_story_10_7_2_10_dialog_content = "犧牲自己，保護了我們。",
  ui_story_10_7_2_11_dialog_content = "又是白夜城……雖然是這種時候，但我還是想問一句。",
  ui_story_10_7_2_12_dialog_content = "為什麼妳們白夜城的人會選擇加入暗鬼那一方？",
  ui_story_10_7_2_13_dialog_content = "明明既不用擔心被暗鬼襲擊的問題，生活也不艱苦。",
  ui_story_10_7_2_14_dialog_content = "這不是很有問題嗎？",
  ui_story_10_7_2_15_dialog_content = "醒山，在這裡大家都是為了同一目標行動的夥伴。",
  ui_story_10_7_2_16_dialog_content = "就別提這些了吧。",
  ui_story_10_7_2_17_dialog_content = "沒事。",
  ui_story_10_7_2_18_dialog_content = "我不過是隨口問兩句而已，畢竟難得有機會遇到白夜城的人。",
  ui_story_10_7_2_19_dialog_content = "對了，如果你不介意用我的火，我也可以幫忙火葬她們。",
  ui_story_10_7_2_20_dialog_content = "醒山，這些事情我會好好處理的，不用你費心。",
  ui_story_10_7_2_21_dialog_content = "也不用你插手。",
  ui_story_10_7_2_22_dialog_content = "我可沒想插手，妳知道自己該做什麼就好。",
  ui_story_10_7_2_23_dialog_content = "我去警戒周圍。",
  ui_story_10_7_2_24_dialog_content = "……",
  ui_story_10_7_2_25_dialog_content = "那個，我也去幫忙找了些可燃物來……",
  ui_story_10_7_2_26_dialog_content = "醒山老大他有時候比較衝動，而且心裡有什麼話就說什麼話……",
  ui_story_10_7_2_27_dialog_content = "但他對妳們沒有惡意的。",
  ui_story_10_7_2_28_dialog_content = "嗯，我知道。",
  ui_story_10_7_2_29_dialog_content = "點火吧。",
  ui_story_10_7_2_30_dialog_content = "白夜至上……",
  ui_story_10_7_2_31_dialog_content = "嘶魘兒、夏爾，追求自由卻走上歧途之人，請在安息之後，再飛向自由吧。",
  ui_story_10_7_2_32_dialog_content = "審判應當留給蠱惑她們的人。",
  ui_story_10_7_2_33_dialog_content = "接下來該埋葬的是罪魁禍首<color=#FFB400>舒默</color>。",
  ui_story_10_7_2_34_dialog_content = "我可以嘗試尋找該走哪個方向……",
  ui_story_10_7_2_35_dialog_content = "PlayerName？你又開始使用感應能力了嗎？",
  ui_story_10_7_2_36_dialog_content = "對……",
  ui_story_10_7_2_37_dialog_content = "快停下來！萬一你又被影響了……",
  ui_story_10_7_2_38_dialog_content = "嘶……",
  ui_story_10_7_2_39_dialog_content = "PlayerName？！",
  ui_story_10_7_2_40_dialog_content = "老師……",
  ui_story_10_7_2_41_dialog_content = "等一下……我看到了一些畫面……",
  ui_story_10_7_2_42_dialog_content = "我沒事，我能想辦法探查……不用擔心……",
  ui_story_10_7_2_43_dialog_content = "漢德羅老師……",
  ui_story_10_7_2_44_dialog_content = "妳到底做了什麼？為什麼？！",
  ui_story_10_7_2_45_dialog_content = "妳為什麼要害死妳的同學？告訴我！",
  ui_story_10_7_2_46_dialog_content = "老師，我什麼都沒做。",
  ui_story_10_7_2_47_dialog_content = "我只是證明了自己的勇氣而已……",
  ui_story_10_7_2_48_dialog_content = "開什麼玩笑？！",
  ui_story_10_7_2_49_dialog_content = "就為了證明自己的勇氣？就要害死妳的同學嗎？！",
  ui_story_10_7_2_50_dialog_content = "又來了，每次老師你都只聽人說一半的話，然後就隨意判斷……",
  ui_story_10_7_2_51_dialog_content = "妳？！",
  ui_story_10_7_2_52_dialog_content = "好，妳說，妳說。",
  ui_story_10_7_2_53_dialog_content = "是他們非要和我打賭的，我只是答應了賭約而已！",
  ui_story_10_7_2_54_dialog_content = "是那群蠢材認為自己已經有足夠的實力挑戰暗鬼了。",
  ui_story_10_7_2_55_dialog_content = "那就來打賭，看看誰敢去外面。",
  ui_story_10_7_2_56_dialog_content = "就因為這種理由？",
  ui_story_10_7_2_57_dialog_content = "老師，我們只是去外面看看而已，誰都沒想到會真的遇到暗鬼……",
  ui_story_10_7_2_58_dialog_content = "他們排擠我！看不起我！就因為我的感應能力用得不好！",
  ui_story_10_7_2_59_dialog_content = "老師你一直說不可輕視他人的潛力，他們聽了嗎？",
  ui_story_10_7_2_60_dialog_content = "他們沒有聽！",
  ui_story_10_7_2_61_dialog_content = "所以我最終證明了！活下來的是我！",
  ui_story_10_7_2_62_dialog_content = "我才是最強的！",
  ui_story_10_7_2_63_dialog_content = "唉……",
  ui_story_10_7_2_64_dialog_content = "妳能夠逃回來，那是運氣好啊！",
  ui_story_10_7_2_65_dialog_content = "舒默，我已經跟妳說過很多次了。",
  ui_story_10_7_2_66_dialog_content = "身為空裔，我們始終是愛好和平的種族。",
  ui_story_10_7_2_67_dialog_content = "我們沒有必要向什麼人證明任何東西。",
  ui_story_10_7_2_68_dialog_content = "力量的強弱不重要，重要的是彼此扶持，共同面對外界的危險。",
  ui_story_10_7_2_69_dialog_content = "面對？老師你說的「面對」是指躲在空谷裡不敢出去嗎？",
  ui_story_10_7_2_70_dialog_content = "不是這樣的。我警告過你們多少次了……",
  ui_story_10_7_2_71_dialog_content = "空谷外有很多暗鬼。",
  ui_story_10_7_2_72_dialog_content = "我們與光靈不同，沒有利用光能戰鬥的能力。",
  ui_story_10_7_2_73_dialog_content = "一旦面對稍微強大一點的暗鬼，幾乎等同於沒有反抗之力。",
  ui_story_10_7_2_74_dialog_content = "但我們有空谷和巨像。",
  ui_story_10_7_2_75_dialog_content = "空谷會保護我們，巨像只要升空就能免遭暗鬼攻擊。",
  ui_story_10_7_2_76_dialog_content = "最重要的是，我們有<color=#FFB400>感應能力</color>，這是空裔獨有的力量。",
  ui_story_10_7_2_77_dialog_content = "我們可以感受光的軌跡、可以知曉同伴的想法、可以察覺危險的敵人。",
  ui_story_10_7_2_78_dialog_content = "但妳們毫無經驗、能力不足，無法利用感應能力偵查，無法迴避危險。",
  ui_story_10_7_2_79_dialog_content = "一無所知地走出空谷，這不是送死嗎？",
  ui_story_10_7_2_80_dialog_content = "偵查、迴避……這裡所有的人都是這樣！",
  ui_story_10_7_2_81_dialog_content = "你們難道就沒想過，如果暗鬼來到這裡的話，我們應該怎麼辦嗎？！",
  ui_story_10_7_2_82_dialog_content = "你以為空谷就能永遠保護我們嗎？！",
  ui_story_10_7_2_83_dialog_content = "到時候我們該怎麼辦？坐巨像逃走嗎？逃去哪裡？",
  ui_story_10_7_2_84_dialog_content = "逃到「一出去就會被殺」的外面嗎？",
  ui_story_10_7_2_85_dialog_content = "誰跟妳說「一出去就會被殺」？！",
  ui_story_10_7_2_86_dialog_content = "我不是告訴過妳很多次了嗎？只要有巨像……",
  ui_story_10_7_2_87_dialog_content = "別說了……我都知道。",
  ui_story_10_7_2_88_dialog_content = "老師，我們空裔愛好和平……是因為我們沒有力量面對爭鬥。",
  ui_story_10_7_2_89_dialog_content = "唉……妳現在不明白，這不怪妳。",
  ui_story_10_7_2_90_dialog_content = "妳以後就會明白的……",
  ui_story_10_7_2_91_dialog_content = "我現在不懂……以後也不會明白……",
  ui_story_10_7_2_92_dialog_content = "你走吧，老師。",
  ui_story_10_7_2_93_dialog_content = "我是不會懺悔的。",
  ui_story_10_7_2_94_dialog_content = "看來妳還需要點時間冷靜。",
  ui_story_10_7_2_95_dialog_content = "長老已經派人去調查這件事了。",
  ui_story_10_7_2_96_dialog_content = "我相信妳不是故意害死同學……",
  ui_story_10_7_2_97_dialog_content = "但在長老們決定妳懲罰之前，我只能先把妳關在這裡。",
  ui_story_10_7_2_98_dialog_content = "另外，這本書是妳朋友送給妳的，他請我轉交給妳。",
  ui_story_10_7_2_99_dialog_content = "朋友？誰？我沒有「朋友」……？……",
  ui_story_10_7_2_100_dialog_content = "是<color=#FFB400>孟德爾頌</color>啊，他很擔心你，他以前的成績也不好。",
  ui_story_10_7_2_101_dialog_content = "我想他能理解你的處境，想要跟妳做朋友。",
  ui_story_10_7_2_102_dialog_content = "擔心我？",
  ui_story_10_7_2_103_dialog_content = "舒默……希望妳總有一天能夠意識到，大家都是愛妳的。",
  ui_story_10_7_2_104_dialog_content = "禁閉禁食期間，希望妳好好反省，不要辜負了大家對妳的期待。",
  ui_story_10_7_2_105_dialog_content = "……",
  ui_story_10_7_2_106_dialog_content = "意識到<color=#FFB400>「大家都愛我」</color>？",
  ui_story_10_7_2_107_dialog_content = "每次都拿這些藉口敷衍我，煩死了……",
  ui_story_10_7_2_108_dialog_content = "……",
  ui_story_10_7_2_109_dialog_content = "居然送書給我……",
  ui_story_10_7_2_110_dialog_content = "<color=#FFB400>《艾達與巨像》</color>？！",
  ui_story_10_7_2_111_dialog_content = "什麼爛書？！知道我感應不了巨像還想刺激我？",
  ui_story_10_7_2_112_dialog_content = "……",
  ui_story_10_7_2_113_dialog_content = "孟德爾頌……",
  ui_story_10_7_2_114_dialog_content = "喔，那個頭髮比我還紅，看起來比我還弱的傢伙。",
  ui_story_10_7_2_115_dialog_content = "肯定和我一樣感應不了巨像。",
  ui_story_10_7_2_116_dialog_content = "<color=#e8d9bb>叮鈴</color>",
  ui_story_10_7_2_117_dialog_content = "什麼玩意？",
  ui_story_10_7_2_118_dialog_content = "是<color=#FFB400>鑰匙</color>？！",
  ui_story_10_7_2_119_dialog_content = "呿，這種門……我現在隨隨便便就能弄壞……",
  ui_story_10_8_1_1_dialog_content = "進一步提升「種子」的暗能後……",
  ui_story_10_8_1_2_dialog_content = "暗能會讓它們備感舒適。",
  ui_story_10_8_1_3_dialog_content = "使其逐漸失去辨別能力。",
  ui_story_10_8_1_4_dialog_content = "獲得暗能的實驗體往往更容易顯露出強烈的自身慾望。",
  ui_story_10_8_1_5_dialog_content = "此時最容易影響他們自主行為的，是對事物的執著……",
  ui_story_10_8_1_6_dialog_content = "妳不要心急，感應能力是可以慢慢訓練的。",
  ui_story_10_8_1_7_dialog_content = "吞噬者號比較特別，短期內很難出現適合它的導航員。",
  ui_story_10_8_1_8_dialog_content = "只要妳現在努力學習，變得強大，妳是有機會的……",
  ui_story_10_8_1_9_dialog_content = "吞噬者號……在哪裡……",
  ui_story_10_8_1_10_dialog_content = "巨像……",
  ui_story_10_8_1_11_dialog_content = "巨像……",
  ui_story_10_8_1_12_dialog_content = "普通巨像……",
  ui_story_10_8_1_13_dialog_content = "不是這一座……",
  ui_story_10_8_1_14_dialog_content = "也不是這一座……",
  ui_story_10_8_1_15_dialog_content = "我要做什麼來著……",
  ui_story_10_8_1_16_dialog_content = "破壞它們的動力源，只留一座。",
  ui_story_10_8_1_17_dialog_content = "這是命令。",
  ui_story_10_8_1_18_dialog_content = "破壞動力源……",
  ui_story_10_8_1_19_dialog_content = "除了吞噬者號，破壞所有巨像的動力源……",
  ui_story_10_8_1_20_dialog_content = "找到你了……",
  ui_story_10_8_1_21_dialog_content = "只要破壞掉意識模組，你就會聽從我了吧?",
  ui_story_10_8_1_22_dialog_content = "<color=#e8d9bb>引擎自動檢查……無異常。正在啟動……</color>",
  ui_story_10_8_1_23_dialog_content = "黑色的、強大的、特別的……",
  ui_story_10_8_1_24_dialog_content = "<color=#e8d9bb>十六％……三十三％……</color>",
  ui_story_10_8_1_25_dialog_content = "<color=#FFB400>我的吞噬者號。</color>",
  ui_story_10_8_1_26_dialog_content = "<color=#e8d9bb>100%，啟動成功。</color>",
  ui_story_10_8_1_27_dialog_content = "果然成功了！",
  ui_story_10_8_1_28_dialog_content = "只要有吞噬者號……",
  ui_story_10_8_1_29_dialog_content = "舒默——",
  ui_story_10_8_1_30_dialog_content = "？！",
  ui_story_10_8_1_31_dialog_content = "你的聲音？！",
  ui_story_10_8_1_32_dialog_content = "聽到我的呼喚……一點禮儀都沒有？！",
  ui_story_10_8_1_33_dialog_content = "妳應該回答「是，我正在聽您的吩咐，斐桀洛大人」！",
  ui_story_10_8_1_34_dialog_content = "是……<color=#FFB400>斐、斐桀洛大人</color>……",
  ui_story_10_8_1_35_dialog_content = "連重複我的話都不會，真蠢……",
  ui_story_10_8_1_36_dialog_content = "桀桀桀，不過沒關係，我不會跟妳一般見識。",
  ui_story_10_8_1_37_dialog_content = "畢竟現在，妳對我們來說還是特別的。",
  ui_story_10_8_1_38_dialog_content = "我知道妳剛成為暗鬼不久，還不清楚狀況。",
  ui_story_10_8_1_39_dialog_content = "這是屬於暗鬼的溝通方式，我在使用母親留給我們的能力。",
  ui_story_10_8_1_40_dialog_content = "即使身在遠方，我也能將聲音直接傳達給妳……",
  ui_story_10_8_1_41_dialog_content = "母親留給我們的能力？",
  ui_story_10_8_1_42_dialog_content = "記住，是「母親」的意志讓我選擇了妳，給妳機會，賜予妳力量。",
  ui_story_10_8_1_43_dialog_content = "妳能夠這麼快適應「種子」並獲得力量，表示「母親」的眼光沒有錯。",
  ui_story_10_8_1_44_dialog_content = "不過現在的妳，還沒資格知曉更多。",
  ui_story_10_8_1_45_dialog_content = "只有變得更加強大，做出更多貢獻，妳才有資格聆聽「母親」的教誨。",
  ui_story_10_8_1_46_dialog_content = "告訴我，妳把我吩咐的事情完成了嗎？",
  ui_story_10_8_1_47_dialog_content = "完成了。",
  ui_story_10_8_1_48_dialog_content = "很好。現在，駕駛妳的巨像來到我身邊吧。",
  ui_story_10_8_1_49_dialog_content = "暗鬼大軍已經如期進入了空谷，審判即將來臨。",
  ui_story_10_8_1_50_dialog_content = "留給妳的時間不多了……不要忘了，妳還有身為使者的使命。",
  ui_story_10_8_1_51_dialog_content = "唔……使者？",
  ui_story_10_8_1_S1_dialog_content = "對，妳可以帶我去見妳認為有資格獲得力量的空裔。",
  ui_story_10_8_1_52_dialog_content = "我會給他們<color=#FFB400>獲得救贖</color>的機會。",
  ui_story_10_8_1_S2_dialog_content = "唔……",
  ui_story_10_8_1_S3_dialog_content = "舒默，妳在支支吾吾些什麼？",
  ui_story_10_8_1_S4_dialog_content = "我突然……覺得……很癢……",
  ui_story_10_8_1_S5_dialog_content = "很癢？",
  ui_story_10_8_1_S6_dialog_content = "桀桀桀，你開始覺得不舒服了是嗎？還有沒有其他異常感覺？",
  ui_story_10_8_1_S7_dialog_content = "其他異常感覺……",
  ui_story_10_8_1_S8_dialog_content = "眼睛睜不開，外面的光線太強了……",
  ui_story_10_8_1_S9_dialog_content = "果然如此……能夠這麼快就讓體內的「種子」產生變化，很好！",
  ui_story_10_8_1_S10_dialog_content = "我感受到妳身上的暗能已經成熟了。",
  ui_story_10_8_1_S11_dialog_content = "妳應當以一種完全不同的姿態，與我們一起降臨空谷。",
  ui_story_10_8_1_S12_dialog_content = "完全不同的姿態……",
  ui_story_10_8_1_S13_dialog_content = "沒錯，妳已經超越空裔了。空裔這副低等的樣貌不適合妳。",
  ui_story_10_8_1_S14_dialog_content = "但我……天生就是這副樣貌……",
  ui_story_10_8_1_S15_dialog_content = "但妳可以擺脫它，就像擺脫空裔註定弱小、註定被消滅的命運……",
  ui_story_10_8_1_S16_dialog_content = "擺脫它……我該怎麼做？",
  ui_story_10_8_1_S17_dialog_content = "妳該怎麼做？桀桀桀。",
  ui_story_10_8_1_S18_dialog_content = "盡情渴望力量吧！這樣一來，妳體內潛藏的力量就會告訴妳該怎麼做！",
  ui_story_10_8_1_S19_dialog_content = "……",
  ui_story_10_8_1_S20_dialog_content = "渴望更加強大的力量……",
  ui_story_10_8_1_S21_dialog_content = "渴望擺脫弱小的命運……",
  ui_story_10_8_1_S22_dialog_content = "渴望蛻變……",
  ui_story_10_8_1_S23_dialog_content = "不……我已經和他們不一樣了。",
  ui_story_10_8_1_S24_dialog_content = "我已經得到一切了！",
  ui_story_10_8_1_53_dialog_content = "快去那邊看看！快去！",
  ui_story_10_8_1_54_dialog_content = "帶好武器！帶好武器！",
  ui_story_10_8_1_55_dialog_content = "是什麼騷動……",
  ui_story_10_8_1_56_dialog_content = "發生了什麼事嗎？",
  ui_story_10_8_1_57_dialog_content = "原來你躲在這裡……",
  ui_story_10_8_1_58_dialog_content = "妳……妳是誰？！",
  ui_story_10_8_1_59_dialog_content = "哈哈，我是舒默啊。你不敢相信自己的眼睛嗎？",
  ui_story_10_8_1_60_dialog_content = "舒默？不、妳的角？頭髮？樣子……完全不一樣！",
  ui_story_10_8_1_61_dialog_content = "不要懷疑，不要害怕，這是我成為使者的證明。",
  ui_story_10_8_1_62_dialog_content = "因為我被選中了，所以我得到了力量，遠遠超越空裔的力量。",
  ui_story_10_8_1_63_dialog_content = "使、使者？力量？這……是什麼意思？",
  ui_story_10_8_1_64_dialog_content = "……",
  ui_story_10_8_1_65_dialog_content = "跟你說你也不懂！你只要記住我比所有的空裔都強大就行了！",
  ui_story_10_8_1_66_dialog_content = "你回答我，你為什麼要幫我？為什麼要把鑰匙藏在書裡給我？",
  ui_story_10_8_1_67_dialog_content = "他、他們說，他們要、要把妳關起來，關、關到死……",
  ui_story_10_8_1_68_dialog_content = "要是我敢跟老師說……下、下一個就是我……",
  ui_story_10_8_1_69_dialog_content = "但是我、我……我們是同胞、是兄弟……我們不應該……",
  ui_story_10_8_1_70_dialog_content = "喔，原來是無聊的同情。",
  ui_story_10_8_1_71_dialog_content = "簡單點來說，妳就是同情我的遭遇吧？",
  ui_story_10_8_1_72_dialog_content = "那幾個男生看到我被關起來，就敢隨口胡說……真可笑。",
  ui_story_10_8_1_73_dialog_content = "我、我不明白……到底怎麼回事……妳不是被他們欺負了嗎？",
  ui_story_10_8_1_74_dialog_content = "學生私自跑出空谷被暗鬼殺死，這種事情那群長老是不敢說出來的。",
  ui_story_10_8_1_75_dialog_content = "因為他們害怕，大家知道審判降臨就不會聽他們的管教了。",
  ui_story_10_8_1_76_dialog_content = "聽著，你別誤會了，那本書和鑰匙，我都沒打算接受。",
  ui_story_10_8_1_77_dialog_content = "但我也不是冷血無情的。既然你之前打算幫我，我就給你活下去的機會。",
  ui_story_10_8_1_78_dialog_content = "妳也會獲得強大的力量，從此以後……",
  ui_story_10_8_1_79_dialog_content = "你、你在說什麼……什麼活下去的機會……",
  ui_story_10_8_1_80_dialog_content = "你還不知道嗎？",
  ui_story_10_8_1_81_dialog_content = "空谷的末日來臨了，暗鬼帶來了這個世界的審判。",
  ui_story_10_8_1_82_dialog_content = "大家都要死啦……",
  ui_story_10_8_1_83_dialog_content = "和我一樣成為暗鬼吧！",
  ui_story_10_8_1_84_dialog_content = "不、不是的……我……我……",
  ui_story_10_8_1_85_dialog_content = "就是他嗎？",
  ui_story_10_8_1_86_dialog_content = "我很忙，快點結束吧……",
  ui_story_10_8_1_87_dialog_content = "！！！",
  ui_story_10_8_1_88_dialog_content = "如果你不同意，你就會死。",
  ui_story_10_8_1_89_dialog_content = "直接說吧，你想不想死？",
  ui_story_10_8_1_90_dialog_content = "我……",
  ui_story_10_8_1_91_dialog_content = "咕……",
  ui_story_10_8_1_92_dialog_content = "只是一隻暗鬼就這麼難對付……",
  ui_story_10_8_1_93_dialog_content = "漢德羅！不好了！東面也發現了暗鬼！",
  ui_story_10_8_1_94_dialog_content = "你們先走！我馬上去！",
  ui_story_10_8_1_95_dialog_content = "老師！我回來了！",
  ui_story_10_8_1_96_dialog_content = "妳跟我一起走吧！",
  ui_story_10_8_1_97_dialog_content = "你……？！",
  ui_story_10_8_1_98_dialog_content = "舒默？！",
  ui_story_10_8_1_99_dialog_content = "老師你別害怕。",
  ui_story_10_8_1_100_dialog_content = "長老一直沒有告訴大家，空谷註定會被暗鬼毀滅，所以大家才會這麼慌亂。",
  ui_story_10_8_1_101_dialog_content = "你在說什麼？",
  ui_story_10_8_1_102_dialog_content = "這個審判其實就是註定要到來的……",
  ui_story_10_8_1_103_dialog_content = "這是世界的選擇，是進化的選擇。",
  ui_story_10_8_1_104_dialog_content = "暗鬼也不會傷害不該傷害的人，只要你有足夠的資格……",
  ui_story_10_8_1_105_dialog_content = "就能夠在審判中活下來！",
  ui_story_10_8_1_106_dialog_content = "我已經是暗鬼的使者了，我可以向它們推薦你！",
  ui_story_10_8_1_107_dialog_content = "捆起來！快，把她捆起來！",
  ui_story_10_8_1_108_dialog_content = "快上！大家一起上！",
  ui_story_10_8_1_109_dialog_content = "……？",
  ui_story_10_8_1_110_dialog_content = "讓人把密室的門打開！快！",
  ui_story_10_8_1_111_dialog_content = "鎖起來……把舒默鎖起來……",
  ui_story_10_8_1_112_dialog_content = "……",
  ui_story_10_8_1_113_dialog_content = "這就是妳的答案嗎……",
  ui_story_10_8_1_114_dialog_content = "真是懦夫……",
  ui_story_10_8_1_115_dialog_content = "但是沒關係……",
  ui_story_10_8_1_116_dialog_content = "妳會後悔的。",
  ui_story_10_8_1_117_dialog_content = "等它們降臨，你們全部都會後悔，都會回頭來求我……",
  ui_story_10_8_1_118_dialog_content = "求我給你們機會。",
  ui_story_10_8_1_119_dialog_content = "啊——！",
  ui_story_10_8_1_120_dialog_content = "快走！快！往那邊跑！",
  ui_story_10_8_1_121_dialog_content = "還有沒有能動的巨像？！",
  ui_story_10_8_1_122_dialog_content = "能感應的去找路！帶孩子先走！",
  ui_story_10_8_1_123_dialog_content = "不行了……太多了……暗鬼太多了……",
  ui_story_10_8_1_124_dialog_content = "嗯——多麼美妙的聲音。",
  ui_story_10_8_1_125_dialog_content = "自從剿滅那群跟動物一樣低等的亞人族以後……",
  ui_story_10_8_1_126_dialog_content = "我已經很久沒有聽到過如此撕心裂肺的慘叫了。",
  ui_story_10_8_1_127_dialog_content = "雖然這群空裔叫得沒有那些亞人族響，但他們的高音很動聽嘛。",
  ui_story_10_8_1_128_dialog_content = "不愧是愛唱歌的種族，桀桀。",
  ui_story_10_8_1_129_dialog_content = "咕……",
  ui_story_10_8_1_130_dialog_content = "去吧，去給我引發更多的尖叫聲！去消滅他們！",
  ui_story_10_8_1_131_dialog_content = "吼！",
  ui_story_10_8_1_132_dialog_content = "去把可以運作的巨像拉出來！",
  ui_story_10_8_1_133_dialog_content = "快！去幫倖存的人！",
  ui_story_10_8_1_134_dialog_content = "咳……",
  ui_story_10_8_1_135_dialog_content = "咳、咳……",
  ui_story_10_8_1_136_dialog_content = "還有一個活著的人……太好了……",
  ui_story_10_8_1_137_dialog_content = "老師……老師……",
  ui_story_10_8_1_138_dialog_content = "孟德爾頌，太好了……我們快走……",
  ui_story_10_8_1_139_dialog_content = "老師……大家都死了……",
  ui_story_10_8_1_140_dialog_content = "老師……我還能走嗎……能逃出去嗎？",
  ui_story_10_8_1_141_dialog_content = "當然能，我們能逃出去的，咳……跟我來……",
  ui_story_10_8_1_142_dialog_content = "走這邊，快點……<color=#FFB400>守祕者號</color>就在附近……",
  ui_story_10_8_1_143_dialog_content = "……",
  ui_story_10_8_1_144_dialog_content = "老師？",
  ui_story_10_8_1_145_dialog_content = "孟德爾頌，你聽我說，我感應到接應我們的人已經被全滅了……",
  ui_story_10_8_1_146_dialog_content = "等一下只能由我去引開那附近的暗鬼，你趁機跑進守祕者號，守祕者號還能啟動。",
  ui_story_10_8_1_147_dialog_content = "守祕者號裡有個特殊房間，你離開空谷後，就去找那個房間……",
  ui_story_10_8_1_148_dialog_content = "裡面有一個<color=#FFB400>特殊組件</color>，那個東西的存在……",
  ui_story_10_8_1_149_dialog_content = "會讓巨像的認知被徹底改變。",
  ui_story_10_8_1_150_dialog_content = "一旦被邪惡的人得到，後果不堪設想。",
  ui_story_10_8_1_151_dialog_content = "能駕駛守祕者號的人已經死了，現在只剩下你了。",
  ui_story_10_8_1_152_dialog_content = "我、我不行……我從來沒有成功感應過巨像……",
  ui_story_10_8_1_153_dialog_content = "我相信你做得到。你很有潛力，只是缺乏自信。",
  ui_story_10_8_1_154_dialog_content = "你很適合守祕者號，我們本來就想將你培養成守祕者號的下一任導航員。",
  ui_story_10_8_1_155_dialog_content = "可是老師……你能夠感應巨像……難道你不和我一起去嗎？",
  ui_story_10_8_1_156_dialog_content = "我沒辦法和你一起去了，<color=#FFB400>教化者號</color>還在等著我。",
  ui_story_10_8_1_157_dialog_content = "我相信你，你沒問題的，一定可以成功啟動它。",
  ui_story_10_8_1_158_dialog_content = "守祕者號裡有名為<color=#FFB400>菲尼克斯</color>和<color=#FFB400>樊尼</color>的守護者，他們會幫助你、陪伴你……",
  ui_story_10_8_1_159_dialog_content = "我……老師……我一個人不行，我從來沒有感應成功過……",
  ui_story_10_8_1_160_dialog_content = "你一定可以順利啟動它。這個時候，你不能再懷疑自己。",
  ui_story_10_8_1_161_dialog_content = "可是那些暗鬼……它們到處都是，還有一隻特別恐怖……",
  ui_story_10_8_1_162_dialog_content = "就算啟動了巨像……也逃不掉……",
  ui_story_10_8_1_163_dialog_content = "會死的……這樣下去，大家都會死的……",
  ui_story_10_8_1_164_dialog_content = "老師，舒默說有讓我們活下去的辦法……",
  ui_story_10_8_1_165_dialog_content = "你？！她去找過你了？",
  ui_story_10_8_1_166_dialog_content = "或許我們能換種方式活下去……",
  ui_story_10_8_1_167_dialog_content = "在末日裡活下去……",
  ui_story_10_8_1_168_dialog_content = "舒默，妳玩夠了嗎？",
  ui_story_10_8_1_169_dialog_content = "斐桀洛大人……我已經沒有想選擇的人了。",
  ui_story_10_8_1_170_dialog_content = "他們真可憐，我已經等夠了。",
  ui_story_10_8_1_171_dialog_content = "他們再也不會有活下去的機會了。",
  ui_story_10_8_1_172_dialog_content = "桀！桀！桀！那麼來見證偉大的末日吧！",
  ui_story_10_8_1_173_dialog_content = "日蝕降臨了！",
  ui_story_10_9_1_1_dialog_content = "PlayerName？！",
  ui_story_10_9_1_2_dialog_content = "是末日……和<color=#FFB400>日蝕</color>……",
  ui_story_10_9_1_3_dialog_content = "什麼末日？聽不明白，你先緩一下，然後說清楚一點。",
  ui_story_10_9_1_4_dialog_content = "我曾經夢見過空谷被毀的畫面……",
  ui_story_10_9_1_5_dialog_content = "那些都是真的。",
  ui_story_10_9_1_6_dialog_content = "我感應到舒默有關空谷的記憶了，是空谷被暗鬼襲擊那天。",
  ui_story_10_9_1_7_dialog_content = "舒默帶著暗鬼進入了空谷……",
  ui_story_10_9_1_8_dialog_content = "整個天都變黑了，出現了日蝕……",
  ui_story_10_9_1_9_dialog_content = "最重要的是，有一個叫做<color=#FFB400>「斐桀洛」</color>的人形暗鬼……",
  ui_story_10_9_1_10_dialog_content = "是他帶著暗鬼，毀滅了整座空谷！",
  ui_story_10_9_1_11_dialog_content = "……你還好嗎？",
  ui_story_10_9_1_12_dialog_content = "我沒事。前方有大批暗鬼來襲，我們要準備戰鬥了。",
  ui_story_10_9_1_13_dialog_content = "在這半點聲音都聽不到的鬼地方，你也能預測暗鬼來襲？",
  ui_story_10_9_1_14_dialog_content = "能聽到一點聲音了！那群暗鬼來了！",
  ui_story_10_9_1_15_dialog_content = "哈，剛剛看你這麼激動，還以為你要情緒失控了。",
  ui_story_10_9_1_16_dialog_content = "沒想到你還能冷靜地判斷戰局。",
  ui_story_10_9_1_17_dialog_content = "不過我得提醒你，光有復仇的決心可不夠。",
  ui_story_10_9_1_18_dialog_content = "到時候見到仇人可太別激動，好好當你的指揮官，發揮你所有的作用。",
  ui_story_10_9_1_19_dialog_content = "多謝提醒，我會的。",
  ui_story_10_9_1_20_dialog_content = "我會冷靜地面對她……然後完成復仇。",
  ui_story_10_13_1_1_dialog_content = "成為暗鬼，並不一定能駕馭暗鬼的力量。",
  ui_story_10_13_1_2_dialog_content = "甚至有可能被暗能影響，變得容易失控……",
  ui_story_10_13_1_3_dialog_content = "即使舒默這種一天到晚渴望著力量的人，也只能把力量提升到這種程度。",
  ui_story_10_13_1_4_dialog_content = "如果再這樣下去……這次實驗，就沒有繼續記錄的必要了。",
  ui_story_10_13_1_5_dialog_content = "（日蝕語）主人，那現在該如何是好？",
  ui_story_10_13_1_6_dialog_content = "（日蝕語）那群光靈，很快就要到達這裡了。",
  ui_story_10_13_1_7_dialog_content = "不能指望舒默自己成長了。",
  ui_story_10_13_1_8_dialog_content = "我來激化她。",
  ui_story_10_13_1_9_dialog_content = "你繼續去監視那些光靈的動向。",
  ui_story_10_13_1_10_dialog_content = "（日蝕語）是。",
  ui_story_10_13_1_11_dialog_content = "舒默。",
  ui_story_10_13_1_12_dialog_content = "吵……死了……",
  ui_story_10_13_1_13_dialog_content = "還沒睡醒嗎？",
  ui_story_10_13_1_14_dialog_content = "啊……？",
  ui_story_10_13_1_15_dialog_content = "收起妳那癡呆的表情吧，我是來通知妳實驗結果的。",
  ui_story_10_13_1_16_dialog_content = "什麼……？",
  ui_story_10_13_1_17_dialog_content = "最終結論是……妳是一個<color=#FFB400>徹頭徹尾的廢物</color>。",
  ui_story_10_13_1_18_dialog_content = "……吞……羅。",
  ui_story_10_13_1_19_dialog_content = "別急躁，舒默。我現在告訴妳的是客觀事實。",
  ui_story_10_13_1_20_dialog_content = "妳吃了整座吞噬者號，吃了一堆暗鬼，卻還是沒能完成蛻變。",
  ui_story_10_13_1_21_dialog_content = "吃……吞噬者號……？",
  ui_story_10_13_1_22_dialog_content = "是的，這個治療繭連結著妳的吞噬者號。",
  ui_story_10_13_1_23_dialog_content = "妳透過治療繭吸收了它的能量，現在它已經變成一堆廢鐵了。",
  ui_story_10_13_1_24_dialog_content = "妳……為什麼不告訴我……",
  ui_story_10_13_1_25_dialog_content = "我知道妳很在意這座巨像。",
  ui_story_10_13_1_26_dialog_content = "好不容易得到了小時候最想要的玩具，一直抓著不想放手。這很正常。",
  ui_story_10_13_1_27_dialog_content = "很明顯，妳骨子裡還是個軟弱的空裔。",
  ui_story_10_13_1_28_dialog_content = "所以見到PlayerName，既捨不得殺他，又不想放過他。",
  ui_story_10_13_1_29_dialog_content = "妳一直被過去的陰影籠罩著吧，真可憐。",
  ui_story_10_13_1_30_dialog_content = "我希望妳沒有妄想過要主宰自己的命運。",
  ui_story_10_13_1_31_dialog_content = "弱者沒有這個資格。",
  ui_story_10_13_1_32_dialog_content = "混蛋……",
  ui_story_10_13_1_33_dialog_content = "妳應該憤怒。",
  ui_story_10_13_1_34_dialog_content = "因為這一切都是妳咎由自取。",
  ui_story_10_13_1_35_dialog_content = "因為妳幼稚，弱小，淺薄、愚蠢……",
  ui_story_10_13_1_36_dialog_content = "弄……死妳……",
  ui_story_10_13_1_37_dialog_content = "不，妳的憤怒不應該針對我。",
  ui_story_10_13_1_38_dialog_content = "妳忘了。",
  ui_story_10_13_1_39_dialog_content = "是誰將妳逼到這個地步的？",
  ui_story_10_13_1_40_dialog_content = "還記得那名空裔說過的話嗎？",
  ui_story_10_13_1_41_dialog_content = "「妳總是跪在地上，祈求力量」。",
  ui_story_10_13_1_42_dialog_content = "他看穿妳了……",
  ui_story_10_13_1_43_dialog_content = "現在，他們來了。",
  ui_story_10_13_1_44_dialog_content = "他們會來到妳面前，殺了妳。",
  ui_story_10_13_1_45_dialog_content = "或許妳可以祈求他們的原諒。",
  ui_story_10_13_1_46_dialog_content = "不可能……",
  ui_story_10_13_1_47_dialog_content = "妳可以祈求他們放過你，祈求PlayerName不要殺妳。",
  ui_story_10_13_1_48_dialog_content = "開什麼……玩笑……",
  ui_story_10_13_1_49_dialog_content = "如果妳不想死……",
  ui_story_10_13_1_50_dialog_content = "想活下去，想殺掉那些傢伙。",
  ui_story_10_13_1_51_dialog_content = "那就只剩下一種方法了。",
  ui_story_10_13_1_52_dialog_content = "渴望更多的力量吧。",
  ui_story_10_13_1_53_dialog_content = "力量……",
  ui_story_10_13_1_54_dialog_content = "……",
  ui_story_10_13_1_55_dialog_content = "舒默？",
  ui_story_10_13_1_56_dialog_content = "<size=45>給我力量！</size>",
  ui_story_10_13_1_57_dialog_content = "……",
  ui_story_10_13_1_58_dialog_content = "雖然在一定程度上預想到了妳會難以控制自己的情緒。",
  ui_story_10_13_1_59_dialog_content = "卻沒想到妳會直接失去理智……",
  ui_story_10_13_1_60_dialog_content = "<size=45>力量——！！！</size>",
  ui_story_10_13_1_61_dialog_content = "無可救藥。",
  ui_story_10_13_1_62_dialog_content = "<color=#e8d9bb>吼——！</color>",
  ui_story_10_13_1_63_dialog_content = "什、什麼聲音？",
  ui_story_10_13_1_64_dialog_content = "PlayerName，能查明是什麼情況嗎？",
  ui_story_10_13_1_65_dialog_content = "不知道……哪怕用盡全力，也只能捕捉到一點點舒默的想法……",
  ui_story_10_13_1_66_dialog_content = "什麼「強大」、「力量」、「特別」之類的。",
  ui_story_10_13_1_67_dialog_content = "除此之外，還有一種很強烈的……",
  ui_story_10_13_1_68_dialog_content = "<color=#FFB400>憎恨。</color>",
  ui_story_10_13_1_69_dialog_content = "這種狀態……簡直就像發瘋了一樣!",
  ui_story_10_13_1_70_dialog_content = "發瘋？先是吃暗鬼，然後發瘋？",
  ui_story_10_13_1_71_dialog_content = "聽起來好奇怪……",
  ui_story_10_13_1_72_dialog_content = "肯定和吞羅有關。",
  ui_story_10_13_1_73_dialog_content = "吞羅很可能將我們來到這裡的事情告訴了舒默。",
  ui_story_10_13_1_74_dialog_content = "她一定做好了要跟我們戰鬥的準備。",
  ui_story_10_13_1_75_dialog_content = "如果她有攻擊你的打算，可能會忽略我們，直接襲擊你。",
  ui_story_10_13_1_76_dialog_content = "如果再加上吞羅在場，到時候，我們不一定能保住你。",
  ui_story_10_13_1_77_dialog_content = "我等會先去探探情況，你們確保PlayerName的安全。",
  ui_story_10_13_1_78_dialog_content = "好。",
  ui_story_10_13_1_79_dialog_content = "前方發現暗鬼！",
  ui_story_10_13_1_80_dialog_content = "迅速解決它們！",
  ui_story_10_13_1_81_dialog_content = "嘎！",
  ui_story_10_13_1_82_dialog_content = "怎麼回事？！這些暗鬼突然激動起來了？",
  ui_story_10_13_1_83_dialog_content = "是因為剛才的地震嗎？！",
  ui_story_10_13_1_84_dialog_content = "我有種不好的預感……",
  ui_story_10_13_1_85_dialog_content = "就連契法小姐都預感到了。",
  ui_story_10_13_1_86_dialog_content = "那一定是特別危險的東西出現了吧。",
  ui_story_10_13_1_87_dialog_content = "維多利亞大人吩咐……",
  ui_story_10_13_1_88_dialog_content = "現在還不應該涉足至這些紛爭之中。",
  ui_story_10_13_1_89_dialog_content = "嗯，既然「種子」已經回收得差不多，我們也該離開這舞台了。",
  ui_story_10_13_1_90_dialog_content = "大戰就要開始了。",
  ui_story_10_13_2_1_dialog_content = "嘎！！",
  ui_story_10_13_2_2_dialog_content = "……",
  ui_story_10_13_2_3_dialog_content = "舒默？！",
  ui_story_10_13_2_4_dialog_content = "她、她……她直接撲向了暗鬼？！",
  ui_story_10_13_2_5_dialog_content = "把暗鬼吃了？",
  ui_story_10_13_2_6_dialog_content = "這……這是舒默嗎？她的樣子完全變了？！",
  ui_story_10_13_2_7_dialog_content = "舒默！",
  ui_story_10_13_2_8_dialog_content = "我已經知道妳全部的罪行了……",
  ui_story_10_13_2_9_dialog_content = "妳不想死，去當妳的暗鬼不就夠了？",
  ui_story_10_13_2_10_dialog_content = "為什麼要將暗鬼帶入空谷？！",
  ui_story_10_13_2_11_dialog_content = "為什麼要害死所有人？！",
  ui_story_10_13_2_12_dialog_content = "……",
  ui_story_10_13_2_13_dialog_content = "妳這個叛徒，我要妳付出代價！",
  ui_story_10_13_2_14_dialog_content = "吼——！！",
  ui_story_10_13_2_15_dialog_content = "PlayerName！小心！",
  ui_story_10_13_2_16_dialog_content = "嘎？！",
  ui_story_10_13_2_17_dialog_content = "她……去襲擊了角落裡的暗鬼？",
  ui_story_10_13_2_18_dialog_content = "……",
  ui_story_10_13_2_19_dialog_content = "力量……",
  ui_story_10_13_2_20_dialog_content = "這到底是什麼情况……",
  ui_story_10_13_2_21_dialog_content = "她好像是……完全看不見我們一樣？",
  ui_story_10_13_2_22_dialog_content = "PlayerName……你剛才的行為太危險了！",
  ui_story_10_13_2_23_dialog_content = "你身為指揮者，怎麼能比我們這些實際上場的還衝動？！",
  ui_story_10_13_2_24_dialog_content = "抱歉……我冷靜下來了。",
  ui_story_10_13_2_25_dialog_content = "……",
  ui_story_10_13_2_26_dialog_content = "接下來怎麼辦？",
  ui_story_10_13_2_27_dialog_content = "舒默……恐怕是為了獲得力量不擇手段，結果失去了理智。",
  ui_story_10_13_2_28_dialog_content = "小心作戰，最好能先試探她的力量。",
  ui_story_10_13_2_29_dialog_content = "咕……",
  ui_story_10_13_2_30_dialog_content = "她……她看過來了？這是因為暗鬼吃完了嗎？！",
  ui_story_10_13_2_31_dialog_content = "……",
  ui_story_10_13_2_32_dialog_content = "PlayerName……",
  ui_story_10_13_2_33_dialog_content = "她有反應了？！",
  ui_story_10_13_2_34_dialog_content = "PlayerName……殺了你們……",
  ui_story_10_13_2_35_dialog_content = "想動他？！先過我這關！",
  ui_story_10_13_2_36_dialog_content = "<anim type=Shake><size=50>PlayerName！去死！！死！！！</size></anim>",
  ui_story_10_14_2_1_dialog_content = "贏了？！",
  ui_story_10_14_2_2_dialog_content = "给她最後一擊，快！",
  ui_story_10_14_2_3_dialog_content = "舒默！接受制裁吧！",
  ui_story_10_14_2_4_dialog_content = "吼——！",
  ui_story_10_14_2_5_dialog_content = "好長的夢，好噁心……",
  ui_story_10_14_2_6_dialog_content = "偏偏是十七年前的那段記憶……",
  ui_story_10_14_2_7_dialog_content = "真是夠了……",
  ui_story_10_14_2_8_dialog_content = "夠了——！",
  ui_story_10_14_2_9_dialog_content = "PlayerName！小心！！",
  ui_story_10_14_2_10_dialog_content = "轟——",
  ui_story_10_14_2_11_dialog_content = "咳……",
  ui_story_10_14_2_12_dialog_content = "這傢伙……被打倒了一次還能發動攻擊……",
  ui_story_10_14_2_13_dialog_content = "這麼強的戰力……開什麼玩笑？",
  ui_story_10_14_2_14_dialog_content = "……",
  ui_story_10_14_2_15_dialog_content = "薇絲、PlayerName……還好嗎？",
  ui_story_10_14_2_16_dialog_content = "勉強……還好……",
  ui_story_10_14_2_17_dialog_content = "我沒事……有叭噗護著我……多謝。",
  ui_story_10_14_2_18_dialog_content = "不客氣。平安最重要……",
  ui_story_10_14_2_19_dialog_content = "……",
  ui_story_10_14_2_20_dialog_content = "死了？",
  ui_story_10_14_2_21_dialog_content = "不，不對……",
  ui_story_10_14_2_22_dialog_content = "哈、哈哈、哈哈哈……",
  ui_story_10_14_2_23_dialog_content = "舒默恢復理智了！所有人準備再戰……她還有餘力！",
  ui_story_10_14_2_24_dialog_content = "理智？",
  ui_story_10_14_2_25_dialog_content = "對了，我剛才……很憤怒……",
  ui_story_10_14_2_26_dialog_content = "不過……PlayerName，我一想到你要來，就高興多了。",
  ui_story_10_14_2_27_dialog_content = "……！",
  ui_story_10_14_2_28_dialog_content = "這是什麼變態發言？！",
  ui_story_10_14_2_29_dialog_content = "PlayerName你往後面站一點！",
  ui_story_10_14_2_30_dialog_content = "叭噗！那傢伙的安全就交給妳了！",
  ui_story_10_14_2_31_dialog_content = "收到！",
  ui_story_10_14_2_32_dialog_content = "喂！死變態！吞羅在哪？告訴我！",
  ui_story_10_14_2_33_dialog_content = "「死變態」？你是在罵我嗎？",
  ui_story_10_14_2_34_dialog_content = "沒關係，我不會跟你生氣的……你不配。",
  ui_story_10_14_2_35_dialog_content = "至於吞羅……妳不用擔心。",
  ui_story_10_14_2_36_dialog_content = "我會去找那個逃跑的混蛋算帳的。",
  ui_story_10_14_2_37_dialog_content = "不過，在那之前，PlayerName，來算算我們之間的恩怨吧。",
  ui_story_10_14_2_38_dialog_content = "我保證，這次我會盡全力……",
  ui_story_10_14_2_39_dialog_content = "讓你痛苦地去死！！！",
  ui_story_10_14_2_40_dialog_content = "！！！",
  ui_story_10_14_2_41_dialog_content = "妳打算跟他們拼命？這可不行……",
  ui_story_10_14_2_42_dialog_content = "吞羅……？！",
  ui_story_10_14_2_43_dialog_content = "做得不錯，因為妳的戰意，「種子」最終成熟了……",
  ui_story_10_14_2_44_dialog_content = "但是在剛才的戰鬥中，妳已經消耗掉了大部分的能量。",
  ui_story_10_14_2_45_dialog_content = "再這樣使用下去，會影響到我好不容易培育出來的「種子」啊。",
  ui_story_10_14_2_46_dialog_content = "你……？！",
  ui_story_10_14_2_47_dialog_content = "在我取出「種子」之前，老實一點。",
  ui_story_10_14_2_48_dialog_content = "醒山！吞羅的目標是舒默！是<color=#FFB400>「種子」</color>！",
  ui_story_10_14_2_49_dialog_content = "休想把東西拿走！",
  ui_story_10_14_2_50_dialog_content = "不要這麼激動，從結果上來講，是我救了你們。",
  ui_story_10_14_2_51_dialog_content = "舒默任憑你們處置，而我拿到種子。",
  ui_story_10_14_2_52_dialog_content = "各取所需，皆大歡喜。",
  ui_story_10_14_2_53_dialog_content = "況且，你阻止不了我……",
  ui_story_10_14_2_54_dialog_content = "醒山小心！！！",
  ui_story_10_14_2_55_dialog_content = "大範圍攻擊？！",
  ui_story_10_14_2_56_dialog_content = "都老老實實趴著吧。",
  ui_story_10_14_2_57_dialog_content = "最後……",
  ui_story_10_14_2_58_dialog_content = "臨死前妳還有什麼想說的嗎？舒默。",
  ui_story_10_14_2_59_dialog_content = "我想聽聽妳失去力量後的感想，或者說是變回空裔的感想。",
  ui_story_10_14_2_60_dialog_content = "如果有價值的話，我會把它寫在我的實驗紀錄上。",
  ui_story_10_14_2_61_dialog_content = "……",
  ui_story_10_14_2_62_dialog_content = "呸……",
  ui_story_10_14_2_63_dialog_content = "……好吧。",
  ui_story_10_14_2_64_dialog_content = "那麼作為你們協助我完成實驗的謝禮，舒默就留給你們了。",
  ui_story_10_14_2_65_dialog_content = "永別了，舒默……",
  ui_story_10_14_2_66_dialog_content = "咳……",
  ui_story_10_14_2_67_dialog_content = "醒山……千萬不要……去追……",
  ui_story_10_14_2_68_dialog_content = "我知道。",
  ui_story_10_14_2_69_dialog_content = "PlayerName，舒默怎麼辦……你來決定。",
  ui_story_10_14_2_70_dialog_content = "舒默已經重傷將死，可能連行動都有困難。",
  ui_story_10_14_2_71_dialog_content = "不要顧忌剛才發生的事，完成你的心願吧。",
  ui_story_10_14_2_72_dialog_content = "PlayerName，只需要一根冰刺，你就能親手審判她。",
  ui_story_10_14_2_73_dialog_content = "在那之前，我還有要問的事。",
  ui_story_10_14_2_74_dialog_content = "哈……審判我？問話？",
  ui_story_10_14_2_75_dialog_content = "要不然……你問一句……我答一句？",
  ui_story_10_14_2_76_dialog_content = "告訴我那三個巨像組件在哪？",
  ui_story_10_14_2_77_dialog_content = "去死吧！",
  ui_story_10_14_2_78_dialog_content = "垃圾空裔！死小鬼！妳想要我的組件？！不可能！",
  ui_story_10_14_2_79_dialog_content = "妳根本就不懂組件的價值！那是只屬於吞噬者號的東西！",
  ui_story_10_14_2_80_option_content = "我不懂，妳就這麼樣重視吞噬者號？",
  ui_story_10_14_2_81_dialog_content = "妳背叛空裔……就只是因為想得到吞噬者號嗎？",
  ui_story_10_14_2_82_dialog_content = "妳面對暗鬼不想死，我無可厚非……",
  ui_story_10_14_2_83_dialog_content = "妳去當妳的暗鬼就好了，妳和它們走啊……但妳為什麼要把暗鬼放入空谷？！",
  ui_story_10_14_2_84_dialog_content = "為什麼？！",
  ui_story_10_14_2_85_dialog_content = "呵呵……",
  ui_story_10_14_2_86_dialog_content = "你不懂。",
  ui_story_10_14_2_87_dialog_content = "你們沒有面臨過末日，沒有面臨過真正的審判，你們不會懂的……",
  ui_story_10_14_2_88_dialog_content = "是降臨……它們是降臨到空谷的！",
  ui_story_10_14_2_89_dialog_content = "逃不掉！所有人都逃不掉！",
  ui_story_10_14_2_90_dialog_content = "你們也是一樣的……很快就要被毀滅了……",
  ui_story_10_14_2_91_dialog_content = "胡言亂語！根本就是被暗鬼洗腦了！",
  ui_story_10_14_2_92_dialog_content = "PlayerName，不要被她的話蠱惑了！",
  ui_story_10_14_2_93_option_content = "我根本不想懂！把組件交出來！",
  ui_story_10_14_2_94_dialog_content = "那不是妳的東西！",
  ui_story_10_14_2_95_dialog_content = "組件是空裔的！",
  ui_story_10_14_2_96_dialog_content = "是屬於空裔的！！",
  ui_story_10_14_2_97_dialog_content = "是空裔的東西！！！",
  ui_story_10_14_2_98_dialog_content = "不是妳這個叛徒有資格拿的東西！！！",
  ui_story_10_14_2_99_dialog_content = "……",
  ui_story_10_14_2_100_dialog_content = "你懂個屁！",
  ui_story_10_14_2_101_dialog_content = "空裔算什麼？弱小就算了，還不識好歹。",
  ui_story_10_14_2_102_dialog_content = "那群空裔根本就不知道巨像真正的價值，根本不知道力量的價值！",
  ui_story_10_14_2_103_dialog_content = "跟你一樣，都是群無知淺薄的白痴！",
  ui_story_10_14_2_104_dialog_content = "閉嘴！",
  ui_story_10_14_2_105_dialog_content = "PlayerName，不要情緒失控！",
  ui_story_10_14_2_106_dialog_content = "我知道。",
  ui_story_10_14_2_107_dialog_content = "我知道……",
  ui_story_10_14_2_108_dialog_content = "來的路上我已經想通了，如果暗鬼的目標一開始就是毀滅空谷。",
  ui_story_10_14_2_109_dialog_content = "不論透過什麼手段，不論在什麼時候，它們都有可能發動襲擊。",
  ui_story_10_14_2_110_dialog_content = "舒默，妳只是個可憐的犧牲品。",
  ui_story_10_14_2_111_dialog_content = "哈？",
  ui_story_10_14_2_112_dialog_content = "你在說什麼鬼話？",
  ui_story_10_14_2_113_dialog_content = "我是被選中的啊……是被選中的，有資格活下來的人！",
  ui_story_10_14_2_114_dialog_content = "薇絲，妳的傷勢怎麼樣？",
  ui_story_10_14_2_115_dialog_content = "欸？我、我還好……我沒事。",
  ui_story_10_14_2_116_dialog_content = "喂？！",
  ui_story_10_14_2_117_dialog_content = "你聽到我說話了嗎？！",
  ui_story_10_14_2_118_dialog_content = "薇絲，巨像構造大同小異，我大概能知道組件在什麼位置。",
  ui_story_10_14_2_119_dialog_content = "來幫忙拿一下吧。",
  ui_story_10_14_2_120_dialog_content = "好的。",
  ui_story_10_14_2_121_dialog_content = "……",
  ui_story_10_14_2_122_dialog_content = "…………",
  ui_story_10_14_2_123_dialog_content = "你的仇恨呢？",
  ui_story_10_14_2_124_dialog_content = "你不喊了？不罵了？不想復仇了？是因為對象是暗鬼嗎？",
  ui_story_10_14_2_125_dialog_content = "想趕快找到組件、殺了我，然後和你心愛的夥伴回家喝茶嗎？",
  ui_story_10_14_2_126_dialog_content = "PlayerName，我不介意幫忙堵上她的嘴……",
  ui_story_10_14_2_127_dialog_content = "不用理她！醒山你小心自己傷口……",
  ui_story_10_14_2_128_dialog_content = "叭噗，麻煩妳也過來幫忙拿一下組件吧。",
  ui_story_10_14_2_129_dialog_content = "好、好的。",
  ui_story_10_14_2_130_dialog_content = "哈、哈哈哈……",
  ui_story_10_14_2_131_dialog_content = "不愧是愛好和平的種族……",
  ui_story_10_14_2_132_dialog_content = "真愚蠢啊，空裔。",
  ui_story_10_14_2_133_dialog_content = "卡蓮，給我一根冰刺。",
  ui_story_10_14_2_134_dialog_content = "好。",
  ui_story_10_14_2_135_dialog_content = "……",
  ui_story_10_14_2_136_dialog_content = "舒默，告訴我<color=#FFB400>「斐桀洛」</color>是誰？",
  ui_story_10_14_2_137_dialog_content = "<color=#FFB400>「日蝕」</color>是什麼？",
  ui_story_10_14_2_138_dialog_content = "……！",
  ui_story_10_14_2_139_dialog_content = "你看了我的記憶？！",
  ui_story_10_14_2_140_dialog_content = "對，我看到了，可惜只能看到一部分。",
  ui_story_10_14_2_141_dialog_content = "剩下的情報，我打算從妳嘴裡撬出來。",
  ui_story_10_14_2_142_dialog_content = "……",
  ui_story_10_14_2_143_dialog_content = "哈、哈哈哈……",
  ui_story_10_14_2_144_dialog_content = "好啊，走近點，我告訴你……",
  ui_story_10_14_2_145_dialog_content = "走近一點，過來。",
  ui_story_10_14_2_146_dialog_content = "你不是要用冰刺審判我嗎？",
  ui_story_10_14_2_147_dialog_content = "PlayerName！她的狀態很奇怪，小心有詐。",
  ui_story_10_14_2_148_dialog_content = "放心，我沒打算過去。",
  ui_story_10_14_2_149_dialog_content = "已經太遲了……",
  ui_story_10_14_2_150_dialog_content = "咕……",
  ui_story_10_14_2_151_dialog_content = "咕……",
  ui_story_10_14_2_152_dialog_content = "小心背後！",
  ui_story_10_14_2_153_dialog_content = "嘎！",
  ui_story_10_14_2_154_dialog_content = "哈哈哈哈哈……",
  ui_story_10_14_2_155_dialog_content = "我說過了啊，我是被選中的！我是「日蝕」的使者！",
  ui_story_10_14_2_156_dialog_content = "過來……給我圍住他們……",
  ui_story_10_14_2_157_dialog_content = "咕……",
  ui_story_10_14_2_158_dialog_content = "咕……",
  ui_story_10_14_2_159_dialog_content = "最後要贏的人還是我……",
  ui_story_10_14_2_160_dialog_content = "PlayerName。",
  ui_story_10_14_2_161_dialog_content = "所謂競爭和進化，就是踩著別人的頭向上走！",
  ui_story_10_14_2_162_dialog_content = "你們和空谷才是真正的犧牲品！",
  ui_story_10_14_2_163_dialog_content = "越過你們、越過這些考驗，我就會變得無比強大！",
  ui_story_10_14_2_164_dialog_content = "……",
  ui_story_10_14_2_165_dialog_content = "各位……準備全力逃跑吧……",
  ui_story_10_14_2_166_dialog_content = "喂！小子，這可是好不容易才有的機會……跟它們拼了！",
  ui_story_10_14_2_167_dialog_content = "我很清楚大家的傷勢已經不可能再跟這麼多暗鬼戰鬥。",
  ui_story_10_14_2_168_dialog_content = "大家也應該比我更清楚……",
  ui_story_10_14_2_169_dialog_content = "我想要復仇……但復仇不能透過犧牲你們來完成……",
  ui_story_10_14_2_170_dialog_content = "想跑？那就跑好了，我倒想看看……",
  ui_story_10_14_2_171_dialog_content = "是你們這群傷殘跑得快，還是我手下的暗鬼跑得快！",
  ui_story_10_14_2_172_dialog_content = "給我咬死他們！",
  ui_story_10_14_2_173_dialog_content = "咕……",
  ui_story_10_14_2_174_dialog_content = "愣著幹嘛？！咬啊！",
  ui_story_10_14_2_175_dialog_content = "嘎！",
  ui_story_10_14_2_176_dialog_content = "什麼？！",
  ui_story_10_14_2_177_dialog_content = "好痛！放開我！！",
  ui_story_10_14_2_178_dialog_content = "不是我！不要！",
  ui_story_10_14_2_179_dialog_content = "不要！！！",
  ui_story_10_14_2_180_dialog_content = "嘎！",
  ui_story_10_14_2_181_dialog_content = "……",
  ui_story_10_14_2_182_dialog_content = "沒、沒時間了……快趁此機會撤退！",
  ui_story_10_14_2_183_dialog_content = "不然下一個就是我們！",
  ui_story_10_14_2_184_dialog_content = "PlayerName！",
  ui_story_10_14_2_185_dialog_content = "拉著PlayerName走！快！",
  ui_story_10_14_2_186_dialog_content = "走！",
  ui_story_10_14_2_187_dialog_content = "這種結局……",
  ui_story_10_14_2_188_dialog_content = "（我不接受！）",
  ui_story_10_14_2_189_dialog_content = "（好不容易才活下來，才得到這一切……）",
  ui_story_10_14_2_190_dialog_content = "（都是騙子！）",
  ui_story_10_14_2_191_dialog_content = "（都是假的！）",
  ui_story_10_14_2_192_dialog_content = "（假的力量！假的審判！）",
  ui_story_10_14_2_193_dialog_content = "（吞羅、斐桀洛、日蝕……）",
  ui_story_10_14_2_194_dialog_content = "（打從一開始……就沒打算放過我……）",
  ui_story_10_14_2_195_dialog_content = "（我詛咒你們……）",
  ui_story_10_14_2_196_dialog_content = "（弱小的種族命中註定要被毀滅……）",
  ui_story_10_14_2_197_dialog_content = "（空裔生來就受到詛咒……）",
  ui_story_10_14_2_198_dialog_content = "（你最後一定會跟我一樣……悲慘死去……）",
  ui_story_10_14_2_199_dialog_content = "（我詛咒你……）",
  ui_story_10_14_2_200_dialog_content = "（PlayerName……）",
  ui_story_10_14_2_201_dialog_content = "（感受註定毀滅的恐懼吧……）",
  ui_story_10_14_2_202_dialog_content = "（<color=#FFB400>日蝕早就降臨了！</color>）",
  ui_story_10_15_1_1_dialog_content = "（我還能夠做什麼……）",
  ui_story_10_15_1_2_dialog_content = "（那傢伙已經死了……）",
  ui_story_10_15_1_3_dialog_content = "（被暗鬼啃食……就這樣……淒慘地死掉了……）",
  ui_story_10_15_1_4_dialog_content = "（接下來……我們該怎麼辦……我該怎麼辦……）",
  ui_story_10_15_1_5_dialog_content = "咕……",
  ui_story_10_15_1_6_dialog_content = "（大家都受傷了……這些暗鬼……一定不會放過我們吧……）",
  ui_story_10_15_1_7_dialog_content = "（就像那個「日蝕」一樣……）",
  ui_story_10_15_1_8_dialog_content = "（把所有人都殺掉……）",
  ui_story_10_15_1_9_dialog_content = "怎麼辦……",
  ui_story_10_15_1_10_dialog_content = "跑啊！",
  ui_story_10_15_1_11_dialog_content = "把PlayerName給我拉起來！",
  ui_story_10_15_1_12_dialog_content = "這傢伙已經嚇傻了！直接拉走！",
  ui_story_10_15_1_13_dialog_content = "跑！往來的路上跑！",
  ui_story_10_15_1_14_dialog_content = "有暗鬼追上來了……",
  ui_story_10_15_1_15_dialog_content = "我來斷後！",
  ui_story_10_15_1_16_dialog_content = "嘎！",
  ui_story_10_15_1_17_dialog_content = "卡蓮？！",
  ui_story_10_15_1_18_dialog_content = "咳……我沒事，快走！",
  ui_story_10_15_1_19_dialog_content = "真是的……這一切都快結束了才開始給我們添麻煩……",
  ui_story_10_15_1_20_dialog_content = "……",
  ui_story_10_15_1_21_dialog_content = "追出來了？！真難纏！",
  ui_story_10_15_1_22_dialog_content = "嘎！",
  ui_story_10_15_1_23_dialog_content = "……！",
  ui_story_10_15_1_24_dialog_content = "PlayerName！振作起來啊！",
  ui_story_10_15_1_25_dialog_content = "大家需要你的支援！！",
  ui_story_10_15_1_26_dialog_content = "……",
  ui_story_10_15_1_27_dialog_content = "…………",
  ui_story_10_15_1_28_dialog_content = "薇絲……有暗鬼堵住通道了！射擊！",
  ui_story_10_15_1_29_dialog_content = "卡蓮先拉開距離……繞到左後方攻擊！",
  ui_story_10_15_1_30_dialog_content = "速射感知！",
  ui_story_10_15_1_31_dialog_content = "收到！",
  ui_story_10_15_1_32_dialog_content = "嘎！",
  ui_story_10_15_1_33_dialog_content = "終於像點樣子了！",
  ui_story_10_15_1_34_dialog_content = "抱歉……我剛才……因為被舒默死前的情緒影響，有點精神恍惚……",
  ui_story_10_15_1_35_dialog_content = "無需道歉，但你還是趕緊恢復成平常的樣子比較好。",
  ui_story_10_15_1_36_dialog_content = "畢竟，這一切都還沒有結束。",
  ui_story_10_15_1_37_dialog_content = "我還要回白夜城復命，你還要去修復你的臨空者號。",
  ui_story_10_15_1_38_dialog_content = "我們要擊敗這群暗鬼，然後活著回去！",
  ui_story_10_15_1_39_dialog_content = "嗯，你說得對。",
  ui_story_10_15_1_40_dialog_content = "我已經振作起來了……我現在能夠支援大家戰鬥！",
  ui_story_10_15_1_41_dialog_content = "那個……PlayerName你恢復了平時樣子是很好啦！",
  ui_story_10_15_1_42_dialog_content = "可這暗鬼……",
  ui_story_10_15_1_43_dialog_content = "吼——！",
  ui_story_10_15_1_44_dialog_content = "雖然我想說大不了就是一死。",
  ui_story_10_15_1_45_dialog_content = "但不好意思，我妹妹還在等著我回去！",
  ui_story_10_15_1_46_dialog_content = "<size=45>所有人，現在開始拼死戰鬥！但是不准死！！</size>",
  ui_story_10_15_1_47_dialog_content = "醒山，你聲音太大了……發號施令還輪不到你！",
  ui_story_10_15_1_48_dialog_content = "咕……",
  ui_story_10_15_1_49_dialog_content = "嘎！",
  ui_story_10_15_1_50_dialog_content = "都給我過來吧！",
  ui_story_10_15_1_51_dialog_content = "暗鬼被吸走了？！",
  ui_story_10_15_1_52_dialog_content = "老老實實地倒下！",
  ui_story_10_15_1_53_dialog_content = "嘎！",
  ui_story_10_15_1_54_dialog_content = "醒山！你黑潮大爺我來救你啦！",
  ui_story_10_15_1_55_dialog_content = "哈哈哈！沒想到你也有這一天啊！哈哈哈！",
  ui_story_10_15_1_56_dialog_content = "小心爆炸！",
  ui_story_10_15_1_57_dialog_content = "哇？！",
  ui_story_10_15_1_58_dialog_content = "有沒有搞錯，差點炸到我了喂！",
  ui_story_10_15_1_59_dialog_content = "誰叫你把暗鬼引過來又不好好打死！",
  ui_story_10_15_1_60_dialog_content = "怎麼了？",
  ui_story_10_15_1_61_dialog_content = "哈哈……",
  ui_story_10_15_1_62_dialog_content = "不好意思，我紅油扳手的傢伙們來幫忙了……",
  ui_story_10_15_1_63_dialog_content = "他們的火力不錯，就是稍微有點吵。",
  ui_story_10_15_1_64_dialog_content = "嗚……得救啦！太好啦！",
  ui_story_10_15_1_65_dialog_content = "嗯……太好了……",
  ui_story_10_15_1_66_dialog_content = "嗨呀，這一戰打得……累死我了。這麼多暗鬼。",
  ui_story_10_15_1_67_dialog_content = "醒山你知道我們怎麼來的嗎？我跟你說，剛才那山一震，我就……",
  ui_story_10_15_1_68_dialog_content = "老大！你沒事吧！",
  ui_story_10_15_1_69_dialog_content = "還行，這傷問題不大……",
  ui_story_10_15_1_70_dialog_content = "喔喔喔，這巨像，真是不錯！",
  ui_story_10_15_1_71_dialog_content = "能把這玩意拉回去，這趟可就沒白來了！",
  ui_story_10_15_1_72_dialog_content = "快都給我過來幫忙！拆了帶走！",
  ui_story_10_15_1_73_dialog_content = "等一下！",
  ui_story_10_15_1_74_dialog_content = "是白夜城的人？",
  ui_story_10_15_1_75_dialog_content = "歐緹，剛沒來得及介紹……",
  ui_story_10_15_1_76_dialog_content = "這是來自白夜城的卡蓮，那兩位是薇絲和PlayerName。",
  ui_story_10_15_1_77_dialog_content = "等等等……老大，這個白夜城的卡蓮不就是……那個衛隊長嗎？",
  ui_story_10_15_1_78_dialog_content = "黑潮你少說兩句！",
  ui_story_10_15_1_79_dialog_content = "今天在這個地方，大家都是一同戰鬥的夥伴。",
  ui_story_10_15_1_80_dialog_content = "你說對吧，卡蓮？",
  ui_story_10_15_1_81_dialog_content = "……",
  ui_story_10_15_1_82_dialog_content = "好吧，那他們也想要這座巨像？",
  ui_story_10_15_1_83_dialog_content = "總得考慮一下誰出的力多，再討論怎麼分吧？",
  ui_story_10_15_1_84_dialog_content = "今天這事直接聽我的，你們誰都不要多說。",
  ui_story_10_15_1_85_dialog_content = "有什麼疑問等回了基地我再跟你們解釋。",
  ui_story_10_15_1_86_dialog_content = "PlayerName！",
  ui_story_10_15_1_87_dialog_content = "你要不要這座黑色巨像？要的話我們直接幫你拖回去！",
  ui_story_10_15_1_88_dialog_content = "欸？",
  ui_story_10_15_1_89_dialog_content = "你不會還沒緩過神來吧？振作一點。",
  ui_story_10_15_1_90_dialog_content = "我沒事……我已經振作起來了。",
  ui_story_10_15_1_91_dialog_content = "那就好。",
  ui_story_10_15_1_92_dialog_content = "我是覺得，這東西應該屬於你……這是屬於你們空裔的巨像。",
  ui_story_10_15_1_93_dialog_content = "不過我有一個建議……",
  ui_story_10_15_1_94_dialog_content = "什麼建議？",
  ui_story_10_15_1_95_dialog_content = "我建議你直接加入我們，這樣我們就能名正言順地把它拖回基地了。",
  ui_story_10_15_1_96_dialog_content = "我……",
  ui_story_10_15_1_97_dialog_content = "你先別急著回答，我就是提議一下。",
  ui_story_10_15_1_98_dialog_content = "如果你想來紅油扳手，我隨時歡迎。",
  ui_story_10_15_1_99_dialog_content = "謝謝。",
  ui_story_10_15_1_100_dialog_content = "但我只需要拿三個組件就行了。",
  ui_story_10_15_1_101_dialog_content = "吞噬者號……随便你們處置吧。",
  ui_story_10_15_1_102_dialog_content = "行，那另外兩個人呢？你們現在怎麼想的？",
  ui_story_10_15_1_103_dialog_content = "如果啟光和白夜城對這座巨像有興趣，不能就這麼讓我們拖走吧？",
  ui_story_10_15_1_104_dialog_content = "既然PlayerName都這麼說，我沒理由阻止你們喔。",
  ui_story_10_15_1_105_dialog_content = "不需要。",
  ui_story_10_15_1_106_dialog_content = "嗯，況且最初遇到你們的時候，我已經知道你們是為巨像來的了。",
  ui_story_10_15_1_107_dialog_content = "也已經想好了，不會跟你們爭這座吞噬者號。",
  ui_story_10_15_1_108_dialog_content = "好，夠義氣。",
  ui_story_10_15_1_109_dialog_content = "這也不算什麼義氣吧……我只是對它沒興趣。",
  ui_story_10_15_1_110_dialog_content = "PlayerName。",
  ui_story_10_15_1_111_dialog_content = "我知道你剛剛經歷了那些事情，心情複雜。",
  ui_story_10_15_1_112_dialog_content = "但我希望你不要想太多，你已經做得夠好了！",
  ui_story_10_15_1_113_dialog_content = "如果你想回歸平靜的生活，沒有人能指責你！",
  ui_story_10_15_1_114_dialog_content = "醒山……",
  ui_story_10_15_1_115_dialog_content = "謝謝你。",
  ui_story_10_15_1_116_dialog_content = "我剛來……我聽到了什麼？",
  ui_story_10_15_1_117_dialog_content = "我只是隨口鼓勵他一下而已！幹嘛一臉這種表情？！",
  ui_story_10_15_1_118_dialog_content = "不說了不說了，該幹嘛幹嘛去！",
  ui_story_10_15_1_119_dialog_content = "嘶……該休息的休息，該幹活的幹活！",
  ui_story_10_15_1_120_dialog_content = "動起來！",
  ui_story_10_15_1_121_dialog_content = "聽我數到三就開始拖！",
  ui_story_10_15_1_122_dialog_content = "嗯——！",
  ui_story_10_15_1_123_dialog_content = "黑潮！你一個人在那使勁有什麼用？！",
  ui_story_10_15_1_124_dialog_content = "我這是提前熱身！",
  ui_story_10_15_1_125_dialog_content = "難道你以為我是聽你說「開始」就聽話地開始嗎？！",
  ui_story_10_15_1_126_dialog_content = "能拖走就奇怪了！沒看見這巨像這麼大個嗎？！",
  ui_story_10_15_1_127_dialog_content = "要不然還是……把有用的零件拆下來帶走吧……",
  ui_story_10_15_1_128_dialog_content = "我同意。",
  ui_story_10_15_1_129_dialog_content = "叭噗，我想先回臨空者號了，妳們還需要幫忙嗎？",
  ui_story_10_15_1_130_dialog_content = "沒關係，不用了。",
  ui_story_10_15_1_131_dialog_content = "我們會自己想辦法的，不用管我們。",
  ui_story_10_15_1_132_dialog_content = "你們快回巨像上休息吧，記得先檢查一下傷勢。",
  ui_story_10_15_1_133_dialog_content = "不會忘記的啦，畢竟還是很痛。",
  ui_story_10_15_1_134_dialog_content = "我們還想跟醒山道個別，他人呢？",
  ui_story_10_15_1_135_dialog_content = "哎呀……這個……他剛才說，要你們走的時候不用跟他告別的說。",
  ui_story_10_15_1_136_dialog_content = "好吧……",
  ui_story_10_15_1_137_dialog_content = "那我們真的走了喔？再見……",
  ui_story_10_15_1_138_dialog_content = "嗯，再見……",
  ui_story_10_15_1_139_dialog_content = "一定要保重呀！下次再見！",
  ui_story_10_15_1_140_dialog_content = "嗯，下次再見……",
  ui_story_10_15_1_141_dialog_content = "我是怎麼走到今天這一步的？",
  ui_story_10_15_1_142_dialog_content = "最初是因為……那個夢？",
  ui_story_10_15_1_143_dialog_content = "「活下去。」",
  ui_story_10_15_1_144_dialog_content = "……你又作<color=#FFB400>那個夢</color>了嗎？",
  ui_story_10_15_1_145_dialog_content = "嗯。",
  ui_story_10_15_1_146_dialog_content = "夢境是心智對未知與渴望的具象化所帶來的幻象。",
  ui_story_10_15_1_147_dialog_content = "然後……孟德爾頌死了……",
  ui_story_10_15_1_148_dialog_content = "為了生存……十七年前的那天，我為了活下去，接受<color=#FFB400>暗鬼的力量</color>……",
  ui_story_10_15_1_149_dialog_content = "好想再看一眼……天空……",
  ui_story_10_15_1_150_dialog_content = "我順利地見證了舒默的死亡……",
  ui_story_10_15_1_151_dialog_content = "（我詛咒你……）",
  ui_story_10_15_1_152_dialog_content = "（PlayerName……）",
  ui_story_10_15_1_153_dialog_content = "根本就不是幻象……這一切都是真的……",
  ui_story_10_15_1_154_dialog_content = "臨空者老師……",
  ui_story_10_15_1_155_dialog_content = "我拿到了智庫組件，但我其實不知道……你有沒有能連上這種組件的系統。",
  ui_story_10_15_1_156_dialog_content = "畢竟你是第六級巨像這件事，都是別人告訴我的……",
  ui_story_10_15_1_E1_dialog_content = "……",
  ui_story_10_15_1_E2_dialog_content = "還是等你「回來」了，再跟你抱怨這些吧。",
  ui_story_10_15_1_157_dialog_content = "智庫組件上的三個連接口……",
  ui_story_10_15_1_158_dialog_content = "好像都是一樣的。",
  ui_story_10_15_1_159_dialog_content = "……",
  ui_story_10_15_1_160_dialog_content = "<color=#e8d9bb>「主控系統自動檢查……無異常。」</color>",
  ui_story_10_15_1_161_dialog_content = "<color=#e8d9bb>「生物模組自動檢查……休眠中。」</color>",
  ui_story_10_15_1_162_dialog_content = "<color=#e8d9bb>「維生系統自動檢查……運行中。目前乘載：一人。」</color>",
  ui_story_10_15_1_163_dialog_content = "<color=#e8d9bb>引擎確認……無異常。</color>",
  ui_story_10_15_1_164_dialog_content = "<color=#e8d9bb>智庫組件……連線中</color>",
  ui_story_10_15_1_165_dialog_content = "<color=#e8d9bb>1%……3%……8%……</color>",
  ui_story_10_15_1_166_dialog_content = "結果……",
  ui_story_10_15_1_167_dialog_content = "就這麼結束了。",
  ui_story_10_15_1_168_dialog_content = "舒默連全屍都沒剩下。",
  ui_story_10_15_1_169_dialog_content = "是啊……PlayerName甚至都不願意去看一眼。",
  ui_story_10_15_1_170_dialog_content = "我想他應該早就藉由感應能力確認了舒默的生死……",
  ui_story_10_15_1_171_dialog_content = "既然已經死了，就沒必要再去在意了。",
  ui_story_10_15_1_172_dialog_content = "可是……真的能不在意嗎？",
  ui_story_10_15_1_173_dialog_content = "雖然舒默已經死了，但毀滅空谷的暗鬼……",
  ui_story_10_15_1_174_dialog_content = "無處不在。",
  ui_story_10_15_1_175_dialog_content = "而且還有PlayerName提到的那個<color=#FFB400>「斐桀洛」</color>。",
  ui_story_10_15_1_176_dialog_content = "但他直到最後，都沒問出那個「斐桀洛」到底是誰。",
  ui_story_10_15_1_177_dialog_content = "……那短短十幾分鐘裡，發生了太多事了。",
  ui_story_10_15_1_178_dialog_content = "或許只是來沒來得及問……",
  ui_story_10_15_1_179_dialog_content = "他自從目睹了舒默的死狀後，就好像失了神一樣。",
  ui_story_10_15_1_180_dialog_content = "雖然他很快就恢復了過來，但我總覺得哪裡不太對勁。",
  ui_story_10_15_1_181_dialog_content = "或許他只是不想讓我們擔心，所以才變回了平常的樣子。",
  ui_story_10_15_1_182_dialog_content = "又或許，他很清楚現在還有更重要的事……",
  ui_story_10_15_1_183_dialog_content = "總之，如果還有需要我們幫忙的地方，我相信他會說出來的。",
  ui_story_10_15_1_184_dialog_content = "嗯，說得也是。",
  ui_story_10_15_1_185_dialog_content = "不過，PlayerName已經進去臨空者號這麼久了……都還沒出來。",
  ui_story_10_15_1_186_dialog_content = "我有點擔心……",
  ui_story_10_15_1_187_dialog_content = "他提出帶著組件單獨進去，一定有他自己的考慮。",
  ui_story_10_15_1_188_dialog_content = "還是再等等吧……",
  ui_story_10_15_1_189_dialog_content = "嗯……",
  ui_story_10_15_1_190_dialog_content = "<color=#e8d9bb>「10%……23%……」</color>",
  ui_story_10_15_1_191_dialog_content = "<color=#e8d9bb>「33%……35%……」</color>",
  ui_story_10_15_1_192_dialog_content = "<color=#e8d9bb>「連結失敗。累積失敗次數：一次。」</color>",
  ui_story_10_15_1_193_dialog_content = "沒關係，再來一次……重試……",
  ui_story_10_15_1_194_dialog_content = "連線至智庫組件……",
  ui_story_10_15_1_195_dialog_content = "<color=#e8d9bb>智庫組件……連線中</color>",
  ui_story_10_15_1_196_dialog_content = "<color=#e8d9bb>「1%……3%……8%……」</color>",
  ui_story_10_15_1_197_dialog_content = "<color=#e8d9bb>「61%……67%……」</color>",
  ui_story_10_15_1_198_dialog_content = "<color=#e8d9bb>「76%……85%……」</color>",
  ui_story_10_15_1_199_dialog_content = "<color=#e8d9bb>「連結失敗。累積失敗次數：兩次。」</color>",
  ui_story_10_15_1_200_dialog_content = "不過是兩次失敗而已……想想我們最開始啟動引擎的時候。",
  ui_story_10_15_1_201_dialog_content = "那可是失敗了三千多次。",
  ui_story_10_15_1_202_dialog_content = "沒關係……",
  ui_story_10_15_1_203_dialog_content = "重試，再來一次。",
  ui_story_10_15_1_204_dialog_content = "從最開始的步驟重新開始。",
  ui_story_10_15_1_205_dialog_content = "<color=#e8d9bb>「主控系統自動檢查……無異常。」</color>",
  ui_story_10_15_1_206_dialog_content = "<color=#e8d9bb>「生物模組自動檢查……休眠中。」</color>",
  ui_story_10_15_1_207_dialog_content = "<color=#e8d9bb>「正在檢測意識模組……已損壞。」</color>",
  ui_story_10_15_1_208_dialog_content = "<color=#e8d9bb>「維生系統自動檢查……運行中。目前乘載：一人。」</color>",
  ui_story_10_15_1_209_dialog_content = "<color=#e8d9bb>引擎確認……無異常。</color>",
  ui_story_10_15_1_210_dialog_content = "<color=#e8d9bb>智庫組件……連線中</color>",
  ui_story_10_15_1_211_dialog_content = "<color=#e8d9bb>「1%……3%……8%……」</color>",
  ui_story_10_15_1_212_dialog_content = "<color=#e8d9bb>「10%……25%……」</color>",
  ui_story_10_15_1_213_dialog_content = "……",
  ui_story_10_15_1_214_dialog_content = "……",
  ui_story_10_15_1_215_dialog_content = "不行，我們還是進去看看吧！",
  ui_story_10_15_1_216_dialog_content = "哪怕問一下情況也好！",
  ui_story_10_15_1_217_dialog_content = "薇絲……這樣可能會妨礙到他。",
  ui_story_10_15_1_218_dialog_content = "我知道……可是……",
  ui_story_10_15_1_219_dialog_content = "如果智庫組件沒辦法連線到巨像上……",
  ui_story_10_15_1_220_dialog_content = "如果根本就找不到……修復臨空者號的方法……",
  ui_story_10_15_1_221_dialog_content = "我不希望他……單獨承受這些。",
  ui_story_10_15_1_222_dialog_content = "我就去確認一下情況！一定會注意，絕不妨礙他！",
  ui_story_10_15_1_223_dialog_content = "唉……你啊。",
  ui_story_10_15_1_224_dialog_content = "這麼擔心，不如站在門口喊他的名字吧。",
  ui_story_10_15_1_225_dialog_content = "他身為空裔，有那麼靈敏的感官和感應能力……",
  ui_story_10_15_1_226_dialog_content = "一定能聽到的。",
  ui_story_10_15_1_227_dialog_content = "這樣就不算破壞讓他單獨進去的約定了。",
  ui_story_10_15_1_228_dialog_content = "有道理！我馬上去喊！",
  ui_story_10_15_1_229_dialog_content = "不愧是卡蓮，能想出這種方法。",
  ui_story_10_15_1_230_dialog_content = "能想出這種方法……我也是跟你學的啊……",
  ui_story_10_15_1_231_dialog_content = "呼……",
  ui_story_10_15_1_232_dialog_content = "PlayerName！",
  ui_story_10_15_1_233_dialog_content = "<color=#e8d9bb>「89%……97%……」</color>",
  ui_story_10_15_1_234_dialog_content = "<color=#e8d9bb>「100%，連結成功。」</color>",
  ui_story_10_15_1_235_dialog_content = "<color=#e8d9bb>「歡迎使用智庫組件。」</color>",
  ui_story_10_15_1_236_dialog_content = "薇絲！卡蓮！",
  ui_story_10_15_1_237_dialog_content = "智庫組件連結成功了！找到修復意識模組的辦法了！",
  ui_story_10_15_1_238_dialog_content = "臨空者號有救了！",
  ui_story_10_15_1_239_dialog_content = "你是說……",
  ui_story_10_15_1_240_dialog_content = "那個叫PlayerName的空裔打败了……那個……叫舒默的空裔叛徒。",
  ui_story_10_15_1_241_dialog_content = "然後讓紅油扳手的人接手了黑色巨像。",
  ui_story_10_15_1_242_dialog_content = "吞羅不僅沒有阻止他們，甚至還幫了他們一把？",
  ui_story_10_15_1_243_dialog_content = "是的。",
  ui_story_10_15_1_244_dialog_content = "那個空裔會不會影響我們的計畫？",
  ui_story_10_15_1_245_dialog_content = "不會，他只會讓事情更有趣。",
  ui_story_10_15_1_246_dialog_content = "舒瓦茲肯定也是這麼想的。",
  ui_story_70000101_1_dialog_content = "<color=#e8d9bb>「運行自檢功能。」</color>",
  ui_story_70000101_2_dialog_content = "<color=#e8d9bb>「主控系統自檢......運行中。零件損耗率39%，需要維護。」</color>",
  ui_story_70000101_3_dialog_content = "<color=#e8d9bb>「生物模組自檢......運行中。零件損耗率46%，需要維護。」</color>",
  ui_story_70000101_4_dialog_content = "<color=#e8d9bb>「維生系統自檢......運行中。警告：目前負荷已滿，需要維護。」</color>",
  ui_story_70000101_5_dialog_content = "<color=#e8d9bb>「維護功能自檢......無異常。正在啟動......」</color>",
  ui_story_70000101_6_dialog_content = "<color=#e8d9bb>「錯誤：意識模組缺失，維護功能無法運行。」</color>",
  ui_story_70000101_7_dialog_content = "<color=#e8d9bb>「啟動失敗。累積失敗次數：1012次。」</color>",
  ui_story_70000101_8_dialog_content = "<color=#e8d9bb>「請安裝意識模組以使用維護功能。」</color>",
  ui_story_70000101_9_dialog_content = "<color=#e8d9bb>「警告：若零件損耗率超過50%，對應功能將無法正常啟用。」</color>",
  ui_story_70000101_10_dialog_content = "<color=#e8d9bb>「請簽名確認。」</color>",
  ui_story_70000101_11_dialog_content = "臨空者號……",
  ui_story_70000101_12_dialog_content = "PlayerName，臨空者號的情況怎麼樣了？",
  ui_story_70000101_13_dialog_content = "……",
  ui_story_70000101_14_dialog_content = "還是一樣。缺少意識模組，沒辦法自行維護，情況已經很緊急了。",
  ui_story_70000101_15_dialog_content = "我當初就該第一時間修復臨空者號，不該被其他事情牽著走。",
  ui_story_70000101_16_dialog_content = "也不能完全怪你，跟臨空者號相處這麼久卻沒發現牠的異常，我也有同樣的責任。",
  ui_story_70000101_17_dialog_content = "你也不要太過擔心，畢竟已經找到了解決方案嘛！",
  ui_story_70000101_18_dialog_content = "我找到線索了！",
  ui_story_70000101_19_dialog_content = "「智庫組件」給出了一個座標，但......這是哪裡？",
  ui_story_70000101_20_dialog_content = "我能看看嗎？",
  ui_story_70000101_21_dialog_content = "這個座標已經到<color=#FFB400>「暗面」</color>了？！",
  ui_story_70000101_22_dialog_content = "如果我沒記錯，這裡應該是......<color=#FFB400>「80號地下城」</color>？",
  ui_story_70000101_23_option_content = "暗面......？",
  ui_story_70000101_24_option_content = "80號地下城......？",
  ui_story_70000101_25_dialog_content = "「暗面」是對永夜附近區域的統稱。",
  ui_story_70000101_26_dialog_content = "「80號地下城」則是這座標指向的位置。",
  ui_story_70000101_27_dialog_content = "暗面是非常危險的地方。",
  ui_story_70000101_28_dialog_content = "那裡白晝短暫，夜晚漫長，並且據說有大量的暗鬼聚集。",
  ui_story_70000101_29_dialog_content = "喂，PlayerName在嗎？",
  ui_story_70000101_30_dialog_content = "欸？涉發來的通訊......？",
  ui_story_70000101_31_dialog_content = "我聽說你們正在調查「暗面」，正好我手上有一些線索。",
  ui_story_70000101_32_dialog_content = "咦？妳是怎麼知道的？！",
  ui_story_70000101_33_dialog_content = "影鎮的商人可不會錯過任何商機。",
  ui_story_70000101_34_dialog_content = "好吧，我知道了，大概是什麼「特殊的情報網」，對吧？",
  ui_story_70000101_35_dialog_content = "真有默契，不愧是我的老主顧。",
  ui_story_70000101_X35_dialog_content = "我不介意給你一個免費的忠告——",
  ui_story_70000101_36_dialog_content = "你手中座標所在的那片區域相當危險，甚至被稱為<color=#FFB400>「泥潭」</color>呢。",
  ui_story_70000101_37_dialog_content = "......就算危險，我也要去。",
  ui_story_70000101_38_dialog_content = "智庫組件給出的唯一線索指向那裡，我不可能放著拯救臨空者號的機會不管。",
  ui_story_70000101_39_dialog_content = "PlayerName，別被一時的衝動沖昏頭腦。",
  ui_story_70000101_40_dialog_content = "在沒有任何準備和情報的情況下進入「泥潭」，是不明智的。",
  ui_story_70000101_41_dialog_content = "……",
  ui_story_70000101_42_dialog_content = "沒錯，這也是我的建議喔。",
  ui_story_70000101_43_dialog_content = "不過，如果你願意付出一些小小的「代價」，我也樂意為你尋找相應的情報......",
  ui_story_70000101_44_dialog_content = "呃......難道，又是白夜幣？",
  ui_story_70000101_45_dialog_content = "白夜城中應該也對那片區域有相應的記載。",
  ui_story_70000101_46_dialog_content = "我可以去幫忙找找。",
  ui_story_70000101_47_dialog_content = "那就拜託了，請幫幫我。",
  ui_story_70000101_48_dialog_content = "我又檢查了一遍臨空者號的情況，目前還能維持正常運行，暫時不需要擔心。",
  ui_story_70000101_49_dialog_content = "嗯，過了這麼久，卡蓮和涉應該也快找到情報了。",
  ui_story_70000101_50_dialog_content = "我也拜託了啟光的同伴幫忙尋找線索，你就放心吧。",
  ui_story_70000101_51_dialog_content = "希望她們能找到有用的線索，畢竟......",
  ui_story_70000101_52_dialog_content = "這是拯救臨空者號唯一的希望了。",
  ui_story_70000101_53_dialog_content = "如果這個座標是準確的，那我們恐怕要搜尋一整座地下城。",
  ui_story_70000101_54_dialog_content = "就算是最小型的地下城，搜尋起來也要花上幾天時間。",
  ui_story_70000101_55_dialog_content = "就不能確定具體位置嗎？",
  ui_story_70000101_56_dialog_content = "不行，現在只有大致方向。",
  ui_story_70000101_57_dialog_content = "如果接近目標的話，說不定可以。",
  ui_story_70000101_58_dialog_content = "喂，PlayerName。聽得到嗎？",
  ui_story_70000101_59_dialog_content = "卡蓮！我能聽見！",
  ui_story_70000101_60_dialog_content = "好，我現在在黎明學院的圖書館，這裡通訊信號不太好，我長話短說。",
  ui_story_70000101_61_dialog_content = "圖書館裡有一些記載著「80號地下城」的戰爭記錄。",
  ui_story_70000101_62_dialog_content = "根據記錄，「80號地下城」曾經是啟光的前哨基地和運輸中轉站。",
  ui_story_70000101_63_dialog_content = "這座地下城靠近永夜，一度是啟光聯邦對抗暗鬼的最前沿。",
  ui_story_70000101_64_dialog_content = "但是，在<color=#FFB400>「暗面戰爭」</color>時，暗鬼攻勢兇猛，加之距離其他地下城路途遙遠、缺乏補給......",
  ui_story_70000101_65_dialog_content = "啟光的軍隊很快放棄了這座地下城，匆匆撤出。",
  ui_story_70000101_66_option_content = "「暗面戰爭」？",
  ui_story_70000101_67_dialog_content = "我聽說過那場戰爭，似乎是二十多年前開始的暗鬼大規模進攻事件。",
  ui_story_70000101_68_dialog_content = "大量暗鬼從永夜區域襲來，戰鬥......非常慘烈。",
  ui_story_70000101_69_dialog_content = "啟光聯邦最後雖然取勝，但也付出了數座地下城和無數軍人生命的高昂代價。",
  ui_story_70000101_70_dialog_content = "書上也是這麼寫的。",
  ui_story_70000101_71_dialog_content = "上面說，啟光撤軍的時候有許多設備沒能帶走，你要找的東西應該也在其中。",
  ui_story_70000101_72_dialog_content = "好的，我知道了。謝謝！",
  ui_story_70000101_73_dialog_content = "不必客氣。舉手之勞而已。",
  ui_story_70000101_X74_dialog_content = "<color=#e8d9bb>嗚——嗚——</color>",
  ui_story_70000101_75_dialog_content = "又有通信請求？喂？妳好？",
  ui_story_70000101_76_dialog_content = "PlayerName，是我。",
  ui_story_70000101_77_dialog_content = "涉，原來是妳！怎麼樣，有什麼情報嗎？",
  ui_story_70000101_X77_dialog_content = "情報我已經拿到了，不過......算不上樂觀。",
  ui_story_70000101_78_dialog_content = "我的情報商說，那邊是個暗鬼成群的地方。",
  ui_story_70000101_79_dialog_content = "如果沒有臨空者號，你恐怕連「泥潭」的邊緣都無法接近。",
  ui_story_70000101_80_dialog_content = "至於那座地下城裡，除了廢墟和戰鬥的痕跡外，也是一無所有。",
  ui_story_70000101_81_dialog_content = "能源核心雖然維持著運作，但狀態非常糟糕，不足以支撐防禦系統，並且隨時會停止運行。",
  ui_story_70000101_82_dialog_content = "只有一個從那裡活著逃回來的倒楣蛋說，地下城中唯一的通路——",
  ui_story_70000101_83_dialog_content = "是塌陷產生的<color=#FFB400>一條裂縫</color>。",
  ui_story_70000101_84_dialog_content = "是這樣嗎……",
  ui_story_70000101_85_dialog_content = "我知道了。",
  ui_story_70000101_86_dialog_content = "祝你們好運。",
  ui_story_70000101_87_dialog_content = "可要活著回來，付清尾款啊。",
  ui_story_70000101_88_dialog_content = "好......好的……",
  ui_story_70000101_89_dialog_content = "奇怪，菲莉詩長官還沒有查到情報嗎......？",
  ui_story_70000101_90_dialog_content = "<color=#e8d9bb>滴滴滴——</color>",
  ui_story_70000101_91_dialog_content = "咦？菲莉詩長官傳來了一份文件。",
  ui_story_70000101_92_dialog_content = "是什麼？我看看。",
  ui_story_70000101_93_dialog_content = "<color=#FFB400>「暗面作戰指導手冊」？</color>",
  ui_story_70000101_94_option_content = "你們還有這種手冊？",
  ui_story_70000101_95_dialog_content = "我印象裡似乎沒有這種東西......",
  ui_story_70000101_96_dialog_content = "它看起來太簡略了。",
  ui_story_70000101_97_dialog_content = "沒有目錄，格式也不規範。",
  ui_story_70000101_98_dialog_content = "根本不像是正規的作戰手冊。",
  ui_story_70000101_99_dialog_content = "很可疑啊......",
  ui_story_70000101_100_dialog_content = "菲莉詩長官應該不會提供錯誤情報。",
  ui_story_70000101_101_option_content = "菲莉詩竟然願意幫忙？",
  ui_story_70000101_102_dialog_content = "不像是平時的她啊。",
  ui_story_70000101_103_dialog_content = "重點不是這個，唉，不過告訴你也沒關係......",
  ui_story_70000101_104_dialog_content = "菲莉詩長官希望我幫她隱瞞上次翹班睡午覺的事情......",
  ui_story_70000101_105_dialog_content = "她答應用「80號地下城」的資料當做報酬。",
  ui_story_70000101_106_dialog_content = "果然這才是她的風格......",
  ui_story_70000101_107_dialog_content = "畢竟在情報方面的，菲莉詩長官是最可靠的。",
  ui_story_70000101_108_dialog_content = "但是......這份手冊看起來有些簡略？",
  ui_story_70000101_109_dialog_content = "裡面寫了什麼？",
  ui_story_70000101_110_dialog_content = "「暗面作戰指導手冊第一條——」",
  ui_story_70000101_111_dialog_content = "「如非必要，任何士兵應避免進入暗面區域作戰！！！」",
  ui_story_70000101_112_dialog_content = "咦？！",
  ui_story_70000101_113_dialog_content = "暗面......是那麼危險的地方嗎？",
  ui_story_70000101_114_dialog_content = "「根據已知情報，暗面為高度危險區域。」",
  ui_story_70000101_115_dialog_content = "「其中濃郁的暗能會導致光靈行動困難，這些暗能的影響會在夜晚加劇。」",
  ui_story_70000101_116_dialog_content = "「加之暗面暗鬼遍布，其中不乏極為強大的個體，非常危險！」",
  ui_story_70000101_117_dialog_content = "啟光士兵避免進入......會不會給妳造成麻煩？",
  ui_story_70000101_119_dialog_content = "我不能讓妳因為捲進這種事情而受罰。",
  ui_story_70000101_120_dialog_content = "或者，我現在去和緋求求情！",
  ui_story_70000101_121_dialog_content = "PlayerName......",
  ui_story_70000101_122_dialog_content = "我沒關係的。",
  ui_story_70000101_123_dialog_content = "臨空者號是PlayerName重要的家人，也是我重要的夥伴。",
  ui_story_70000101_124_dialog_content = "夥伴有難，我怎麼能不施以援手呢！",
  ui_story_70000101_125_dialog_content = "我現在已經是知情者了，知情不報在啟光的軍令裡等同於共犯。",
  ui_story_70000101_126_dialog_content = "這次行動只要別讓大元帥和軍團長們知道，應該就沒問題......",
  ui_story_70000101_127_dialog_content = "嗯，一定沒問題的！",
  ui_story_70000101_128_dialog_content = "抱歉，讓妳冒險了......",
  ui_story_70000101_129_dialog_content = "這份手冊中似乎詳細記載了暗面作戰的注意事項。",
  ui_story_70000101_130_dialog_content = "只是......它究竟是誰寫的呢？",
  ui_story_70000101_131_dialog_content = "這種事情以後再研究吧。",
  ui_story_70000101_132_dialog_content = "現在的當務之急是根據這些情報制定作戰計畫。",
  ui_story_70000101_133_dialog_content = "很多暗鬼，暗能的影響會在晚上加劇，還有夜長晝短的限制......",
  ui_story_70000101_134_dialog_content = "這會是相當困難的行動啊......",
  ui_story_70000101_135_dialog_content = "我們可以利用臨空者號的優勢，直接忽略半路上的暗鬼，飛往那裡。",
  ui_story_70000101_136_dialog_content = "進入地下城後，利用智庫組件的定位功能尋找目標。",
  ui_story_70000101_137_dialog_content = "儘量速戰速決，或許能趁白天完成行動......",
  ui_story_70000101_138_dialog_content = "風險也同樣高啊，萬一地下有高級暗鬼埋伏怎麼辦？",
  ui_story_70000101_139_dialog_content = "繞過去。我們的目標不是戰鬥，一旦找到組件，立刻撤離。",
  ui_story_70000101_140_dialog_content = "我明白了。",
  ui_story_70000101_141_dialog_content = "好，那就出發吧。目標，「80號地下城」！",
  ui_story_70000101_142_dialog_content = "<color=#e8d9bb>啟光安全線</color>",
  ui_story_70000101_143_dialog_content = "臨空者號即將越過安全線，正在向「80號地下城」的方向前進。",
  ui_story_70000101_144_dialog_content = "您......真的要放任他們行動嗎？",
  ui_story_70000101_145_dialog_content = "嗯？妳剛才叫我？",
  ui_story_70000101_146_dialog_content = "是......是的，您是大元帥......只有您能做決斷。",
  ui_story_70000101_147_dialog_content = "既然他們委託菲莉詩調查80號地下城這件事是妳發現的，那妳應該也知道他們的目的吧？",
  ui_story_70000101_148_dialog_content = "是的，PlayerName得到情報稱，80號地下城裡有能夠修復巨像意識模組的古代科技物品。",
  ui_story_70000101_149_dialog_content = "妳覺得他為什麼要找那東西？",
  ui_story_70000101_150_dialog_content = "因為......在之前對抗舒默和吞羅的戰鬥中，他的巨像——臨空者號被吞羅破壞了意識模組。",
  ui_story_70000101_151_dialog_content = "對於他來說，巨像就像是家人，而巨像失去意識模組，大概就像是人失去生命一樣。",
  ui_story_70000101_152_dialog_content = "那不就說得通了嗎？",
  ui_story_70000101_153_dialog_content = "我可沒有理由去阻止一個一心要拯救自己家人的人。",
  ui_story_70000101_154_dialog_content = "既然他並沒有惡意，那我認為稍微放任一下他們的行動也不是不可以。",
  ui_story_70000101_155_dialog_content = "就當是支付給他之前幫啟光對抗暗鬼的酬金。",
  ui_story_70000101_156_dialog_content = "該怎麼向委員會那邊解釋？他們一向反對任何人探索暗面區域，尤其是作為大元帥的您自己。",
  ui_story_70000101_157_dialog_content = "確實是個問題......",
  ui_story_70000101_158_dialog_content = "這樣告訴他們吧：空裔進入暗面區域是自主行為，我們試圖在半路攔截，但失敗了。",
  ui_story_70000101_159_dialog_content = "由於委員會的禁令，啟光軍隊並未直接進入暗面，而是選擇在安全線等候。",
  ui_story_70000101_160_dialog_content = "那位空裔並不是啟光人，並且他在各個勢力都有人脈。",
  ui_story_70000101_161_dialog_content = "僅憑這一點，委員會就不會特別為難他。",
  ui_story_70000101_162_dialog_content = "但是，大元帥，我還是認為那裡的危險性太高。",
  ui_story_70000101_163_dialog_content = "他們經歷過不少戰鬥，能力姑且可以相信。",
  ui_story_70000101_164_dialog_content = "只要謹慎一些，按照那份「指導手冊」去做，就不會有問題。",
  ui_story_70000101_165_dialog_content = "那您......為什麼還要守在這裡？",
  ui_story_70000101_166_dialog_content = "因為除了優秀的作戰能力，他們還需要一點別的東西，比如——",
  ui_story_70000101_167_dialog_content = "一根可以隨時把他們從「泥潭」裡拉出來的安全繩。",
  ui_story_70000101_168_dialog_content = "命令部隊保持警戒，隨時注意暗面方向的情況。",
  ui_story_70000101_169_dialog_content = "是，大元帥。",
  ui_story_70000101_170_dialog_content = "菲莉詩？",
  ui_story_70000101_171_dialog_content = "喵呀？！",
  ui_story_70000101_172_dialog_content = "妳的通訊終端，我先替妳保管一下。",
  ui_story_70000101_173_dialog_content = "至於妳翹班的事，等一切結束後再說。",
  ui_story_70000101_174_dialog_content = "是……",
  ui_story_70000101_175_dialog_content = "現在，去監視「80號地下城」方向的情況，如有異常，隨時向我報告。",
  ui_story_70000101_176_dialog_content = "是喵......",
  ui_story_70000101_177_dialog_content = "唉，薇絲，你們可惹上大麻煩了喵......",
  ui_story_70000101_178_dialog_content = "「80號地下城」......",
  ui_story_70000101_179_dialog_content = "那裡可不是隨便什麼人都能去的地方，這兩個傢伙膽子可真不小。",
  ui_story_70000201_1_dialog_content = "我們已經越過了啟光聯邦在永夜邊境設立的安全線。",
  ui_story_70000201_2_dialog_content = "再過一會就會到達80號地下城了。",
  ui_story_70000201_3_dialog_content = "天色明顯變暗了，這就是所謂的「暗面」嗎？",
  ui_story_70000201_4_dialog_content = "這種昏暗的環境真讓人不舒服，連呼吸都變得沉重了。",
  ui_story_70000201_5_dialog_content = "不知道會不會對戰鬥有影響......",
  ui_story_70000201_6_dialog_content = "指導手冊裡是怎麼寫的？",
  ui_story_70000201_7_dialog_content = "我看看……",
  ui_story_70000201_8_dialog_content = "「第3條：在「泥潭」作戰時，盡量避免戰鬥，量力而行。」",
  ui_story_70000201_9_dialog_content = "「80號地下城被稱為「泥潭」，因為那裡存在著壓得人無法呼吸的濃重暗能。」",
  ui_story_70000201_10_dialog_content = "「那些暗能甚至會阻礙通訊訊號，只要離開幾公尺遠，通訊器就無法正常工作。」",
  ui_story_70000201_11_dialog_content = "「並且，這些暗能帶來的負面影響會隨著時間推移不斷加劇。」",
  ui_story_70000201_12_dialog_content = "「夜間的負面影響會比白天嚴重兩倍以上。」",
  ui_story_70000201_13_dialog_content = "也就是說，普通的暗鬼都會變得極難對付。",
  ui_story_70000201_14_dialog_content = "看來我們必須儘量避免戰鬥。",
  ui_story_70000201_15_dialog_content = "嗯，而且有時間限制，一旦到了晚上，情況會變得更不利。",
  ui_story_70000201_16_dialog_content = "我們必須要依靠臨空者號的機動能力，趁著白天進入，速戰速決。",
  ui_story_70000201_17_dialog_content = "PlayerName......你好像變得更穩重了？",
  ui_story_70000201_18_dialog_content = "欸？是，是嗎？",
  ui_story_70000201_19_dialog_content = "說得我有點不好意思了......",
  ui_story_70000201_20_dialog_content = "不過，從剛才開始，我就在想一個問題。",
  ui_story_70000201_21_dialog_content = "這本手冊的編寫者對80號地下城的情況那麼熟悉，是不是曾經在那裡戰鬥過？",
  ui_story_70000201_22_dialog_content = "這就不得而知了......",
  ui_story_70000201_23_dialog_content = "這本手冊並不是用正規格式書寫的，甚至都沒有署名。",
  ui_story_70000201_24_dialog_content = "倒更像是哪個前線指揮官臨時寫給手下士兵的「注意事項」。",
  ui_story_70000201_25_dialog_content = "真奇怪......",
  ui_story_70000201_26_dialog_content = "不過，既然這是菲莉詩長官提供的資料，肯定真實可靠。",
  ui_story_70000201_27_dialog_content = "但願我們不會遇到最壞的情況。",
  ui_story_70000201_28_dialog_content = "PlayerName，快看外面！",
  ui_story_70000201_29_dialog_content = "那是80號地下城嗎？",
  ui_story_70000201_30_dialog_content = "就是這裡了嗎？",
  ui_story_70000201_31_dialog_content = "和我想像中的樣子完全不同......",
  ui_story_70000201_32_dialog_content = "印像中的啟光地下城有著堅實的銅牆鐵壁和森嚴羅列的大砲。",
  ui_story_70000201_33_dialog_content = "而這裡只剩下佈滿焦痕和彈孔的殘垣斷壁，以及棄置一地、無法使用的武器殘骸。",
  ui_story_70000201_34_dialog_content = "簡直就像常年被災難和戰火蹂躪一樣......",
  ui_story_70000201_35_dialog_content = "這裡......真的有我們要找的模組嗎？",
  ui_story_70000201_36_dialog_content = "畢竟那裡曾經發生過激烈的戰鬥，再加上廢棄多年......",
  ui_story_70000201_37_dialog_content = "現在恐怕已經變成暗鬼的老巢了......",
  ui_story_70000201_38_dialog_content = "我相信總有一天，啟光一定會回到這裡。",
  ui_story_70000201_39_dialog_content = "每一座地下城都意味著珍貴的能源、物資和科技。",
  ui_story_70000201_40_dialog_content = "啟光......絕對不會將它拱手讓給暗鬼。",
  ui_story_70000201_41_dialog_content = "……",
  ui_story_70000201_42_dialog_content = "地面上有很多暗鬼在徘徊，與牠們戰鬥會浪費很多時間。",
  ui_story_70000201_43_dialog_content = "找一個避人耳目的地方停靠吧，然後偷偷溜過去。",
  ui_story_70000201_44_dialog_content = "現在是黎明時分，我們還有足夠的時間行動！",
  ui_story_70000201_45_dialog_content = "<color=#e8d9bb>不久之後</color>",
  ui_story_70000201_46_dialog_content = "這就是......暗能的副作用嗎？",
  ui_story_70000201_47_dialog_content = "身體變得無比沉重，彷彿背著幾十斤的沙包......",
  ui_story_70000201_48_dialog_content = "我也是，只要走幾步就會變得氣喘吁吁......",
  ui_story_70000201_49_dialog_content = "這大概就是指導手冊上說的......暗面的負擔吧？",
  ui_story_70000201_50_dialog_content = "要在這種環境下戰鬥，簡直不可能......",
  ui_story_70000201_51_dialog_content = "先想辦法尋找入口吧。",
  ui_story_70000201_52_dialog_content = "坍塌成這個樣子，已經找不到地下城原本的入口了。",
  ui_story_70000201_53_dialog_content = "只有廢棄的鋼板上模糊的「80」字樣的白漆能夠證明這裡曾是啟光的地下城......",
  ui_story_70000201_54_dialog_content = "主結構斷裂，外側防壁完全坍塌，建築框架變形......",
  ui_story_70000201_55_dialog_content = "這裡至少發生過九級以上的地震，或者遭遇過菁英暗鬼持續二十四小時以上的進攻......",
  ui_story_70000201_56_dialog_content = "不然是無法把啟光地下城的防禦工事破壞成這樣的。",
  ui_story_70000201_57_dialog_content = "大門的情況呢？",
  ui_story_70000201_58_dialog_content = "完全被掩埋了。",
  ui_story_70000201_59_dialog_content = "至少視野內沒有發現可供接近地下區域的通路。",
  ui_story_70000201_60_dialog_content = "看來只能尋找涉說的<color=#FFB400>裂縫</color>。",
  ui_story_70000201_61_dialog_content = "吼——！",
  ui_story_70000201_62_dialog_content = "PlayerName，小心側面！",
  ui_story_70000201_63_dialog_content = "哪裡冒出來的暗鬼？！",
  ui_story_70000201_64_dialog_content = "暗鬼出現的方向，似乎有一條裂縫！",
  ui_story_70000201_65_dialog_content = "看來這場戰鬥避免不了了......",
  ui_story_70000201_66_dialog_content = "薇絲，按照手冊上寫的做，謹慎應對。",
  ui_story_70000201_67_dialog_content = "交給我吧！",
  ui_story_70000202_1_dialog_content = "呼……呼……",
  ui_story_70000202_2_dialog_content = "終於......結束了嗎？",
  ui_story_70000202_3_dialog_content = "頭......疼得像是要裂開一樣。",
  ui_story_70000202_4_dialog_content = "甚至連光的軌跡都要看不清了......",
  ui_story_70000202_5_dialog_content = "PlayerName？！",
  ui_story_70000202_6_dialog_content = "我沒事，只是......差點暈過去。",
  ui_story_70000202_7_dialog_content = "為了避免麻煩，還是低調行事吧。",
  ui_story_70000202_8_dialog_content = "沒想到這裡的環境竟然這麼艱難......",
  ui_story_70000202_9_dialog_content = "不能放棄，為了救臨空者號......",
  ui_story_70000202_10_dialog_content = "先來看看那條縫隙。",
  ui_story_70000202_11_dialog_content = "這......",
  ui_story_70000202_12_dialog_content = "這哪裡是縫隙啊。",
  ui_story_70000202_13_dialog_content = "這分明就是一道直上直下的懸崖！",
  ui_story_70000202_14_dialog_content = "下面勉強能看見有什麼東西在發光。",
  ui_story_70000202_15_dialog_content = "好像是機器的指示燈！",
  ui_story_70000202_16_dialog_content = "這座城市竟然還在運作嗎？！",
  ui_story_70000202_17_dialog_content = "那邊似乎有一條突出的管道可以落腳......",
  ui_story_70000202_18_dialog_content = "如果是這個高度，我可以帶著PlayerName降落到下面。",
  ui_story_70000202_19_dialog_content = "但是恐怕要另尋出路了。",
  ui_story_70000202_20_dialog_content = "出口的情報......手冊上有寫嗎？",
  ui_story_70000202_21_dialog_content = "好像有，我看看！",
  ui_story_70000202_22_dialog_content = "「80號地下城有一條從底部核心室通向地面的逃生通道。」",
  ui_story_70000202_23_dialog_content = "「但是，為了防止外敵由通道進入，這條通道只能由內側單向開啟。」",
  ui_story_70000202_24_dialog_content = "「通道入口非常隱祕，位於地下城能源核心旁的一道隱藏門內。」",
  ui_story_70000202_25_dialog_content = "「需以三輕三重再三輕的節奏，敲打核心室北牆，才能開啟隱藏門。」",
  ui_story_70000202_26_dialog_content = "竟然有連涉都不知道的細節？！",
  ui_story_70000202_27_dialog_content = "能對80號地下城了解得如此詳細，說不定它的編寫者曾經在這里工作或戰鬥過。",
  ui_story_70000202_28_dialog_content = "既然已經有了回到地面的方法，是時候行動了。",
  ui_story_70000202_29_dialog_content = "PlayerName，抓緊我。",
  ui_story_70000202_30_dialog_content = "我可以拒絕嗎，這種感覺簡直像是......",
  ui_story_70000202_31_dialog_content = "嘿！",
  ui_story_70000202_32_dialog_content = "<anim type=Shake>唔啊啊啊——！</anim>",
  ui_story_70000202_33_dialog_content = "簡直就像是——",
  ui_story_70000202_34_dialog_content = "PlayerName，小心咬到舌頭！",
  ui_story_70000202_35_dialog_content = "<size=45><anim type=Shake>啊啊啊——！</anim></size>",
  ui_story_70000202_36_dialog_content = "嘿呀！",
  ui_story_70000202_37_dialog_content = "<size=50><anim type=Shake>啊啊啊——！！！</anim></size>",
  ui_story_70000202_38_dialog_content = "......PlayerName，已經落地了喔？",
  ui_story_70000202_39_dialog_content = "啊......啊？是，是嗎？",
  ui_story_70000202_40_dialog_content = "你還好嗎？",
  ui_story_70000202_41_dialog_content = "已經......落地了嗎？",
  ui_story_70000202_42_dialog_content = "我的頭好暈......不行了......",
  ui_story_70000202_43_dialog_content = "欸？是我落地不穩的原因嗎？要不要休息一下？",
  ui_story_70000202_44_dialog_content = "讓我緩一緩就好......",
  ui_story_70000202_45_dialog_content = "附近情況怎麼樣？",
  ui_story_70000202_46_dialog_content = "暫時沒有發現暗鬼。",
  ui_story_70000202_47_dialog_content = "這附近......像是地下城的淺層。",
  ui_story_70000202_48_dialog_content = "到處都是廢墟和機器的殘骸，裡面似乎還夾雜著啟光制式裝備的碎片。",
  ui_story_70000202_49_dialog_content = "這牆上的標記是......<color=#FFB400>「第2號通風井」</color>？",
  ui_story_70000202_50_dialog_content = "看來確實是地下城內部沒錯了。",
  ui_story_70000202_51_dialog_content = "牆體上遍布彈孔，這裡一定經歷過慘烈的戰爭......",
  ui_story_70000202_52_dialog_content = "是「暗面戰爭」嗎？",
  ui_story_70000202_53_dialog_content = "地上遺落的彈殼型號符合舊時啟光制式裝備，就這一點來看，恐怕是的。",
  ui_story_70000202_54_dialog_content = "難怪寫下這本指導手冊的人不希望有人重回這裡。",
  ui_story_70000202_55_dialog_content = "這裡簡直就是......吞噬生命的泥潭。",
  ui_story_70000202_56_dialog_content = "……",
  ui_story_70000202_57_option_content = "（觸摸彈孔）",
  ui_story_70000202_58_option_content = "（撿起彈殼）",
  ui_story_70000202_59_dialog_content = "別，別過來！",
  ui_story_70000202_60_dialog_content = "吼——！",
  ui_story_70000202_61_dialog_content = "救......救我......",
  ui_story_70000202_62_dialog_content = "噫——！",
  ui_story_70000202_63_dialog_content = "求求你別吃我，我不好吃！",
  ui_story_70000202_64_dialog_content = "吼！ ！ ！",
  ui_story_70000202_65_dialog_content = "啊......媽，媽媽......",
  ui_story_70000202_66_dialog_content = "我......回不去了......",
  ui_story_70000202_67_dialog_content = "……",
  ui_story_70000202_68_dialog_content = "PlayerName......你看到那些了吧？",
  ui_story_70000202_69_dialog_content = "嗯……",
  ui_story_70000202_70_dialog_content = "那些事情......我們也無能為力，不要難過了。",
  ui_story_70000202_71_dialog_content = "再看看目標的位置吧？",
  ui_story_70000202_72_dialog_content = "好，我感應一下。",
  ui_story_70000202_73_option_content = "建立感應！",
  ui_story_70000202_74_dialog_content = "......！",
  ui_story_70000202_75_dialog_content = "我們要找的東西還在下面。",
  ui_story_70000202_76_dialog_content = "干擾非常嚴重，只能感應到大概方向。",
  ui_story_70000202_77_dialog_content = "在那邊！",
  ui_story_70000202_78_dialog_content = "又是一個斷崖......",
  ui_story_70000202_79_dialog_content = "這個看起來比上一個更深，而且沒有落腳點......",
  ui_story_70000202_80_dialog_content = "如果直接跳下去的話，會引起很大的動靜。",
  ui_story_70000202_81_dialog_content = "說不定四周的暗鬼都會向我們湧過來。",
  ui_story_70000202_82_dialog_content = "但是，感應能力將我們帶到了這裡，說明這裡就是最近的道路。",
  ui_story_70000202_83_dialog_content = "我們還有多少時間？",
  ui_story_70000202_84_dialog_content = "已經不多了。",
  ui_story_70000202_85_dialog_content = "這裡的白天比別處短得多，只有六個小時。",
  ui_story_70000202_86_dialog_content = "想要在白天回去的話，我們還有三個小時的時間。",
  ui_story_70000202_87_dialog_content = "就走這裡吧，跳到下面之後立刻找地方隱蔽，應該來得及！",
  ui_story_70000202_88_dialog_content = "......好，我相信你。",
  ui_story_70000301_1_dialog_content = "那兩個傢伙到哪裡了？",
  ui_story_70000301_2_dialog_content = "報告，根據裝置定位，他們仍在80號地下城內部喵。",
  ui_story_70000301_3_dialog_content = "受到暗能干擾，信號時斷時續，可能......他們進入到了深處喵？",
  ui_story_70000301_4_dialog_content = "希望他們進展順利......",
  ui_story_70000301_5_dialog_content = "不用急，放平心態。",
  ui_story_70000301_6_dialog_content = "對於執行潛入作戰的士兵，沒有消息就是最好的消息。",
  ui_story_70000301_7_dialog_content = "您這樣判斷的依據是？",
  ui_story_70000301_8_dialog_content = "每個啟光人都是我手底下的兵，作為大元帥，我當然對自己部下的能力心知肚明。",
  ui_story_70000301_9_dialog_content = "更何況，自從薇絲開始與<color=#FFB400>那位</color>一起行動時，她就受到了我的「特殊關注」。",
  ui_story_70000301_10_dialog_content = "妳也不用太擔心，我在「手冊」裡留了保險措施。",
  ui_story_70000301_11_dialog_content = "保險措施......？",
  ui_story_70000301_12_dialog_content = "如果一個半小時後，他們還在地下城裡，就透過通訊器聯絡他們。",
  ui_story_70000301_13_dialog_content = "沒錯。",
  ui_story_70000301_14_dialog_content = "……",
  ui_story_70000301_15_dialog_content = "PlayerName，走這邊。",
  ui_story_70000301_16_dialog_content = "這裡的暗鬼明顯變多了......",
  ui_story_70000301_17_dialog_content = "走起來......似乎也更困難了。",
  ui_story_70000301_18_dialog_content = "再堅持一下，PlayerName。",
  ui_story_70000301_19_dialog_content = "不行，好累......",
  ui_story_70000301_20_dialog_content = "這裡太危險了，想要休息的話，至少也要找個隱蔽的地方。",
  ui_story_70000301_21_dialog_content = "你看，只要再走幾百公尺，就能到達核心室正上方了。",
  ui_story_70000301_22_dialog_content = "如果你實在走不動的話......我背著你？",
  ui_story_70000301_23_dialog_content = "不不不，不必了......",
  ui_story_70000301_24_dialog_content = "讓我喘口氣就好！",
  ui_story_70000301_25_dialog_content = "等拿到目標回臨空者號以後，我給你做一頓好吃的補一補！",
  ui_story_70000301_26_dialog_content = "......這個真不用了！",
  ui_story_70000301_27_dialog_content = "我，我一點也不累！我們走吧！",
  ui_story_70000301_28_dialog_content = "前方發現暗鬼，數量......不行，太暗了，只能看清輪廓。",
  ui_story_70000301_29_dialog_content = "正堵在通往核心室的通道口嗎......這可不好辦了。",
  ui_story_70000301_30_dialog_content = "能繞開嗎？",
  ui_story_70000301_31_dialog_content = "我看一下地圖！",
  ui_story_70000301_32_dialog_content = "妳哪裡來的地圖？！",
  ui_story_70000301_33_dialog_content = "咦？你沒看到嗎？",
  ui_story_70000301_34_dialog_content = "剛剛你休息的時候，我看見廢墟里埋著半張地圖，就順手記在筆記本上了。",
  ui_story_70000301_35_dialog_content = "妳的記憶力那麼好嗎......",
  ui_story_70000301_36_dialog_content = "畢竟是工程製圖，對我來說是小意思啦。",
  ui_story_70000301_37_dialog_content = "而且地下城的建造都是遵循一定規律的，只要熟悉規律，想要記住地圖就不是什麼難事。",
  ui_story_70000301_38_dialog_content = "就比如逃生通道一般會有兩條以上，通風口會位於地下城的——",
  ui_story_70000301_39_dialog_content = "打住，我只想知道有沒有可以讓我們繞過暗鬼的路。",
  ui_story_70000301_40_dialog_content = "有一條，但是不知道是否暢通。",
  ui_story_70000301_41_dialog_content = "而且，這條路還滿遠的，以我們現在的速度，恐怕要多花半個小時。",
  ui_story_70000301_42_dialog_content = "半個小時嗎......時間已經很緊張了，拖得越久就越危險......",
  ui_story_70000301_43_dialog_content = "PlayerName，怎麼辦，要繞路嗎？",
  ui_story_70000301_44_dialog_content = "來不及了。",
  ui_story_70000301_45_dialog_content = "繞路的風險太大，而且時間也不夠用。",
  ui_story_70000301_46_dialog_content = "這樣，我們分別潛行到暗鬼兩側。",
  ui_story_70000301_X46_dialog_content = "我來製造噪音吸引牠們的注意，你趁機偷襲，務必將牠們迅速解決。",
  ui_story_70000301_47_dialog_content = "就這麼辦吧。",
  ui_story_70000301_48_dialog_content = "PlayerName，注意安全！",
  ui_story_70000302_1_dialog_content = "妳有沒有覺得，剛才那幾隻暗鬼比之前遇到的要強？",
  ui_story_70000302_2_dialog_content = "恐怕不是牠們變強了，而是我們變弱了。",
  ui_story_70000302_3_dialog_content = "越往下走，我就越覺得呼吸困難。",
  ui_story_70000302_4_dialog_content = "或許這裡的暗能濃度不止會隨著晝夜而變化，還會隨著深度而變化。",
  ui_story_70000302_5_dialog_content = "越陷越深，直到沉沒，難怪被叫做「泥潭」......",
  ui_story_70000302_6_dialog_content = "這裡已經是核心室的正上方了，附近沒有暗鬼，暫時安全。",
  ui_story_70000302_7_dialog_content = "PlayerName，你的臉色很差，還是休息一下比較好。",
  ui_story_70000302_8_dialog_content = "我們還有一個半小時，休息幾分鐘不會造成影響的。",
  ui_story_70000302_9_dialog_content = "我還可以再堅持一下，不能等到......",
  ui_story_70000302_10_dialog_content = "手冊上說，在暗面戰鬥，要抓緊一切時間休息，保持體力。",
  ui_story_70000302_11_dialog_content = "就算你不聽我的，也要聽「前輩」的忠告。",
  ui_story_70000302_12_dialog_content = "好吧......抱歉，薇絲，是我拖累妳了。",
  ui_story_70000302_13_dialog_content = "哪裡的話，你是我的夥伴呀。",
  ui_story_70000302_14_dialog_content = "來，這裡有塊石頭，先坐這裡吧。",
  ui_story_70000302_15_dialog_content = "我們到哪了？",
  ui_story_70000302_16_dialog_content = "根據指導手冊上的內容，這裡應該是原本的倉庫區，位置已經很深了。",
  ui_story_70000302_17_dialog_content = "附近確實散落著很多物品。",
  ui_story_70000302_18_dialog_content = "罐頭盒，空掉的醫療箱，遍地的彈殼......",
  ui_story_70000302_19_dialog_content = "還有骯髒的紗布和用鐵皮堆起來的、千瘡百孔的防禦工事......",
  ui_story_70000302_20_dialog_content = "守衛這裡的啟光士兵，一定戰鬥到了最後一刻。",
  ui_story_70000302_21_dialog_content = "但這裡最終還是失守了。",
  ui_story_70000302_22_dialog_content = "……",
  ui_story_70000302_23_dialog_content = "我只知道在那場戰爭中，啟光失去了很多人，很多很多人......",
  ui_story_70000302_24_dialog_content = "有時間仔細找找的話，說不定還能在這裡發現他們的吊牌。",
  ui_story_70000302_25_dialog_content = "如果能把它們帶回啟光的話，對於那些人的親屬而言，也是一種慰藉吧......",
  ui_story_70000302_26_dialog_content = "薇絲……",
  ui_story_70000302_27_dialog_content = "如果我也能幫忙找找的話......",
  ui_story_70000302_28_dialog_content = "欸？",
  ui_story_70000302_29_dialog_content = "這個是……？",
  ui_story_70000302_30_dialog_content = "PlayerName，你發現了什麼？",
  ui_story_70000302_31_dialog_content = "那些廢墟里埋著的碎片，看起來有點眼熟。",
  ui_story_70000302_32_dialog_content = "雖然覆蓋著灰塵，但那些東西，好像是白色的，上面的紋路就像是......",
  ui_story_70000302_33_dialog_content = "<color=#FFB400>巨像？</color>",
  ui_story_70000302_34_dialog_content = "欸？",
  ui_story_70000302_35_dialog_content = "你這麼一說，確實......",
  ui_story_70000302_36_dialog_content = "乍一看像是普通的垃圾，但仔細觀察的話——",
  ui_story_70000302_37_dialog_content = "有些像巨像組件？",
  ui_story_70000302_38_dialog_content = "即便不是巨像組件，也像是「空之山谷才會有的東西」。",
  ui_story_70000302_39_dialog_content = "難怪智庫組件說這裡會有修復臨空者號的方法。",
  ui_story_70000302_40_dialog_content = "看來我們找對方向了。",
  ui_story_70000302_41_dialog_content = "我再感應一下目標的位置。",
  ui_story_70000302_42_option_content = "感應！",
  ui_story_70000302_43_dialog_content = "這是……",
  ui_story_70000302_44_dialog_content = "吼——！！！",
  ui_story_70000302_45_dialog_content = "？！",
  ui_story_70000302_46_dialog_content = "PlayerName，你沒事吧？！",
  ui_story_70000302_47_dialog_content = "我感應到了一個非常強大的東西......",
  ui_story_70000302_48_dialog_content = "是暗鬼嗎？",
  ui_story_70000302_49_dialog_content = "很像，但是......我不確定。",
  ui_story_70000302_50_dialog_content = "那傢伙身上散發出強大的暗能，但又有若隱若現的光能。",
  ui_story_70000302_51_dialog_content = "就像是......",
  ui_story_70000302_52_dialog_content = "難道這裡也有吞羅改造出的怪物嗎？",
  ui_story_70000302_53_dialog_content = "我不確定。",
  ui_story_70000302_54_dialog_content = "我只知道，那傢伙不是一般的強大。",
  ui_story_70000302_55_dialog_content = "牠並不在我們附近，只要悄悄溜過去，就能在不驚動牠的情況下找到組件，然後溜走。",
  ui_story_70000302_56_dialog_content = "悄悄地......",
  ui_story_70000302_57_dialog_content = "悄悄地............",
  ui_story_70000302_58_dialog_content = "時間到了，聯繫上他們了嗎？",
  ui_story_70000302_59_dialog_content = "不行，他們的訊號完全消失了喵。",
  ui_story_70000302_60_dialog_content = "要組織救援隊嗎？",
  ui_story_70000302_61_dialog_content = "......唉，讓救援隊收拾裝備，跟我出發。",
  ui_story_70000302_62_dialog_content = "您要親自上陣嗎？",
  ui_story_70000302_63_dialog_content = "當然，輪到我活動活動筋骨了。",
  ui_story_70000302_64_dialog_content = "果然現在給他們這種難度的考驗還為時尚早嗎......？",
  ui_story_70000302_65_dialog_content = "看來還是要循序漸進才行啊。",
  ui_story_70000302_66_dialog_content = "......我明白了。救援隊，整隊！",
  ui_story_70000302_67_dialog_content = "（日蝕語）啟光的軍隊在永夜邊境集結。",
  ui_story_70000302_68_dialog_content = "（日蝕語）那個人也在其中。",
  ui_story_70000302_69_dialog_content = "（日蝕語）幾乎與此同時，空裔已經進入了80號地下城。",
  ui_story_70000302_70_dialog_content = "80號地下城......",
  ui_story_70000302_71_dialog_content = "難道她也想尋找<color=#FFB400>「那個」</color>嗎？",
  ui_story_70000302_72_dialog_content = "確實，整個世界上也只有那裡會存在一點線索了。",
  ui_story_70000302_73_dialog_content = "就讓我看看，妳會發現什麼吧——",
  ui_story_70000302_74_dialog_content = "「姐姐」。",
  ui_story_70000401_1_dialog_content = "PlayerName，把手給我。",
  ui_story_70000401_2_dialog_content = "嘿！",
  ui_story_70000401_3_dialog_content = "呼......終於......終於到了......",
  ui_story_70000401_4_dialog_content = "這裡的暗能簡直濃郁得不像話，稍微動一動身體都無比困難。",
  ui_story_70000401_5_dialog_content = "PlayerName，我們要找的東西真的在這附近嗎？",
  ui_story_70000401_6_dialog_content = "嗯，我能感受到它，就在附近了。",
  ui_story_70000401_7_dialog_content = "應該......就在核心室的機器上。",
  ui_story_70000401_8_dialog_content = "好像是那個！",
  ui_story_70000401_9_dialog_content = "這東西......真的是意識模組嗎？",
  ui_story_70000401_10_dialog_content = "和臨空者號的意識模組完全不一樣......",
  ui_story_70000401_11_dialog_content = "但是，智庫組件確實準確地指向了它。",
  ui_story_70000401_12_dialog_content = "而且附近也沒有其他看起來像是意識模組的東西了。",
  ui_story_70000401_13_dialog_content = "總之，先把它帶回臨空者號看看！",
  ui_story_70000401_14_dialog_content = "好，不過它裝在核心上。",
  ui_story_70000401_15_dialog_content = "我試試看能不能把它弄下來。",
  ui_story_70000401_16_dialog_content = "唔......",
  ui_story_70000401_17_dialog_content = "不行，嵌得太緊了。",
  ui_story_70000401_18_dialog_content = "PlayerName，幫幫我。",
  ui_story_70000401_19_dialog_content = "來了！",
  ui_story_70000401_20_dialog_content = "我喊三二一，我們一起用力拔。",
  ui_story_70000401_21_dialog_content = "三——",
  ui_story_70000401_22_dialog_content = "二——",
  ui_story_70000401_23_dialog_content = "一！",
  ui_story_70000401_24_dialog_content = "用力！",
  ui_story_70000401_25_dialog_content = "啊——！",
  ui_story_70000401_26_dialog_content = "後腦勺......好像撞到什麼了，模組沒事吧？",
  ui_story_70000401_27_dialog_content = "看起來沒什麼問題，我們快走吧！",
  ui_story_70000401_28_dialog_content = "<color=#e8d9bb>轟隆——</color>",
  ui_story_70000401_29_dialog_content = "地震了？！",
  ui_story_70000401_30_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_70000401_31_dialog_content = "地下城的能源供應......停止了？！",
  ui_story_70000401_32_dialog_content = "是因為我們拿了模組的原因嗎？",
  ui_story_70000401_33_dialog_content = "我不清楚，但我能感受到......",
  ui_story_70000401_34_dialog_content = "<color=#e8d9bb>轟隆——！！！</color>",
  ui_story_70000401_36_dialog_content = "愈來愈近了？！",
  ui_story_70000401_37_dialog_content = "是塌方！",
  ui_story_70000401_37X1_dialog_content = "PlayerName，快離開那面牆！",
  ui_story_70000401_37X2_dialog_content = "咳咳，咳咳咳！",
  ui_story_70000401_37X3_dialog_content = "好多灰塵！",
  ui_story_70000401_37X4_dialog_content = "……",
  ui_story_70000401_37X5_dialog_content = "塌方的牆壁後面，露出了一片空間......？",
  ui_story_70000401_37X6_dialog_content = "裡面那個是......",
  ui_story_70000401_37X7_dialog_content = "…………",
  ui_story_70000401_37X8_dialog_content = "好重的暗能！",
  ui_story_70000401_37X9_dialog_content = "難道是PlayerName感應到的暗鬼......？！",
  ui_story_70000401_37X10_dialog_content = "......！",
  ui_story_70000401_37X11_dialog_content = "真的是暗鬼，還是之前沒見過的種類？！",
  ui_story_70000401_37X12_dialog_content = "牠看起來沒什麼反應，難道是睡著了？",
  ui_story_70000401_37X13_dialog_content = "先別驚擾牠，我們悄悄溜過去，找到出口......",
  ui_story_70000401_37X14_dialog_content = "但是開啟出口需要拍打牆壁，肯定還會驚醒牠。",
  ui_story_70000401_37X15_dialog_content = "那到時你就先——",
  ui_story_70000401_37X16_dialog_content = "......光......",
  ui_story_70000401_37X17_dialog_content = "牠在說夢話......？",
  ui_story_70000401_37X18_dialog_content = "離得太遠了，聽不清。",
  ui_story_70000401_37X19_dialog_content = "會說話的暗鬼多了......",
  ui_story_70000401_37X20_dialog_content = "先別管牠，想辦法離開這裡吧！",
  ui_story_70000401_37X21_dialog_content = "嗯，說得對......",
  ui_story_70000401_37X22_dialog_content = "......啟......光！！！",
  ui_story_70000401_37X23_dialog_content = "等等，你聽見了嗎，牠剛才喊的是——",
  ui_story_70000401_37X24_dialog_content = "吼——！！！",
  ui_story_70000401_37X25_dialog_content = "不好，牠醒了！",
  ui_story_70000401_37X26_dialog_content = "快跑，我們被發現了！",
  ui_story_70000401_38_dialog_content = "PlayerName，小心！",
  ui_story_70000401_39_dialog_content = "薇絲！妳沒事吧？！",
  ui_story_70000401_39X1_dialog_content = "這裡暗能太重，我們不能跟牠打。找機會，逃出去！",
  ui_story_70000401_40_dialog_content = "好！妳先拖住牠，我去找出口！",
  ui_story_70000401_41_dialog_content = "呃......！",
  ui_story_70000401_42_dialog_content = "快點！我拖不了幾分鐘，你快去找暗門！",
  ui_story_70000402_1_dialog_content = "三輕——",
  ui_story_70000402_2_dialog_content = "<color=#e8d9bb>咚咚咚！</color>",
  ui_story_70000402_3_dialog_content = "三重——",
  ui_story_70000402_4_dialog_content = "<color=#e8d9bb>咚——！咚——！咚——！</color>",
  ui_story_70000402_5_dialog_content = "三輕——",
  ui_story_70000402_6_dialog_content = "<color=#e8d9bb>咚咚咚！</color>",
  ui_story_70000402_7_dialog_content = "……",
  ui_story_70000402_8_dialog_content = "為什麼沒有動靜？！",
  ui_story_70000402_9_dialog_content = "快開門啊！！！",
  ui_story_70000402_10_dialog_content = "PlayerName，還沒好嗎？！",
  ui_story_70000402_11_dialog_content = "不行！完全沒反應！",
  ui_story_70000402_12_dialog_content = "吼——！",
  ui_story_70000402_13_dialog_content = "呃——！",
  ui_story_70000402_14_dialog_content = "不行了！先往深處撤退！",
  ui_story_70000402_15_dialog_content = "但是深處根本沒有退路啊？！",
  ui_story_70000402_16_dialog_content = "管不了那麼多了！",
  ui_story_70000402_17_dialog_content = "現在那傢伙擋住了通往淺層的路，我們無法突圍！",
  ui_story_70000402_18_dialog_content = "向深處躲藏說不定還能有轉機！",
  ui_story_70000402_19_dialog_content = "......妳說得對！",
  ui_story_70000402_20_dialog_content = "那就別愣著了，快跑！",
  ui_story_70000402_21_dialog_content = "吼！ ！ ！",
  ui_story_70000402_22_dialog_content = "<color=#e8d9bb>轟隆！</color>",
  ui_story_70000402_23_dialog_content = "報，報告！",
  ui_story_70000402_24_dialog_content = "80號地下城遺跡方向，有強烈震感！",
  ui_story_70000402_25_dialog_content = "穩住，不要慌！",
  ui_story_70000402_26_dialog_content = "維持防禦陣型不變，繼續向80號地下城前進。",
  ui_story_70000402_27_dialog_content = "是！",
  ui_story_70000402_28_dialog_content = "<color=#e8d9bb>吼——！</color>",
  ui_story_70000402_29_dialog_content = "什麼聲音？！",
  ui_story_70000402_30_dialog_content = "這是……",
  ui_story_70000402_31_dialog_content = "......！",
  ui_story_70000402_32_dialog_content = "這感覺......",
  ui_story_70000402_33_dialog_content = "不可能，怎麼可能......",
  ui_story_70000402_34_dialog_content = "大元帥，您沒事吧？！",
  ui_story_70000402_35_dialog_content = "……",
  ui_story_70000402_36_dialog_content = "不行，不能讓他們過去。",
  ui_story_70000402_37_dialog_content = "那不是他們能對付的。",
  ui_story_70000402_38_dialog_content = "救援隊，聽我命令，立刻返回安全線。",
  ui_story_70000402_39_dialog_content = "不管發生什麼，都不能進入「暗面」。",
  ui_story_70000402_40_dialog_content = "是！可是......大元帥您......",
  ui_story_70000402_41_dialog_content = "不用擔心，有些事情需要我親自處理而已。",
  ui_story_70000402_42_dialog_content = "還有，幫我帶話給薇薇安——",
  ui_story_70000402_43_dialog_content = "在我回來之前，讓她幫忙應付一下「那些傢伙」。",
  ui_story_70000402_44_dialog_content = "是！",
  ui_story_70000402_45_dialog_content = "<color=#e8d9bb>吼——！</color>",
  ui_story_70000402_46_dialog_content = "……",
  ui_story_70000402_47_dialog_content = "果然，這裡存在著「線索」。",
  ui_story_70000402_48_dialog_content = "「凡走過，必留下痕跡。」",
  ui_story_70000402_49_dialog_content = "這片拼圖，我就收下了。",
  ui_story_70000402_50_dialog_content = "吞羅——",
  ui_story_70000402_51_dialog_content = "別忘了妳的承諾。",
  ui_story_70000402_52_dialog_content = "呿……",
  ui_story_70000402_53_dialog_content = "知道了。",
  ui_story_70000402_54_dialog_content = "你要做的只是等待我的信號，然後將那群蟲子趕走。",
  ui_story_70000402_55_dialog_content = "妳那搖擺不定的心態，終究會招致失敗。",
  ui_story_70000402_56_dialog_content = "半吊子。",
  ui_story_70000402_57_dialog_content = "......愚蠢。",
  ui_story_70000501_1_dialog_content = "微量的光能術痕跡，還沒被暗能吞噬，是最近才留下的。",
  ui_story_70000501_2_dialog_content = "暗鬼的痕跡......十隻左右，但是戰鬥痕跡不多。",
  ui_story_70000501_3_dialog_content = "看起來使用了突襲的戰術，並且在盡量避免戰鬥。",
  ui_story_70000501_4_dialog_content = "戰術運用得不錯，還充分考慮到了地形......",
  ui_story_70000501_5_dialog_content = "不錯啊，逐漸有點指揮者的樣子了。",
  ui_story_70000501_6_dialog_content = "只是，在這種地方，你們又能堅持多久呢？",
  ui_story_70000501_7_dialog_content = "<color=#e8d9bb>轟隆——</color>",
  ui_story_70000501_8_dialog_content = "還是被困住了嗎？",
  ui_story_70000501_9_dialog_content = "明明已經在手冊中強調了無數回，卻還是犯下這種低級錯誤。",
  ui_story_70000501_10_dialog_content = "等到回去以後，要好好給他們上一課了。",
  ui_story_70000501_11_dialog_content = "薇絲，向右後方閃避！",
  ui_story_70000501_12_dialog_content = "好的！",
  ui_story_70000501_13_dialog_content = "嚐嚐這個！",
  ui_story_70000501_14_dialog_content = "吼——！",
  ui_story_70000501_15_dialog_content = "不行，攻擊完全不奏效！",
  ui_story_70000501_16_dialog_content = "這個地方的暗能太重了！",
  ui_story_70000501_17_dialog_content = "我來試試牽制牠！",
  ui_story_70000501_18_option_content = "強制感應——！",
  ui_story_70000501_19_dialog_content = "啟......",
  ui_story_70000501_20_dialog_content = "啟？",
  ui_story_70000501_21_dialog_content = "牠這是......在說什麼？",
  ui_story_70000501_22_dialog_content = "啟......光......",
  ui_story_70000501_23_dialog_content = "啟光......？啟光聯邦？！",
  ui_story_70000501_24_dialog_content = "啟光——！！！",
  ui_story_70000501_25_dialog_content = "呃——！好強的恨意！",
  ui_story_70000501_26_dialog_content = "PlayerName？！",
  ui_story_70000501_27_dialog_content = "我沒事！",
  ui_story_70000501_28_dialog_content = "那隻暗鬼很奇怪，牠似乎對啟光有著強烈的恨意！",
  ui_story_70000501_29_dialog_content = "啟光......吼！！！",
  ui_story_70000501_30_dialog_content = "難道牠看見我穿的是啟光的制服，所以才攻擊的？",
  ui_story_70000501_31_dialog_content = "PlayerName，我來引開牠，你趁機向外跑！",
  ui_story_70000501_32_dialog_content = "那妳怎麼辦？！",
  ui_story_70000501_33_dialog_content = "不要管我，保護好你自己！",
  ui_story_70000501_34_dialog_content = "啟光——！！！",
  ui_story_70000501_35_dialog_content = "呃——！",
  ui_story_70000501_36_dialog_content = "薇絲！",
  ui_story_70000501_37_dialog_content = "得想辦法救薇絲......！",
  ui_story_70000501_38_dialog_content = "傻里傻氣的大個子，看我啊，我在這裡呢！！！",
  ui_story_70000501_39_dialog_content = "吼！ ！ ！",
  ui_story_70000501_40_dialog_content = "PlayerName......快......跑......",
  ui_story_70000501_41_dialog_content = "快來追我啊啊啊——！",
  ui_story_70000501_42_dialog_content = "吼！ ！ ！",
  ui_story_70000501_43_dialog_content = "好快？！",
  ui_story_70000501_44_dialog_content = "唔——！",
  ui_story_70000501_45_dialog_content = "PlayerName？！",
  ui_story_70000501_46_dialog_content = "難道......要死在這裡了嗎......",
  ui_story_70000501_47_dialog_content = "誰都好，請妳......救救我們......",
  ui_story_70000501_48_dialog_content = "吼——",
  ui_story_70000501_49_dialog_content = "<color=#e8d9bb>鏘——！</color>",
  ui_story_70000501_50_dialog_content = "作為一個指揮者，你的眼睛要時刻注視戰局。",
  ui_story_70000501_51_dialog_content = "這聲音是……",
  ui_story_70000501_52_dialog_content = "萊因哈特？！",
  ui_story_70000501_53_dialog_content = "空裔PlayerName，你是個不錯的指揮官苗子，但還缺乏鍛鍊。",
  ui_story_70000501_54_dialog_content = "回去讓巴頓和老克好好敲打敲打你！",
  ui_story_70000501_55_dialog_content = "咦？！",
  ui_story_70000501_56_dialog_content = "啟光——啟光——！！！",
  ui_story_70000501_57_dialog_content = "——！！！",
  ui_story_70000501_58_dialog_content = "萊因哈特......大元帥......！",
  ui_story_70000501_59_dialog_content = "你們要是還能動，就先找掩護躲好。",
  ui_story_70000501_60_dialog_content = "薇絲，這邊！",
  ui_story_70000501_61_dialog_content = "吼——！！！",
  ui_story_70000501_62_dialog_content = "沒想到，竟然真的是你。",
  ui_story_70000501_63_dialog_content = "就算外表變成半個暗鬼，但你熟悉的戰斗方式，卻還是一點也沒變。",
  ui_story_70000501_64_dialog_content = "奇怪，萊因哈特她......在和那隻暗鬼說話？",
  ui_story_70000501_65_dialog_content = "你難道忘了你的過去嗎？",
  ui_story_70000501_66_dialog_content = "「我的老朋友」。",
  ui_story_70000501_67_dialog_content = "「老朋友」......？",
  ui_story_70000501_68_dialog_content = "吼！",
  ui_story_70000501_69_dialog_content = "糟糕，這裡有暗能，不利於萊因哈特戰鬥！",
  ui_story_70000501_70_dialog_content = "得試著干擾那隻暗鬼......",
  ui_story_70000501_71_dialog_content = "感應鏈接——！",
  ui_story_70000501_72_dialog_content = "吼——",
  ui_story_70000501_73_dialog_content = "唔啊！",
  ui_story_70000501_74_dialog_content = "<color=#e8d9bb>轟隆！</color>",
  ui_story_70000501_75_dialog_content = "這傢伙......簡直就是不要命啊！",
  ui_story_70000501_76_dialog_content = "牠就不怕把地下城都弄塌嗎？！",
  ui_story_70000501_77_dialog_content = "PlayerName，先停下！",
  ui_story_70000501_78_dialog_content = "別那麼著急。",
  ui_story_70000501_78X1_dialog_content = "——！！！",
  ui_story_70000501_78X2_dialog_content = "萊因哈特？！快躲開！",
  ui_story_70000501_78X3_dialog_content = "大元帥！",
  ui_story_70000501_78X4_dialog_content = "別擔心，我沒事的。",
  ui_story_70000501_78X5_dialog_content = "只是有一件事......我想要嘗試一下。",
  ui_story_70000501_79_dialog_content = "可是……",
  ui_story_70000501_80_dialog_content = "PlayerName，先暫時相信大元帥吧......",
  ui_story_70000501_81_dialog_content = "萊因哈特......她為什麼不反擊？",
  ui_story_70000501_82_dialog_content = "你......還記得嗎？",
  ui_story_70000501_83_dialog_content = "我們曾經並肩戰鬥，擊退過無數敵人。",
  ui_story_70000501_84_dialog_content = "……",
  ui_story_70000501_85_dialog_content = "掘開一條條壕溝，抵擋一輪輪進攻，只為守護我們的故鄉，迦南城。",
  ui_story_70000501_86_dialog_content = "迦......南......城......",
  ui_story_70000501_87_dialog_content = "對，迦南城。我們曾經向著它，以自己的名字發誓。",
  ui_story_70000501_88_dialog_content = "你還記得你的名字嗎？",
  ui_story_70000501_89_dialog_content = "吼……",
  ui_story_70000501_90_dialog_content = "你的名字是——<color=#FFB400>赫利俄斯</color>。",
  ui_story_70000501_91_dialog_content = "啟......光......",
  ui_story_70000501_92_dialog_content = "啟光——！！！",
  ui_story_70000501_93_dialog_content = "吼——！",
  ui_story_70000501_94_dialog_content = "嘖，還是不行嗎......",
  ui_story_70000501_95_dialog_content = "大元帥，危險！",
  ui_story_70000501_96_dialog_content = "這裡的結構脆弱，已經經不住衝擊了！",
  ui_story_70000501_97_dialog_content = "再打下去，整座地下城都有可能崩塌！",
  ui_story_70000501_98_dialog_content = "......吼！",
  ui_story_70000501_99_dialog_content = "你也不看看自己變成了什麼德行......",
  ui_story_70000501_100_dialog_content = "想起來吧，想起你自己究竟是誰。",
  ui_story_70000501_101_dialog_content = "跟我回啟光，我會幫你尋找治療的方法，讓你變回原樣！",
  ui_story_70000501_102_dialog_content = "吼！ ！ ！",
  ui_story_70000501_103_dialog_content = "咳咳——！",
  ui_story_70000501_104_dialog_content = "PlayerName，往這邊躲！",
  ui_story_70000501_105_dialog_content = "<color=#e8d9bb>叮鈴鈴——</color>",
  ui_story_70000501_106_dialog_content = "——！",
  ui_story_70000501_107_dialog_content = "這是……",
  ui_story_70000501_108_dialog_content = "是鈴聲嗎？從哪裡來的？",
  ui_story_70000501_109_dialog_content = "吼——！！！",
  ui_story_70000501_110_dialog_content = "那隻高級暗鬼......爬上懸崖頭也不回地跑了？",
  ui_story_70000501_111_dialog_content = "難道那鈴聲能控制暗鬼？",
  ui_story_70000501_112_dialog_content = "不。",
  ui_story_70000501_113_dialog_content = "那鈴聲只代表一個意思——<color=#FFB400>「援軍已到，開始撤退」</color>。",
  ui_story_70000501_114_dialog_content = "那隻暗鬼......是妳的熟人？",
  ui_story_70000501_115_dialog_content = "不只是熟人，還是戰友。",
  ui_story_70000501_116_dialog_content = "可以把性命託付給對方的那種。",
  ui_story_70000501_117_dialog_content = "在「暗面戰爭」中，他失蹤了，就在這座地下城裡。",
  ui_story_70000501_118_dialog_content = "我原本以為「他」死了，只是沒想到......",
  ui_story_70000501_119_dialog_content = "那傢伙竟然還活著，甚至變成了暗鬼。",
  ui_story_70000501_120_dialog_content = "變成暗鬼？這簡直就像是......",
  ui_story_70000501_121_dialog_content = "關於「他」的事，我現在的思路也很混亂。",
  ui_story_70000501_122_dialog_content = "<color=#e8d9bb>轟隆！</color>",
  ui_story_70000501_123_dialog_content = "看來這座地下城也已經要完了。",
  ui_story_70000501_124_dialog_content = "我們先離開這裡，剩下的事路上說。",
  ui_story_70000501_125_dialog_content = "也只能這樣了。",
  ui_story_70000501_126_dialog_content = "我知道一條出路，跟我來！",
  ui_story_70000601_1_dialog_content = "我曾經有兩個最為要好的夥伴，其中一個就是他，<color=#FFB400>赫利俄斯</color>。",
  ui_story_70000601_1X1_dialog_content = "而另一個，你們應該也認識，那時候，她還叫<color=#FFB400>德尼耶爾</color>。",
  ui_story_70000601_1X2_dialog_content = "吞羅......？！",
  ui_story_70000601_1X3_dialog_content = "是的，這是她現在的名字。",
  ui_story_70000601_2_dialog_content = "我們三個一起在啟光的育嬰院長大，又一起參軍、一起戰鬥。",
  ui_story_70000601_3_dialog_content = "德尼耶爾，萊因哈特，妳們的目標定下了嗎？",
  ui_story_70000601_4_dialog_content = "我的教官說我很有天賦，以後可能會當偵察兵。",
  ui_story_70000601_5_dialog_content = "我和你們不一樣，實驗室才是我的戰場。",
  ui_story_70000601_6_dialog_content = "熱血笨蛋的角色有別人比我更適合。",
  ui_story_70000601_7_dialog_content = "妳還是這麼喜歡諷刺人啊。",
  ui_story_70000601_8_dialog_content = "那妳呢，萊因哈特？",
  ui_story_70000601_9_dialog_content = "我？",
  ui_story_70000601_10_dialog_content = "我還沒想好。不過，不妨定一個小目標——",
  ui_story_70000601_11_dialog_content = "先當上啟光的大元帥好了。",
  ui_story_70000601_12_dialog_content = "不久之後，我們的功績終於被啟光的領導者、被委員會重視。",
  ui_story_70000601_13_dialog_content = "我們一起成為了大元帥的候選人。",
  ui_story_70000601_14_dialog_content = "你們是啟光最優秀的士兵，擔負著啟光的明天。",
  ui_story_70000601_15_dialog_content = "你們將要經歷的，是啟光最為嚴酷的訓練。",
  ui_story_70000601_16_dialog_content = "每天，甚至每小時，都會有人被淘汰。",
  ui_story_70000601_17_dialog_content = "但是，其中的獲勝者將成為啟光的大元帥。",
  ui_story_70000601_18_dialog_content = "成為最強的那個人！",
  ui_story_70000601_19_dialog_content = "有沒有信心？！",
  ui_story_70000601_20_dialog_content = "有。",
  ui_story_70000601_21_dialog_content = "有！",
  ui_story_70000601_22_dialog_content = "有——！",
  ui_story_70000601_23_dialog_content = "<color=#FFB400>委員會</color>？那是什麼？",
  ui_story_70000601_24_dialog_content = "咦？PlayerName沒聽說過委員會嗎？",
  ui_story_70000601_25_dialog_content = "完全沒有。",
  ui_story_70000601_26_dialog_content = "那可是和萊因哈特大元帥共同管理啟光各類事項的機構！",
  ui_story_70000601_27_dialog_content = "畢竟啟光人總是三句話不離大元帥嘛！",
  ui_story_70000601_28_dialog_content = "都沒有人說過什麼「委員會」。",
  ui_story_70000601_29_dialog_content = "咳咳......",
  ui_story_70000601_30_dialog_content = "（糟了！淨顧著吐槽，竟然忘了大元帥本人就在這裡！）",
  ui_story_70000601_31_dialog_content = "委員會，全稱<color=#FFB400>「啟光聯邦軍事與政務委員會」</color>。",
  ui_story_70000601_32_dialog_content = "他們是一群難對付的老古董，啟光的每件事會由他們親自過目。",
  ui_story_70000601_33_dialog_content = "不過那些傢伙向來行事低調，不為外人所知也正常。",
  ui_story_70000601_34_dialog_content = "（還好還好，萊因哈特替我解了圍......）",
  ui_story_70000601_35_dialog_content = "欸？等一下，這麼說來——",
  ui_story_70000601_36_dialog_content = "豈不就是說，啟光的大元帥是由委員會來決定的？",
  ui_story_70000601_37_dialog_content = "欸？",
  ui_story_70000601_38_dialog_content = "大元帥......不應該是由軍功最高的人來當嗎？",
  ui_story_70000601_39_dialog_content = "至少我在上學時讀的書上是這樣寫的......",
  ui_story_70000601_40_dialog_content = "軍功只是一方面。",
  ui_story_70000601_41_dialog_content = "團結人心可是一件麻煩事。",
  ui_story_70000601_41X_dialog_content = "啟光聯邦由那麼多地下城組成，僅靠「軍功」無法服眾。",
  ui_story_70000601_42_dialog_content = "如果一個人只憑軍功就能當上大元帥，而沒有任何領導能力......",
  ui_story_70000601_43_dialog_content = "萬一是一個窮兵黷武的莽夫怎麼辦？",
  ui_story_70000601_44_dialog_content = "難道要按照那人的意願，用整個啟光的資源修建城牆和大砲。",
  ui_story_70000601_44X_dialog_content = "然後讓所有人一起喝西北風？",
  ui_story_70000601_45_dialog_content = "這......",
  ui_story_70000601_46_dialog_content = "我們到了。",
  ui_story_70000601_47_dialog_content = "這附近......完全就是廢墟啊？！",
  ui_story_70000601_48_dialog_content = "別急，我記得入口是......",
  ui_story_70000601_49_dialog_content = "這裡竟然還有暗道？！",
  ui_story_70000601_50_dialog_content = "準確來說，是逃生通道。",
  ui_story_70000601_51_dialog_content = "可能是考慮到地震多發，所以這座地下城的逃生通道進行過特殊加固。",
  ui_story_70000601_52_dialog_content = "我也曾經從這裡發起過突圍。",
  ui_story_70000601_53_dialog_content = "進來吧。",
  ui_story_70000601_54_dialog_content = "好安靜......",
  ui_story_70000601_55_dialog_content = "薇絲，我來扶妳。",
  ui_story_70000601_56_dialog_content = "謝謝你，PlayerName。",
  ui_story_70000601_57_dialog_content = "我沒關係的。",
  ui_story_70000601_58_dialog_content = "妳剛才受了那麼重的攻擊，還是先保存體力吧。",
  ui_story_70000601_59_dialog_content = "唉......就算你們能力出眾，也不能亂來。",
  ui_story_70000601_60_dialog_content = "如果你們乖乖聽話，在時間將近的時候就按照手冊的要求返回地面......",
  ui_story_70000601_60X_dialog_content = "就不會遭遇這種麻煩。",
  ui_story_70000601_61_dialog_content = "您，您知道手冊？難道它是......",
  ui_story_70000601_62_dialog_content = "當然是我寫的，而且我還知道妳委託菲莉詩調查80號地下城。",
  ui_story_70000601_63_dialog_content = "！！！",
  ui_story_70000601_64_dialog_content = "那樣看著我幹什麼？",
  ui_story_70000601_65_dialog_content = "我是整個啟光聯邦唯一曾在暗面經歷過戰鬥，最終活著回來的人。",
  ui_story_70000601_66_dialog_content = "這座80號地下城，就是我們當年的戰場。",
  ui_story_70000601_67_dialog_content = "有人要調查這座地下城，我會不知道？",
  ui_story_70000601_68_dialog_content = "那您為什麼會在這裡......？",
  ui_story_70000601_69_dialog_content = "我以為您會在迦南城。",
  ui_story_70000601_70_dialog_content = "我默許你們探索這片區域，是因為信任你們的能力。",
  ui_story_70000601_71_dialog_content = "但這不代表我不會考慮可能出現的意外情況，更不代表我會放任你們陷入危險。",
  ui_story_70000601_72_dialog_content = "大元帥的職責不就是保護啟光的每一個人嗎？",
  ui_story_70000601_73_dialog_content = "這其中也包括你，啟光的盟友，PlayerName。",
  ui_story_70000601_74_dialog_content = "呃，是，是......",
  ui_story_70000601_75_dialog_content = "自從得知你們要調查80號地下城......",
  ui_story_70000601_75X_dialog_content = "我就帶領士兵，守候在暗面邊界的安全線上了。",
  ui_story_70000601_76_dialog_content = "本來我想把它當作對你們實力的考察。",
  ui_story_70000601_77_dialog_content = "如果你們順利回來，我就裝作無事發生，不再深究。",
  ui_story_70000601_78_dialog_content = "沒想到你們竟然差點遇險。",
  ui_story_70000601_79_dialog_content = "嗯，本來計畫一切順利，只是沒想到地下竟然還存在著這麼強大的敵人......",
  ui_story_70000601_79X_dialog_content = "如果不是我感應到了赫利俄斯的存在，及時救援，可就出大事了。",
  ui_story_70000601_80_dialog_content = "情報可信，但不能盡信......",
  ui_story_70000601_81_dialog_content = "作為一個指揮官，你可得好好記住這句話。",
  ui_story_70000601_82_dialog_content = "是……",
  ui_story_70000601_83_dialog_content = "你們遲遲不歸，讓我得出你們遇到麻煩的結論。",
  ui_story_70000601_84_dialog_content = "本來我以為只是普通的暗鬼，但沒想到，竟然是他......",
  ui_story_70000601_85_dialog_content = "命運還真喜歡開這種沒品味的玩笑。",
  ui_story_70000601_86_dialog_content = "……",
  ui_story_70000601_87_dialog_content = "好了，不說這個了。",
  ui_story_70000601_88_dialog_content = "打開這扇門，我們就能進入逃生通道。",
  ui_story_70000601_89_dialog_content = "繼續向上走，就可以到達地面。",
  ui_story_70000601_90_dialog_content = "<color=#e8d9bb>吱呀——</color>",
  ui_story_70000601_91_dialog_content = "這裡果然沒有被地震影響。",
  ui_story_70000601_92_dialog_content = "甚至還能感覺到隱隱的風。",
  ui_story_70000601_93_dialog_content = "說明這條路通向外面！",
  ui_story_70000601_94_dialog_content = "小聲點，通道會把你的聲音放大。",
  ui_story_70000601_95_dialog_content = "管道裡說不定還有潛伏的暗鬼。",
  ui_story_70000601_96_dialog_content = "吼——！",
  ui_story_70000601_97_dialog_content = "還真是怕什麼來什麼......",
  ui_story_70000601_98_dialog_content = "噫！對不起！",
  ui_story_70000601_99_dialog_content = "準備戰鬥，空裔，讓我看看你的指揮水平吧！",
  ui_story_70000602_1_dialog_content = "為什麼……",
  ui_story_70000602_2_dialog_content = "明明是在向上走，但是暗能的壓迫感卻愈來愈沉重了？",
  ui_story_70000602_3_dialog_content = "沒錯……",
  ui_story_70000602_4_dialog_content = "剛剛還能勉強應付幾隻暗鬼，但是現在卻連一兩隻都打不過......",
  ui_story_70000602_5_dialog_content = "原因清清楚楚地寫「手冊」上，現在該考考你們的記憶力了。",
  ui_story_70000602_6_dialog_content = "因為消耗了體力？",
  ui_story_70000602_7_dialog_content = "錯了。",
  ui_story_70000602_8_dialog_content = "這雖然也是原因之一，但你忘了最關鍵的答案。",
  ui_story_70000602_9_dialog_content = "難道是因為......時間？",
  ui_story_70000602_10_dialog_content = "沒錯。",
  ui_story_70000602_11_dialog_content = "因為......入夜了？",
  ui_story_70000602_12_dialog_content = "記憶力不錯啊。",
  ui_story_70000602_13_dialog_content = "看來你們好好讀過作戰手冊。",
  ui_story_70000602_14_dialog_content = "我千叮嚀萬囑咐，讓你們注意時間，就是為了避免這種最糟糕的情況。",
  ui_story_70000602_15_dialog_content = "不過就算我說了，你也不會聽吧？",
  ui_story_70000602_16_dialog_content = "畢竟「臨空者號」對於你來說，也是重要的夥伴和家人。",
  ui_story_70000602_17_dialog_content = "被妳看透了......",
  ui_story_70000602_18_dialog_content = "是你的想法太好懂了。",
  ui_story_70000602_19_dialog_content = "薇絲每天都嘰嘰喳喳地說著關於你的事情。",
  ui_story_70000602_20_dialog_content = "就算我不想听，也總是被迫聽到幾句。",
  ui_story_70000602_21_dialog_content = "萊因哈特大元帥！？",
  ui_story_70000602_22_dialog_content = "不過，我還有個問題。",
  ui_story_70000602_23_dialog_content = "為什麼妳能感應到赫利俄斯？",
  ui_story_70000602_24_dialog_content = "大概是某種戰友之間的默契吧。",
  ui_story_70000602_25_dialog_content = "從小到大，我們之間的關係就像家人一樣緊密。",
  ui_story_70000602_26_dialog_content = "如果家人遇到了麻煩，冥冥之中總會有種感覺的。",
  ui_story_70000602_27_dialog_content = "這座地下城本來封閉已久，暗能和距離將這冥冥中的感覺切斷。",
  ui_story_70000602_28_dialog_content = "但是你們打開了它，甚至驚動了被困底層多年的赫利俄斯。",
  ui_story_70000602_29_dialog_content = "這份牽絆藉此機會，重新連結了......",
  ui_story_70000602_30_dialog_content = "難道萊因哈特也有感應能力？",
  ui_story_70000602_31_dialog_content = "我倒是想擁有感應能力。",
  ui_story_70000602_32_dialog_content = "那樣指揮起戰鬥來可就方便多了。",
  ui_story_70000602_33_dialog_content = "我們之間的情況，大概類似於某種戰友之間的牽絆。",
  ui_story_70000602_34_dialog_content = "本來已經中斷了......",
  ui_story_70000602_34X_dialog_content = "但是隨著你們無意間的行動，這份牽絆又將我們再次連結在一起。",
  ui_story_70000602_35_dialog_content = "我個人更願意把它歸因於某種共同經歷——",
  ui_story_70000602_36_dialog_content = "一同接受過生死存亡考驗的經歷。",
  ui_story_70000602_36X1_dialog_content = "那是屬於我們三個人共同的記憶。",
  ui_story_70000602_36X2_dialog_content = "你們三個......究竟經歷了什麼？",
  ui_story_70000602_36X3_dialog_content = "一場苦戰。不過，對於他們而言，大概更像是一場背叛。",
  ui_story_70000602_36X4_dialog_content = "來自我和啟光的背叛......他們被啟光，被我放棄了。",
  ui_story_70000602_36X5_dialog_content = "放棄......？",
  ui_story_70000602_36X6_dialog_content = "可是，萊因哈特，妳看起來不像是會放棄別人的樣子啊？",
  ui_story_70000602_37_dialog_content = "這就說來話長了，先讓我整理一下思緒吧。",
  ui_story_70000602_38_dialog_content = "我只覺得恐怕也是這場背叛，讓赫利俄斯變成了如今這副樣子。",
  ui_story_70000602_39_dialog_content = "還有德尼耶爾......不，她現在只有一個名字——",
  ui_story_70000602_40_dialog_content = "<color=#FFB400>吞羅。</color>",
  ui_story_70000602_41_dialog_content = "吞羅......",
  ui_story_70000602_42_dialog_content = "她後來之所以背叛啟光，也是因為被放棄而感到失望嗎？",
  ui_story_70000602_43_dialog_content = "我不知道。",
  ui_story_70000602_44_dialog_content = "但這不能成為她進行人體實驗、危害啟光人民的理由。",
  ui_story_70000602_45_dialog_content = "我知道她對沒能等來救援這件事心懷怨恨。",
  ui_story_70000602_46_dialog_content = "可這是我的過失，是我的弱小所致，她如果要恨的話，恨的也只應該是我。",
  ui_story_70000602_47_dialog_content = "她終究還是對其他人下了手......",
  ui_story_70000602_48_dialog_content = "舒默、我，還有那麼多無辜的人們......",
  ui_story_70000602_49_dialog_content = "對，所以這是她犯下的罪行。",
  ui_story_70000602_50_dialog_content = "她要為此付出代價。",
  ui_story_70000602_51_dialog_content = "嗯，我也同意。這兩件事要分開來看。",
  ui_story_70000602_51X1_dialog_content = "不過，有時候我也會想......",
  ui_story_70000602_51X2_dialog_content = "如果他們沒有參加「委員會」的培養計畫，沒有參加那場堪稱慘烈的戰鬥。",
  ui_story_70000602_51X3_dialog_content = "他們現在是不是不會變成暗鬼，而是能有更好的生活？",
  ui_story_70000602_52_dialog_content = "你們參加的到底是什麼訓練啊......",
  ui_story_70000602_52X1_dialog_content = "怎麼聽起來不像是正常人能夠承受的？",
  ui_story_70000602_53_dialog_content = "委員會的培養計畫可不只是單純的<color=#FFB400>「訓練」</color>。",
  ui_story_70000602_54_dialog_content = "你們三個......都參加過那個什麼「委員會」組織的訓練？",
  ui_story_70000602_55_dialog_content = "委員會的培養計畫可不只是單純的訓練。",
  ui_story_70000602_56_dialog_content = "有些時候甚至需要拼上性命。",
  ui_story_70000602_57_dialog_content = "聽上去真殘酷......",
  ui_story_70000602_58_dialog_content = "啟光......非要通過這種方式選出大元帥不可嗎？",
  ui_story_70000602_59_dialog_content = "對於啟光人來說，「大元帥」就像是黑暗中的火炬。",
  ui_story_70000602_60_dialog_content = "只有最強大的火焰才能照亮每個角落，讓每個身處絕境中的人都能看到希望。",
  ui_story_70000602_61_dialog_content = "看到了希望，啟光的人們才能團結一心，在這艱難困苦的世界上不斷前行。",
  ui_story_70000602_62_dialog_content = "但是......想要等到世界上誕生一個強大的個體，等到死恐怕都等不來一個。",
  ui_story_70000602_63_dialog_content = "所以，就算不得不歷盡苦難與折磨，我也想成為啟光的大元帥。",
  ui_story_70000602_63X_dialog_content = "成為最強大的那個存在。",
  ui_story_70000602_64_dialog_content = "……",
  ui_story_70000602_65_dialog_content = "小子，不用露出那種表情。",
  ui_story_70000602_66_dialog_content = "那句話怎麼說來著——",
  ui_story_70000602_67_dialog_content = "「欲戴其冠，必承其重」。",
  ui_story_70000602_68_dialog_content = "你放心，天塌下來的時候，有高個子頂著呢。",
  ui_story_70000602_69_dialog_content = "同樣的，啟光遭遇麻煩時，也有大元帥頂著呢。",
  ui_story_70000602_70_dialog_content = "你也包括在內。",
  ui_story_70000602_71_dialog_content = "我們到了。",
  ui_story_70000701_1_dialog_content = "這裡似乎是地下城的淺層，和我們剛剛進來時所在的區域很像。",
  ui_story_70000701_2_dialog_content = "但是剛才在逃生通道裡兜兜轉轉一大圈，繞得我有點暈頭轉向，分不太清方向了......",
  ui_story_70000701_3_dialog_content = "PlayerName，這里和我們進來的地方並不相同喔。",
  ui_story_70000701_4_dialog_content = "甚至可以說......是背道而馳的兩個方向。",
  ui_story_70000701_5_dialog_content = "咦？！",
  ui_story_70000701_6_dialog_content = "很難嗎？從天花板上的管路排布和功能區域的劃分就可以看出來，另外通風管道的走向也——",
  ui_story_70000701_7_dialog_content = "（薇絲又滔滔不絕地講起我聽不懂的事情了呢......）",
  ui_story_70000701_8_dialog_content = "呃......我，我有一個問題！",
  ui_story_70000701_9_dialog_content = "莫非旺盛的好奇心也是空裔一族的特徵？",
  ui_story_70000701_10_dialog_content = "對不起！最後一個，真的是最後一個了！",
  ui_story_70000701_11_dialog_content = "沒關係，好奇心旺盛不是什麼壞事，你問吧。",
  ui_story_70000701_12_dialog_content = "剛才那個逃掉的高級暗鬼......之前是萊因哈特的戰友吧？",
  ui_story_70000701_13_dialog_content = "為什麼他會變成那樣？",
  ui_story_70000701_14_dialog_content = "難道這也是吞羅的所作所為？不過我好像沒在牠身上感應到有「種子」的痕跡。",
  ui_story_70000701_15_dialog_content = "我只能說，我不知道。",
  ui_story_70000701_16_dialog_content = "當年的戰況太慘烈，以至於我們都以為，他已經死去了。",
  ui_story_70000701_17_dialog_content = "當年......究竟發生了什麼？",
  ui_story_70000701_18_dialog_content = "……",
  ui_story_70000701_19_dialog_content = "那時候，我們這種被當成大元帥後補培養的士兵都屬於一支特殊的隊伍。",
  ui_story_70000701_20_dialog_content = "十一年前，我們接到了委員會的命令，前往早已廢棄的80號地下城找回遺落的科技物品。",
  ui_story_70000701_21_dialog_content = "當時的情報是，80號地下城雖然處於暗能的影響範圍之下，但是暗鬼並不多。",
  ui_story_70000701_22_dialog_content = "因此我們做了和你同樣的決定——輕裝上陣。",
  ui_story_70000701_22X_dialog_content = "趁著短暫的白天進入地下城，取得目標後迅速返回。",
  ui_story_70000701_23_dialog_content = "但是......實際情況與情報出現了嚴重的偏差。",
  ui_story_70000701_24_dialog_content = "不行，暗鬼太多了！",
  ui_story_70000701_25_dialog_content = "請求支援！請求——",
  ui_story_70000701_26_dialog_content = "地下城中的暗鬼多得像罐頭里的魚，不管消滅多少，仍在源源不斷地湧出來。",
  ui_story_70000701_27_dialog_content = "光是到達目標倉庫，我們就已經損失了將近兩成的隊友。",
  ui_story_70000701_28_dialog_content = "所以，我們在倉庫區看到的那些防禦工事和裝備殘骸......",
  ui_story_70000701_29_dialog_content = "都是那些英勇的士兵的遺物。",
  ui_story_70000701_30_dialog_content = "……",
  ui_story_70000701_31_dialog_content = "而當我們拿上所有目標物資，準備撤退的時候......",
  ui_story_70000701_32_dialog_content = "天黑了。",
  ui_story_70000701_33_dialog_content = "更多強大的暗鬼像是被什麼吸引了一樣，湧向這80號地下城......",
  ui_story_70000701_34_dialog_content = "就像現在發生的一樣。",
  ui_story_70000701_35_dialog_content = "吼——！！！",
  ui_story_70000701_36_dialog_content = "薇絲，PlayerName，準備戰鬥！",
  ui_story_70000702_1_dialog_content = "吼……",
  ui_story_70000702_2_dialog_content = "戰鬥結束！",
  ui_story_70000702_3_dialog_content = "附近......暫時沒有敵人了。",
  ui_story_70000702_4_dialog_content = "薇絲！",
  ui_story_70000702_5_dialog_content = "呃......身體，好重......",
  ui_story_70000702_6_dialog_content = "現在正是午夜，暗能最重的時候。",
  ui_story_70000702_7_dialog_content = "你們兩個的情況已經算不錯了，當年我們來到這裡時，有不少人都直接昏了過去。",
  ui_story_70000702_8_dialog_content = "那時候，我們還要面對比剛才多上百倍、上千倍的暗鬼......",
  ui_story_70000702_9_dialog_content = "<color=#e8d9bb>「暗面戰爭」時期</color>",
  ui_story_70000702_10_dialog_content = "注意三點鐘方向！",
  ui_story_70000702_11_dialog_content = "吼！ ！ ！",
  ui_story_70000702_12_dialog_content = "<color=#e8d9bb>噠噠噠——！</color>",
  ui_story_70000702_13_dialog_content = "目標消滅！",
  ui_story_70000702_14_dialog_content = "十點鐘方向，出現高級暗鬼！",
  ui_story_70000702_15_dialog_content = "數量......一，二......不行，太多了！",
  ui_story_70000702_16_dialog_content = "需要火力支援！",
  ui_story_70000702_17_dialog_content = "休想從這裡通過！",
  ui_story_70000702_18_dialog_content = "嗷——",
  ui_story_70000702_19_dialog_content = "情報裡可沒說這裡有這麼多暗鬼啊！",
  ui_story_70000702_20_dialog_content = "委員會提供的情報，也會有誤嗎......",
  ui_story_70000702_21_dialog_content = "這種情況還是想盡量避免啊......但是，既然已經發生了，就只能想辦法帶著拿到的資料逃出去！",
  ui_story_70000702_22_dialog_content = "之後的事，你也能猜個八九不離十吧？",
  ui_story_70000702_23_dialog_content = "地下城內的暗能阻斷了通訊訊號，所以我擔負起了突圍求援的責任。",
  ui_story_70000702_24_dialog_content = "當我返回安全線求援時，地下城......已經完全淪陷，並且發生了崩塌。",
  ui_story_70000702_25_dialog_content = "在那樣的情景中，前往被暗鬼包圍的地下城、一邊戰鬥一邊挖掘救人......",
  ui_story_70000702_26_dialog_content = "要付出的代價可想而知，而收獲卻少之又少，甚至可能為零。",
  ui_story_70000702_27_dialog_content = "在經過考量後，啟光方面最終決定放棄救援。",
  ui_story_70000702_28_option_content = "怎麼可以這樣......",
  ui_story_70000702_29_dialog_content = "他們明明都是啟光的士兵，都是鮮活的生命......",
  ui_story_70000702_30_dialog_content = "為什麼，為什麼要放棄他們？",
  ui_story_70000702_31_dialog_content = "……",
  ui_story_70000702_32_dialog_content = "這個問題也曾困擾了我很長時間，你想不明白是正常的。",
  ui_story_70000702_33_dialog_content = "當時進入地下城裡的、我所在的那支部隊，是整個啟光裝備最精良、火力最強大的隊伍。",
  ui_story_70000702_34_dialog_content = "連我們都無法在80號地下城取得勝利，就更別說守衛安全線的啟光常規軍隊了。",
  ui_story_70000702_35_dialog_content = "被困地下的是我的戰友，我當然不願意看到他們死去。",
  ui_story_70000702_36_dialog_content = "但那些比我們更弱小的普通啟光士兵，他們不同樣也是我的戰友嗎？",
  ui_story_70000702_37_dialog_content = "如果必須犧牲十個人才能讓一個人活著回來，你會做交換嗎？",
  ui_story_70000702_38_dialog_content = "我......",
  ui_story_70000702_39_dialog_content = "你也能理解吧，每個人都有著自己的家人、朋友，有著自己的珍視之物。",
  ui_story_70000702_40_dialog_content = "暗面的影響對我來說可能只是一點點負重，但對普通人來說，就如同缺氧般危險。",
  ui_story_70000702_41_dialog_content = "再加上那些洶湧如潮水的暗鬼......",
  ui_story_70000702_42_dialog_content = "暗面危機四伏的環境讓「我們」都損失慘重，更何況是他們呢。",
  ui_story_70000702_43_option_content = "原來如此……",
  ui_story_70000702_44_dialog_content = "你能理解就好。",
  ui_story_70000702_45_option_content = "我還是不認同",
  ui_story_70000702_46_dialog_content = "不論如何，我都不會放棄自己的夥伴。",
  ui_story_70000702_47_dialog_content = "絕對不會。",
  ui_story_70000702_48_dialog_content = "我不強求你理解，但我希望你知道——",
  ui_story_70000702_49_dialog_content = "作為啟光的大元帥，我做出決斷的時候，考慮的是所有啟光人。",
  ui_story_70000702_50_dialog_content = "……",
  ui_story_70000702_51_dialog_content = "（糟了，我是不是......讓話題變得太沉重了？）",
  ui_story_70000702_52_dialog_content = "嗯......這，這條路還挺好走的......？",
  ui_story_70000702_53_dialog_content = "那是當然。",
  ui_story_70000702_54_dialog_content = "這條路，是當年的我們付出無數流血犧牲才開拓出來的。",
  ui_story_70000702_55_dialog_content = "而我也是踏著他們的鮮血，最終才得以逃脫。",
  ui_story_70000702_56_dialog_content = "<color=#e8d9bb>叮鈴鈴——</color>",
  ui_story_70000702_57_dialog_content = "PlayerName，你聽到了嗎？",
  ui_story_70000702_58_dialog_content = "又是那個鈴聲！",
  ui_story_70000702_59_dialog_content = "我聽到了！這次很近！",
  ui_story_70000702_60_dialog_content = "那個高級暗鬼，聽見鈴聲的時候立刻跑掉了......",
  ui_story_70000702_61_dialog_content = "牠會在這附近嗎？",
  ui_story_70000702_62_dialog_content = "可惡，要是這裡的暗能再輕一些，我就可以使用感應能力了......",
  ui_story_70000702_63_dialog_content = "感應不到也沒關係，那傢伙一定就在鈴聲的附近。",
  ui_story_70000702_64_dialog_content = "萊因哈特大元帥為什麼這麼肯定？",
  ui_story_70000702_65_dialog_content = "當年我突圍離開的時候，和他們立下約定。",
  ui_story_70000702_66_dialog_content = "如果我成功帶來援軍，就會通知你們撤離。",
  ui_story_70000702_67_dialog_content = "撤離的時機......按照老樣子，以鈴聲為號。",
  ui_story_70000702_68_dialog_content = "嗯，知道了。",
  ui_story_70000702_69_dialog_content = "放心吧，我們一定能撐得住。",
  ui_story_70000702_70_dialog_content = "就算變成暗鬼，我也會等到救援的鈴聲響起！",
  ui_story_70000702_71_dialog_content = "好……",
  ui_story_70000702_72_dialog_content = "聽到鈴聲的時候，就向外衝吧！",
  ui_story_70000702_73_dialog_content = "沒想到那傢伙隨便開的玩笑，最終竟然成了真的。",
  ui_story_70000702_74_dialog_content = "這個烏鴉嘴。",
  ui_story_70000702_75_dialog_content = "所以......牠一直記得最初的約定？",
  ui_story_70000702_76_dialog_content = "也有可能，「他」已經失去了理性，只將那句話當成了某種本能。",
  ui_story_70000702_77_dialog_content = "……",
  ui_story_70000702_78_dialog_content = "……",
  ui_story_70000702_79_dialog_content = "做好戰鬥準備吧，「他」說不定就在前面。",
  ui_story_70000702_80_dialog_content = "讓我最後再試一次吧......",
  ui_story_70000702_81_dialog_content = "我已經錯失了上一次拯救他的機會，這次，我不會再放過。",
  ui_story_70000801_1_dialog_content = "<color=#e8d9bb>叮鈴鈴——</color>",
  ui_story_70000801_2_dialog_content = "終於出來了！",
  ui_story_70000801_3_dialog_content = "呃......但是，暗能的壓迫感卻絲毫沒有減輕。",
  ui_story_70000801_4_dialog_content = "PlayerName，別太勉強。",
  ui_story_70000801_5_dialog_content = "我來扶你。",
  ui_story_70000801_6_dialog_content = "<color=#e8d9bb>叮鈴鈴——</color>",
  ui_story_70000801_7_dialog_content = "那個鈴聲，很近了......",
  ui_story_70000801_8_dialog_content = "在那——",
  ui_story_70000801_9_dialog_content = "吼……",
  ui_story_70000801_10_dialog_content = "牠好像在尋找鈴聲的源頭？",
  ui_story_70000801_11_dialog_content = "但是，牠的周圍都是暗鬼。",
  ui_story_70000801_12_dialog_content = "要在這種情況下接近牠嗎？",
  ui_story_70000801_13_dialog_content = "這是我的私人請求，請再幫我爭取五分鐘時間。",
  ui_story_70000801_14_dialog_content = "我想最後試一次。",
  ui_story_70000801_15_dialog_content = "五分鐘一到，大家就一起撤離。",
  ui_story_70000801_16_dialog_content = "我會幫忙的！",
  ui_story_70000801_17_dialog_content = "PlayerName呢？",
  ui_story_70000801_18_dialog_content = "也算我一個吧。",
  ui_story_70000801_19_dialog_content = "這一次，一定要把他救回來！",
  ui_story_70000801_20_dialog_content = "呵呵，那就好好看著吧。",
  ui_story_70000801_21_dialog_content = "見證啟光的意志。",
  ui_story_70000801_22_dialog_content = "那麼，還是老樣子，我們分頭行動。",
  ui_story_70000801_23_dialog_content = "薇絲，我們到暗鬼的另一邊去。",
  ui_story_70000801_24_dialog_content = "好。",
  ui_story_70000801_25_dialog_content = "這個位置應該沒問題了！",
  ui_story_70000801_26_dialog_content = "好，萊因哈特那邊也準備好了。",
  ui_story_70000801_27_dialog_content = "那麼……",
  ui_story_70000801_28_dialog_content = "你們這群暗鬼雜魚，有本事來抓我啊！！！",
  ui_story_70000801_29_dialog_content = "吼......？",
  ui_story_70000801_30_dialog_content = "吼——！！！",
  ui_story_70000801_31_dialog_content = "噫！",
  ui_story_70000801_32_dialog_content = "怎麼這麼多？！",
  ui_story_70000801_33_dialog_content = "PlayerName！堅持住！！！",
  ui_story_70000802_1_dialog_content = "你已經忘記了嗎？",
  ui_story_70000802_2_dialog_content = "啟光的夢想。",
  ui_story_70000802_3_dialog_content = "啟光的信念。",
  ui_story_70000802_4_dialog_content = "啟光的榮耀。",
  ui_story_70000802_5_dialog_content = "這些屬於啟光的記憶......",
  ui_story_70000802_6_dialog_content = "難道你都忘記了嗎？！",
  ui_story_70000802_7_dialog_content = "吼！ ！ ！",
  ui_story_70000802_8_dialog_content = "告訴我......",
  ui_story_70000802_9_dialog_content = "你為什麼要背棄光明，投身黑暗？",
  ui_story_70000802_10_dialog_content = "難道是為了活下去嗎？！",
  ui_story_70000802_11_dialog_content = "還是說受到了別人的教唆？",
  ui_story_70000802_12_dialog_content = "告訴我——",
  ui_story_70000802_13_dialog_content = "<size=45>你的答案！</size>",
  ui_story_70000802_14_dialog_content = "吼——！",
  ui_story_70000802_15_dialog_content = "<color=#e8d9bb>叮鈴鈴——</color>",
  ui_story_70000802_16_dialog_content = "......！",
  ui_story_70000802_17_dialog_content = "又是鈴聲！",
  ui_story_70000802_18_dialog_content = "這次非常近了，就在......那邊！",
  ui_story_70000802_19_dialog_content = "<color=#e8d9bb>叮鈴鈴——</color>",
  ui_story_70000802_20_dialog_content = "那是——",
  ui_story_70000802_21_dialog_content = "吞羅——？！",
  ui_story_70000802_22_dialog_content = "……",
  ui_story_70000802_23_dialog_content = "多年不見，妳的話變多了——",
  ui_story_70000802_24_dialog_content = "萊因哈特。",
  ui_story_70000802_25_dialog_content = "德尼耶爾......不，吞羅。",
  ui_story_70000802_26_dialog_content = "赫利俄斯變成這樣，也是妳的所作所為嗎？",
  ui_story_70000802_27_dialog_content = "關於這件事，我知道的並不比妳多。",
  ui_story_70000802_28_dialog_content = "但不可否認，這是一件不錯的實驗材料。",
  ui_story_70000802_29_dialog_content = "那他變成這個樣子的原因究竟是......",
  ui_story_70000802_30_dialog_content = "妳還不明白嗎？",
  ui_story_70000802_31_dialog_content = "他並不是忘記了什麼。",
  ui_story_70000802_32_dialog_content = "他只是......記得太清楚了。",
  ui_story_70000802_33_dialog_content = "……？！",
  ui_story_70000802_34_dialog_content = "可悲的棄子，他唯一忘記的，反而是對啟光的怨恨。",
  ui_story_70000802_35_dialog_content = "現在，是時候想起來了！",
  ui_story_70000802_36_dialog_content = "<size=45>嘎嗷——！</size>",
  ui_story_70000802_37_dialog_content = "呃——！",
  ui_story_70000802_38_dialog_content = "這是，記憶？！",
  ui_story_70000802_39_dialog_content = "距離萊因哈特突圍已經過去四個小時了......",
  ui_story_70000802_40_dialog_content = "還是沒有聽見「鈴聲」。",
  ui_story_70000802_41_dialog_content = "我還有一些力氣，哪怕只用這雙拳頭，也能讓暗鬼吃點苦頭。",
  ui_story_70000802_42_dialog_content = "妳呢？還有多少補給和彈藥？",
  ui_story_70000802_43_dialog_content = "還剩十發子彈和......兩塊鋸末麵包。",
  ui_story_70000802_44_dialog_content = "早知這樣，我當初就該留在迦南城應付那些繁瑣的實驗室規章制度。",
  ui_story_70000802_45_dialog_content = "相比起步槍和子彈，我還是更擅長用解剖刀對付暗鬼。",
  ui_story_70000802_46_dialog_content = "哈哈，不愧是備受矚目的研究員。",
  ui_story_70000802_47_dialog_content = "我猜妳還能用縫合線在暗鬼身上打個蝴蝶結。",
  ui_story_70000802_48_dialog_content = "呵，你心態真好。",
  ui_story_70000802_49_dialog_content = "只是我們能堅持多久呢？",
  ui_story_70000802_50_dialog_content = "還是說......我們已經成了棄子？",
  ui_story_70000802_51_dialog_content = "……",
  ui_story_70000802_52_dialog_content = "不論如何，不能放棄活下去的希望。",
  ui_story_70000802_53_dialog_content = "萊因哈特......她一定會帶啟光的援軍來救我們的。",
  ui_story_70000802_54_dialog_content = "在那之前，我們要先想辦法保護自己。",
  ui_story_70000802_55_dialog_content = "看啊，前面就是出口！",
  ui_story_70000802_56_dialog_content = "附近徘徊的暗鬼很多啊，而且......",
  ui_story_70000802_57_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_70000802_58_dialog_content = "上一次的戰鬥動靜太大，這裡看起來馬上要塌了。",
  ui_story_70000802_59_dialog_content = "現在還是天亮，是那些暗鬼實力最弱的時候。",
  ui_story_70000802_60_dialog_content = "再不逃出去，我們就真要困死在這裡了。",
  ui_story_70000802_61_dialog_content = "妳跟緊我，趁著暗鬼遊蕩到遠端，我們突圍。",
  ui_story_70000802_62_dialog_content = "十一點方向！",
  ui_story_70000802_63_dialog_content = "知道了！",
  ui_story_70000802_64_dialog_content = "該死的......怎麼沒完沒了！",
  ui_story_70000802_65_dialog_content = "我還頂得住！德尼耶爾，向出口移動！",
  ui_story_70000802_66_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_70000802_67_dialog_content = "地面裂開了，小心！",
  ui_story_70000802_68_dialog_content = "啊——！",
  ui_story_70000802_69_dialog_content = "赫利俄斯！！！",
  ui_story_70000802_70_dialog_content = "我必須......活下去。",
  ui_story_70000802_71_dialog_content = "要等到......支援。",
  ui_story_70000802_72_dialog_content = "過了多少天呢......",
  ui_story_70000802_73_dialog_content = "身體......似乎出現了不太好的變化......",
  ui_story_70000802_74_dialog_content = "鈴聲啊......快點響起吧......",
  ui_story_70000802_75_dialog_content = "一天......兩天......",
  ui_story_70000802_76_dialog_content = "一年......兩年......",
  ui_story_70000802_77_dialog_content = "為什麼支援還沒有到來......",
  ui_story_70000802_78_dialog_content = "為什麼要放棄我？？？",
  ui_story_70000802_79_dialog_content = "吼——！！！",
  ui_story_70000802_80_dialog_content = "看來你已經想起來了。",
  ui_story_70000802_81_dialog_content = "但是，還不夠。",
  ui_story_70000802_82_dialog_content = "就像「種子」一樣，憤怒是最好的養料......",
  ui_story_70000802_83_dialog_content = "就讓我再推你一把吧。",
  ui_story_70000802_84_dialog_content = "吞羅，妳要做什麼？！",
  ui_story_70000802_85_dialog_content = "……",
  ui_story_70000802_86_dialog_content = "萊因哈特......",
  ui_story_70000802_87_dialog_content = "妳......為什麼沒有帶回支援？",
  ui_story_70000802_88_dialog_content = "因為……",
  ui_story_70000802_89_dialog_content = "在當時的局面下，犧牲你們是最好的選擇。",
  ui_story_70000802_90_dialog_content = "妳果然還是——",
  ui_story_70000802_91_dialog_content = "毫無長進。",
  ui_story_70000802_92_dialog_content = "妳和啟光，都是如此。",
  ui_story_70000802_93_dialog_content = "吼——！！！",
  ui_story_70000802_94_dialog_content = "小心！牠朝這邊來了！",
  ui_story_70000802_95_dialog_content = "憤怒吧，然後......成長。",
  ui_story_70000802_96_dialog_content = "在這暗面之中，吞噬一切。",
  ui_story_70000802_97_dialog_content = "吼——！！！",
  ui_story_70000802_98_dialog_content = "也是時候為這件事畫上句號了。",
  ui_story_70000802_99_dialog_content = "薇絲，準備戰鬥！",
  ui_story_70000802_100_dialog_content = "是！",
  ui_story_70000902_1_dialog_content = "嘎嗷......",
  ui_story_70000902_2_dialog_content = "就算在這種情況下，還是被壓制了嗎？",
  ui_story_70000902_3_dialog_content = "終究只是個<color=#FFB400>「殘次品」</color>罷了。",
  ui_story_70000902_4_dialog_content = "不過，還能活動這一點倒是超出了實驗預期。",
  ui_story_70000902_5_dialog_content = "說明多少還有點價值。",
  ui_story_70000902_6_dialog_content = "但，我的時間也是有限的。",
  ui_story_70000902_7_dialog_content = "呃——！",
  ui_story_70000902_8_dialog_content = "周圍的暗能......竟然都凝聚過來了！",
  ui_story_70000902_9_dialog_content = "暗能......太重了！不行！",
  ui_story_70000902_10_dialog_content = "咳、幾年不見，妳倒是從一個文弱的研究員變得能打起來了。",
  ui_story_70000902_11_dialog_content = "住嘴。",
  ui_story_70000902_12_dialog_content = "弱者，就應該跪伏於地。",
  ui_story_70000902_13_dialog_content = "至於你，就用這些暗能發揮出你最後的價值吧。",
  ui_story_70000902_14_dialog_content = "吼——！！！",
  ui_story_70000902_15_dialog_content = "暗鬼......在......消散！",
  ui_story_70000902_16_dialog_content = "嘎嗷——！",
  ui_story_70000902_17_dialog_content = "這些......慘叫！",
  ui_story_70000902_18_dialog_content = "吞羅在吸取他們的......生命力，吸取暗能！",
  ui_story_70000902_19_dialog_content = "這麼強大的暗能，如果轉化成攻擊......",
  ui_story_70000902_20_dialog_content = "哪怕只是單純的爆炸，整個地下城......也都會灰飛煙滅的！",
  ui_story_70000902_21_dialog_content = "萊因哈特，小心！",
  ui_story_70000902_22_dialog_content = "......！",
  ui_story_70000902_23_dialog_content = "PlayerName，快找掩護！！！",
  ui_story_70000902_24_dialog_content = "太慢了。",
  ui_story_70000902_25_dialog_content = "（那是我見過最絕望的畫面。）",
  ui_story_70000902_26_dialog_content = "（鋪天蓋地的暗能裹挾著永夜的黑暗，如同海嘯一樣吼叫著、沖刷著地上的一切。）",
  ui_story_70000902_27_dialog_content = "（面對這樣強大的威壓，我和薇絲像是身負巨石，甚至無法站立。）",
  ui_story_70000902_28_dialog_content = "（我只能勉強抬起頭，看著暗能吞沒自己。）",
  ui_story_70000902_29_dialog_content = "然後，在那至暗的黑夜中——",
  ui_story_70000902_30_dialog_content = "我看到了<color=#FFB400>光</color>。",
  ui_story_70000902_31_dialog_content = "我，不會讓你們得逞。",
  ui_story_70000902_32_dialog_content = "萊因哈特？！",
  ui_story_70000902_33_dialog_content = "（在永夜的籠罩下，那道光算不上明亮，甚至隨時會被吞沒。）",
  ui_story_70000902_34_dialog_content = "（但那光仍舊倔強地照耀著，向四周散發光芒。）",
  ui_story_70000902_35_dialog_content = "（就像即將躍出地平線的太陽，泛白的天空昭示著黎明。）",
  ui_story_70000902_36_dialog_content = "區區......暗能罷了。",
  ui_story_70000902_37_dialog_content = "我身上肩負的，可是啟明之光！",
  ui_story_70000902_38_dialog_content = "在啟光，天塌了有我頂著——！",
  ui_story_70000902_39_dialog_content = "（黑暗，被逐漸驅散。）",
  ui_story_70000902_40_dialog_content = "（光芒，便貫穿天際。）",
  ui_story_70000902_41_dialog_content = "呃！！！",
  ui_story_70000902_42_dialog_content = "......！",
  ui_story_70000902_43_dialog_content = "萊因哈特！！",
  ui_story_70000902_44_dialog_content = "竟然完全放棄了防禦，選擇了不要命的進攻嗎。",
  ui_story_70000902_45_dialog_content = "就算這樣也能擋下大部分攻擊......",
  ui_story_70000902_46_dialog_content = "呵呵，妳還真是個瘋子。",
  ui_story_70000902_47_dialog_content = "愚蠢......又瘋狂。",
  ui_story_70000902_48_dialog_content = "這種力量倒是符合實驗預期。",
  ui_story_70000902_49_dialog_content = "如果是普通的光靈，直面暗能的壓迫，恐怕早就瘋了吧。",
  ui_story_70000902_50_dialog_content = "不愧是妳。",
  ui_story_70000902_51_dialog_content = "不愧是活著走出泥潭的、最傑出的「怪物」。",
  ui_story_70000902_52_dialog_content = "那些傢伙把妳「教」得真好啊。",
  ui_story_70000902_53_dialog_content = "呵，彼此彼此。",
  ui_story_70000902_54_dialog_content = "明明擁有這種程度的技術，卻止步不前，滿足於扮演英雄的兒戲。",
  ui_story_70000902_55_dialog_content = "而妳......看起來還滿沉浸於其中的。",
  ui_story_70000902_56_dialog_content = "因為這是我們三個最初的夢想啊......",
  ui_story_70000902_57_dialog_content = "成為啟光的大元帥，帶領啟光的人們尋找更好的生活。",
  ui_story_70000902_58_dialog_content = "為了啟光，為了人們......",
  ui_story_70000902_59_dialog_content = "說得真好聽，但是他們除了向妳索取，祈求妳的庇護，還會為妳做什麼嗎？",
  ui_story_70000902_60_dialog_content = "在他們眼中，妳只不過是一個具象化的符號，用完了隨時可以丟掉。",
  ui_story_70000902_61_dialog_content = "這樣看來，妳和那些實驗動物也沒什麼區別。",
  ui_story_70000902_62_dialog_content = "研究員在意的永遠只有從動物身上得到的實驗數據。",
  ui_story_70000902_63_dialog_content = "而那些傢伙在意的則是......一個看起來強大的形象，至於這個形象放在誰身上都無所謂。",
  ui_story_70000902_64_dialog_content = "呵呵……",
  ui_story_70000902_65_dialog_content = "哈哈哈——",
  ui_story_70000902_66_dialog_content = "吞羅，不，德尼耶爾......",
  ui_story_70000902_67_dialog_content = "妳也變得話多了啊。",
  ui_story_70000902_68_dialog_content = "我記得過去的妳只知道把自己關在實驗室裡，埋頭苦讀。",
  ui_story_70000902_69_dialog_content = "不管我跟妳說什麼，妳只會說——妳要證明自己是最優秀的。",
  ui_story_70000902_70_dialog_content = "……",
  ui_story_70000902_71_dialog_content = "那個時候的妳，從來不會在意別人怎麼看待自己。",
  ui_story_70000902_72_dialog_content = "我也一樣。我是啟光的大元帥，所以我會守護啟光，守護啟光的人們。",
  ui_story_70000902_73_dialog_content = "至於啟光的人們怎麼看待我，我不在乎。",
  ui_story_70000902_74_dialog_content = "這一點，我可是跟妳學的。",
  ui_story_70000902_75_dialog_content = "……",
  ui_story_70000902_76_dialog_content = "我會在關於妳的研究記錄上多加一個標籤——瘋子。",
  ui_story_70000902_77_dialog_content = "既然材料已經到手，那也是時候回去繼續實驗了。",
  ui_story_70000902_78_dialog_content = "吞......羅......",
  ui_story_70000902_79_dialog_content = "蟲子的生命力還真是頑強。",
  ui_story_70000902_80_dialog_content = "不像這個失敗的實驗品......",
  ui_story_70000902_81_dialog_content = "……",
  ui_story_70000902_82_dialog_content = "到極限了嗎......",
  ui_story_70000902_83_dialog_content = "但是，已經勉強能作為研究的材料了。",
  ui_story_70000902_84_dialog_content = "既不屬於光靈，也不屬於暗鬼。",
  ui_story_70000902_85_dialog_content = "只不過是個......還有點利用價值的半吊子罷了。",
  ui_story_70000902_86_dialog_content = "妳想做什麼？把他放下！",
  ui_story_70000902_87_dialog_content = "以妳現在的樣子，能阻止得了我？",
  ui_story_70000902_88_dialog_content = "「是時候了。」",
  ui_story_70000902_89_dialog_content = "遠處的地平線上......傳來了震動和煙塵......？",
  ui_story_70000902_90_dialog_content = "PlayerName，那些......是什麼？",
  ui_story_70000902_91_dialog_content = "不知道，我試試看......",
  ui_story_70000902_92_option_content = "強制感應！",
  ui_story_70000902_93_dialog_content = "......！",
  ui_story_70000902_94_dialog_content = "（這是......暗鬼？！）",
  ui_story_70000902_95_dialog_content = "（一支......暗鬼大軍！）",
  ui_story_70000902_96_dialog_content = "（日蝕語）支援......吞羅！",
  ui_story_70000902_97_dialog_content = "（牠們的目標是這裡？！）",
  ui_story_70000902_98_dialog_content = "（數量太多了，就算有萊因哈特......）",
  ui_story_70000902_99_dialog_content = "（不，她剛剛的捨命一擊也讓自己身受重傷。）",
  ui_story_70000902_100_dialog_content = "（能堅持到現在，恐怕只是在靠意志逞強！）",
  ui_story_70000902_101_dialog_content = "（必須立刻撤退！）",
  ui_story_70000902_102_dialog_content = "萊因哈特！情況很嚴重！",
  ui_story_70000902_103_dialog_content = "什麼？",
  ui_story_70000902_104_dialog_content = "我感應到了大量的暗鬼！牠們馬上就要到這裡了！",
  ui_story_70000902_105_dialog_content = "其中還有非常強大的個體！",
  ui_story_70000902_106_dialog_content = "我們必須立刻撤離！",
  ui_story_70000902_107_dialog_content = "只要三分鐘就好，我會解決一切！",
  ui_story_70000902_108_dialog_content = "吼——！！！",
  ui_story_70000902_109_dialog_content = "來不及了，萊因哈特！",
  ui_story_70000902_110_dialog_content = "再拖下去......我們會被包圍！",
  ui_story_70000902_111_dialog_content = "……",
  ui_story_70000902_112_dialog_content = "「第3條：在「泥潭」作戰時，盡量避免戰鬥，量力而行！」",
  ui_story_70000902_113_dialog_content = "…………",
  ui_story_70000902_114_dialog_content = "弱者。",
  ui_story_70000902_115_dialog_content = "妳心裡應該清楚，他是我們共同的戰友。",
  ui_story_70000902_116_dialog_content = "如果妳敢傷害他，傷害啟光的軍人，我會讓妳付出代價。",
  ui_story_70000902_117_dialog_content = "呵。",
  ui_story_70000902_118_dialog_content = "等妳活下來，再對我說這種大話吧。",
  ui_story_70000902_119_dialog_content = "現在的妳，沒有選擇的資格。",
  ui_story_70000902_120_dialog_content = "……",
  ui_story_70000902_121_dialog_content = "薇絲，PlayerName，我們撤。",
  ui_story_70000902_122_dialog_content = "……",
  ui_story_70000902_123_dialog_content = "妳的時間不多了——",
  ui_story_70000902_124_dialog_content = "「姐姐」。",
  ui_story_70001001_1_dialog_content = "薇絲，妳扶著萊因哈特，我去啟動巨像！",
  ui_story_70001001_2_dialog_content = "好！",
  ui_story_70001001_3_dialog_content = "已經......起飛了嗎？",
  ui_story_70001001_4_dialog_content = "是的！我們已經起飛了！",
  ui_story_70001001_5_dialog_content = "幸虧起飛得及時，我們才沒有被暗鬼淹沒......",
  ui_story_70001001_6_dialog_content = "全速......返回......",
  ui_story_70001001_7_dialog_content = "萊因哈特大元帥？！",
  ui_story_70001001_8_dialog_content = "她傷得太重了，一定是從剛才開始就在逞強。",
  ui_story_70001001_9_dialog_content = "PlayerName，你去駕駛臨空者號，我去找急救用品！",
  ui_story_70001001_10_dialog_content = "好！",
  ui_story_70001001_11_dialog_content = "萊因哈特，撐住啊......",
  ui_story_70001001_12_dialog_content = "呃……",
  ui_story_70001001_13_dialog_content = "不行......大元帥的狀態很差。",
  ui_story_70001001_14_dialog_content = "她需要立刻治療！",
  ui_story_70001001_15_dialog_content = "<color=#e8d9bb>「檢測到關鍵詞——治療。」</color>",
  ui_story_70001001_16_dialog_content = "<color=#e8d9bb>「正在掃描相關數據......掃描完畢。」</color>",
  ui_story_70001001_17_dialog_content = "<color=#e8d9bb>「掃描結果：意識模組修復器中存有升級數據。」</color>",
  ui_story_70001001_18_dialog_content = "<color=#e8d9bb>「安裝意識模組修復器，可將維生系統升級為醫療系統。」</color>",
  ui_story_70001001_19_option_content = "臨空者號？",
  ui_story_70001001_20_dialog_content = "突然啟動了？！",
  ui_story_70001001_21_dialog_content = "意識模組修復器......是指這個？對啊，我怎麼把它忘了！",
  ui_story_70001001_22_dialog_content = "既然叫醫療系統，或許能對萊因哈特有幫助。",
  ui_story_70001001_23_dialog_content = "先裝上試試吧！",
  ui_story_70001001_24_dialog_content = "<color=#e8d9bb>「檢測到意識模組修復器。」</color>",
  ui_story_70001001_25_dialog_content = "<color=#e8d9bb>「連接中......完成。」</color>",
  ui_story_70001001_26_dialog_content = "<color=#e8d9bb>「優先級判定......完成。」</color>",
  ui_story_70001001_27_dialog_content = "<color=#e8d9bb>「檢測到維生系統升級數據，開始執行升級。」</color>",
  ui_story_70001001_28_dialog_content = "修復器......發生變化了？！",
  ui_story_70001001_29_dialog_content = "<color=#e8d9bb>「升級已完成，醫療系統正常運行中。」</color>",
  ui_story_70001001_30_dialog_content = "<color=#e8d9bb>「當前負荷：1。剩餘空位：1。」</color>",
  ui_story_70001001_31_dialog_content = "<color=#e8d9bb>「請簽名確認。」</color>",
  ui_story_70001001_32_dialog_content = "欸？可是，不需要先測試一下嗎？",
  ui_story_70001001_33_dialog_content = "呃……",
  ui_story_70001001_34_dialog_content = "這個時候......管不了那麼多了。",
  ui_story_70001001_35_dialog_content = "冒險......一試吧。",
  ui_story_70001001_36_dialog_content = "……是！",
  ui_story_70001001_37_dialog_content = "希望醫療系統能有作用......",
  ui_story_70001001_38_dialog_content = "她一定會沒事的。",
  ui_story_70001001_39_dialog_content = "我相信她，也相信臨空者號可以做到。",
  ui_story_70001001_40_dialog_content = "剛才的提示......說不定也是臨空者號感應到了我們遇到的困難，想要提供幫助吧......",
  ui_story_70001001_41_dialog_content = "嗯……",
  ui_story_70001001_42_dialog_content = "醫療系統似乎需要一些時間才能發揮效果。",
  ui_story_70001001_43_dialog_content = "還是先來看看意識模組的修復方法吧。",
  ui_story_70001001_44_dialog_content = "好，我也來幫忙。",
  ui_story_70001001_45_dialog_content = "<color=#e8d9bb>「繼續執行意識模組修復進程。」</color>",
  ui_story_70001001_46_dialog_content = "<color=#e8d9bb>「第一步：請安裝巨像意識標準資料庫插件。」</color>",
  ui_story_70001001_47_dialog_content = "欸……？",
  ui_story_70001001_48_dialog_content = "啥......？",
  ui_story_70001001_49_dialog_content = "PlayerName，你還拿了別的組件回來嗎？",
  ui_story_70001001_50_dialog_content = "沒了啊......只有這一個！",
  ui_story_70001001_51_dialog_content = "臨空者號，那個什麼數據庫插件又是怎麼回事？",
  ui_story_70001001_52_dialog_content = "<color=#e8d9bb>「正在搜尋巨像意識標準資料庫插件相關資訊......搜尋完畢。」</color>",
  ui_story_70001001_53_dialog_content = "<color=#e8d9bb>「回答：巨像意識標準資料庫插件是巨像意識的模板。」</color>",
  ui_story_70001001_54_dialog_content = "<color=#e8d9bb>「目前該模組儲備數量：0。」</color>",
  ui_story_70001001_55_dialog_content = "<color=#e8d9bb>「提示：可以在各巨像整備基地中找到巨像意識標準資料庫插件。」</color>",
  ui_story_70001001_56_dialog_content = "<color=#e8d9bb>「正在搜尋最近的巨像整備基地......搜尋完畢。」</color>",
  ui_story_70001001_57_dialog_content = "<color=#e8d9bb>「目標位於——空之山谷。」</color>",
  ui_story_70001001_58_dialog_content = "空之山谷......？！",
  ui_story_70001001_59_dialog_content = "那裡還有基地嗎？！",
  ui_story_70001001_60_dialog_content = "我怎麼從沒聽說過......",
  ui_story_70001001_61_dialog_content = "<color=#e8d9bb>「提示：如無法安裝插件，意識模組修復器將處於待命狀態。」</color>",
  ui_story_70001001_62_dialog_content = "......進入待命狀態。",
  ui_story_70001001_63_dialog_content = "<color=#e8d9bb>「臨空者號意識模組修復器，進入待命狀態。」</color>",
  ui_story_70001001_64_dialog_content = "等回到空谷，我就去調查那個<color=#FFB400>「巨像整備基地」</color>。",
  ui_story_70001001_65_dialog_content = "就算翻個底朝天，也要找到救臨空者號的方法......",
  ui_story_70001001_66_dialog_content = "不過，當務之急是先把大元帥送回安全線。",
  ui_story_70001001_67_dialog_content = "沒錯……",
  ui_story_70001001_68_dialog_content = "萊因哈特怎麼樣了？",
  ui_story_70001001_69_dialog_content = "醫療系統正在為她進行治療。",
  ui_story_70001001_70_dialog_content = "只是不知道效果如何......",
  ui_story_70001001_71_dialog_content = "但願能有好結果。",
  ui_story_70001001_72_dialog_content = "<color=#e8d9bb>嘀嘀嘀——</color>",
  ui_story_70001001_73_dialog_content = "這是......啟光發來的通訊請求，但是發訊人卻沒有署名？",
  ui_story_70001001_74_dialog_content = "說不定是援軍，先接通看看吧！",
  ui_story_70001001_75_dialog_content = "呼叫薇絲中尉，呼叫空裔PlayerName，呼叫臨空者號。",
  ui_story_70001001_76_dialog_content = "能聽見嗎？",
  ui_story_70001001_77_dialog_content = "該怎麼說來著......",
  ui_story_70001001_78_dialog_content = "喔對了，這裡是臨空者號，請講。",
  ui_story_70001001_79_dialog_content = "我是啟光情報官——艾森。",
  ui_story_70001001_80_dialog_content = "請報告你們的位置。",
  ui_story_70001001_81_dialog_content = "我們在80號地下城東南，預計10分鐘後抵達啟光防線。",
  ui_story_70001001_82_dialog_content = "我有緊急情況需要報告！",
  ui_story_70001001_83_dialog_content = "萊因哈特大元帥在戰鬥中受了重傷，需要治療。",
  ui_story_70001001_84_dialog_content = "果然……",
  ui_story_70001001_85_dialog_content = "不，沒什麼。",
  ui_story_70001001_86_dialog_content = "我會安排一支醫療隊在啟光防線上待命，你們，立刻將大元帥送至啟光防線。",
  ui_story_70001001_87_dialog_content = "知道了！",
  ui_story_70001001_88_dialog_content = "那麼，通訊結束。",
  ui_story_70001001_89_dialog_content = "他們還真是著急。",
  ui_story_70001001_90_dialog_content = "大元帥！",
  ui_story_70001001_91_dialog_content = "萊因哈特......！",
  ui_story_70001001_92_dialog_content = "妳怎麼樣了？",
  ui_story_70001001_93_dialog_content = "不礙事了。雖然身體痛得要死，但離死還遠著呢。",
  ui_story_70001001_94_dialog_content = "接下來只要靜養幾天，就能恢復。",
  ui_story_70001001_95_dialog_content = "空裔的技術還真是奇妙啊。",
  ui_story_70001001_96_dialog_content = "如果能給啟光的地下城裡也來幾套這種治療裝置，應該就能有更多人活下來吧......",
  ui_story_70001001_97_dialog_content = "如果不是臨空者號的提醒，我也不會知道竟然有這種功能。",
  ui_story_70001001_98_dialog_content = "臨空者號嗎？牠的情況怎麼樣了？",
  ui_story_70001001_99_dialog_content = "雖然找到了修復用的模組，但還是有所欠缺。",
  ui_story_70001001_100_dialog_content = "是嗎……",
  ui_story_70001001_101_dialog_content = "希望牠能早日恢復。",
  ui_story_70001001_102_dialog_content = "……",
  ui_story_70001001_103_dialog_content = "萊因哈特，我有一點想不明白。",
  ui_story_70001001_104_dialog_content = "嗯？你不是已經問過「最後一個問題」了嗎？",
  ui_story_70001001_105_dialog_content = "不，不是問題，我只是有一種違和感......",
  ui_story_70001001_106_dialog_content = "明明妳不是一個會拋棄戰友的人。",
  ui_story_70001001_107_dialog_content = "但是為什麼，當初妳會選擇放棄他們？",
  ui_story_70001001_108_dialog_content = "......這是當時的最優決策。",
  ui_story_70001001_109_dialog_content = "我不會允許啟光的士兵白白犧牲。",
  ui_story_70001001_110_dialog_content = "但是當年，妳也並不是「大元帥」，而只是普通的士兵。",
  ui_story_70001001_111_dialog_content = "我敢確定，那一定不是妳的真實想法。",
  ui_story_70001001_112_dialog_content = "確實......有些奇怪。",
  ui_story_70001001_113_dialog_content = "大元帥這一次一個人救了我們，並且一直在竭力試圖喚醒過去的隊友。",
  ui_story_70001001_114_dialog_content = "如果是過去的您，哪怕只有孤身一人，也一定會回去救他們吧......",
  ui_story_70001001_115_dialog_content = "……",
  ui_story_70001001_116_dialog_content = "空裔還真是難對付的傢伙。",
  ui_story_70001001_117_option_content = "謝謝誇獎",
  ui_story_70001001_118_option_content = "我比較注重細節",
  ui_story_70001001_119_dialog_content = "過去的事情，我本來不想再提。但是現在想起來......",
  ui_story_70001001_120_dialog_content = "那時候，我突破重圍，終於回到安全線上。",
  ui_story_70001001_121_dialog_content = "我有緊急情況報告！",
  ui_story_70001001_122_dialog_content = "之前的情報有誤，80號地下城內聚集了大量暗鬼！",
  ui_story_70001001_123_dialog_content = "我突圍了出來，但還有許多人因為暗能和重傷無法行動，被困在裡面。",
  ui_story_70001001_124_dialog_content = "我們需要支援！",
  ui_story_70001001_125_dialog_content = "我知道了，稍後我們會討論的。醫療兵，帶她去治療。",
  ui_story_70001001_126_dialog_content = "請跟我來——",
  ui_story_70001001_127_dialog_content = "你不明白情況的緊急程度！",
  ui_story_70001001_128_dialog_content = "必須現在就派出救援隊伍！",
  ui_story_70001001_129_dialog_content = "不然他們......我的戰友們，都會死啊！",
  ui_story_70001001_130_dialog_content = "安排救援的具體行動需要經過嚴密的商議，這不是妳該管的事情。現在，立刻去接受治療。",
  ui_story_70001001_131_dialog_content = "你是不是根本就不想救他們？",
  ui_story_70001001_132_dialog_content = "不要憑空猜測。",
  ui_story_70001001_133_dialog_content = "好，你們不去救的話，我自己一個人回去。",
  ui_story_70001001_134_dialog_content = "我絕不會放棄他們！",
  ui_story_70001001_135_dialog_content = "妳是啟光的軍人，軍人的天職是服從命令！妳再這樣，會上軍事法庭！",
  ui_story_70001001_136_dialog_content = "我的戰友，他們還在等著我回去。",
  ui_story_70001001_137_dialog_content = "醫療兵！",
  ui_story_70001001_138_dialog_content = "竟然......敢對我......",
  ui_story_70001001_139_dialog_content = "把她送去治療，記得看緊點。",
  ui_story_70001001_140_dialog_content = "是。",
  ui_story_70001001_141_dialog_content = "當我從鎮靜劑的藥效裡恢復、最終醒來時，已經是好幾天後了。",
  ui_story_70001001_142_dialog_content = "我被轉移到了迦南城接受治療，從安全線上撤下來的人告訴我說——",
  ui_story_70001001_143_dialog_content = "委員會最終沒有向80號地下城派出增援。",
  ui_story_70001001_144_dialog_content = "我是唯一一個活著從那裡回來的。",
  ui_story_70001001_145_dialog_content = "……",
  ui_story_70001001_146_dialog_content = "在冷靜下來以後，我開始思考，並逐漸理解了他們的決策。",
  ui_story_70001001_147_dialog_content = "啟光的每一個人都是重要的。",
  ui_story_70001001_148_dialog_content = "不能因為私情就強迫啟光的人民白白犧牲。",
  ui_story_70001001_149_dialog_content = "這是成為大元帥所必須接受的事實，並要為之付出代價。",
  ui_story_70001001_150_dialog_content = "直到身負重傷的德尼耶爾回到啟光。",
  ui_story_70001001_151_dialog_content = "也就是吞羅......？",
  ui_story_70001001_152_dialog_content = "我為了戰友的回歸欣喜不已，但在那件事後，我們之間產生了隔閡。",
  ui_story_70001001_153_dialog_content = "最終，我們分道揚鑣。",
  ui_story_70001001_154_dialog_content = "妳騙了她，明明放棄救援不是妳的決定。",
  ui_story_70001001_155_dialog_content = "我只是覺得，讓她恨我一個人，比讓她恨整個啟光要好點。",
  ui_story_70001001_156_dialog_content = "她很聰明，但報復心也很強。",
  ui_story_70001001_157_dialog_content = "讓她的怒火集中在我身上，啟光的普通人就能免於災難。",
  ui_story_70001001_158_dialog_content = "畢竟想消滅我這樣的「怪物」，可是相當困難的。",
  ui_story_70001001_159_dialog_content = "原來是這麼回事。",
  ui_story_70001001_160_dialog_content = "看來是我之前誤會妳了。",
  ui_story_70001001_161_dialog_content = "誤會了什麼？",
  ui_story_70001001_162_dialog_content = "我以為妳是個冷血的傢伙。",
  ui_story_70001001_163_dialog_content = "PlayerName......那種話可不敢隨便說......",
  ui_story_70001001_164_dialog_content = "哈哈哈——咳咳！",
  ui_story_70001001_165_dialog_content = "咳咳......嗯，沒事，我沒事的。",
  ui_story_70001001_166_dialog_content = "這世界上誤會我的人多了，多一個不多，少一個也不少。",
  ui_story_70001001_167_dialog_content = "只要能守護啟光聯邦的人民，哪怕要承受再多誤會，我也無所謂。",
  ui_story_70001001_168_dialog_content = "嗯……",
  ui_story_70001001_169_dialog_content = "說了這麼久的話，我們馬上就要到啟光的安全線了。",
  ui_story_70001001_170_dialog_content = "是啊，我也該去對付「他們」了。",
  ui_story_70001001_171_dialog_content = "大元帥，您終於回來了！",
  ui_story_70001001_172_dialog_content = "您再不回來，委員會就要把我們送上軍事法庭了喵......",
  ui_story_70001001_173_dialog_content = "聽說您受了傷？醫療班已在待命，馬上可以展開治療！",
  ui_story_70001001_174_dialog_content = "不用緊張，我沒什麼大礙。",
  ui_story_70001001_175_dialog_content = "多虧空裔和他的巨像，我的傷已經緊急處理過一遍了，暫時不會危及生命。",
  ui_story_70001001_176_dialog_content = "這還要感謝臨空者號的及時提醒。",
  ui_story_70001001_177_dialog_content = "那也請務必接受全面的檢查，確保萬無一失！",
  ui_story_70001001_178_dialog_content = "啟光無法承受失去大元帥的風險。",
  ui_story_70001001_179_dialog_content = "失去「大元帥」嗎......",
  ui_story_70001001_180_dialog_content = "唉，所以說流程這東西啊，雖然沒錯，但還真是麻煩......",
  ui_story_70001001_181_dialog_content = "就听妳的，我現在去接受檢查。",
  ui_story_70001001_182_dialog_content = "好的，請來這邊。",
  ui_story_70001001_183_dialog_content = "對了，等一下，我還要再和PlayerName說句話。",
  ui_story_70001001_184_dialog_content = "欸？好，好的。",
  ui_story_70001001_185_dialog_content = "到時候，如果有人向你問起80號地下城發生的事情，你實話實說就好。",
  ui_story_70001001_186_dialog_content = "委員會那些人雖然保守又頑固，但也不會隨便往別人腦袋上安罪名。",
  ui_story_70001001_187_dialog_content = "但是妳那邊......",
  ui_story_70001001_188_dialog_content = "不用擔心，我畢竟還是啟光的大元帥。",
  ui_story_70001001_189_dialog_content = "......好，那妳好好養傷，有機會再見。",
  ui_story_70001001_190_dialog_content = "嗯，有機會再見。",
  ui_story_70001001_191_dialog_content = "我看著萊因哈特的背影逐漸遠去，消失在地下城中",
  ui_story_70001001_192_dialog_content = "一種隱隱的擔憂從心底升起",
  ui_story_70001001_193_dialog_content = "總之，先回去檢查一下臨空者號的狀態吧。",
  ui_story_70001001_194_dialog_content = "然後回空之山谷，繼續尋找修好臨空者號的方法。"
}
